window.SEED = {"version": 1, "sets": [{"id": "seed-bio-ch3", "rev": 1, "title": "Bio Ch 3 — Biomolecules (with pictures)", "folder": "AP Bio", "description": "Campbell Ch 3 concepts 3.1–3.7 with before/after bonding diagrams on the answer side.", "cards": [{"id": "seed-bio-ch3-0", "term": "What are the monomer, bond, and polymer for each of the four classes?", "def": "Carbohydrate: monosaccharide, glycosidic linkage, polysaccharide. Lipid: fatty acid (with glycerol), ester linkage, no true polymer. Protein: amino acid, peptide bond, polypeptide. Nucleic acid: nucleotide, phosphodiester linkage, DNA/RNA."}, {"id": "seed-bio-ch3-1", "term": "Which elements are in each class?", "def": "Carbohydrates CHO (1:2:1). Lipids CHO with very little O. Proteins CHONS. Nucleic acids CHONP."}, {"id": "seed-bio-ch3-2", "term": "Why can carbon build so many different molecules?", "def": "It has 4 valence electrons, so it forms 4 covalent bonds. That lets it make chains, branches, rings and double bonds."}, {"id": "seed-bio-ch3-3", "term": "How many bonds do H, O, N and C form?", "def": "H 1, O 2, N 3, C 4."}, {"id": "seed-bio-ch3-4", "term": "How many water molecules does it take to fully hydrolyze a polymer of 10 monomers?", "def": "9. There are 9 bonds, and each needs one water. The rule is n − 1.", "defImg": "seed/img/bio-dehydration.svg"}, {"id": "seed-bio-ch3-5", "term": "Dehydration synthesis vs hydrolysis: which releases water, which is anabolic?", "def": "Dehydration synthesis builds bonds, releases water, and is anabolic/endergonic. Hydrolysis breaks bonds, uses water, and is catabolic/exergonic. Both need enzymes.", "defImg": "seed/img/bio-dehydration.svg"}, {"id": "seed-bio-ch3-6", "term": "What is the formula of maltose (glucose + glucose)?", "def": "C₁₂H₂₂O₁₁. Twice C₆H₁₂O₆ is C₁₂H₂₄O₁₂; subtract one H₂O.", "defImg": "seed/img/bio-maltose.svg"}, {"id": "seed-bio-ch3-7", "term": "What is the formula of a 3-carbon sugar?", "def": "C₃H₆O₃ (the CH₂O unit × 3)."}, {"id": "seed-bio-ch3-8", "term": "Aldehyde vs ketone sugar?", "def": "Aldehyde: C=O at the END (glucose). Ketone: C=O in the MIDDLE (fructose).", "defImg": "seed/img/bio-linear-sugars.svg"}, {"id": "seed-bio-ch3-9", "term": "Why can’t humans digest cellulose but can digest starch?", "def": "Starch has α links; cellulose has β links (every other glucose flipped). Our enzymes only fit α links.", "defImg": "seed/img/bio-polysaccharides.svg"}, {"id": "seed-bio-ch3-10", "term": "Why is glycogen so branched?", "def": "More branches = more ends, so many glucoses can be broken off at once for fast energy.", "defImg": "seed/img/bio-polysaccharides.svg"}, {"id": "seed-bio-ch3-11", "term": "Why does a cow need a “gut culture” after antibiotics?", "def": "The antibiotics killed the microbes that digest cellulose for it. The culture puts them back."}, {"id": "seed-bio-ch3-12", "term": "Compare a fat and a phospholipid.", "def": "Fat: glycerol + 3 fatty acids. Phospholipid: glycerol + 2 fatty acids + a phosphate head, so it has a hydrophilic head and hydrophobic tails.", "defImg": "seed/img/bio-phospholipid.svg"}, {"id": "seed-bio-ch3-13", "term": "Saturated vs unsaturated fat?", "def": "Saturated: no C=C, straight, packs tight, solid (butter). Unsaturated: cis C=C makes kinks, can’t pack, liquid (oil).", "defImg": "seed/img/bio-fatty-acids.svg"}, {"id": "seed-bio-ch3-14", "term": "What is a trans fat?", "def": "An unsaturated fat with trans double bonds, made when oils are hydrogenated. Linked to heart disease."}, {"id": "seed-bio-ch3-15", "term": "Why are sex hormones lipids?", "def": "They are steroids: four fused hydrophobic carbon rings.", "defImg": "seed/img/bio-steroid.svg"}, {"id": "seed-bio-ch3-16", "term": "Which lipid has the most energy per gram?", "def": "Lipids (fats) at 9 Cal/g, more than twice carbs or proteins (4 Cal/g)."}, {"id": "seed-bio-ch3-17", "term": "What does an oil droplet in a seed look like with a membrane around it?", "def": "A single layer (monolayer) of phospholipids: tails point into the oil, heads face the watery cytoplasm."}, {"id": "seed-bio-ch3-18", "term": "Draw the general amino acid.", "def": "Central α carbon with H, −NH₂ (amino), −COOH (carboxyl), and R (side chain).", "defImg": "seed/img/bio-amino-acid.svg"}, {"id": "seed-bio-ch3-19", "term": "What makes each of the 20 amino acids different?", "def": "Only the R group (side chain)."}, {"id": "seed-bio-ch3-20", "term": "What holds secondary structure together? Tertiary?", "def": "Secondary: H-bonds between BACKBONE atoms (α helix, β sheet). Tertiary: interactions between R GROUPS (hydrophobic, H-bonds, ionic, disulfide bridges).", "defImg": "seed/img/bio-protein-levels.svg"}, {"id": "seed-bio-ch3-21", "term": "Where would a region rich in valine, leucine and isoleucine end up?", "def": "In the protein’s interior. Those R groups are nonpolar, so they hide from water."}, {"id": "seed-bio-ch3-22", "term": "What is quaternary structure?", "def": "Two or more polypeptide chains together. Hemoglobin has 4; collagen has 3.", "defImg": "seed/img/bio-protein-levels.svg"}, {"id": "seed-bio-ch3-23", "term": "What causes sickle-cell disease?", "def": "One amino acid swap in hemoglobin: valine (nonpolar) replaces glutamic acid (charged). The proteins clump, and red cells sickle."}, {"id": "seed-bio-ch3-24", "term": "Why does a denatured protein stop working?", "def": "Heat, pH or salt breaks the weak bonds holding its shape. Function depends on shape, so it can’t bind its target."}, {"id": "seed-bio-ch3-25", "term": "What are the 3 parts of a nucleotide?", "def": "A phosphate, a 5-carbon sugar, and a nitrogenous base.", "defImg": "seed/img/bio-nucleotide.svg"}, {"id": "seed-bio-ch3-26", "term": "Purines vs pyrimidines?", "def": "Purines = 2 rings: A, G. Pyrimidines = 1 ring: C, T, U.", "defImg": "seed/img/bio-bases.svg"}, {"id": "seed-bio-ch3-27", "term": "DNA vs RNA: sugar, bases, strands?", "def": "DNA: deoxyribose, A T G C, double helix. RNA: ribose, A U G C, single strand.", "defImg": "seed/img/bio-nucleotide.svg"}, {"id": "seed-bio-ch3-28", "term": "Write the complement of 5′-TAGGCCT-3′.", "def": "3′-ATCCGGA-5′, which is written 5′-AGGCCTA-3′.", "defImg": "seed/img/bio-dna.svg"}, {"id": "seed-bio-ch3-29", "term": "What does “antiparallel” mean?", "def": "The two DNA strands run in opposite directions: one 5′→3′, the other 3′→5′.", "defImg": "seed/img/bio-dna.svg"}, {"id": "seed-bio-ch3-30", "term": "Order of gene expression?", "def": "DNA → mRNA (in the nucleus) → ribosome reads it → protein.", "defImg": "seed/img/bio-gene-expression.svg"}, {"id": "seed-bio-ch3-31", "term": "Which functional group is the only nonpolar one?", "def": "Methyl (−CH₃): only C and H.", "defImg": "seed/img/group-methyl.svg"}, {"id": "seed-bio-ch3-32", "term": "Which group is the acid and which is the base?", "def": "Carboxyl (−COOH) is the acid: gives away H⁺. Amino (−NH₂) is the base: picks up H⁺."}, {"id": "seed-bio-ch3-33", "term": "What forms a disulfide bridge?", "def": "Two sulfhydryl (−SH) groups on cysteines bond S–S.", "defImg": "seed/img/group-sulfhydryl.svg"}, {"id": "seed-bio-ch3-34", "term": "How does ATP release energy?", "def": "Water splits off its last phosphate, making ADP + Pᵢ + energy.", "defImg": "seed/img/bio-atp.svg"}, {"id": "seed-bio-ch3-35", "term": "How do two sugars bond? (draw before and after)", "def": "Dehydration synthesis: the −OH on C1 of one sugar and an −H from C4 of the other leave as water. The remaining O bridges the rings: a 1–4 glycosidic linkage.", "defImg": "seed/img/bio-maltose.svg"}, {"id": "seed-bio-ch3-36", "term": "How is a fat (triglyceride) built?", "def": "One glycerol + three fatty acids. Each fatty acid joins by a dehydration reaction, so 3 H₂O leave and 3 ester linkages form.", "defImg": "seed/img/bio-triglyceride.svg"}, {"id": "seed-bio-ch3-37", "term": "How do two amino acids bond?", "def": "The −OH of one carboxyl and an −H of the next amino group leave as water. C bonds to N: a peptide bond. Chains have an N-terminus and a C-terminus.", "defImg": "seed/img/bio-dipeptide.svg"}, {"id": "seed-bio-ch3-38", "term": "How do two nucleotides bond?", "def": "The phosphate of one nucleotide bonds to the 3′ carbon of the sugar before it (water leaves): a phosphodiester linkage. The chain runs 5′ → 3′.", "defImg": "seed/img/bio-phosphodiester.svg"}, {"id": "seed-bio-ch3-39", "term": "Cis vs trans isomers", "def": "Cis: groups on the SAME side of a C=C double bond. Trans: groups on OPPOSITE sides. Double bonds can’t rotate, so they are different molecules.", "defImg": "seed/img/bio-cis-trans.svg"}, {"id": "seed-bio-ch3-40", "term": "What does a glucose ring look like?", "def": "A 6-sided ring with the O inside the ring, an −OH on almost every carbon, and CH₂OH (carbon 6) sticking up. C₆H₁₂O₆.", "defImg": "seed/img/bio-glucose-ring.svg"}, {"id": "seed-bio-ch3-41", "term": "Hydroxyl group", "def": "−OH · Polar · Alcohols. Found in: Every sugar, glycerol. Makes molecules dissolve in water.", "defImg": "seed/img/group-hydroxyl.svg"}, {"id": "seed-bio-ch3-42", "term": "Carbonyl group", "def": "C=O · Polar · Aldehyde (end) or ketone (middle). Found in: Straight-chain sugars, peptide bonds. End = aldehyde (glucose); middle = ketone (fructose).", "defImg": "seed/img/group-carbonyl.svg"}, {"id": "seed-bio-ch3-43", "term": "Carboxyl group", "def": "−COOH · Polar · ACID · Carboxylic acid. Found in: Every amino acid and fatty acid. Gives away H⁺ → −COO⁻.", "defImg": "seed/img/group-carboxyl.svg"}, {"id": "seed-bio-ch3-44", "term": "Amino group", "def": "−NH₂ · Polar · BASE · Amine. Found in: Every amino acid, DNA/RNA bases. Picks up H⁺ → −NH₃⁺.", "defImg": "seed/img/group-amino.svg"}, {"id": "seed-bio-ch3-45", "term": "Sulfhydryl group", "def": "−SH · Slightly polar · Thiol. Found in: Cysteine. Two −SH → S–S disulfide bridge.", "defImg": "seed/img/group-sulfhydryl.svg"}, {"id": "seed-bio-ch3-46", "term": "Phosphate group", "def": "−OPO₃²⁻ · Polar · negative · Organic phosphate. Found in: ATP, DNA/RNA backbone, phospholipid heads. Carries energy in ATP.", "defImg": "seed/img/group-phosphate.svg"}, {"id": "seed-bio-ch3-47", "term": "Methyl group", "def": "−CH₃ · NONPOLAR (only one) · Methylated compound. Found in: Fatty acid tails, thymine. Not reactive, acts as a tag.", "defImg": "seed/img/group-methyl.svg"}]}, {"id": "seed-bio-identify", "rev": 1, "title": "Bio Ch 3 — Identify the Molecule", "folder": "AP Bio", "description": "Picture on the front, name on the back. Ask: Is there N? Is the N in a ring? How many O?", "cards": [{"id": "seed-bio-identify-0", "term": "", "def": "Monosaccharide (carbohydrate)", "termImg": "seed/img/identify-1.svg", "note": "No N. Oxygen INSIDE the ring and an −OH on almost every carbon."}, {"id": "seed-bio-identify-1", "term": "", "def": "Amino acid (protein)", "termImg": "seed/img/identify-2.svg", "note": "Has N, but the N is in an −NH₂ (not a ring), next to a carbon that also has −COOH."}, {"id": "seed-bio-identify-2", "term": "", "def": "Saturated fatty acid (lipid)", "termImg": "seed/img/identify-3.svg", "note": "No N, only 2 O (one −COOH head), long straight C–H tail, no double bonds."}, {"id": "seed-bio-identify-3", "term": "", "def": "Unsaturated fatty acid (lipid)", "termImg": "seed/img/identify-4.svg", "note": "Same head and tail, but a C=C double bond puts a kink in it."}, {"id": "seed-bio-identify-4", "term": "", "def": "Purine base (nucleic acid)", "termImg": "seed/img/identify-5.svg", "note": "Nitrogen INSIDE the rings, and two rings fused together."}, {"id": "seed-bio-identify-5", "term": "", "def": "Pyrimidine base (nucleic acid)", "termImg": "seed/img/identify-6.svg", "note": "Nitrogen inside a single ring."}, {"id": "seed-bio-identify-6", "term": "", "def": "Steroid (lipid)", "termImg": "seed/img/identify-7.svg", "note": "Four fused rings, almost no oxygen, no nitrogen."}, {"id": "seed-bio-identify-7", "term": "", "def": "Nucleotide (nucleic acid)", "termImg": "seed/img/identify-8.svg", "note": "Phosphate + 5-sided sugar ring + a ring with N atoms, all connected."}, {"id": "seed-bio-identify-8", "term": "", "def": "Dipeptide (protein)", "termImg": "seed/img/identify-9.svg", "note": "Repeating N–C–C backbone with a C(=O)–N peptide bond in the middle."}, {"id": "seed-bio-identify-9", "term": "", "def": "Disaccharide (carbohydrate)", "termImg": "seed/img/identify-10.svg", "note": "Two sugar rings joined through one bridging O (glycosidic linkage)."}, {"id": "seed-bio-identify-10", "term": "", "def": "Triglyceride (lipid)", "termImg": "seed/img/identify-11.svg", "note": "Glycerol backbone with THREE fatty acid tails attached by ester bonds."}, {"id": "seed-bio-identify-11", "term": "", "def": "Phospholipid (lipid)", "termImg": "seed/img/identify-12.svg", "note": "Phosphate head + only TWO tails. The P doesn’t make it a nucleic acid; the tails make it a lipid."}, {"id": "seed-bio-identify-12", "term": "", "def": "Straight-chain monosaccharide (carbohydrate)", "termImg": "seed/img/identify-13.svg", "note": "C=O at the END of the chain and −OH on every other carbon. Roughly 1 C : 2 H : 1 O."}], "answerWith": "def"}, {"id": "seed-pid", "rev": 1, "title": "Picture ID — Which Macromolecule Is It?", "folder": "AP Bio", "description": "62 structure drawings: sugars, fats, amino acids, peptides, bases, nucleotides and functional groups. Use the Picture ID test: pick the class, then the exact kind.", "answerWith": "def", "cards": [{"id": "seed-pid-0", "term": "", "termImg": "seed/img/pid-1.svg", "def": "Monosaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Monosaccharide", "detail": "α-glucose (ring)", "note": "This one: α-glucose (ring). No N. One 6-sided ring with the O IN the ring and an −OH on almost every carbon."}, {"id": "seed-pid-1", "term": "", "termImg": "seed/img/pid-2.svg", "def": "Monosaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Monosaccharide", "detail": "β-glucose (ring)", "note": "This one: β-glucose (ring). No N. Same ring as α-glucose, but the C1 −OH points UP (β). Still one ring = monosaccharide."}, {"id": "seed-pid-2", "term": "", "termImg": "seed/img/pid-3.svg", "def": "Monosaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Monosaccharide", "detail": "galactose (ring)", "note": "This one: galactose (ring). No N. One ring, O inside it, OH everywhere. (Galactose: the C4 −OH points up.)"}, {"id": "seed-pid-3", "term": "", "termImg": "seed/img/pid-4.svg", "def": "Monosaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Monosaccharide", "detail": "glucose, drawn mirrored", "note": "This one: glucose, drawn mirrored. No N. Flipped left-to-right, but still one ring with the O inside and OH groups all around."}, {"id": "seed-pid-4", "term": "", "termImg": "seed/img/pid-5.svg", "def": "Monosaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Monosaccharide", "detail": "fructose (5-sided ring)", "note": "This one: fructose (5-sided ring). No N. A 5-sided ring with O inside, plus −OH and −CH₂OH groups. Fructose forms a 5-ring."}, {"id": "seed-pid-5", "term": "", "termImg": "seed/img/pid-6.svg", "def": "Monosaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Monosaccharide", "detail": "ribose (the sugar in RNA)", "note": "This one: ribose (the sugar in RNA). No N. 5-sided ring, O inside, OH groups. On its own (no base, no phosphate) it’s just a sugar."}, {"id": "seed-pid-6", "term": "", "termImg": "seed/img/pid-7.svg", "def": "Monosaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Monosaccharide", "detail": "deoxyribose (the sugar in DNA)", "note": "This one: deoxyribose (the sugar in DNA). No N. 5-ring sugar with one fewer O: carbon 2′ has only H. No base attached, so it’s still a carbohydrate."}, {"id": "seed-pid-7", "term": "", "termImg": "seed/img/pid-8.svg", "def": "Monosaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Monosaccharide", "detail": "straight-chain glucose (aldehyde)", "note": "This one: straight-chain glucose (aldehyde). No N. A straight chain with C=O at the END (aldehyde) and −OH on every other carbon. About 1 C : 2 H : 1 O."}, {"id": "seed-pid-8", "term": "", "termImg": "seed/img/pid-9.svg", "def": "Monosaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Monosaccharide", "detail": "straight-chain fructose (ketone)", "note": "This one: straight-chain fructose (ketone). No N. C=O in the MIDDLE (ketone) with −OH on the other carbons. Lots of O, so carbohydrate."}, {"id": "seed-pid-9", "term": "", "termImg": "seed/img/pid-10.svg", "def": "Monosaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Monosaccharide", "detail": "glyceraldehyde (3-carbon sugar)", "note": "This one: glyceraldehyde (3-carbon sugar). No N. Short chain, but still C=O at the end + OH on each carbon. C₃H₆O₃ fits 1 : 2 : 1."}, {"id": "seed-pid-10", "term": "", "termImg": "seed/img/pid-11.svg", "def": "Disaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Disaccharide", "detail": "maltose (glucose + glucose)", "note": "This one: maltose (glucose + glucose). No N. TWO sugar rings joined by one bridging O (a glycosidic linkage)."}, {"id": "seed-pid-11", "term": "", "termImg": "seed/img/pid-12.svg", "def": "Disaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Disaccharide", "detail": "sucrose (glucose + fructose)", "note": "This one: sucrose (glucose + fructose). No N. A 6-ring and a 5-ring joined through one O. Two sugar units = disaccharide (table sugar)."}, {"id": "seed-pid-12", "term": "", "termImg": "seed/img/pid-13.svg", "def": "Polysaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Polysaccharide", "detail": "starch / cellulose chain", "note": "This one: starch / cellulose chain. No N. Many sugar rings in a row, each joined by an O, and the “…” means the chain keeps going."}, {"id": "seed-pid-13", "term": "", "termImg": "seed/img/pid-14.svg", "def": "Polysaccharide (carbohydrate)", "cls": "Carbohydrate", "name": "Polysaccharide", "detail": "glycogen / amylopectin (branched)", "note": "This one: glycogen / amylopectin (branched). No N. A chain of sugar rings with a BRANCH coming off it. Branched = energy storage."}, {"id": "seed-pid-14", "term": "", "termImg": "seed/img/pid-15.svg", "def": "Saturated fatty acid (lipid)", "cls": "Lipid", "name": "Saturated fatty acid", "detail": "skeletal drawing", "note": "This one: skeletal drawing. No N. Only 2 O (one −COOH head) and a long straight zigzag of carbons with NO double bonds."}, {"id": "seed-pid-15", "term": "", "termImg": "seed/img/pid-16.svg", "def": "Saturated fatty acid (lipid)", "cls": "Lipid", "name": "Saturated fatty acid", "detail": "written-out formula", "note": "This one: written-out formula. No N. HO−C(=O)− head and a long chain of CH₂ ending in CH₃. Almost no oxygen, no C=C."}, {"id": "seed-pid-16", "term": "", "termImg": "seed/img/pid-17.svg", "def": "Saturated fatty acid (lipid)", "cls": "Lipid", "name": "Saturated fatty acid", "detail": "a shorter one", "note": "This one: a shorter one. No N. Length doesn’t matter: −COOH head + straight C–H tail with no double bonds = saturated fatty acid."}, {"id": "seed-pid-17", "term": "", "termImg": "seed/img/pid-18.svg", "def": "Unsaturated fatty acid (lipid)", "cls": "Lipid", "name": "Unsaturated fatty acid", "detail": "one cis double bond", "note": "This one: one cis double bond. No N. Same −COOH head and C–H tail, but a C=C double bond puts a KINK in the tail."}, {"id": "seed-pid-18", "term": "", "termImg": "seed/img/pid-19.svg", "def": "Unsaturated fatty acid (lipid)", "cls": "Lipid", "name": "Unsaturated fatty acid", "detail": "written-out, with CH=CH", "note": "This one: written-out, with CH=CH. No N. Look for CH=CH in the middle of the chain. That C=C makes it unsaturated."}, {"id": "seed-pid-19", "term": "", "termImg": "seed/img/pid-20.svg", "def": "Unsaturated fatty acid (lipid)", "cls": "Lipid", "name": "Unsaturated fatty acid", "detail": "polyunsaturated (two kinks)", "note": "This one: polyunsaturated (two kinks). No N. More than one C=C = polyunsaturated. Still a fatty acid: one −COOH head, one tail."}, {"id": "seed-pid-20", "term": "", "termImg": "seed/img/pid-21.svg", "def": "Triglyceride (lipid)", "cls": "Lipid", "name": "Triglyceride", "detail": "fat (3 tails)", "note": "This one: fat (3 tails). No N. A 3-carbon glycerol backbone with THREE fatty acid tails attached through O (ester bonds)."}, {"id": "seed-pid-21", "term": "", "termImg": "seed/img/pid-22.svg", "def": "Phospholipid (lipid)", "cls": "Lipid", "name": "Phospholipid", "detail": "full structure", "note": "This one: full structure. Has P and one N⁺, but look at the shape: glycerol + only TWO long tails + a phosphate head. The tails make it a lipid."}, {"id": "seed-pid-22", "term": "", "termImg": "seed/img/pid-23.svg", "def": "Phospholipid (lipid)", "cls": "Lipid", "name": "Phospholipid", "detail": "symbol", "note": "This one: symbol. A round head with a phosphate (P) and TWO tails hanging down. That’s the cell-membrane lipid."}, {"id": "seed-pid-23", "term": "", "termImg": "seed/img/pid-24.svg", "def": "Steroid (lipid)", "cls": "Lipid", "name": "Steroid", "detail": "cholesterol", "note": "This one: cholesterol. No N. FOUR fused rings (three 6-sided + one 5-sided) and almost no oxygen. No tails from glycerol."}, {"id": "seed-pid-24", "term": "", "termImg": "seed/img/pid-25.svg", "def": "Steroid (lipid)", "cls": "Lipid", "name": "Steroid", "detail": "a sex hormone (testosterone-like)", "note": "This one: a sex hormone (testosterone-like). No N. The same 4 fused rings with =O and −OH attached. Different groups, still a steroid."}, {"id": "seed-pid-25", "term": "", "termImg": "seed/img/pid-26.svg", "def": "Amino acid (protein)", "cls": "Protein", "name": "Amino acid", "detail": "general structure (R group)", "note": "This one: general structure (R group). Has N, but it’s in an −NH₂ (not a ring) next to a carbon with −COOH. Central C with H, −NH₂, −COOH and R = an amino acid."}, {"id": "seed-pid-26", "term": "", "termImg": "seed/img/pid-27.svg", "def": "Amino acid (protein)", "cls": "Protein", "name": "Amino acid", "detail": "glycine (R = H)", "note": "This one: glycine (R = H). Has N, but it’s in an −NH₂ (not a ring) next to a carbon with −COOH. The R group is just H, the simplest amino acid."}, {"id": "seed-pid-27", "term": "", "termImg": "seed/img/pid-28.svg", "def": "Amino acid (protein)", "cls": "Protein", "name": "Amino acid", "detail": "alanine (R = CH₃)", "note": "This one: alanine (R = CH₃). Has N, but it’s in an −NH₂ (not a ring) next to a carbon with −COOH. A methyl R group makes it nonpolar."}, {"id": "seed-pid-28", "term": "", "termImg": "seed/img/pid-29.svg", "def": "Amino acid (protein)", "cls": "Protein", "name": "Amino acid", "detail": "serine (R = CH₂OH)", "note": "This one: serine (R = CH₂OH). Has N, but it’s in an −NH₂ (not a ring) next to a carbon with −COOH. The −OH in the R group makes it polar. Don’t confuse it with a sugar: there’s an N."}, {"id": "seed-pid-29", "term": "", "termImg": "seed/img/pid-30.svg", "def": "Amino acid (protein)", "cls": "Protein", "name": "Amino acid", "detail": "cysteine (R = CH₂SH)", "note": "This one: cysteine (R = CH₂SH). Has N, but it’s in an −NH₂ (not a ring) next to a carbon with −COOH. The S in the side chain (sulfhydryl) can form disulfide bridges."}, {"id": "seed-pid-30", "term": "", "termImg": "seed/img/pid-31.svg", "def": "Amino acid (protein)", "cls": "Protein", "name": "Amino acid", "detail": "aspartic acid (acidic R group)", "note": "This one: aspartic acid (acidic R group). Has N, but it’s in an −NH₂ (not a ring) next to a carbon with −COOH. An extra −COOH in the side chain makes it acidic. Still the amino-acid backbone."}, {"id": "seed-pid-31", "term": "", "termImg": "seed/img/pid-32.svg", "def": "Amino acid (protein)", "cls": "Protein", "name": "Amino acid", "detail": "lysine (basic R group)", "note": "This one: lysine (basic R group). Has N, but it’s in an −NH₂ (not a ring) next to a carbon with −COOH. A long side chain ending in another −NH₂ (basic). Look at the top: H₂N–C–COOH."}, {"id": "seed-pid-32", "term": "", "termImg": "seed/img/pid-33.svg", "def": "Amino acid (protein)", "cls": "Protein", "name": "Amino acid", "detail": "phenylalanine (ring in the R group)", "note": "This one: phenylalanine (ring in the R group). Has a ring, but the ring has NO N in it. The N is in −NH₂ next to −COOH, so it’s an amino acid, not a nucleic acid."}, {"id": "seed-pid-33", "term": "", "termImg": "seed/img/pid-34.svg", "def": "Amino acid (protein)", "cls": "Protein", "name": "Amino acid", "detail": "valine, drawn ionized (H₃N⁺ … COO⁻)", "note": "This one: valine, drawn ionized (H₃N⁺ … COO⁻). H₃N⁺ and COO⁻ are just the charged forms of −NH₂ and −COOH (how they look at cell pH). Same amino acid pattern."}, {"id": "seed-pid-34", "term": "", "termImg": "seed/img/pid-35.svg", "def": "Dipeptide (protein)", "cls": "Protein", "name": "Dipeptide", "detail": "two amino acids", "note": "This one: two amino acids. Has N (not in a ring). Two amino-acid units joined by ONE peptide bond: C(=O)–N(H)."}, {"id": "seed-pid-35", "term": "", "termImg": "seed/img/pid-36.svg", "def": "Polypeptide (protein)", "cls": "Protein", "name": "Polypeptide", "detail": "chain of amino acids", "note": "This one: chain of amino acids. The N–C–C backbone repeats over and over with R groups hanging off, and it keeps going (…)."}, {"id": "seed-pid-36", "term": "", "termImg": "seed/img/pid-37.svg", "def": "Polypeptide (protein)", "cls": "Protein", "name": "Polypeptide", "detail": "tripeptide (3 units)", "note": "This one: tripeptide (3 units). Three amino acids joined by two peptide bonds. More than two units = polypeptide chain."}, {"id": "seed-pid-37", "term": "", "termImg": "seed/img/pid-38.svg", "def": "Purine base (nucleic acid)", "cls": "Nucleic acid", "name": "Purine base", "detail": "adenine (A)", "note": "This one: adenine (A). Has N INSIDE a ring. Two fused rings (6 + 5) = purine. The −NH₂ on top makes it adenine."}, {"id": "seed-pid-38", "term": "", "termImg": "seed/img/pid-39.svg", "def": "Purine base (nucleic acid)", "cls": "Nucleic acid", "name": "Purine base", "detail": "guanine (G)", "note": "This one: guanine (G). Has N INSIDE a ring. Two fused rings = purine. =O on top and −NH₂ on the side = guanine."}, {"id": "seed-pid-39", "term": "", "termImg": "seed/img/pid-40.svg", "def": "Purine base (nucleic acid)", "cls": "Nucleic acid", "name": "Purine base", "detail": "purine skeleton", "note": "This one: purine skeleton. Has N INSIDE a ring. A 6-ring fused to a 5-ring, with N atoms in both = purine (A or G)."}, {"id": "seed-pid-40", "term": "", "termImg": "seed/img/pid-41.svg", "def": "Pyrimidine base (nucleic acid)", "cls": "Nucleic acid", "name": "Pyrimidine base", "detail": "cytosine (C)", "note": "This one: cytosine (C). Has N INSIDE a ring. ONE ring = pyrimidine. =O at the bottom and −NH₂ on the side = cytosine."}, {"id": "seed-pid-41", "term": "", "termImg": "seed/img/pid-42.svg", "def": "Pyrimidine base (nucleic acid)", "cls": "Nucleic acid", "name": "Pyrimidine base", "detail": "thymine (T, DNA only)", "note": "This one: thymine (T, DNA only). Has N INSIDE a ring. One ring, two =O, and a −CH₃ = thymine (only in DNA)."}, {"id": "seed-pid-42", "term": "", "termImg": "seed/img/pid-43.svg", "def": "Pyrimidine base (nucleic acid)", "cls": "Nucleic acid", "name": "Pyrimidine base", "detail": "uracil (U, RNA only)", "note": "This one: uracil (U, RNA only). Has N INSIDE a ring. One ring with two =O and no −CH₃ = uracil (only in RNA)."}, {"id": "seed-pid-43", "term": "", "termImg": "seed/img/pid-44.svg", "def": "Pyrimidine base (nucleic acid)", "cls": "Nucleic acid", "name": "Pyrimidine base", "detail": "pyrimidine skeleton", "note": "This one: pyrimidine skeleton. Has N INSIDE a ring. A single 6-ring with two N in it = pyrimidine (C, T or U)."}, {"id": "seed-pid-44", "term": "", "termImg": "seed/img/pid-45.svg", "def": "Nucleoside (nucleic acid)", "cls": "Nucleic acid", "name": "Nucleoside", "detail": "cytidine (base + sugar, no phosphate)", "note": "This one: cytidine (base + sugar, no phosphate). Has N INSIDE a ring. A base attached to a 5-ring sugar, but NO phosphate. Base + sugar = nucleoSIDE."}, {"id": "seed-pid-45", "term": "", "termImg": "seed/img/pid-46.svg", "def": "Nucleoside (nucleic acid)", "cls": "Nucleic acid", "name": "Nucleoside", "detail": "adenosine (base + sugar, no phosphate)", "note": "This one: adenosine (base + sugar, no phosphate). Has N INSIDE a ring. Purine base + ribose sugar, no phosphate = nucleoside."}, {"id": "seed-pid-46", "term": "", "termImg": "seed/img/pid-47.svg", "def": "Nucleotide (nucleic acid)", "cls": "Nucleic acid", "name": "Nucleotide", "detail": "a pyrimidine nucleotide", "note": "This one: a pyrimidine nucleotide. Has N INSIDE a ring. Phosphate + 5-ring sugar + nitrogenous base, all connected = nucleotide (the monomer)."}, {"id": "seed-pid-47", "term": "", "termImg": "seed/img/pid-48.svg", "def": "Nucleotide (nucleic acid)", "cls": "Nucleic acid", "name": "Nucleotide", "detail": "a DNA nucleotide (2′ H)", "note": "This one: a DNA nucleotide (2′ H). Has N INSIDE a ring. Phosphate + sugar + base. The 2′ carbon has only H, so this is a DNA nucleotide (deoxyribose)."}, {"id": "seed-pid-48", "term": "", "termImg": "seed/img/pid-49.svg", "def": "Nucleotide (nucleic acid)", "cls": "Nucleic acid", "name": "Nucleotide", "detail": "ATP (adenine + ribose + 3 phosphates)", "note": "This one: ATP (adenine + ribose + 3 phosphates). Has N INSIDE a ring. A nucleotide with THREE phosphates in a row. ATP is a nucleotide, the cell’s energy molecule."}, {"id": "seed-pid-49", "term": "", "termImg": "seed/img/pid-50.svg", "def": "Nucleotide (nucleic acid)", "cls": "Nucleic acid", "name": "Nucleotide", "detail": "simple symbol version", "note": "This one: simple symbol version. Has N INSIDE a ring. Phosphate + 5-ring sugar + a ring with N atoms = nucleotide."}, {"id": "seed-pid-50", "term": "", "termImg": "seed/img/pid-51.svg", "def": "Polynucleotide (nucleic acid)", "cls": "Nucleic acid", "name": "Polynucleotide", "detail": "two nucleotides linked (DNA/RNA strand)", "note": "This one: two nucleotides linked (DNA/RNA strand). Has N INSIDE a ring. Nucleotides chained sugar–phosphate–sugar (phosphodiester bonds). A chain of nucleotides = a nucleic acid strand."}, {"id": "seed-pid-51", "term": "", "termImg": "seed/img/pid-52.svg", "def": "Hydroxyl group", "cls": "Functional group", "name": "Hydroxyl group", "detail": "−OH", "note": "This one: −OH. Found in every sugar (carbohydrates), glycerol (lipids), and serine/threonine (proteins)."}, {"id": "seed-pid-52", "term": "", "termImg": "seed/img/pid-53.svg", "def": "Carbonyl group", "cls": "Functional group", "name": "Carbonyl group", "detail": "C=O", "note": "This one: C=O. Found in straight-chain sugars (aldehyde or ketone) and in every peptide bond."}, {"id": "seed-pid-53", "term": "", "termImg": "seed/img/pid-54.svg", "def": "Carboxyl group", "cls": "Functional group", "name": "Carboxyl group", "detail": "−COOH", "note": "This one: −COOH. Found on every amino acid (protein) and the head of every fatty acid (lipid). It’s the acid."}, {"id": "seed-pid-54", "term": "", "termImg": "seed/img/pid-55.svg", "def": "Amino group", "cls": "Functional group", "name": "Amino group", "detail": "−NH₂", "note": "This one: −NH₂. Found on every amino acid (protein) and in the nitrogenous bases (nucleic acids). It’s the base."}, {"id": "seed-pid-55", "term": "", "termImg": "seed/img/pid-56.svg", "def": "Sulfhydryl group", "cls": "Functional group", "name": "Sulfhydryl group", "detail": "−SH", "note": "This one: −SH. Found in cysteine (protein). Two of them form a disulfide bridge. The S in CHONS."}, {"id": "seed-pid-56", "term": "", "termImg": "seed/img/pid-57.svg", "def": "Phosphate group", "cls": "Functional group", "name": "Phosphate group", "detail": "−OPO₃²⁻", "note": "This one: −OPO₃²⁻. Found in the DNA/RNA backbone and ATP (nucleic acids) and phospholipid heads (lipids). The P in CHONP."}, {"id": "seed-pid-57", "term": "", "termImg": "seed/img/pid-58.svg", "def": "Methyl group", "cls": "Functional group", "name": "Methyl group", "detail": "−CH₃", "note": "This one: −CH₃. Found in fatty acid tails, steroids, and thymine. The only NONPOLAR group."}, {"id": "seed-pid-58", "term": "", "termImg": "seed/img/pid-59.svg", "def": "Carbonyl group", "cls": "Functional group", "name": "Carbonyl group", "detail": "aldehyde form (C=O at the end, with H)", "note": "This one: aldehyde form (C=O at the end, with H). C double-bonded to O. With an H on the carbon it’s at the END of a chain = aldehyde. Found in straight-chain sugars (aldehyde or ketone) and in every peptide bond."}, {"id": "seed-pid-59", "term": "", "termImg": "seed/img/pid-60.svg", "def": "Carboxyl group", "cls": "Functional group", "name": "Carboxyl group", "detail": "ionized form (−COO⁻)", "note": "This one: ionized form (−COO⁻). A carboxyl that has given away its H⁺ (that’s why it’s an acid). Found on every amino acid (protein) and the head of every fatty acid (lipid). It’s the acid."}, {"id": "seed-pid-60", "term": "", "termImg": "seed/img/pid-61.svg", "def": "Amino group", "cls": "Functional group", "name": "Amino group", "detail": "ionized form (−NH₃⁺)", "note": "This one: ionized form (−NH₃⁺). An amino group that picked up an H⁺ (that’s why it’s a base). Found on every amino acid (protein) and in the nitrogenous bases (nucleic acids). It’s the base."}, {"id": "seed-pid-61", "term": "", "termImg": "seed/img/pid-62.svg", "def": "Sulfhydryl group", "cls": "Functional group", "name": "Sulfhydryl group", "detail": "two joined: a disulfide bridge (S–S)", "note": "This one: two joined: a disulfide bridge (S–S). Two −SH groups (from two cysteines) bonded S–S. Holds protein tertiary structure together."}]}, {"id": "seed-mcq-ap", "rev": 1, "kind": "mcq", "title": "AP-Style MCQ Practice: Water + Biochem (with figures)", "folder": "AP Bio", "description": "AP-style questions with diagrams and data tables, like your practice test: water, elements, reactions and all four macromolecules.", "cards": [], "questions": [{"id": "seed-mcq-ap-q0", "stem": "The diagram shows two water molecules. Which best describes the attraction shown by the dashed line?", "img": "seed/img/mcq-water.svg", "choices": ["A covalent bond in which the two oxygen atoms share a pair of electrons", "An ionic bond formed when one molecule transfers an electron to the other", "A hydrogen bond between the partially positive H of one molecule and the partially negative O of the other", "A nonpolar attraction between the hydrogen atoms of the two molecules"], "answer": 2, "why": "Water is polar. The δ+ hydrogen of one molecule is attracted to the δ− oxygen of a neighbor. That weak attraction is a hydrogen bond, not a covalent or ionic bond."}, {"id": "seed-mcq-ap-q1", "stem": "When the corner of a paper towel is dipped in water, the water climbs up the towel against gravity. The towel is made of cellulose, which has many −OH groups. Which properties of water best explain this?", "img": null, "choices": ["The nonpolar nature of water, which lets it slip easily between fibers", "The lower density of ice, which lets water float upward through the fibers", "Adhesion of water to the polar cellulose fibers, plus cohesion that pulls more water molecules along behind", "The high specific heat of water, which makes warm water rise"], "answer": 2, "why": "This is capillary action. Water hydrogen-bonds to the polar −OH groups (adhesion) and to other water molecules (cohesion)."}, {"id": "seed-mcq-ap-q2", "stem": "Cities on the coast usually have smaller day-to-night temperature swings than cities far inland. Which property of water best explains this?", "img": null, "choices": ["Water is nonpolar, so it does not absorb energy from sunlight", "Water has low cohesion, so it evaporates quickly and cools the air", "Water has a high specific heat because many hydrogen bonds must be broken before its temperature rises, so the ocean absorbs and releases heat slowly", "Water is a good solvent, so it dissolves heat from the air"], "answer": 2, "why": "Hydrogen bonds absorb a lot of energy before water molecules speed up. Large bodies of water resist temperature change and moderate nearby climates."}, {"id": "seed-mcq-ap-q3", "stem": "A water strider can stand on the surface of a pond without sinking. Which best explains this?", "img": null, "choices": ["Water at the surface is denser than water below it", "Hydrogen bonds between water molecules at the surface create surface tension that resists being broken", "Covalent bonds between water molecules at the surface form a solid layer", "The insect is hydrophilic, so it is attracted to water and floats"], "answer": 1, "why": "Surface tension is cohesion at the surface. Surface water molecules hydrogen-bond tightly to their neighbors."}, {"id": "seed-mcq-ap-q4", "stem": "Table salt (NaCl) dissolves easily in water, but vegetable oil forms a separate layer. Which best explains the difference?", "img": null, "choices": ["Salt is a covalent compound and oil is ionic", "Oil molecules are too large to fit between water molecules, while salt ions are small", "The partial charges on water molecules surround and separate charged Na⁺ and Cl⁻ ions, but oil is nonpolar and cannot hydrogen-bond with water", "Water is nonpolar, so it only dissolves nonpolar substances like salt"], "answer": 2, "why": "Water is a good solvent for charged and polar substances. Oil is made of nonpolar C–H chains (hydrophobic), so water excludes it."}, {"id": "seed-mcq-ap-q5", "stem": "Suppose water molecules were nonpolar instead of polar. Which change would most likely result?", "img": null, "choices": ["Water would no longer form hydrogen bonds, so it would lose cohesion and its temperature would change much more easily", "Water would become a better solvent for salts and sugars", "Ice would become even less dense and float higher", "Water would form more hydrogen bonds and have a higher boiling point"], "answer": 0, "why": "Every special property of water (cohesion, adhesion, high specific heat, solvent ability, floating ice) comes from polarity and hydrogen bonding."}, {"id": "seed-mcq-ap-q6", "stem": "Bacteria are grown in a medium where the only sulfur source is radioactive ³⁵S. After several generations, which molecules would contain the radioactive label?", "img": null, "choices": ["Triglycerides", "Carbohydrates", "Proteins", "DNA"], "answer": 2, "why": "Of the four macromolecules, only proteins contain sulfur (in cysteine and methionine). CHONS = proteins."}, {"id": "seed-mcq-ap-q7", "stem": "Plant cells are given radioactive phosphorus (³²P). In which molecules would the label mostly appear?", "img": null, "choices": ["Nucleic acids and phospholipids", "Proteins and carbohydrates", "Steroids and amino acids", "Carbohydrates and triglycerides"], "answer": 0, "why": "Phosphorus is in the phosphate groups of the DNA/RNA backbone (and ATP) and in phospholipid heads."}, {"id": "seed-mcq-ap-q8", "stem": "A farmer’s soil has very little available nitrogen. The crops grow poorly. Which best explains the poor growth?", "img": null, "choices": ["Without nitrogen, the plants cannot make carbohydrates for energy", "Without nitrogen, the plants cannot absorb water through their roots", "Without nitrogen, the plants cannot make enough proteins and nucleic acids", "Without nitrogen, the plants cannot make phospholipids for membranes"], "answer": 2, "why": "Nitrogen is in amino acids (the −NH₂ group) and the nitrogenous bases. Carbohydrates and most lipids have no N."}, {"id": "seed-mcq-ap-q9", "stem": "A student analyzes three unknown biological molecules.<table class=\"qt\"><tr><th>Molecule</th><th>Elements present</th><th>Notes</th></tr><tr><td>X</td><td>C, H, O</td><td>about 1 C : 2 H : 1 O</td></tr><tr><td>Y</td><td>C, H, O, N, S</td><td>long unbranched chain</td></tr><tr><td>Z</td><td>C, H, O, N, P</td><td>two strands</td></tr></table>Which identification is best supported?", "img": null, "choices": ["X is a carbohydrate, Y is a nucleic acid, Z is a protein", "X is a protein, Y is a carbohydrate, Z is a lipid", "X is a lipid, Y is a nucleic acid, Z is a protein", "X is a carbohydrate, Y is a protein, Z is a nucleic acid"], "answer": 3, "why": "1:2:1 CHO = carbohydrate. S is the giveaway for protein (CHONS). P plus two strands = DNA (CHONP)."}, {"id": "seed-mcq-ap-q10", "stem": "Which best describes the reaction shown from left to right?", "img": "seed/img/bio-dehydration.svg", "choices": ["Dehydration synthesis: water is added to form a hydrogen bond between the monomers", "Hydrolysis: water is added to break the bond between the monomers", "Hydrolysis: an ionic bond forms and water is released", "Dehydration synthesis: an −OH and an −H are removed as water, and a covalent bond forms between the monomers"], "answer": 3, "why": "Left to right, water comes OUT and a new covalent bond forms. That is dehydration synthesis (anabolic). The reverse (water IN) is hydrolysis."}, {"id": "seed-mcq-ap-q11", "stem": "A polysaccharide made of 25 glucose monomers is completely hydrolyzed. How many water molecules are used?", "img": null, "choices": ["26", "25", "12", "24"], "answer": 3, "why": "A chain of 25 monomers has 24 bonds, and each bond needs one water to break. The rule is n − 1."}, {"id": "seed-mcq-ap-q12", "stem": "In the small intestine, the enzyme maltase breaks maltose into two glucose molecules. Which best describes this reaction?", "img": null, "choices": ["Dehydration synthesis: energy is released as two glucose molecules join", "Hydrolysis: a water molecule is used to break the glycosidic linkage, and energy is released", "Dehydration synthesis: a water molecule is released as the glycosidic linkage forms", "Hydrolysis: a water molecule is released as the peptide bond breaks"], "answer": 1, "why": "Breaking a polymer or dimer uses water (hydrolysis). It is catabolic and exergonic."}, {"id": "seed-mcq-ap-q13", "stem": "The figure shows two glucose molecules forming maltose. Which statement about the new bond is correct?", "img": "seed/img/bio-maltose.svg", "choices": ["It is a peptide bond between carbon 1 and carbon 4", "It is a covalent glycosidic linkage (C–O–C) formed when an −OH from one glucose and an −H from the other leave as water", "It is an ionic bond between the two ring oxygens", "It is a hydrogen bond formed when water is added between the two rings"], "answer": 1, "why": "The bridging O is a glycosidic linkage, a covalent bond between sugars made by dehydration synthesis."}, {"id": "seed-mcq-ap-q14", "stem": "Which statement is true of both dehydration synthesis and hydrolysis in living cells?", "img": null, "choices": ["Both form covalent bonds between monomers", "Both require specific enzymes to occur at the rates needed by the cell", "Both release free energy", "Both release a water molecule"], "answer": 1, "why": "Dehydration releases water and needs energy; hydrolysis uses water and releases energy. What they share is that both need enzymes."}, {"id": "seed-mcq-ap-q15", "stem": "Animals store glucose as glycogen, which is highly branched. Plants build cell walls from cellulose, which is unbranched and forms stacked fibers. How does glycogen’s structure fit its function?", "img": "seed/img/bio-polysaccharides.svg", "choices": ["Its many branches give enzymes many free ends to break glucose off at once for quick energy", "Its branches let it hydrogen-bond into strong, rigid fibers", "Its branches make it hydrophobic so it can be stored in membranes", "Its branches prevent enzymes from breaking it down, so it lasts longer"], "answer": 0, "why": "Energy-storing carbohydrates are branched (more ends, faster release). Structural ones are straight and stack (cellulose, chitin)."}, {"id": "seed-mcq-ap-q16", "stem": "Humans have enzymes that hydrolyze starch but not cellulose, even though both are made only of glucose. Which is the best explanation?", "img": "seed/img/fig-starch-cellulose.jpg", "choices": ["Starch is held together by ionic bonds that are easier to break", "The β linkages in cellulose give it a different shape, so the human enzymes that fit α linkages cannot bind and hydrolyze it", "Cellulose is made of fructose instead of glucose", "Cellulose contains nitrogen, which human enzymes cannot break"], "answer": 1, "why": "Same monomer, different linkage. In cellulose every other glucose is flipped, so the molecule has a shape that starch-digesting enzymes don’t fit."}, {"id": "seed-mcq-ap-q17", "stem": "Termites eat wood, which is mostly cellulose, yet they obtain glucose from it. Which best explains this?", "img": null, "choices": ["Microorganisms living in the termite’s gut produce enzymes that hydrolyze cellulose into glucose", "Termites convert cellulose to starch before digesting it", "Cellulose is broken down by stomach acid rather than enzymes", "Termites absorb whole cellulose molecules directly into their cells"], "answer": 0, "why": "Like cows and sheep, termites rely on gut microbes that make cellulose-digesting enzymes."}, {"id": "seed-mcq-ap-q18", "stem": "Glucose and fructose both have the formula C₆H₁₂O₆. Based on the figure, which statement is correct?", "img": "seed/img/bio-linear-sugars.svg", "choices": ["Fructose is a lipid because it has fewer −OH groups", "They are the same molecule drawn two different ways", "They are structural isomers: glucose has its C=O at the end of the chain (aldehyde) and fructose has it in the middle (ketone)", "They are polymers because they contain six carbons"], "answer": 2, "why": "Same atoms, different arrangement = isomers. The position of the carbonyl makes one an aldehyde sugar and the other a ketone sugar."}, {"id": "seed-mcq-ap-q19", "stem": "Olive oil is liquid at room temperature, while butter is solid. Based on the figure, which best explains this?", "img": "seed/img/bio-fatty-acids.svg", "choices": ["Olive oil has mostly saturated fatty acids that are straighter and pack loosely", "Butter is made of carbohydrates, which are solid at room temperature", "Butter contains more double bonds, which hold the molecules together as a solid", "Olive oil has mostly unsaturated fatty acids whose cis double bonds create kinks, so the molecules cannot pack tightly"], "answer": 3, "why": "Saturated = no C=C, straight, packs tight, solid. Unsaturated = C=C kinks, can’t pack, liquid."}, {"id": "seed-mcq-ap-q20", "stem": "Phospholipids placed in water spontaneously form a double layer. Which best explains this arrangement?", "img": "seed/img/bio-phospholipid.svg", "choices": ["The phosphate heads are nonpolar and repel water", "The hydrophilic tails face the water, and the hydrophobic heads face each other", "The hydrophobic fatty acid tails cluster together away from water, while the hydrophilic phosphate heads face the water on both sides", "Covalent bonds form between the tails of neighboring phospholipids"], "answer": 2, "why": "Head = polar, charged, water-loving. Tails = nonpolar, water-avoiding. The bilayer hides the tails from water."}, {"id": "seed-mcq-ap-q21", "stem": "Which best describes how the molecule shown is built?", "img": "seed/img/bio-triglyceride.svg", "choices": ["One glycerol and three fatty acids are joined by three dehydration reactions, forming ester linkages and releasing three water molecules", "Amino acids are joined by peptide bonds to form a chain", "Three glycerol molecules are joined to one fatty acid by hydrolysis", "One glycerol, two fatty acids and a phosphate group are joined by hydrogen bonds"], "answer": 0, "why": "A triglyceride (fat) = 1 glycerol + 3 fatty acids. It is not a polymer, but it is still built by dehydration synthesis."}, {"id": "seed-mcq-ap-q22", "stem": "Testosterone is a steroid hormone that can pass directly through the plasma membrane to reach receptors inside the cell. Which best explains this?", "img": "seed/img/bio-steroid.svg", "choices": ["Steroids are nonpolar lipids, so they can move through the hydrophobic interior of the phospholipid bilayer", "Steroids are charged, so they are attracted to the phosphate heads", "Steroids are proteins that open channels in the membrane", "Steroids are small carbohydrates that dissolve in the cytoplasm"], "answer": 0, "why": "Steroids (four fused rings, almost no O) are hydrophobic lipids and dissolve through the membrane’s nonpolar core."}, {"id": "seed-mcq-ap-q23", "stem": "Many seeds store energy mostly as oils rather than as starch. Which is the main advantage of this?", "img": null, "choices": ["Fats store more than twice as much energy per gram as carbohydrates, so the seed can stay small and light", "Starch cannot be broken down by plant enzymes", "Oils contain nitrogen needed to build the embryo’s proteins", "Oils dissolve in water, so the embryo can use them quickly"], "answer": 0, "why": "Lipids = 9 Cal/g, carbohydrates = 4 Cal/g. Compact energy storage is an advantage for seeds and animals."}, {"id": "seed-mcq-ap-q24", "stem": "The figure shows the general structure of an amino acid. Which part differs among the 20 amino acids used to build proteins?", "img": "seed/img/bio-amino-acid.svg", "choices": ["The hydrogen attached to the central carbon", "The R group (side chain) attached to the central carbon", "The carboxyl group (−COOH)", "The amino group (−NH₂)"], "answer": 1, "why": "Every amino acid has the same backbone: H₂N–C(H)–COOH. Only the R group changes, and it decides the amino acid’s chemical properties."}, {"id": "seed-mcq-ap-q25", "stem": "In sickle-cell disease, valine (nonpolar R group) replaces glutamic acid (charged R group) at one position on the surface of hemoglobin. Which is the most likely result?", "img": "seed/img/fig-sickle.jpg", "choices": ["Hemoglobin gains an extra polypeptide chain and carries more oxygen", "There is no effect, because only one of 146 amino acids changed", "The hemoglobin becomes a carbohydrate and is broken down for energy", "The nonpolar valine makes hemoglobin molecules stick to each other, changing their shape and function and deforming red blood cells"], "answer": 3, "why": "A change in primary structure can change folding. Hydrophobic valine on the surface causes hemoglobins to clump into fibers."}, {"id": "seed-mcq-ap-q26", "stem": "Which level of protein structure is determined directly by the gene’s DNA sequence?", "img": "seed/img/bio-protein-levels.svg", "choices": ["Tertiary structure, the overall 3-D shape", "Primary structure, the sequence of amino acids", "Quaternary structure, the arrangement of several chains", "Secondary structure, the α helices and β sheets"], "answer": 1, "why": "DNA codes for the amino acid order (primary). That order then determines how the chain folds into the other levels."}, {"id": "seed-mcq-ap-q27", "stem": "A section of a protein contains many amino acids with nonpolar R groups, such as leucine, valine and isoleucine. In the watery cytoplasm, where is this section most likely found when the protein folds?", "img": null, "choices": ["In the interior of the protein, away from water", "On the outer surface of the protein, touching water", "Bonded covalently to water molecules", "Cut off from the protein because it cannot fold"], "answer": 0, "why": "Hydrophobic R groups cluster in the core (hydrophobic interactions), part of tertiary structure."}, {"id": "seed-mcq-ap-q28", "stem": "An enzyme is heated to 90 °C and stops working, even though no peptide bonds were broken. Which is the best explanation?", "img": "seed/img/fig-denature.jpg", "choices": ["The heat converted the enzyme into a carbohydrate", "The heat changed the order of its amino acids", "The heat added extra amino acids to the chain", "The heat disrupted the hydrogen bonds and other weak interactions that hold its 3-D shape, so it no longer fits its substrate"], "answer": 3, "why": "That is denaturation. The primary structure is still there, but the shape (and therefore the function) is lost."}, {"id": "seed-mcq-ap-q29", "stem": "In the figure, the new bond (green) that joins the two amino acids forms between which atoms?", "img": "seed/img/bio-dipeptide.svg", "choices": ["The carbon of the carboxyl group of one amino acid and the nitrogen of the amino group of the next", "The two R groups of the amino acids", "The two central (α) carbons", "The oxygen of one amino acid and the oxygen of the next"], "answer": 0, "why": "A peptide bond is C–N, formed by dehydration synthesis. That’s why an amino acid needs both an −NH₂ and a −COOH to be in the middle of a chain."}, {"id": "seed-mcq-ap-q30", "stem": "Hair gets its strength from many covalent bonds between the sulfur atoms of cysteine R groups. These bonds are called", "img": null, "choices": ["hydrogen bonds, which form α helices", "peptide bonds, which form primary structure", "glycosidic linkages, which join sugars", "disulfide bridges, which help hold tertiary structure"], "answer": 3, "why": "Two sulfhydryl (−SH) groups on cysteines bond S–S. It is a covalent “rivet” that stabilizes the folded shape."}, {"id": "seed-mcq-ap-q31", "stem": "Hemoglobin is made of four polypeptide chains that fit together into one functional protein. This is an example of", "img": null, "choices": ["primary structure", "denaturation", "quaternary structure", "secondary structure"], "answer": 2, "why": "Quaternary structure only exists when a protein has two or more polypeptide chains."}, {"id": "seed-mcq-ap-q32", "stem": "A DNA sample is 30% adenine. What percentage of the bases are guanine?", "img": "seed/img/bio-dna.svg", "choices": ["40%", "70%", "30%", "20%"], "answer": 3, "why": "A pairs with T, so T = 30% and A + T = 60%. The remaining 40% is split evenly between G and C, so G = 20%."}, {"id": "seed-mcq-ap-q33", "stem": "Which feature distinguishes a DNA nucleotide from an RNA nucleotide?", "img": "seed/img/bio-nucleotide.svg", "choices": ["DNA nucleotides have no phosphate group", "DNA’s sugar (deoxyribose) has only H on the 2′ carbon, and DNA uses thymine instead of uracil", "RNA nucleotides contain sulfur instead of phosphorus", "DNA nucleotides have two sugars instead of one"], "answer": 1, "why": "Deoxyribose = “missing an oxygen” at 2′. Base difference: T in DNA, U in RNA."}, {"id": "seed-mcq-ap-q34", "stem": "A section of one DNA strand reads 5′-ATGCCA-3′. Which is the complementary strand?", "img": null, "choices": ["5′-TACGGT-3′", "3′-ATGCCA-5′", "3′-TACGGT-5′", "3′-UACGGU-5′"], "answer": 2, "why": "Pair A–T and G–C, and run the new strand in the opposite direction (antiparallel). U would only appear in RNA."}, {"id": "seed-mcq-ap-q35", "stem": "The figure shows two nucleotides joining. The bond that links them is", "img": "seed/img/bio-phosphodiester.svg", "choices": ["a covalent phosphodiester bond between a phosphate and the 3′ carbon of the neighboring sugar", "a peptide bond between two sugars", "a hydrogen bond between two nitrogenous bases", "an ionic bond between two phosphate groups"], "answer": 0, "why": "The sugar–phosphate backbone is held by phosphodiester linkages. Hydrogen bonds only hold the two strands together at the bases."}, {"id": "seed-mcq-ap-q36", "stem": "The DNA double helix has the same width along its whole length. Which best explains this?", "img": "seed/img/bio-bases.svg", "choices": ["The sugars are all the same size, and the bases do not pair", "The phosphate groups are in the middle of the helix", "Every base pair contains two purines", "Every base pair contains one two-ring purine paired with one one-ring pyrimidine"], "answer": 3, "why": "A (purine) pairs with T (pyrimidine), and G (purine) pairs with C (pyrimidine), so each rung is the same length."}, {"id": "seed-mcq-ap-q37", "stem": "Which best describes how genetic information in a eukaryotic cell is used to make a protein?", "img": "seed/img/bio-gene-expression.svg", "choices": ["mRNA is translated into DNA, which then folds into a protein", "Ribosomes travel into the nucleus to read the DNA directly", "A gene’s DNA is copied into mRNA in the nucleus; the mRNA travels to a ribosome in the cytoplasm, where its sequence directs the order of amino acids", "Proteins are copied directly from DNA inside the nucleus"], "answer": 2, "why": "DNA → RNA → protein. DNA stays in the nucleus, and mRNA carries the message out."}, {"id": "seed-mcq-ap-q38", "stem": "A scientist isolates a single-stranded nucleic acid and finds that it contains uracil. Which conclusion is best supported?", "img": null, "choices": ["The molecule is a polysaccharide", "The molecule is DNA", "The molecule is RNA", "The molecule is a protein"], "answer": 2, "why": "Uracil is found only in RNA. RNA is also usually single-stranded."}, {"id": "seed-mcq-ap-q39", "stem": "The molecule ATP is best classified as", "img": "seed/img/bio-atp.svg", "choices": ["a lipid made of glycerol and three fatty acids", "a protein made of three amino acids", "a polysaccharide made of three sugars", "a nucleotide made of adenine, ribose and three phosphate groups"], "answer": 3, "why": "ATP has all three nucleotide parts (base + 5-carbon sugar + phosphates). Breaking off the last phosphate releases energy."}, {"id": "seed-mcq-ap-q40", "stem": "The functional group shown is found in which pair of molecules?", "img": "seed/img/group-phosphate.svg", "choices": ["Steroids and triglycerides", "Nucleic acids and phospholipids", "Amino acids and fatty acids", "Carbohydrates and proteins"], "answer": 1, "why": "This is a phosphate group. It forms the DNA/RNA backbone (and ATP) and the head of every phospholipid."}, {"id": "seed-mcq-ap-q41", "stem": "Which best identifies the molecule shown?", "img": "seed/img/pid-30.svg", "choices": ["A lipid, because it has a long hydrocarbon chain", "A carbohydrate, because it has an −OH group", "An amino acid; its sulfur-containing R group can form disulfide bridges", "A nucleotide, because it contains nitrogen"], "answer": 2, "why": "H₂N and COOH on a central carbon = amino acid. The −CH₂SH side chain makes it cysteine."}, {"id": "seed-mcq-ap-q42", "stem": "A student claims the molecule shown is part of a nucleic acid because it contains a ring. Which best evaluates the claim?", "img": "seed/img/pid-33.svg", "choices": ["The claim is correct: any molecule with a ring is a nucleic acid", "The claim is correct: the ring is a purine base", "The claim is incorrect: the molecule is a steroid because it has a ring", "The claim is incorrect: the ring has no nitrogen in it, and the molecule has −NH₂ and −COOH on a central carbon, so it is an amino acid"], "answer": 3, "why": "In nucleic acids the N is inside the ring. Here the ring is all carbon (phenylalanine’s side chain)."}, {"id": "seed-mcq-ap-q43", "stem": "Which best identifies the molecule shown?", "img": "seed/img/pid-22.svg", "choices": ["A nucleotide, because it contains phosphorus and nitrogen", "A phospholipid: a glycerol backbone with two fatty acid tails and a phosphate-containing head", "A protein, because it contains nitrogen", "A triglyceride, because it has glycerol and three fatty acids"], "answer": 1, "why": "Two tails + phosphate head = phospholipid. The P doesn’t make it a nucleic acid; the long hydrocarbon tails make it a lipid."}, {"id": "seed-mcq-ap-q44", "stem": "A researcher tests three digestive enzymes.<table class=\"qt\"><tr><th>Tube</th><th>Substance</th><th>Enzyme</th><th>Product detected</th></tr><tr><td>1</td><td>Protein</td><td>Protease</td><td>Amino acids</td></tr><tr><td>2</td><td>Starch</td><td>Protease</td><td>None</td></tr><tr><td>3</td><td>Starch</td><td>Amylase</td><td>Glucose</td></tr><tr><td>4</td><td>Triglyceride</td><td>Amylase</td><td>None</td></tr></table>Which conclusion is best supported by the data?", "img": null, "choices": ["Each enzyme hydrolyzes only a specific type of polymer", "Amylase breaks down all types of macromolecules", "Protease can digest starch if given enough time", "Triglycerides cannot be broken down by any enzyme"], "answer": 0, "why": "Protease worked only on protein, and amylase only on starch. Enzymes are specific because their shape must fit the substrate."}]}, {"id": "seed-mcq-nucleic", "rev": 1, "kind": "mcq", "title": "Nucleic Acids Deep Dive (fix-it set)", "folder": "AP Bio", "description": "Aimed at the gaps from your AP test: where phosphorus lives, bond names, base-pair math, and base vs nucleoside vs nucleotide.", "cards": [], "questions": [{"id": "seed-mcq-nucleic-q0", "stem": "Which molecule contains phosphorus?", "img": null, "choices": ["ATP", "Glucose", "Alanine (an amino acid)", "Cholesterol"], "answer": 0, "why": "ATP is a nucleotide: base + sugar + 3 phosphates. Sugars, amino acids and steroids have no P."}, {"id": "seed-mcq-nucleic-q1", "stem": "Which of these does NOT contain any phosphorus?", "img": null, "choices": ["A phospholipid", "DNA", "ATP", "Starch"], "answer": 3, "why": "P lives in exactly three places you need to know: nucleic acids (backbone), ATP, and phospholipid heads. Starch is just glucose (CHO)."}, {"id": "seed-mcq-nucleic-q2", "stem": "A cell is grown with radioactive ³²P. Which part of a DNA molecule becomes radioactive?", "img": "seed/img/bio-phosphodiester.svg", "choices": ["The hydrogen bonds between bases", "The deoxyribose sugar only", "The nitrogenous bases only", "The sugar–phosphate backbone"], "answer": 3, "why": "Phosphorus is in the phosphate groups, which alternate with sugars to form the backbone."}, {"id": "seed-mcq-nucleic-q3", "stem": "The functional group −OPO₃²⁻ is found in which pair?", "img": "seed/img/group-phosphate.svg", "choices": ["DNA and phospholipids", "Amino acids and triglycerides", "Steroids and fatty acids", "Glycogen and cellulose"], "answer": 0, "why": "Phosphate = the P in CHONP and the head of every phospholipid."}, {"id": "seed-mcq-nucleic-q4", "stem": "Which bond joins one nucleotide to the next along a DNA strand?", "img": "seed/img/bio-phosphodiester.svg", "choices": ["Phosphodiester bond (covalent)", "Peptide bond", "Hydrogen bond", "Glycosidic linkage"], "answer": 0, "why": "Match bond to class: glycosidic = sugars, peptide = amino acids, ester = fats, phosphodiester = nucleotides."}, {"id": "seed-mcq-nucleic-q5", "stem": "Which bonds hold the two strands of DNA together?", "img": "seed/img/bio-dna.svg", "choices": ["Hydrogen bonds between complementary bases", "Phosphodiester bonds between sugars", "Ionic bonds between phosphates", "Peptide bonds between bases"], "answer": 0, "why": "Strong covalent bonds make each strand’s backbone. Weak hydrogen bonds hold the two strands together, so they can unzip to be copied."}, {"id": "seed-mcq-nucleic-q6", "stem": "A peptide bond could join which two molecules?", "img": null, "choices": ["A glycerol and a fatty acid", "Two nucleotides", "Two sugars", "Two amino acids"], "answer": 3, "why": "Elimination trick: “peptide” only ever goes with amino acids. If an answer says “peptide bond between two sugars”, cross it out."}, {"id": "seed-mcq-nucleic-q7", "stem": "When DNA is heated, the two strands separate but each strand stays intact. Which bonds broke?", "img": null, "choices": ["Covalent bonds inside the sugars", "Peptide bonds between nucleotides", "Phosphodiester bonds in the backbone", "Hydrogen bonds between the bases"], "answer": 3, "why": "Hydrogen bonds are weak and break easily. The covalent backbone stays together."}, {"id": "seed-mcq-nucleic-q8", "stem": "A double-stranded DNA sample is 20% thymine. What percent is cytosine?", "img": null, "choices": ["40%", "30%", "20%", "60%"], "answer": 1, "why": "T = A = 20%, so A + T = 40%. The remaining 60% is split evenly: G = C = 30%."}, {"id": "seed-mcq-nucleic-q9", "stem": "A double-stranded DNA sample is 35% guanine. What percent is adenine?", "img": null, "choices": ["35%", "65%", "30%", "15%"], "answer": 3, "why": "G = C = 35%, so G + C = 70%. The remaining 30% is split evenly: A = T = 15%."}, {"id": "seed-mcq-nucleic-q10", "stem": "DNA is 18% adenine. What percent is guanine?", "img": null, "choices": ["36%", "64%", "32%", "18%"], "answer": 2, "why": "A = T = 18% → 36% total. 100 − 36 = 64%, split in half → G = 32%. The trap answer is 64% (forgetting to split)."}, {"id": "seed-mcq-nucleic-q11", "stem": "Which set of base percentages could come from double-stranded DNA?", "img": null, "choices": ["A 28%, T 22%, G 28%, C 22%", "A 28%, T 28%, G 22%, C 22%", "A 25%, U 25%, G 25%, C 25%", "A 40%, T 10%, G 40%, C 10%"], "answer": 1, "why": "In double-stranded DNA, A = T and G = C. Uracil means RNA."}, {"id": "seed-mcq-nucleic-q12", "stem": "Why does the DNA double helix have the same width everywhere?", "img": "seed/img/bio-bases.svg", "choices": ["The sugars are all the same size, and the bases do not pair", "Each pair is one two-ring purine with one one-ring pyrimidine", "The phosphates are in the middle of the helix", "Every pair has two purines"], "answer": 1, "why": "Big (2 rings) + small (1 ring) = same total every time. Reading tip: “the bases do not pair” is false, so that choice is out immediately."}, {"id": "seed-mcq-nucleic-q13", "stem": "Write the complement of 5′-GATTC-3′.", "img": null, "choices": ["3′-CTAAG-5′", "3′-CUAAG-5′", "5′-CTAAG-3′", "3′-GATTC-5′"], "answer": 0, "why": "Swap A↔T and G↔C, and flip the direction (antiparallel). U only appears in RNA."}, {"id": "seed-mcq-nucleic-q14", "stem": "In RNA, adenine pairs with", "img": null, "choices": ["uracil", "guanine", "cytosine", "thymine"], "answer": 0, "why": "RNA has U instead of T."}, {"id": "seed-mcq-nucleic-q15", "stem": "What makes up the backbone of a DNA strand?", "img": "seed/img/bio-dna.svg", "choices": ["Alternating bases and sugars", "Alternating sugars and phosphates", "Amino acids linked by peptide bonds", "Nitrogenous bases only"], "answer": 1, "why": "Backbone = sugar–phosphate–sugar–phosphate. Bases stick off the side toward the middle."}, {"id": "seed-mcq-nucleic-q16", "stem": "What actually carries the genetic information in DNA?", "img": null, "choices": ["The sequence (order) of the nitrogenous bases", "The number of phosphate groups", "The hydrogen bonds between strands", "The type of sugar"], "answer": 0, "why": "Every nucleotide has the same sugar and phosphate. Only the base changes, so the order of bases is the code."}, {"id": "seed-mcq-nucleic-q17", "stem": "What does “antiparallel” mean for DNA?", "img": "seed/img/bio-dna.svg", "choices": ["The bases are parallel to the backbone", "The strands never touch each other", "The two strands are identical copies", "The two strands run in opposite directions (one 5′→3′, the other 3′→5′)"], "answer": 3, "why": "Like a two-lane road with traffic going opposite ways."}, {"id": "seed-mcq-nucleic-q18", "stem": "Which end of a DNA strand has a free phosphate group?", "img": "seed/img/bio-phosphodiester.svg", "choices": ["The 5′ end", "The 3′ end", "Neither end", "Both ends"], "answer": 0, "why": "5′ = phosphate end, 3′ = −OH end. New nucleotides are added onto the 3′ −OH."}, {"id": "seed-mcq-nucleic-q19", "stem": "What is the difference between deoxyribose and ribose?", "img": "seed/img/pid-48.svg", "choices": ["Deoxyribose contains nitrogen", "Ribose is found only in DNA", "Deoxyribose has only H on the 2′ carbon; ribose has −OH there", "Deoxyribose has six carbons; ribose has five"], "answer": 2, "why": "“Deoxy” = missing an oxygen. Deoxyribose → DNA, ribose → RNA."}, {"id": "seed-mcq-nucleic-q20", "stem": "Identify the molecule shown.", "img": "seed/img/pid-45.svg", "choices": ["Amino acid", "Nucleoside (base + sugar, no phosphate)", "Nucleotide", "Pyrimidine base"], "answer": 1, "why": "There’s a ring with N (base) and a 5-sided sugar, but no P. NucleoSide = Sugar + base."}, {"id": "seed-mcq-nucleic-q21", "stem": "Identify the molecule shown.", "img": "seed/img/pid-47.svg", "choices": ["Nucleoside", "Purine base", "Phospholipid", "Nucleotide"], "answer": 3, "why": "Base + sugar + phosphate (the P). NucleoTide has the phosphaTe."}, {"id": "seed-mcq-nucleic-q22", "stem": "Identify the molecule shown.", "img": "seed/img/pid-41.svg", "choices": ["Purine base (adenine)", "Nucleoside", "Amino acid (lysine)", "Pyrimidine base (cytosine)"], "answer": 3, "why": "One ring with N inside it, and nothing else attached = a base. One ring = pyrimidine. The −NH₂ is on the ring, not next to a −COOH."}, {"id": "seed-mcq-nucleic-q23", "stem": "Identify the molecule shown.", "img": "seed/img/pid-38.svg", "choices": ["Steroid", "Nucleotide", "Pyrimidine base (cytosine)", "Purine base (adenine)"], "answer": 3, "why": "Two fused rings (6 + 5) with N in both = purine. −NH₂ on top = adenine."}, {"id": "seed-mcq-nucleic-q24", "stem": "Identify the molecule shown.", "img": "seed/img/pid-33.svg", "choices": ["Pyrimidine base", "Purine base", "Amino acid (phenylalanine)", "Nucleoside"], "answer": 2, "why": "The ring has NO N in it. H₂N–C–COOH on a central carbon = amino acid. Rings alone don’t mean nucleic acid."}, {"id": "seed-mcq-nucleic-q25", "stem": "Which is the best first check to decide whether a picture is an amino acid or part of a nucleic acid?", "img": null, "choices": ["Find the N: is it inside a ring (nucleic acid) or in −NH₂ next to a −COOH (amino acid)?", "Look for oxygen", "Check whether there is any ring", "Count the carbons"], "answer": 0, "why": "Both classes have N. Where the N sits is what separates them."}, {"id": "seed-mcq-nucleic-q26", "stem": "ATP is best classified as a", "img": "seed/img/bio-atp.svg", "choices": ["lipid", "nucleotide", "protein", "nucleoside"], "answer": 1, "why": "It has a base (adenine), a sugar (ribose) and phosphates (3 of them). Anything with all three parts is a nucleotide."}]}, {"id": "seed-biochem", "rev": 1, "title": "Biochem Quiz 9-16", "folder": "AP Bio", "description": "From your Quizlet export, with structure pictures added.", "cards": [{"id": "seed-biochem-0", "term": "Main elements of life", "def": "Carbon, Hydrogen, Oxygen, Nitrogen (CHON)."}, {"id": "seed-biochem-1", "term": "Covalent bond", "def": "Occurs when two atoms share electrons. Energy is stored in covalent bonds and is released when the bond is broken."}, {"id": "seed-biochem-2", "term": "Biomolecule", "def": "An organic, carbon based macromolecule. All living organisms need biomolecules. Four main types: carbohydrates, lipids, proteins, nucleic acids."}, {"id": "seed-biochem-3", "term": "Organic", "def": "Can be used and converted by living things. Organic molecules are carbon based."}, {"id": "seed-biochem-4", "term": "Monomer", "def": "The individual subunit (building block) of a biomolecule."}, {"id": "seed-biochem-5", "term": "Dimer", "def": "Two monomers covalently bonded together."}, {"id": "seed-biochem-6", "term": "Polymer", "def": "Many monomers covalently bonded together."}, {"id": "seed-biochem-7", "term": "Biomolecule metabolism", "def": "The combination of chemical reactions that synthesize and hydrolyze biomolecules for energy storage and release in an organism."}, {"id": "seed-biochem-8", "term": "Anabolic reaction", "def": "Builds up monomers into biological polymers for energy storage. Anabolic reactions are endergonic, meaning they require a net investment of free energy into the bonds between the monomers."}, {"id": "seed-biochem-9", "term": "Catabolic reaction", "def": "Breaks down biological polymers into monomers to help generate ATP. Catabolic reactions are exergonic, meaning there is a net release of free energy."}, {"id": "seed-biochem-10", "term": "Free energy", "def": "Energy that is actually available for a cell to use for metabolic processes."}, {"id": "seed-biochem-11", "term": "Dehydration synthesis", "def": "The process by which monomers are covalently bonded together into polymers. Dehydration = removal of water, synthesis = to make (a bond), so it is the removal of water to make a bond between monomers. Water is formed as a byproduct. It is an anabolic process and requires enzymes. Also called a condensation reaction.", "defImg": "seed/img/bio-dehydration.svg"}, {"id": "seed-biochem-12", "term": "Hydrolysis", "def": "The process by which polymers are broken down into monomers. Hydro = water, lysis = to break (a bond), so it uses water to break the bond between monomers. It is a catabolic process that releases energy, and it requires enzymes and the breakdown of water.", "defImg": "seed/img/bio-dehydration.svg"}, {"id": "seed-biochem-13", "term": "Enzyme", "def": "A specialized protein that speeds up (catalyzes) chemical reactions in cells to help maintain homeostasis. Both dehydration synthesis and hydrolysis require enzymes."}, {"id": "seed-biochem-14", "term": "Calories", "def": "The energy we get from breaking down biomolecules. These are the same as calories in food. Lipids have the most energy at 9 per gram; carbohydrates and proteins have 4 per gram; nucleic acids are NOT broken down for energy."}, {"id": "seed-biochem-15", "term": "Carbohydrate", "def": "Commonly referred to as sugars. Structure: hexamer rings. Elements CHO in a 1C : 2H : 1O ratio."}, {"id": "seed-biochem-16", "term": "Monosaccharide", "def": "The carbohydrate monomer - a simple sugar like glucose.", "defImg": "seed/img/bio-glucose-ring.svg"}, {"id": "seed-biochem-17", "term": "Polysaccharide", "def": "The carbohydrate polymer - a complex carbohydrate like starches or cellulose."}, {"id": "seed-biochem-18", "term": "Energy-storing carbohydrate", "def": "Has a branched structure. More branches means more monomers can be broken off at once, allowing cellular respiration to happen faster to make more ATP energy.", "defImg": "seed/img/bio-polysaccharides.svg"}, {"id": "seed-biochem-19", "term": "Structural carbohydrate", "def": "Has a linear structure and is able to stack. Stacking gives stability, allowing tough structures like plant cell walls and chitin shells in crabs.", "defImg": "seed/img/bio-polysaccharides.svg"}, {"id": "seed-biochem-20", "term": "Lipid", "def": "Commonly referred to as fats or oils. Structure: long hydrocarbon chains. Elements CHO with very little oxygen."}, {"id": "seed-biochem-21", "term": "Fatty acid", "def": "The lipid monomer."}, {"id": "seed-biochem-22", "term": "Phospholipid", "def": "A special type of lipid that makes up the main part of the cell membrane.", "defImg": "seed/img/bio-phospholipid.svg"}, {"id": "seed-biochem-23", "term": "Hydrophobic", "def": "Avoids water. Lipids are hydrophobic."}, {"id": "seed-biochem-24", "term": "Saturated fat", "def": "Does not have double bonds in its molecular structure. Saturated fats are linear, so they can stack and form solids at room temperature. This can lead to lipid build-up in blood vessels - the \"bad fats\".", "defImg": "seed/img/bio-fatty-acids.svg"}, {"id": "seed-biochem-25", "term": "Unsaturated fat", "def": "Does have double bonds in its molecular structure. The double bonds prevent them from stacking, so they are liquid at room temperature and less likely to clog arteries - the \"good fats\".", "defImg": "seed/img/bio-fatty-acids.svg"}, {"id": "seed-biochem-26", "term": "Protein", "def": "Commonly found in meats and muscles. Structure is very complex with four levels. Elements CHONS."}, {"id": "seed-biochem-27", "term": "Amino acid", "def": "The protein monomer. Joined by peptide bonds.", "defImg": "seed/img/bio-amino-acid.svg"}, {"id": "seed-biochem-28", "term": "Polypeptide", "def": "The protein polymer."}, {"id": "seed-biochem-29", "term": "Nucleic acid", "def": "Commonly referred to as genetic material. Elements CHONP. Main function: storage of genetic material."}, {"id": "seed-biochem-30", "term": "Nucleotide", "def": "The nucleic acid monomer. 3 parts: a sugar, a phosphate and a nitrogenous base, linked by covalent bonds.", "defImg": "seed/img/bio-nucleotide.svg"}, {"id": "seed-biochem-31", "term": "Directionality", "def": "DNA and RNA have a 5' end and a 3' end.", "defImg": "seed/img/bio-phosphodiester.svg"}, {"id": "seed-biochem-32", "term": "DNA", "def": "Deoxyribonucleic acid. Linear, double stranded double helix in eukaryotes (circular in prokaryotes). Deoxyribose sugar; bases A, T, C, G. More stable than RNA. Stores the genetic code. Found in the nucleus.", "defImg": "seed/img/bio-dna.svg"}, {"id": "seed-biochem-33", "term": "RNA", "def": "Ribonucleic acid. Single stranded. Ribose sugar; bases A, U, C, G. Less stable than DNA. 3 types: mRNA, tRNA, rRNA. Used for protein synthesis. Made in the nucleus and transported to the cytoplasm."}, {"id": "seed-biochem-34", "term": "Topic 1.3 Main Concept 3 (dehydration synthesis)", "def": "\"Dehydration synthesis is an anabolic chemical reaction that forms covalent bonds between monomers to build polymers of biomolecules.\" Water is formed as a byproduct of the reaction."}, {"id": "seed-biochem-35", "term": "Topic 1.3 Main Concept 4 (hydrolysis)", "def": "\"Hydrolysis is a catabolic chemical reaction that breaks the covalent bonds between monomers to break polymers into monomers.\" Water is used as a reactant in the reaction."}, {"id": "seed-biochem-36", "term": "Topic 1.3 Main Concept 5 (enzymes)", "def": "\"Both dehydration synthesis and hydrolysis require the assistance of enzymes to occur in living organisms.\""}, {"id": "seed-biochem-37", "term": "Slide labels and plural phrasing your decks use", "def": "Your decks label these sections Elemental Composition, Main Functions, Structure, and 3 Parts of a Nucleotide, and write the monomer/polymer lines in the plural: \"Monomers = monosaccharides / Polymers = polysaccharides\", \"Monomers = amino acids / Polymers = polypeptides\", \"Monomers = nucleotides\". Expect the blank to be phrased that way."}, {"id": "seed-biochem-38", "term": "Functional group", "def": "A specific cluster of atoms attached to a carbon skeleton that gives the molecule its chemical behavior."}, {"id": "seed-biochem-39", "term": "Hydroxyl (-OH)", "def": "Polar and hydrophilic. Found in every sugar, in glycerol, and in serine and threonine. Makes molecules water soluble.", "defImg": "seed/img/group-hydroxyl.svg"}, {"id": "seed-biochem-40", "term": "Carbonyl (C=O)", "def": "Polar. An aldehyde if the C=O is at the end of the chain, a ketone if it is in the middle. Found in straight-chain sugars.", "defImg": "seed/img/group-carbonyl.svg"}, {"id": "seed-biochem-41", "term": "Carboxyl (-COOH)", "def": "Polar and ACIDIC - it donates H+ and becomes -COO-. Found on every amino acid and every fatty acid.", "defImg": "seed/img/group-carboxyl.svg"}, {"id": "seed-biochem-42", "term": "Amino (-NH2)", "def": "Polar and BASIC - it accepts H+ and becomes -NH3+. Found on every amino acid.", "defImg": "seed/img/group-amino.svg"}, {"id": "seed-biochem-43", "term": "Sulfhydryl (-SH)", "def": "Two of them form a disulfide bridge (-S-S-) that holds protein tertiary structure together. Found in cysteine. This is the S in CHONS.", "defImg": "seed/img/group-sulfhydryl.svg"}, {"id": "seed-biochem-44", "term": "Phosphate (-OPO3(2-))", "def": "Polar and negatively charged. The bonds between phosphates store a lot of energy, which is how ATP works. Found in ATP, the DNA/RNA backbone and phospholipid heads. The P in CHONP.", "defImg": "seed/img/group-phosphate.svg"}, {"id": "seed-biochem-45", "term": "Methyl (-CH3)", "def": "The only NONPOLAR one - hydrophobic. C and H have nearly the same electronegativity, so no partial charges and no hydrogen bonding. Found in fatty acid tails and in thymine.", "defImg": "seed/img/group-methyl.svg"}, {"id": "seed-biochem-46", "term": "Hydrophilic", "def": "Attracted to water. Any group containing O, N or P is hydrophilic, because those atoms are electronegative enough to create partial charges."}, {"id": "seed-biochem-47", "term": "First question to ask when identifying a molecule from a picture", "def": "Is there a nitrogen? No N means carbohydrate or lipid. Has N means protein or nucleic acid. That one question splits the four types in half.", "defImg": "seed/img/step2-all.png"}, {"id": "seed-biochem-48", "term": "If it HAS nitrogen, how do you tell protein from nucleic acid?", "def": "Is the N inside a ring? Nucleic acid. Is the N in an -NH2 hanging off a carbon that also carries a -COOH? Amino acid, so protein.", "defImg": "seed/img/step2-nucleic.png"}, {"id": "seed-biochem-49", "term": "If it has NO nitrogen, how do you tell carbohydrate from lipid?", "def": "Count the oxygens. Lots of O, roughly one per carbon (1C : 2H : 1O), means carbohydrate. Very few O, maybe just one COOH, with a long hydrogen-rich chain, means lipid.", "defImg": "seed/img/step2-lipid.png"}, {"id": "seed-biochem-50", "term": "How do you spot a CARBOHYDRATE in a picture?", "def": "A ring with the oxygen INSIDE the ring and an -OH on nearly every carbon. No nitrogen. Roughly one O per carbon. The straight-chain form has a C=O plus many -OH groups.", "defImg": "seed/img/step2-carbohydrate.png"}, {"id": "seed-biochem-51", "term": "How do you spot a LIPID in a picture?", "def": "No nitrogen and almost no oxygen, plus a long zigzag hydrocarbon chain. One -COOH head = fatty acid. Glycerol + 3 tails = triglyceride. Phosphate head + 2 tails = phospholipid. Four fused rings = steroid.", "defImg": "seed/img/step2-lipid.png"}, {"id": "seed-biochem-52", "term": "How do you spot a PROTEIN (amino acid) in a picture?", "def": "A central carbon with an amino group (-NH2) on one side, a carboxyl group (-COOH) on the other, an H above and an R group below. It has nitrogen, but the N is NOT in a ring.", "defImg": "seed/img/step2-protein.png"}, {"id": "seed-biochem-53", "term": "How do you spot a NUCLEIC ACID in a picture?", "def": "Nitrogen INSIDE a ring. Phosphate + a 5-membered sugar ring + a nitrogenous base = nucleotide. Two fused rings = purine (A, G). One ring = pyrimidine (C, T, U).", "defImg": "seed/img/step2-nucleic.png"}, {"id": "seed-biochem-54", "term": "Purine vs pyrimidine", "def": "Purine = 2 fused rings (Adenine, Guanine). Pyrimidine = 1 ring (Cytosine, Thymine, Uracil).", "defImg": "seed/img/bio-bases.svg"}, {"id": "seed-biochem-55", "term": "Saturated vs unsaturated fatty acid, on a picture", "def": "Saturated = a straight zigzag with no double bonds; it stacks, so it is solid at room temperature. Unsaturated = has a C=C double bond that puts a kink in the tail, so it cannot stack and is liquid at room temperature.", "defImg": "seed/img/bio-fatty-acids.svg"}, {"id": "seed-biochem-56", "term": "How do you read a skeletal formula?", "def": "Every line end and every kink is a carbon. Hydrogens on carbons are not drawn, so assume however many it takes to give that carbon 4 bonds. Anything that is not C or H (O, N, P, S) is always written out. A double line is a double bond."}, {"id": "seed-biochem-57", "term": "Which functional groups are polar, and which is nonpolar?", "def": "If the group contains O, N or P it is polar and hydrophilic. If it is only C and H it is nonpolar and hydrophobic. Only methyl is nonpolar; the other six (hydroxyl, carbonyl, carboxyl, amino, sulfhydryl, phosphate) are all polar."}, {"id": "seed-biochem-58", "term": "Which functional group is the acid, and which is the base?", "def": "Carboxyl (-COOH) DONATES H+ so it is the acid, becoming -COO- and negatively charged. Amino (-NH2) ACCEPTS H+ so it is the base, becoming -NH3+ and positively charged. An amino acid has one of each."}, {"id": "seed-biochem-59", "term": "The monomer of a carbohydrate is a ____________.", "def": "monosaccharide"}, {"id": "seed-biochem-60", "term": "The polymer of a carbohydrate is a ____________.", "def": "polysaccharide"}, {"id": "seed-biochem-61", "term": "Carbohydrates always have a ____________ ratio of C : H : O.", "def": "1C : 2H : 1O"}, {"id": "seed-biochem-62", "term": "The monomer of a lipid is a ____________.", "def": "fatty acid"}, {"id": "seed-biochem-63", "term": "The monomer of a protein is an ____________.", "def": "amino acid"}, {"id": "seed-biochem-64", "term": "The polymer of a protein is a ____________.", "def": "polypeptide"}, {"id": "seed-biochem-65", "term": "Amino acids are joined together by ____________ bonds.", "def": "peptide", "defImg": "seed/img/bio-amino-acid.svg"}, {"id": "seed-biochem-66", "term": "The monomer of a nucleic acid is a ____________.", "def": "nucleotide"}, {"id": "seed-biochem-67", "term": "The three parts of a nucleotide are ____________.", "def": "a sugar, a phosphate and a nitrogenous base"}, {"id": "seed-biochem-68", "term": "Proteins are made of the elements ____________.", "def": "Carbon, Hydrogen, Oxygen, Nitrogen, Sulfur (CHONS)"}, {"id": "seed-biochem-69", "term": "Nucleic acids are made of the elements ____________.", "def": "Carbon, Hydrogen, Oxygen, Nitrogen, Phosphorus (CHONP)"}, {"id": "seed-biochem-70", "term": "The biomolecule with the most energy per gram is ____________, at ______ calories per gram.", "def": "lipid / 9"}, {"id": "seed-biochem-71", "term": "The biomolecule that is NOT broken down for energy is ____________.", "def": "nucleic acid"}, {"id": "seed-biochem-72", "term": "Energy-storing carbohydrates have a ____________ structure.", "def": "branched", "defImg": "seed/img/bio-polysaccharides.svg"}, {"id": "seed-biochem-73", "term": "Structural carbohydrates are ____________ and able to ____________.", "def": "linear / stack", "defImg": "seed/img/bio-polysaccharides.svg"}, {"id": "seed-biochem-74", "term": "Saturated fats have ____________ double bonds, so they are ____________ at room temperature.", "def": "no / solid", "defImg": "seed/img/bio-fatty-acids.svg"}, {"id": "seed-biochem-75", "term": "Unsaturated fats have ____________ double bonds, so they are ____________ at room temperature.", "def": "one or more / liquid", "defImg": "seed/img/bio-fatty-acids.svg"}, {"id": "seed-biochem-76", "term": "____________ are the special lipid that makes up the main part of the cell membrane.", "def": "Phospholipids"}, {"id": "seed-biochem-77", "term": "Steroids are lipids built from ____________.", "def": "four fused carbon rings"}, {"id": "seed-biochem-78", "term": "Lipids are ____________, meaning they avoid water.", "def": "hydrophobic"}, {"id": "seed-biochem-79", "term": "____________ are specialized proteins that speed up chemical reactions.", "def": "Enzymes"}, {"id": "seed-biochem-80", "term": "Protein structure has ____________ levels.", "def": "four (primary, secondary, tertiary, quaternary)"}, {"id": "seed-biochem-81", "term": "The only NONPOLAR functional group is ____________.", "def": "methyl (-CH3)"}, {"id": "seed-biochem-82", "term": "-COOH is the ____________ group and it acts as an ____________.", "def": "carboxyl / acid (donates H+)"}, {"id": "seed-biochem-83", "term": "-NH2 is the ____________ group and it acts as a ____________.", "def": "amino / base (accepts H+)"}, {"id": "seed-biochem-84", "term": "Two -SH groups can join to form a ____________.", "def": "disulfide bridge"}, {"id": "seed-biochem-85", "term": "A C=O at the END of a chain is an ____________; in the MIDDLE it is a ____________.", "def": "aldehyde / ketone"}, {"id": "seed-biochem-86", "term": "____________ builds polymers and RELEASES water.", "def": "Dehydration synthesis (condensation)"}, {"id": "seed-biochem-87", "term": "____________ breaks polymers apart and REQUIRES water.", "def": "Hydrolysis"}, {"id": "seed-biochem-88", "term": "Dehydration synthesis is ____________ and ____________.", "def": "anabolic / endergonic", "defImg": "seed/img/bio-dehydration.svg"}, {"id": "seed-biochem-89", "term": "Hydrolysis is ____________ and ____________.", "def": "catabolic / exergonic", "defImg": "seed/img/bio-dehydration.svg"}, {"id": "seed-biochem-90", "term": "Both dehydration synthesis and hydrolysis require ____________.", "def": "enzymes"}]}, {"id": "seed-mcq-basics", "rev": 1, "kind": "mcq", "title": "Biochem Basics MCQ: 1 question per card (91)", "folder": "AP Bio", "description": "One multiple-choice question for every card in your Biochem Quiz 9-16 deck (91 cards), in the same order.", "cards": [], "questions": [{"id": "seed-mcq-basics-q0", "stem": "What are the four main elements of life?", "img": null, "choices": ["Calcium, hydrogen, oxygen and nitrogen", "Carbon, hydrogen, oxygen and sulfur", "Carbon, hydrogen, oxygen and nitrogen (CHON)", "Carbon, sodium, oxygen and nitrogen"], "answer": 2, "why": "CHON makes up most of every living thing. Other elements are trace elements."}, {"id": "seed-mcq-basics-q1", "stem": "What happens in a covalent bond?", "img": null, "choices": ["One atom transfers electrons to another", "A hydrogen is attracted to an O, N or F on another molecule", "Two ions of opposite charge attract", "Two atoms share electrons, and energy is stored in the bond"], "answer": 3, "why": "Covalent = sharing. Energy is stored in covalent bonds and released when they break."}, {"id": "seed-mcq-basics-q2", "stem": "Which best defines a biomolecule?", "img": null, "choices": ["A molecule made only of nitrogen and phosphorus", "An organic, carbon-based macromolecule needed by all living things", "Any molecule that contains water", "An inorganic mineral found in cells"], "answer": 1, "why": "The four biomolecules are carbohydrates, lipids, proteins and nucleic acids."}, {"id": "seed-mcq-basics-q3", "stem": "What does “organic” mean in biology?", "img": null, "choices": ["Made only by plants", "Containing no carbon", "Carbon-based, and able to be used and converted by living things", "Grown without pesticides"], "answer": 2, "why": "All four biomolecules are organic because they are built on carbon."}, {"id": "seed-mcq-basics-q4", "stem": "What is a monomer?", "img": null, "choices": ["Many subunits bonded together", "An enzyme that joins subunits", "The individual subunit (building block) of a biomolecule", "Two subunits bonded together"], "answer": 2, "why": "Mono = one. Monomers link to make dimers and polymers."}, {"id": "seed-mcq-basics-q5", "stem": "What is a dimer?", "img": null, "choices": ["Two monomers covalently bonded together", "Many monomers bonded in a chain", "Two polymers joined by hydrogen bonds", "One single monomer"], "answer": 0, "why": "Di = two. Maltose and dipeptides are dimers."}, {"id": "seed-mcq-basics-q6", "stem": "What is a polymer?", "img": null, "choices": ["A molecule made only of water", "A single building block", "Many monomers covalently bonded together", "Two monomers bonded together"], "answer": 2, "why": "Poly = many. Polysaccharides, polypeptides and nucleic acids are polymers."}, {"id": "seed-mcq-basics-q7", "stem": "What is biomolecule metabolism?", "img": null, "choices": ["The movement of water into cells", "Only the reactions that break down food", "The copying of DNA", "All the reactions that synthesize and hydrolyze biomolecules to store and release energy"], "answer": 3, "why": "Metabolism includes both building (anabolic) and breaking down (catabolic)."}, {"id": "seed-mcq-basics-q8", "stem": "Which describes an anabolic reaction?", "img": null, "choices": ["It moves water across a membrane", "It builds monomers into polymers and is endergonic (requires energy)", "It only happens outside cells", "It breaks polymers into monomers and releases energy"], "answer": 1, "why": "Anabolic = build up. Endergonic = energy in."}, {"id": "seed-mcq-basics-q9", "stem": "Which describes a catabolic reaction?", "img": null, "choices": ["It breaks polymers into monomers and is exergonic (releases free energy that helps make ATP)", "It forms hydrogen bonds between water molecules", "It stores energy in new bonds", "It builds polymers from monomers and requires energy"], "answer": 0, "why": "Catabolic = break down. Exergonic = energy out."}, {"id": "seed-mcq-basics-q10", "stem": "What is free energy?", "img": null, "choices": ["Energy that is lost as heat and cannot be used", "Energy stored only in lipids", "Energy from sunlight only", "Energy that is actually available for a cell to use for metabolic processes"], "answer": 3, "why": "Exergonic reactions release free energy; endergonic reactions use it."}, {"id": "seed-mcq-basics-q11", "stem": "Which best describes dehydration synthesis?", "img": "seed/img/bio-dehydration.svg", "choices": ["Water is added to break the bond between monomers", "Water is removed to form a covalent bond between monomers, building a polymer", "Water is added to form a hydrogen bond", "Monomers are joined by ionic bonds without water"], "answer": 1, "why": "Dehydration = remove water; synthesis = make a bond. Water is the byproduct."}, {"id": "seed-mcq-basics-q12", "stem": "Which best describes hydrolysis?", "img": null, "choices": ["Enzymes join monomers without water", "Water is used to break the covalent bond between monomers, breaking a polymer apart", "Water is released as monomers are joined", "Heat is used to join monomers"], "answer": 1, "why": "Hydro = water; lysis = break. Water is a reactant."}, {"id": "seed-mcq-basics-q13", "stem": "What is an enzyme?", "img": null, "choices": ["A specialized protein that speeds up (catalyzes) chemical reactions", "A nucleic acid that stores genes", "A carbohydrate that gives structure", "A lipid that stores energy"], "answer": 0, "why": "Enzymes help maintain homeostasis and are needed for both dehydration synthesis and hydrolysis."}, {"id": "seed-mcq-basics-q14", "stem": "How many Calories per gram do the biomolecules provide?", "img": null, "choices": ["All four provide 4 Calories per gram", "Proteins 9, lipids 4, carbohydrates 4, nucleic acids 9", "Lipids 9, carbohydrates 4, proteins 4, nucleic acids are not used for energy", "Carbohydrates 9, lipids 4, proteins 4, nucleic acids 4"], "answer": 2, "why": "Lipids have the most energy per gram."}, {"id": "seed-mcq-basics-q15", "stem": "Which describes carbohydrates?", "img": null, "choices": ["Sugars made of C, H and O in a 1 : 2 : 1 ratio, often as ring structures", "Molecules containing phosphorus and nitrogenous bases", "Long hydrocarbon chains with very little oxygen", "Chains of amino acids containing sulfur"], "answer": 0, "why": "Example: glucose C₆H₁₂O₆."}, {"id": "seed-mcq-basics-q16", "stem": "Which molecule is a monosaccharide?", "img": "seed/img/bio-glucose-ring.svg", "choices": ["Glucose", "Cellulose", "Glycogen", "Starch"], "answer": 0, "why": "A monosaccharide is a single sugar: the carbohydrate monomer. The others are polysaccharides."}, {"id": "seed-mcq-basics-q17", "stem": "Which is a polysaccharide?", "img": null, "choices": ["Glucose", "Starch", "Fructose", "Sucrose"], "answer": 1, "why": "Starch, cellulose, glycogen and chitin are polysaccharides. Sucrose is a disaccharide."}, {"id": "seed-mcq-basics-q18", "stem": "Why are energy-storing carbohydrates branched?", "img": "seed/img/bio-polysaccharides.svg", "choices": ["Branches make them dissolve in lipids", "More branches mean more monomers can be broken off at once, so energy is released faster", "Branches keep enzymes from breaking them down", "Branches make them stack into strong walls"], "answer": 1, "why": "Glycogen and starch are branched for fast glucose release."}, {"id": "seed-mcq-basics-q19", "stem": "Why are structural carbohydrates linear?", "img": null, "choices": ["Linear chains can stack, giving stability for tough structures like cell walls and crab shells", "Linear chains dissolve more easily in water", "Linear chains contain nitrogen", "Linear chains release glucose faster"], "answer": 0, "why": "Cellulose (plant walls) and chitin (shells) are straight and stacked."}, {"id": "seed-mcq-basics-q20", "stem": "Which describes lipids?", "img": null, "choices": ["Fats or oils made of long hydrocarbon chains, with C, H and very little O", "Chains of nucleotides", "Sugars with a 1 : 2 : 1 ratio of C, H and O", "Chains of amino acids"], "answer": 0, "why": "Lipids are mostly C–H, which makes them hydrophobic."}, {"id": "seed-mcq-basics-q21", "stem": "What is the monomer (building block) of a lipid?", "img": "seed/img/pid-15.svg", "choices": ["Nucleotide", "Amino acid", "Monosaccharide", "Fatty acid"], "answer": 3, "why": "A fatty acid = a −COOH head + a long hydrocarbon tail."}, {"id": "seed-mcq-basics-q22", "stem": "Which lipid makes up the main part of the cell membrane?", "img": "seed/img/bio-phospholipid.svg", "choices": ["Phospholipid", "Steroid", "Wax", "Triglyceride"], "answer": 0, "why": "Phospholipids form the bilayer: heads out, tails in."}, {"id": "seed-mcq-basics-q23", "stem": "What does hydrophobic mean?", "img": null, "choices": ["Attracted to water", "Avoids water", "Made of water", "Dissolves in water"], "answer": 1, "why": "Lipids are hydrophobic because of their nonpolar C–H bonds."}, {"id": "seed-mcq-basics-q24", "stem": "Which describes a saturated fat?", "img": null, "choices": ["Made of glucose rings", "Contains nitrogen and sulfur", "Has C=C double bonds, kinked, liquid at room temperature", "No C=C double bonds, straight chains that stack, solid at room temperature"], "answer": 3, "why": "Saturated fats (like butter) can build up in blood vessels: the “bad fats”."}, {"id": "seed-mcq-basics-q25", "stem": "Which describes an unsaturated fat?", "img": null, "choices": ["Is a carbohydrate", "Has no double bonds and is solid", "Has C=C double bonds that kink the chains, so it is liquid at room temperature", "Contains phosphorus in every molecule"], "answer": 2, "why": "Unsaturated fats (oils) can’t stack and are less likely to clog arteries."}, {"id": "seed-mcq-basics-q26", "stem": "Which elements are in proteins?", "img": null, "choices": ["C, H, O, N and S (CHONS)", "C, H, O and P only", "C, H and O only", "C, H, O, N and P (CHONP)"], "answer": 0, "why": "The S comes from cysteine and methionine."}, {"id": "seed-mcq-basics-q27", "stem": "What is the monomer of a protein, and what bond joins them?", "img": "seed/img/bio-amino-acid.svg", "choices": ["Nucleotides, joined by phosphodiester bonds", "Fatty acids, joined by ester bonds", "Monosaccharides, joined by glycosidic linkages", "Amino acids, joined by peptide bonds"], "answer": 3, "why": "Amino acid = protein monomer."}, {"id": "seed-mcq-basics-q28", "stem": "What is the polymer of amino acids called?", "img": null, "choices": ["Polypeptide", "Triglyceride", "Polynucleotide", "Polysaccharide"], "answer": 0, "why": "A polypeptide folds into a protein."}, {"id": "seed-mcq-basics-q29", "stem": "What is the main function of nucleic acids?", "img": null, "choices": ["Speeding up chemical reactions", "Forming the cell membrane", "Long-term energy storage", "Storing genetic material (coding for traits)"], "answer": 3, "why": "Nucleic acids (DNA, RNA) are made of C, H, O, N and P."}, {"id": "seed-mcq-basics-q30", "stem": "What are the three parts of a nucleotide?", "img": "seed/img/bio-nucleotide.svg", "choices": ["A glycerol, a fatty acid, and a phosphate", "A 5-carbon sugar, a phosphate group, and a nitrogenous base", "Three glucose molecules", "An amino group, a carboxyl group, and an R group"], "answer": 1, "why": "The three parts are linked by covalent bonds."}, {"id": "seed-mcq-basics-q31", "stem": "What does it mean that DNA and RNA have directionality?", "img": "seed/img/bio-phosphodiester.svg", "choices": ["Each strand has a 5′ end (phosphate) and a 3′ end (−OH)", "DNA only moves toward the nucleus", "The bases point in random directions", "Each strand can only be read from the middle"], "answer": 0, "why": "The two DNA strands run in opposite directions (antiparallel)."}, {"id": "seed-mcq-basics-q32", "stem": "Which describes DNA?", "img": "seed/img/bio-dna.svg", "choices": ["A chain of amino acids folded into a helix", "Single-stranded, ribose sugar, bases A U C G", "A lipid that forms the nuclear membrane", "Double-stranded helix, deoxyribose sugar, bases A T C G, stores the genetic code"], "answer": 3, "why": "DNA is more stable than RNA and is found in the nucleus (eukaryotes)."}, {"id": "seed-mcq-basics-q33", "stem": "Which describes RNA?", "img": null, "choices": ["Single-stranded, ribose sugar, bases A U C G, used for protein synthesis", "Stored in the cell membrane", "Double-stranded, deoxyribose sugar, bases A T C G", "Contains sulfur instead of phosphorus"], "answer": 0, "why": "RNA has three types: mRNA, tRNA and rRNA. It’s made in the nucleus and moves to the cytoplasm."}, {"id": "seed-mcq-basics-q34", "stem": "Dehydration synthesis is a(n) ______ reaction that forms ______ bonds between monomers.", "img": null, "choices": ["anabolic; covalent", "catabolic; covalent", "catabolic; hydrogen", "anabolic; ionic"], "answer": 0, "why": "Water is formed as a byproduct."}, {"id": "seed-mcq-basics-q35", "stem": "Hydrolysis is a(n) ______ reaction in which water is used as a ______.", "img": null, "choices": ["catabolic; reactant", "anabolic; reactant", "catabolic; product", "anabolic; product"], "answer": 0, "why": "Hydrolysis breaks covalent bonds and releases energy."}, {"id": "seed-mcq-basics-q36", "stem": "Which statement about enzymes and biomolecule reactions is true?", "img": null, "choices": ["Neither reaction needs enzymes", "Only dehydration synthesis needs enzymes", "Both dehydration synthesis and hydrolysis need enzymes in living organisms", "Only hydrolysis needs enzymes"], "answer": 2, "why": "Enzymes make both reactions happen fast enough for life."}, {"id": "seed-mcq-basics-q37", "stem": "Complete the line from the biomolecules notes: “Monomers = amino acids / Polymers = ______”", "img": null, "choices": ["fatty acids", "polysaccharides", "nucleic acids", "polypeptides"], "answer": 3, "why": "Carbohydrates: monosaccharides → polysaccharides. Proteins: amino acids → polypeptides."}, {"id": "seed-mcq-basics-q38", "stem": "What is a functional group?", "img": null, "choices": ["An enzyme that joins monomers", "A chain of identical monomers", "A cluster of atoms attached to a carbon skeleton that gives a molecule its chemical behavior", "A group of cells that work together"], "answer": 2, "why": "The seven to know: hydroxyl, carbonyl, carboxyl, amino, sulfhydryl, phosphate, methyl."}, {"id": "seed-mcq-basics-q39", "stem": "Which functional group is shown?", "img": "seed/img/group-hydroxyl.svg", "choices": ["Sulfhydryl (−SH)", "Methyl (−CH₃)", "Hydroxyl (−OH)", "Carboxyl (−COOH)"], "answer": 2, "why": "Hydroxyl is polar and hydrophilic, found in every sugar."}, {"id": "seed-mcq-basics-q40", "stem": "Which functional group is shown?", "img": "seed/img/group-carbonyl.svg", "choices": ["Carbonyl (C=O)", "Phosphate (−OPO₃²⁻)", "Hydroxyl (−OH)", "Amino (−NH₂)"], "answer": 0, "why": "Carbonyl at the end = aldehyde; in the middle = ketone."}, {"id": "seed-mcq-basics-q41", "stem": "Which functional group is shown, and how does it behave?", "img": "seed/img/group-carboxyl.svg", "choices": ["Amino (−NH₂); basic, it picks up H⁺", "Hydroxyl (−OH); acidic", "Carbonyl (C=O); nonpolar", "Carboxyl (−COOH); acidic, it gives away H⁺"], "answer": 3, "why": "Carboxyl is on every amino acid and every fatty acid."}, {"id": "seed-mcq-basics-q42", "stem": "Which functional group is shown, and how does it behave?", "img": "seed/img/group-amino.svg", "choices": ["Sulfhydryl (−SH); forms disulfide bridges", "Methyl (−CH₃); nonpolar", "Carboxyl (−COOH); acidic", "Amino (−NH₂); basic, it picks up H⁺"], "answer": 3, "why": "Amino groups are on every amino acid and in nitrogenous bases."}, {"id": "seed-mcq-basics-q43", "stem": "Which functional group is shown?", "img": "seed/img/group-sulfhydryl.svg", "choices": ["Hydroxyl (−OH)", "Phosphate (−OPO₃²⁻)", "Sulfhydryl (−SH)", "Amino (−NH₂)"], "answer": 2, "why": "Two −SH groups form a disulfide bridge. Found in cysteine: the S in CHONS."}, {"id": "seed-mcq-basics-q44", "stem": "Which functional group is shown?", "img": "seed/img/group-phosphate.svg", "choices": ["Carbonyl (C=O)", "Phosphate (−OPO₃²⁻)", "Methyl (−CH₃)", "Carboxyl (−COOH)"], "answer": 1, "why": "Phosphate is in ATP, the DNA/RNA backbone and phospholipid heads: the P in CHONP."}, {"id": "seed-mcq-basics-q45", "stem": "Which functional group is shown, and what is special about it?", "img": "seed/img/group-methyl.svg", "choices": ["Hydroxyl (−OH); the only nonpolar group", "Methyl (−CH₃); the only nonpolar (hydrophobic) group", "Phosphate; the only uncharged group", "Amino (−NH₂); the only acidic group"], "answer": 1, "why": "C and H share electrons almost equally, so no partial charges."}, {"id": "seed-mcq-basics-q46", "stem": "What does hydrophilic mean, and which groups are hydrophilic?", "img": null, "choices": ["Avoids water; any group containing only C and H", "Avoids water; groups containing O", "Attracted to lipids; groups containing S", "Attracted to water; any group containing O, N or P"], "answer": 3, "why": "O, N and P are electronegative and create partial charges."}, {"id": "seed-mcq-basics-q47", "stem": "What is the FIRST question to ask when identifying a molecule from a picture?", "img": "seed/img/step2-all.png", "choices": ["How many carbons are there?", "Is there a ring?", "Is there a double bond?", "Is there a nitrogen (N)?"], "answer": 3, "why": "No N → carbohydrate or lipid. Has N → protein or nucleic acid."}, {"id": "seed-mcq-basics-q48", "stem": "A molecule HAS nitrogen. How do you tell whether it is a protein or a nucleic acid?", "img": null, "choices": ["Any ring → protein; no ring → nucleic acid", "More carbons → protein; fewer → nucleic acid", "A double bond → protein; no double bond → nucleic acid", "N inside a ring → nucleic acid; N in −NH₂ on a carbon that also has −COOH → amino acid"], "answer": 3, "why": "Where the N sits is the tell."}, {"id": "seed-mcq-basics-q49", "stem": "A molecule has NO nitrogen. How do you tell a carbohydrate from a lipid?", "img": null, "choices": ["Count carbons: more than 6 → lipid", "Count oxygens: about one O per carbon → carbohydrate; very few O with a long C–H chain → lipid", "Look for a ring: ring → lipid", "Look for P: P → carbohydrate"], "answer": 1, "why": "Carbohydrates are 1 : 2 : 1 CHO. Lipids are mostly C–H."}, {"id": "seed-mcq-basics-q50", "stem": "Which molecule class is shown?", "img": "seed/img/pid-1.svg", "choices": ["Protein", "Lipid", "Nucleic acid", "Carbohydrate"], "answer": 3, "why": "A ring with the O inside it and an −OH on nearly every carbon, and no N."}, {"id": "seed-mcq-basics-q51", "stem": "Which molecule class is shown?", "img": "seed/img/bio-triglyceride.svg", "choices": ["Lipid", "Protein", "Carbohydrate", "Nucleic acid"], "answer": 0, "why": "Glycerol + three long hydrocarbon tails = triglyceride. No N, very little O."}, {"id": "seed-mcq-basics-q52", "stem": "Which molecule class is shown?", "img": "seed/img/pid-28.svg", "choices": ["Lipid", "Protein", "Carbohydrate", "Nucleic acid"], "answer": 1, "why": "Central carbon with −NH₂, −COOH, H and R = amino acid. The N is not in a ring."}, {"id": "seed-mcq-basics-q53", "stem": "Which molecule class is shown?", "img": "seed/img/pid-47.svg", "choices": ["Protein", "Carbohydrate", "Lipid", "Nucleic acid"], "answer": 3, "why": "Phosphate + 5-ring sugar + a ring with N in it = nucleotide."}, {"id": "seed-mcq-basics-q54", "stem": "Which describes a purine vs a pyrimidine?", "img": "seed/img/bio-bases.svg", "choices": ["Both have 2 rings", "Purines contain sulfur; pyrimidines contain phosphorus", "Purine = 2 fused rings (A, G); pyrimidine = 1 ring (C, T, U)", "Purine = 1 ring (C, T, U); pyrimidine = 2 rings (A, G)"], "answer": 2, "why": "Memory trick: “Pure As Gold” and “CUT the Py”."}, {"id": "seed-mcq-basics-q55", "stem": "On a drawing, how do you tell a saturated fatty acid from an unsaturated one?", "img": "seed/img/bio-fatty-acids.svg", "choices": ["Saturated has a kink; unsaturated is straight", "Saturated is a straight zigzag with no C=C; unsaturated has a C=C that kinks the tail", "Saturated has more oxygens", "Unsaturated has a nitrogen"], "answer": 1, "why": "The kink is why unsaturated fats can’t stack."}, {"id": "seed-mcq-basics-q56", "stem": "In a skeletal formula, what does each corner or line end represent?", "img": null, "choices": ["A hydrogen atom", "A double bond", "A carbon atom (with enough H’s to make 4 bonds, not drawn)", "An oxygen atom"], "answer": 2, "why": "O, N, P and S are always written out. A double line is a double bond."}, {"id": "seed-mcq-basics-q57", "stem": "Which functional groups are polar?", "img": null, "choices": ["None of them", "All except methyl: hydroxyl, carbonyl, carboxyl, amino, sulfhydryl and phosphate", "Only methyl", "Only hydroxyl and carboxyl"], "answer": 1, "why": "Rule: contains O, N or P → polar. Only C and H → nonpolar."}, {"id": "seed-mcq-basics-q58", "stem": "Which group is the acid and which is the base?", "img": null, "choices": ["Phosphate is the base; sulfhydryl is the acid", "Carboxyl (−COOH) is the acid; amino (−NH₂) is the base", "Amino is the acid; carboxyl is the base", "Hydroxyl is the acid; methyl is the base"], "answer": 1, "why": "An amino acid has one of each, which is why it’s often drawn H₃N⁺ … COO⁻."}, {"id": "seed-mcq-basics-q59", "stem": "The monomer of a carbohydrate is a ______.", "img": null, "choices": ["polysaccharide", "nucleotide", "monosaccharide", "fatty acid"], "answer": 2, "why": "Example: glucose."}, {"id": "seed-mcq-basics-q60", "stem": "The polymer of a carbohydrate is a ______.", "img": null, "choices": ["polysaccharide", "triglyceride", "polypeptide", "monosaccharide"], "answer": 0, "why": "Examples: starch, cellulose, glycogen, chitin."}, {"id": "seed-mcq-basics-q61", "stem": "Carbohydrates always have a ______ ratio of C : H : O.", "img": null, "choices": ["2 : 1 : 2", "1 : 2 : very little", "1 : 2 : 1", "1 : 1 : 1"], "answer": 2, "why": "C₆H₁₂O₆ fits 1 : 2 : 1."}, {"id": "seed-mcq-basics-q62", "stem": "The monomer of a lipid is a ______.", "img": null, "choices": ["amino acid", "monosaccharide", "fatty acid", "nucleotide"], "answer": 2, "why": "Fatty acids attach to glycerol to make fats."}, {"id": "seed-mcq-basics-q63", "stem": "The monomer of a protein is an ______.", "img": null, "choices": ["enzyme", "fatty acid", "amino acid", "nucleotide"], "answer": 2, "why": "There are 20 amino acids."}, {"id": "seed-mcq-basics-q64", "stem": "The polymer of a protein is a ______.", "img": null, "choices": ["polynucleotide", "polypeptide", "polysaccharide", "phospholipid"], "answer": 1, "why": "A polypeptide folds into a functional protein."}, {"id": "seed-mcq-basics-q65", "stem": "Amino acids are joined together by ______ bonds.", "img": "seed/img/bio-dipeptide.svg", "choices": ["phosphodiester", "hydrogen", "peptide", "glycosidic"], "answer": 2, "why": "A peptide bond is C–N, made by dehydration synthesis."}, {"id": "seed-mcq-basics-q66", "stem": "The monomer of a nucleic acid is a ______.", "img": null, "choices": ["nucleotide", "nucleus", "amino acid", "fatty acid"], "answer": 0, "why": "Nucleotides join by phosphodiester bonds."}, {"id": "seed-mcq-basics-q67", "stem": "The three parts of a nucleotide are ______.", "img": null, "choices": ["a sugar, a fatty acid and a nitrogenous base", "a sugar, a phosphate and a nitrogenous base", "an amino group, a carboxyl group and an R group", "a glycerol, a phosphate and two fatty acids"], "answer": 1, "why": "Base + sugar + phosphate."}, {"id": "seed-mcq-basics-q68", "stem": "Proteins are made of the elements ______.", "img": null, "choices": ["CHONP", "CHO", "CHOP", "CHONS"], "answer": 3, "why": "S is the giveaway for proteins."}, {"id": "seed-mcq-basics-q69", "stem": "Nucleic acids are made of the elements ______.", "img": null, "choices": ["CHONP", "CHONS", "CHOS", "CHO"], "answer": 0, "why": "P is in the phosphate backbone."}, {"id": "seed-mcq-basics-q70", "stem": "The biomolecule with the most energy per gram is ______, at ______ Calories per gram.", "img": null, "choices": ["lipid; 9", "protein; 4", "lipid; 4", "carbohydrate; 9"], "answer": 0, "why": "Carbohydrates and proteins are 4 Cal/g."}, {"id": "seed-mcq-basics-q71", "stem": "The biomolecule that is NOT broken down for energy is ______.", "img": null, "choices": ["protein", "nucleic acid", "lipid", "carbohydrate"], "answer": 1, "why": "Nucleic acids store information, not fuel."}, {"id": "seed-mcq-basics-q72", "stem": "Energy-storing carbohydrates have a ______ structure.", "img": null, "choices": ["double-helix", "stacked", "linear", "branched"], "answer": 3, "why": "Branches = many ends to break off glucose."}, {"id": "seed-mcq-basics-q73", "stem": "Structural carbohydrates are ______ and able to ______.", "img": null, "choices": ["linear; stack", "branched; dissolve", "branched; stack", "linear; dissolve"], "answer": 0, "why": "Cellulose and chitin."}, {"id": "seed-mcq-basics-q74", "stem": "Saturated fats have ______ double bonds, so they are ______ at room temperature.", "img": null, "choices": ["no; solid", "one or more; liquid", "one or more; solid", "no; liquid"], "answer": 0, "why": "Straight chains stack."}, {"id": "seed-mcq-basics-q75", "stem": "Unsaturated fats have ______ double bonds, so they are ______ at room temperature.", "img": null, "choices": ["one or more; solid", "no; liquid", "one or more; liquid", "no; solid"], "answer": 2, "why": "Kinks stop stacking."}, {"id": "seed-mcq-basics-q76", "stem": "______ are the special lipids that make up the main part of the cell membrane.", "img": null, "choices": ["Steroids", "Fatty acids", "Triglycerides", "Phospholipids"], "answer": 3, "why": "They form the bilayer."}, {"id": "seed-mcq-basics-q77", "stem": "Steroids are lipids built from ______.", "img": "seed/img/bio-steroid.svg", "choices": ["a phosphate head and two tails", "glycerol and three fatty acids", "four fused carbon rings", "chains of glucose"], "answer": 2, "why": "Examples: cholesterol, testosterone, estrogen."}, {"id": "seed-mcq-basics-q78", "stem": "Lipids are ______, meaning they avoid water.", "img": null, "choices": ["hydrophilic", "ionic", "hydrophobic", "polar"], "answer": 2, "why": "Nonpolar C–H chains."}, {"id": "seed-mcq-basics-q79", "stem": "______ are specialized proteins that speed up chemical reactions.", "img": null, "choices": ["Enzymes", "Lipids", "Monosaccharides", "Nucleotides"], "answer": 0, "why": "Enzymes catalyze reactions."}, {"id": "seed-mcq-basics-q80", "stem": "Protein structure has ______ levels.", "img": "seed/img/bio-protein-levels.svg", "choices": ["two (primary and secondary)", "four (primary, secondary, tertiary, quaternary)", "three (primary, secondary, tertiary)", "one (the amino acid sequence)"], "answer": 1, "why": "Quaternary only when there are 2+ chains."}, {"id": "seed-mcq-basics-q81", "stem": "The only NONPOLAR functional group is ______.", "img": null, "choices": ["methyl (−CH₃)", "amino (−NH₂)", "hydroxyl (−OH)", "carboxyl (−COOH)"], "answer": 0, "why": "Only C and H."}, {"id": "seed-mcq-basics-q82", "stem": "−COOH is the ______ group, and it acts as an ______.", "img": null, "choices": ["carbonyl; acid", "hydroxyl; acid", "carboxyl; acid", "carboxyl; base"], "answer": 2, "why": "It donates H⁺."}, {"id": "seed-mcq-basics-q83", "stem": "−NH₂ is the ______ group, and it acts as a ______.", "img": null, "choices": ["amino; base", "amino; acid", "methyl; base", "ammonia; base"], "answer": 0, "why": "It accepts H⁺."}, {"id": "seed-mcq-basics-q84", "stem": "Two −SH groups can join to form a ______.", "img": null, "choices": ["glycosidic linkage", "peptide bond", "disulfide bridge", "hydrogen bond"], "answer": 2, "why": "A covalent S–S bond in proteins."}, {"id": "seed-mcq-basics-q85", "stem": "A C=O at the END of a chain is an ______; in the MIDDLE it is a ______.", "img": "seed/img/bio-linear-sugars.svg", "choices": ["alcohol; ketone", "aldehyde; alcohol", "ketone; aldehyde", "aldehyde; ketone"], "answer": 3, "why": "Glucose = aldehyde sugar, fructose = ketone sugar."}, {"id": "seed-mcq-basics-q86", "stem": "______ builds polymers and RELEASES water.", "img": null, "choices": ["Diffusion", "Hydrolysis", "Dehydration synthesis", "Denaturation"], "answer": 2, "why": "Also called a condensation reaction."}, {"id": "seed-mcq-basics-q87", "stem": "______ breaks polymers apart and REQUIRES water.", "img": null, "choices": ["Hydrolysis", "Condensation", "Photosynthesis", "Dehydration synthesis"], "answer": 0, "why": "Hydro = water, lysis = break."}, {"id": "seed-mcq-basics-q88", "stem": "Dehydration synthesis is ______ and ______.", "img": null, "choices": ["anabolic; endergonic", "anabolic; exergonic", "catabolic; endergonic", "catabolic; exergonic"], "answer": 0, "why": "Builds up and needs energy."}, {"id": "seed-mcq-basics-q89", "stem": "Hydrolysis is ______ and ______.", "img": null, "choices": ["catabolic; exergonic", "anabolic; endergonic", "anabolic; exergonic", "catabolic; endergonic"], "answer": 0, "why": "Breaks down and releases energy."}, {"id": "seed-mcq-basics-q90", "stem": "Both dehydration synthesis and hydrolysis require ______.", "img": null, "choices": ["phosphorus", "lipids", "enzymes", "sunlight"], "answer": 2, "why": "Enzymes catalyze both."}]}, {"id": "seed-apes-u1", "rev": 1, "title": "APES Unit 1 — Ecosystems", "folder": "APES", "description": "From your Quizlet export, with the cycle and ecology diagrams attached.", "cards": [{"id": "seed-apes-u1-0", "term": "Environmental science", "def": "The interdisciplinary study of the Earth's life support systems and human activities that threaten those systems"}, {"id": "seed-apes-u1-1", "term": "Life support systems (supporting services)", "def": "Nutrient cycling, evolution, soil formation, spatial structure, and primary productivity"}, {"id": "seed-apes-u1-2", "term": "Provisioning services", "def": "Ecosystem services that provide food, water, fuel wood, fiber, biochemicals, and genetic diversity"}, {"id": "seed-apes-u1-3", "term": "Regulating services", "def": "Ecosystem services that provide climate regulation, disease regulation, water regulation, water purification, and pollination"}, {"id": "seed-apes-u1-4", "term": "Cultural services", "def": "Ecosystem services that provide spiritual/religious value, recreation, ecotourism, aesthetic, inspirational, educational, sense of place, and cultural heritage"}, {"id": "seed-apes-u1-5", "term": "Spatial ecology", "def": "The study of spatial structure; combines ecology and geography to identify spatial patterns in the environment and their relationships to ecological phenomena"}, {"id": "seed-apes-u1-6", "term": "USGS LandCarbon Project", "def": "Assesses an ecosystem's capacity to increase carbon stocks and reduce greenhouse gas fluxes by examining changes in land use/land cover and land management practices"}, {"id": "seed-apes-u1-7", "term": "Ecology", "def": "From the Greek \"oikos\" meaning house; the study of houses"}, {"id": "seed-apes-u1-8", "term": "Population", "def": "All the organisms of the same species in a given area"}, {"id": "seed-apes-u1-9", "term": "Community", "def": "All the species populations in a given area"}, {"id": "seed-apes-u1-10", "term": "Ecosystem", "def": "All the living (biotic) and nonliving (abiotic) elements found within a given area and their interactions with each other"}, {"id": "seed-apes-u1-11", "term": "\"Nutrients cycle\" means", "def": "The Earth is a closed system for matter"}, {"id": "seed-apes-u1-12", "term": "\"Energy flows\" means", "def": "The Earth is an open system for energy"}, {"id": "seed-apes-u1-13", "term": "Watersheds", "def": "Logical units of study because all of the biotic and abiotic components of a watershed are linked together by topography"}, {"id": "seed-apes-u1-14", "term": "Biome", "def": "A large geographic area with similar climatic conditions (temperature and rainfall); example: desert", "defImg": "seed/img/biomes.jpg"}, {"id": "seed-apes-u1-15", "term": "Biosphere", "def": "The portion of the Earth that supports life"}, {"id": "seed-apes-u1-16", "term": "Habitat", "def": "An organism's \"address\"; the biotic and abiotic conditions necessary for a species to survive"}, {"id": "seed-apes-u1-17", "term": "Range of tolerance", "def": "The range of a specific physical factor under which an organism can survive (e.g., water temperature, pH)", "defImg": "seed/img/range-of-tolerance.jpg"}, {"id": "seed-apes-u1-18", "term": "Niche", "def": "An organism's occupation or way of making a living; an organism's overall role in an ecosystem"}, {"id": "seed-apes-u1-19", "term": "Generalist", "def": "A species with a broad niche; example: raccoons, which will eat just about anything"}, {"id": "seed-apes-u1-20", "term": "Specialist", "def": "A species with a narrow niche that can go extinct easily; example: koalas, which only eat eucalyptus"}, {"id": "seed-apes-u1-21", "term": "Autotrophs", "def": "Organisms that make their own food; plants (terrestrial) and algae (aquatic) use photosynthesis, while primitive bacteria use chemosynthesis"}, {"id": "seed-apes-u1-22", "term": "Heterotrophs", "def": "Organisms that consume other organisms; includes herbivores, carnivores, omnivores, and scavengers"}, {"id": "seed-apes-u1-23", "term": "Herbivores", "def": "Animals that eat plants"}, {"id": "seed-apes-u1-24", "term": "Carnivores", "def": "Animals that eat other animals"}, {"id": "seed-apes-u1-25", "term": "Omnivores", "def": "Animals that eat both plants and animals"}, {"id": "seed-apes-u1-26", "term": "Scavengers", "def": "Animals that eat dead animals; example: vultures"}, {"id": "seed-apes-u1-27", "term": "Decomposers", "def": "Organisms that consume dead material and return nutrients to the soil"}, {"id": "seed-apes-u1-28", "term": "Detritivores", "def": "Decomposers that eat nonliving organic matter; example: earthworms"}, {"id": "seed-apes-u1-29", "term": "Saprotrophs", "def": "Decomposers that chemically absorb nonliving organic matter; examples: fungus, bacteria"}, {"id": "seed-apes-u1-30", "term": "Indicator species", "def": "A species with a narrow range of tolerance for important biotic and abiotic factors; when it is not healthy, it indicates the entire ecosystem may not be healthy; examples: Northern Spotted Owl (NW old growth forests), Orca (Puget Sound)"}, {"id": "seed-apes-u1-31", "term": "Keystone species", "def": "A species whose niche contributes to many other species within an ecosystem (\"ecosystem engineers\"); when its population declines, it impacts the entire ecosystem; examples: wolf, beaver, salmon"}, {"id": "seed-apes-u1-32", "term": "Yellowstone wolves case study", "def": "Last wolf killed in 1926; without wolves, elk increased, willows were destroyed, and beaver and trout declined; 29 wolves reintroduced in 1995; by 2012 there were 10 packs totaling 83 wolves; elk went down while willows, beaver, and trout recovered"}, {"id": "seed-apes-u1-33", "term": "Food chain", "def": "A series of organisms in an ecosystem related by their feeding patterns", "defImg": "seed/img/food-chain-food-web.jpg"}, {"id": "seed-apes-u1-34", "term": "Food web", "def": "A series of multiple, overlapping food chains", "defImg": "seed/img/food-chain-food-web.jpg"}, {"id": "seed-apes-u1-35", "term": "Producers (autotrophs)", "def": "Organisms that get all their energy from the sun; example: grass"}, {"id": "seed-apes-u1-36", "term": "Primary consumers", "def": "Herbivores that consume plants; example: insects"}, {"id": "seed-apes-u1-37", "term": "Secondary consumers", "def": "Animals that consume primary consumers; example: mice"}, {"id": "seed-apes-u1-38", "term": "Tertiary consumers", "def": "Secondary carnivores that consume secondary consumers; example: hawks"}, {"id": "seed-apes-u1-39", "term": "90-10 Rule", "def": "90% of energy is lost at every trophic level to heat and waste; only 10% becomes biomass in the next trophic level", "defImg": "seed/img/90-10-rule.jpg"}, {"id": "seed-apes-u1-40", "term": "Energy pyramid characteristics", "def": "All pyramids (number of organisms, energy, and biomass) look the same, decreasing at each trophic level", "defImg": "seed/img/energy-pyramid.jpg"}, {"id": "seed-apes-u1-41", "term": "Eating lower on the food chain", "def": "Eating vegetarian makes 10x as much plant energy available for other humans"}, {"id": "seed-apes-u1-42", "term": "Productivity", "def": "A measure of how much photosynthesis is taking place within a given area", "defImg": "seed/img/net-primary-productivity.jpg"}, {"id": "seed-apes-u1-43", "term": "Gross primary productivity (GPP)", "def": "The total amount of solar energy captured (CO2 incorporated into C6H12O6)", "defImg": "seed/img/net-primary-productivity.jpg"}, {"id": "seed-apes-u1-44", "term": "Net primary productivity (NPP)", "def": "Gross productivity minus (waste + heat)", "defImg": "seed/img/net-primary-productivity.jpg"}, {"id": "seed-apes-u1-45", "term": "Predation", "def": "When one animal kills and eats another; predators benefit by acquiring food, and prey benefit from the \"culling of the herd\" (weakest members killed)"}, {"id": "seed-apes-u1-46", "term": "Competition", "def": "When two organisms strive for the same limited resource"}, {"id": "seed-apes-u1-47", "term": "Intraspecies competition", "def": "Competition between members of the same species"}, {"id": "seed-apes-u1-48", "term": "Interspecies competition", "def": "Competition between members of different species"}, {"id": "seed-apes-u1-49", "term": "Competitive exclusion principle", "def": "No two species can occupy the same niche in the same place at the same time; example: European starlings introduced in Central Park in 1890 crowded out native species"}, {"id": "seed-apes-u1-50", "term": "Symbiosis", "def": "A close, long-term relationship between two species in which at least one species benefits", "defImg": "seed/img/symbiotic-relationships.jpg"}, {"id": "seed-apes-u1-51", "term": "Parasitism", "def": "One organism (parasite) lives in or on another organism (host), from which it derives nourishment", "defImg": "seed/img/symbiotic-relationships.jpg"}, {"id": "seed-apes-u1-52", "term": "Ectoparasites", "def": "Parasites that live on the host's surface; examples: fleas, lice, molds, mildews"}, {"id": "seed-apes-u1-53", "term": "Endoparasites", "def": "Parasites that live inside the body of the host; examples: tapeworms, malaria parasites, bacteria, fungi"}, {"id": "seed-apes-u1-54", "term": "Commensalism", "def": "Symbiosis in which one organism benefits while the other is not affected; example: remoras and sharks", "defImg": "seed/img/symbiotic-relationships.jpg"}, {"id": "seed-apes-u1-55", "term": "Mutualism", "def": "Symbiosis in which both species benefit; the relationship is often obligatory (neither can exist without the other); examples: bats and cacti, ants and the Acacia plant", "defImg": "seed/img/symbiotic-relationships.jpg"}, {"id": "seed-apes-u1-56", "term": "Why humans have to hunt", "def": "Humans remove top carnivores, so herbivores overgraze plants, affecting many biotic and abiotic components; we become responsible for culling the herbivores; the problem is hunters take trophies while carnivores take the sick and weak"}, {"id": "seed-apes-u1-57", "term": "Water cycle steps", "def": "Water falls as precipitation; some runs off to oceans; some infiltrates into the ground and collects as groundwater in an aquifer; ocean water evaporates and is purified; plants release water via transpiration; ice converts directly to vapor via sublimation", "defImg": "seed/img/water-cycle-1.jpg"}, {"id": "seed-apes-u1-58", "term": "Transpiration", "def": "Water that evaporates from plants", "defImg": "seed/img/water-cycle-1.jpg"}, {"id": "seed-apes-u1-59", "term": "Sublimation", "def": "Water that goes straight from ice to vapor", "defImg": "seed/img/water-cycle-1.jpg"}, {"id": "seed-apes-u1-60", "term": "Human impacts on the water cycle", "def": "Global warming increases evaporation and precipitation; urbanization removes vegetation and increases pavement (less infiltration, more runoff); clearcuts increase runoff and erosion and may promote landslides", "defImg": "seed/img/water-cycle-2.jpg"}, {"id": "seed-apes-u1-61", "term": "Nitrogen in the atmosphere", "def": "N2 comprises 78% of the atmosphere; it is the most important nutrient for plants and must be converted to water-soluble nitrate (NO3) before plants can absorb it", "defImg": "seed/img/nitrogen-cycle-1.jpg"}, {"id": "seed-apes-u1-62", "term": "Nitrogen fixation", "def": "N2 → NH4 (ammonium)", "defImg": "seed/img/nitrogen-cycle-1.jpg"}, {"id": "seed-apes-u1-63", "term": "Nitrification", "def": "NH4 → NO2 (nitrite) → NO3 (nitrate)", "defImg": "seed/img/nitrogen-cycle-1.jpg"}, {"id": "seed-apes-u1-64", "term": "Assimilation (nitrogen cycle)", "def": "NO3 → NH2 (amino acids)", "defImg": "seed/img/nitrogen-cycle-1.jpg"}, {"id": "seed-apes-u1-65", "term": "Mineralization", "def": "NH2 → NH3 (ammonia)", "defImg": "seed/img/nitrogen-cycle-1.jpg"}, {"id": "seed-apes-u1-66", "term": "Denitrification", "def": "NO3 → N2 (atmospheric nitrogen)", "defImg": "seed/img/nitrogen-cycle-1.jpg"}, {"id": "seed-apes-u1-67", "term": "Human impacts on the nitrogen cycle", "def": "Human activity has doubled fixed nitrogen over pre-industrial levels; NOx break down stratospheric ozone (letting in UV), become smog (PAN and O3) in sunlight, and form acid rain; nitrates contaminate drinking water causing \"blue baby\" syndrome; nitrogen with phosphorous causes eutrophication/algal blooms that reduce O2 in water", "defImg": "seed/img/nitrogen-cycle-2.jpg"}, {"id": "seed-apes-u1-68", "term": "Fritz Haber", "def": "German chemist known as the \"father of chemical warfare\" for weaponizing chlorine; invented the Haber process for converting nitrogen and hydrogen gases into ammonia; won the Nobel Prize in Chemistry in 1918"}, {"id": "seed-apes-u1-69", "term": "Friedrich Wilhelm Ostwald", "def": "Russian chemist who worked in Germany; developed the Ostwald process for making nitric acid; won the Nobel Prize in Chemistry in 1909"}, {"id": "seed-apes-u1-70", "term": "Carbon-oxygen cycle", "def": "A symbiotic relationship between plants and animals in which plants absorb CO2 and release O2, while animals absorb O2 and release CO2", "defImg": "seed/img/carbon-cycle.jpg"}, {"id": "seed-apes-u1-71", "term": "Most productive ecosystems", "def": "Swamps and marshes are the most productive ecosystems on Earth, coral reefs are second; the rainforest is the biggest scrubber of CO2 (sequestered in tree trunks)"}, {"id": "seed-apes-u1-72", "term": "How carbon is stored", "def": "Plants (land) or algae (sea) absorb CO2 from the atmosphere, die, and are buried; buried plants and algae become coal, oil, methane (CH4), and calcium carbonate (CaCO3)", "defImg": "seed/img/carbon-cycle.jpg"}, {"id": "seed-apes-u1-73", "term": "How carbon is released", "def": "Burning fossil fuels and making cement", "defImg": "seed/img/carbon-cycle.jpg"}, {"id": "seed-apes-u1-74", "term": "Photosynthesis equation", "def": "6CO2 + 6H2O → C6H12O6 + 6O2"}, {"id": "seed-apes-u1-75", "term": "Respiration equation", "def": "6O2 + C6H12O6 → 6CO2 + 6H2O"}, {"id": "seed-apes-u1-76", "term": "Human impacts on the carbon cycle", "def": "Burning fossil fuels increases atmospheric CO2 and global climate change; cutting down and burning rainforest adds CO2 and removes an important carbon sink (tree trunks); making cement releases CO2 from CaCO3", "defImg": "seed/img/carbon-cycle.jpg"}, {"id": "seed-apes-u1-77", "term": "Cement and CO2", "def": "Cement production accounts for around 5% of global CO2 emissions; concrete is the second most consumed substance on Earth after water; the average person \"consumes\" 3 tons of concrete per year"}, {"id": "seed-apes-u1-78", "term": "Phosphorous cycle", "def": "The only cycle without an atmospheric component; phosphorous is mined from deposits in the ground, used in fertilizers and detergents, taken up by plants and algae, then released by decomposition into ocean sediments which become rock", "defImg": "seed/img/phosphorus-cycle.jpg"}, {"id": "seed-apes-u1-79", "term": "Human impacts on the phosphorous cycle", "def": "Fertilizer and detergent get into bodies of water where P (along with N) is the limiting nutrient for algae growth, triggering eutrophication", "defImg": "seed/img/phosphorus-cycle.jpg"}, {"id": "seed-apes-u1-80", "term": "Eutrophication", "def": "Along with phosphorous, nitrogen causes \"algal blooms,\" which ultimately reduce O2 in water"}, {"id": "seed-apes-u1-81", "term": "Carbon's main nonliving storehouse", "def": "Sedimentary: carbon-containing minerals in rocks; also dissolved carbonate (CO3) and bicarbonate (HCO3) in water and atmospheric CO2; found in living organisms as carbohydrates and all other organic molecules"}, {"id": "seed-apes-u1-82", "term": "Nitrogen's main nonliving storehouse", "def": "Atmospheric: nitrogen gas (N2); also dissolved ammonium (NH4), nitrate (NO3), and nitrite (NO2) in water; found in living organisms as proteins and other nitrogen-containing organic molecules"}, {"id": "seed-apes-u1-83", "term": "Phosphorous's main nonliving storehouse", "def": "Sedimentary: minerals and rocks containing phosphate (PO4); also dissolved phosphate in water; found in living organisms as DNA, other nucleic acids, and phospholipids"}, {"id": "seed-apes-u1-84", "term": "Sulfur's main nonliving storehouse", "def": "Sedimentary: minerals and rocks containing sulfate (SO4); also atmospheric H2S, SO2, SO3, and H2SO4 and hydrologic sulfate and sulfuric acid; found in living organisms as sulfur-containing amino acids in most proteins and some vitamins", "defImg": "seed/img/sulfur-cycle.jpg"}, {"id": "seed-apes-u1-85", "term": "Origin of biodiversity", "def": "Within any ecosystem there are many habitats, and within each habitat there are many niches; biodiversity results from organisms evolving to fill the many niches"}, {"id": "seed-apes-u1-86", "term": "Coevolution", "def": "The notion that whole ecosystems evolve together cooperatively to provide the greatest diversity, efficiency, and stability to ecosystems"}, {"id": "seed-apes-u1-87", "term": "Ecosystem stability", "def": "Ecosystems are most stable and best able to recover after disturbance when there are a wide variety of species occupying diverse niches; this usually describes mature ecosystems"}, {"id": "seed-apes-u1-88", "term": "Natural selection: 5 key ideas", "def": "1) There is a lot of genetic variation within any species; 2) species have the capacity to overproduce; 3) only the best adapted individual organisms survive; 4) the best adapted individuals pass their genes on to their offspring; 5) over time, species become better adapted to their environments"}, {"id": "seed-apes-u1-89", "term": "Adaptation to environmental change", "def": "If environments change slowly, organisms can adapt through migration or natural selection; rapid change, like global climate change, can have catastrophic results"}, {"id": "seed-apes-u1-90", "term": "Peppered moths and the Industrial Revolution", "def": "In 1840 white moths were more common than black moths because the trees were white; from 1840-1890 air pollution darkened the bark of the trees; by 1890 black moths were more common than white"}, {"id": "seed-apes-u1-91", "term": "DDT and mosquitoes", "def": "DDT kills 99.9% of mosquitoes, but genetically resistant mosquitoes survive; over time DDT no longer works because mosquitoes have evolved resistance"}]}, {"id": "seed-apes-review", "rev": 1, "title": "APES Unit 1 — Review Questions", "folder": "APES", "description": "", "cards": [{"id": "seed-apes-review-0", "term": "Environmental science", "def": "The interdisciplinary study of the Earth's life support systems and human activities that threaten those systems"}, {"id": "seed-apes-review-1", "term": "Life support systems (supporting services)", "def": "Nutrient cycling, evolution, soil formation, spatial structure, and primary productivity"}, {"id": "seed-apes-review-2", "term": "Provisioning services", "def": "Ecosystem services that provide food, water, fuel wood, fiber, biochemicals, and genetic diversity"}, {"id": "seed-apes-review-3", "term": "Regulating services", "def": "Ecosystem services that provide climate regulation, disease regulation, water regulation, water purification, and pollination"}, {"id": "seed-apes-review-4", "term": "Cultural services", "def": "Ecosystem services that provide spiritual/religious value, recreation, ecotourism, aesthetic, inspirational, educational, sense of place, and cultural heritage"}, {"id": "seed-apes-review-5", "term": "Ecology", "def": "From the Greek \"oikos\" meaning house; the study of houses"}, {"id": "seed-apes-review-6", "term": "Population", "def": "All the organisms of the same species in a given area"}, {"id": "seed-apes-review-7", "term": "Community", "def": "All the species populations in a given area"}, {"id": "seed-apes-review-8", "term": "Ecosystem", "def": "All the living (biotic) and nonliving (abiotic) elements found within a given area and their interactions with each other"}, {"id": "seed-apes-review-9", "term": "Biome", "def": "A large geographic area with similar climatic conditions (temperature and rainfall); example: desert"}, {"id": "seed-apes-review-10", "term": "Biosphere", "def": "The portion of the Earth that supports life"}, {"id": "seed-apes-review-11", "term": "Habitat", "def": "An organism's \"address\"; the biotic and abiotic conditions necessary for a species to survive"}, {"id": "seed-apes-review-12", "term": "Niche", "def": "An organism's occupation or way of making a living; an organism's overall role in an ecosystem"}, {"id": "seed-apes-review-13", "term": "Generalist", "def": "A species with a broad niche; example: raccoons, which will eat just about anything"}, {"id": "seed-apes-review-14", "term": "Specialist", "def": "A species with a narrow niche that can go extinct easily; example: koalas, which only eat eucalyptus"}, {"id": "seed-apes-review-15", "term": "Autotrophs", "def": "Organisms that make their own food; plants (terrestrial) and algae (aquatic) use photosynthesis, while primitive bacteria use chemosynthesis"}, {"id": "seed-apes-review-16", "term": "Heterotrophs", "def": "Organisms that consume other organisms; includes herbivores, carnivores, omnivores, and scavengers"}, {"id": "seed-apes-review-17", "term": "Herbivores", "def": "Animals that eat plants"}, {"id": "seed-apes-review-18", "term": "Carnivores", "def": "Animals that eat other animals"}, {"id": "seed-apes-review-19", "term": "Omnivores", "def": "Animals that eat both plants and animals"}, {"id": "seed-apes-review-20", "term": "Detritivores", "def": "Decomposers that eat nonliving organic matter; example: earthworms"}, {"id": "seed-apes-review-21", "term": "Saprotrophs", "def": "Decomposers that chemically absorb nonliving organic matter; examples: fungus, bacteria"}, {"id": "seed-apes-review-22", "term": "Indicator species", "def": "A species with a narrow range of tolerance for important biotic and abiotic factors; when it is not healthy, it indicates the entire ecosystem may not be healthy; examples: Northern Spotted Owl (NW old growth forests), Orca (Puget Sound)"}, {"id": "seed-apes-review-23", "term": "Keystone species", "def": "A species whose niche contributes to many other species within an ecosystem (\"ecosystem engineers\"); when its population declines, it impacts the entire ecosystem; examples: wolf, beaver, salmon"}, {"id": "seed-apes-review-24", "term": "Yellowstone wolves case study", "def": "Last wolf killed in 1926; without wolves, elk increased, willows were destroyed, and beaver and trout declined; 29 wolves reintroduced in 1995; by 2012 there were 10 packs totaling 83 wolves; elk went down while willows, beaver, and trout recovered"}, {"id": "seed-apes-review-25", "term": "Food chain", "def": "A series of organisms in an ecosystem related by their feeding patterns"}, {"id": "seed-apes-review-26", "term": "Food web", "def": "A series of multiple, overlapping food chains"}, {"id": "seed-apes-review-27", "term": "90-10 Rule", "def": "90% of energy is lost at every trophic level to heat and waste; only 10% becomes biomass in the next trophic level"}, {"id": "seed-apes-review-28", "term": "Energy pyramid characteristics", "def": "All three pyramids (number of organisms, energy, and biomass) look the same, narrowing at every trophic level. They match because of the 90-10 rule: only 10% of the energy passes up each level, so each level can support less biomass and therefore fewer organisms than the one below it"}, {"id": "seed-apes-review-29", "term": "Eating lower on the food chain", "def": "Eating vegetarian makes 10x as much plant energy available for other humans"}, {"id": "seed-apes-review-30", "term": "Gross primary productivity (GPP)", "def": "The total amount of solar energy captured (CO2 incorporated into C6H12O6)"}, {"id": "seed-apes-review-31", "term": "Net primary productivity (NPP)", "def": "Gross productivity minus (waste + heat)"}, {"id": "seed-apes-review-32", "term": "Predation", "def": "When one animal kills and eats another; predators benefit by acquiring food, and prey benefit from the \"culling of the herd\" (weakest members killed)"}, {"id": "seed-apes-review-33", "term": "Intraspecies competition", "def": "Competition between members of the same species"}, {"id": "seed-apes-review-34", "term": "Interspecies competition", "def": "Competition between members of different species"}, {"id": "seed-apes-review-35", "term": "Competitive exclusion principle", "def": "No two species can occupy the same niche in the same place at the same time; example: European starlings introduced in Central Park in 1890 crowded out native species"}, {"id": "seed-apes-review-36", "term": "Symbiosis", "def": "A close, long-term relationship between two species in which at least one species benefits"}, {"id": "seed-apes-review-37", "term": "Ectoparasites", "def": "Parasites that live on the host's surface; examples: fleas, lice, molds, mildews"}, {"id": "seed-apes-review-38", "term": "Endoparasites", "def": "Parasites that live inside the body of the host; examples: tapeworms, malaria parasites, bacteria, fungi"}, {"id": "seed-apes-review-39", "term": "Commensalism", "def": "Symbiosis in which one organism benefits while the other is not affected; example: remoras and sharks"}, {"id": "seed-apes-review-40", "term": "Mutualism", "def": "Symbiosis in which both species benefit; the relationship is often obligatory (neither can exist without the other); examples: bats and cacti, ants and the Acacia plant"}, {"id": "seed-apes-review-41", "term": "Water cycle steps", "def": "Water falls as precipitation; some runs off to oceans; some infiltrates into the ground and collects as groundwater in an aquifer; ocean water evaporates and is purified; plants release water via transpiration; ice converts directly to vapor via sublimation"}, {"id": "seed-apes-review-42", "term": "Transpiration", "def": "Water that evaporates from plants"}, {"id": "seed-apes-review-43", "term": "Sublimation", "def": "Water that goes straight from ice to vapor"}, {"id": "seed-apes-review-44", "term": "Human impacts on the water cycle", "def": "Global warming increases evaporation and precipitation; urbanization removes vegetation and increases pavement (less infiltration, more runoff); clearcuts increase runoff and erosion and may promote landslides"}, {"id": "seed-apes-review-45", "term": "Nitrogen in the atmosphere", "def": "N2 comprises 78% of the atmosphere; it is the most important nutrient for plants and must be converted to water-soluble nitrate (NO3) before plants can absorb it"}, {"id": "seed-apes-review-46", "term": "Nitrogen fixation", "def": "N2 → NH4 (ammonium)"}, {"id": "seed-apes-review-47", "term": "Nitrification", "def": "NH4 → NO2 (nitrite) → NO3 (nitrate)"}, {"id": "seed-apes-review-48", "term": "Assimilation (nitrogen cycle)", "def": "NO3 → NH2 (amino acids)"}, {"id": "seed-apes-review-49", "term": "Mineralization", "def": "NH2 → NH3 (ammonia)"}, {"id": "seed-apes-review-50", "term": "Denitrification", "def": "NO3 → N2 (atmospheric nitrogen)"}, {"id": "seed-apes-review-51", "term": "Human impacts on the nitrogen cycle", "def": "Human activity has doubled fixed nitrogen over pre-industrial levels; NOx break down stratospheric ozone (letting in UV), become smog (PAN and O3) in sunlight, and form acid rain; nitrates contaminate drinking water causing \"blue baby\" syndrome; nitrogen with phosphorous causes eutrophication/algal blooms that reduce O2 in water"}, {"id": "seed-apes-review-52", "term": "Carbon-oxygen cycle", "def": "A symbiotic relationship between plants and animals in which plants absorb CO2 and release O2, while animals absorb O2 and release CO2"}, {"id": "seed-apes-review-53", "term": "How carbon is stored", "def": "Plants (land) or algae (sea) absorb CO2 from the atmosphere, die, and are buried; buried plants and algae become coal, oil, methane (CH4), and calcium carbonate (CaCO3)"}, {"id": "seed-apes-review-54", "term": "How carbon is released", "def": "Burning fossil fuels and making cement"}, {"id": "seed-apes-review-55", "term": "Photosynthesis equation", "def": "6CO2 + 6H2O → C6H12O6 + 6O2"}, {"id": "seed-apes-review-56", "term": "Respiration equation", "def": "6O2 + C6H12O6 → 6CO2 + 6H2O"}, {"id": "seed-apes-review-57", "term": "Human impacts on the carbon cycle", "def": "Burning fossil fuels increases atmospheric CO2 and global climate change; cutting down and burning rainforest adds CO2 and removes an important carbon sink (tree trunks); making cement releases CO2 from CaCO3"}, {"id": "seed-apes-review-58", "term": "Phosphorous cycle", "def": "The only cycle without an atmospheric component; phosphorous is mined from deposits in the ground, used in fertilizers and detergents, taken up by plants and algae, then released by decomposition into ocean sediments which become rock"}, {"id": "seed-apes-review-59", "term": "Human impacts on the phosphorous cycle", "def": "Fertilizer and detergent get into bodies of water where P (along with N) is the limiting nutrient for algae growth, triggering eutrophication"}, {"id": "seed-apes-review-60", "term": "Eutrophication", "def": "Along with phosphorous, nitrogen causes \"algal blooms,\" which ultimately reduce O2 in water"}, {"id": "seed-apes-review-61", "term": "Origin of biodiversity", "def": "Within any ecosystem there are many habitats, and within each habitat there are many niches; biodiversity results from organisms evolving to fill the many niches"}, {"id": "seed-apes-review-62", "term": "Natural selection: 5 key ideas", "def": "1) There is a lot of genetic variation within any species; 2) species have the capacity to overproduce; 3) only the best adapted individual organisms survive; 4) the best adapted individuals pass their genes on to their offspring; 5) over time, species become better adapted to their environments"}, {"id": "seed-apes-review-63", "term": "Adaptation to environmental change", "def": "If environments change slowly, organisms can adapt through migration or natural selection; rapid change, like global climate change, can have catastrophic results"}, {"id": "seed-apes-review-64", "term": "Peppered moths and the Industrial Revolution", "def": "In 1840 white moths were more common than black moths because the trees were white; from 1840-1890 air pollution darkened the bark of the trees; by 1890 black moths were more common than white"}, {"id": "seed-apes-review-65", "term": "Natural sciences vs social sciences in environmental science", "def": "Environmental science is interdisciplinary. The natural sciences (biology, chemistry, geology, ecology) describe how Earth's systems work and measure what is happening to them. The social sciences (economics, politics, sociology, ethics) explain why people behave as they do and how laws, markets, and culture can change that behavior. You need both: the natural sciences identify and measure the problem, the social sciences design solutions people will actually accept"}, {"id": "seed-apes-review-66", "term": "Spatial structure (and why it is a supporting service)", "def": "The physical arrangement of organisms, habitats, and resources across a landscape. It is a supporting service because the arrangement itself makes the other services possible: connected habitats allow migration, dispersal, and gene flow, and the pattern of vegetation controls water flow, soil retention, and productivity. Studied through spatial ecology"}, {"id": "seed-apes-review-67", "term": "Millennium Ecosystem Assessment", "def": "A UN-sponsored study (2001-2005) in which about 1,360 experts assessed the condition and trends of the world's ecosystems, the services they provide, and the options for conserving them. Its headline finding was that roughly 60% of the ecosystem services examined are being degraded or used unsustainably. It is the source of the four service categories: supporting, provisioning, regulating, and cultural"}, {"id": "seed-apes-review-68", "term": "MEA's five constituents of human well-being", "def": "1) Security; 2) Basic material for a good life; 3) Health; 4) Good social relations; 5) Freedom of choice and action"}, {"id": "seed-apes-review-69", "term": "Sustainable Development Goal for FOOD", "def": "SDG 2 - Zero Hunger: end hunger, achieve food security and improved nutrition, and promote sustainable agriculture"}, {"id": "seed-apes-review-70", "term": "Sustainable Development Goal for WATER", "def": "SDG 6 - Clean Water and Sanitation: ensure availability and sustainable management of water and sanitation for all"}, {"id": "seed-apes-review-71", "term": "Sustainable Development Goal for ENERGY", "def": "SDG 7 - Affordable and Clean Energy: ensure access to affordable, reliable, sustainable, and modern energy for all"}, {"id": "seed-apes-review-72", "term": "Sustainable Development Goal for CONSUMPTION", "def": "SDG 12 - Responsible Consumption and Production: ensure sustainable consumption and production patterns"}, {"id": "seed-apes-review-73", "term": "Sustainable Development Goal for CLIMATE CHANGE", "def": "SDG 13 - Climate Action: take urgent action to combat climate change and its impacts"}, {"id": "seed-apes-review-74", "term": "Sustainable Development Goal for MARINE ECOSYSTEMS", "def": "SDG 14 - Life Below Water: conserve and sustainably use the oceans, seas, and marine resources"}, {"id": "seed-apes-review-75", "term": "Sustainable Development Goal for TERRESTRIAL ECOSYSTEMS", "def": "SDG 15 - Life on Land: protect, restore, and promote sustainable use of terrestrial ecosystems, manage forests sustainably, combat desertification, halt and reverse land degradation, and halt biodiversity loss"}, {"id": "seed-apes-review-76", "term": "Five levels of organization in the biosphere", "def": "Population, then Community, then Ecosystem, then Biome, then Biosphere - each level contains all the ones before it"}, {"id": "seed-apes-review-77", "term": "Resource partitioning", "def": "When two species that would otherwise compete for the same resource divide it up - by time of day, by location, or by using a slightly different part of it - so that both can coexist. It is how species escape competitive exclusion: instead of one driving the other out, each evolves a narrower, non-overlapping niche. Example: MacArthur's warblers feeding at different heights in the same spruce tree"}, {"id": "seed-apes-review-78", "term": "Why the phosphorous cycle has no atmospheric component", "def": "Phosphorous forms no stable gas at Earth's surface temperatures, so unlike carbon and nitrogen it never enters the atmosphere. It moves only through rock, soil, water, and organisms - entering by the weathering of phosphate rock and leaving by settling into ocean sediment that slowly becomes rock again. Consequences: it is the slowest nutrient cycle, it cannot be replenished from the air, and phosphorous is usually the limiting nutrient in fresh water"}, {"id": "seed-apes-review-79", "term": "Antibiotic resistant bacteria", "def": "Bacteria that survive antibiotics because of random genetic mutations. It is natural selection step by step: there is variation in the population, the antibiotic is the selective pressure, susceptible bacteria die while resistant ones survive, and the survivors reproduce and pass the resistance on, so the whole population becomes resistant over generations. Sped up by overusing antibiotics, not finishing a prescription, and using them in livestock. Example: MRSA"}]}, {"id": "seed-apes-friedland", "rev": 1, "title": "APES Friedland Ch 3 + Ch 5", "folder": "APES", "description": "", "cards": [{"id": "seed-apes-friedland-0", "term": "Biosphere", "def": "The combination of all ecosystems on Earth; the region of our planet where life resides. It is a 20-km (12-mile) thick layer around Earth between the deepest ocean bottom and the highest mountain peak"}, {"id": "seed-apes-friedland-1", "term": "Producer", "def": "Plants, algae, and some bacteria that use the Sun's energy to produce usable forms of energy. Also called autotrophs"}, {"id": "seed-apes-friedland-2", "term": "Autotroph", "def": "Another name for a producer; an organism that uses the Sun's energy to produce usable forms of energy"}, {"id": "seed-apes-friedland-3", "term": "Photosynthesis", "def": "The process in which producers use solar energy to convert carbon dioxide and water into glucose. It also produces oxygen as a waste product"}, {"id": "seed-apes-friedland-4", "term": "Cellular respiration", "def": "A process by which cells unlock the energy of chemical compounds"}, {"id": "seed-apes-friedland-5", "term": "Aerobic respiration", "def": "The opposite of photosynthesis; cells convert glucose and oxygen into energy, carbon dioxide, and water. Organisms doing this essentially run photosynthesis backward to recover the solar energy stored in glucose"}, {"id": "seed-apes-friedland-6", "term": "Anaerobic respiration", "def": "A process by which cells convert glucose into energy in the absence of oxygen. It does not provide as much energy as aerobic respiration"}, {"id": "seed-apes-friedland-7", "term": "Consumer", "def": "An organism that is incapable of photosynthesis and must obtain its energy by consuming other organisms. Also called a heterotroph"}, {"id": "seed-apes-friedland-8", "term": "Heterotroph", "def": "Another name for a consumer; an organism incapable of photosynthesis that must eat other organisms"}, {"id": "seed-apes-friedland-9", "term": "Herbivore", "def": "A consumer that eats producers. Also called a primary consumer. Examples: zebras, grasshoppers, tadpoles, zooplankton"}, {"id": "seed-apes-friedland-10", "term": "Primary consumer", "def": "A consumer that eats producers; a herbivore"}, {"id": "seed-apes-friedland-11", "term": "Carnivore", "def": "A consumer that eats other consumers"}, {"id": "seed-apes-friedland-12", "term": "Secondary consumer", "def": "A carnivore that eats primary consumers. Examples: lions, hawks, rattlesnakes"}, {"id": "seed-apes-friedland-13", "term": "Tertiary consumer", "def": "A carnivore that eats secondary consumers. Example: bald eagles"}, {"id": "seed-apes-friedland-14", "term": "Trophic levels", "def": "The successive levels of organisms consuming one another. From the Greek trophe, meaning “nourishment”"}, {"id": "seed-apes-friedland-15", "term": "Food chain", "def": "The sequence of consumption from producers through tertiary consumers, where energy moves from one trophic level to the next"}, {"id": "seed-apes-friedland-16", "term": "Food web", "def": "A complex model of how energy and matter move through trophic levels. More realistic than a food chain, and it illustrates that all species in an ecosystem are connected to one another"}, {"id": "seed-apes-friedland-17", "term": "Scavenger", "def": "An organism, such as a vulture, that consumes dead animals"}, {"id": "seed-apes-friedland-18", "term": "Detritivore", "def": "An organism, such as a dung beetle, that specializes in breaking down dead tissues and waste products (called detritus) into smaller particles"}, {"id": "seed-apes-friedland-19", "term": "Decomposers", "def": "The fungi and bacteria that complete the breakdown process by converting organic matter into small elements and molecules that can be recycled back into the ecosystem"}, {"id": "seed-apes-friedland-20", "term": "Gross primary productivity (GPP)", "def": "A measure of the total amount of solar energy that the producers in an ecosystem capture via photosynthesis over a given amount of time. “Gross” means it does NOT subtract the energy lost when producers respire"}, {"id": "seed-apes-friedland-21", "term": "Net primary productivity (NPP)", "def": "The energy captured by producers minus the energy respired by producers. NPP = GPP − respiration"}, {"id": "seed-apes-friedland-22", "term": "Biomass", "def": "The total mass of all living matter in a specific area"}, {"id": "seed-apes-friedland-23", "term": "Standing crop", "def": "The amount of biomass present in an ecosystem at a particular time. Standing crop measures the amount of energy in a system at a given time, whereas productivity measures the rate of energy production over a span of time"}, {"id": "seed-apes-friedland-24", "term": "Ecological efficiency", "def": "The proportion of energy at one trophic level that is converted into energy at the next higher trophic level. Usually about 10 percent, with actual values ranging from 5 to 20 percent across ecosystems"}, {"id": "seed-apes-friedland-25", "term": "Trophic pyramid", "def": "A representation of the distribution of biomass or energy among trophic levels. Most of the energy and biomass is found at the producer level and commonly decreases as you move up"}, {"id": "seed-apes-friedland-26", "term": "Biogeochemical cycle", "def": "The cycles of biological, geological, and chemical processes that move matter within and between ecosystems. The components that contain the matter (air, water, organisms) are called “pools,” and the processes that move matter between pools are called “flows”"}, {"id": "seed-apes-friedland-27", "term": "Hydrologic cycle", "def": "The movement of water through the biosphere"}, {"id": "seed-apes-friedland-28", "term": "Transpiration", "def": "The process in which plants release water from their leaves into the atmosphere"}, {"id": "seed-apes-friedland-29", "term": "Evapotranspiration", "def": "The combined amount of evaporation and transpiration"}, {"id": "seed-apes-friedland-30", "term": "Runoff", "def": "Water that moves across the land surface and into streams and rivers, eventually reaching the ocean, which is the ultimate pool of water on Earth"}, {"id": "seed-apes-friedland-31", "term": "Carbon cycle", "def": "The movement of carbon around the biosphere"}, {"id": "seed-apes-friedland-32", "term": "Macronutrient", "def": "One of six key elements that organisms need in relatively large amounts: nitrogen, phosphorus, potassium, calcium, magnesium, and sulfur"}, {"id": "seed-apes-friedland-33", "term": "Limiting nutrient", "def": "A nutrient required for the growth of an organism but available in a lower quantity than other nutrients. Lack of it constrains growth, and adding other nutrients will not help"}, {"id": "seed-apes-friedland-34", "term": "Nitrogen cycle", "def": "The movement of nitrogen around the biosphere"}, {"id": "seed-apes-friedland-35", "term": "Nitrogen fixation", "def": "The process that converts nitrogen gas in the atmosphere into forms of nitrogen that producers can use. It can occur through biotic or abiotic processes"}, {"id": "seed-apes-friedland-36", "term": "Nitrification", "def": "The conversion of ammonium into nitrite and then into nitrate. These conversions are conducted by specialized species of bacteria"}, {"id": "seed-apes-friedland-37", "term": "Assimilation", "def": "The process in which producers take up nitrogen (as ammonia, ammonium, nitrite, or nitrate) and incorporate the element into their tissues"}, {"id": "seed-apes-friedland-38", "term": "Mineralization", "def": "The process in which fungal and bacterial decomposers break down the organic matter found in dead bodies and waste products and convert organic compounds back into inorganic compounds"}, {"id": "seed-apes-friedland-39", "term": "Ammonification", "def": "The name given to mineralization in the nitrogen cycle, because organic nitrogen compounds are converted into inorganic ammonium"}, {"id": "seed-apes-friedland-40", "term": "Denitrification", "def": "The final step that completes the nitrogen cycle: the conversion of nitrate in a series of steps into nitrous oxide and eventually nitrogen gas, which is emitted into the atmosphere. Conducted by specialized bacteria living under anaerobic conditions such as waterlogged soils or bottom sediments"}, {"id": "seed-apes-friedland-41", "term": "Leaching", "def": "A process in which dissolved molecules are transported through the soil via groundwater"}, {"id": "seed-apes-friedland-42", "term": "Phosphorus cycle", "def": "The movement of phosphorus around the biosphere. It operates primarily between land and water and has no gas phase, although tiny amounts enter the atmosphere as dust or sea spray"}, {"id": "seed-apes-friedland-43", "term": "Algal bloom", "def": "A rapid increase in the algal population of a waterway caused by phosphorus inputs, which quickly increases the biomass of algae in the ecosystem"}, {"id": "seed-apes-friedland-44", "term": "Hypoxic", "def": "Low in oxygen. Water becomes hypoxic when algae die and decomposition consumes large amounts of oxygen"}, {"id": "seed-apes-friedland-45", "term": "Dead zone", "def": "An area where oxygen concentrations become so low that fish and other aquatic animals are killed. Dead zones occur worldwide, including where the Mississippi River empties into the Gulf of Mexico"}, {"id": "seed-apes-friedland-46", "term": "Sulfur cycle", "def": "The movement of sulfur around the biosphere"}, {"id": "seed-apes-friedland-47", "term": "Disturbance", "def": "An event that alters how an ecosystem operates. Disturbances can occur over both short and long time scales"}, {"id": "seed-apes-friedland-48", "term": "Resistance (ecosystem)", "def": "A measure of how much a disturbance can affect an ecosystem's flows of energy and matter"}, {"id": "seed-apes-friedland-49", "term": "Resilience (ecosystem)", "def": "The rate at which an ecosystem returns to its original state after a disturbance. A highly resilient ecosystem returns relatively rapidly; a less resilient one does so more slowly"}, {"id": "seed-apes-friedland-50", "term": "Restoration ecology", "def": "The scientific discipline created out of growing interest in restoring damaged ecosystems. Current high-profile projects include the Florida Everglades and Chesapeake Bay"}, {"id": "seed-apes-friedland-51", "term": "Watershed", "def": "All of the land in a given landscape that drains into a particular stream, river, lake, or wetland"}, {"id": "seed-apes-friedland-52", "term": "Intermediate disturbance hypothesis", "def": "States that ecosystems experiencing intermediate levels of disturbance will favor a higher diversity of species than those with high or low disturbance levels"}, {"id": "seed-apes-friedland-53", "term": "Ecosystem boundaries", "def": "Ecosystem boundaries distinguish one ecosystem from another. Although boundaries can be well defined, often they are not. They are commonly defined either by topographic features such as mountain ranges, or are set subjectively by administrative criteria rather than biological criteria"}, {"id": "seed-apes-friedland-54", "term": "Earth as a system for energy vs matter", "def": "Earth is an OPEN system with respect to energy, but a CLOSED system with respect to matter. This is why matter must cycle"}, {"id": "seed-apes-friedland-55", "term": "Percent of solar energy producers capture", "def": "Producers typically capture only about 1 percent of the available solar energy via photosynthesis. That 1 percent is the gross primary productivity"}, {"id": "seed-apes-friedland-56", "term": "How GPP is divided", "def": "About 60 percent of GPP is typically used for respiration. The remaining 40 percent of GPP is used for growth and reproduction of the producers, which is the net primary productivity"}, {"id": "seed-apes-friedland-57", "term": "Energy transfer efficiency between trophic levels", "def": "Generally about 10 percent of the energy in one trophic level transfers to the next. Because efficiency is so low, the energy in each trophic level declines as you move up, giving a large biomass of producers but much less biomass of primary consumers and even less of secondary consumers"}, {"id": "seed-apes-friedland-58", "term": "Omnivores", "def": "Consumers that eat individuals from more than one trophic group"}, {"id": "seed-apes-friedland-59", "term": "Why scavengers, detritivores, and decomposers matter", "def": "Without them there would be no way of recycling organic matter and energy, and the world would rapidly fill up with dead plants and animals"}, {"id": "seed-apes-friedland-60", "term": "The seven processes of the carbon cycle", "def": "Photosynthesis, respiration, exchange, sedimentation, burial, extraction, and combustion"}, {"id": "seed-apes-friedland-61", "term": "Largest carbon pool in the slow part of the carbon cycle", "def": "Calcium carbonate sediment. Dissolved CO2 in the ocean combines with calcium ions to form calcium carbonate, which precipitates out and forms limestone and dolomite rock through sedimentation and burial. Although sedimentation is very slow, small yearly amounts have accumulated over millions of years"}, {"id": "seed-apes-friedland-62", "term": "Carbon cycle in the absence of human disturbance", "def": "The exchange of carbon between Earth's surface and atmosphere is in a steady state. Carbon taken up by photosynthesis ends up in the soil, and decomposers release it at roughly the same rate it is added"}, {"id": "seed-apes-friedland-63", "term": "Human impacts on the carbon cycle", "def": "The extraction and combustion of fossil fuels, and the destruction of forests, return CO2 to the atmosphere"}, {"id": "seed-apes-friedland-64", "term": "The five major transformations of the nitrogen cycle", "def": "Nitrogen fixation, nitrification, assimilation, mineralization, and denitrification"}, {"id": "seed-apes-friedland-65", "term": "What nitrogen is used to build, and why it limits growth", "def": "Nitrogen is used to form amino acids, the building blocks of proteins, and nucleic acids, the building blocks of DNA and RNA. Because so much is required, nitrogen is often a limiting nutrient for producers"}, {"id": "seed-apes-friedland-66", "term": "Why most atmospheric nitrogen is unusable", "def": "Although the atmosphere is about 78 percent nitrogen by volume, the vast majority is in a gas form that most producers cannot use. It must be fixed first"}, {"id": "seed-apes-friedland-67", "term": "Nitrogen-fixing organisms", "def": "Cyanobacteria, also known as blue-green algae, and certain bacteria that live within the roots of legumes such as peas, beans, and a few species of trees. They use the fixed nitrogen for their own tissues and excrete the excess"}, {"id": "seed-apes-friedland-68", "term": "Phosphorus cycle and the atmosphere", "def": "The phosphorus cycle has no gas phase, so it operates primarily between land and water. Phosphorus does enter the atmosphere in very small amounts when dust is dissolved in rainwater or sea spray"}, {"id": "seed-apes-friedland-69", "term": "Calcium, magnesium, and potassium in ecosystems", "def": "They regulate cellular processes and transmit signals between cells. Like phosphorus they come primarily from rocks and decomposed vegetation. All three dissolve in water as positively charged ions, none has a gaseous phase, and all can be deposited from the air as dust. Their positive charges attract them to the negative charges on soil particles"}, {"id": "seed-apes-friedland-70", "term": "Why potassium leaches but calcium and magnesium do not", "def": "Calcium and magnesium are strongly attracted to soil particles and are abundant in soils over limestone and marble. Potassium is only weakly attracted, so it is more easily leached away by water moving through the soil, which can create potassium-deficient soils that constrain plant and animal growth"}, {"id": "seed-apes-friedland-71", "term": "Sulfur in ecosystems", "def": "Sulfur is a component of proteins and plays an important role in allowing organisms to use oxygen. Most sulfur exists in rocks and is released by weathering, which makes it available for plant assimilation"}, {"id": "seed-apes-friedland-72", "term": "Sulfur, sulfur dioxide, and acid rain", "def": "Some sulfur exists as a gas in the form of sulfur dioxide (SO2), produced by volcanic eruptions and the burning of fossil fuels. In the atmosphere SO2 is converted into sulfuric acid (H2SO4) when it mixes with water, and the sulfuric acid is carried back to the ground when it rains or snows"}, {"id": "seed-apes-friedland-73", "term": "What watershed studies allow scientists to do", "def": "Because a watershed contains all the land that drains into a particular water body, experimental manipulations such as logging let scientists determine how a disturbance alters the flow of energy and matter through an ecosystem"}, {"id": "seed-apes-friedland-74", "term": "The Hubbard Brook result", "def": "Stream nitrate concentrations in two watersheds were similar before clear-cutting. After one watershed was clear-cut, its stream nitrate concentration increased"}, {"id": "seed-apes-friedland-75", "term": "Resistance vs resilience", "def": "Resistance is how much a disturbance can affect an ecosystem's flows of energy and matter. Resilience is the RATE at which the ecosystem returns to its original state afterward. An ecosystem that takes many years to recover from a drought has LOW resilience"}, {"id": "seed-apes-friedland-76", "term": "FIGURE 6.4  Photosynthesis and respiration", "def": "The top half shows producers using photosynthesis: solar energy converts carbon dioxide and water into glucose, releasing oxygen. The bottom half shows aerobic respiration, the opposite: cells convert glucose and oxygen into energy, carbon dioxide, and water"}, {"id": "seed-apes-friedland-77", "term": "FIGURE 6.5  Simple food chains", "def": "A simple food chain linking producers and consumers. Example: algae (producers) convert sunlight to glucose, zooplankton (primary consumers) eat the algae, fish (secondary consumers) eat the zooplankton, and eagles (tertiary consumers) eat the fish"}, {"id": "seed-apes-friedland-78", "term": "FIGURE 6.6  A simplified food web", "def": "Food webs are more realistic representations of trophic relationships than simple food chains. They include scavengers, detritivores, and decomposers, and they recognize that some species feed at multiple trophic levels. Arrows indicate the direction of energy movement"}, {"id": "seed-apes-friedland-79", "term": "FIGURE 6.7  Gross and net primary productivity", "def": "Shows that 99 percent of solar energy is reflected or passes through producers unabsorbed. About 1 percent is captured as GPP, roughly 60 percent of GPP goes to respiration, and the remaining 40 percent is NPP"}, {"id": "seed-apes-friedland-80", "term": "FIGURE 6.9  Trophic pyramid for the Serengeti ecosystem", "def": "Represents the energy present at each trophic level, measured in joules. It assumes 10 percent ecological efficiency. Graphing numbers of individuals or biomass per trophic level produces a similar pyramid"}, {"id": "seed-apes-friedland-81", "term": "FIGURE 7.1  The hydrologic cycle", "def": "Water moves from the atmosphere to Earth's surface and back. Labels to know: precipitation, evaporation, transpiration, evapotranspiration, percolation into groundwater, and runoff into streams, rivers, and the ocean"}, {"id": "seed-apes-friedland-82", "term": "FIGURE 7.2  The carbon cycle", "def": "Illustrates the seven processes that drive the carbon cycle: photosynthesis, respiration, exchange, sedimentation, burial, extraction, and combustion"}, {"id": "seed-apes-friedland-83", "term": "FIGURE 7.3  The nitrogen cycle", "def": "Moves nitrogen from the atmosphere into soils through several fixation pathways, including human production of fertilizers. In the soil nitrogen exists in several forms, and denitrifying bacteria return it to the atmosphere. The five transformations shown are fixation, nitrification, assimilation, mineralization, and denitrification"}, {"id": "seed-apes-friedland-84", "term": "FIGURE 7.4  The phosphorus cycle", "def": "Operates primarily between land and water with no gas phase. A large pool of phosphorus sits in rock formed by phosphate precipitating onto the ocean floor; geologic uplift forms mountains, and weathering or mining makes it available to producers"}, {"id": "seed-apes-friedland-85", "term": "FIGURE 7.5  Algal bloom", "def": "When excess phosphorus enters waterways it can stimulate sudden rapid algae growth that turns the water bright green"}, {"id": "seed-apes-friedland-86", "term": "FIGURE 8.3  Watershed", "def": "A watershed is the area of land that drains into a particular body of water"}, {"id": "seed-apes-friedland-87", "term": "FIGURE 8.5  Intermediate disturbance hypothesis", "def": "Species diversity is highest at intermediate levels of disturbance and lower at both high and low disturbance levels. An example is marine algae attached to rocks along the rocky coast of New England"}, {"id": "seed-apes-friedland-88", "term": "Species richness", "def": "The number of species in a given area, such as a pond, the canopy of a tree, or a plot of grassland. It gives an approximate sense of the biodiversity of a place"}, {"id": "seed-apes-friedland-89", "term": "Species evenness", "def": "The relative proportion of individuals within the different species in a location. It tells us whether an ecosystem is numerically dominated by one species or whether all its species have similar abundances"}, {"id": "seed-apes-friedland-90", "term": "Phylogeny", "def": "A branching diagram (a phylogenetic tree) showing how species are related to one another and the likely steps in evolution that gave rise to current species. Relatedness is determined by similarity of traits: the more similar the traits, the more closely related two species are assumed to be"}, {"id": "seed-apes-friedland-91", "term": "Evolution", "def": "A change in the genetic composition of a population over time"}, {"id": "seed-apes-friedland-92", "term": "Microevolution", "def": "Evolution below the species level, such as the evolution of different varieties of apples or potatoes"}, {"id": "seed-apes-friedland-93", "term": "Macroevolution", "def": "Evolution in which genetic changes give rise to new species, genera, families, classes, or phyla. Speciation is the term restricted to the evolution of new species"}, {"id": "seed-apes-friedland-94", "term": "Gene", "def": "A physical location on a chromosome within each cell of an organism. A given gene has DNA that codes for a particular trait"}, {"id": "seed-apes-friedland-95", "term": "Genotype", "def": "The complete set of genes in an individual. It serves as the blueprint for the complete set of traits the organism may potentially possess"}, {"id": "seed-apes-friedland-96", "term": "Phenotype", "def": "The actual set of traits expressed in an individual, including its anatomy, physiology, and behavior. Eye color is a phenotype; the genes coding for eye color are part of the genotype"}, {"id": "seed-apes-friedland-97", "term": "Mutation", "def": "A random change in the genetic code. If a mutation improves an organism's chance of survival or reproduction and is passed to the next generation, it adds new genetic diversity to the population"}, {"id": "seed-apes-friedland-98", "term": "Recombination", "def": "Occurs as chromosomes are duplicated during reproductive cell division and a piece of one chromosome breaks off and attaches to another chromosome. It allows new allele combinations to come together"}, {"id": "seed-apes-friedland-99", "term": "Evolution by artificial selection", "def": "When humans determine which individuals to breed, typically with a preconceived set of traits in mind"}, {"id": "seed-apes-friedland-100", "term": "Evolution by natural selection", "def": "When the environment determines which individuals survive and reproduce. Members of a population naturally vary in their traits, and certain combinations make individuals better able to survive and reproduce, so the genes producing those traits become more common in the next generation"}, {"id": "seed-apes-friedland-101", "term": "Fitness", "def": "An individual's ability to survive and reproduce"}, {"id": "seed-apes-friedland-102", "term": "Adaptation", "def": "A trait that improves an individual's fitness"}, {"id": "seed-apes-friedland-103", "term": "Gene flow", "def": "The process by which individuals move from one population to another and thereby alter the genetic composition of both populations"}, {"id": "seed-apes-friedland-104", "term": "Genetic drift", "def": "A change in the genetic composition of a population over time as a result of random mating"}, {"id": "seed-apes-friedland-105", "term": "Bottleneck effect", "def": "A drastic reduction in the size of a population that reduces genetic variation. Causes include habitat loss, natural disaster, harvesting by humans, or environmental change"}, {"id": "seed-apes-friedland-106", "term": "Extinction", "def": "Occurs when the last member of a species dies"}, {"id": "seed-apes-friedland-107", "term": "Founder effect", "def": "A change in a population's genetic composition that results from a small number of colonizing individuals. Like mutation, genetic drift, and the bottleneck effect, it is random and not based on differences in fitness"}, {"id": "seed-apes-friedland-108", "term": "Geographic isolation", "def": "The physical separation of a group of individuals from others of the same species"}, {"id": "seed-apes-friedland-109", "term": "Allopatric speciation", "def": "The process of speciation that occurs with geographic isolation. From the Greek allos, meaning “other,” and patris, meaning “fatherland.” It is thought to be the most common way evolution generates new species"}, {"id": "seed-apes-friedland-110", "term": "Reproductive isolation", "def": "When two populations of a species have evolved separately to the point that they can no longer interbreed and produce viable offspring. At this point they have become distinct species"}, {"id": "seed-apes-friedland-111", "term": "Sympatric speciation", "def": "The evolution of one species into two species without geographic isolation. It usually happens through polyploidy"}, {"id": "seed-apes-friedland-112", "term": "Genetically modified organism (GMO)", "def": "An organism produced when scientists use genetic engineering to copy genes from a species with a desirable trait, such as rapid growth or disease resistance, and insert them into another species of plant, animal, or microbe"}, {"id": "seed-apes-friedland-113", "term": "Range of tolerance", "def": "The limits to the abiotic conditions a species can tolerate, such as extremes of temperature, humidity, salinity, and pH. As conditions move further from the ideal, an individual's ability to survive, grow, and reproduce declines"}, {"id": "seed-apes-friedland-114", "term": "Fundamental niche", "def": "The suite of abiotic conditions under which a species can survive, grow, and reproduce"}, {"id": "seed-apes-friedland-115", "term": "Realized niche", "def": "The portion of the fundamental niche that a species actually occupies due to biotic interactions, including predation, competition, and disease"}, {"id": "seed-apes-friedland-116", "term": "Distribution", "def": "The areas of the world in which a species lives. The niche a species occupies determines its distribution"}, {"id": "seed-apes-friedland-117", "term": "Niche generalist", "def": "A species that can live under a very wide range of abiotic or biotic conditions. Example: gray kangaroos, which feed on numerous plant species"}, {"id": "seed-apes-friedland-118", "term": "Niche specialist", "def": "A species specialized to live under a very narrow range of conditions or to feed on a small group of species. Example: the koala, which feeds only on the leaves of several species of eucalyptus"}, {"id": "seed-apes-friedland-119", "term": "Mass extinction", "def": "A period in which large numbers of species went extinct over a relatively short time. The fossil record has revealed five periods of global mass extinction. Because species are hard to discriminate in the fossil record, scientists count genera rather than species"}, {"id": "seed-apes-friedland-120", "term": "How scientists estimate the number of species on Earth", "def": "They collect samples of diverse groups of organisms, determine the proportion of all known species, and then extrapolate those numbers to other groups to estimate the total"}, {"id": "seed-apes-friedland-121", "term": "Why we quantify biodiversity", "def": "Measurements of species richness, evenness, or both give scientists a baseline they can use to determine how much an ecosystem has been affected by a natural or anthropogenic disturbance"}, {"id": "seed-apes-friedland-122", "term": "What creates genetic diversity", "def": "Mutation and recombination. Every individual has a genotype that, in combination with the environment, determines its phenotype"}, {"id": "seed-apes-friedland-123", "term": "Harmful outcomes of artificial selection", "def": "It has produced selection for pesticide-resistant pests and drug-resistant bacteria"}, {"id": "seed-apes-friedland-124", "term": "What natural selection does and does not do", "def": "Natural selection does not target particular traits or work toward a predetermined goal. It simply favors any combination of traits that improves an individual's fitness, and it can favor multiple solutions to the same environmental challenge"}, {"id": "seed-apes-friedland-125", "term": "The five random processes that cause evolution", "def": "Mutation, gene flow, genetic drift, the bottleneck effect, and the founder effect. These change a population's genetic composition but are NOT related to differences in fitness"}, {"id": "seed-apes-friedland-126", "term": "Why population size matters for mutation", "def": "The larger the population, the more opportunities there are for mutations to appear within it"}, {"id": "seed-apes-friedland-127", "term": "The cheetah example", "def": "The cheetah has relatively little genetic variation because of a bottleneck that appears to have occurred about 10,000 years ago. Once forced through a bottleneck, low genetic diversity can cause a species to decline to extinction"}, {"id": "seed-apes-friedland-128", "term": "How allopatric speciation works", "def": "A subset of individuals becomes geographically isolated from the larger population. The isolated populations diverge over time through random processes or natural selection, becoming more genetically distinct until reproductive isolation makes them separate species"}, {"id": "seed-apes-friedland-129", "term": "How sympatric speciation works", "def": "One species separates into two without geographic isolation, usually through polyploidy. Most organisms are diploid with two sets of chromosomes; in polyploidy the number increases to three, four, or even six sets"}, {"id": "seed-apes-friedland-130", "term": "Four factors that affect the pace of evolution", "def": "1) Populations adapt more easily when environmental change is slow rather than rapid. 2) Populations with high genetic variation, often large populations, are more likely to adapt. 3) A beneficial mutation spreads through a small population faster than a large one. 4) Evolution is faster in populations with shorter generation times"}, {"id": "seed-apes-friedland-131", "term": "Fundamental vs realized niche", "def": "The fundamental niche is where a species COULD live based on abiotic conditions alone. The realized niche is the smaller portion it ACTUALLY occupies once biotic interactions such as predation, competition, and disease are included"}, {"id": "seed-apes-friedland-132", "term": "How environmental change alters distributions", "def": "Because a species' niche represents the conditions under which it can live, environmental change causes a change in the distribution of that species"}, {"id": "seed-apes-friedland-133", "term": "When environmental change causes extinction", "def": "When environmental changes are too rapid and too extensive to permit evolutionary change, or if a species cannot move to a more hospitable environment, it will not persist and will go extinct"}, {"id": "seed-apes-friedland-134", "term": "Niche specialists vs generalists under change", "def": "Niche specialists persist well when environmental conditions are stable, but they are more vulnerable when conditions change, because they tolerate only a narrow range"}, {"id": "seed-apes-friedland-135", "term": "FIGURE 14.2  Measures of species diversity", "def": "Two communities can contain the same NUMBER of species but differ in diversity. Community 1 has an even distribution of four species at 25 percent each and is therefore more diverse than Community 2, which is dominated by one species"}, {"id": "seed-apes-friedland-136", "term": "FIGURE 14.3  A phylogenetic tree", "def": "Shows clades branching as traits evolve, for example the clade in which mammary glands are formed leading onward to chipmunks. It depicts relatedness and the likely evolutionary steps"}, {"id": "seed-apes-friedland-137", "term": "FIGURE 15.1  Environmental effects on phenotype", "def": "The same genotype can produce different phenotypes depending on the environment, showing that phenotype results from genotype combined with environment"}, {"id": "seed-apes-friedland-138", "term": "FIGURE 15.7  Evolution by mutation", "def": "The larger the population, the more opportunities there will be for mutations to appear within it, and as mutations accumulate genetic variation increases"}, {"id": "seed-apes-friedland-139", "term": "FIGURE 15.10  Evolution by the bottleneck effect", "def": "A drastic reduction in population size reduces genetic variation, so the survivors' genetic composition differs from the original population's"}, {"id": "seed-apes-friedland-140", "term": "FIGURE 15.11  Evolution by the founder effect", "def": "If a few individuals from a mainland population colonize an island, the genetic composition of the new island population reflects only the genes those few founders happened to carry"}, {"id": "seed-apes-friedland-141", "term": "FIGURE 16.1  Allopatric speciation", "def": "Geographic isolation occurs when a subset of individuals from a larger population colonizes a new area of habitat physically separated from the larger population"}, {"id": "seed-apes-friedland-142", "term": "FIGURE 16.2  Allopatric speciation of Darwin's finches", "def": "Shows how geographic isolation among islands produced multiple finch species from a common ancestor"}, {"id": "seed-apes-friedland-143", "term": "FIGURE 17.1  Range of tolerance", "def": "All species have an ideal range of abiotic conditions, such as temperature, under which members can survive, grow, and reproduce. Under more extreme conditions that ability declines. The area under the curve represents the fundamental niche"}, {"id": "seed-apes-friedland-144", "term": "FIGURE 17.2  Generalists and specialists", "def": "Contrasts the gray kangaroo, a niche generalist that feeds on numerous plant species, with the koala, a niche specialist that eats only certain eucalyptus leaves"}, {"id": "seed-apes-friedland-145", "term": "FIGURE 17.6  Mass extinctions", "def": "Shows the timing of the five periods of global mass extinction revealed by the fossil record, counted by genera rather than species"}, {"id": "seed-apes-friedland-146", "term": "DO THE MATH  Raising Mangoes", "def": "Applies basic math to the decisions involved in planting trees to reforest Haiti and reduce human impacts on the hydrologic cycle"}, {"id": "seed-apes-friedland-147", "term": "DO THE MATH  Measuring Species Diversity", "def": "Demonstrates a common way of calculating species diversity, evaluating both species richness and species evenness"}, {"id": "seed-apes-friedland-148", "term": "DO THE MATH  Estimating the Impact of the Founder Effect", "def": "Practice converting the number of individuals with each phenotype into percentages of each phenotype"}, {"id": "seed-apes-friedland-149", "term": "Calculating energy transfer between trophic levels", "def": "Divide the productivity of the higher trophic level by the productivity of the level below it, then multiply by 100. Example from Cedar Bog Lake: producers 111.3, primary consumers 14.8, secondary consumers 3.1 cal/cm2/year"}, {"id": "seed-apes-friedland-150", "term": "Working out GPP from NPP", "def": "Because NPP = GPP − respiration, GPP = NPP + respiration. If NPP is 1 kg C/m2/yr and respiration is 1.5, then GPP is 2.5 kg C/m2/yr"}, {"id": "seed-apes-friedland-151", "term": "WORKING TOWARD SUSTAINABILITY  The Practice of Precision Agriculture", "def": "Farmers use GPS-equipped, self-steering tractors and satellite imagery to tailor the amount of fertilizer or pesticide applied to different areas of a field. Nutrients such as phosphorus and nitrogen otherwise wash into streams, rivers, and lakes and cause algal blooms and dead zones. Excess fertilizer is also a financial loss to the farmer, so precision agriculture reduces nutrient runoff and increases the efficiency of fertilizer application"}, {"id": "seed-apes-friedland-152", "term": "WORKING TOWARD SUSTAINABILITY  Protecting the Oceans When They Cannot Be Bought", "def": "The Nature Conservancy has protected biodiversity for over 50 years with a simple strategy: buy it. Using grants and donations it purchases natural areas or development rights. TNC owns over 0.8 million hectares (2 million acres) and has protected over 46 million hectares (115 million acres) by buying development rights. As a nonprofit NGO it has flexibility to use innovative conservation and restoration techniques. It focuses on areas with rare species or high biodiversity, such as the Florida Keys and Santa Cruz Island, and has recently turned to oceans and coastal marine ecosystems"}, {"id": "seed-apes-friedland-153", "term": "AP EXAM TIP  Photosynthesis and respiration", "def": "You should know how photosynthesis and cellular respiration work, including the various inputs and outputs of each process"}, {"id": "seed-apes-friedland-154", "term": "AP EXAM TIP  Cycles", "def": "It is important to understand the role of photosynthesis and cellular respiration in biogeochemical cycles, particularly the carbon cycle"}, {"id": "seed-apes-friedland-155", "term": "AP EXAM TIP  Using terms in free response", "def": "The free-response section asks you to describe and quantify processes and systems. Using a term is not enough without including the MEANING of the term in your description"}, {"id": "seed-apes-friedland-156", "term": "AP EXAM TIP  Avoid vague answers", "def": "Avoid statements such as “it will kill all the animals and plants.” Use the phrase “range of tolerance” instead. For example, if ocean temperatures increase, some organisms will not survive because the temperature exceeds their range of tolerance"}, {"id": "seed-apes-friedland-157", "term": "AP EXAM TIP  Models and data", "def": "The exam includes models such as data tables, graphs, and other data graphics. Practice analyzing them so you are comfortable gathering data and making predictions and inferences"}]}, {"id": "seed-apes-frq", "rev": 1, "title": "APES — 6 FRQs to Memorize", "folder": "APES", "description": "", "cards": [{"id": "seed-apes-frq-0", "term": "FRQ 1a  List the five Life support systems (Supporting services)", "def": "1) Nutrient cycling  2) Evolution  3) Soil formation  4) Spatial structure  5) Primary productivity"}, {"id": "seed-apes-frq-1", "term": "FRQ 1b  List the Provisioning services", "def": "Food, water, fuel wood, fiber, biochemicals, genetic diversity. (6 items)"}, {"id": "seed-apes-frq-2", "term": "FRQ 1c  List the Regulating services", "def": "Climate regulation, disease regulation, water regulation, water purification, pollination. (5 items)"}, {"id": "seed-apes-frq-3", "term": "FRQ 1d  List the Cultural services", "def": "Spiritual and religious, recreation, ecotourism, aesthetic, inspirational, educational, sense of place, cultural heritage. (8 items)"}, {"id": "seed-apes-frq-4", "term": "FRQ 1  What are ecosystem services?", "def": "Ecosystem services are a natural extension of the Earth's life support systems. The four categories are supporting (life support) services, provisioning services, regulating services, and cultural services"}, {"id": "seed-apes-frq-5", "term": "FRQ 2  Indicator species — give the full answer", "def": "a) A species with a narrow range of tolerance for important biotic and abiotic factors within an ecosystem.  b) When an indicator species is not healthy, it is an indicator that the entire ecosystem may not be healthy.  c) Ex: Northern Spotted Owl for NW old growth forests; Orca for Puget Sound"}, {"id": "seed-apes-frq-6", "term": "FRQ 2  Keystone species — give the full answer", "def": "a) A species that has a niche that contributes to many other species within an ecosystem, also called “ecosystem engineers.”  b) When the population of a keystone species declines, it impacts the entire ecosystem.  c) Ex: wolf, beaver, salmon"}, {"id": "seed-apes-frq-7", "term": "FRQ 3  Human impacts on the carbon cycle — the three ways", "def": "a) Burning fossil fuels increases atmospheric CO2 and global climate change.  b) Cutting down trees and burning rainforest adds CO2 to the atmosphere through combustion and removes an important carbon sink (tree trunks).  c) Making cement releases CO2 from the CaCO3"}, {"id": "seed-apes-frq-8", "term": "FRQ 4  Human impacts on the nitrogen cycle — the opening line", "def": "Human activity has doubled the amount of fixed nitrogen over pre-industrial levels"}, {"id": "seed-apes-frq-9", "term": "FRQ 4  The five negative effects of increased fixed nitrogen", "def": "IN THE ATMOSPHERE: 1) Nitrogen oxides (NOx) break down stratospheric ozone, which lets in too much UV radiation.  2) NOx are converted by sunlight into smog (PAN and O3).  3) NOx mix with water in the atmosphere to become acid rain.  IN THE WATER: 4) Nitrates from manure and fertilizer contaminate drinking water and cause “blue baby” syndrome.  5) Eutrophication — along with phosphorous, nitrogen causes “algal blooms,” which ultimately reduce O2 in water"}, {"id": "seed-apes-frq-10", "term": "FRQ 5  The 5 key ideas of natural selection", "def": "1) There is a lot of genetic variation within any species.  2) Species have the capacity to overproduce.  3) Only the best adapted individual organisms survive.  4) The best adapted individual organisms pass their genes on to their offspring.  5) Over time, species become better adapted to their environments"}, {"id": "seed-apes-frq-11", "term": "Life support systems — item a", "def": "Nutrient cycling"}, {"id": "seed-apes-frq-12", "term": "Life support systems — item b", "def": "Evolution"}, {"id": "seed-apes-frq-13", "term": "Life support systems — item c", "def": "Soil formation"}, {"id": "seed-apes-frq-14", "term": "Life support systems — item d", "def": "Spatial structure"}, {"id": "seed-apes-frq-15", "term": "Life support systems — item e", "def": "Primary productivity"}, {"id": "seed-apes-frq-16", "term": "Natural selection — key idea 1", "def": "There is a lot of genetic variation within any species"}, {"id": "seed-apes-frq-17", "term": "Natural selection — key idea 2", "def": "Species have the capacity to overproduce"}, {"id": "seed-apes-frq-18", "term": "Natural selection — key idea 3", "def": "Only the best adapted individual organisms survive"}, {"id": "seed-apes-frq-19", "term": "Natural selection — key idea 4", "def": "The best adapted individual organisms pass their genes on to their offspring"}, {"id": "seed-apes-frq-20", "term": "Natural selection — key idea 5", "def": "Over time, species become better adapted to their environments"}, {"id": "seed-apes-frq-21", "term": "Carbon impact a", "def": "Burning fossil fuels increases atmospheric CO2 and global climate change"}, {"id": "seed-apes-frq-22", "term": "Carbon impact b", "def": "Cutting down trees and burning rainforest adds CO2 to the atmosphere through combustion and removes an important carbon sink (tree trunks)"}, {"id": "seed-apes-frq-23", "term": "Carbon impact c", "def": "Making cement releases CO2 from the CaCO3"}, {"id": "seed-apes-frq-24", "term": "Nitrogen effect 1", "def": "Nitrogen oxides (NOx) break down stratospheric ozone, which lets in too much UV radiation"}, {"id": "seed-apes-frq-25", "term": "Nitrogen effect 2", "def": "NOx are converted by sunlight into smog (PAN and O3)"}, {"id": "seed-apes-frq-26", "term": "Nitrogen effect 3", "def": "NOx mix with water in the atmosphere to become acid rain"}, {"id": "seed-apes-frq-27", "term": "Nitrogen effect 4", "def": "Nitrates from manure and fertilizer contaminate drinking water and cause “blue baby” syndrome"}, {"id": "seed-apes-frq-28", "term": "Nitrogen effect 5", "def": "Eutrophication — along with phosphorous, nitrogen causes “algal blooms,” which ultimately reduce O2 in water"}, {"id": "seed-apes-frq-29", "term": "Indicator species — the definition line", "def": "A species with a narrow range of tolerance for important biotic and abiotic factors within an ecosystem"}, {"id": "seed-apes-frq-30", "term": "Indicator species — the significance line", "def": "When an indicator species is not healthy, it is an indicator that the entire ecosystem may not be healthy"}, {"id": "seed-apes-frq-31", "term": "Indicator species — the examples", "def": "Northern Spotted Owl for NW old growth forests; Orca for Puget Sound"}, {"id": "seed-apes-frq-32", "term": "Keystone species — the definition line", "def": "A species that has a niche that contributes to many other species within an ecosystem, also called “ecosystem engineers”"}, {"id": "seed-apes-frq-33", "term": "Keystone species — the significance line", "def": "When the population of a keystone species declines, it impacts the entire ecosystem"}, {"id": "seed-apes-frq-34", "term": "Keystone species — the examples", "def": "Wolf, beaver, salmon"}, {"id": "seed-apes-frq-35", "term": "HOW MANY  Life support (supporting) services", "def": "5"}, {"id": "seed-apes-frq-36", "term": "HOW MANY  Provisioning services", "def": "6"}, {"id": "seed-apes-frq-37", "term": "HOW MANY  Regulating services", "def": "5"}, {"id": "seed-apes-frq-38", "term": "HOW MANY  Cultural services", "def": "8 — the longest list, so this is the one you are most likely to come up short on"}, {"id": "seed-apes-frq-39", "term": "HOW MANY  Categories of ecosystem services", "def": "4 — supporting, provisioning, regulating, cultural"}, {"id": "seed-apes-frq-40", "term": "HOW MANY  Human impacts on the carbon cycle", "def": "3"}, {"id": "seed-apes-frq-41", "term": "HOW MANY  Negative effects of increased fixed nitrogen", "def": "5 — three in the atmosphere, two in the water"}, {"id": "seed-apes-frq-42", "term": "HOW MANY  Key ideas of natural selection", "def": "5"}, {"id": "seed-apes-frq-43", "term": "HOW MANY  Parts to each special species answer", "def": "3 each — the definition, what it means when it declines or is unhealthy, and the examples"}, {"id": "seed-apes-frq-44", "term": "HOOK  Life support (supporting) services", "def": "PENSS — Primary productivity, Evolution, Nutrient cycling, Soil formation, Spatial structure. Think “PENS” plus one more S, and remember the two S's are the pair: Soil and Spatial"}, {"id": "seed-apes-frq-45", "term": "HOOK  Provisioning services", "def": "Three F's plus three more: FOOD, FUEL WOOD, FIBER are the F's, then WATER, BIOCHEMICALS, GENETIC DIVERSITY. These are all things you physically take out of an ecosystem"}, {"id": "seed-apes-frq-46", "term": "HOOK  Regulating services", "def": "Three regulations, one purification, one pollination. The three regulations are CLIMATE, DISEASE, WATER. Then add WATER PURIFICATION and POLLINATION. These are all jobs the ecosystem does for you"}, {"id": "seed-apes-frq-47", "term": "HOOK  Cultural services", "def": "Four pairs of two. BELIEF: spiritual and religious + cultural heritage. VISITING: recreation + ecotourism. BEAUTY: aesthetic + inspirational. BELONGING: educational + sense of place. These are all what the ecosystem MEANS to people"}, {"id": "seed-apes-frq-48", "term": "HOOK  Human impacts on the carbon cycle", "def": "BURN, CUT, BAKE. Burn fossil fuels, cut down trees, bake cement. Cement is literally baked limestone, which is why the CO2 comes out of the CaCO3"}, {"id": "seed-apes-frq-49", "term": "HOOK  The five nitrogen effects", "def": "3 in the air, 2 in the water. AIR: ozone/UV, smog, acid rain — all three start with NOx. WATER: blue baby, eutrophication. The slide brackets them this way, so use the same split"}, {"id": "seed-apes-frq-50", "term": "HOOK  The 5 key ideas of natural selection", "def": "It is a story in order, not a list: there is VARIATION, species OVERPRODUCE, only the best adapted SURVIVE, survivors PASS ON their genes, and over time the species ADAPTS. Vary, Overproduce, Survive, Pass on, Adapt"}, {"id": "seed-apes-frq-51", "term": "HOOK  Indicator vs keystone", "def": "INDICATOR is the canary: narrow range of tolerance, so it tells you the ecosystem is sick. KEYSTONE is the engineer: its niche supports many other species, so its loss wrecks the ecosystem. Indicator WARNS, keystone HOLDS THINGS UP"}, {"id": "seed-apes-frq-52", "term": "SORT IT  Nutrient cycling", "def": "Life support / supporting service"}, {"id": "seed-apes-frq-53", "term": "SORT IT  Evolution", "def": "Life support / supporting service"}, {"id": "seed-apes-frq-54", "term": "SORT IT  Soil formation", "def": "Life support / supporting service"}, {"id": "seed-apes-frq-55", "term": "SORT IT  Spatial structure", "def": "Life support / supporting service"}, {"id": "seed-apes-frq-56", "term": "SORT IT  Primary productivity", "def": "Life support / supporting service"}, {"id": "seed-apes-frq-57", "term": "SORT IT  Food", "def": "Provisioning service"}, {"id": "seed-apes-frq-58", "term": "SORT IT  Water", "def": "Provisioning service"}, {"id": "seed-apes-frq-59", "term": "SORT IT  Fuel wood", "def": "Provisioning service"}, {"id": "seed-apes-frq-60", "term": "SORT IT  Fiber", "def": "Provisioning service"}, {"id": "seed-apes-frq-61", "term": "SORT IT  Biochemicals", "def": "Provisioning service"}, {"id": "seed-apes-frq-62", "term": "SORT IT  Genetic diversity", "def": "Provisioning service"}, {"id": "seed-apes-frq-63", "term": "SORT IT  Climate regulation", "def": "Regulating service"}, {"id": "seed-apes-frq-64", "term": "SORT IT  Disease regulation", "def": "Regulating service"}, {"id": "seed-apes-frq-65", "term": "SORT IT  Water regulation", "def": "Regulating service"}, {"id": "seed-apes-frq-66", "term": "SORT IT  Water purification", "def": "Regulating service"}, {"id": "seed-apes-frq-67", "term": "SORT IT  Pollination", "def": "Regulating service"}, {"id": "seed-apes-frq-68", "term": "SORT IT  Spiritual and religious", "def": "Cultural service"}, {"id": "seed-apes-frq-69", "term": "SORT IT  Recreation", "def": "Cultural service"}, {"id": "seed-apes-frq-70", "term": "SORT IT  Ecotourism", "def": "Cultural service"}, {"id": "seed-apes-frq-71", "term": "SORT IT  Aesthetic", "def": "Cultural service"}, {"id": "seed-apes-frq-72", "term": "SORT IT  Inspirational", "def": "Cultural service"}, {"id": "seed-apes-frq-73", "term": "SORT IT  Educational", "def": "Cultural service"}, {"id": "seed-apes-frq-74", "term": "SORT IT  Sense of place", "def": "Cultural service"}, {"id": "seed-apes-frq-75", "term": "SORT IT  Cultural heritage", "def": "Cultural service"}, {"id": "seed-apes-frq-76", "term": "TRAP  Water vs water regulation vs water purification", "def": "Plain WATER is a PROVISIONING service, because you take it out and use it. WATER REGULATION and WATER PURIFICATION are both REGULATING services, because they are jobs the ecosystem performs. All three appear on the slide, so do not list one and think you are done"}, {"id": "seed-apes-frq-77", "term": "TRAP  Evolution as a service", "def": "Evolution is a LIFE SUPPORT (supporting) service, not a cultural one. So are nutrient cycling, soil formation, spatial structure, and primary productivity — the underlying processes that make the other services possible"}, {"id": "seed-apes-frq-78", "term": "TRAP  Which nitrogen effects are in the water", "def": "Only two: blue baby syndrome from nitrates in drinking water, and eutrophication. The other three are atmospheric and all involve NOx"}]}, {"id": "seed-chem-equipment", "rev": 1, "title": "Chem — Lab Equipment ID", "folder": "Chem", "description": "Picture on the front: name the equipment.", "cards": [{"id": "seed-chem-equipment-0", "term": "", "def": "Beaker", "termImg": "seed/img/chem-beaker.svg", "note": "Straight sides, wide mouth. General mixing and heating; volume marks are only approximate."}, {"id": "seed-chem-equipment-1", "term": "", "def": "Erlenmeyer flask", "termImg": "seed/img/chem-erlenmeyer.svg", "note": "Cone-shaped with a narrow neck, so you can swirl without splashing."}, {"id": "seed-chem-equipment-2", "term": "", "def": "Volumetric flask", "termImg": "seed/img/chem-volumetric.svg", "note": "Round bottom, long neck with ONE line: makes an exact volume of solution."}, {"id": "seed-chem-equipment-3", "term": "", "def": "Florence flask", "termImg": "seed/img/chem-florence.svg", "note": "Round bottom and a long neck; heats evenly."}, {"id": "seed-chem-equipment-4", "term": "", "def": "Buret", "termImg": "seed/img/chem-buret.svg", "note": "Long graduated tube with a stopcock; delivers a precise, variable volume (titrations)."}, {"id": "seed-chem-equipment-5", "term": "", "def": "Pipet", "termImg": "seed/img/chem-pipet.svg", "note": "Slender tube that transfers a precise, usually fixed volume of liquid."}, {"id": "seed-chem-equipment-6", "term": "", "def": "Ring stand and clamp", "termImg": "seed/img/chem-ringstand.svg", "note": "Heavy base and rod that holds apparatus in place."}, {"id": "seed-chem-equipment-7", "term": "", "def": "Buret clamp", "termImg": "seed/img/chem-buretclamp.svg", "note": "Holds a buret upright on a ring stand."}, {"id": "seed-chem-equipment-8", "term": "", "def": "Crucible (with lid)", "termImg": "seed/img/chem-crucible.svg", "note": "Small ceramic cup for heating substances to very high temperatures."}, {"id": "seed-chem-equipment-9", "term": "", "def": "Mortar and pestle", "termImg": "seed/img/chem-mortar.svg", "note": "Bowl and club for grinding solids into powder."}, {"id": "seed-chem-equipment-10", "term": "", "def": "Evaporating dish", "termImg": "seed/img/chem-evaporating.svg", "note": "Shallow dish; evaporate a liquid to leave the dissolved solid behind."}, {"id": "seed-chem-equipment-11", "term": "", "def": "Test tube holder", "termImg": "seed/img/chem-tubeholder.svg", "note": "Grips a single test tube so you can hold it over heat."}, {"id": "seed-chem-equipment-12", "term": "", "def": "Test tube rack", "termImg": "seed/img/chem-tuberack.svg", "note": "Holds test tubes upright."}, {"id": "seed-chem-equipment-13", "term": "", "def": "Beaker tongs", "termImg": "seed/img/chem-beakertongs.svg", "note": "Tongs shaped to grip and move hot beakers."}], "answerWith": "def"}, {"id": "seed-chem-intro", "rev": 1, "title": "Chem Intro + Philosophy of Science", "folder": "Chem", "description": "From your Quizlet export, with lab equipment drawings.", "cards": [{"id": "seed-chem-intro-0", "term": "Realism", "def": "The view that truth is objective and knowable, and that truth is independent of human thought and perception. The goal of science is to provide a TRUE description of the world"}, {"id": "seed-chem-intro-1", "term": "Anti-realism", "def": "The view that truth isn't entirely knowable. Explanations WORK but don't really describe reality as it is. The goal of science is to provide theories that are empirically adequate"}, {"id": "seed-chem-intro-2", "term": "Worldview", "def": "The set of foundational answers a person holds to seven basic questions. It looks a lot like a person's religious and/or political views"}, {"id": "seed-chem-intro-3", "term": "Element", "def": "A pure substance made of all the same kind of atoms"}, {"id": "seed-chem-intro-4", "term": "Compound", "def": "A pure substance made of atoms of different elements chemically bonded to each other"}, {"id": "seed-chem-intro-5", "term": "Mixture", "def": "A combination of more than one substance NOT chemically bonded to each other"}, {"id": "seed-chem-intro-6", "term": "Pure substance", "def": "A substance with a single, uniform composition. Elements and compounds are pure substances; mixtures are not"}, {"id": "seed-chem-intro-7", "term": "Homogeneous", "def": "A mixture that is uniform throughout the entire sample. Example: apple juice or hong cha. Solutions are homogeneous"}, {"id": "seed-chem-intro-8", "term": "Heterogeneous", "def": "A mixture that is NOT uniform throughout the entire sample. Example: bubble tea or orange juice. Suspensions are heterogeneous"}, {"id": "seed-chem-intro-9", "term": "Solid (as a phase)", "def": "No compressibility, very ordered, and its shape is INDEPENDENT of its container"}, {"id": "seed-chem-intro-10", "term": "Liquid (as a phase)", "def": "Slight compressibility, less ordered, and its shape is DEPENDENT on its container"}, {"id": "seed-chem-intro-11", "term": "Gas (as a phase)", "def": "Very compressible, very disordered, and its shape is DEPENDENT on its container"}, {"id": "seed-chem-intro-12", "term": "Significant figures (sig figs)", "def": "The digits in a measurement that are meaningful. They matter primarily because they convey honesty about the level of certainty in our measurements"}, {"id": "seed-chem-intro-13", "term": "Scientific notation", "def": "Writing a number as the product of a number between 1 and 10 and a power of 10. Example: 436 becomes 4.36 x 10^2"}, {"id": "seed-chem-intro-14", "term": "Physical change", "def": "A change that does NOT affect the chemical composition of the substance, such as melting, breaking, or freezing"}, {"id": "seed-chem-intro-15", "term": "Chemical change", "def": "A change IN the chemical composition of a substance, such as burning, rusting, decomposing, or digesting"}, {"id": "seed-chem-intro-16", "term": "Physical property", "def": "A property such as color, shape, size, density, odor, melting point, or boiling point"}, {"id": "seed-chem-intro-17", "term": "Chemical property", "def": "Reactivity, or the ability to form new compounds"}, {"id": "seed-chem-intro-18", "term": "The six philosophical considerations in science (from class)", "def": "1) What is the scientific pursuit?  2) What makes something “science” vs non-science?  3) How do we know what we know?  4) What makes a good experimental design?  5) What makes a good scientific explanation?  6) How do we handle changes in theories?"}, {"id": "seed-chem-intro-19", "term": "Realism vs anti-realism in one line", "def": "REALISM: truth is objective, knowable, independent of us, and science aims to describe the world truly. ANTI-REALISM: truth isn't fully knowable, explanations merely WORK, and science aims only to be empirically adequate"}, {"id": "seed-chem-intro-20", "term": "The seven worldview questions", "def": "1) What is prime reality?  2) What is the nature of external reality?  3) What is a human being?  4) What happens to a person at death?  5) Why is it possible to know anything at all?  6) How do we know what is right and wrong?  7) What is the meaning of human history?"}, {"id": "seed-chem-intro-21", "term": "Epistemology — how do we know what we know?", "def": "Observations and measurements in experimentation rely on our finite brains and senses. If our brains or senses are faulty, our observations might be inaccurate. And because we used those same brains and senses to build our measuring instruments, our measurements might be faulty too"}, {"id": "seed-chem-intro-22", "term": "What makes a good experimental design?", "def": "One independent and one dependent variable, all other variables controlled, blinded, a large n value, and reproducible results"}, {"id": "seed-chem-intro-23", "term": "What makes a good scientific explanation?", "def": "Simplicity, corresponds to existing data, broad scope, and predictive capacity"}, {"id": "seed-chem-intro-24", "term": "What makes something science vs non-science?", "def": "It typically uses what we call the scientific method, but not all sciences use all the steps. Also worth asking: is non-science necessarily bad or wrong?"}, {"id": "seed-chem-intro-25", "term": "Kuhn and the paradigm shift", "def": "Kuhn's view of scientific revolution. A paradigm shift is “the transfer of allegiance from paradigm to paradigm,” which is a conversion experience that cannot be forced. New paradigms are accepted more rapidly if powerful advocates exist, and the political and social climate affects acceptance too"}, {"id": "seed-chem-intro-26", "term": "Is scientific development linear?", "def": "Not necessarily. Nothing happens in a vacuum (think Copernicus), and it is an open question whether we are necessarily getting closer to the truth"}, {"id": "seed-chem-intro-27", "term": "Is the scientific method scientific?", "def": "No — the “scientific method” is really a PHILOSOPHICAL construct rather than a scientific one. Technically there is no single scientific method; there are several, depending on the field of study"}, {"id": "seed-chem-intro-28", "term": "The Nikola Tesla quote and what it illustrates", "def": "“To me, the universe is simply a great machine which never came into being and never will end. The human being is no exception to the natural order. Man, like the universe, is a machine.” It illustrates a worldview — his answers to what prime reality is and what a human being is"}, {"id": "seed-chem-intro-29", "term": "Rule for proper scientific notation", "def": "Every number can be written as the product of a number between 1 and 10 and a power of 10"}, {"id": "seed-chem-intro-30", "term": "436 in scientific notation", "def": "4.36 x 10^2"}, {"id": "seed-chem-intro-31", "term": "43,600,000 in scientific notation", "def": "4.36 x 10^7"}, {"id": "seed-chem-intro-32", "term": "0.00436 in scientific notation", "def": "4.36 x 10^-3"}, {"id": "seed-chem-intro-33", "term": "Which direction does the exponent go?", "def": "A number BIGGER than 10 gets a POSITIVE exponent. A number SMALLER than 1 gets a NEGATIVE exponent. Count how many places you moved the decimal"}, {"id": "seed-chem-intro-34", "term": "Why do sig figs exist at all? (the reasoning)", "def": "They convey honesty about the level of certainty in our measurements. In math class it may be fine to use the first 100 digits of a number, but in science we deal in REALITY — the digits you write should reflect what you actually measured"}, {"id": "seed-chem-intro-35", "term": "Sig fig rule: non-zero integers", "def": "They ALWAYS count as sig figs"}, {"id": "seed-chem-intro-36", "term": "Sig fig rule: leading zeros", "def": "Zeros that precede all of the non-zero integers NEVER count as sig figs"}, {"id": "seed-chem-intro-37", "term": "Sig fig rule: captive zeros", "def": "Zeros between non-zero digits ALWAYS count as sig figs"}, {"id": "seed-chem-intro-38", "term": "Sig fig rule: trailing zeros", "def": "Zeros to the right of all the non-zero digits count ONLY if followed by a decimal. Example: 20 has 1 sig fig, but 20. has 2 sig figs"}, {"id": "seed-chem-intro-39", "term": "Sig fig rule: exact numbers", "def": "Numbers obtained by counting or by definition have an INFINITE number of sig figs. Example: 100 cm is defined as 1 meter"}, {"id": "seed-chem-intro-40", "term": "Trailing zeros to the right of a decimal", "def": "They DO count as sig figs. Example: 1.230 has 4 sig figs"}, {"id": "seed-chem-intro-41", "term": "How many sig figs: 0.00123", "def": "3"}, {"id": "seed-chem-intro-42", "term": "How many sig figs: 1.230", "def": "4"}, {"id": "seed-chem-intro-43", "term": "How many sig figs: 1230", "def": "3 — the trailing zero does not count because there is no decimal after it"}, {"id": "seed-chem-intro-44", "term": "How many sig figs: 1230.", "def": "4 — the decimal makes the trailing zero count"}, {"id": "seed-chem-intro-45", "term": "How many sig figs: 0.001203000", "def": "7 — leading zeros don't count, the captive zero does, and the trailing zeros after the decimal do"}, {"id": "seed-chem-intro-46", "term": "How many sig figs: 1.23 x 10^4", "def": "3 — in scientific notation only the digits in front of the power of 10 count"}, {"id": "seed-chem-intro-47", "term": "Sig figs for multiplication and division", "def": "Your FINAL answer shouldn't have more sig figs than the FEWEST used in the calculation. Multiplying a 3-sig-fig number by a 4-sig-fig number gives a 3-sig-fig answer"}, {"id": "seed-chem-intro-48", "term": "Sig figs for addition and subtraction", "def": "Round your FINAL answer to the smallest PLACE VALUE known in all the numbers used. Example: 139.785 + 516.391 + 81.4 = 737.576, but 81.4 only knows the tenths place, so the answer is 737.6"}, {"id": "seed-chem-intro-49", "term": "The class shortcut for sig figs (Bottom Line slide)", "def": "Almost every calculation in this class involves 2–4 sig figs, so: carry all your digits through until the END, then round. Always round to THREE sig figs and we'll call it good"}, {"id": "seed-chem-intro-50", "term": "Uncertainty in measurement — how to read an instrument", "def": "Always read a measurement as an ESTIMATE between the two nearest markings visible on the device. Normally the reading falls between markings, not exactly on one"}, {"id": "seed-chem-intro-51", "term": "Uncertainty — what the last digit means", "def": "Assume the LAST number written is an estimate, with an uncertainty of +/- 1 in that last place. If you use that measurement in a calculation, the uncertainty carries over into your calculated value"}, {"id": "seed-chem-intro-52", "term": "The thermometer example", "def": "Reading 36.4 °C: the “36” is certain because you can see the markings, and the “.4” is uncertain, so it is 36.4 °C +/- 0.1 °C. That is 3 sig figs, so a calculation using it shouldn't have more than 3"}, {"id": "seed-chem-intro-53", "term": "Law vs theory — LAW", "def": "Often numerical (quantitative), based on calculations, and answers the “how” and “what” questions. Examples: the laws of gravity and conservation of mass"}, {"id": "seed-chem-intro-54", "term": "Law vs theory — THEORY", "def": "Often qualitative, answers the “why” questions. It is a MODEL — our best attempt at describing our best understanding of the truth, an interpretation of reality"}, {"id": "seed-chem-intro-55", "term": "What laws and theories have in common", "def": "Both are based on LOTS of data and experimentation. A scientific theory is much more than just a guess"}, {"id": "seed-chem-intro-56", "term": "Hypothesis vs theory — the trap", "def": "Common everyday usage of the word “theory” is really closer to a HYPOTHESIS in science. A hypothesis is the testable proposal you start with; a scientific theory is a well-supported model built on lots of data"}, {"id": "seed-chem-intro-57", "term": "The steps of the “scientific method” as listed in class", "def": "Observation, hypothesis, experiment, theory (model), law, prediction, experiment, and theory modified as needed"}, {"id": "seed-chem-intro-58", "term": "The 5 SI units from class", "def": "Mass = kilogram (kg), length = meter (m), time = second (s), temperature = Kelvin (K), volume = liter (L, or dm^3)"}, {"id": "seed-chem-intro-59", "term": "SI unit of mass", "def": "Kilogram, kg"}, {"id": "seed-chem-intro-60", "term": "SI unit of length", "def": "Meter, m"}, {"id": "seed-chem-intro-61", "term": "SI unit of time", "def": "Second, s"}, {"id": "seed-chem-intro-62", "term": "SI unit of temperature", "def": "Kelvin, K"}, {"id": "seed-chem-intro-63", "term": "SI unit of volume", "def": "Liter, L (also written dm^3)"}, {"id": "seed-chem-intro-64", "term": "Prefix: kilo", "def": "1000, or 10^3. Example: km"}, {"id": "seed-chem-intro-65", "term": "Prefix: deca", "def": "10, or 10^1. Example: Dm"}, {"id": "seed-chem-intro-66", "term": "Prefix: unit (no prefix)", "def": "1, or 10^0. Example: m"}, {"id": "seed-chem-intro-67", "term": "Prefix: deci", "def": "0.1, or 10^-1. Example: dm"}, {"id": "seed-chem-intro-68", "term": "Prefix: centi", "def": "0.01, or 10^-2. Example: cm"}, {"id": "seed-chem-intro-69", "term": "Prefix: milli", "def": "0.001, or 10^-3. Example: mm"}, {"id": "seed-chem-intro-70", "term": "Prefix: micro", "def": "0.000001, or 10^-6. Example: micrometer"}, {"id": "seed-chem-intro-71", "term": "Prefix: nano", "def": "0.000000001, or 10^-9. Example: nm"}, {"id": "seed-chem-intro-72", "term": "All prefixes in order, largest to smallest", "def": "kilo (10^3), deca (10^1), unit (10^0), deci (10^-1), centi (10^-2), milli (10^-3), micro (10^-6), nano (10^-9). They are all powers of ten"}, {"id": "seed-chem-intro-73", "term": "Why is the liter a DERIVED unit?", "def": "Because it is defined from length, not measured directly. A liter is defined as 1 dm^3 — a cube measuring 1 dm x 1 dm x 1 dm"}, {"id": "seed-chem-intro-74", "term": "1 mL equals what volume?", "def": "1 cm^3, sometimes abbreviated 1 cc. It is a cube 1 cm x 1 cm x 1 cm, and a milliliter is 0.001 L"}, {"id": "seed-chem-intro-75", "term": "How to do a unit conversion", "def": "You must know what is equivalent, and that pair of equivalents becomes your conversion factor. Set the conversion factor up as a RATIO — since both values are equivalent it is just like multiplying by 1 — so the unwanted unit cancels out"}, {"id": "seed-chem-intro-76", "term": "The check on any conversion", "def": "Make sure you end up with the proper units in your answer. All the other units should cancel out"}, {"id": "seed-chem-intro-77", "term": "Convert °F to °C", "def": "°C = (°F − 32) x 5/9"}, {"id": "seed-chem-intro-78", "term": "Convert °C to K", "def": "K = °C + 273.15"}, {"id": "seed-chem-intro-79", "term": "Convert K to °C", "def": "°C = K − 273.15"}, {"id": "seed-chem-intro-80", "term": "Convert °C to °F", "def": "°F = (°C x 9/5) + 32 — the reverse of the °F to °C formula"}, {"id": "seed-chem-intro-81", "term": "Why the K and °C formula is just addition", "def": "The degrees are the SAME SIZE on both scales; Kelvin simply starts lower. So you only shift by 273.15 and never multiply"}, {"id": "seed-chem-intro-82", "term": "Physical vs chemical CHANGE — the test", "def": "Ask whether the chemical composition changed. Physical change: composition is the same (melting, breaking, freezing). Chemical change: composition is different (burning, rusting, decomposing, digesting)"}, {"id": "seed-chem-intro-83", "term": "Physical vs chemical PROPERTY — the test", "def": "A physical property can be observed without changing what the substance is (color, shape, size, density, odor, melting point, boiling point). A chemical property is about reactivity — the ability to form new compounds"}, {"id": "seed-chem-intro-84", "term": "Sharpening a pencil", "def": "Physical change — the wood and graphite are still wood and graphite"}, {"id": "seed-chem-intro-85", "term": "Baking a cake", "def": "Chemical change"}, {"id": "seed-chem-intro-86", "term": "Solvent evaporating from fresh paint", "def": "Physical change"}, {"id": "seed-chem-intro-87", "term": "Burning charcoal", "def": "Chemical change"}, {"id": "seed-chem-intro-88", "term": "Water freezing on a sidewalk", "def": "Physical change"}, {"id": "seed-chem-intro-89", "term": "Frying an egg", "def": "Chemical change"}, {"id": "seed-chem-intro-90", "term": "The three phases compared by COMPRESSIBILITY", "def": "Solid = none, liquid = slight, gas = very"}, {"id": "seed-chem-intro-91", "term": "The three phases compared by ORDER", "def": "Solid = very ordered, liquid = less ordered, gas = very disordered"}, {"id": "seed-chem-intro-92", "term": "The three phases compared by SHAPE", "def": "Solid = independent of container. Liquid and gas = both dependent on container"}, {"id": "seed-chem-intro-93", "term": "Phase change: solid to liquid and back", "def": "Solid to liquid is MELTING; liquid to solid is FREEZING"}, {"id": "seed-chem-intro-94", "term": "Phase change: liquid to gas and back", "def": "Liquid to gas is BOILING; gas to liquid is CONDENSING"}, {"id": "seed-chem-intro-95", "term": "Phase change: solid to gas and back", "def": "Solid to gas is SUBLIMING; gas to solid is DEPOSING"}, {"id": "seed-chem-intro-96", "term": "Two main types of chemical bonding", "def": "IONIC — ions (charged atoms) are attracted to each other by electromagnetic attraction. COVALENT — atoms share each other's electrons"}, {"id": "seed-chem-intro-97", "term": "Where does the word “atom” come from?", "def": "The Greek word atomos"}, {"id": "seed-chem-intro-98", "term": "Element vs compound vs mixture at the molecular level (Figure 1.5)", "def": "An ELEMENT is all identical atoms. A COMPOUND is identical molecules made of two or more different elements bonded together. A MIXTURE shows two or more different kinds of particles side by side, not bonded"}, {"id": "seed-chem-intro-99", "term": "Physical methods of separating mixtures", "def": "Distillation, filtration, and chromatography"}, {"id": "seed-chem-intro-100", "term": "Chemical methods of separating mixtures", "def": "Substances can be used to chemically BIND one or more compounds in a mixture so they can be separated, or to chemically BREAK DOWN one or more compounds so the unaffected compound can be isolated"}, {"id": "seed-chem-intro-101", "term": "Density formula", "def": "Density = mass / volume"}, {"id": "seed-chem-intro-102", "term": "Usual density units in the high school lab", "def": "grams per milliliter (g/mL)"}, {"id": "seed-chem-intro-103", "term": "Why is density useful?", "def": "It is a very useful way of IDENTIFYING a substance. Gold has a different density than iron pyrite (fool's gold), so you can tell a fake by its density"}, {"id": "seed-chem-intro-104", "term": "Solve for mass or volume from density", "def": "mass = density x volume, and volume = mass / density"}, {"id": "seed-chem-intro-105", "term": "How do you find the volume of a regular shape?", "def": "Calculate it. Cubes, rectangular prisms, and cylinders can all be calculated easily from their dimensions"}, {"id": "seed-chem-intro-106", "term": "How do you find the volume of an IRREGULAR shape?", "def": "Water displacement. Accurately measure the water in a graduated cylinder, place the object in, read the new water level, and subtract the initial reading from the final reading. That difference is the volume of the object"}, {"id": "seed-chem-intro-107", "term": "Accuracy vs precision", "def": "ACCURACY is how close your measurement is to the “true” or accepted value. PRECISION is how close your measurements are to EACH OTHER. You can be precise and still be wrong"}, {"id": "seed-chem-intro-108", "term": "Lab equipment to be able to identify (the study guide's own list)", "def": "The flasks, beaker, buret, pipet, ring stand and various clamps, crucible, mortar & pestle, evaporating dish, test tube holder, test tube rack, and beaker tongs"}, {"id": "seed-chem-intro-109", "term": "Buret — what is it for?", "def": "A long graduated glass tube with a stopcock at the bottom, used to deliver a precisely measured, variable volume of liquid, typically for titration", "defImg": "seed/img/chem-buret.svg"}, {"id": "seed-chem-intro-110", "term": "Pipet — what is it for?", "def": "A slender tube used to transfer a precise, usually fixed volume of liquid", "defImg": "seed/img/chem-pipet.svg"}, {"id": "seed-chem-intro-111", "term": "Crucible — what is it for?", "def": "A small ceramic container used to heat substances to very high temperatures", "defImg": "seed/img/chem-crucible.svg"}, {"id": "seed-chem-intro-112", "term": "Mortar & pestle — what is it for?", "def": "A bowl (mortar) and a club-shaped tool (pestle) used to crush and grind solids into a powder", "defImg": "seed/img/chem-mortar.svg"}, {"id": "seed-chem-intro-113", "term": "Evaporating dish — what is it for?", "def": "A shallow dish used to evaporate a liquid away and leave the dissolved solid behind", "defImg": "seed/img/chem-evaporating.svg"}, {"id": "seed-chem-intro-114", "term": "Beaker vs flask", "def": "A BEAKER has straight sides and a wide mouth, for general mixing and heating. A FLASK has a narrower neck — an Erlenmeyer flask is cone-shaped and good for swirling without spilling, and a volumetric flask measures one precise volume", "defImg": "seed/img/chem-erlenmeyer.svg"}, {"id": "seed-chem-intro-115", "term": "Beaker tongs — what is it for?", "def": "Tongs shaped to grip a beaker so you can lift or move hot glassware without touching it", "defImg": "seed/img/chem-beakertongs.svg"}, {"id": "seed-chem-intro-116", "term": "Ring stand and clamps — what is it for?", "def": "A vertical stand with a heavy base that clamps hold apparatus to, so glassware can be suspended and heated hands-free", "defImg": "seed/img/chem-ringstand.svg"}]}, {"id": "seed-water", "rev": 1, "title": "Properties of Water (Topic 1.1)", "folder": "AP Bio", "description": "Your Properties of Water cards, with the diagrams from the slides.", "cards": [{"id": "seed-water-0", "term": "What is an atom?", "def": "The smallest stable unit of matter that retains the characteristics of an element."}, {"id": "seed-water-1", "term": "What charge does a proton have?", "def": "Positive (+)."}, {"id": "seed-water-2", "term": "What charge does a neutron have?", "def": "No charge; neutral."}, {"id": "seed-water-3", "term": "What charge does an electron have?", "def": "Negative (-)."}, {"id": "seed-water-4", "term": "Where are protons and neutrons located?", "def": "In the nucleus."}, {"id": "seed-water-5", "term": "Where are electrons located?", "def": "In orbitals surrounding the nucleus."}, {"id": "seed-water-6", "term": "How does electron energy change with distance from the nucleus?", "def": "Electrons farther from the nucleus occupy higher-energy orbitals."}, {"id": "seed-water-7", "term": "What are valence electrons?", "def": "Electrons in the outermost orbital; they are used to form chemical bonds."}, {"id": "seed-water-8", "term": "Why do valence electrons matter?", "def": "They determine how an atom interacts and bonds with other atoms."}, {"id": "seed-water-9", "term": "When is an atom electrically neutral?", "def": "When it has equal numbers of protons and electrons."}, {"id": "seed-water-10", "term": "What is an ion?", "def": "An atom or molecule with a net electrical charge."}, {"id": "seed-water-11", "term": "What is a cation?", "def": "A positively charged ion; it has fewer electrons than protons."}, {"id": "seed-water-12", "term": "What is an anion?", "def": "A negatively charged ion; it has more electrons than protons."}, {"id": "seed-water-13", "term": "What are the four main elements of life emphasized in the PowerPoint?", "def": "Carbon, hydrogen, oxygen, and nitrogen (CHON)."}, {"id": "seed-water-14", "term": "What does CHON stand for?", "def": "Carbon, Hydrogen, Oxygen, Nitrogen."}, {"id": "seed-water-15", "term": "What are trace elements?", "def": "Elements needed in relatively small amounts but still important for maintaining life and homeostasis."}, {"id": "seed-water-16", "term": "Why is carbon important to life?", "def": "Carbon forms the backbone of biological molecules and can form many different complex structures."}, {"id": "seed-water-17", "term": "How many valence electrons does carbon have?", "def": "4."}, {"id": "seed-water-18", "term": "How many covalent bonds can carbon form?", "def": "4."}, {"id": "seed-water-19", "term": "Why can carbon form such diverse molecules?", "def": "Its four valence electrons allow it to form four covalent bonds and many different molecular structures."}, {"id": "seed-water-20", "term": "How many bonds does hydrogen usually form?", "def": "1."}, {"id": "seed-water-21", "term": "How many bonds does oxygen usually form?", "def": "2."}, {"id": "seed-water-22", "term": "How many bonds does nitrogen usually form?", "def": "3."}, {"id": "seed-water-23", "term": "Which biomolecules contain carbon?", "def": "Carbohydrates, lipids, proteins, and nucleic acids."}, {"id": "seed-water-24", "term": "Why is nitrogen important to organisms?", "def": "It is needed to make proteins and nucleic acids."}, {"id": "seed-water-25", "term": "Why is phosphorus important to organisms?", "def": "It is needed to make nucleic acids and phospholipids, which are major components of cell membranes."}, {"id": "seed-water-26", "term": "What biomolecules contain nitrogen?", "def": "Proteins and nucleic acids."}, {"id": "seed-water-27", "term": "What biomolecules contain phosphorus?", "def": "Nucleic acids and phospholipids."}, {"id": "seed-water-28", "term": "What is electronegativity?", "def": "A measure of how strongly an atom attracts bonding electrons toward itself."}, {"id": "seed-water-29", "term": "Which is more electronegative: oxygen or nitrogen?", "def": "Oxygen."}, {"id": "seed-water-30", "term": "What happens when two bonded atoms have different electronegativities?", "def": "Electrons are shared unequally, producing a polar covalent bond and partial charges."}, {"id": "seed-water-31", "term": "What is a covalent bond?", "def": "A chemical bond formed when atoms share electrons."}, {"id": "seed-water-32", "term": "What is a polar covalent bond?", "def": "A covalent bond in which electrons are shared unequally.", "defImg": "seed/img/water-hbond.png"}, {"id": "seed-water-33", "term": "What is a nonpolar covalent bond?", "def": "A covalent bond in which electrons are shared relatively equally."}, {"id": "seed-water-34", "term": "What is an ionic interaction?", "def": "An attraction between oppositely charged ions."}, {"id": "seed-water-35", "term": "What is a hydrogen bond?", "def": "A weak attraction between a partially positive hydrogen and a nearby electronegative atom.", "defImg": "seed/img/water-hbond.png"}, {"id": "seed-water-36", "term": "Why is a water molecule polar?", "def": "Oxygen attracts the shared electrons more strongly than hydrogen, giving oxygen a partial negative charge and the hydrogens partial positive charges.", "defImg": "seed/img/water-hbond.png"}, {"id": "seed-water-37", "term": "What charge does oxygen have in water?", "def": "A partial negative charge (δ−)."}, {"id": "seed-water-38", "term": "What charge do the hydrogens have in water?", "def": "Partial positive charges (δ+)."}, {"id": "seed-water-39", "term": "What causes water's important biological properties?", "def": "Its polarity and its ability to form hydrogen bonds."}, {"id": "seed-water-40", "term": "Where does a hydrogen bond form between two water molecules?", "def": "Between the partially positive hydrogen of one water molecule and the partially negative oxygen of another.", "defImg": "seed/img/water-hbond.png"}, {"id": "seed-water-41", "term": "Are the O-H bonds within one water molecule hydrogen bonds?", "def": "No. They are polar covalent bonds.", "defImg": "seed/img/water-hbond.png"}, {"id": "seed-water-42", "term": "What is cohesion?", "def": "Attraction between water molecules caused by hydrogen bonding.", "defImg": "seed/img/water-cohesion.png"}, {"id": "seed-water-43", "term": "Cohesion = ?", "def": "Water sticking to water.", "defImg": "seed/img/water-cohesion.png"}, {"id": "seed-water-44", "term": "What is adhesion?", "def": "Attraction between water and other polar or charged substances."}, {"id": "seed-water-45", "term": "Adhesion = ?", "def": "Water sticking to something other than water."}, {"id": "seed-water-46", "term": "What causes cohesion?", "def": "Hydrogen bonds between water molecules."}, {"id": "seed-water-47", "term": "What causes adhesion?", "def": "Hydrogen bonds between water and other polar or charged molecules."}, {"id": "seed-water-48", "term": "What is surface tension?", "def": "Resistance at the surface of water produced by cohesion among water molecules.", "defImg": "seed/img/water-cohesion.png"}, {"id": "seed-water-49", "term": "What directly causes water's surface tension?", "def": "Cohesion."}, {"id": "seed-water-50", "term": "Why can some small organisms move across the surface of water?", "def": "Cohesion and hydrogen bonding create surface tension that resists disruption."}, {"id": "seed-water-51", "term": "What is capillary action?", "def": "The movement of water through a narrow space resulting from both adhesion and cohesion."}, {"id": "seed-water-52", "term": "Which two properties cause capillary action?", "def": "Cohesion and adhesion."}, {"id": "seed-water-53", "term": "How does adhesion contribute to capillary action?", "def": "Water is attracted to polar or charged surfaces and moves along them."}, {"id": "seed-water-54", "term": "How does cohesion contribute to capillary action?", "def": "Water molecules remain connected to one another as some molecules move upward."}, {"id": "seed-water-55", "term": "How do plants use capillary action?", "def": "Water adheres to vascular tissue while cohesion helps keep the water column together as water moves from roots toward leaves."}, {"id": "seed-water-56", "term": "Why is water important for transport in organisms?", "def": "Water's polarity and solvent properties allow substances to dissolve and be transported in fluids such as blood and plant sap."}, {"id": "seed-water-57", "term": "What is specific heat?", "def": "The amount of heat required to change the temperature of a substance."}, {"id": "seed-water-58", "term": "Does water have high or low specific heat capacity?", "def": "High specific heat capacity."}, {"id": "seed-water-59", "term": "Why does water resist temperature change?", "def": "Many hydrogen bonds must absorb energy before water molecules can move substantially faster."}, {"id": "seed-water-60", "term": "Why are hydrogen bonds important for temperature regulation?", "def": "They are individually weak but collectively require substantial energy to disrupt."}, {"id": "seed-water-61", "term": "How does high specific heat help living organisms?", "def": "It reduces rapid temperature changes and helps maintain homeostasis."}, {"id": "seed-water-62", "term": "Why can large bodies of water moderate environmental temperature?", "def": "Water absorbs or releases large amounts of heat with relatively small changes in its own temperature."}, {"id": "seed-water-63", "term": "Why does evaporation cool a surface?", "def": "The highest-energy water molecules leave as vapor, carrying thermal energy away."}, {"id": "seed-water-64", "term": "Why can sweating cool an organism?", "def": "Evaporation of water from the skin removes heat."}, {"id": "seed-water-65", "term": "What is a solvent?", "def": "A substance that dissolves other substances."}, {"id": "seed-water-66", "term": "Why is water an excellent solvent?", "def": "Its polarity allows it to interact with ions and polar molecules.", "defImg": "seed/img/water-sugar-dissolves.png"}, {"id": "seed-water-67", "term": "What is a solute?", "def": "A substance dissolved in a solvent."}, {"id": "seed-water-68", "term": "What happens when an ionic compound such as salt dissolves in water?", "def": "Water molecules surround and separate the ions."}, {"id": "seed-water-69", "term": "Why can water dissolve polar molecules such as sugars?", "def": "Water can form interactions, including hydrogen bonds, with their polar regions.", "defImg": "seed/img/water-sugar-dissolves.png"}, {"id": "seed-water-70", "term": "What is a hydration shell?", "def": "A layer of water molecules surrounding a dissolved ion or polar molecule.", "defImg": "seed/img/water-sugar-dissolves.png"}, {"id": "seed-water-71", "term": "What is hydrophilic?", "def": "Water-attracting; generally describes polar or charged substances that interact well with water."}, {"id": "seed-water-72", "term": "What is hydrophobic?", "def": "Water-repelling; generally describes nonpolar substances that do not interact favorably with water."}, {"id": "seed-water-73", "term": "Do nonpolar molecules dissolve well in water?", "def": "No."}, {"id": "seed-water-74", "term": "Why is water important for cellular metabolism?", "def": "Many reactants dissolve in water, allowing them to interact during chemical reactions."}, {"id": "seed-water-75", "term": "How does water support homeostasis?", "def": "It resists temperature change, transports dissolved substances, and participates in many chemical reactions."}, {"id": "seed-water-76", "term": "If water could no longer form hydrogen bonds, what properties would be affected?", "def": "Cohesion, adhesion, surface tension, capillary action, temperature resistance, and many solvent-related interactions would be disrupted."}, {"id": "seed-water-77", "term": "AP-style: Water molecules stick together in a droplet. What property explains this?", "def": "Cohesion."}, {"id": "seed-water-78", "term": "AP-style: Water sticks to the inside of plant vascular tissue. What property explains this?", "def": "Adhesion."}, {"id": "seed-water-79", "term": "AP-style: Water rises through a narrow tube. What properties explain this?", "def": "Adhesion to the tube plus cohesion between water molecules."}, {"id": "seed-water-80", "term": "AP-style: An organism maintains a relatively stable temperature despite environmental changes. Which water property helps?", "def": "High specific heat capacity."}, {"id": "seed-water-81", "term": "AP-style: Why can ionic compounds dissolve in water?", "def": "Water's partial charges interact with and surround the charged ions."}, {"id": "seed-water-82", "term": "AP-style: Which interaction is responsible for cohesion in water?", "def": "Hydrogen bonding between the oxygen of one water molecule and hydrogen of another."}]}, {"id": "seed-frq", "rev": 1, "title": "FRQ Practice: Macromolecules (model answers)", "folder": "AP Bio", "description": "Your two free-response questions. The front has the prompt and figure; the back has a full-credit paragraph answer, plus the scoring points.", "cards": [{"id": "seed-frq-0", "term": "FRQ 1 (fused B-cancer cells). (a) Describe the role of carbon in biological systems.", "def": "Carbon is the backbone of all biological macromolecules. Because carbon has four valence electrons, it can form four covalent bonds, which lets it build long chains, branches and rings. These carbon skeletons make up carbohydrates, lipids, proteins and nucleic acids, so the carbon in the growth medium is used by the cells to build new molecules and is also broken down for energy.", "termImg": "seed/img/frq1-bcells.png", "note": "Scoring point: carbon forms the backbone / is used to build macromolecules (carbohydrates, lipids, proteins, nucleic acids). Bonus detail: 4 covalent bonds allow chains and rings."}, {"id": "seed-frq-1", "term": "FRQ 1 (fused B-cancer cells). (b) Explain how, when the membranes fuse, the polar parts and the nonpolar parts of the phospholipids from one cell interact with the phospholipids from the other cell.", "def": "The polar, hydrophilic phosphate heads of the phospholipids from one cell will line up next to the polar heads of the other cell’s phospholipids, facing the watery environment inside and outside the cell. The nonpolar, hydrophobic fatty acid tails of one cell’s phospholipids will associate with the nonpolar tails of the other cell’s phospholipids through hydrophobic interactions, away from water. This lets the two membranes join into one continuous bilayer.", "termImg": "seed/img/frq1-bcells.png", "note": "Scoring points: (1) polar heads interact with polar heads / face water; (2) nonpolar tails interact with nonpolar tails through hydrophobic interactions in the middle of the bilayer."}, {"id": "seed-frq-2", "term": "FRQ 1 (fused B-cancer cells). (c) Make a claim about the most immediate effect on the fused B-cancer cells if they are transferred to a growth medium that lacks a source of nitrogen.", "def": "The fused B-cancer cells will no longer be able to make new proteins and nucleic acids, so they will stop growing and dividing.", "termImg": "seed/img/frq1-bcells.png", "note": "Scoring point: a clear claim that the cells can’t synthesize proteins and/or nucleic acids (DNA/RNA), and so stop growing/dividing."}, {"id": "seed-frq-3", "term": "FRQ 1 (fused B-cancer cells). (d) Provide reasoning with evidence based on the composition of biological macromolecules to support your claim.", "def": "Nitrogen is an element found in proteins and nucleic acids. Every amino acid contains nitrogen in its amino group (−NH₂), and every nucleotide contains a nitrogenous base such as adenine or guanine. Carbohydrates and lipids are made of mostly carbon, hydrogen and oxygen and do not require nitrogen. Without a nitrogen source, the cells cannot make new amino acids or nitrogenous bases, so they cannot build the proteins and DNA needed to grow and divide.", "termImg": "seed/img/frq1-bcells.png", "note": "Scoring point: link nitrogen to the amino group of amino acids and the nitrogenous bases of nucleotides (CHONS and CHONP), and state that carbohydrates/lipids lack N."}, {"id": "seed-frq-4", "term": "FRQ 2 (Receptor X). (a) Identify the process used to form the covalent peptide bonds that join amino acids into a polypeptide.", "def": "Peptide bonds are formed by dehydration synthesis (a condensation reaction), in which a water molecule is removed as the carboxyl group of one amino acid bonds to the amino group of the next.", "termImg": "seed/img/frq2-receptor.png", "note": "Scoring point: “dehydration synthesis” or “condensation reaction.”"}, {"id": "seed-frq-5", "term": "FRQ 2 (Receptor X). Which amino acids were substituted in Figure 1? (read the R groups)", "def": "Position 1 (CH(OH)CH₃) is threonine, unchanged. Position 2 changed from lysine (a long chain ending in ⁺NH₃, positively charged) to isoleucine (CH(CH₃)CH₂CH₃, nonpolar). Position 3 changed from glutamic acid (CH₂CH₂COO⁻, negatively charged) to alanine (CH₃, nonpolar). Positions 4 (valine) and 5 (glycine) are unchanged.", "termImg": "seed/img/frq2-receptor.png", "note": "How to read it: ⁺NH₃ at the end = basic/positive. COO⁻ = acidic/negative. Only CH and CH₃ = nonpolar/hydrophobic."}, {"id": "seed-frq-6", "term": "FRQ 2 (Receptor X). (b) Based on the R groups of the original and substituted amino acids, explain why Receptor X changed shape.", "def": "In the normal sequence, the second and third amino acids have charged R groups: one ends in a positively charged amino group (⁺NH₃) and the other ends in a negatively charged carboxyl group (COO⁻). These charged, hydrophilic R groups can form ionic bonds and hydrogen bonds that help hold the receptor in its folded shape. In the altered sequence they were replaced by amino acids with nonpolar, hydrophobic R groups that contain only carbon and hydrogen. The nonpolar R groups cannot form those ionic interactions and instead tend to cluster away from water, so the interactions between R groups change and the polypeptide folds into a different three-dimensional shape.", "termImg": "seed/img/frq2-receptor.png", "note": "Scoring point: original R groups were charged/polar (hydrophilic) and the new ones are nonpolar (hydrophobic), so the R-group interactions (ionic/hydrophobic) that determine folding change."}, {"id": "seed-frq-7", "term": "FRQ 2 (Receptor X). (c) Place an X on each level of protein structure expected to be altered by the substitutions.", "def": "X on PRIMARY and TERTIARY only. Primary changes because the amino acid sequence changed. Tertiary changes because R-group interactions changed. Secondary is not marked because Receptor X has no α helices or β sheets. Quaternary is not marked because Receptor X is a single polypeptide.", "termImg": "seed/img/frq2-receptor.png", "note": "The stem gives the clues: “contains no alpha-helices or beta sheets” (rules out secondary) and “single-polypeptide protein” (rules out quaternary)."}, {"id": "seed-frq-8", "term": "FRQ 2 (Receptor X). (d) Explain how the amino acid substitution is most likely to affect the function of Receptor X.", "def": "Because the substitution changed the three-dimensional shape of Receptor X, the region that recognizes and binds the specific molecule outside the cell will no longer have the correct shape or chemical properties. The molecule will not be able to bind to the receptor, or will bind less effectively, so the cells will not show their normal response to the molecule.", "termImg": "seed/img/frq2-receptor.png", "note": "Scoring point: changed shape → the molecule can no longer bind (or binds less) → the cell’s response is reduced or lost. Structure determines function."}]}, {"id": "seed-ch4-cells", "rev": 1, "title": "Bio Ch 4.1–4.2 — Cells & Organelles", "folder": "AP Bio", "description": "Microscopes, cell size, prokaryotes vs eukaryotes, every organelle and the cytoskeleton, with labeled diagrams, textbook figures, and notes on your quiz questions.", "cards": [{"id": "seed-ch4-0", "term": "Light microscope (LM)", "def": "Visible light passes through the specimen, then through glass lenses that bend (refract) the light to magnify the image. Magnifies up to about 1,000×; resolution limit about 0.2 µm (200 nm). CAN be used to view living cells.", "defImg": "seed/img/ch4-microscopes.svg", "note": "The limit is resolution, not magnification: past ~1,000× the image just gets bigger and blurrier."}, {"id": "seed-ch4-1", "term": "Magnification", "def": "The ratio of an object’s image size to its real size.", "note": "Bigger ≠ clearer. Clearer = resolution."}, {"id": "seed-ch4-2", "term": "Resolution", "def": "A measure of the clarity of the image: the minimum distance two points can be apart and still be seen as two separate points.", "defImg": "seed/img/ch4-size-scale.svg", "note": "Light microscope ≈ 0.2 µm (200 nm). Electron microscope ≈ 2 nm in practice. Super-resolution light ≈ 10–20 nm. Unaided eye ≈ 0.1 mm."}, {"id": "seed-ch4-3", "term": "Contrast", "def": "The difference in brightness between the light and dark areas of an image. Increased by staining or labeling parts of the cell."}, {"id": "seed-ch4-4", "term": "Why can’t a standard light microscope show ribosomes?", "def": "Ribosomes are only about 20 nm across, far smaller than the light microscope’s resolution limit of about 200 nm (0.2 µm). You need an electron microscope.", "defImg": "seed/img/ch4-size-scale.svg", "note": "Anything smaller than 0.2 µm (ribosomes, proteins, viruses, membranes) is below the LM limit."}, {"id": "seed-ch4-5", "term": "Electron microscope (EM)", "def": "Focuses a beam of ELECTRONS through or onto the specimen, using electromagnets as lenses. Electrons have a much shorter wavelength than light, so resolution is ~100× better (about 2 nm).", "defImg": "seed/img/ch4-microscopes.svg", "note": "Resolution is inversely related to wavelength: shorter wavelength → finer detail."}, {"id": "seed-ch4-6", "term": "Scanning electron microscope (SEM)", "def": "Electron beam scans the SURFACE of a specimen (usually coated with gold) → a 3-D-looking image of the outside. Example: surface texture of a hair, cilia on a cell.", "defImg": "seed/img/ch4-microscopes.svg", "note": "S = Surface."}, {"id": "seed-ch4-7", "term": "Transmission electron microscope (TEM)", "def": "Electron beam passes THROUGH a very thin slice stained with heavy-metal atoms → shows the INTERNAL structure of the cell (organelles, membranes).", "defImg": "seed/img/ch4-microscopes.svg", "note": "T = Through / inTernal."}, {"id": "seed-ch4-8", "term": "Main disadvantage of electron microscopy", "def": "Preparing the specimen kills the cells and can create artifacts (structures seen in the image that don’t exist in the living cell). The light microscope can view living cells."}, {"id": "seed-ch4-9", "term": "Artifact", "def": "A structural feature seen in a micrograph that does not exist in the living cell (caused by preparing the specimen)."}, {"id": "seed-ch4-10", "term": "Which microscope: watching a living white blood cell change shape?", "def": "Light microscope (for example phase-contrast or DIC), because it is the only type that can look at LIVING cells.", "defImg": "seed/img/ch4-microscopes.svg"}, {"id": "seed-ch4-11", "term": "Which microscope: the surface texture of a hair?", "def": "Scanning electron microscope (SEM): it images surfaces in 3-D.", "defImg": "seed/img/ch4-microscopes.svg"}, {"id": "seed-ch4-12", "term": "How do stains for light microscopy differ from stains for electron microscopy?", "def": "LM stains are colored dyes (or fluorescent tags) that absorb/emit light to add contrast. EM stains are heavy-metal atoms that deflect (scatter) electrons.", "note": "Concept Check 4.1 #1."}, {"id": "seed-ch4-13", "term": "Fluorescence microscopy", "def": "Specific molecules are labeled with fluorescent dyes or antibodies; they absorb ultraviolet light and emit visible light, showing where those molecules are in the cell.", "defImg": "seed/img/ch4-tb-microscopy.jpg"}, {"id": "seed-ch4-14", "term": "Confocal microscopy", "def": "A fluorescence technique that uses a laser to remove out-of-focus light from thick samples, giving a sharp single plane; many planes can be stacked into a 3-D image.", "defImg": "seed/img/ch4-tb-microscopy.jpg"}, {"id": "seed-ch4-15", "term": "Super-resolution microscopy", "def": "New light-microscope techniques that light up individual fluorescent molecules to \"break\" the 200 nm limit, resolving structures as small as 10–20 nm.", "defImg": "seed/img/ch4-tb-microscopy.jpg"}, {"id": "seed-ch4-16", "term": "Cryo-electron microscopy (cryo-EM)", "def": "A type of TEM where specimens are frozen at extremely low temperatures, so no preservatives are needed and structures are seen in their natural cellular state. Used for protein complexes and ribosomes."}, {"id": "seed-ch4-17", "term": "Cytology vs biochemistry", "def": "Cytology = the study of cell STRUCTURE (mainly with microscopes). Biochemistry = the study of the chemical processes (metabolism) of cells. Together they connect structure to function."}, {"id": "seed-ch4-18", "term": "Cell fractionation", "def": "Break cells apart and spin them in a centrifuge. Big parts form a pellet first; the liquid is spun again faster and longer. Pellet order: nuclei → mitochondria (and chloroplasts) → membrane pieces → ribosomes (smallest).", "defImg": "seed/img/ch4-fractionation.svg", "note": "Why it’s useful: you get lots of one organelle to test. Example: the fraction with respiration enzymes was full of mitochondria → mitochondria do cellular respiration."}, {"id": "seed-ch4-19", "term": "Metric units for cells", "def": "1 µm (micrometer) = 10⁻⁶ m = 1,000 nm. 1 nm (nanometer) = 10⁻⁹ m. Most cells are 1–100 µm.", "defImg": "seed/img/ch4-tb-size-range.jpg", "note": "Sizes: atom 0.1–0.2 nm · protein 5–10 nm · ribosome ~20 nm · virus 50–100 nm · bacterium 1–10 µm · mitochondrion ~1–10 µm · plant/animal cell 10–100 µm."}, {"id": "seed-ch4-20", "term": "Hooke vs van Leeuwenhoek", "def": "Robert Hooke (1665) first saw cell WALLS in dead cork/oak bark cells. Antoni van Leeuwenhoek first saw LIVING cells (“animalcules”) with his hand-crafted lenses."}, {"id": "seed-ch4-21", "term": "4 features ALL cells share", "def": "1. Plasma membrane  2. Cytosol  3. Chromosomes (DNA)  4. Ribosomes", "defImg": "seed/img/ch4-prok-vs-euk.svg", "note": "Remember “M-C-C-R”: membrane, cytosol, chromosomes, ribosomes."}, {"id": "seed-ch4-22", "term": "Prokaryotic cell", "def": "Cell of Bacteria and Archaea. No nucleus (DNA is in a nucleoid), no membrane-bound organelles, usually 1–5 µm. Has plasma membrane, ribosomes, cytosol, and usually a cell wall.", "termImg": "seed/img/ch4-prokaryote.svg", "defImg": "seed/img/ch4-tb-prokaryote.jpg", "note": "“Pro” = before, “karyon” = kernel/nucleus → “before nucleus.”"}, {"id": "seed-ch4-23", "term": "Eukaryotic cell", "def": "Cell of protists, fungi, animals and plants. DNA inside a nucleus with a double membrane, plus many membrane-bound organelles. Usually 10–100 µm.", "defImg": "seed/img/ch4-prok-vs-euk.svg", "note": "“Eu” = true → “true nucleus.”"}, {"id": "seed-ch4-24", "term": "Best clue that a cell is eukaryotic (not prokaryotic)", "def": "It has INTERNAL MEMBRANES: a membrane-enclosed nucleus and membrane-bound organelles (ER, Golgi, mitochondria…).", "defImg": "seed/img/ch4-prok-vs-euk.svg", "note": "Not a good clue: ribosomes, plasma membrane, DNA, flagella, or a cell wall (both types can have these)."}, {"id": "seed-ch4-25", "term": "Nucleoid", "def": "The region of a prokaryotic cell where the DNA is concentrated. It is NOT enclosed by a membrane.", "termImg": "seed/img/ch4-id-prok-nucleoid.svg", "defImg": "seed/img/ch4-tb-prokaryote.jpg"}, {"id": "seed-ch4-26", "term": "Fimbriae", "def": "Short hair-like attachment structures on the surface of some prokaryotes; they let the cell stick to surfaces and other cells.", "termImg": "seed/img/ch4-id-prok-fimbriae.svg", "note": "Fimbriae = many short hairs (stick). Flagella = few long tails (swim)."}, {"id": "seed-ch4-27", "term": "Capsule (glycocalyx)", "def": "Sticky outer coating (capsule or slime layer) of many prokaryotes, outside the cell wall; protects the cell and helps it stick.", "termImg": "seed/img/ch4-id-prok-capsule.svg"}, {"id": "seed-ch4-28", "term": "Prokaryotic cell wall", "def": "Rigid structure OUTSIDE the plasma membrane; keeps the cell’s shape and stops it from bursting.", "termImg": "seed/img/ch4-id-prok-wall.svg", "note": "The wall is rigid support. It does NOT decide what gets in; that’s the plasma membrane."}, {"id": "seed-ch4-29", "term": "Structure that regulates what passes in and out of a cell", "def": "The PLASMA MEMBRANE: a selective barrier. (Not the cell wall, not the capsule.)", "termImg": "seed/img/ch4-id-prok-pm.svg", "defImg": "seed/img/ch4-tb-membrane.jpg", "note": "You missed this one on the quiz. Order from outside in on a bacterium: capsule → cell wall → PLASMA MEMBRANE → cytoplasm. Selective = membrane."}, {"id": "seed-ch4-30", "term": "Cytosol vs cytoplasm", "def": "Cytosol = the semifluid, jelly-like substance inside all cells. Cytoplasm = the whole interior of the cell; in eukaryotes, the region between the nucleus and the plasma membrane."}, {"id": "seed-ch4-31", "term": "Plasma membrane", "def": "Selective barrier around every cell: a phospholipid bilayer with proteins; lets enough O₂, nutrients and wastes pass to serve the cell.", "termImg": "seed/img/ch4-id-animal-pm.svg", "defImg": "seed/img/ch4-tb-membrane.jpg", "note": "Hydrophobic tails in the middle, hydrophilic heads facing the water on both sides, proteins embedded, carbohydrate chains on the outside."}, {"id": "seed-ch4-32", "term": "Proteins found in the plasma membrane", "def": "Transport and signaling proteins like aquaporins (water channels), proton pumps, calcium channels and receptors.", "defImg": "seed/img/ch4-tb-membrane.jpg", "note": "From your Mastering quiz: aquaporin, proton pump and calcium channel all belong in the plasma membrane."}, {"id": "seed-ch4-33", "term": "Smallest cells", "def": "Mycoplasmas: bacteria 0.1–1.0 µm across; about the minimum size with enough DNA and enzymes to live and reproduce.", "note": "Typical bacteria are 1–5 µm (about 10× bigger); eukaryotic cells are 10–100 µm."}, {"id": "seed-ch4-34", "term": "Why are cells so small? (surface area to volume ratio)", "def": "As a cell grows, its volume increases faster (length³) than its surface area (length²), so the surface-to-volume ratio drops. The membrane can’t exchange materials fast enough for the huge volume.", "defImg": "seed/img/ch4-tb-surface-volume.jpg", "note": "A smaller object has a GREATER surface-to-volume ratio. Bigger organisms have more cells, not bigger cells."}, {"id": "seed-ch4-35", "term": "Surface-to-volume calculation (cube)", "def": "Surface area = 6 × side². Volume = side³. Ratio = SA ÷ V. Side 1: 6/1 = 6. Side 5: 150/125 = 1.2. 125 cubes of side 1: 750/125 = 6.", "defImg": "seed/img/ch4-tb-surface-volume.jpg", "note": "Same volume, cut into small pieces → much more surface."}, {"id": "seed-ch4-36", "term": "Surface area and volume of a sphere", "def": "Volume = 4/3 π r³.  Surface area = 4 π r².  (r = radius = half the diameter)", "note": "From the yeast budding exercise: use the scale bar to get the diameter first."}, {"id": "seed-ch4-37", "term": "Nerve cell shape 125 × 1 × 1: surface-to-volume?", "def": "SA = 4 sides × (125 × 1) + 2 ends × (1 × 1) = 502. V = 125. Ratio ≈ 4.0, much higher than a 5 × 5 × 5 cube with the same volume (1.2).", "note": "Long, thin shapes keep surface area high. Concept Check 4.2 “Draw it.”"}, {"id": "seed-ch4-38", "term": "Microvilli", "def": "Long, thin projections of the plasma membrane that increase surface area without much increase in volume (for example intestinal cells).", "termImg": "seed/img/ch4-id-animal-microvilli.svg", "note": "Their core is microfilaments (actin)."}, {"id": "seed-ch4-39", "term": "Why do eukaryotic cells have internal membranes? (compartmentalization)", "def": "Membranes divide the cell into compartments with different local environments, so incompatible processes can happen at the same time. Many enzymes are built right into the membranes.", "defImg": "seed/img/ch4-endomembrane.svg"}, {"id": "seed-ch4-40", "term": "Nucleus", "def": "Contains most of the cell’s DNA (genetic information) and controls the cell. Surrounded by a double-membrane nuclear envelope with pores.", "termImg": "seed/img/ch4-id-animal-nucleus.svg", "defImg": "seed/img/ch4-tb-animal-cell.jpg", "note": "Largest organelle in most animal cells."}, {"id": "seed-ch4-41", "term": "Nuclear envelope and nuclear pores", "def": "Double membrane around the nucleus, continuous with the ER. Nuclear pores let large molecules (mRNA, proteins, ribosome subunits) pass in and out.", "termImg": "seed/img/ch4-id-animal-envelope.svg", "note": "Quiz: a 19 nm protein made in the cytoplasm gets into the nucleus through a NUCLEAR PORE (it’s too big to cross the membrane)."}, {"id": "seed-ch4-42", "term": "Chromatin", "def": "DNA plus proteins inside the nucleus; condenses into visible chromosomes when the cell divides.", "defImg": "seed/img/ch4-tb-animal-cell.jpg"}, {"id": "seed-ch4-43", "term": "Nucleolus", "def": "Dense region inside the nucleus (no membrane) where ribosomal RNA is made and ribosome subunits are assembled.", "termImg": "seed/img/ch4-id-animal-nucleolus.svg", "note": "Quiz: nucleolus = assembles ribosomes."}, {"id": "seed-ch4-44", "term": "Ribosomes", "def": "Complexes of RNA + protein that make proteins. Free in the cytosol or bound to the rough ER / nuclear envelope. Found in ALL cells.", "termImg": "seed/img/ch4-id-animal-ribo.svg", "defImg": "seed/img/ch4-size-scale.svg", "note": "No membrane, so they are in prokaryotes too. At ~20 nm, a ribosome is bigger than a single protein or lipid molecule (quiz: “largest” among those choices)."}, {"id": "seed-ch4-45", "term": "Rough ER", "def": "Endoplasmic reticulum studded with ribosomes. Makes secretory proteins and membrane proteins, and makes new membrane.", "termImg": "seed/img/ch4-id-animal-rer.svg", "defImg": "seed/img/ch4-endomembrane.svg", "note": "Rough = ribosomes = proteins."}, {"id": "seed-ch4-46", "term": "Smooth ER", "def": "ER with NO ribosomes. Makes lipids (like steroids and phospholipids), detoxifies drugs and poisons, and stores calcium ions.", "termImg": "seed/img/ch4-id-animal-ser.svg", "defImg": "seed/img/ch4-endomembrane.svg", "note": "Smooth = no ribosomes = lipids. Quiz: smooth ER synthesizes lipids."}, {"id": "seed-ch4-47", "term": "Golgi apparatus", "def": "Stacks of flattened sacs that modify, sort, tag and package proteins and lipids from the ER into vesicles; ships them to their destination (\"post office\").", "termImg": "seed/img/ch4-id-animal-golgi.svg", "defImg": "seed/img/ch4-endomembrane.svg", "note": "Receives on the cis face (near ER), ships from the trans face."}, {"id": "seed-ch4-48", "term": "Lysosome", "def": "Membrane sac of hydrolytic (digestive) enzymes that break down macromolecules, food, and worn-out organelles. Mainly in animal cells.", "termImg": "seed/img/ch4-id-animal-lyso.svg", "defImg": "seed/img/ch4-endomembrane.svg", "note": "Plants usually use the central vacuole for this job."}, {"id": "seed-ch4-49", "term": "Peroxisome", "def": "Single-membrane organelle that does specialized metabolism (like breaking down fatty acids and toxins); makes hydrogen peroxide (H₂O₂) as a by-product and converts it to water.", "termImg": "seed/img/ch4-id-animal-perox.svg", "note": "In plant AND animal cells. Not part of the endomembrane system."}, {"id": "seed-ch4-50", "term": "Mitochondrion", "def": "Site of cellular respiration: makes most of the cell’s ATP. Double membrane; the folded inner membrane forms cristae. Has its own DNA.", "termImg": "seed/img/ch4-id-animal-mito.svg", "defImg": "seed/img/ch4-mito-chloro.svg", "note": "Found in BOTH plant and animal cells. Plants do photosynthesis AND cellular respiration."}, {"id": "seed-ch4-51", "term": "Chloroplast", "def": "Site of photosynthesis: converts light (solar) energy into chemical energy stored in sugar. Contains chlorophyll in thylakoid membranes; stacks = grana; fluid = stroma. Has its own DNA.", "termImg": "seed/img/ch4-id-plant-chloro.svg", "defImg": "seed/img/ch4-mito-chloro.svg", "note": "Plants and algae only. Quiz: thylakoids + stroma, chlorophyll, solar → chemical energy."}, {"id": "seed-ch4-52", "term": "Mitochondria and chloroplasts have in common…", "def": "Both have a double membrane, their own DNA and ribosomes, make ATP with ATP synthase, and grow/divide on their own; evidence they came from engulfed prokaryotes (endosymbiosis).", "defImg": "seed/img/ch4-mito-chloro.svg", "note": "Quiz: ATP synthase is found in BOTH chloroplasts and mitochondria."}, {"id": "seed-ch4-53", "term": "Central vacuole", "def": "Large sac in mature plant cells: stores water, ions and wastes; keeps turgor pressure; regulates the cytoplasm; helps the cell grow by enlarging; can break down macromolecules.", "termImg": "seed/img/ch4-id-plant-vacuole.svg", "defImg": "seed/img/ch4-tb-plant-cell.jpg", "note": "Its membrane is the tonoplast."}, {"id": "seed-ch4-54", "term": "Plant cell wall", "def": "Rigid layer OUTSIDE the plasma membrane made of cellulose fibrils (plus other polysaccharides and protein): protects the cell, keeps its shape, prevents it from taking up too much water and bursting.", "termImg": "seed/img/ch4-id-plant-wall.svg", "defImg": "seed/img/ch4-tb-plant-cell.jpg", "note": "Plants: cellulose. Fungi: chitin. Bacteria: peptidoglycan. Animals: NO wall."}, {"id": "seed-ch4-55", "term": "Plasmodesmata", "def": "Channels through plant cell walls that connect the cytoplasm of neighboring cells.", "termImg": "seed/img/ch4-id-plant-plasmo.svg", "defImg": "seed/img/ch4-tb-plant-cell.jpg"}, {"id": "seed-ch4-56", "term": "Centrosome and centrioles", "def": "Centrosome = region near the nucleus where the cell’s microtubules start. In animal cells it contains a pair of centrioles.", "termImg": "seed/img/ch4-id-animal-centro.svg", "note": "Quiz: centrioles = animal cells only."}, {"id": "seed-ch4-57", "term": "Flagellum (eukaryotic)", "def": "Long whip-like motility structure made of a cluster of microtubules (9+2 arrangement) inside an extension of the plasma membrane; dynein motors bend it. Example: sperm.", "termImg": "seed/img/ch4-id-animal-flagellum.svg", "defImg": "seed/img/ch4-9plus2.svg", "note": "Prokaryotes also have flagella (built differently), so flagella are “both” on a prokaryote/eukaryote sort."}, {"id": "seed-ch4-58", "term": "Cytoskeleton", "def": "Network of protein fibers (microtubules, microfilaments, intermediate filaments) that gives the cell its shape, anchors organelles, and helps the cell and its parts move.", "termImg": "seed/img/ch4-id-animal-cyto.svg", "defImg": "seed/img/ch4-cytoskeleton.svg", "note": "Quiz: cytoskeleton = defines cell shape. Found in plant and animal cells."}, {"id": "seed-ch4-59", "term": "Microtubules", "def": "Thickest fibers: hollow tubes of TUBULIN. Build cilia and flagella (dynein motors), grow out from the centrosome, act as tracks for vesicles, and separate chromosomes.", "defImg": "seed/img/ch4-cytoskeleton.svg", "note": "Quiz: flagella, dynein, centrosomes → microtubules."}, {"id": "seed-ch4-60", "term": "Microfilaments", "def": "Thinnest fibers: two twisted chains of ACTIN. Muscle contraction (with myosin), pseudopodia (amoeba crawling), cytoplasmic streaming, microvilli core.", "defImg": "seed/img/ch4-cytoskeleton.svg", "note": "Quiz: pseudopodia and myosin in muscle → microfilaments."}, {"id": "seed-ch4-61", "term": "Intermediate filaments", "def": "Middle-size, rope-like fibers (keratin family). Bear tension and ANCHOR the nucleus and other organelles in place. NOT used for movement.", "defImg": "seed/img/ch4-cytoskeleton.svg", "note": "Quiz: anchor the nucleus, not used in movement → intermediate filaments."}, {"id": "seed-ch4-62", "term": "9 + 2 arrangement", "def": "Cross-section of a cilium or eukaryotic flagellum: 9 outer doublets of microtubules around 2 central microtubules. Dynein arms make the doublets slide so it bends.", "defImg": "seed/img/ch4-9plus2.svg"}, {"id": "seed-ch4-63", "term": "Plant cells only / animal cells only / both", "def": "PLANT only: chloroplasts, cellulose cell wall, central vacuole, plasmodesmata. ANIMAL only: centrioles, lysosomes, flagella (most), microvilli. BOTH: nucleus, ER, Golgi, ribosomes, mitochondria, peroxisomes, cytoskeleton, plasma membrane.", "defImg": "seed/img/ch4-plant-vs-animal.svg"}, {"id": "seed-ch4-64", "term": "Do plant cells do cellular respiration?", "def": "YES. Plant cells have mitochondria and do cellular respiration, as well as photosynthesis in chloroplasts.", "defImg": "seed/img/ch4-mito-chloro.svg", "note": "Common trap: “plants do photosynthesis instead of respiration” is WRONG."}, {"id": "seed-ch4-65", "term": "Endomembrane system: parts", "def": "Nuclear envelope, ER (rough and smooth), Golgi apparatus, lysosomes, vacuoles, vesicles, and the plasma membrane.", "defImg": "seed/img/ch4-endomembrane.svg", "note": "NOT included: mitochondria, chloroplasts, peroxisomes, ribosomes."}, {"id": "seed-ch4-66", "term": "Path of a secreted protein", "def": "Ribosome on rough ER → inside the ER → transport vesicle → Golgi (modified, sorted) → vesicle → plasma membrane → secreted by exocytosis.", "defImg": "seed/img/ch4-endomembrane.svg"}, {"id": "seed-ch4-67", "term": "Label the animal cell", "def": "See the labeled diagram: plasma membrane, nucleus (envelope, nucleolus), rough ER, smooth ER, Golgi, ribosomes, mitochondria, lysosome, peroxisome, centrosome, cytoskeleton, microvilli, flagellum.", "defImg": "seed/img/ch4-animal-cell.svg"}, {"id": "seed-ch4-68", "term": "Label the plant cell", "def": "See the labeled diagram: cell wall, plasma membrane, central vacuole, chloroplasts, nucleus, rough and smooth ER, Golgi, mitochondria, peroxisome, ribosomes, cytoskeleton, plasmodesmata.", "defImg": "seed/img/ch4-plant-cell.svg"}, {"id": "seed-ch4-69", "term": "Label the bacterium", "def": "From outside in: fimbriae, capsule, cell wall, plasma membrane; inside: nucleoid (DNA) and ribosomes; flagellum for swimming.", "defImg": "seed/img/ch4-prokaryote.svg"}]}, {"id": "seed-ch4-pid", "rev": 1, "title": "Organelle ID — Where Is It Found? What Is It?", "folder": "AP Bio", "description": "37 pictures of an animal cell, a plant cell and a bacterium with ONE structure highlighted. Use the Picture ID test: say where it’s found, then name it.", "answerWith": "def", "cards": [{"id": "seed-ch4id-animal-flagellum", "term": "", "termImg": "seed/img/ch4-id-animal-flagellum.svg", "def": "Flagellum (both prokaryotes & eukaryotes)", "cls": "Both prokaryotes & eukaryotes", "name": "Flagellum", "detail": "Long whip-like tail for movement. In eukaryotes: microtubules (9+2) bent by dynein.", "note": "In this animal cell. One long tail sticking out of the cell (e.g., a sperm cell). Prokaryotes have flagella too, built differently."}, {"id": "seed-ch4id-animal-pm", "term": "", "termImg": "seed/img/ch4-id-animal-pm.svg", "def": "Plasma membrane (both prokaryotes & eukaryotes)", "cls": "Both prokaryotes & eukaryotes", "name": "Plasma membrane", "detail": "Selective barrier (phospholipid bilayer + proteins) that controls what enters and leaves.", "note": "In this animal cell. Outermost boundary of the cytoplasm. In plants it sits just inside the wall; in bacteria just inside the cell wall."}, {"id": "seed-ch4id-animal-microvilli", "term": "", "termImg": "seed/img/ch4-id-animal-microvilli.svg", "def": "Microvilli (animal cells only)", "cls": "Animal cells only", "name": "Microvilli", "detail": "Finger-like projections that increase surface area (e.g., intestine cells).", "note": "In this animal cell. Bumps/fingers sticking out of the membrane; core of microfilaments."}, {"id": "seed-ch4id-animal-cyto", "term": "", "termImg": "seed/img/ch4-id-animal-cyto.svg", "def": "Cytoskeleton (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Cytoskeleton", "detail": "Protein fibers (microtubules, microfilaments, intermediate filaments): shape, support, movement.", "note": "In this animal cell. Thin lines/network running through the cytoplasm, especially under the membrane."}, {"id": "seed-ch4id-animal-rer", "term": "", "termImg": "seed/img/ch4-id-animal-rer.svg", "def": "Rough ER (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Rough ER", "detail": "Studded with ribosomes: makes secretory & membrane proteins; makes membrane.", "note": "In this animal cell. Stacked sheets hugging the nucleus, covered with dots (ribosomes)."}, {"id": "seed-ch4id-animal-ser", "term": "", "termImg": "seed/img/ch4-id-animal-ser.svg", "def": "Smooth ER (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Smooth ER", "detail": "No ribosomes: makes lipids (steroids), detoxifies drugs/poisons, stores Ca²⁺.", "note": "In this animal cell. Tube network like the rough ER but with NO dots."}, {"id": "seed-ch4id-animal-nucleus", "term": "", "termImg": "seed/img/ch4-id-animal-nucleus.svg", "def": "Nucleus (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Nucleus", "detail": "Holds most of the DNA (genetic info); controls the cell. Largest organelle.", "note": "In this animal cell. Big round organelle with a double membrane, pores and a dark nucleolus inside."}, {"id": "seed-ch4id-animal-envelope", "term": "", "termImg": "seed/img/ch4-id-animal-envelope.svg", "def": "Nuclear envelope (with pores) (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Nuclear envelope (with pores)", "detail": "Double membrane around the nucleus; pores let RNA and proteins in/out. Continuous with the ER.", "note": "In this animal cell. The (dashed-looking) double boundary of the nucleus; gaps are nuclear pores."}, {"id": "seed-ch4id-animal-nucleolus", "term": "", "termImg": "seed/img/ch4-id-animal-nucleolus.svg", "def": "Nucleolus (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Nucleolus", "detail": "Makes ribosomal RNA and assembles ribosome subunits. No membrane.", "note": "In this animal cell. Dark spot INSIDE the nucleus."}, {"id": "seed-ch4id-animal-golgi", "term": "", "termImg": "seed/img/ch4-id-animal-golgi.svg", "def": "Golgi apparatus (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Golgi apparatus", "detail": "Modifies, sorts, tags and packages proteins into vesicles (\"post office\").", "note": "In this animal cell. Stack of curved flattened sacs (like pancakes) with small vesicles budding off the ends."}, {"id": "seed-ch4id-animal-mito", "term": "", "termImg": "seed/img/ch4-id-animal-mito.svg", "def": "Mitochondrion (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Mitochondrion", "detail": "Cellular respiration: makes most of the cell’s ATP. Has its own DNA.", "note": "In this animal cell. Oval with folded inner membrane (cristae zig-zags). In plant AND animal cells."}, {"id": "seed-ch4id-animal-lyso", "term": "", "termImg": "seed/img/ch4-id-animal-lyso.svg", "def": "Lysosome (animal cells only)", "cls": "Animal cells only", "name": "Lysosome", "detail": "Digestive sac: hydrolytic enzymes break down macromolecules, old organelles, food.", "note": "In this animal cell. Small single-membrane sphere with enzymes (dots) inside. Plants use the vacuole for this job."}, {"id": "seed-ch4id-animal-perox", "term": "", "termImg": "seed/img/ch4-id-animal-perox.svg", "def": "Peroxisome (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Peroxisome", "detail": "Breaks down fatty acids/toxins; makes H₂O₂ and converts it to water.", "note": "In this animal cell. Small single-membrane sphere, often with a crystal-like core."}, {"id": "seed-ch4id-animal-centro", "term": "", "termImg": "seed/img/ch4-id-animal-centro.svg", "def": "Centrosome (centrioles) (animal cells only)", "cls": "Animal cells only", "name": "Centrosome (centrioles)", "detail": "Where microtubules start (organizing center); has a pair of centrioles.", "note": "In this animal cell. Two little barrels at right angles, with fibers radiating out, near the nucleus."}, {"id": "seed-ch4id-animal-ribo", "term": "", "termImg": "seed/img/ch4-id-animal-ribo.svg", "def": "Ribosomes (both prokaryotes & eukaryotes)", "cls": "Both prokaryotes & eukaryotes", "name": "Ribosomes", "detail": "Make proteins. Free in cytosol or bound to rough ER / nuclear envelope. Not membrane-bound.", "note": "In this animal cell. Tiny dots. Every cell has them, which is why they are in prokaryotes too."}, {"id": "seed-ch4id-plant-wall", "term": "", "termImg": "seed/img/ch4-id-plant-wall.svg", "def": "Cell wall (cellulose) (plant cells only)", "cls": "Plant cells only", "name": "Cell wall (cellulose)", "detail": "Rigid layer outside the membrane made of cellulose fibrils: protects, keeps shape, prevents bursting.", "note": "In this plant cell. Thick green border OUTSIDE the plasma membrane. (Bacteria have walls too, but made of peptidoglycan.)"}, {"id": "seed-ch4id-plant-pm", "term": "", "termImg": "seed/img/ch4-id-plant-pm.svg", "def": "Plasma membrane (both prokaryotes & eukaryotes)", "cls": "Both prokaryotes & eukaryotes", "name": "Plasma membrane", "detail": "Selective barrier (phospholipid bilayer + proteins) that controls what enters and leaves.", "note": "In this plant cell. Outermost boundary of the cytoplasm. In plants it sits just inside the wall; in bacteria just inside the cell wall."}, {"id": "seed-ch4id-plant-plasmo", "term": "", "termImg": "seed/img/ch4-id-plant-plasmo.svg", "def": "Plasmodesmata (plant cells only)", "cls": "Plant cells only", "name": "Plasmodesmata", "detail": "Channels through cell walls connecting cytoplasm of neighboring plant cells.", "note": "In this plant cell. Small tunnels crossing the cell wall."}, {"id": "seed-ch4id-plant-vacuole", "term": "", "termImg": "seed/img/ch4-id-plant-vacuole.svg", "def": "Central vacuole (plant cells only)", "cls": "Plant cells only", "name": "Central vacuole", "detail": "Huge sac: stores water/ions/wastes, keeps turgor pressure, helps the cell grow; can digest.", "note": "In this plant cell. Largest thing in a mature plant cell; surrounded by the tonoplast membrane."}, {"id": "seed-ch4id-plant-rer", "term": "", "termImg": "seed/img/ch4-id-plant-rer.svg", "def": "Rough ER (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Rough ER", "detail": "Studded with ribosomes: makes secretory & membrane proteins; makes membrane.", "note": "In this plant cell. Stacked sheets hugging the nucleus, covered with dots (ribosomes)."}, {"id": "seed-ch4id-plant-nucleus", "term": "", "termImg": "seed/img/ch4-id-plant-nucleus.svg", "def": "Nucleus (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Nucleus", "detail": "Holds most of the DNA (genetic info); controls the cell. Largest organelle.", "note": "In this plant cell. Big round organelle with a double membrane, pores and a dark nucleolus inside."}, {"id": "seed-ch4id-plant-envelope", "term": "", "termImg": "seed/img/ch4-id-plant-envelope.svg", "def": "Nuclear envelope (with pores) (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Nuclear envelope (with pores)", "detail": "Double membrane around the nucleus; pores let RNA and proteins in/out. Continuous with the ER.", "note": "In this plant cell. The (dashed-looking) double boundary of the nucleus; gaps are nuclear pores."}, {"id": "seed-ch4id-plant-nucleolus", "term": "", "termImg": "seed/img/ch4-id-plant-nucleolus.svg", "def": "Nucleolus (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Nucleolus", "detail": "Makes ribosomal RNA and assembles ribosome subunits. No membrane.", "note": "In this plant cell. Dark spot INSIDE the nucleus."}, {"id": "seed-ch4id-plant-ser", "term": "", "termImg": "seed/img/ch4-id-plant-ser.svg", "def": "Smooth ER (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Smooth ER", "detail": "No ribosomes: makes lipids (steroids), detoxifies drugs/poisons, stores Ca²⁺.", "note": "In this plant cell. Tube network like the rough ER but with NO dots."}, {"id": "seed-ch4id-plant-golgi", "term": "", "termImg": "seed/img/ch4-id-plant-golgi.svg", "def": "Golgi apparatus (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Golgi apparatus", "detail": "Modifies, sorts, tags and packages proteins into vesicles (\"post office\").", "note": "In this plant cell. Stack of curved flattened sacs (like pancakes) with small vesicles budding off the ends."}, {"id": "seed-ch4id-plant-mito", "term": "", "termImg": "seed/img/ch4-id-plant-mito.svg", "def": "Mitochondrion (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Mitochondrion", "detail": "Cellular respiration: makes most of the cell’s ATP. Has its own DNA.", "note": "In this plant cell. Oval with folded inner membrane (cristae zig-zags). In plant AND animal cells."}, {"id": "seed-ch4id-plant-chloro", "term": "", "termImg": "seed/img/ch4-id-plant-chloro.svg", "def": "Chloroplast (plant cells only)", "cls": "Plant cells only", "name": "Chloroplast", "detail": "Photosynthesis: light energy → chemical energy in sugar. Chlorophyll in thylakoids.", "note": "In this plant cell. Green oval with stacks (grana) of thylakoid discs inside."}, {"id": "seed-ch4id-plant-perox", "term": "", "termImg": "seed/img/ch4-id-plant-perox.svg", "def": "Peroxisome (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Peroxisome", "detail": "Breaks down fatty acids/toxins; makes H₂O₂ and converts it to water.", "note": "In this plant cell. Small single-membrane sphere, often with a crystal-like core."}, {"id": "seed-ch4id-plant-cyto", "term": "", "termImg": "seed/img/ch4-id-plant-cyto.svg", "def": "Cytoskeleton (eukaryotes only (plant & animal))", "cls": "Eukaryotes only (plant & animal)", "name": "Cytoskeleton", "detail": "Protein fibers (microtubules, microfilaments, intermediate filaments): shape, support, movement.", "note": "In this plant cell. Thin lines/network running through the cytoplasm, especially under the membrane."}, {"id": "seed-ch4id-plant-ribo", "term": "", "termImg": "seed/img/ch4-id-plant-ribo.svg", "def": "Ribosomes (both prokaryotes & eukaryotes)", "cls": "Both prokaryotes & eukaryotes", "name": "Ribosomes", "detail": "Make proteins. Free in cytosol or bound to rough ER / nuclear envelope. Not membrane-bound.", "note": "In this plant cell. Tiny dots. Every cell has them, which is why they are in prokaryotes too."}, {"id": "seed-ch4id-prok-capsule", "term": "", "termImg": "seed/img/ch4-id-prok-capsule.svg", "def": "Capsule (glycocalyx) (prokaryotes only)", "cls": "Prokaryotes only", "name": "Capsule (glycocalyx)", "detail": "Sticky outer coat (capsule or slime layer): protects the cell and helps it stick.", "note": "In this bacterium. Outermost jelly layer, outside the cell wall."}, {"id": "seed-ch4id-prok-fimbriae", "term": "", "termImg": "seed/img/ch4-id-prok-fimbriae.svg", "def": "Fimbriae (prokaryotes only)", "cls": "Prokaryotes only", "name": "Fimbriae", "detail": "Short hair-like attachment structures: stick to surfaces and other cells.", "note": "In this bacterium. Many short hairs all over the surface (flagella are few and long)."}, {"id": "seed-ch4id-prok-wall", "term": "", "termImg": "seed/img/ch4-id-prok-wall.svg", "def": "Cell wall (prokaryote) (both prokaryotes & eukaryotes)", "cls": "Both prokaryotes & eukaryotes", "name": "Cell wall (prokaryote)", "detail": "Rigid layer outside the plasma membrane: keeps shape and prevents bursting. Bacterial wall = peptidoglycan.", "note": "In this bacterium. Stiff layer between the capsule (outside) and plasma membrane (inside)."}, {"id": "seed-ch4id-prok-pm", "term": "", "termImg": "seed/img/ch4-id-prok-pm.svg", "def": "Plasma membrane (both prokaryotes & eukaryotes)", "cls": "Both prokaryotes & eukaryotes", "name": "Plasma membrane", "detail": "Selective barrier (phospholipid bilayer + proteins) that controls what enters and leaves.", "note": "In this bacterium. Outermost boundary of the cytoplasm. In plants it sits just inside the wall; in bacteria just inside the cell wall."}, {"id": "seed-ch4id-prok-nucleoid", "term": "", "termImg": "seed/img/ch4-id-prok-nucleoid.svg", "def": "Nucleoid (prokaryotes only)", "cls": "Prokaryotes only", "name": "Nucleoid", "detail": "Region where the prokaryote’s DNA is. NOT enclosed by a membrane.", "note": "In this bacterium. Tangled DNA in the middle of a bacterium, no membrane around it."}, {"id": "seed-ch4id-prok-ribo", "term": "", "termImg": "seed/img/ch4-id-prok-ribo.svg", "def": "Ribosomes (both prokaryotes & eukaryotes)", "cls": "Both prokaryotes & eukaryotes", "name": "Ribosomes", "detail": "Make proteins. Free in cytosol or bound to rough ER / nuclear envelope. Not membrane-bound.", "note": "In this bacterium. Tiny dots. Every cell has them, which is why they are in prokaryotes too."}, {"id": "seed-ch4id-prok-flag", "term": "", "termImg": "seed/img/ch4-id-prok-flag.svg", "def": "Flagellum (both prokaryotes & eukaryotes)", "cls": "Both prokaryotes & eukaryotes", "name": "Flagellum", "detail": "Locomotion: the bacterium spins it like a propeller.", "note": "In this bacterium. Long tail off one end. Much longer than fimbriae."}], "pid": {"q1": "Where is this structure found?", "q2": "Name the highlighted structure.", "intro": "say where the highlighted structure is found (prokaryotes only, both, eukaryotes, plant only, animal only)", "k1": "Where found", "order": ["Prokaryotes only", "Both prokaryotes & eukaryotes", "Eukaryotes only (plant & animal)", "Plant cells only", "Animal cells only"]}}, {"id": "seed-mcq-ch4", "rev": 1, "kind": "mcq", "title": "Ch 4 Cells — Quiz Practice (Mastering + AP style)", "folder": "AP Bio", "description": "62 questions: your Mastering cell-structure quiz rewritten (including the plasma-membrane one you missed), lettered diagrams, highlighted-organelle pictures, microscopes, cell size and the endomembrane system.", "cards": [], "questions": [{"id": "seed-mcq-ch4-q0", "stem": "Which of these is the LARGEST?", "img": "seed/img/ch4-size-scale.svg", "choices": ["A ribosome", "A glucose molecule", "A phospholipid molecule", "A single protein molecule"], "answer": 0, "why": "A ribosome (~20 nm) is a big complex of RNA and many proteins, so it is bigger than any single protein (5–10 nm), lipid (2–5 nm) or small molecule (~1 nm)."}, {"id": "seed-mcq-ch4-q1", "stem": "A protein 19 nm wide is made in the cytoplasm and must get into the nucleus. How does it enter?", "img": null, "choices": ["Through the nucleolus", "Through a nuclear pore", "It is carried by the Golgi apparatus into the nucleus", "By diffusing straight through the phospholipid bilayer of the nuclear envelope"], "answer": 1, "why": "Large molecules can’t cross the double membrane; nuclear pores are the channels that let proteins in and mRNA/ribosome subunits out."}, {"id": "seed-mcq-ch4-q2", "stem": "ATP synthase would be found in which organelles?", "img": "seed/img/ch4-mito-chloro.svg", "choices": ["Nucleus and rough ER", "Chloroplasts only", "Mitochondria and chloroplasts", "Mitochondria only"], "answer": 2, "why": "Both energy organelles make ATP with ATP synthase: mitochondria during cellular respiration, chloroplasts during the light reactions of photosynthesis."}, {"id": "seed-mcq-ch4-q3", "stem": "Which group of proteins would all be found in the plasma membrane?", "img": null, "choices": ["Hemoglobin, amylase, insulin", "Aquaporin, proton pump, calcium channel", "Actin, myosin, tubulin", "Ribosomal proteins, histones, DNA polymerase"], "answer": 1, "why": "The plasma membrane is the selective barrier, so its proteins are transport channels/pumps and receptors. Histones are in the nucleus, actin/tubulin form the cytoskeleton, and amylase/insulin are secreted."}, {"id": "seed-mcq-ch4-q4", "stem": "Which structure is found in plant cells but NOT in animal cells?", "img": "seed/img/ch4-plant-vs-animal.svg", "choices": ["Endoplasmic reticulum", "Golgi apparatus", "Chloroplast", "Mitochondrion"], "answer": 2, "why": "Plant only: chloroplasts, cellulose cell wall, central vacuole, plasmodesmata. Mitochondria, Golgi and ER are in both."}, {"id": "seed-mcq-ch4-q5", "stem": "Which structure is found in animal cells but NOT in plant cells?", "img": "seed/img/ch4-plant-vs-animal.svg", "choices": ["Mitochondria", "Nucleus", "Plasma membrane", "Centrioles"], "answer": 3, "why": "Animal cells have a centrosome with a pair of centrioles; plant cells do not have centrioles."}, {"id": "seed-mcq-ch4-q6", "stem": "Which is a function of the plant central vacuole?", "img": null, "choices": ["Converting light energy into sugar", "Making most of the cell’s ATP", "Holding the cell’s genetic information", "Storing water and ions and maintaining pressure against the cell wall"], "answer": 3, "why": "The central vacuole stores water, ions and wastes, keeps turgor pressure, regulates the cytoplasm, and helps the cell grow. Light → sugar is the chloroplast, ATP is the mitochondrion, DNA is the nucleus."}, {"id": "seed-mcq-ch4-q7", "stem": "Which statement about chloroplasts is TRUE?", "img": "seed/img/ch4-mito-chloro.svg", "choices": ["They are surrounded by a single membrane and have no DNA", "They contain thylakoid stacks surrounded by a fluid called stroma", "They are found in both plant and animal cells", "They break down glucose to make ATP in cellular respiration"], "answer": 1, "why": "Chloroplasts have thylakoids (with chlorophyll) and stroma, a double membrane and their own DNA. They turn solar energy into chemical energy. Respiration is the mitochondrion’s job."}, {"id": "seed-mcq-ch4-q8", "stem": "The smooth ER’s main job is to…", "img": null, "choices": ["produce secretory proteins", "digest worn-out organelles", "assemble ribosomes", "synthesize lipids"], "answer": 3, "why": "Smooth ER has no ribosomes: it makes lipids, detoxifies drugs, and stores calcium. Ribosomes are assembled in the nucleolus, secretory proteins are made on rough ER, and lysosomes digest."}, {"id": "seed-mcq-ch4-q9", "stem": "Which structure assembles ribosomes?", "img": null, "choices": ["Nucleolus", "Rough ER", "Smooth ER", "Golgi apparatus"], "answer": 0, "why": "The nucleolus makes ribosomal RNA and puts ribosome subunits together, then they leave through nuclear pores."}, {"id": "seed-mcq-ch4-q10", "stem": "Which organelle produces proteins that will be secreted from the cell?", "img": "seed/img/ch4-endomembrane.svg", "choices": ["Smooth ER", "Rough ER", "Peroxisome", "Lysosome"], "answer": 1, "why": "The ribosomes on rough ER make secretory and membrane proteins, which enter the ER and are shipped to the Golgi."}, {"id": "seed-mcq-ch4-q11", "stem": "Which organelle modifies, sorts and packages proteins?", "img": "seed/img/ch4-endomembrane.svg", "choices": ["Nucleus", "Golgi apparatus", "Rough ER", "Mitochondrion"], "answer": 1, "why": "The Golgi is the cell’s “post office.”"}, {"id": "seed-mcq-ch4-q12", "stem": "Which organelle digests macromolecules and worn-out organelles?", "img": null, "choices": ["Peroxisome", "Smooth ER", "Nucleolus", "Lysosome"], "answer": 3, "why": "Lysosomes contain hydrolytic enzymes that break down macromolecules."}, {"id": "seed-mcq-ch4-q13", "stem": "What mainly defines the shape of an animal cell (which has no cell wall)?", "img": "seed/img/ch4-cytoskeleton.svg", "choices": ["The rough ER", "The cytoskeleton", "The Golgi apparatus", "The nucleolus"], "answer": 1, "why": "The cytoskeleton is a network of protein fibers that supports the cell and keeps its shape."}, {"id": "seed-mcq-ch4-q14", "stem": "Which is found ONLY in prokaryotic cells?", "img": "seed/img/ch4-prok-vs-euk.svg", "choices": ["Ribosomes", "A nucleoid region", "A plasma membrane", "Flagella"], "answer": 1, "why": "The nucleoid is the non-membrane DNA region of prokaryotes. Ribosomes, plasma membranes and flagella are found in both prokaryotes and eukaryotes."}, {"id": "seed-mcq-ch4-q15", "stem": "Which is found ONLY in eukaryotic cells?", "img": "seed/img/ch4-prok-vs-euk.svg", "choices": ["Ribosomes", "Mitochondria", "Plasma membrane", "Cytosol"], "answer": 1, "why": "Mitochondria, lysosomes and the nucleolus are membrane-bound/nuclear structures, so they are eukaryote-only. The other three are in every cell."}, {"id": "seed-mcq-ch4-q16", "stem": "A motor protein called dynein makes a flagellum bend by walking along which fibers?", "img": "seed/img/ch4-9plus2.svg", "choices": ["Microtubules", "Cellulose fibrils", "Intermediate filaments", "Microfilaments"], "answer": 0, "why": "Flagella and cilia are built from microtubules (9+2). Dynein arms make the microtubule doublets slide. Centrosomes are also microtubule organizers."}, {"id": "seed-mcq-ch4-q17", "stem": "Which cytoskeleton fibers anchor the nucleus in place and are NOT used for movement?", "img": "seed/img/ch4-cytoskeleton.svg", "choices": ["Microfilaments", "Actin and myosin", "Microtubules", "Intermediate filaments"], "answer": 3, "why": "Intermediate filaments are rope-like, bear tension, and hold organelles like the nucleus in place."}, {"id": "seed-mcq-ch4-q18", "stem": "An amoeba extends pseudopodia, and muscle cells contract using myosin. Both use…", "img": "seed/img/ch4-cytoskeleton.svg", "choices": ["microtubules (tubulin)", "intermediate filaments (keratin)", "microfilaments (actin)", "the central vacuole"], "answer": 2, "why": "Actin microfilaments + myosin = muscle contraction; actin also drives pseudopodia and cytoplasmic streaming."}, {"id": "seed-mcq-ch4-q19", "stem": "In the bacterium shown, which letter points to the structure that helps it STICK to surfaces?", "img": "seed/img/ch4-prokaryote-letters.svg", "choices": ["A", "B", "E", "G"], "answer": 0, "why": "A = fimbriae: short hair-like attachment structures. G (flagellum) is for swimming, B is the capsule, E the nucleoid."}, {"id": "seed-mcq-ch4-q20", "stem": "In the bacterium shown, which letter is the protective sticky outer coat (capsule)?", "img": "seed/img/ch4-prokaryote-letters.svg", "choices": ["A", "B", "C", "D"], "answer": 1, "why": "B = capsule (glycocalyx), the outermost layer. C = cell wall, D = plasma membrane, A = fimbriae."}, {"id": "seed-mcq-ch4-q21", "stem": "In the bacterium shown, which letter is the rigid layer that keeps the cell’s shape?", "img": "seed/img/ch4-prokaryote-letters.svg", "choices": ["B", "C", "D", "E"], "answer": 1, "why": "C = cell wall, which is rigid and sits between the capsule (B) and plasma membrane (D)."}, {"id": "seed-mcq-ch4-q22", "stem": "In the bacterium shown, which letter REGULATES what passes into and out of the cell?", "img": "seed/img/ch4-prokaryote-letters.svg", "choices": ["B", "C", "D", "E"], "answer": 2, "why": "D = the PLASMA MEMBRANE, the selective barrier. The cell wall (C) is rigid support but lets most small things through; it does not control passage. This is the one you missed!"}, {"id": "seed-mcq-ch4-q23", "stem": "In the bacterium shown, where is the cell’s DNA?", "img": "seed/img/ch4-prokaryote-letters.svg", "choices": ["D", "E", "F", "G"], "answer": 1, "why": "E = the nucleoid, the region where DNA is concentrated (no membrane around it). F = ribosomes."}, {"id": "seed-mcq-ch4-q24", "stem": "In the bacterium shown, which letter points to where proteins are made?", "img": "seed/img/ch4-prokaryote-letters.svg", "choices": ["A", "D", "E", "F"], "answer": 3, "why": "F = ribosomes, which make proteins in every cell."}, {"id": "seed-mcq-ch4-q25", "stem": "Which feature would best tell you that a cell is eukaryotic rather than prokaryotic?", "img": "seed/img/ch4-prok-vs-euk.svg", "choices": ["It has ribosomes", "It has a plasma membrane", "It has DNA", "It has internal membranes, such as a membrane-enclosed nucleus"], "answer": 3, "why": "All cells have ribosomes, a plasma membrane and DNA. Only eukaryotes have internal membranes that make a nucleus and organelles."}, {"id": "seed-mcq-ch4-q26", "stem": "Which structure is common to BOTH plant and animal cells?", "img": "seed/img/ch4-plant-vs-animal.svg", "choices": ["Mitochondrion", "Centriole", "Central vacuole", "Chloroplast"], "answer": 0, "why": "Mitochondria are in both. Chloroplasts and the central vacuole are plant only; centrioles are animal only."}, {"id": "seed-mcq-ch4-q27", "stem": "Which structure would you find in a prokaryotic cell?", "img": null, "choices": ["Mitochondrion", "Nucleus", "Golgi apparatus", "Ribosome"], "answer": 3, "why": "Ribosomes are not membrane-bound and every cell needs them to make proteins. The others are membrane-bound organelles."}, {"id": "seed-mcq-ch4-q28", "stem": "Which statement correctly describes the smooth ER?", "img": null, "choices": ["It is found only in plant cells", "It lacks ribosomes on its surface", "It is studded with ribosomes", "It makes ribosomal RNA"], "answer": 1, "why": "Smooth = no ribosomes. Rough ER is the one studded with ribosomes."}, {"id": "seed-mcq-ch4-q29", "stem": "Which process happens in BOTH plant and animal cells?", "img": "seed/img/ch4-mito-chloro.svg", "choices": ["Cellular respiration", "Photosynthesis", "Building a cellulose cell wall", "Storing water in a central vacuole"], "answer": 0, "why": "Plants have mitochondria too, so they do cellular respiration. The other three happen only in plant cells."}, {"id": "seed-mcq-ch4-q30", "stem": "Mitochondria and chloroplasts are alike because both…", "img": "seed/img/ch4-mito-chloro.svg", "choices": ["contain their own DNA", "are surrounded by a single membrane", "make sugar from light", "are found in animal cells"], "answer": 0, "why": "Both have their own DNA and ribosomes and a double membrane (evidence for endosymbiosis). Only mitochondria are in animals; only chloroplasts make sugar."}, {"id": "seed-mcq-ch4-q31", "stem": "In the animal cell, which letter is the organelle that makes lipids and has NO ribosomes?", "img": "seed/img/ch4-animal-letters.svg", "choices": ["A", "B", "C", "E"], "answer": 1, "why": "B = smooth ER. A is rough ER (has ribosomes), C is the Golgi, E is a mitochondrion."}, {"id": "seed-mcq-ch4-q32", "stem": "In the animal cell, which letter modifies and sorts proteins before shipping them?", "img": "seed/img/ch4-animal-letters.svg", "choices": ["A", "C", "D", "F"], "answer": 1, "why": "C = Golgi apparatus (stack of flattened sacs)."}, {"id": "seed-mcq-ch4-q33", "stem": "In the animal cell, which letter is where most ATP is made?", "img": "seed/img/ch4-animal-letters.svg", "choices": ["B", "D", "E", "H"], "answer": 2, "why": "E = mitochondrion (the folded inner membrane forms cristae)."}, {"id": "seed-mcq-ch4-q34", "stem": "In the animal cell, which letter assembles ribosomes?", "img": "seed/img/ch4-animal-letters.svg", "choices": ["A", "D", "F", "H"], "answer": 2, "why": "F = nucleolus, the dark spot inside the nucleus."}, {"id": "seed-mcq-ch4-q35", "stem": "In the animal cell, which letter is the region where microtubules start and centrioles are found?", "img": "seed/img/ch4-animal-letters.svg", "choices": ["D", "F", "G", "H"], "answer": 3, "why": "H = centrosome with a pair of centrioles."}, {"id": "seed-mcq-ch4-q36", "stem": "What is the highlighted structure?", "img": "seed/img/ch4-id-plant-vacuole.svg", "choices": ["Chloroplast", "Lysosome", "Nucleus", "Central vacuole"], "answer": 3, "why": "The huge sac taking up most of a mature plant cell is the central vacuole."}, {"id": "seed-mcq-ch4-q37", "stem": "What is the highlighted structure?", "img": "seed/img/ch4-id-animal-golgi.svg", "choices": ["Mitochondrion", "Smooth ER", "Rough ER", "Golgi apparatus"], "answer": 3, "why": "A stack of curved, flattened sacs with vesicles budding off = Golgi."}, {"id": "seed-mcq-ch4-q38", "stem": "What is the highlighted structure?", "img": "seed/img/ch4-id-animal-rer.svg", "choices": ["Nuclear envelope", "Smooth ER", "Golgi apparatus", "Rough ER"], "answer": 3, "why": "Sheets wrapped around the nucleus and covered with dots (ribosomes) = rough ER."}, {"id": "seed-mcq-ch4-q39", "stem": "What is the highlighted structure?", "img": "seed/img/ch4-id-plant-wall.svg", "choices": ["Cell wall", "Plasma membrane", "Central vacuole", "Plasmodesmata"], "answer": 0, "why": "The thick layer OUTSIDE the plasma membrane is the cellulose cell wall."}, {"id": "seed-mcq-ch4-q40", "stem": "What is the highlighted structure?", "img": "seed/img/ch4-id-prok-pm.svg", "choices": ["Nucleoid", "Cell wall", "Capsule", "Plasma membrane"], "answer": 3, "why": "In a bacterium the order from outside in is capsule → cell wall → plasma membrane. The innermost boundary (blue) is the plasma membrane."}, {"id": "seed-mcq-ch4-q41", "stem": "What is the highlighted structure?", "img": "seed/img/ch4-id-prok-nucleoid.svg", "choices": ["Capsule", "Ribosome", "Nucleoid", "Nucleus"], "answer": 2, "why": "Prokaryotes have no nucleus; their DNA sits in the nucleoid region with no membrane around it."}, {"id": "seed-mcq-ch4-q42", "stem": "A standard light microscope cannot resolve details smaller than about…", "img": "seed/img/ch4-size-scale.svg", "choices": ["2 nm", "0.2 µm (200 nm)", "20 µm", "0.1 mm"], "answer": 1, "why": "LM resolution limit ≈ 0.2 µm = 200 nm. EM ≈ 2 nm, unaided eye ≈ 0.1 mm."}, {"id": "seed-mcq-ch4-q43", "stem": "Which could NOT be seen clearly with a standard light microscope?", "img": "seed/img/ch4-size-scale.svg", "choices": ["A nucleus", "A ribosome", "A chloroplast", "A plant cell"], "answer": 1, "why": "Ribosomes (~20 nm) are far below the 200 nm limit; nuclei (~5 µm), chloroplasts (~2–5 µm) and cells (10–100 µm) are visible."}, {"id": "seed-mcq-ch4-q44", "stem": "To study the changes in shape of a LIVING white blood cell, you should use a…", "img": "seed/img/ch4-microscopes.svg", "choices": ["transmission electron microscope", "centrifuge", "light microscope", "scanning electron microscope"], "answer": 2, "why": "Electron microscopy kills the cells, so only light microscopy works for living cells."}, {"id": "seed-mcq-ch4-q45", "stem": "To see the detailed surface texture of a hair, you should use a…", "img": "seed/img/ch4-microscopes.svg", "choices": ["scanning electron microscope (SEM)", "light microscope", "cell fractionation", "transmission electron microscope (TEM)"], "answer": 0, "why": "SEM scans the surface and gives a 3-D-looking image. TEM shows internal structure of thin slices."}, {"id": "seed-mcq-ch4-q46", "stem": "To see the internal membranes of a mitochondrion, you should use a…", "img": "seed/img/ch4-microscopes.svg", "choices": ["transmission electron microscope (TEM)", "light microscope", "scanning electron microscope (SEM)", "unaided eye"], "answer": 0, "why": "TEM passes electrons through a thin slice → shows internal structure. A mitochondrion’s cristae are too small for LM."}, {"id": "seed-mcq-ch4-q47", "stem": "Why do electron microscopes have much better resolution than light microscopes?", "img": null, "choices": ["Electron beams have much shorter wavelengths than visible light", "They use colored dyes that stand out", "They only look at living cells", "They use stronger glass lenses"], "answer": 0, "why": "Resolution is inversely related to wavelength. EMs use electromagnets (not glass) as lenses."}, {"id": "seed-mcq-ch4-q48", "stem": "Resolution is best defined as…", "img": null, "choices": ["the minimum distance two points can be apart and still be seen as separate", "the number of lenses in the microscope", "how many times bigger the image is than the object", "the difference in brightness between light and dark areas"], "answer": 0, "why": "That’s resolution (clarity). The ratio of image size to real size is magnification; brightness difference is contrast."}, {"id": "seed-mcq-ch4-q49", "stem": "In cell fractionation, which cell parts collect in the FIRST pellet (slowest, shortest spin)?", "img": "seed/img/ch4-fractionation.svg", "choices": ["Mitochondria", "Nuclei", "Membrane pieces", "Ribosomes"], "answer": 1, "why": "The biggest, heaviest parts pellet first: nuclei → mitochondria/chloroplasts → membranes → ribosomes last (fastest, longest spin)."}, {"id": "seed-mcq-ch4-q50", "stem": "A cell fraction had high levels of enzymes for cellular respiration. Under the EM it would be full of…", "img": "seed/img/ch4-fractionation.svg", "choices": ["ribosomes", "nuclei", "mitochondria", "lysosomes"], "answer": 2, "why": "This is how biochemistry + cytology showed that mitochondria are the sites of cellular respiration."}, {"id": "seed-mcq-ch4-q51", "stem": "A cube-shaped cell is 2 µm on each side. What is its surface-to-volume ratio?", "img": "seed/img/ch4-tb-surface-volume.jpg", "choices": ["3", "1.5", "0.33", "6"], "answer": 0, "why": "SA = 6 × 2² = 24 µm². V = 2³ = 8 µm³. Ratio = 24 ÷ 8 = 3."}, {"id": "seed-mcq-ch4-q52", "stem": "As a cell gets bigger, its surface-to-volume ratio…", "img": "seed/img/ch4-tb-surface-volume.jpg", "choices": ["stays the same", "increases, because surface area grows faster than volume", "decreases, because volume grows faster than surface area", "decreases, because surface area grows faster than volume"], "answer": 2, "why": "Volume ∝ length³ and surface area ∝ length², so volume outpaces surface area. That limits how large a cell can be."}, {"id": "seed-mcq-ch4-q53", "stem": "Intestinal cells have many microvilli. What is the advantage?", "img": null, "choices": ["They increase surface area for absorbing nutrients without much increase in volume", "They make ATP", "They help the cell swim", "They store digestive enzymes"], "answer": 0, "why": "A high surface-to-volume ratio speeds exchange with the surroundings."}, {"id": "seed-mcq-ch4-q54", "stem": "An elongated nerve-like cell is 125 × 1 × 1 units. Compared with a 5 × 5 × 5 cube (same volume, ratio 1.2), its surface-to-volume ratio is…", "img": null, "choices": ["the same, 1.2", "higher, about 4", "lower, about 0.5", "higher, about 125"], "answer": 1, "why": "SA = 4(125 × 1) + 2(1 × 1) = 502; V = 125; 502 ÷ 125 ≈ 4.0."}, {"id": "seed-mcq-ch4-q55", "stem": "Which is the correct path of a protein that is secreted from the cell?", "img": "seed/img/ch4-endomembrane.svg", "choices": ["Rough ER → transport vesicle → Golgi → vesicle → plasma membrane", "Nucleolus → mitochondrion → Golgi → plasma membrane", "Smooth ER → nucleus → Golgi → plasma membrane", "Golgi → rough ER → lysosome → plasma membrane"], "answer": 0, "why": "Made by ribosomes on the rough ER, shipped by vesicle to the Golgi to be modified, then packaged into a vesicle that fuses with the plasma membrane (exocytosis)."}, {"id": "seed-mcq-ch4-q56", "stem": "Which is NOT part of the endomembrane system?", "img": "seed/img/ch4-endomembrane.svg", "choices": ["Lysosome", "Mitochondrion", "Nuclear envelope", "Golgi apparatus"], "answer": 1, "why": "The endomembrane system = nuclear envelope, ER, Golgi, lysosomes, vacuoles, vesicles, plasma membrane. Mitochondria, chloroplasts and peroxisomes are separate."}, {"id": "seed-mcq-ch4-q57", "stem": "What is the main advantage of the internal membranes of eukaryotic cells?", "img": null, "choices": ["They replace the need for a plasma membrane", "They make the cell smaller", "They create compartments so incompatible chemical processes can happen at the same time", "They let the cell survive without ribosomes"], "answer": 2, "why": "Each compartment keeps its own local conditions, and many enzymes are built into the membranes."}, {"id": "seed-mcq-ch4-q58", "stem": "A cell has a cell wall, ribosomes and a plasma membrane, but no nucleus and no membrane-bound organelles. It is most likely a…", "img": "seed/img/ch4-prok-vs-euk.svg", "choices": ["animal cell", "bacterium", "plant cell", "fungal cell"], "answer": 1, "why": "No nucleus and no membrane organelles = prokaryote (bacterium or archaean)."}, {"id": "seed-mcq-ch4-q59", "stem": "A cell has a nucleus, mitochondria, chloroplasts, a large central vacuole and a cellulose wall. It is a…", "img": "seed/img/ch4-plant-vs-animal.svg", "choices": ["animal cell", "fungal cell", "bacterium", "plant cell"], "answer": 3, "why": "Chloroplasts + central vacuole + cellulose wall = plant cell."}, {"id": "seed-mcq-ch4-q60", "stem": "The plasma membrane’s interior is hydrophobic because it is made mainly of…", "img": "seed/img/ch4-tb-membrane.jpg", "choices": ["the phosphate heads of phospholipids", "cellulose", "the fatty acid tails of phospholipids", "carbohydrate side chains"], "answer": 2, "why": "Hydrophobic tails face inward; hydrophilic phosphate heads face the watery fluid on both sides."}, {"id": "seed-mcq-ch4-q61", "stem": "Why is the inner membrane of a mitochondrion folded into cristae?", "img": "seed/img/ch4-mito-chloro.svg", "choices": ["To trap light energy", "To store DNA", "To make ribosomes", "To increase surface area for the enzymes of cellular respiration"], "answer": 3, "why": "More membrane = more room for respiration enzymes and ATP synthase → more ATP."}]}, {"id": "seed-chem-atomic-rules", "rev": 1, "title": "Chem — Atomic Structure: Rules & Conventions", "folder": "Chem", "description": "Every rule you need: p/n/e counting, isotope notation, average atomic mass, formula subscripts, periodic table families, diatomics, ion charges and names, Dalton, states of matter, safety.", "cards": [{"id": "seed-chem-atomic-rules-0", "term": "The 3 subatomic particles (name, mass, charge, location)", "def": "Proton p⁺: 1 amu, +1, nucleus.  Neutron n⁰: 1 amu, 0, nucleus.  Electron e⁻: ≈ 0 amu, −1, outside the nucleus.", "defImg": "seed/img/chem-atomic-atom.svg", "note": "Only protons and neutrons count toward mass; electrons are so light their mass is ignored."}, {"id": "seed-chem-atomic-rules-1", "term": "RULE: atomic number (Z) =", "def": "# of protons. It’s the element’s “name tag”: change the protons and you have a different element.", "defImg": "seed/img/chem-atomic-iso.svg", "note": "Z is the whole number on the periodic table (the one that goes 1, 2, 3…)."}, {"id": "seed-chem-atomic-rules-2", "term": "RULE: mass number (A) =", "def": "# protons + # neutrons (the “atomic mass” of one isotope, in amu).", "defImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-chem-atomic-rules-3", "term": "RULE: # neutrons =", "def": "Mass number − atomic number  (A − Z).", "defImg": "seed/img/chem-atomic-iso.svg", "note": "Example: C-14 → 14 − 6 = 8 neutrons."}, {"id": "seed-chem-atomic-rules-4", "term": "RULE: # electrons in a NEUTRAL atom =", "def": "# protons (charges cancel out)."}, {"id": "seed-chem-atomic-rules-5", "term": "RULE: # electrons in an ION =", "def": "protons − charge.  A + charge means electrons were LOST (fewer e⁻); a − charge means electrons were GAINED (more e⁻).", "defImg": "seed/img/chem-atomic-ions.svg", "note": "Mg²⁺: 12 − 2 = 10 e⁻.   S²⁻: 16 + 2 = 18 e⁻."}, {"id": "seed-chem-atomic-rules-6", "term": "Standard isotopic notation: what goes where?", "def": "Mass number (A) on the TOP LEFT, atomic number (Z) on the BOTTOM LEFT, symbol (X) in the middle, charge on the TOP RIGHT.", "defImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-chem-atomic-rules-7", "term": "Hyphen notation: “carbon-14” or “C-14” means…", "def": "The number is the MASS NUMBER. Get the atomic number from the periodic table (C = 6), so C-14 has 6 p⁺, 8 n⁰, 6 e⁻.", "defImg": "seed/img/chem-atomic-iso-slide.png"}, {"id": "seed-chem-atomic-rules-8", "term": "Isotope", "def": "Atoms of the SAME element (same # of protons) with DIFFERENT numbers of neutrons, so they have different masses.", "defImg": "seed/img/chem-atomic-iso-slide.png", "note": "C-12, C-13 and C-14 all have 6 protons; they have 6, 7 and 8 neutrons."}, {"id": "seed-chem-atomic-rules-9", "term": "Atomic mass / atomic mass unit (amu)", "def": "Mass of an atom, measured in amu. 1 proton ≈ 1 amu, 1 neutron ≈ 1 amu, electron ≈ 0."}, {"id": "seed-chem-atomic-rules-10", "term": "Percent abundance", "def": "The percentage of an element’s atoms in nature that are a particular isotope. All the isotopes’ % abundances add up to 100%.", "defImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-chem-atomic-rules-11", "term": "Average atomic mass", "def": "The weighted average mass of all the naturally occurring isotopes of an element, based on their % abundance. It’s the decimal number on the periodic table.", "defImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-chem-atomic-rules-12", "term": "RULE: average atomic mass formula", "def": "AAM = (mass₁ × decimal abundance₁) + (mass₂ × decimal abundance₂) + …  (decimal = % ÷ 100)", "defImg": "seed/img/chem-atomic-aam.svg", "note": "Common mistakes: forgetting to turn % into a decimal, or averaging the masses without weighting them."}, {"id": "seed-chem-atomic-rules-13", "term": "How to check an average atomic mass answer", "def": "It must be BETWEEN the lightest and heaviest isotope masses, and closest to the MOST ABUNDANT isotope.", "defImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-chem-atomic-rules-14", "term": "Why aren’t periodic-table masses whole numbers?", "def": "Because they are weighted averages of all the element’s isotopes (and protons/neutrons aren’t exactly 1 amu).", "defImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-chem-atomic-rules-15", "term": "How are % abundances measured?", "def": "With a mass spectrometer: atoms are ionized, accelerated, and bent by a magnet; lighter isotopes bend more. The detector shows how much of each isotope there is.", "defImg": "seed/img/chem-atomic-mass-spec.png"}, {"id": "seed-chem-atomic-rules-16", "term": "RULE: subscripts in a formula", "def": "A subscript tells how many atoms of the element RIGHT BEFORE it. No subscript = 1 atom.  H₂O = 2 H, 1 O.", "defImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-chem-atomic-rules-17", "term": "RULE: parentheses in a formula", "def": "A subscript after parentheses multiplies EVERYTHING inside.  Al₂(SO₄)₃ = 2 Al, 3 S, 12 O.", "defImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-chem-atomic-rules-18", "term": "RULE: a coefficient in front (like 3H₂O)", "def": "It multiplies the whole formula: 3H₂O = 6 H and 3 O.", "note": "Coefficients go in front; subscripts go after a symbol."}, {"id": "seed-chem-atomic-rules-19", "term": "RULE: element symbols", "def": "First letter CAPITAL, second letter lowercase. Co = cobalt, but CO = carbon + oxygen.", "note": "A capital letter always starts a new element when counting atoms."}, {"id": "seed-chem-atomic-rules-20", "term": "Period", "def": "A horizontal ROW of the periodic table (7 periods).", "defImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-chem-atomic-rules-21", "term": "Group (family)", "def": "A vertical COLUMN of the periodic table (18 groups). Elements in a group have similar properties.", "defImg": "seed/img/chem-atomic-pt.svg", "note": "Your notes also use 1A–8A for the tall columns."}, {"id": "seed-chem-atomic-rules-22", "term": "Alkali metals", "def": "Group 1 (1A), NOT including hydrogen: Li, Na, K, Rb, Cs, Fr. Very reactive, form 1+ ions.", "defImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-chem-atomic-rules-23", "term": "Alkaline earth metals", "def": "Group 2 (2A): Be, Mg, Ca, Sr, Ba, Ra. Form 2+ ions.", "defImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-chem-atomic-rules-24", "term": "Transition metals", "def": "Groups 3–12 (the middle “d block”): Fe, Cu, Zn, Ag, Au, etc. Their ion charges vary.", "defImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-chem-atomic-rules-25", "term": "Halogens", "def": "Group 17 (7A): F, Cl, Br, I, At. Very reactive nonmetals, form 1− ions.", "defImg": "seed/img/chem-atomic-pt.svg", "note": "“Halogen” = salt-former (NaCl)."}, {"id": "seed-chem-atomic-rules-26", "term": "Noble gases", "def": "Group 18 (8A): He, Ne, Ar, Kr, Xe, Rn. Very stable and unreactive; don’t form ions (charge 0).", "defImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-chem-atomic-rules-27", "term": "Where are metals vs nonmetals?", "def": "Metals are LEFT of the staircase line (most elements). Nonmetals are to the RIGHT, plus hydrogen. Metalloids touch the staircase (B, Si, Ge, As, Sb, Te).", "defImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-chem-atomic-rules-28", "term": "Metals: properties", "def": "Shiny, conduct electricity and heat, malleable. Tend to LOSE electrons → positive ions (cations).", "defImg": "seed/img/chem-atomic-metals.svg", "note": "Metals conduct because their electrons are held loosely."}, {"id": "seed-chem-atomic-rules-29", "term": "Nonmetals: properties", "def": "Dull, poor conductors, brittle if solid. Tend to GAIN electrons → negative ions (anions).", "defImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-chem-atomic-rules-30", "term": "The 7 diatomic elements", "def": "H₂, N₂, O₂, F₂, Cl₂, Br₂, I₂ (they exist as 2-atom molecules in their standard state).", "defImg": "seed/img/chem-atomic-diatomic.svg", "note": "Trick: “HOFBrINCl,” or the “7” shape starting at nitrogen (element 7), plus H."}, {"id": "seed-chem-atomic-rules-31", "term": "Ion", "def": "An atom (or group of atoms) with a charge because it GAINED or LOST electrons.", "defImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-chem-atomic-rules-32", "term": "Cation", "def": "A POSITIVE ion; it LOST electron(s). Usually a metal.", "defImg": "seed/img/chem-atomic-ions.svg", "note": "Think “ca+ion” (the t looks like a + sign), or a cat is “paws-itive.”"}, {"id": "seed-chem-atomic-rules-33", "term": "Anion", "def": "A NEGATIVE ion; it GAINED electron(s). Usually a nonmetal.", "defImg": "seed/img/chem-atomic-ions.svg", "note": "“A Negative ION.”"}, {"id": "seed-chem-atomic-rules-34", "term": "RULE: naming a cation", "def": "Same name as the element + “ion.”  Na⁺ = sodium ion, Ca²⁺ = calcium ion.", "defImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-chem-atomic-rules-35", "term": "RULE: naming an anion", "def": "Change the ending to “-ide.”  Cl⁻ = chloride, F⁻ = fluoride, O²⁻ = oxide, N³⁻ = nitride, S²⁻ = sulfide.", "defImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-chem-atomic-rules-36", "term": "RULE: you can only move ELECTRONS", "def": "Ions form by gaining or losing electrons. Never change the number of protons (that would make a different element).", "defImg": "seed/img/chem-atomic-ions.svg", "note": "“Keep your hands off the nucleus!”"}, {"id": "seed-chem-atomic-rules-37", "term": "RULE: predicting an ion’s charge", "def": "1) Find the element’s atomic number. 2) Find the NEAREST noble gas. 3) Count how many e⁻ it must gain or lose to match. Lose = +, gain = −.", "defImg": "seed/img/chem-atomic-charges.svg", "note": "Why: noble gases have a very stable number of electrons."}, {"id": "seed-chem-atomic-rules-38", "term": "Charges by group (memorize)", "def": "Group 1: 1+   Group 2: 2+   Group 13: 3+   Group 15: 3−   Group 16: 2−   Group 17: 1−   Group 18: 0", "defImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-chem-atomic-rules-39", "term": "Worked: charge on sulfur (S)", "def": "S = 16. Nearest noble gas Ar = 18. Gain 2 e⁻ → S²⁻ (sulfide).", "defImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-chem-atomic-rules-40", "term": "Worked: charge on aluminum (Al)", "def": "Al = 13. Nearest noble gas Ne = 10. Lose 3 e⁻ → Al³⁺.", "defImg": "seed/img/chem-atomic-charges.svg", "note": "Losing 3 is easier than gaining 5 to reach Ar."}, {"id": "seed-chem-atomic-rules-41", "term": "Why do ions conduct electricity?", "def": "Charged particles that can MOVE carry current. Ionic compounds conduct only when melted or dissolved in water (ions free to move). This is called an electrolyte.", "defImg": "seed/img/chem-atomic-conductivity.png", "note": "Solid salt does not conduct."}, {"id": "seed-chem-atomic-rules-42", "term": "Like and opposite charges", "def": "Like charges repel; opposite charges attract."}, {"id": "seed-chem-atomic-rules-43", "term": "Dalton’s atomic theory: point 1", "def": "All matter is made of atoms (tiny, indivisible particles)."}, {"id": "seed-chem-atomic-rules-44", "term": "Dalton’s atomic theory: point 2", "def": "All atoms of a given element are identical in mass and properties; atoms of different elements are different.", "note": "Later shown to be not quite right: isotopes."}, {"id": "seed-chem-atomic-rules-45", "term": "Dalton’s atomic theory: point 3", "def": "Compounds form when atoms of two or more elements combine in small whole-number ratios."}, {"id": "seed-chem-atomic-rules-46", "term": "Dalton’s atomic theory: point 4", "def": "In a chemical reaction atoms are only combined, separated or rearranged; they are NOT created, destroyed, divided or changed into other atoms."}, {"id": "seed-chem-atomic-rules-47", "term": "Solid", "def": "Definite shape AND definite volume. Particles tightly packed, vibrating in place.", "defImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-chem-atomic-rules-48", "term": "Liquid", "def": "Definite volume but NO definite shape (takes the shape of its container). Particles close together but slide past each other.", "defImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-chem-atomic-rules-49", "term": "Gas", "def": "No definite shape and no definite volume (fills its container). Particles far apart and moving fast; easily compressed.", "defImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-chem-atomic-rules-50", "term": "Safety equipment and when to use it", "def": "Goggles (always), eyewash (chemical in eye, ~15 min), safety shower (big spill on body), fire extinguisher, fire blanket, fume hood (vapors), first-aid kit, broken-glass box.", "defImg": "seed/img/chem-atomic-safety.svg", "note": "Know where each one is in your lab."}, {"id": "seed-chem-atomic-rules-51", "term": "Basic lab safety rules", "def": "Goggles on; tie back hair; closed-toe shoes; no food or drink; waft, never sniff directly; point heated test tubes away from people; never return chemicals to the stock bottle; add acid to water; report ALL accidents to the teacher.", "defImg": "seed/img/chem-atomic-safety.svg"}]}, {"id": "seed-mcq-chem-atomic", "rev": 4, "kind": "mcq", "title": "Chem — Atomic Structure Test Review", "folder": "Chem", "description": "156 questions covering every item on your study guide. Use the periodic table image (like the one you get on the test).", "cards": [], "questions": [{"id": "seed-mcq-chem-atomic-q0", "stem": "Which particle has a charge of −1 and almost no mass?", "img": null, "choices": ["Electron", "Proton", "Nucleus", "Neutron"], "answer": 0, "why": "Electrons are −1 and ≈ 0 amu, found outside the nucleus.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q1", "stem": "Which two particles are found in the nucleus?", "img": null, "choices": ["Protons and neutrons", "Protons and electrons", "Only electrons", "Neutrons and electrons"], "answer": 0, "why": "The nucleus holds protons (+1) and neutrons (0); electrons are outside.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q2", "stem": "Which particle has a mass of about 1 amu and NO charge?", "img": null, "choices": ["Neutron", "Electron", "Proton", "Ion"], "answer": 0, "why": "Neutron: 1 amu, charge 0, in the nucleus."}, {"id": "seed-mcq-chem-atomic-q3", "stem": "The mass of an atom comes almost entirely from…", "img": null, "choices": ["its electrons", "its electrons and protons", "its protons and neutrons", "the empty space around the nucleus"], "answer": 2, "why": "Electrons are so light (~0 amu) that mass = protons + neutrons."}, {"id": "seed-mcq-chem-atomic-q4", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>40</span><span>19</span></span><span class=\"isox\">K</span></span>?", "img": null, "choices": ["21 p⁺, 19 n⁰, 21 e⁻", "19 p⁺, 40 n⁰, 19 e⁻", "19 p⁺, 21 n⁰, 19 e⁻", "40 p⁺, 19 n⁰, 40 e⁻"], "answer": 2, "why": "Protons = Z = 19. Neutrons = A − Z = 40 − 19 = 21. Neutral, so electrons = 19.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-atomic-q5", "stem": "How many neutrons are in <span class=\"isow\"><span class=\"iso\"><span>14</span><span>6</span></span><span class=\"isox\">C</span></span>?", "img": null, "choices": ["8", "20", "6", "14"], "answer": 0, "why": "A − Z = 14 − 6 = 8."}, {"id": "seed-mcq-chem-atomic-q6", "stem": "How many electrons are in <span class=\"isow\"><span class=\"iso\"><span>35</span><span>17</span></span><span class=\"isox\">Cl</span><span class=\"isoc\">−</span></span>?", "img": null, "choices": ["17", "16", "18", "35"], "answer": 2, "why": "Chloride gained 1 electron: 17 + 1 = 18.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-atomic-q7", "stem": "How many electrons are in <span class=\"isow\"><span class=\"iso\"><span>27</span><span>13</span></span><span class=\"isox\">Al</span><span class=\"isoc\">3+</span></span>?", "img": null, "choices": ["13", "16", "10", "14"], "answer": 2, "why": "Lost 3 electrons: 13 − 3 = 10. (Neutrons = 27 − 13 = 14.)", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-atomic-q8", "stem": "An ion is written <span class=\"isow\"><span class=\"iso\"><span>56</span><span>26</span></span><span class=\"isox\">Fe</span><span class=\"isoc\">2+</span></span>. Which is correct?", "img": null, "choices": ["26 p⁺, 30 n⁰, 24 e⁻", "26 p⁺, 56 n⁰, 24 e⁻", "26 p⁺, 30 n⁰, 28 e⁻", "24 p⁺, 30 n⁰, 26 e⁻"], "answer": 0, "why": "p = 26; n = 56 − 26 = 30; 2+ means 2 e⁻ lost → 24."}, {"id": "seed-mcq-chem-atomic-q9", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>32</span><span>16</span></span><span class=\"isox\">S</span><span class=\"isoc\">2−</span></span>?", "img": null, "choices": ["18 p⁺, 16 n⁰, 16 e⁻", "16 p⁺, 16 n⁰, 14 e⁻", "16 p⁺, 32 n⁰, 18 e⁻", "16 p⁺, 16 n⁰, 18 e⁻"], "answer": 3, "why": "p = 16; n = 32 − 16 = 16; gained 2 e⁻ → 18."}, {"id": "seed-mcq-chem-atomic-q10", "stem": "An atom has 11 protons and 12 neutrons. What is it, and what is its mass number?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Magnesium, mass number 23", "Sodium, mass number 12", "Sodium, mass number 23", "Vanadium, mass number 23"], "answer": 2, "why": "11 protons = sodium (Z = 11). Mass number = 11 + 12 = 23."}, {"id": "seed-mcq-chem-atomic-q11", "stem": "An atom has 26 protons. Which element is it?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Aluminum (Al)", "Cobalt (Co)", "Iron (Fe)", "Magnesium (Mg)"], "answer": 2, "why": "The atomic number (# protons) identifies the element: Z = 26 is Fe."}, {"id": "seed-mcq-chem-atomic-q12", "stem": "Uranium-238 (U, atomic number 92) has how many neutrons?", "img": null, "choices": ["330", "238", "92", "146"], "answer": 3, "why": "238 − 92 = 146. In “uranium-238,” 238 is the mass number."}, {"id": "seed-mcq-chem-atomic-q13", "stem": "Isotopes of the same element have different numbers of…", "img": null, "choices": ["protons", "atomic numbers", "neutrons", "electrons only"], "answer": 2, "why": "Same protons (same element), different neutrons → different mass numbers."}, {"id": "seed-mcq-chem-atomic-q14", "stem": "Which pair are isotopes of each other?", "img": null, "choices": ["C-14 and N-14", "C-12 and C-14", "O₂ and O₃", "Na and Na⁺"], "answer": 1, "why": "Both have 6 protons but different neutrons. C-14 and N-14 have the same mass number but are different elements."}, {"id": "seed-mcq-chem-atomic-q15", "stem": "In isotope notation, the number on the BOTTOM LEFT is the…", "img": null, "choices": ["atomic number (protons)", "charge", "number of neutrons", "mass number"], "answer": 0, "why": "Top left = mass number A, bottom left = atomic number Z, top right = charge.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-atomic-q16", "stem": "An element has two isotopes: mass 10 amu (20%) and mass 11 amu (80%). What is its average atomic mass?", "img": null, "choices": ["11.0 amu", "10.8 amu", "10.2 amu", "10.5 amu"], "answer": 1, "why": "(10 × 0.20) + (11 × 0.80) = 2.0 + 8.8 = 10.8 amu (that’s boron!).", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-atomic-q17", "stem": "Chlorine is 75.77% Cl-35 (34.97 amu) and 24.23% Cl-37 (36.97 amu). Its average atomic mass is closest to…", "img": null, "choices": ["34.97 amu", "35.97 amu", "36.00 amu", "35.45 amu"], "answer": 3, "why": "(34.97 × 0.7577) + (36.97 × 0.2423) = 26.50 + 8.96 = 35.46 ≈ 35.45 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-atomic-q18", "stem": "Element X: X-24 is 78.99% (23.99 amu), X-25 is 10.00% (24.99 amu), X-26 is 11.01% (25.98 amu). Average atomic mass ≈", "img": null, "choices": ["25.00 amu", "24.99 amu", "23.99 amu", "24.31 amu"], "answer": 3, "why": "18.95 + 2.50 + 2.86 = 24.31 amu, which is magnesium.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-atomic-q19", "stem": "Carbon: C-12 (12 amu) is 99.43% and C-14 (14 amu) is 0.57%. Average atomic mass =", "img": null, "choices": ["13.00 amu", "12.57 amu", "14.00 amu", "12.01 amu"], "answer": 3, "why": "(12 × 0.9943) + (14 × 0.0057) = 11.93 + 0.08 = 12.01 amu. Weighted toward the common isotope."}, {"id": "seed-mcq-chem-atomic-q20", "stem": "Copper’s average atomic mass is 63.55 amu. Its isotopes are Cu-63 and Cu-65. Which is more abundant?", "img": null, "choices": ["Can’t tell", "Cu-63", "Cu-65", "They are equal"], "answer": 1, "why": "63.55 is closer to 63, so Cu-63 is more common. The average is pulled toward the most abundant isotope."}, {"id": "seed-mcq-chem-atomic-q21", "stem": "Average atomic mass is best described as…", "img": null, "choices": ["protons + neutrons of one atom", "a weighted average of an element’s isotopes based on percent abundance", "the mass of the most common isotope", "the simple average of all the isotope masses"], "answer": 1, "why": "Weighted, like a grade where some assignments count more."}, {"id": "seed-mcq-chem-atomic-q22", "stem": "Percent abundance means…", "img": null, "choices": ["the percent of an element’s atoms in nature that are a certain isotope", "the percent of electrons lost", "the percent of Earth made of that element", "the percent of the atom’s mass in the nucleus"], "answer": 0, "why": "All isotopes’ abundances add to 100%."}, {"id": "seed-mcq-chem-atomic-q23", "stem": "How do scientists measure the percent abundance of isotopes?", "img": null, "choices": ["Gold foil experiment", "Oil drop experiment", "Cathode ray tube", "Mass spectrometry"], "answer": 3, "why": "A mass spectrometer separates isotopes by mass.", "whyImg": "seed/img/chem-atomic-mass-spec.png"}, {"id": "seed-mcq-chem-atomic-q24", "stem": "A roll of 50 pennies has a mass of 146.35 g. Pre-1982 pennies are 3.11 g and newer ones are 2.50 g. How many pre-1982 pennies?", "img": null, "choices": ["40", "35", "25", "15"], "answer": 1, "why": "3.11x + 2.50(50 − x) = 146.35 → 0.61x = 21.35 → x = 35 old pennies (and 15 new)."}, {"id": "seed-mcq-chem-atomic-q25", "stem": "How many atoms of each element are in H₂SO₄?", "img": null, "choices": ["2 H, 1 S, 4 O", "1 H, 2 S, 4 O", "2 H, 4 S, 1 O", "2 H, 1 S, 1 O"], "answer": 0, "why": "Each subscript belongs to the element before it; S has none, so 1.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-atomic-q26", "stem": "How many oxygen atoms are in Al₂(SO₄)₃?", "img": null, "choices": ["3", "12", "7", "4"], "answer": 1, "why": "4 O inside the parentheses × 3 = 12.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-atomic-q27", "stem": "How many total atoms are in Ca(OH)₂?", "img": null, "choices": ["3", "4", "6", "5"], "answer": 3, "why": "1 Ca + 2 O + 2 H = 5."}, {"id": "seed-mcq-chem-atomic-q28", "stem": "How many hydrogen atoms are in (NH₄)₃PO₄?", "img": null, "choices": ["3", "7", "12", "4"], "answer": 2, "why": "4 H × 3 = 12. (Also 3 N, 1 P, 4 O.)"}, {"id": "seed-mcq-chem-atomic-q29", "stem": "How many atoms of each element are in C₂₅H₅₂?", "img": null, "choices": ["25 C and 52 H", "2 C, 5 H", "52 C and 25 H", "25 C and 5 H"], "answer": 0, "why": "Subscripts can be more than one digit."}, {"id": "seed-mcq-chem-atomic-q30", "stem": "How many oxygen atoms are in 3H₂O?", "img": null, "choices": ["6", "2", "3", "1"], "answer": 2, "why": "The coefficient 3 multiplies the whole formula: 3 × 1 O = 3 O (and 6 H)."}, {"id": "seed-mcq-chem-atomic-q31", "stem": "P₂O₅ contains…", "img": null, "choices": ["1 phosphorus and 5 oxygen", "2 potassium and 5 oxygen", "2 phosphorus and 5 oxygen", "2 phosphorus and 1 oxygen"], "answer": 2, "why": "P = phosphorus (K is potassium)."}, {"id": "seed-mcq-chem-atomic-q32", "stem": "A vertical column on the periodic table is called a…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["row", "group (family)", "block", "period"], "answer": 1, "why": "Columns = groups; rows = periods.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-atomic-q33", "stem": "What is the highlighted row called?", "img": "seed/img/chem-atomic-hl-p3.svg", "choices": ["Group 3", "The halogens", "Period 3", "Group 3A"], "answer": 2, "why": "Rows are periods. This is the 3rd row (Na to Ar)."}, {"id": "seed-mcq-chem-atomic-q34", "stem": "Which family is highlighted?", "img": "seed/img/chem-atomic-hl-g1.svg", "choices": ["Transition metals", "Alkaline earth metals", "Halogens", "Alkali metals"], "answer": 3, "why": "Group 1 without hydrogen = alkali metals."}, {"id": "seed-mcq-chem-atomic-q35", "stem": "Which family is highlighted?", "img": "seed/img/chem-atomic-hl-g2.svg", "choices": ["Alkali metals", "Noble gases", "Transition metals", "Alkaline earth metals"], "answer": 3, "why": "Group 2 = alkaline earth metals."}, {"id": "seed-mcq-chem-atomic-q36", "stem": "Which family is highlighted?", "img": "seed/img/chem-atomic-hl-g17.svg", "choices": ["Halogens", "Alkali metals", "Metalloids", "Noble gases"], "answer": 0, "why": "Group 17 (7A) = halogens."}, {"id": "seed-mcq-chem-atomic-q37", "stem": "Which family is highlighted?", "img": "seed/img/chem-atomic-hl-g18.svg", "choices": ["Noble gases", "Alkaline earth metals", "Halogens", "Transition metals"], "answer": 0, "why": "Group 18 (8A) = noble gases."}, {"id": "seed-mcq-chem-atomic-q38", "stem": "Which group of elements is highlighted?", "img": "seed/img/chem-atomic-hl-tm.svg", "choices": ["Alkaline earth metals", "Transition metals", "Noble gases", "Nonmetals"], "answer": 1, "why": "Groups 3–12, the middle block = transition metals."}, {"id": "seed-mcq-chem-atomic-q39", "stem": "Which element is an alkali metal?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Calcium (Ca)", "Hydrogen (H)", "Chlorine (Cl)", "Potassium (K)"], "answer": 3, "why": "Group 1 metals: Li, Na, K, Rb, Cs, Fr. Hydrogen is in group 1 but is NOT an alkali metal."}, {"id": "seed-mcq-chem-atomic-q40", "stem": "Which element is a halogen?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Krypton (Kr)", "Boron (B)", "Bromine (Br)", "Barium (Ba)"], "answer": 2, "why": "Halogens are group 17: F, Cl, Br, I, At."}, {"id": "seed-mcq-chem-atomic-q41", "stem": "Which element is a noble gas?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Argon (Ar)", "Oxygen (O)", "Fluorine (F)", "Nitrogen (N)"], "answer": 0, "why": "Group 18: He, Ne, Ar, Kr, Xe, Rn."}, {"id": "seed-mcq-chem-atomic-q42", "stem": "Which element is an alkaline earth metal?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Magnesium (Mg)", "Manganese (Mn)", "Sodium (Na)", "Aluminum (Al)"], "answer": 0, "why": "Group 2: Be, Mg, Ca, Sr, Ba, Ra. (Mn is a transition metal.)"}, {"id": "seed-mcq-chem-atomic-q43", "stem": "Which element is a transition metal?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Selenium (Se)", "Iron (Fe)", "Lithium (Li)", "Calcium (Ca)"], "answer": 1, "why": "Transition metals are groups 3–12, like Fe, Cu, Zn, Ag."}, {"id": "seed-mcq-chem-atomic-q44", "stem": "Which element is a NONMETAL?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Copper (Cu)", "Aluminum (Al)", "Sodium (Na)", "Sulfur (S)"], "answer": 3, "why": "Nonmetals are right of the staircase (plus H).", "whyImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-mcq-chem-atomic-q45", "stem": "Which element is a METAL?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Phosphorus (P)", "Neon (Ne)", "Carbon (C)", "Calcium (Ca)"], "answer": 3, "why": "Metals are left of the staircase.", "whyImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-mcq-chem-atomic-q46", "stem": "Where are the metals found on the periodic table?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["To the left of the staircase line", "Only in the top row", "To the right of the staircase line", "Only in group 18"], "answer": 0, "why": "Most elements are metals, on the left/center. Hydrogen is the exception (a nonmetal on the left).", "whyImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-mcq-chem-atomic-q47", "stem": "Which list contains ONLY diatomic elements?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["H, N, O, F, Cl, Br, I", "C, N, O, S, P", "H, He, O, N, Ne", "Na, Cl, K, Br"], "answer": 0, "why": "The Big 7: HOFBrINCl.", "whyImg": "seed/img/chem-atomic-diatomic.svg"}, {"id": "seed-mcq-chem-atomic-q48", "stem": "Which element is NOT diatomic?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Hydrogen", "Nitrogen", "Iodine", "Helium"], "answer": 3, "why": "Noble gases like He exist as single atoms.", "whyImg": "seed/img/chem-atomic-diatomic.svg"}, {"id": "seed-mcq-chem-atomic-q49", "stem": "What is the most likely charge on an ion of calcium (Ca)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["1+", "2+", "0", "2−"], "answer": 1, "why": "Ca = 20; nearest noble gas Ar = 18; lose 2 e⁻ → Ca²⁺.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-atomic-q50", "stem": "What is the most likely charge on an ion of iodine (I)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["7+", "1−", "1+", "2−"], "answer": 1, "why": "I = 53; nearest noble gas Xe = 54; gain 1 e⁻ → I⁻ (iodide)."}, {"id": "seed-mcq-chem-atomic-q51", "stem": "What is the most likely charge on an ion of nitrogen (N)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["5+", "3+", "5−", "3−"], "answer": 3, "why": "N = 7; nearest noble gas Ne = 10; gain 3 e⁻ → N³⁻ (nitride)."}, {"id": "seed-mcq-chem-atomic-q52", "stem": "What is the most likely charge on an ion of aluminum (Al)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["5−", "3+", "13+", "3−"], "answer": 1, "why": "Al = 13; nearest noble gas Ne = 10; lose 3 e⁻ → Al³⁺."}, {"id": "seed-mcq-chem-atomic-q53", "stem": "What is the most likely charge on an ion of oxygen (O)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["2−", "2+", "6−", "6+"], "answer": 0, "why": "O = 8; nearest noble gas Ne = 10; gain 2 e⁻ → O²⁻ (oxide)."}, {"id": "seed-mcq-chem-atomic-q54", "stem": "What is the most likely charge on an ion of potassium (K)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["2+", "1+", "0", "1−"], "answer": 1, "why": "K = 19; nearest noble gas Ar = 18; lose 1 e⁻ → K⁺."}, {"id": "seed-mcq-chem-atomic-q55", "stem": "What is the charge on an ion of neon (Ne)?", "img": null, "choices": ["1+", "0 (it doesn’t form an ion)", "1−", "2−"], "answer": 1, "why": "Noble gases already have a stable number of electrons."}, {"id": "seed-mcq-chem-atomic-q56", "stem": "Why do atoms gain or lose electrons to form ions?", "img": null, "choices": ["To get the same number of electrons as the nearest noble gas", "To gain mass", "To become a different element", "To get the same number of protons as a noble gas"], "answer": 0, "why": "Noble-gas electron numbers are very stable. Protons never change."}, {"id": "seed-mcq-chem-atomic-q57", "stem": "A cation is an ion that has…", "img": null, "choices": ["lost electrons and is positive", "lost protons and is negative", "gained protons and is positive", "gained electrons and is negative"], "answer": 0, "why": "Cation = + (lost e⁻), usually a metal.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-atomic-q58", "stem": "An anion is an ion that has…", "img": null, "choices": ["lost protons", "gained neutrons", "lost electrons and is positive", "gained electrons and is negative"], "answer": 3, "why": "Anion = − (gained e⁻), usually a nonmetal.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-atomic-q59", "stem": "What is the name of the ion Cl⁻?", "img": null, "choices": ["Chlorine", "Chlorate", "Chloride", "Chlorine ion"], "answer": 2, "why": "Anions end in “-ide.”", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-atomic-q60", "stem": "What is the name of the ion S²⁻?", "img": null, "choices": ["Sulfate", "Sulfide", "Sulfur", "Sulfur ion"], "answer": 1, "why": "Anions end in “-ide.”"}, {"id": "seed-mcq-chem-atomic-q61", "stem": "What is the name of the ion Mg²⁺?", "img": null, "choices": ["Magnesium-2", "Magnesate", "Magnesium ion", "Magneside"], "answer": 2, "why": "Cations keep the element’s name."}, {"id": "seed-mcq-chem-atomic-q62", "stem": "An atom becomes a 2+ ion. What happened?", "img": null, "choices": ["It lost 2 protons", "It lost 2 electrons", "It gained 2 electrons", "It gained 2 protons"], "answer": 1, "why": "Only electrons move. Losing negative charge leaves the ion positive."}, {"id": "seed-mcq-chem-atomic-q63", "stem": "Solid table salt (NaCl) does not conduct electricity, but salt water does. Why?", "img": null, "choices": ["Water itself is a metal", "The salt gains protons in water", "The ions can move freely only when dissolved (or melted)", "Solid salt has no ions"], "answer": 2, "why": "Ionic compounds conduct only when their ions are free to move: they are electrolytes.", "whyImg": "seed/img/chem-atomic-conductivity.png"}, {"id": "seed-mcq-chem-atomic-q64", "stem": "Metals conduct electricity because…", "img": null, "choices": ["they have more protons", "they have no electrons", "their electrons are held loosely and can move", "their nuclei move"], "answer": 2, "why": "Electrons pushed in one end bump others out the other end."}, {"id": "seed-mcq-chem-atomic-q65", "stem": "Which is one of the 4 points of Dalton’s atomic theory?", "img": null, "choices": ["Electrons move in fixed energy levels", "Atoms are not created or destroyed in a chemical reaction; they are rearranged", "Atoms have a small dense nucleus", "Atoms contain neutrons"], "answer": 1, "why": "The other three come later (Rutherford, Bohr, Chadwick)."}, {"id": "seed-mcq-chem-atomic-q66", "stem": "Dalton said compounds form when atoms combine in…", "img": null, "choices": ["small whole-number ratios", "any random ratio", "pairs only", "equal masses"], "answer": 0, "why": "Example: H₂O is always 2 H : 1 O."}, {"id": "seed-mcq-chem-atomic-q67", "stem": "Which part of Dalton’s theory was later shown to be NOT exactly right?", "img": null, "choices": ["Atoms are rearranged in reactions", "All matter is made of atoms", "Atoms combine in whole-number ratios", "All atoms of an element are identical in mass"], "answer": 3, "why": "Isotopes of the same element have different masses."}, {"id": "seed-mcq-chem-atomic-q68", "stem": "Rutherford’s gold foil experiment showed that atoms have…", "img": null, "choices": ["electrons in energy levels", "a tiny, dense, positive nucleus", "the same mass for all atoms of an element", "neutrons"], "answer": 1, "why": "Most alpha particles went through, but a few bounced back off the nucleus."}, {"id": "seed-mcq-chem-atomic-q69", "stem": "Who discovered the electron and proposed the “plum pudding” model?", "img": null, "choices": ["Niels Bohr", "John Dalton", "J.J. Thomson", "James Chadwick"], "answer": 2, "why": "Thomson (1897), using cathode rays."}, {"id": "seed-mcq-chem-atomic-q70", "stem": "Who discovered the neutron?", "img": null, "choices": ["Ernest Rutherford", "Democritus", "James Chadwick", "Robert Millikan"], "answer": 2, "why": "Chadwick, 1932."}, {"id": "seed-mcq-chem-atomic-q71", "stem": "Which state of matter has a definite volume but NO definite shape?", "img": null, "choices": ["All three", "Solid", "Liquid", "Gas"], "answer": 2, "why": "Liquids take the shape of their container but keep their volume.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q72", "stem": "Which state has particles far apart that fill their entire container?", "img": null, "choices": ["Liquid and solid", "Liquid", "Solid", "Gas"], "answer": 3, "why": "Gases have no definite shape or volume and can be compressed.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q73", "stem": "In which state do particles only vibrate in fixed positions?", "img": null, "choices": ["None", "Gas", "Solid", "Liquid"], "answer": 2, "why": "Solids have a definite shape and volume.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q74", "stem": "A chemical splashes into your eye. What should you do first?", "img": null, "choices": ["Go to the eyewash station and flush for about 15 minutes, and tell the teacher", "Use the safety shower for 1 second", "Wait to see if it hurts", "Rub your eye"], "answer": 0, "why": "Flush right away at the eyewash; report it.", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q75", "stem": "A large amount of acid spills on your clothes and skin. Use the…", "img": null, "choices": ["fire blanket", "fume hood", "eyewash only", "safety shower"], "answer": 3, "why": "Safety shower for large spills on the body.", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q76", "stem": "What is the safe way to smell a chemical?", "img": null, "choices": ["Waft the vapors toward your nose with your hand", "Sniff directly from the container", "Heat it and inhale", "Taste a tiny amount"], "answer": 0, "why": "Never smell directly; never taste."}, {"id": "seed-mcq-chem-atomic-q77", "stem": "Which is a correct lab safety rule?", "img": null, "choices": ["Report every accident or broken glass to the teacher", "Return unused chemicals to the stock bottle", "Point a heated test tube toward yourself", "Eat only if you wash your hands first"], "answer": 0, "why": "Also: goggles on, hair tied back, no food, never put chemicals back in the stock bottle."}, {"id": "seed-mcq-chem-atomic-q78", "stem": "A proton is a…", "img": null, "choices": ["positive particle outside the nucleus with ~0 mass", "neutral particle in the nucleus", "positively charged (+1) particle in the nucleus with a mass of about 1 amu", "negatively charged particle outside the nucleus"], "answer": 2, "why": "Proton: p⁺, 1 amu, +1, nucleus.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q79", "stem": "A neutron is a…", "img": null, "choices": ["neutral particle in the nucleus with a mass of about 1 amu", "neutral particle outside the nucleus with ~0 mass", "positive particle in the nucleus", "negative particle outside the nucleus"], "answer": 0, "why": "Neutron: n⁰, 1 amu, 0 charge, nucleus.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q80", "stem": "An electron is a…", "img": null, "choices": ["negative particle inside the nucleus with a mass of 1 amu", "neutral particle in the nucleus", "negatively charged (−1) particle outside the nucleus with almost no mass", "positive particle in the nucleus"], "answer": 2, "why": "Electron: e⁻, ~0 amu, −1, somewhere outside the nucleus.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q81", "stem": "The atomic number of an element is the number of…", "img": null, "choices": ["protons", "neutrons", "protons + neutrons", "electrons in an ion"], "answer": 0, "why": "Atomic number (Z) = # protons. It identifies the element.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q82", "stem": "The atomic mass (mass number) of an isotope equals…", "img": null, "choices": ["protons + electrons", "protons + neutrons", "neutrons − protons", "protons only"], "answer": 1, "why": "Electrons are too light to count.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q83", "stem": "An isotope is…", "img": null, "choices": ["a different element with the same mass", "an atom with a different number of protons", "an atom that has gained or lost electrons", "an atom of the same element with a different number of neutrons"], "answer": 3, "why": "Same protons, different neutrons → different mass.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q84", "stem": "A group on the periodic table is…", "img": null, "choices": ["a horizontal row", "the staircase line", "a vertical column", "a block of transition metals"], "answer": 2, "why": "Groups (families) are columns; elements in a group act alike.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q85", "stem": "A period on the periodic table is…", "img": null, "choices": ["the metals on the left", "a vertical column", "a horizontal row", "a family of similar elements"], "answer": 2, "why": "There are 7 periods (rows).", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q86", "stem": "Alkali metals are the elements in…", "img": null, "choices": ["group 17 (7A)", "group 1 (1A), except hydrogen", "group 2 (2A)", "groups 3–12"], "answer": 1, "why": "Li, Na, K, Rb, Cs, Fr.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q87", "stem": "Alkaline earth metals are the elements in…", "img": null, "choices": ["group 2 (2A)", "group 18 (8A)", "groups 3–12", "group 1 (1A)"], "answer": 0, "why": "Be, Mg, Ca, Sr, Ba, Ra.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q88", "stem": "Noble gases are the elements in…", "img": null, "choices": ["group 2 (2A)", "group 18 (8A)", "group 17 (7A)", "group 1 (1A)"], "answer": 1, "why": "He, Ne, Ar, Kr, Xe, Rn: very stable and unreactive.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q89", "stem": "Halogens are the elements in…", "img": null, "choices": ["group 16 (6A)", "group 18 (8A)", "group 17 (7A)", "group 1 (1A)"], "answer": 2, "why": "F, Cl, Br, I, At.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q90", "stem": "Transition metals are the elements in…", "img": null, "choices": ["group 17", "group 18", "groups 3–12 (the middle block)", "groups 1 and 2"], "answer": 2, "why": "The d block in the middle of the table.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q91", "stem": "Where are electrons found?", "img": null, "choices": ["Somewhere outside the nucleus", "Stuck to the protons", "Inside the nucleus", "Only in the center of the atom"], "answer": 0, "why": "The nucleus holds only protons and neutrons.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q92", "stem": "What is the symbol and charge of a neutron?", "img": null, "choices": ["n⁻, charge −1", "n⁰, charge 0", "e⁻, charge −1", "n⁺, charge +1"], "answer": 1, "why": "Neutrons are neutral.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q93", "stem": "Which two particles have about the SAME mass?", "img": null, "choices": ["Proton and neutron", "Neutron and electron", "Proton and electron", "All three"], "answer": 0, "why": "Both are about 1 amu; the electron is about 0.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q94", "stem": "Which particle determines what ELEMENT an atom is?", "img": null, "choices": ["Electron", "Neutron", "Proton", "Nucleus size"], "answer": 2, "why": "Change the protons and you have a different element.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q95", "stem": "In a NEUTRAL atom, the number of electrons equals the number of…", "img": null, "choices": ["protons", "neutrons", "isotopes", "protons + neutrons"], "answer": 0, "why": "Equal + and − charges cancel out.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q96", "stem": "“amu” stands for…", "img": null, "choices": ["atomic measurement unit", "average mass unit", "atomic mass unit", "atomic molecule unit"], "answer": 2, "why": "Protons and neutrons are each about 1 amu.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q97", "stem": "Which part of the atom contains almost all of its mass?", "img": null, "choices": ["The nucleus", "The empty space", "The electron cloud", "The outer electrons"], "answer": 0, "why": "Protons + neutrons are in the nucleus.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-atomic-q98", "stem": "Which is one of Dalton’s 4 points?", "img": null, "choices": ["Atoms are mostly empty space", "Electrons are in energy levels", "Atoms have a nucleus", "All matter is made of atoms"], "answer": 3, "why": "Point 1: all matter is made of atoms, the ultimate chemical particles."}, {"id": "seed-mcq-chem-atomic-q99", "stem": "According to Dalton, all atoms of a given element are…", "img": null, "choices": ["identical in mass and other properties", "different in mass", "made of protons only", "able to change into other elements"], "answer": 0, "why": "Point 2. (Isotopes later showed this isn’t exactly true.)"}, {"id": "seed-mcq-chem-atomic-q100", "stem": "According to Dalton, atoms of DIFFERENT elements…", "img": null, "choices": ["have different masses and properties", "can’t combine", "are identical", "have the same number of protons"], "answer": 0, "why": "Point 2, second half."}, {"id": "seed-mcq-chem-atomic-q101", "stem": "According to Dalton, compounds form when…", "img": null, "choices": ["atoms are destroyed", "one atom splits in two", "atoms combine in any random ratio", "two or more different kinds of atoms combine in small whole-number ratios"], "answer": 3, "why": "Point 3."}, {"id": "seed-mcq-chem-atomic-q102", "stem": "According to Dalton, in a chemical reaction atoms are…", "img": null, "choices": ["converted into other kinds of atoms", "created and destroyed", "divided into smaller parts", "combined, separated, or rearranged, but never created or destroyed"], "answer": 3, "why": "Point 4: atoms are the units of chemical change."}, {"id": "seed-mcq-chem-atomic-q103", "stem": "Which is NOT part of Dalton’s atomic theory?", "img": null, "choices": ["Atoms combine in small whole-number ratios", "Atoms are rearranged in reactions", "Atoms have a tiny, dense, positive nucleus", "All matter is made of atoms"], "answer": 2, "why": "The nucleus came from Rutherford (1909)."}, {"id": "seed-mcq-chem-atomic-q104", "stem": "Which part of Dalton’s theory did isotopes prove wrong?", "img": null, "choices": ["All atoms of an element are identical in mass", "Atoms are rearranged in reactions", "Atoms combine in whole-number ratios", "All matter is made of atoms"], "answer": 0, "why": "Isotopes = same element, different masses."}, {"id": "seed-mcq-chem-atomic-q105", "stem": "Who first said matter is made of tiny indivisible particles called “atomos”?", "img": null, "choices": ["Thomson", "Dalton", "Democritus (and Leucippus)", "Bohr"], "answer": 2, "why": "460–370 BC."}, {"id": "seed-mcq-chem-atomic-q106", "stem": "Who published the first formal model of the atom?", "img": null, "choices": ["Democritus", "J.J. Thomson", "Ernest Rutherford", "John Dalton"], "answer": 3, "why": "Dalton combined atomic ideas with the known elements."}, {"id": "seed-mcq-chem-atomic-q107", "stem": "J.J. Thomson’s “plum pudding” model showed…", "img": null, "choices": ["neutrons in the nucleus", "a dense nucleus", "electrons in fixed energy levels", "+ and − charged pieces spread throughout the atom"], "answer": 3, "why": "Thomson (1897) proved cathode rays are electrons."}, {"id": "seed-mcq-chem-atomic-q108", "stem": "Rutherford’s gold foil experiment showed…", "img": null, "choices": ["a tiny, very dense nucleus with almost all the mass", "atoms are solid spheres", "electrons have fixed energy levels", "the charge on an electron"], "answer": 0, "why": "Most alpha particles passed through; a few bounced back."}, {"id": "seed-mcq-chem-atomic-q109", "stem": "Niels Bohr (1913) proposed that electrons…", "img": null, "choices": ["have no charge", "are spread like plums in pudding", "have fixed energy levels", "are in the nucleus"], "answer": 2, "why": "This keeps them from collapsing into the nucleus."}, {"id": "seed-mcq-chem-atomic-q110", "stem": "Who discovered the neutron in 1932?", "img": null, "choices": ["Niels Bohr", "Robert Millikan", "James Chadwick", "Ernest Rutherford"], "answer": 2, "why": "Same mass as a proton, no charge."}, {"id": "seed-mcq-chem-atomic-q111", "stem": "Robert Millikan (1909) measured…", "img": null, "choices": ["radioactivity", "the size of the nucleus", "the charge on an electron", "the mass of a neutron"], "answer": 2, "why": "Oil drop experiment; used to find the electron’s mass."}, {"id": "seed-mcq-chem-atomic-q112", "stem": "Henri Becquerel (1896) discovered…", "img": null, "choices": ["the nucleus", "the electron", "radioactivity", "the neutron"], "answer": 2, "why": ""}, {"id": "seed-mcq-chem-atomic-q113", "stem": "Sir William Crookes used a Crookes tube, an early…", "img": null, "choices": ["cathode ray tube", "mass spectrometer", "gold foil", "microscope"], "answer": 0, "why": "1879: electrical discharges in gases."}, {"id": "seed-mcq-chem-atomic-q114", "stem": "Which state has a definite shape AND a definite volume?", "img": null, "choices": ["Gas", "Liquid", "Solid", "Liquid and gas"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q115", "stem": "Which state has a definite volume but takes the shape of its container?", "img": null, "choices": ["Liquid", "None", "Gas", "Solid"], "answer": 0, "why": "", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q116", "stem": "Which state has NO definite shape and NO definite volume?", "img": null, "choices": ["Solid", "Solid and liquid", "Gas", "Liquid"], "answer": 2, "why": "Gases fill the whole container.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q117", "stem": "Which state is the easiest to compress?", "img": null, "choices": ["Liquid", "Gas", "Solid", "All are equally compressible"], "answer": 1, "why": "Gas particles are far apart.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q118", "stem": "Particles that are close together but can slide past each other describe a…", "img": null, "choices": ["liquid", "gas", "plasma", "solid"], "answer": 0, "why": "That’s why liquids flow.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q119", "stem": "Particles packed tightly in fixed positions that only vibrate describe a…", "img": null, "choices": ["solid", "solution", "liquid", "gas"], "answer": 0, "why": "", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q120", "stem": "In which state do particles move the fastest and are farthest apart?", "img": null, "choices": ["Solid", "They are all the same", "Gas", "Liquid"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q121", "stem": "10 mL of water is poured from a tall cylinder into a wide beaker. What changes?", "img": null, "choices": ["Both shape and volume", "Only its volume", "Only its shape", "Neither"], "answer": 2, "why": "Liquids keep their volume.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q122", "stem": "A gas is moved from a small container into a much larger one. What happens?", "img": null, "choices": ["It turns into a liquid", "It sinks to the bottom as a layer", "It spreads out to fill the larger container", "It keeps its original volume"], "answer": 2, "why": "Gases have no definite volume.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q123", "stem": "Which states can flow?", "img": null, "choices": ["Liquids and gases", "Gases only", "Solids only", "Solids and liquids"], "answer": 0, "why": "Their particles can move past each other.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-atomic-q124", "stem": "When must safety goggles be worn?", "img": null, "choices": ["Only when the teacher is watching", "Only on test days", "Whenever chemicals, glassware, or heat are being used", "Only when heating"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q125", "stem": "A chemical splashes in your eye. You should…", "img": null, "choices": ["rub your eye", "flush it at the eyewash station for about 15 minutes and tell the teacher", "wait until class ends", "wipe it with a paper towel"], "answer": 1, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q126", "stem": "A large chemical spill soaks your clothes. Use the…", "img": null, "choices": ["fire extinguisher", "eyewash station only", "safety shower", "fume hood"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q127", "stem": "A classmate’s clothing catches fire. Use the…", "img": null, "choices": ["fire blanket (stop, drop, and roll)", "fume hood", "broken-glass box", "eyewash"], "answer": 0, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q128", "stem": "What does P-A-S-S stand for when using a fire extinguisher?", "img": null, "choices": ["Pull, Aim, Squeeze, Sweep", "Push, Aim, Spray, Stop", "Point, Aim, Shoot, Stop", "Pull, Alert, Spray, Sweep"], "answer": 0, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q129", "stem": "Work with toxic or strong-smelling vapors should be done in the…", "img": null, "choices": ["hallway", "safety shower", "fume hood", "sink"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q130", "stem": "Where does broken glass go?", "img": null, "choices": ["The recycling bin", "The regular trash", "The sink", "The broken-glass box (after telling the teacher)"], "answer": 3, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q131", "stem": "How should you smell a chemical?", "img": null, "choices": ["Taste it instead", "Take a deep breath over the beaker", "Put your nose right over it", "Waft the vapor toward your nose with your hand"], "answer": 3, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q132", "stem": "What should you do with leftover chemical you didn’t use?", "img": null, "choices": ["Take it home", "Mix it with another chemical", "Pour it back into the stock bottle", "Dispose of it as the teacher directs, never back in the stock bottle"], "answer": 3, "why": "Returning it can contaminate the whole bottle.", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q133", "stem": "When heating a test tube, point the open end…", "img": null, "choices": ["straight down", "away from yourself and others", "toward your lab partner", "toward your face so you can watch"], "answer": 1, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q134", "stem": "Long hair and loose clothing in the lab should be…", "img": null, "choices": ["left as is", "only a problem on test days", "tied back / secured", "covered with a paper towel"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q135", "stem": "Is it OK to eat or drink in the lab?", "img": null, "choices": ["Only water", "Only after the lab is done", "Yes, if you wash your hands", "No, never"], "answer": 3, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q136", "stem": "When diluting an acid you should…", "img": null, "choices": ["add the acid to the water", "mix them in any order", "heat the acid first", "add water to the acid"], "answer": 0, "why": "“Do as you oughta, add acid to water.”", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q137", "stem": "You cut your finger on glassware. What is the FIRST thing to do?", "img": null, "choices": ["Tell the teacher right away", "Leave class without telling anyone", "Put the glass back", "Hide it and keep working"], "answer": 0, "why": "Report ALL accidents, even small ones.", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q138", "stem": "Why should you know where the safety equipment is in YOUR lab?", "img": null, "choices": ["It’s only for the teacher", "You won’t need it", "So you can get to it immediately in an emergency", "To be able to move it"], "answer": 2, "why": "Know the eyewash, shower, extinguisher, blanket, exits.", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q139", "stem": "What kind of shoes are safe in the lab?", "img": null, "choices": ["Sandals", "Flip-flops", "Any shoes", "Closed-toe shoes"], "answer": 3, "why": "Protect feet from spills and broken glass.", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-atomic-q140", "stem": "Why aren’t most atomic masses on the periodic table whole numbers?", "img": null, "choices": ["Protons weigh 1.5 amu", "Scientists measured them wrong", "Electrons add extra mass", "They are weighted averages of all of the element’s isotopes"], "answer": 3, "why": "", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-atomic-q141", "stem": "How many carbon atoms weigh exactly 12.011 amu?", "img": null, "choices": ["All of them", "Only C-14", "Only C-12", "None; 12.011 is an average"], "answer": 3, "why": "No single atom has the average mass.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-atomic-q142", "stem": "An element’s isotope percent abundances always add up to…", "img": null, "choices": ["its atomic number", "1%", "50%", "100%"], "answer": 3, "why": "", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-atomic-q143", "stem": "An element’s average atomic mass is closest to the mass of…", "img": null, "choices": ["its most abundant isotope", "its rarest isotope", "its heaviest isotope", "its lightest isotope"], "answer": 0, "why": "The most common isotope carries the most “weight.”", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-atomic-q144", "stem": "Before multiplying, what do you do to a percent abundance like 75.77%?", "img": null, "choices": ["Divide by 100 to make it a decimal (0.7577)", "Divide by the mass", "Multiply by 100", "Leave it as 75.77"], "answer": 0, "why": "", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-atomic-q145", "stem": "Isotope percent abundances are measured using…", "img": null, "choices": ["gold foil", "a mass spectrometer", "a Crookes tube", "a Bunsen burner"], "answer": 1, "why": "The mass spectrometer separates isotopes by mass.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-atomic-q146", "stem": "Average atomic mass is like your grade in class because…", "img": null, "choices": ["it only counts the heaviest isotope", "you drop the lowest isotope", "every isotope counts equally", "items that count more (more abundant isotopes) have more weight"], "answer": 3, "why": "It’s a weighted average.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-atomic-q147", "stem": "Which is true about elements in nature?", "img": null, "choices": ["Every element exists naturally", "Some elements are much more abundant than others, and some are only man-made", "All elements are equally abundant", "Helium is more abundant on Earth than oxygen"], "answer": 1, "why": "", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-atomic-q148", "stem": "An ion is…", "img": null, "choices": ["an atom with extra protons", "an isotope", "an atom with extra neutrons", "an atom (or group of atoms) with a charge because it gained or lost electrons"], "answer": 3, "why": "", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-atomic-q149", "stem": "Opposite charges ______ and like charges ______.", "img": null, "choices": ["attract; repel", "repel; attract", "attract; attract", "repel; repel"], "answer": 0, "why": "", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-atomic-q150", "stem": "Ionic compounds conduct electricity only when…", "img": null, "choices": ["they gain protons", "melted or dissolved, so the ions can move", "they are solid", "they are cold"], "answer": 1, "why": "These are electrolytes.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-atomic-q151", "stem": "An “electrolyte” is a substance that…", "img": null, "choices": ["conducts electricity when dissolved or melted because its ions can move", "never conducts electricity", "has no charge", "is a metal"], "answer": 0, "why": "", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-atomic-q152", "stem": "When forming an ion, which particle can change?", "img": null, "choices": ["Electrons only", "Protons and electrons", "Neutrons and protons", "Protons only"], "answer": 0, "why": "Keep your hands off the nucleus!", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-atomic-q153", "stem": "Why are noble gases used to predict ion charges?", "img": null, "choices": ["They are metals", "They conduct electricity", "They have the most protons", "Their number of electrons is very stable, so atoms gain or lose e⁻ to match them"], "answer": 3, "why": "", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-atomic-q154", "stem": "Metals tend to ______ electrons and form ______ ions.", "img": null, "choices": ["gain; negative", "gain; positive", "lose; positive", "lose; negative"], "answer": 2, "why": "Cations.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-atomic-q155", "stem": "Nonmetals tend to ______ electrons and form ______ ions.", "img": null, "choices": ["gain; negative", "lose; negative", "lose; positive", "gain; positive"], "answer": 0, "why": "Anions.", "whyImg": "seed/img/chem-atomic-ions.svg"}]}, {"id": "seed-mcq-chem-mock1", "rev": 1, "kind": "mcq", "title": "Chem — Atomic Structure Mock Test 1", "folder": "Chem", "description": "71-question full-length mock test. Every study-guide topic, mixed like the real test. Use the periodic table when shown; the explanation diagram appears after you answer.", "cards": [], "questions": [{"id": "seed-mcq-chem-mock1-q0", "stem": "In which PERIOD is zinc (Zn)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["4", "6", "3", "5"], "answer": 0, "why": "Count rows down: Zn is in row 4.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock1-q1", "stem": "Who published the first formal model of the atom?", "img": null, "choices": ["John Dalton", "Democritus", "J.J. Thomson", "Ernest Rutherford"], "answer": 0, "why": "Dalton combined atomic ideas with the known elements."}, {"id": "seed-mcq-chem-mock1-q2", "stem": "An ion has 35 protons and 36 electrons. What is its charge?", "img": null, "choices": ["0", "2−", "1−", "1+"], "answer": 2, "why": "Charge = protons − electrons = 35 − 36 = −1.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock1-q3", "stem": "Which ion has the SAME number of electrons as xenon (Xe)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Br⁻", "K⁺", "Al³⁺", "Ba²⁺"], "answer": 3, "why": "Ba²⁺ has 56 − (+2) = 54 electrons, the same as Xe.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock1-q4", "stem": "How many TOTAL atoms are in Al₂O₃?", "img": null, "choices": ["6", "2", "5", "7"], "answer": 2, "why": "2 Al + 3 O = 5 atoms.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock1-q5", "stem": "Particles packed tightly in fixed positions that only vibrate describe a…", "img": null, "choices": ["liquid", "solid", "solution", "gas"], "answer": 1, "why": "", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock1-q6", "stem": "A bag of 60 coins has a total mass of 174.40 g. Type A coins are 3.11 g and type B coins are 2.50 g. How many type A coins are there?", "img": null, "choices": ["45", "20", "30", "40"], "answer": 3, "why": "3.11x + 2.50(60 − x) = 174.40 → 0.61x = 24.40 → x = 40.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock1-q7", "stem": "Which element is one of the alkali metals?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Radium (Ra)", "Chlorine (Cl)", "Sodium (Na)", "Argon (Ar)"], "answer": 2, "why": "Na is in the alkali metals column.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock1-q8", "stem": "An ion has 56 protons and 54 electrons. Which ion is it?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Xe²⁻", "Ba²⁺", "Ba²⁻", "Xe"], "answer": 1, "why": "56 protons = Ba. Charge = 56 − 54 = +2.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock1-q9", "stem": "Why should you know where the safety equipment is in YOUR lab?", "img": null, "choices": ["So you can get to it immediately in an emergency", "To be able to move it", "You won’t need it", "It’s only for the teacher"], "answer": 0, "why": "Know the eyewash, shower, extinguisher, blanket, exits.", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock1-q10", "stem": "In which PERIOD is gold (Au)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["1", "6", "5", "7"], "answer": 1, "why": "Count rows down: Au is in row 6.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock1-q11", "stem": "How many electrons are in <span class=\"isow\"><span class=\"iso\"><span>24</span><span>12</span></span><span class=\"isox\">Mg</span><span class=\"isoc\">2+</span></span>?", "img": null, "choices": ["14", "10", "24", "12"], "answer": 1, "why": "12 protons. A 2+ charge means lost 2 e⁻ → 12 − (+2) = 10.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock1-q12", "stem": "Which two particles have about the SAME mass?", "img": null, "choices": ["Proton and electron", "Neutron and electron", "Proton and neutron", "All three"], "answer": 2, "why": "Both are about 1 amu; the electron is about 0.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock1-q13", "stem": "Rutherford’s gold foil experiment showed…", "img": null, "choices": ["electrons have fixed energy levels", "a tiny, very dense nucleus with almost all the mass", "atoms are solid spheres", "the charge on an electron"], "answer": 1, "why": "Most alpha particles passed through; a few bounced back."}, {"id": "seed-mcq-chem-mock1-q14", "stem": "Work with toxic or strong-smelling vapors should be done in the…", "img": null, "choices": ["safety shower", "hallway", "fume hood", "sink"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock1-q15", "stem": "Element Z has 3 isotopes: 33.00 amu (80%), 34.00 amu (5%), 35.00 amu (15%). What is its average atomic mass?", "img": null, "choices": ["34.65 amu", "33.00 amu", "33.35 amu", "34.00 amu"], "answer": 2, "why": "(33 × 0.80) + (34 × 0.05) + (35 × 0.15) = 33.35 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock1-q16", "stem": "How many chromium atoms are in K₂Cr₂O₇?", "img": null, "choices": ["11", "4", "3", "2"], "answer": 3, "why": "Count Cr in K₂Cr₂O₇: 2.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock1-q17", "stem": "How many hydrogen atoms are in (NH₄)₃PO₄?", "img": null, "choices": ["13", "12", "20", "4"], "answer": 1, "why": "Count H in (NH₄)₃PO₄ (the subscript after parentheses multiplies everything inside): 12.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock1-q18", "stem": "How many oxygen atoms are in Ca(OH)₂?", "img": null, "choices": ["5", "1", "2", "3"], "answer": 2, "why": "Count O in Ca(OH)₂ (the subscript after parentheses multiplies everything inside): 2.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock1-q19", "stem": "What is the name of the F⁻ ion?", "img": null, "choices": ["Fluorine", "Fluoride", "Fluorine ion", "Fluorate"], "answer": 1, "why": "Anions (negative) change the ending to “-ide.”", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock1-q20", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>90</span><span>38</span></span><span class=\"isox\">Sr</span></span>?", "img": null, "choices": ["90 p⁺, 52 n⁰, 90 e⁻", "52 p⁺, 38 n⁰, 38 e⁻", "38 p⁺, 90 n⁰, 38 e⁻", "38 p⁺, 52 n⁰, 38 e⁻"], "answer": 3, "why": "Protons = Z = 38. Neutrons = 90 − 38 = 52. Neutral, so electrons = 38.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock1-q21", "stem": "Particles that are close together but can slide past each other describe a…", "img": null, "choices": ["solid", "liquid", "plasma", "gas"], "answer": 1, "why": "That’s why liquids flow.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock1-q22", "stem": "Alkali metals are the elements in…", "img": null, "choices": ["group 17 (7A)", "groups 3–12", "group 2 (2A)", "group 1 (1A), except hydrogen"], "answer": 3, "why": "Li, Na, K, Rb, Cs, Fr.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock1-q23", "stem": "Which family does bromine (Br) belong to?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Noble gases", "Alkaline earth metals", "Halogens", "Alkali metals"], "answer": 2, "why": "Br is in group 17: halogens.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock1-q24", "stem": "What group is zinc (Zn) in?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Group 4", "Group 11", "Group 13 (3A)", "Group 12"], "answer": 3, "why": "Zn is in column 12.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock1-q25", "stem": "Transition metals are the elements in…", "img": null, "choices": ["group 18", "groups 3–12 (the middle block)", "groups 1 and 2", "group 17"], "answer": 1, "why": "The d block in the middle of the table.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock1-q26", "stem": "In which PERIOD is lithium (Li)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["1", "4", "2", "3"], "answer": 2, "why": "Count rows down: Li is in row 2.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock1-q27", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>3</span><span>1</span></span><span class=\"isox\">H</span><span class=\"isoc\">−</span></span>?", "img": null, "choices": ["1 p⁺, 2 n⁰, 2 e⁻", "2 p⁺, 1 n⁰, 2 e⁻", "1 p⁺, 3 n⁰, 2 e⁻", "1 p⁺, 2 n⁰, 0 e⁻"], "answer": 0, "why": "Protons = Z = 1. Neutrons = 3 − 1 = 2. Electrons = 1 − (−1) = 2.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock1-q28", "stem": "How many neutrons are in zinc-64? (Use your periodic table.)", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["30", "34", "64", "94"], "answer": 1, "why": "Zinc has atomic number 30. In “zinc-64,” 64 is the mass number: 64 − 30 = 34.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock1-q29", "stem": "What does P-A-S-S stand for when using a fire extinguisher?", "img": null, "choices": ["Push, Aim, Spray, Stop", "Pull, Alert, Spray, Sweep", "Point, Aim, Shoot, Stop", "Pull, Aim, Squeeze, Sweep"], "answer": 3, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock1-q30", "stem": "How many electrons are in <span class=\"isow\"><span class=\"iso\"><span>3</span><span>1</span></span><span class=\"isox\">H</span><span class=\"isoc\">−</span></span>?", "img": null, "choices": ["2", "0", "1", "3"], "answer": 0, "why": "1 proton. A 1− charge means gained 1 e⁻ → 1 − (−1) = 2.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock1-q31", "stem": "A classmate’s clothing catches fire. Use the…", "img": null, "choices": ["eyewash", "fire blanket (stop, drop, and roll)", "fume hood", "broken-glass box"], "answer": 1, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock1-q32", "stem": "Which family does osmium (Os) belong to?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Transition metals", "Alkaline earth metals", "Halogens", "Alkali metals"], "answer": 0, "why": "Os is in group 8: transition metals.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock1-q33", "stem": "Which family does xenon (Xe) belong to?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Alkaline earth metals", "Transition metals", "Halogens", "Noble gases"], "answer": 3, "why": "Xe is in group 18: noble gases.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock1-q34", "stem": "Which state has a definite volume but takes the shape of its container?", "img": null, "choices": ["Gas", "Solid", "Liquid", "None"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock1-q35", "stem": "Alkaline earth metals are the elements in…", "img": null, "choices": ["group 1 (1A)", "group 18 (8A)", "groups 3–12", "group 2 (2A)"], "answer": 3, "why": "Be, Mg, Ca, Sr, Ba, Ra.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock1-q36", "stem": "What is the most likely charge on an ion of cesium (Cs)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["1−", "2+", "0", "1+"], "answer": 3, "why": "Cs = 55. Nearest noble gas is Xenon (54). Lose 1 e⁻ → Cs⁺.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock1-q37", "stem": "What is the most likely charge on an ion of aluminum (Al)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["3−", "3+", "0", "4+"], "answer": 1, "why": "Al = 13. Nearest noble gas is Neon (10). Lose 3 e⁻ → Al³⁺.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock1-q38", "stem": "Element Z has 2 isotopes: 90.00 amu (35%), 93.00 amu (65%). What is its average atomic mass?", "img": null, "choices": ["91.50 amu", "91.05 amu", "91.95 amu", "93.00 amu"], "answer": 2, "why": "(90 × 0.35) + (93 × 0.65) = 91.95 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock1-q39", "stem": "Isotope percent abundances are measured using…", "img": null, "choices": ["a mass spectrometer", "a Bunsen burner", "gold foil", "a Crookes tube"], "answer": 0, "why": "The mass spectrometer separates isotopes by mass.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock1-q40", "stem": "Element Z has 3 isotopes: 25.00 amu (80%), 26.00 amu (5%), 27.00 amu (15%). What is its average atomic mass?", "img": null, "choices": ["25.35 amu", "26.65 amu", "25.00 amu", "26.00 amu"], "answer": 0, "why": "(25 × 0.80) + (26 × 0.05) + (27 × 0.15) = 25.35 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock1-q41", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>40</span><span>18</span></span><span class=\"isox\">Ar</span></span>?", "img": null, "choices": ["22 p⁺, 18 n⁰, 18 e⁻", "18 p⁺, 40 n⁰, 18 e⁻", "40 p⁺, 22 n⁰, 40 e⁻", "18 p⁺, 22 n⁰, 18 e⁻"], "answer": 3, "why": "Protons = Z = 18. Neutrons = 40 − 18 = 22. Neutral, so electrons = 18.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock1-q42", "stem": "Which state is the easiest to compress?", "img": null, "choices": ["Liquid", "All are equally compressible", "Solid", "Gas"], "answer": 3, "why": "Gas particles are far apart.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock1-q43", "stem": "Which ion has the SAME number of electrons as argon (Ar)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["K⁺", "Cs⁺", "Al³⁺", "Br⁻"], "answer": 0, "why": "K⁺ has 19 − (+1) = 18 electrons, the same as Ar.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock1-q44", "stem": "An ion has 37 protons and 36 electrons. Which ion is it?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Kr", "Kr⁻", "Rb⁺", "Rb⁻"], "answer": 2, "why": "37 protons = Rb. Charge = 37 − 36 = +1.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock1-q45", "stem": "How many neutrons are in neon-20? (Use your periodic table.)", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["10", "20", "12", "30"], "answer": 0, "why": "Neon has atomic number 10. In “neon-20,” 20 is the mass number: 20 − 10 = 10.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock1-q46", "stem": "When diluting an acid you should…", "img": null, "choices": ["add the acid to the water", "add water to the acid", "heat the acid first", "mix them in any order"], "answer": 0, "why": "“Do as you oughta, add acid to water.”", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock1-q47", "stem": "An element’s average atomic mass is closest to the mass of…", "img": null, "choices": ["its lightest isotope", "its heaviest isotope", "its rarest isotope", "its most abundant isotope"], "answer": 3, "why": "The most common isotope carries the most “weight.”", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock1-q48", "stem": "What is the name of the Cs⁺ ion?", "img": null, "choices": ["Cesium ion", "Cesate", "Cesium-1", "Ceside"], "answer": 0, "why": "Cations (positive) keep the element’s name.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock1-q49", "stem": "An ion has 11 protons and 10 electrons. Which ion is it?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Ne", "Na⁺", "Na⁻", "Ne⁻"], "answer": 1, "why": "11 protons = Na. Charge = 11 − 10 = +1.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock1-q50", "stem": "How many electrons are in <span class=\"isow\"><span class=\"iso\"><span>64</span><span>30</span></span><span class=\"isox\">Zn</span><span class=\"isoc\">2+</span></span>?", "img": null, "choices": ["32", "28", "30", "64"], "answer": 1, "why": "30 protons. A 2+ charge means lost 2 e⁻ → 30 − (+2) = 28.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock1-q51", "stem": "To become stable, an atom of beryllium (Be) will most likely…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["gain 6 electrons", "lose 2 electrons", "lose 2 protons", "gain 2 electrons"], "answer": 1, "why": "Be = 4. Nearest noble gas is Helium (2). Lose 2 e⁻ → Be²⁺. It’s easier than moving 6 the other way.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock1-q52", "stem": "Which is NOT part of Dalton’s atomic theory?", "img": null, "choices": ["All matter is made of atoms", "Atoms have a tiny, dense, positive nucleus", "Atoms are rearranged in reactions", "Atoms combine in small whole-number ratios"], "answer": 1, "why": "The nucleus came from Rutherford (1909)."}, {"id": "seed-mcq-chem-mock1-q53", "stem": "A particle has 2 protons, 2 neutrons and 2 electrons. Which notation is correct?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["⁴₂He", "⁵₂He", "²₄He", "²₂He"], "answer": 0, "why": "Mass number = 2 + 2 = 4 (top). Atomic number 2 (bottom). Protons = electrons, so no charge.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock1-q54", "stem": "A bag of 50 coins has a total mass of 240.50 g. Type A coins are 6.25 g and type B coins are 4.00 g. How many type A coins are there?", "img": null, "choices": ["23", "18", "25", "32"], "answer": 1, "why": "6.25x + 4.00(50 − x) = 240.50 → 2.25x = 40.50 → x = 18.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock1-q55", "stem": "Which element exists as a DIATOMIC molecule in its standard state?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Sulfur (S)", "Chlorine (Cl)", "Phosphorus (P)", "Argon (Ar)"], "answer": 1, "why": "The Big 7: H₂, N₂, O₂, F₂, Cl₂, Br₂, I₂.", "whyImg": "seed/img/chem-atomic-diatomic.svg"}, {"id": "seed-mcq-chem-mock1-q56", "stem": "Lithium has these isotopes: Li-6 (6.015 amu, 7.59%), Li-7 (7.016 amu, 92.41%). What is its average atomic mass?", "img": null, "choices": ["6.52 amu", "6.94 amu", "7.02 amu", "6.09 amu"], "answer": 1, "why": "(6.015 × 0.0759) + (7.016 × 0.9241) = 6.94 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock1-q57", "stem": "Which particle determines what ELEMENT an atom is?", "img": null, "choices": ["Electron", "Neutron", "Nucleus size", "Proton"], "answer": 3, "why": "Change the protons and you have a different element.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock1-q58", "stem": "How many hydrogen atoms are in C₂₅H₅₂?", "img": null, "choices": ["77", "54", "52", "53"], "answer": 2, "why": "Count H in C₂₅H₅₂: 52.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock1-q59", "stem": "How many TOTAL atoms are in Zn₃(PO₄)₂?", "img": null, "choices": ["14", "13", "3", "8"], "answer": 1, "why": "3 Zn + 2 P + 8 O = 13 atoms.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock1-q60", "stem": "How many neutrons are in <span class=\"isow\"><span class=\"iso\"><span>64</span><span>30</span></span><span class=\"isox\">Zn</span><span class=\"isoc\">2+</span></span>?", "img": null, "choices": ["94", "30", "34", "64"], "answer": 2, "why": "Neutrons = mass number − atomic number = 64 − 30 = 34.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock1-q61", "stem": "In which PERIOD is germanium (Ge)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["6", "3", "5", "4"], "answer": 3, "why": "Count rows down: Ge is in row 4.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock1-q62", "stem": "Germanium (Ge) is a…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Metal", "Nonmetal", "Metalloid"], "answer": 2, "why": "Metals: left of the staircase. Nonmetals: right of it (plus H). Metalloids touch the staircase: B, Si, Ge, As, Sb, Te.", "whyImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-mcq-chem-mock1-q63", "stem": "In a NEUTRAL atom, the number of electrons equals the number of…", "img": null, "choices": ["protons + neutrons", "isotopes", "protons", "neutrons"], "answer": 2, "why": "Equal + and − charges cancel out.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock1-q64", "stem": "Nonmetals tend to ______ electrons and form ______ ions.", "img": null, "choices": ["lose; positive", "lose; negative", "gain; negative", "gain; positive"], "answer": 2, "why": "Anions.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock1-q65", "stem": "Sir William Crookes used a Crookes tube, an early…", "img": null, "choices": ["microscope", "cathode ray tube", "gold foil", "mass spectrometer"], "answer": 1, "why": "1879: electrical discharges in gases."}, {"id": "seed-mcq-chem-mock1-q66", "stem": "Which correctly counts the atoms in CCl₄?", "img": null, "choices": ["2 C, 4 Cl", "1 C, 4 Cl", "1 C, 1 Cl", "4 C, 1 Cl"], "answer": 1, "why": "Subscripts count the element right before them; a subscript after ( ) multiplies everything inside; a coefficient multiplies the whole formula.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock1-q67", "stem": "Which family does sodium (Na) belong to?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Transition metals", "Noble gases", "Alkali metals", "Halogens"], "answer": 2, "why": "Na is in group 1: alkali metals.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock1-q68", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>28</span><span>14</span></span><span class=\"isox\">Si</span></span>?", "img": null, "choices": ["28 p⁺, 14 n⁰, 28 e⁻", "14 p⁺, 14 n⁰, 14 e⁻", "14 p⁺, 28 n⁰, 14 e⁻", "14 p⁺, 15 n⁰, 14 e⁻"], "answer": 1, "why": "Protons = Z = 14. Neutrons = 28 − 14 = 14. Neutral, so electrons = 14.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock1-q69", "stem": "According to Dalton, in a chemical reaction atoms are…", "img": null, "choices": ["divided into smaller parts", "created and destroyed", "combined, separated, or rearranged, but never created or destroyed", "converted into other kinds of atoms"], "answer": 2, "why": "Point 4: atoms are the units of chemical change."}, {"id": "seed-mcq-chem-mock1-q70", "stem": "Opposite charges ______ and like charges ______.", "img": null, "choices": ["attract; attract", "repel; attract", "repel; repel", "attract; repel"], "answer": 3, "why": "", "whyImg": "seed/img/chem-atomic-ions.svg"}]}, {"id": "seed-mcq-chem-mock2", "rev": 1, "kind": "mcq", "title": "Chem — Atomic Structure Mock Test 2", "folder": "Chem", "description": "71-question full-length mock test. Every study-guide topic, mixed like the real test. Use the periodic table when shown; the explanation diagram appears after you answer.", "cards": [], "questions": [{"id": "seed-mcq-chem-mock2-q0", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>27</span><span>13</span></span><span class=\"isox\">Al</span></span>?", "img": null, "choices": ["27 p⁺, 14 n⁰, 27 e⁻", "13 p⁺, 14 n⁰, 13 e⁻", "14 p⁺, 13 n⁰, 13 e⁻", "13 p⁺, 27 n⁰, 13 e⁻"], "answer": 1, "why": "Protons = Z = 13. Neutrons = 27 − 13 = 14. Neutral, so electrons = 13.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock2-q1", "stem": "How many phosphorus atoms are in P₂O₅?", "img": null, "choices": ["3", "4", "2", "7"], "answer": 2, "why": "Count P in P₂O₅: 2.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock2-q2", "stem": "How many neutrons are in <span class=\"isow\"><span class=\"iso\"><span>64</span><span>30</span></span><span class=\"isox\">Zn</span><span class=\"isoc\">2+</span></span>?", "img": null, "choices": ["34", "64", "94", "30"], "answer": 0, "why": "Neutrons = mass number − atomic number = 64 − 30 = 34.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock2-q3", "stem": "What is the most likely charge on an ion of aluminum (Al)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["4+", "3−", "0", "3+"], "answer": 3, "why": "Al = 13. Nearest noble gas is Neon (10). Lose 3 e⁻ → Al³⁺.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock2-q4", "stem": "How many neutrons are in <span class=\"isow\"><span class=\"iso\"><span>18</span><span>8</span></span><span class=\"isox\">O</span></span>?", "img": null, "choices": ["8", "18", "26", "10"], "answer": 3, "why": "Neutrons = mass number − atomic number = 18 − 8 = 10.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock2-q5", "stem": "What group is radon (Rn) in?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Group 17 (7A)", "Group 16 (6A)", "Group 18 (8A)", "Group 6"], "answer": 2, "why": "Rn is in column 18.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock2-q6", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>22</span><span>10</span></span><span class=\"isox\">Ne</span></span>?", "img": null, "choices": ["12 p⁺, 10 n⁰, 10 e⁻", "22 p⁺, 12 n⁰, 22 e⁻", "10 p⁺, 22 n⁰, 10 e⁻", "10 p⁺, 12 n⁰, 10 e⁻"], "answer": 3, "why": "Protons = Z = 10. Neutrons = 22 − 10 = 12. Neutral, so electrons = 10.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock2-q7", "stem": "10 mL of water is poured from a tall cylinder into a wide beaker. What changes?", "img": null, "choices": ["Only its volume", "Neither", "Both shape and volume", "Only its shape"], "answer": 3, "why": "Liquids keep their volume.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock2-q8", "stem": "Which family does silver (Ag) belong to?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Alkali metals", "Noble gases", "Halogens", "Transition metals"], "answer": 3, "why": "Ag is in group 11: transition metals.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock2-q9", "stem": "Which states can flow?", "img": null, "choices": ["Gases only", "Solids and liquids", "Liquids and gases", "Solids only"], "answer": 2, "why": "Their particles can move past each other.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock2-q10", "stem": "What is the most likely charge on an ion of calcium (Ca)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["2−", "3+", "0", "2+"], "answer": 3, "why": "Ca = 20. Nearest noble gas is Argon (18). Lose 2 e⁻ → Ca²⁺.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock2-q11", "stem": "Which state has a definite shape AND a definite volume?", "img": null, "choices": ["Solid", "Liquid", "Liquid and gas", "Gas"], "answer": 0, "why": "", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock2-q12", "stem": "When must safety goggles be worn?", "img": null, "choices": ["Only when the teacher is watching", "Whenever chemicals, glassware, or heat are being used", "Only on test days", "Only when heating"], "answer": 1, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock2-q13", "stem": "What is the most likely charge on an ion of lithium (Li)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["1+", "0", "2+", "1−"], "answer": 0, "why": "Li = 3. Nearest noble gas is Helium (2). Lose 1 e⁻ → Li⁺.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock2-q14", "stem": "How many oxygen atoms are in Fe(OH)₃?", "img": null, "choices": ["4", "3", "7", "1"], "answer": 1, "why": "Count O in Fe(OH)₃ (the subscript after parentheses multiplies everything inside): 3.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock2-q15", "stem": "A large chemical spill soaks your clothes. Use the…", "img": null, "choices": ["fume hood", "fire extinguisher", "safety shower", "eyewash station only"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock2-q16", "stem": "How many oxygen atoms are in Ca₃(PO₄)₂?", "img": null, "choices": ["4", "8", "13", "9"], "answer": 1, "why": "Count O in Ca₃(PO₄)₂ (the subscript after parentheses multiplies everything inside): 8.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock2-q17", "stem": "Is it OK to eat or drink in the lab?", "img": null, "choices": ["Only water", "No, never", "Yes, if you wash your hands", "Only after the lab is done"], "answer": 1, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock2-q18", "stem": "What is the most likely charge on an ion of nitrogen (N)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["5+", "3+", "0", "3−"], "answer": 3, "why": "N = 7. Nearest noble gas is Neon (10). Gain 3 e⁻ → N³⁻.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock2-q19", "stem": "To become stable, an atom of selenium (Se) will most likely…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["lose 6 electrons", "gain 2 protons", "lose 2 electrons", "gain 2 electrons"], "answer": 3, "why": "Se = 34. Nearest noble gas is Krypton (36). Gain 2 e⁻ → Se²⁻. It’s easier than moving 6 the other way.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock2-q20", "stem": "A neutron is a…", "img": null, "choices": ["negative particle outside the nucleus", "positive particle in the nucleus", "neutral particle outside the nucleus with ~0 mass", "neutral particle in the nucleus with a mass of about 1 amu"], "answer": 3, "why": "Neutron: n⁰, 1 amu, 0 charge, nucleus.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock2-q21", "stem": "Manganese (Mn) is a…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Metalloid", "Nonmetal", "Metal"], "answer": 2, "why": "Metals: left of the staircase. Nonmetals: right of it (plus H). Metalloids touch the staircase: B, Si, Ge, As, Sb, Te.", "whyImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-mcq-chem-mock2-q22", "stem": "Which family does cesium (Cs) belong to?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Transition metals", "Halogens", "Alkali metals", "Alkaline earth metals"], "answer": 2, "why": "Cs is in group 1: alkali metals.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock2-q23", "stem": "Nickel (Ni) is a…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Nonmetal", "Metalloid", "Metal"], "answer": 2, "why": "Metals: left of the staircase. Nonmetals: right of it (plus H). Metalloids touch the staircase: B, Si, Ge, As, Sb, Te.", "whyImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-mcq-chem-mock2-q24", "stem": "How many neutrons are in <span class=\"isow\"><span class=\"iso\"><span>63</span><span>29</span></span><span class=\"isox\">Cu</span><span class=\"isoc\">+</span></span>?", "img": null, "choices": ["63", "29", "34", "92"], "answer": 2, "why": "Neutrons = mass number − atomic number = 63 − 29 = 34.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock2-q25", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>60</span><span>27</span></span><span class=\"isox\">Co</span><span class=\"isoc\">2+</span></span>?", "img": null, "choices": ["27 p⁺, 60 n⁰, 25 e⁻", "27 p⁺, 33 n⁰, 25 e⁻", "33 p⁺, 27 n⁰, 25 e⁻", "27 p⁺, 33 n⁰, 29 e⁻"], "answer": 1, "why": "Protons = Z = 27. Neutrons = 60 − 27 = 33. Electrons = 27 − (+2) = 25.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock2-q26", "stem": "An ion has 13 protons and 10 electrons. What is its charge?", "img": null, "choices": ["3−", "3+", "0", "6+"], "answer": 1, "why": "Charge = protons − electrons = 13 − 10 = +3.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock2-q27", "stem": "How should you smell a chemical?", "img": null, "choices": ["Taste it instead", "Take a deep breath over the beaker", "Put your nose right over it", "Waft the vapor toward your nose with your hand"], "answer": 3, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock2-q28", "stem": "How many TOTAL atoms are in Zn₃(PO₄)₂?", "img": null, "choices": ["13", "14", "3", "8"], "answer": 0, "why": "3 Zn + 2 P + 8 O = 13 atoms.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock2-q29", "stem": "Element Z has 3 isotopes: 67.00 amu (60%), 68.00 amu (10%), 69.00 amu (30%). What is its average atomic mass?", "img": null, "choices": ["68.30 amu", "67.70 amu", "67.00 amu", "68.00 amu"], "answer": 1, "why": "(67 × 0.60) + (68 × 0.10) + (69 × 0.30) = 67.70 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock2-q30", "stem": "Which state has NO definite shape and NO definite volume?", "img": null, "choices": ["Solid and liquid", "Liquid", "Gas", "Solid"], "answer": 2, "why": "Gases fill the whole container.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock2-q31", "stem": "What is the most likely charge on an ion of magnesium (Mg)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["2+", "3+", "2−", "0"], "answer": 0, "why": "Mg = 12. Nearest noble gas is Neon (10). Lose 2 e⁻ → Mg²⁺.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock2-q32", "stem": "Element Z has 2 isotopes: 83.00 amu (20%), 86.00 amu (80%). What is its average atomic mass?", "img": null, "choices": ["86.00 amu", "84.50 amu", "85.40 amu", "83.60 amu"], "answer": 2, "why": "(83 × 0.20) + (86 × 0.80) = 85.40 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock2-q33", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>40</span><span>20</span></span><span class=\"isox\">Ca</span></span>?", "img": null, "choices": ["20 p⁺, 40 n⁰, 20 e⁻", "20 p⁺, 21 n⁰, 20 e⁻", "20 p⁺, 20 n⁰, 20 e⁻", "40 p⁺, 20 n⁰, 40 e⁻"], "answer": 2, "why": "Protons = Z = 20. Neutrons = 40 − 20 = 20. Neutral, so electrons = 20.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock2-q34", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>85</span><span>37</span></span><span class=\"isox\">Rb</span><span class=\"isoc\">+</span></span>?", "img": null, "choices": ["37 p⁺, 85 n⁰, 36 e⁻", "48 p⁺, 37 n⁰, 36 e⁻", "37 p⁺, 48 n⁰, 36 e⁻", "37 p⁺, 48 n⁰, 38 e⁻"], "answer": 2, "why": "Protons = Z = 37. Neutrons = 85 − 37 = 48. Electrons = 37 − (+1) = 36.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock2-q35", "stem": "According to Dalton, compounds form when…", "img": null, "choices": ["one atom splits in two", "atoms are destroyed", "two or more different kinds of atoms combine in small whole-number ratios", "atoms combine in any random ratio"], "answer": 2, "why": "Point 3."}, {"id": "seed-mcq-chem-mock2-q36", "stem": "What group is scandium (Sc) in?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Group 2 (2A)", "Group 4", "Group 3", "Group 9"], "answer": 2, "why": "Sc is in column 3.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock2-q37", "stem": "Which is one of Dalton’s 4 points?", "img": null, "choices": ["Atoms have a nucleus", "Electrons are in energy levels", "All matter is made of atoms", "Atoms are mostly empty space"], "answer": 2, "why": "Point 1: all matter is made of atoms, the ultimate chemical particles."}, {"id": "seed-mcq-chem-mock2-q38", "stem": "An “electrolyte” is a substance that…", "img": null, "choices": ["conducts electricity when dissolved or melted because its ions can move", "has no charge", "is a metal", "never conducts electricity"], "answer": 0, "why": "", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock2-q39", "stem": "Selenium (Se) is a…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Metalloid", "Nonmetal", "Metal"], "answer": 1, "why": "Metals: left of the staircase. Nonmetals: right of it (plus H). Metalloids touch the staircase: B, Si, Ge, As, Sb, Te.", "whyImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-mcq-chem-mock2-q40", "stem": "The atomic mass (mass number) of an isotope equals…", "img": null, "choices": ["protons only", "protons + electrons", "protons + neutrons", "neutrons − protons"], "answer": 2, "why": "Electrons are too light to count.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock2-q41", "stem": "Where are electrons found?", "img": null, "choices": ["Somewhere outside the nucleus", "Only in the center of the atom", "Stuck to the protons", "Inside the nucleus"], "answer": 0, "why": "The nucleus holds only protons and neutrons.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock2-q42", "stem": "“amu” stands for…", "img": null, "choices": ["atomic mass unit", "average mass unit", "atomic measurement unit", "atomic molecule unit"], "answer": 0, "why": "Protons and neutrons are each about 1 amu.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock2-q43", "stem": "An element has these isotopes: X-79 (78.92 amu, 50.69%), X-81 (80.92 amu, 49.31%). Calculate its average atomic mass and use the periodic table to identify it.", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Rubidium (Rb)", "Bromine (Br)", "Krypton (Kr)", "Selenium (Se)"], "answer": 1, "why": "Average ≈ 79.91 amu, which matches Bromine on the periodic table.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock2-q44", "stem": "A particle has 3 protons, 4 neutrons and 3 electrons. Which notation is correct?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["³₇Li", "⁴₃Li", "⁸₃Li", "⁷₃Li"], "answer": 3, "why": "Mass number = 3 + 4 = 7 (top). Atomic number 3 (bottom). Protons = electrons, so no charge.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock2-q45", "stem": "What is the most likely charge on an ion of sulfur (S)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["0", "2+", "2−", "6+"], "answer": 2, "why": "S = 16. Nearest noble gas is Argon (18). Gain 2 e⁻ → S²⁻.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock2-q46", "stem": "Who discovered the neutron in 1932?", "img": null, "choices": ["Niels Bohr", "James Chadwick", "Ernest Rutherford", "Robert Millikan"], "answer": 1, "why": "Same mass as a proton, no charge."}, {"id": "seed-mcq-chem-mock2-q47", "stem": "According to Dalton, atoms of DIFFERENT elements…", "img": null, "choices": ["have the same number of protons", "can’t combine", "have different masses and properties", "are identical"], "answer": 2, "why": "Point 2, second half."}, {"id": "seed-mcq-chem-mock2-q48", "stem": "Element Z has 2 isotopes: 46.00 amu (10%), 47.00 amu (90%). What is its average atomic mass?", "img": null, "choices": ["46.90 amu", "47.00 amu", "46.10 amu", "46.50 amu"], "answer": 0, "why": "(46 × 0.10) + (47 × 0.90) = 46.90 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock2-q49", "stem": "What group is niobium (Nb) in?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Group 4", "Group 11", "Group 6", "Group 5"], "answer": 3, "why": "Nb is in column 5.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock2-q50", "stem": "Before multiplying, what do you do to a percent abundance like 75.77%?", "img": null, "choices": ["Divide by the mass", "Divide by 100 to make it a decimal (0.7577)", "Leave it as 75.77", "Multiply by 100"], "answer": 1, "why": "", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock2-q51", "stem": "An electron is a…", "img": null, "choices": ["negatively charged (−1) particle outside the nucleus with almost no mass", "positive particle in the nucleus", "negative particle inside the nucleus with a mass of 1 amu", "neutral particle in the nucleus"], "answer": 0, "why": "Electron: e⁻, ~0 amu, −1, somewhere outside the nucleus.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock2-q52", "stem": "Magnesium (Mg) is a…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Metalloid", "Nonmetal", "Metal"], "answer": 2, "why": "Metals: left of the staircase. Nonmetals: right of it (plus H). Metalloids touch the staircase: B, Si, Ge, As, Sb, Te.", "whyImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-mcq-chem-mock2-q53", "stem": "An ion is…", "img": null, "choices": ["an isotope", "an atom with extra neutrons", "an atom (or group of atoms) with a charge because it gained or lost electrons", "an atom with extra protons"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock2-q54", "stem": "To become stable, an atom of lithium (Li) will most likely…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["gain 1 electron", "lose 1 proton", "lose 1 electron", "gain 7 electrons"], "answer": 2, "why": "Li = 3. Nearest noble gas is Helium (2). Lose 1 e⁻ → Li⁺. It’s easier than moving 7 the other way.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock2-q55", "stem": "What is the name of the S²⁻ ion?", "img": null, "choices": ["Sulfide", "Sulfur ion", "Sulfur", "Sulfate"], "answer": 0, "why": "Anions (negative) change the ending to “-ide.”", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock2-q56", "stem": "Which element is one of the noble gases?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Tungsten (W)", "Iodine (I)", "Radon (Rn)", "Barium (Ba)"], "answer": 2, "why": "Rn is in the noble gases column.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock2-q57", "stem": "When heating a test tube, point the open end…", "img": null, "choices": ["away from yourself and others", "straight down", "toward your face so you can watch", "toward your lab partner"], "answer": 0, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock2-q58", "stem": "How many electrons are in <span class=\"isow\"><span class=\"iso\"><span>197</span><span>79</span></span><span class=\"isox\">Au</span><span class=\"isoc\">+</span></span>?", "img": null, "choices": ["197", "80", "78", "79"], "answer": 2, "why": "79 protons. A 1+ charge means lost 1 e⁻ → 79 − (+1) = 78.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock2-q59", "stem": "Which ion has the SAME number of electrons as krypton (Kr)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Ba²⁺", "Br⁻", "I⁻", "K⁺"], "answer": 1, "why": "Br⁻ has 35 − (−1) = 36 electrons, the same as Kr.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock2-q60", "stem": "How many hydrogen atoms are in 3H₂O?", "img": null, "choices": ["9", "8", "6", "2"], "answer": 2, "why": "Count H in 3H₂O, then multiply by the coefficient 3: 6.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock2-q61", "stem": "Which part of the atom contains almost all of its mass?", "img": null, "choices": ["The outer electrons", "The electron cloud", "The nucleus", "The empty space"], "answer": 2, "why": "Protons + neutrons are in the nucleus.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock2-q62", "stem": "Who first said matter is made of tiny indivisible particles called “atomos”?", "img": null, "choices": ["Dalton", "Bohr", "Thomson", "Democritus (and Leucippus)"], "answer": 3, "why": "460–370 BC."}, {"id": "seed-mcq-chem-mock2-q63", "stem": "Silicon has these isotopes: Si-28 (27.98 amu, 92.23%), Si-29 (28.98 amu, 4.68%), Si-30 (29.97 amu, 3.09%). What is its average atomic mass?", "img": null, "choices": ["28.98 amu", "27.98 amu", "28.96 amu", "28.09 amu"], "answer": 3, "why": "(27.98 × 0.9223) + (28.98 × 0.0468) + (29.97 × 0.0309) = 28.09 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock2-q64", "stem": "How many hydrogen atoms are in C₁₂H₂₂O₁₁?", "img": null, "choices": ["22", "24", "45", "23"], "answer": 0, "why": "Count H in C₁₂H₂₂O₁₁: 22.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock2-q65", "stem": "Which family does chlorine (Cl) belong to?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Halogens", "Transition metals", "Noble gases", "Alkaline earth metals"], "answer": 0, "why": "Cl is in group 17: halogens.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock2-q66", "stem": "Bromine has these isotopes: Br-79 (78.92 amu, 50.69%), Br-81 (80.92 amu, 49.31%). What is its average atomic mass?", "img": null, "choices": ["78.92 amu", "79.91 amu", "79.92 amu", "79.93 amu"], "answer": 1, "why": "(78.92 × 0.5069) + (80.92 × 0.4931) = 79.91 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock2-q67", "stem": "An element’s isotope percent abundances always add up to…", "img": null, "choices": ["its atomic number", "1%", "100%", "50%"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock2-q68", "stem": "How many oxygen atoms are in C₆H₁₂O₆?", "img": null, "choices": ["7", "24", "8", "6"], "answer": 3, "why": "Count O in C₆H₁₂O₆: 6.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock2-q69", "stem": "Which element exists as a DIATOMIC molecule in its standard state?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Magnesium (Mg)", "Hydrogen (H)", "Iron (Fe)", "Silicon (Si)"], "answer": 1, "why": "The Big 7: H₂, N₂, O₂, F₂, Cl₂, Br₂, I₂.", "whyImg": "seed/img/chem-atomic-diatomic.svg"}, {"id": "seed-mcq-chem-mock2-q70", "stem": "How many neutrons are in cesium-137? (Use your periodic table.)", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["82", "137", "55", "192"], "answer": 0, "why": "Cesium has atomic number 55. In “cesium-137,” 137 is the mass number: 137 − 55 = 82.", "whyImg": "seed/img/chem-atomic-iso.svg"}]}, {"id": "seed-mcq-chem-mock3", "rev": 1, "kind": "mcq", "title": "Chem — Atomic Structure Mock Test 3", "folder": "Chem", "description": "71-question full-length mock test. Every study-guide topic, mixed like the real test. Use the periodic table when shown; the explanation diagram appears after you answer.", "cards": [], "questions": [{"id": "seed-mcq-chem-mock3-q0", "stem": "What is the name of the I⁻ ion?", "img": null, "choices": ["Iodide", "Iodine", "Iodate", "Iodine ion"], "answer": 0, "why": "Anions (negative) change the ending to “-ide.”", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock3-q1", "stem": "An isotope is…", "img": null, "choices": ["an atom of the same element with a different number of neutrons", "an atom with a different number of protons", "an atom that has gained or lost electrons", "a different element with the same mass"], "answer": 0, "why": "Same protons, different neutrons → different mass.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock3-q2", "stem": "How many iron atoms are in Fe₂O₃?", "img": null, "choices": ["5", "4", "2", "3"], "answer": 2, "why": "Count Fe in Fe₂O₃: 2.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock3-q3", "stem": "Manganese (Mn) is a…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Nonmetal", "Metal", "Metalloid"], "answer": 1, "why": "Metals: left of the staircase. Nonmetals: right of it (plus H). Metalloids touch the staircase: B, Si, Ge, As, Sb, Te.", "whyImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-mcq-chem-mock3-q4", "stem": "Why are noble gases used to predict ion charges?", "img": null, "choices": ["They have the most protons", "Their number of electrons is very stable, so atoms gain or lose e⁻ to match them", "They conduct electricity", "They are metals"], "answer": 1, "why": "", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock3-q5", "stem": "What group is palladium (Pd) in?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Group 9", "Group 11", "Group 5", "Group 10"], "answer": 3, "why": "Pd is in column 10.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock3-q6", "stem": "How many electrons does the most common ion of calcium (Ca) have?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["22", "18", "24", "20"], "answer": 1, "why": "Ca = 20. Nearest noble gas is Argon (18). Lose 2 e⁻ → Ca²⁺. Electrons = 20 − (+2) = 18.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock3-q7", "stem": "How does pure bromine naturally exist?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Br⁻", "Br", "Br₃", "Br₂"], "answer": 3, "why": "Bromine is one of the 7 diatomic elements, so it exists as Br₂.", "whyImg": "seed/img/chem-atomic-diatomic.svg"}, {"id": "seed-mcq-chem-mock3-q8", "stem": "What group is osmium (Os) in?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Group 9", "Group 7", "Group 8", "Group 6"], "answer": 2, "why": "Os is in column 8.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock3-q9", "stem": "According to Dalton, all atoms of a given element are…", "img": null, "choices": ["made of protons only", "different in mass", "identical in mass and other properties", "able to change into other elements"], "answer": 2, "why": "Point 2. (Isotopes later showed this isn’t exactly true.)"}, {"id": "seed-mcq-chem-mock3-q10", "stem": "How many electrons does the most common ion of magnesium (Mg) have?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["10", "14", "12", "16"], "answer": 0, "why": "Mg = 12. Nearest noble gas is Neon (10). Lose 2 e⁻ → Mg²⁺. Electrons = 12 − (+2) = 10.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock3-q11", "stem": "An ion has 34 protons and 36 electrons. What is its charge?", "img": null, "choices": ["0", "2−", "2+", "4−"], "answer": 1, "why": "Charge = protons − electrons = 34 − 36 = −2.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock3-q12", "stem": "An atom of carbon has 6 neutrons. What is its mass number? (Use your periodic table.)", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["12", "7", "6", "13"], "answer": 0, "why": "Carbon: Z = 6. Mass number = 6 + 6 = 12.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock3-q13", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>63</span><span>29</span></span><span class=\"isox\">Cu</span><span class=\"isoc\">2+</span></span>?", "img": null, "choices": ["29 p⁺, 34 n⁰, 27 e⁻", "29 p⁺, 34 n⁰, 31 e⁻", "34 p⁺, 29 n⁰, 27 e⁻", "29 p⁺, 63 n⁰, 27 e⁻"], "answer": 0, "why": "Protons = Z = 29. Neutrons = 63 − 29 = 34. Electrons = 29 − (+2) = 27.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock3-q14", "stem": "An ion has 56 protons and 54 electrons. What is its charge?", "img": null, "choices": ["4+", "2−", "0", "2+"], "answer": 3, "why": "Charge = protons − electrons = 56 − 54 = +2.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock3-q15", "stem": "How many oxygen atoms are in 6CO₂?", "img": null, "choices": ["2", "12", "14", "18"], "answer": 1, "why": "Count O in 6CO₂, then multiply by the coefficient 6: 12.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock3-q16", "stem": "An element has these isotopes: X-10 (10.01 amu, 19.9%), X-11 (11.01 amu, 80.1%). Calculate its average atomic mass and use the periodic table to identify it.", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Nitrogen (N)", "Carbon (C)", "Beryllium (Be)", "Boron (B)"], "answer": 3, "why": "Average ≈ 10.81 amu, which matches Boron on the periodic table.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock3-q17", "stem": "Henri Becquerel (1896) discovered…", "img": null, "choices": ["the electron", "radioactivity", "the neutron", "the nucleus"], "answer": 1, "why": ""}, {"id": "seed-mcq-chem-mock3-q18", "stem": "In which state do particles move the fastest and are farthest apart?", "img": null, "choices": ["Gas", "They are all the same", "Solid", "Liquid"], "answer": 0, "why": "", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock3-q19", "stem": "Robert Millikan (1909) measured…", "img": null, "choices": ["radioactivity", "the charge on an electron", "the size of the nucleus", "the mass of a neutron"], "answer": 1, "why": "Oil drop experiment; used to find the electron’s mass."}, {"id": "seed-mcq-chem-mock3-q20", "stem": "A bag of 40 coins has a total mass of 131.75 g. Type A coins are 2.27 g and type B coins are 5.00 g. How many type A coins are there?", "img": null, "choices": ["30", "20", "15", "25"], "answer": 3, "why": "2.27x + 5.00(40 − x) = 131.75 → -2.73x = -68.25 → x = 25.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock3-q21", "stem": "To become stable, an atom of fluorine (F) will most likely…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["gain 1 electron", "lose 7 electrons", "lose 1 electron", "gain 1 proton"], "answer": 0, "why": "F = 9. Nearest noble gas is Neon (10). Gain 1 e⁻ → F⁻. It’s easier than moving 7 the other way.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock3-q22", "stem": "How many electrons are in <span class=\"isow\"><span class=\"iso\"><span>41</span><span>19</span></span><span class=\"isox\">K</span><span class=\"isoc\">+</span></span>?", "img": null, "choices": ["41", "20", "18", "19"], "answer": 2, "why": "19 protons. A 1+ charge means lost 1 e⁻ → 19 − (+1) = 18.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock3-q23", "stem": "A particle has 1 proton, 2 neutrons and 2 electrons. Which notation is correct?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["²₁H⁻", "³₁H⁺", "³₁H⁻", "¹₃H⁻"], "answer": 2, "why": "Mass number = 1 + 2 = 3 (top). Atomic number 1 (bottom). 1 − 2 = −1 charge.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock3-q24", "stem": "Particles packed tightly in fixed positions that only vibrate describe a…", "img": null, "choices": ["liquid", "solid", "solution", "gas"], "answer": 1, "why": "", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock3-q25", "stem": "Lanthanum (La) is a…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Nonmetal", "Metal", "Metalloid"], "answer": 1, "why": "Metals: left of the staircase. Nonmetals: right of it (plus H). Metalloids touch the staircase: B, Si, Ge, As, Sb, Te.", "whyImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-mcq-chem-mock3-q26", "stem": "What group is titanium (Ti) in?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Group 4", "Group 5", "Group 10", "Group 3"], "answer": 0, "why": "Ti is in column 4.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock3-q27", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>81</span><span>35</span></span><span class=\"isox\">Br</span></span>?", "img": null, "choices": ["35 p⁺, 81 n⁰, 35 e⁻", "35 p⁺, 46 n⁰, 35 e⁻", "81 p⁺, 46 n⁰, 81 e⁻", "46 p⁺, 35 n⁰, 35 e⁻"], "answer": 1, "why": "Protons = Z = 35. Neutrons = 81 − 35 = 46. Neutral, so electrons = 35.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock3-q28", "stem": "The atomic number of an element is the number of…", "img": null, "choices": ["electrons in an ion", "protons", "neutrons", "protons + neutrons"], "answer": 1, "why": "Atomic number (Z) = # protons. It identifies the element.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock3-q29", "stem": "Halogens are the elements in…", "img": null, "choices": ["group 1 (1A)", "group 18 (8A)", "group 17 (7A)", "group 16 (6A)"], "answer": 2, "why": "F, Cl, Br, I, At.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock3-q30", "stem": "Which ion has the SAME number of electrons as neon (Ne)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Rb⁺", "Ca²⁺", "Al³⁺", "Br⁻"], "answer": 2, "why": "Al³⁺ has 13 − (+3) = 10 electrons, the same as Ne.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock3-q31", "stem": "Which element is one of the transition metals?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Osmium (Os)", "Fluorine (F)", "Cesium (Cs)", "Beryllium (Be)"], "answer": 0, "why": "Os is in the transition metals column.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock3-q32", "stem": "How many TOTAL atoms are in CuSO₄?", "img": null, "choices": ["7", "6", "8", "3"], "answer": 1, "why": "1 Cu + 1 S + 4 O = 6 atoms.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock3-q33", "stem": "What should you do with leftover chemical you didn’t use?", "img": null, "choices": ["Dispose of it as the teacher directs, never back in the stock bottle", "Pour it back into the stock bottle", "Take it home", "Mix it with another chemical"], "answer": 0, "why": "Returning it can contaminate the whole bottle.", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock3-q34", "stem": "How many magnesium atoms are in 3Mg(NO₃)₂?", "img": null, "choices": ["3", "1", "27", "5"], "answer": 0, "why": "Count Mg in 3Mg(NO₃)₂ (the subscript after parentheses multiplies everything inside), then multiply by the coefficient 3: 3.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock3-q35", "stem": "Particles that are close together but can slide past each other describe a…", "img": null, "choices": ["liquid", "solid", "plasma", "gas"], "answer": 0, "why": "That’s why liquids flow.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock3-q36", "stem": "When forming an ion, which particle can change?", "img": null, "choices": ["Protons only", "Neutrons and protons", "Protons and electrons", "Electrons only"], "answer": 3, "why": "Keep your hands off the nucleus!", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock3-q37", "stem": "You cut your finger on glassware. What is the FIRST thing to do?", "img": null, "choices": ["Tell the teacher right away", "Put the glass back", "Leave class without telling anyone", "Hide it and keep working"], "answer": 0, "why": "Report ALL accidents, even small ones.", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock3-q38", "stem": "A bag of 40 coins has a total mass of 200.50 g. Type A coins are 6.25 g and type B coins are 4.00 g. How many type A coins are there?", "img": null, "choices": ["22", "18", "23", "20"], "answer": 1, "why": "6.25x + 4.00(40 − x) = 200.50 → 2.25x = 40.50 → x = 18.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock3-q39", "stem": "Which family does fluorine (F) belong to?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Transition metals", "Halogens", "Noble gases", "Alkali metals"], "answer": 1, "why": "F is in group 17: halogens.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock3-q40", "stem": "Silicon has these isotopes: Si-28 (27.98 amu, 92.23%), Si-29 (28.98 amu, 4.68%), Si-30 (29.97 amu, 3.09%). What is its average atomic mass?", "img": null, "choices": ["27.98 amu", "28.96 amu", "28.09 amu", "28.98 amu"], "answer": 2, "why": "(27.98 × 0.9223) + (28.98 × 0.0468) + (29.97 × 0.0309) = 28.09 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock3-q41", "stem": "Zirconium (Zr) is a…", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Metalloid", "Metal", "Nonmetal"], "answer": 1, "why": "Metals: left of the staircase. Nonmetals: right of it (plus H). Metalloids touch the staircase: B, Si, Ge, As, Sb, Te.", "whyImg": "seed/img/chem-atomic-metals.svg"}, {"id": "seed-mcq-chem-mock3-q42", "stem": "How many neutrons are in boron-11? (Use your periodic table.)", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["16", "11", "5", "6"], "answer": 3, "why": "Boron has atomic number 5. In “boron-11,” 11 is the mass number: 11 − 5 = 6.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock3-q43", "stem": "How many chlorine atoms are in CCl₄?", "img": null, "choices": ["6", "3", "4", "5"], "answer": 2, "why": "Count Cl in CCl₄: 4.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock3-q44", "stem": "What kind of shoes are safe in the lab?", "img": null, "choices": ["Closed-toe shoes", "Sandals", "Any shoes", "Flip-flops"], "answer": 0, "why": "Protect feet from spills and broken glass.", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock3-q45", "stem": "Average atomic mass is like your grade in class because…", "img": null, "choices": ["you drop the lowest isotope", "every isotope counts equally", "it only counts the heaviest isotope", "items that count more (more abundant isotopes) have more weight"], "answer": 3, "why": "It’s a weighted average.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock3-q46", "stem": "J.J. Thomson’s “plum pudding” model showed…", "img": null, "choices": ["electrons in fixed energy levels", "neutrons in the nucleus", "a dense nucleus", "+ and − charged pieces spread throughout the atom"], "answer": 3, "why": "Thomson (1897) proved cathode rays are electrons."}, {"id": "seed-mcq-chem-mock3-q47", "stem": "A group on the periodic table is…", "img": null, "choices": ["a vertical column", "a horizontal row", "a block of transition metals", "the staircase line"], "answer": 0, "why": "Groups (families) are columns; elements in a group act alike.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock3-q48", "stem": "Lithium has these isotopes: Li-6 (6.015 amu, 7.59%), Li-7 (7.016 amu, 92.41%). What is its average atomic mass?", "img": null, "choices": ["6.09 amu", "6.52 amu", "6.94 amu", "7.02 amu"], "answer": 2, "why": "(6.015 × 0.0759) + (7.016 × 0.9241) = 6.94 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock3-q49", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>32</span><span>16</span></span><span class=\"isox\">S</span></span>?", "img": null, "choices": ["16 p⁺, 32 n⁰, 16 e⁻", "32 p⁺, 16 n⁰, 32 e⁻", "16 p⁺, 17 n⁰, 16 e⁻", "16 p⁺, 16 n⁰, 16 e⁻"], "answer": 3, "why": "Protons = Z = 16. Neutrons = 32 − 16 = 16. Neutral, so electrons = 16.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock3-q50", "stem": "How many electrons does the most common ion of rubidium (Rb) have?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["38", "36", "37", "39"], "answer": 1, "why": "Rb = 37. Nearest noble gas is Krypton (36). Lose 1 e⁻ → Rb⁺. Electrons = 37 − (+1) = 36.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock3-q51", "stem": "A particle has 35 protons, 46 neutrons and 36 electrons. Which notation is correct?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["⁴⁶₃₅Br⁻", "⁸¹₃₅Br⁺", "⁸¹₃₅Br⁻", "³⁵₈₁Br⁻"], "answer": 2, "why": "Mass number = 35 + 46 = 81 (top). Atomic number 35 (bottom). 35 − 36 = −1 charge.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock3-q52", "stem": "What is the most likely charge on an ion of iodine (I)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["0", "1−", "1+", "7+"], "answer": 1, "why": "I = 53. Nearest noble gas is Xenon (54). Gain 1 e⁻ → I⁻.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock3-q53", "stem": "Which part of Dalton’s theory did isotopes prove wrong?", "img": null, "choices": ["All atoms of an element are identical in mass", "Atoms combine in whole-number ratios", "Atoms are rearranged in reactions", "All matter is made of atoms"], "answer": 0, "why": "Isotopes = same element, different masses."}, {"id": "seed-mcq-chem-mock3-q54", "stem": "How many oxygen atoms are in Pb(NO₃)₂?", "img": null, "choices": ["3", "6", "7", "9"], "answer": 1, "why": "Count O in Pb(NO₃)₂ (the subscript after parentheses multiplies everything inside): 6.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock3-q55", "stem": "How many protons, neutrons and electrons are in <span class=\"isow\"><span class=\"iso\"><span>40</span><span>20</span></span><span class=\"isox\">Ca</span><span class=\"isoc\">2+</span></span>?", "img": null, "choices": ["20 p⁺, 20 n⁰, 18 e⁻", "20 p⁺, 20 n⁰, 22 e⁻", "20 p⁺, 40 n⁰, 18 e⁻", "20 p⁺, 20 n⁰, 20 e⁻"], "answer": 0, "why": "Protons = Z = 20. Neutrons = 40 − 20 = 20. Electrons = 20 − (+2) = 18.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock3-q56", "stem": "How does pure iodine naturally exist?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["I₂", "I", "I⁻", "I₃"], "answer": 0, "why": "Iodine is one of the 7 diatomic elements, so it exists as I₂.", "whyImg": "seed/img/chem-atomic-diatomic.svg"}, {"id": "seed-mcq-chem-mock3-q57", "stem": "How many neutrons are in phosphorus-31? (Use your periodic table.)", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["46", "31", "16", "15"], "answer": 2, "why": "Phosphorus has atomic number 15. In “phosphorus-31,” 31 is the mass number: 31 − 15 = 16.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock3-q58", "stem": "Noble gases are the elements in…", "img": null, "choices": ["group 18 (8A)", "group 1 (1A)", "group 2 (2A)", "group 17 (7A)"], "answer": 0, "why": "He, Ne, Ar, Kr, Xe, Rn: very stable and unreactive.", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock3-q59", "stem": "What is the most likely charge on an ion of cesium (Cs)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["2+", "1+", "0", "1−"], "answer": 1, "why": "Cs = 55. Nearest noble gas is Xenon (54). Lose 1 e⁻ → Cs⁺.", "whyImg": "seed/img/chem-atomic-charges.svg"}, {"id": "seed-mcq-chem-mock3-q60", "stem": "Long hair and loose clothing in the lab should be…", "img": null, "choices": ["left as is", "tied back / secured", "only a problem on test days", "covered with a paper towel"], "answer": 1, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock3-q61", "stem": "A period on the periodic table is…", "img": null, "choices": ["a horizontal row", "a family of similar elements", "a vertical column", "the metals on the left"], "answer": 0, "why": "There are 7 periods (rows).", "whyImg": "seed/img/chem-atomic-atom.svg"}, {"id": "seed-mcq-chem-mock3-q62", "stem": "An ion has 12 protons and 10 electrons. What is its charge?", "img": null, "choices": ["2−", "2+", "4+", "0"], "answer": 1, "why": "Charge = protons − electrons = 12 − 10 = +2.", "whyImg": "seed/img/chem-atomic-ions.svg"}, {"id": "seed-mcq-chem-mock3-q63", "stem": "How many TOTAL atoms are in Al₂O₃?", "img": null, "choices": ["2", "6", "7", "5"], "answer": 3, "why": "2 Al + 3 O = 5 atoms.", "whyImg": "seed/img/chem-atomic-formula.svg"}, {"id": "seed-mcq-chem-mock3-q64", "stem": "Which is true about elements in nature?", "img": null, "choices": ["Helium is more abundant on Earth than oxygen", "All elements are equally abundant", "Every element exists naturally", "Some elements are much more abundant than others, and some are only man-made"], "answer": 3, "why": "", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock3-q65", "stem": "Chlorine has these isotopes: Cl-35 (34.97 amu, 75.77%), Cl-37 (36.97 amu, 24.23%). What is its average atomic mass?", "img": null, "choices": ["35.97 amu", "34.97 amu", "36.49 amu", "35.45 amu"], "answer": 3, "why": "(34.97 × 0.7577) + (36.97 × 0.2423) = 35.45 amu.", "whyImg": "seed/img/chem-atomic-aam.svg"}, {"id": "seed-mcq-chem-mock3-q66", "stem": "An atom of argon has 22 neutrons. What is its mass number? (Use your periodic table.)", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["40", "18", "4", "22"], "answer": 0, "why": "Argon: Z = 18. Mass number = 18 + 22 = 40.", "whyImg": "seed/img/chem-atomic-iso.svg"}, {"id": "seed-mcq-chem-mock3-q67", "stem": "A chemical splashes in your eye. You should…", "img": null, "choices": ["rub your eye", "wait until class ends", "flush it at the eyewash station for about 15 minutes and tell the teacher", "wipe it with a paper towel"], "answer": 2, "why": "", "whyImg": "seed/img/chem-atomic-safety.svg"}, {"id": "seed-mcq-chem-mock3-q68", "stem": "A gas is moved from a small container into a much larger one. What happens?", "img": null, "choices": ["It keeps its original volume", "It sinks to the bottom as a layer", "It turns into a liquid", "It spreads out to fill the larger container"], "answer": 3, "why": "Gases have no definite volume.", "whyImg": "seed/img/chem-atomic-states.svg"}, {"id": "seed-mcq-chem-mock3-q69", "stem": "In which PERIOD is nitrogen (N)?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["4", "1", "2", "3"], "answer": 2, "why": "Count rows down: N is in row 2.", "whyImg": "seed/img/chem-atomic-pt.svg"}, {"id": "seed-mcq-chem-mock3-q70", "stem": "Which element is one of the noble gases?", "img": "seed/img/chem-atomic-pt-blank.svg", "choices": ["Molybdenum (Mo)", "Helium (He)", "Chlorine (Cl)", "Rubidium (Rb)"], "answer": 1, "why": "He is in the noble gases column.", "whyImg": "seed/img/chem-atomic-pt.svg"}]}, {"id": "seed-chem-nomen-rules", "rev": 1, "title": "Chem — Nomenclature: Rules & Ions", "folder": "Chem", "description": "Every rule from the Nomenclature slides: compound types, ionic naming, polyatomic ions, transition-metal Roman numerals, molecular prefixes, acids, alkanes.", "cards": [{"id": "seed-chem-nomen-rules-0", "term": "What does “nomenclature” mean?", "def": "A naming system. Chemistry has three main ones: ionic compounds, molecular compounds, and organic (carbon-containing) compounds. Acids get their own rules too."}, {"id": "seed-chem-nomen-rules-1", "term": "STEP 1 of naming anything", "def": "Identify the TYPE of compound first: ionic, molecular, acid, or organic. Each type uses different rules.", "note": "Ionic = metal + nonmetal (or a polyatomic ion). Molecular = nonmetal + nonmetal. Acid = formula starts with H. Organic = C and H (alkanes: CₙH₂ₙ₊₂)."}, {"id": "seed-chem-nomen-rules-2", "term": "How do you recognize an IONIC compound?", "def": "Metal + nonmetal, OR it contains a polyatomic ion (including NH₄⁺).", "note": "Shortcuts: more than 2 elements → probably ionic. Name ends in something other than “-ide” → probably has a polyatomic ion."}, {"id": "seed-chem-nomen-rules-3", "term": "How do you recognize a MOLECULAR compound?", "def": "Nonmetal + nonmetal only (covalent bonds). Examples: CO₂, N₂O₄, SF₆."}, {"id": "seed-chem-nomen-rules-4", "term": "How do you recognize an ACID?", "def": "The formula starts with H (and it gives off H⁺ in water). Examples: HCl, H₂SO₄, HNO₂."}, {"id": "seed-chem-nomen-rules-5", "term": "How do you recognize an ORGANIC compound (alkane)?", "def": "Only C and H, fitting CₙH₂ₙ₊₂. Name ends in “-ane”."}, {"id": "seed-chem-nomen-rules-6", "term": "Lattice vs. discrete molecules", "def": "Ionic compounds form a LATTICE (huge repeating grid of ions, no separate molecules). Molecular compounds exist as DISCRETE molecules (each CO₂ is its own separate unit)."}, {"id": "seed-chem-nomen-rules-7", "term": "What is a formula unit?", "def": "The lowest whole-number ratio of cation to anion in an ionic lattice.", "note": "A NaCl crystal has billions of ions, but always 1 Na⁺ for every 1 Cl⁻, so the formula unit is NaCl."}, {"id": "seed-chem-nomen-rules-8", "term": "Which side of the periodic table loses e⁻? Which gains?", "def": "Left side (metals) LOSES electrons → cations (+). Far right (nonmetals) GAINS electrons → anions (−)."}, {"id": "seed-chem-nomen-rules-9", "term": "RULE: naming ANY ionic compound", "def": "(Cation name) + (Anion name). Always. Never use prefixes like di- or tri- for ionic compounds.", "note": "Na₂S is “sodium sulfide,” NOT “disodium sulfide.”"}, {"id": "seed-chem-nomen-rules-10", "term": "RULE: naming a simple cation", "def": "Same as the element name. Na⁺ = sodium, Ca²⁺ = calcium, Al³⁺ = aluminum."}, {"id": "seed-chem-nomen-rules-11", "term": "RULE: naming a simple anion", "def": "Change the element’s ending to “-ide.” Cl → chloride, O → oxide, S → sulfide, N → nitride, P → phosphide, F → fluoride, I → iodide, Br → bromide."}, {"id": "seed-chem-nomen-rules-12", "term": "RULE: writing an ionic formula from its name", "def": "Ions combine in whatever ratio makes the total charge ZERO (electrically neutral).", "note": "Shortcut “criss-cross”: the size of each charge becomes the other ion’s subscript, then reduce. Al³⁺ + O²⁻ → Al₂O₃."}, {"id": "seed-chem-nomen-rules-13", "term": "Worked example: potassium oxide", "def": "K⁺ (1+) and O²⁻ (2−). You need 2 K⁺ to cancel one O²⁻ → K₂O."}, {"id": "seed-chem-nomen-rules-14", "term": "Worked example: aluminum oxide", "def": "Al³⁺ and O²⁻. LCM of 3 and 2 is 6: 2 Al³⁺ (+6) and 3 O²⁻ (−6) → Al₂O₃."}, {"id": "seed-chem-nomen-rules-15", "term": "Common simple ion charges by group", "def": "Group 1: 1+. Group 2: 2+. Al: 3+. N, P: 3−. O, S: 2−. Halogens (F, Cl, Br, I): 1−."}, {"id": "seed-chem-nomen-rules-16", "term": "What is a polyatomic ion?", "def": "A group of atoms bonded together that, as a unit, has gained or lost electrons. Example: SO₄²⁻ is one S + four O with an overall 2− charge."}, {"id": "seed-chem-nomen-rules-17", "term": "Which common polyatomic ion is a CATION?", "def": "Ammonium, NH₄⁺. It’s the only common one; all the others are anions."}, {"id": "seed-chem-nomen-rules-18", "term": "Polyatomic ions: CN⁻", "def": "cyanide"}, {"id": "seed-chem-nomen-rules-19", "term": "Polyatomic ions: OH⁻", "def": "hydroxide"}, {"id": "seed-chem-nomen-rules-20", "term": "Polyatomic ions: NO₃⁻ vs NO₂⁻", "def": "NO₃⁻ = nitrate.  NO₂⁻ = nitrite (one fewer O)."}, {"id": "seed-chem-nomen-rules-21", "term": "Polyatomic ions: SO₄²⁻ vs SO₃²⁻", "def": "SO₄²⁻ = sulfate.  SO₃²⁻ = sulfite."}, {"id": "seed-chem-nomen-rules-22", "term": "Polyatomic ions: PO₄³⁻ vs PO₃³⁻", "def": "PO₄³⁻ = phosphate.  PO₃³⁻ = phosphite."}, {"id": "seed-chem-nomen-rules-23", "term": "Polyatomic ions: CO₃²⁻", "def": "carbonate (and HCO₃⁻ = hydrogen carbonate / bicarbonate)", "note": "There is no “carbonite” in the usual chart, which is the slide’s joke."}, {"id": "seed-chem-nomen-rules-24", "term": "Polyatomic ions: C₂H₃O₂⁻", "def": "acetate"}, {"id": "seed-chem-nomen-rules-25", "term": "Polyatomic ions: C₂O₄²⁻", "def": "oxalate"}, {"id": "seed-chem-nomen-rules-26", "term": "Polyatomic ions: CrO₄²⁻ vs Cr₂O₇²⁻", "def": "CrO₄²⁻ = chromate.  Cr₂O₇²⁻ = dichromate."}, {"id": "seed-chem-nomen-rules-27", "term": "Polyatomic ions: MnO₄⁻", "def": "permanganate"}, {"id": "seed-chem-nomen-rules-28", "term": "The chlorine oxyanion family (ClOₓ⁻)", "def": "ClO₄⁻ perchlorate, ClO₃⁻ chlorate, ClO₂⁻ chlorite, ClO⁻ hypochlorite.", "note": "Same pattern for Br and I: BrO₃⁻ bromate, IO₄⁻ periodate, IO⁻ hypoiodite, etc."}, {"id": "seed-chem-nomen-rules-29", "term": "-ate vs -ite", "def": "-ate has MORE oxygen; -ite has ONE FEWER oxygen, with the same charge. Nitrate NO₃⁻ → nitrite NO₂⁻."}, {"id": "seed-chem-nomen-rules-30", "term": "per- and hypo- prefixes", "def": "per-___-ate = one MORE O than -ate (ClO₄⁻). hypo-___-ite = one FEWER O than -ite (ClO⁻)."}, {"id": "seed-chem-nomen-rules-31", "term": "RULE: when do you use parentheses?", "def": "When you need MORE THAN ONE of a polyatomic ion. Put it in parentheses with the subscript outside.", "note": "Ca(NO₃)₂ = 2 nitrates. (NH₄)₂SO₃ = 2 ammoniums. BaSO₄ needs none because there’s only one sulfate."}, {"id": "seed-chem-nomen-rules-32", "term": "Why do transition metals need Roman numerals?", "def": "Many d-block metals can form more than one stable ion (Fe²⁺ or Fe³⁺), so the name must state the charge."}, {"id": "seed-chem-nomen-rules-33", "term": "What does the Roman numeral in “iron (III)” mean?", "def": "The CHARGE of the metal ion (3+). It does NOT mean the number of atoms.", "note": "Iron (III) oxide is Fe₂O₃: the III is the charge, the 2 is how many Fe."}, {"id": "seed-chem-nomen-rules-34", "term": "Name these ions: Cu²⁺, Fe³⁺, Sn⁴⁺", "def": "copper (II), iron (III), tin (IV)"}, {"id": "seed-chem-nomen-rules-35", "term": "Name these ions: Pb⁴⁺, Pb²⁺, Sn²⁺, Fe²⁺, Cu⁺", "def": "lead (IV), lead (II), tin (II), iron (II), copper (I)"}, {"id": "seed-chem-nomen-rules-36", "term": "Old naming system: -ic vs -ous", "def": "-ic = the HIGHER charge; -ous = the LOWER charge. Cu⁺ = cuprous, Cu²⁺ = cupric. You won’t have to use it, just recognize it."}, {"id": "seed-chem-nomen-rules-37", "term": "RULE: finding a transition metal’s charge from a formula", "def": "1) Anions have only one possible charge, so use them. 2) Add up the total negative charge. 3) Total positive must equal it. 4) Divide by the number of metal atoms.", "note": "PbO₂: 2 × (−2) = −4, so the one Pb is 4+ → lead (IV) oxide."}, {"id": "seed-chem-nomen-rules-38", "term": "Worked example: CuCl₂", "def": "2 Cl⁻ = −2 total, so Cu must be 2+ → copper (II) chloride."}, {"id": "seed-chem-nomen-rules-39", "term": "Worked example: Fe₂(SO₄)₃", "def": "3 SO₄²⁻ = −6 total, split over 2 Fe → each Fe is 3+ → iron (III) sulfate."}, {"id": "seed-chem-nomen-rules-40", "term": "Which transition metals usually DON’T need a Roman numeral?", "def": "Silver (Ag⁺) and zinc (Zn²⁺) only have one common charge.", "note": "The slides write “silver (I) chloride,” so check what your teacher accepts."}, {"id": "seed-chem-nomen-rules-41", "term": "What kind of elements form molecular compounds?", "def": "Nonmetal + nonmetal, sharing electrons in covalent bonds."}, {"id": "seed-chem-nomen-rules-42", "term": "Why do molecular names use prefixes?", "def": "The same two nonmetals can combine in many ratios (CO vs CO₂, NO vs NO₂), so the name must say how many of each atom."}, {"id": "seed-chem-nomen-rules-43", "term": "Molecular prefixes 1–10", "def": "1 mono, 2 di, 3 tri, 4 tetra, 5 penta, 6 hexa, 7 hepta, 8 octa, 9 nona, 10 deca"}, {"id": "seed-chem-nomen-rules-44", "term": "RULE: naming a molecular compound", "def": "1) First element: its name, plus a prefix only if there’s MORE than 1 (never “mono” first). 2) Second element: prefix (including mono-) + root + “-ide.”", "note": "CO = carbon monoxide (not monocarbon monoxide). P₂O₅ = diphosphorus pentoxide."}, {"id": "seed-chem-nomen-rules-45", "term": "RULE: dropping vowels in prefixes", "def": "If the element name starts with a vowel (usually “oxide”), drop the prefix’s last vowel: mono-oxide → monoxide, tetra-oxide → tetroxide, penta-oxide → pentoxide."}, {"id": "seed-chem-nomen-rules-46", "term": "Common names that break the rules", "def": "H₂O = water (not dihydrogen monoxide). NH₃ = ammonia (not nitrogen trihydride)."}, {"id": "seed-chem-nomen-rules-47", "term": "What do all acids do?", "def": "Release at least one H⁺ ion in water. HCl → H⁺ + Cl⁻."}, {"id": "seed-chem-nomen-rules-48", "term": "How many H⁺ does an acid need?", "def": "Equal to the size of the anion’s negative charge. SO₄²⁻ → H₂SO₄. PO₄³⁻ → H₃PO₄."}, {"id": "seed-chem-nomen-rules-49", "term": "RULE: anion ends in -ide → acid name?", "def": "hydro- + stem + -ic acid.  Cl⁻ chloride → HCl hydrochloric acid.", "note": "Applies to anions WITHOUT oxygen: halides, S²⁻ (hydrosulfuric), CN⁻ (hydrocyanic)."}, {"id": "seed-chem-nomen-rules-50", "term": "RULE: anion ends in -ate → acid name?", "def": "stem + -ic acid (no “hydro”).  NO₃⁻ nitrate → HNO₃ nitric acid.", "note": "Memory trick: “I ATE something ICky.”"}, {"id": "seed-chem-nomen-rules-51", "term": "RULE: anion ends in -ite → acid name?", "def": "stem + -ous acid.  NO₂⁻ nitrite → HNO₂ nitrous acid.", "note": "Memory trick: “I bITE when I’m nervOUS.”"}, {"id": "seed-chem-nomen-rules-52", "term": "per- and hypo- in acid names", "def": "They stay. ClO₄⁻ perchlorate → HClO₄ perchloric acid. ClO⁻ hypochlorite → HClO hypochlorous acid."}, {"id": "seed-chem-nomen-rules-53", "term": "Sulfur & phosphorus acid spelling quirks", "def": "Sulfate → sulfURic, sulfite → sulfURous (add “ur”). Phosphate → phosphORic, phosphite → phosphORous (add “or”)."}, {"id": "seed-chem-nomen-rules-54", "term": "What is an alkane?", "def": "The simplest hydrocarbon: only C and H, all single bonds (saturated). Formula CₙH₂ₙ₊₂. Name ends in “-ane.”"}, {"id": "seed-chem-nomen-rules-55", "term": "Alkane roots for 1–5 carbons", "def": "1 meth-, 2 eth-, 3 prop-, 4 but-, 5 pent-", "note": "Mnemonic: “Monkeys Eat Peeled Bananas.”"}, {"id": "seed-chem-nomen-rules-56", "term": "Alkane roots for 6–10 carbons", "def": "6 hex-, 7 hept-, 8 oct-, 9 non-, 10 dec-"}, {"id": "seed-chem-nomen-rules-57", "term": "How do you find H in an alkane with n carbons?", "def": "H = 2n + 2.  Octane (8 C) → 2(8) + 2 = 18 → C₈H₁₈."}]}, {"id": "seed-chem-nomen-practice", "rev": 1, "title": "Chem — Nomenclature: Name ↔ Formula Drill", "folder": "Chem", "description": "Every practice problem from the Nomenclature slides. Formula on the front means name it; name on the front means write the formula.", "cards": [{"id": "seed-chem-nomen-practice-0", "term": "NaF", "def": "sodium fluoride"}, {"id": "seed-chem-nomen-practice-1", "term": "CaO", "def": "calcium oxide"}, {"id": "seed-chem-nomen-practice-2", "term": "MgS", "def": "magnesium sulfide"}, {"id": "seed-chem-nomen-practice-3", "term": "AlN", "def": "aluminum nitride"}, {"id": "seed-chem-nomen-practice-4", "term": "K₂S", "def": "potassium sulfide"}, {"id": "seed-chem-nomen-practice-5", "term": "CaCl₂", "def": "calcium chloride"}, {"id": "seed-chem-nomen-practice-6", "term": "Ba₃N₂", "def": "barium nitride"}, {"id": "seed-chem-nomen-practice-7", "term": "sodium iodide", "def": "NaI"}, {"id": "seed-chem-nomen-practice-8", "term": "magnesium fluoride", "def": "MgF₂"}, {"id": "seed-chem-nomen-practice-9", "term": "aluminum phosphide", "def": "AlP"}, {"id": "seed-chem-nomen-practice-10", "term": "aluminum oxide", "def": "Al₂O₃"}, {"id": "seed-chem-nomen-practice-11", "term": "strontium iodide", "def": "SrI₂"}, {"id": "seed-chem-nomen-practice-12", "term": "NaNO₃", "def": "sodium nitrate"}, {"id": "seed-chem-nomen-practice-13", "term": "K₂SO₄", "def": "potassium sulfate"}, {"id": "seed-chem-nomen-practice-14", "term": "AlPO₄", "def": "aluminum phosphate"}, {"id": "seed-chem-nomen-practice-15", "term": "BaSO₄", "def": "barium sulfate"}, {"id": "seed-chem-nomen-practice-16", "term": "(NH₄)₂SO₃", "def": "ammonium sulfite"}, {"id": "seed-chem-nomen-practice-17", "term": "Ca(NO₃)₂", "def": "calcium nitrate"}, {"id": "seed-chem-nomen-practice-18", "term": "ammonium phosphate", "def": "(NH₄)₃PO₄"}, {"id": "seed-chem-nomen-practice-19", "term": "magnesium cyanide", "def": "Mg(CN)₂"}, {"id": "seed-chem-nomen-practice-20", "term": "strontium acetate", "def": "Sr(C₂H₃O₂)₂"}, {"id": "seed-chem-nomen-practice-21", "term": "Fe³⁺ + N³⁻", "def": "iron (III) nitride, FeN"}, {"id": "seed-chem-nomen-practice-22", "term": "Cu²⁺ + SO₄²⁻", "def": "copper (II) sulfate, CuSO₄"}, {"id": "seed-chem-nomen-practice-23", "term": "Sn²⁺ + F⁻", "def": "tin (II) fluoride, SnF₂"}, {"id": "seed-chem-nomen-practice-24", "term": "Pb⁴⁺ + O²⁻", "def": "lead (IV) oxide, PbO₂"}, {"id": "seed-chem-nomen-practice-25", "term": "Fe²⁺ + Cl⁻", "def": "iron (II) chloride, FeCl₂"}, {"id": "seed-chem-nomen-practice-26", "term": "SnCl₄", "def": "tin (IV) chloride"}, {"id": "seed-chem-nomen-practice-27", "term": "CuBr₂", "def": "copper (II) bromide"}, {"id": "seed-chem-nomen-practice-28", "term": "Cu(NO₃)₂", "def": "copper (II) nitrate"}, {"id": "seed-chem-nomen-practice-29", "term": "CuNO₃", "def": "copper (I) nitrate"}, {"id": "seed-chem-nomen-practice-30", "term": "CuS", "def": "copper (II) sulfide"}, {"id": "seed-chem-nomen-practice-31", "term": "PbO", "def": "lead (II) oxide"}, {"id": "seed-chem-nomen-practice-32", "term": "AgCl", "def": "silver chloride (slides: silver (I) chloride)"}, {"id": "seed-chem-nomen-practice-33", "term": "Pb₃N₂", "def": "lead (II) nitride"}, {"id": "seed-chem-nomen-practice-34", "term": "lead (IV) dichromate", "def": "Pb(Cr₂O₇)₂"}, {"id": "seed-chem-nomen-practice-35", "term": "chromium (III) phosphite", "def": "CrPO₃"}, {"id": "seed-chem-nomen-practice-36", "term": "NO₂", "def": "nitrogen dioxide"}, {"id": "seed-chem-nomen-practice-37", "term": "SCl₂", "def": "sulfur dichloride"}, {"id": "seed-chem-nomen-practice-38", "term": "PBr₃", "def": "phosphorus tribromide"}, {"id": "seed-chem-nomen-practice-39", "term": "CO₂", "def": "carbon dioxide"}, {"id": "seed-chem-nomen-practice-40", "term": "CCl₄", "def": "carbon tetrachloride"}, {"id": "seed-chem-nomen-practice-41", "term": "P₂O₅", "def": "diphosphorus pentoxide"}, {"id": "seed-chem-nomen-practice-42", "term": "SF₆", "def": "sulfur hexafluoride"}, {"id": "seed-chem-nomen-practice-43", "term": "CO", "def": "carbon monoxide"}, {"id": "seed-chem-nomen-practice-44", "term": "carbon tetrabromide", "def": "CBr₄"}, {"id": "seed-chem-nomen-practice-45", "term": "dinitrogen tetroxide", "def": "N₂O₄"}, {"id": "seed-chem-nomen-practice-46", "term": "trineptunium heptoxide", "def": "Np₃O₇"}, {"id": "seed-chem-nomen-practice-47", "term": "xenon hexafluoride", "def": "XeF₆"}, {"id": "seed-chem-nomen-practice-48", "term": "bromine pentafluoride", "def": "BrF₅"}, {"id": "seed-chem-nomen-practice-49", "term": "oxygen difluoride", "def": "OF₂"}, {"id": "seed-chem-nomen-practice-50", "term": "HBr", "def": "hydrobromic acid"}, {"id": "seed-chem-nomen-practice-51", "term": "HF", "def": "hydrofluoric acid"}, {"id": "seed-chem-nomen-practice-52", "term": "HCl", "def": "hydrochloric acid"}, {"id": "seed-chem-nomen-practice-53", "term": "HI", "def": "hydroiodic acid"}, {"id": "seed-chem-nomen-practice-54", "term": "H₂S", "def": "hydrosulfuric acid"}, {"id": "seed-chem-nomen-practice-55", "term": "HCN", "def": "hydrocyanic acid"}, {"id": "seed-chem-nomen-practice-56", "term": "HClO₄", "def": "perchloric acid"}, {"id": "seed-chem-nomen-practice-57", "term": "HNO₂", "def": "nitrous acid"}, {"id": "seed-chem-nomen-practice-58", "term": "H₂SO₄", "def": "sulfuric acid"}, {"id": "seed-chem-nomen-practice-59", "term": "H₂SO₃", "def": "sulfurous acid"}, {"id": "seed-chem-nomen-practice-60", "term": "H₃PO₄", "def": "phosphoric acid"}, {"id": "seed-chem-nomen-practice-61", "term": "H₃PO₃", "def": "phosphorous acid"}, {"id": "seed-chem-nomen-practice-62", "term": "HClO₃", "def": "chloric acid"}, {"id": "seed-chem-nomen-practice-63", "term": "HClO₂", "def": "chlorous acid"}, {"id": "seed-chem-nomen-practice-64", "term": "HClO", "def": "hypochlorous acid"}, {"id": "seed-chem-nomen-practice-65", "term": "nitric acid", "def": "HNO₃"}, {"id": "seed-chem-nomen-practice-66", "term": "oxalic acid", "def": "H₂C₂O₄"}, {"id": "seed-chem-nomen-practice-67", "term": "acetic acid", "def": "HC₂H₃O₂"}, {"id": "seed-chem-nomen-practice-68", "term": "bromic acid", "def": "HBrO₃"}, {"id": "seed-chem-nomen-practice-69", "term": "hypoiodous acid", "def": "HIO"}, {"id": "seed-chem-nomen-practice-70", "term": "periodic acid", "def": "HIO₄"}, {"id": "seed-chem-nomen-practice-71", "term": "CH₄", "def": "methane"}, {"id": "seed-chem-nomen-practice-72", "term": "C₂H₆", "def": "ethane"}, {"id": "seed-chem-nomen-practice-73", "term": "C₁₀H₂₂", "def": "decane"}, {"id": "seed-chem-nomen-practice-74", "term": "C₆H₁₄", "def": "hexane"}, {"id": "seed-chem-nomen-practice-75", "term": "butane", "def": "C₄H₁₀"}, {"id": "seed-chem-nomen-practice-76", "term": "octane", "def": "C₈H₁₈"}, {"id": "seed-chem-nomen-practice-77", "term": "propane", "def": "C₃H₈"}, {"id": "seed-chem-nomen-practice-78", "term": "heptane", "def": "C₇H₁₆"}]}, {"id": "seed-calc-u2-rules", "rev": 2, "title": "AP Calc Unit 2 — Rules & Formulas (2.1–2.8)", "folder": "AP Calc", "description": "Every rule from Lessons 2.1–2.8: limit definitions, tangent and normal lines, differentiability, power rule, trig, eˣ, ln x, aˣ, log rules, product rule, quotient rule, unit circle.", "cards": [{"id": "seed-calc-u2-rules-0", "term": "Average rate of change of f on [a, b]", "def": "(f(b) − f(a)) / (b − a)\nThe slope of the SECANT line through the two points.", "note": "Only uses f-values (never f′). Units: output units per input unit."}, {"id": "seed-calc-u2-rules-1", "term": "Instantaneous rate of change: Definition 1 (the \"h\" form)", "def": "f′(a) = lim h→0 [ f(a + h) − f(a) ] / h", "note": "Without the limit it is a secant slope. The limit squeezes the points together to get the tangent slope."}, {"id": "seed-calc-u2-rules-2", "term": "Instantaneous rate of change: Definition 2 (the \"x → a\" form)", "def": "f′(a) = lim x→a [ f(x) − f(a) ] / (x − a)", "note": "Same value as Definition 1. Watch for x − (−2) = x + 2 in the denominator."}, {"id": "seed-calc-u2-rules-3", "term": "Derivative FUNCTION (limit definition)", "def": "f′(x) = lim h→0 [ f(x + h) − f(x) ] / h\nIt gives the slope of f at ANY x-value.", "note": "Plug (x + h) into every x, subtract all of f(x), factor out h, cancel, then let h → 0."}, {"id": "seed-calc-u2-rules-4", "term": "What does f′(a) mean?", "def": "The slope of the curve (tangent line) at x = a = the instantaneous rate of change of f at x = a.", "note": "In context: \"At [input] = a, [output] is increasing/decreasing at a rate of |f′(a)| [units] per [unit].\""}, {"id": "seed-calc-u2-rules-5", "term": "Notation for the derivative", "def": "f′(x),  y′,  dy/dx,  df/dx,  d/dx (f(x))"}, {"id": "seed-calc-u2-rules-6", "term": "Tangent line equation at x = a", "def": "y − f(a) = f′(a)(x − a)\nPoint: (a, f(a)). Slope: f′(a).", "note": "You always need BOTH a point and a slope."}, {"id": "seed-calc-u2-rules-7", "term": "Normal line", "def": "Perpendicular to the tangent line at the same point.\nSlope = −1 / f′(a) (opposite reciprocal).", "note": "If f′(a) = 0, the normal line is vertical: x = a."}, {"id": "seed-calc-u2-rules-8", "term": "If y = mx + b is tangent to f at x = a, then…", "def": "f(a) = ma + b (shared point) and f′(a) = m (shared slope).", "note": "From 2.2 HW #3: tangent line y = 5x − 2 at x = 4 ⇒ f(4) = 18, f′(4) = 5."}, {"id": "seed-calc-u2-rules-9", "term": "Parallel vs. perpendicular lines", "def": "Parallel: equal slopes. Perpendicular: slopes are opposite reciprocals (multiply to −1).", "note": "\"Tangent parallel to y = 9x − 1\" ⇒ solve f′(x) = 9."}, {"id": "seed-calc-u2-rules-10", "term": "Horizontal tangent line", "def": "Slope 0 ⇒ solve f′(x) = 0.", "note": "Example: f′(x) = 3(x + 5)(x − 1) = 0 ⇒ x = −5, 1."}, {"id": "seed-calc-u2-rules-11", "term": "Reading a graph of f′", "def": "The y-values of an f′ graph are SLOPES of f.\nf′ > 0 ⇒ f increasing. f′ < 0 ⇒ f decreasing. f′ = 0 ⇒ horizontal tangent on f.", "note": "A point (1, 2) on f′ means f has slope 2 at x = 1. It does NOT mean f(1) = 2."}, {"id": "seed-calc-u2-rules-12", "term": "Graphing f′ from a piecewise linear f", "def": "Each line segment of f becomes a horizontal segment on f′ at height = its slope. Corners of f become open circles (f′ does not exist)."}, {"id": "seed-calc-u2-rules-13", "term": "Differentiability ⇒ ?", "def": "Differentiable ⇒ continuous.\nContinuous does NOT ⇒ differentiable.", "note": "So if f is not continuous at a, it is automatically not differentiable at a."}, {"id": "seed-calc-u2-rules-14", "term": "4 ways a function fails to be differentiable at x = a", "def": "1. Corner (slopes differ on each side)\n2. Cusp (sharp point)\n3. Vertical tangent (infinite slope)\n4. Discontinuity (hole, jump, asymptote)", "note": "A horizontal tangent (slope 0) IS differentiable."}, {"id": "seed-calc-u2-rules-15", "term": "Piecewise function: test for differentiability at the break x = a", "def": "1. Continuity: left piece at a = right piece at a = f(a).\n2. Slopes: derivative of left piece at a = derivative of right piece at a.\nBoth ⇒ differentiable.", "note": "Always check continuity first. Matching slopes with a jump is still NOT differentiable."}, {"id": "seed-calc-u2-rules-16", "term": "If f is differentiable at a, which of these are NOT guaranteed?", "def": "lim x→a⁻ f′(x) = lim x→a⁺ f′(x) is NOT guaranteed (f′ can misbehave near a).\nGuaranteed: f is continuous at a, and f′(a) is the tangent slope.", "note": "From 2.3 HW #10."}, {"id": "seed-calc-u2-rules-17", "term": "Derivative of a constant", "def": "d/dx (c) = 0", "note": "A horizontal line has slope 0."}, {"id": "seed-calc-u2-rules-18", "term": "Constant multiple rule", "def": "d/dx [ c·f(x) ] = c·f′(x)", "note": "A vertical stretch by c multiplies every slope by c."}, {"id": "seed-calc-u2-rules-19", "term": "Sum / difference rule", "def": "d/dx [ f(x) ± g(x) ] = f′(x) ± g′(x)"}, {"id": "seed-calc-u2-rules-20", "term": "Power rule", "def": "d/dx (xⁿ) = n·xⁿ⁻¹  (for n ≠ 0)", "note": "Bring the exponent down, then subtract 1 from it."}, {"id": "seed-calc-u2-rules-21", "term": "Rewrite BEFORE using the power rule", "def": "√x = x^(1/2)\n∛x = x^(1/3)\n1/x = x^(−1)\n6/x² = 6x^(−2)\nx^(2/3) = ∛(x²)", "note": "Example: d/dx (6/x) = −6/x².  d/dx (4√x) = 2/√x."}, {"id": "seed-calc-u2-rules-22", "term": "Transformations and derivatives", "def": "y = f(x) + c ⇒ y′ = f′(x) (shifts up/down do NOT change slopes)\ny = k·f(x) ⇒ y′ = k·f′(x)\ny = f(x + c) ⇒ y′ = f′(x + c)", "note": "g(x) = 3f(x + 2) − 5 ⇒ g′(2) = 3f′(4)."}, {"id": "seed-calc-u2-rules-23", "term": "Position, velocity, average velocity", "def": "Velocity v(t) = s′(t).\nAverage velocity on [a, b] = (s(b) − s(a)) / (b − a)."}, {"id": "seed-calc-u2-rules-24", "term": "d/dx (sin x)", "def": "cos x"}, {"id": "seed-calc-u2-rules-25", "term": "d/dx (cos x)", "def": "−sin x", "note": "The minus sign goes with the derivative of COSINE."}, {"id": "seed-calc-u2-rules-26", "term": "Unit circle values to memorize", "def": "π/6: sin ½, cos √3/2\nπ/4: sin √2/2, cos √2/2\nπ/3: sin √3/2, cos ½\nπ/2: sin 1, cos 0\nπ: sin 0, cos −1\n3π/2: sin −1, cos 0\n2π: sin 0, cos 1", "note": "ASTC: All positive in QI, Sine in QII, Tangent in QIII, Cosine in QIV."}, {"id": "seed-calc-u2-rules-27", "term": "Where is sin x = ½? cos x = ½? on [0, 2π]", "def": "sin x = ½ at π/6 and 5π/6.\ncos x = ½ at π/3 and 5π/3.", "note": "sin x = −½ at 7π/6, 11π/6. cos x = −½ at 2π/3, 4π/3."}, {"id": "seed-calc-u2-rules-28", "term": "d/dx (eˣ)", "def": "eˣ", "note": "eˣ > 0 always, so y = eˣ has no horizontal tangents."}, {"id": "seed-calc-u2-rules-29", "term": "d/dx (ln x)", "def": "1/x", "note": "ln x is always increasing but gets flatter as x grows."}, {"id": "seed-calc-u2-rules-30", "term": "d/dx (aˣ)  (like 4ˣ or 2ˣ)", "def": "aˣ · ln a", "note": "NOT x·aˣ⁻¹. The power rule is only for x to a constant power."}, {"id": "seed-calc-u2-rules-31", "term": "Log and exponential rules", "def": "e^(ln x) = x\nln(eˣ) = x\nln e = 1, ln 1 = 0\nln a + ln b = ln(ab)\nln a − ln b = ln(a/b)\nln(aⁿ) = n ln a", "note": "e^(ln 4 + ln 2) = e^(ln 8) = 8.  4 ln e² = 8."}, {"id": "seed-calc-u2-rules-32", "term": "Product rule", "def": "d/dx [ f(x)·g(x) ] = f′(x)g(x) + f(x)g′(x)", "note": "\"Derivative of the first times the second, plus the first times the derivative of the second.\""}, {"id": "seed-calc-u2-rules-33", "term": "Is (f·g)′ = f′·g′?", "def": "NO. The derivative of a product is not the product of the derivatives. Use the product rule.", "note": "f = 3x⁴, g = −x²: (fg)′ = −18x⁵, but f′g′ = −24x⁴."}, {"id": "seed-calc-u2-rules-34", "term": "Quotient rule (2.8)", "def": "d/dx [ f(x) / g(x) ] = [ f′(x)g(x) − f(x)g′(x) ] / [ g(x) ]²", "note": "\"Low d-high minus high d-low, over the square of what's below.\" The MINUS makes order matter: start with the derivative of the TOP."}, {"id": "seed-calc-u2-rules-35", "term": "Is (f/g)′ = f′/g′?", "def": "NO. Use the quotient rule. Also: the denominator gets SQUARED, and you never take its derivative.", "note": "f = x², g = x: (f/g)′ = (2x·x − x²·1)/x² = 1, but f′/g′ = 2x."}, {"id": "seed-calc-u2-rules-36", "term": "When can you skip the quotient rule?", "def": "When the bottom is a single term like x² or 4x³: split the fraction and use the power rule.\n(4x³ − 2x + 1)/x² = 4x − 2x⁻¹ + x⁻²", "note": "If the bottom is a constant, just pull it out: (x² + 1)/5 = (1/5)(x² + 1)."}, {"id": "seed-calc-u2-rules-37", "term": "Even function facts (for product rule sign questions)", "def": "f(−x) = f(x): the graph is mirrored across the y-axis.\nIf f is increasing for x > 0, it is decreasing for x < 0.\nf′(−a) = −f′(a)."}, {"id": "seed-calc-u2-rules-38", "term": "\"Derivative in disguise\" limits", "def": "lim h→0 [f(a + h) − f(a)]/h or lim x→a [f(x) − f(a)]/(x − a) is just f′(a).\nFind f and a, differentiate, plug in.", "note": "lim h→0 [ln(3 + h) − ln 3]/h = 1/3."}]}, {"id": "seed-calc-u2-methods", "rev": 2, "title": "AP Calc Unit 2 — How To Do Each Problem Type", "folder": "AP Calc", "description": "One card per homework problem type: the steps to follow, plus the trap to avoid and the homework problem it came from.", "cards": [{"id": "seed-calc-u2-methods-0", "term": "HOW TO: Find f(x + h) and f(x + h) − f(x)", "def": "1. Replace EVERY x with (x + h), keeping parentheses.\n2. Expand: (x + h)² = x² + 2xh + h².\n3. Subtract the WHOLE f(x) in parentheses.\n4. Everything without an h should cancel.", "note": "Example: f(x) = −x² + 7x ⇒ f(x + h) − f(x) = −2xh − h² + 7h."}, {"id": "seed-calc-u2-methods-1", "term": "HOW TO: Evaluate lim h→0 [f(a + h) − f(a)]/h with algebra", "def": "1. Compute f(a) as a number.\n2. Plug a + h into f and expand.\n3. Subtract f(a); every term left has an h.\n4. Factor out h and cancel it with the denominator.\n5. Plug in h = 0.", "note": "f(x) = 3x² − 8 at a = 3: (18h + 3h²)/h = 18 + 3h → 18."}, {"id": "seed-calc-u2-methods-2", "term": "HOW TO: Use Definition 2 with a fraction (like C(t) = 20/(5 + t))", "def": "1. Write [C(t) − C(2)]/(t − 2).\n2. Combine the top into ONE fraction with a common denominator.\n3. Factor the top to show (t − 2) (often −(t − 2)).\n4. Cancel and plug in t = 2.", "note": "2.1 HW #8b: answer −20/49 mg/L per hour."}, {"id": "seed-calc-u2-methods-3", "term": "HOW TO: Spot an error in someone's limit-definition work", "def": "Check: (1) every x became (a + h) with parentheses; (2) constants were distributed; (3) f(a) was subtracted as a group; (4) the denominator is h.", "note": "Lina forgot to write 4(3 + h) and to group (12 − 9)."}, {"id": "seed-calc-u2-methods-4", "term": "HOW TO: \"Which expressions give the instantaneous rate of change at x = a?\"", "def": "Correct forms only:\n• lim h→0 [f(a + h) − f(a)] / h\n• lim x→a [f(x) − f(a)] / (x − a)\nReject: h → a, x → ∞, missing parentheses, wrong denominator, or f(a) not subtracted.", "note": "Plug the real f(a) in and check signs."}, {"id": "seed-calc-u2-methods-5", "term": "HOW TO: Recognize f and a in a disguised limit (like tan(π/4 + h) − 1)", "def": "1. Whatever is added to h (or what x approaches) is a.\n2. The function wrapped around it is f.\n3. Check: the number subtracted must equal f(a).\n4. Answer = f′(a).", "note": "tan(π/4) = 1, so f = tan x and c = π/4."}, {"id": "seed-calc-u2-methods-6", "term": "HOW TO: Secant slopes from a graph (h = 4, 2, 0.5…)", "def": "1. Find the two points: x = a and x = a + h.\n2. Read the y-values from the graph (or the formula).\n3. Slope = Δy/Δx.\n4. The smallest h gives the best estimate of f′(a)."}, {"id": "seed-calc-u2-methods-7", "term": "HOW TO: Write a tangent line equation", "def": "1. Point: (a, f(a)).\n2. Slope: find f′(x), then plug in a.\n3. y − f(a) = f′(a)(x − a).", "note": "For a normal line, use −1/f′(a) as the slope."}, {"id": "seed-calc-u2-methods-8", "term": "HOW TO: Find f′(a) when you are given the tangent line or two points on it", "def": "f′(a) is the slope of the tangent line. Read the slope from y = mx + b, or use (y₂ − y₁)/(x₂ − x₁) for two points on the line.", "note": "If L(2) = 6 and the tangent point is (−4, 3): slope = 3/6 = 1/2."}, {"id": "seed-calc-u2-methods-9", "term": "HOW TO: Two tangent lines with an unknown b that intersect at x = c", "def": "1. Set the two line equations equal at x = c.\n2. Solve for b.\n3. The slope of each line is f′ at its tangent point.", "note": "2.2 HW #8: b = 2 ⇒ f′(−1) = 2, f′(0) = 4."}, {"id": "seed-calc-u2-methods-10", "term": "HOW TO: Read values from a graph of f with its tangent line drawn", "def": "f(a): the height of the curve at x = a.\nf′(a): the slope of the tangent line (pick 2 grid points on it).\nf(other x): read the curve, not the line."}, {"id": "seed-calc-u2-methods-11", "term": "HOW TO: Compare f′ values from a graph of f (rank f′(−1), f′(0), f′(2))", "def": "1. At each x, decide: rising (+), falling (−), or flat (0).\n2. Among the negatives, the STEEPER one is smaller.\n3. Order from most negative to most positive."}, {"id": "seed-calc-u2-methods-12", "term": "HOW TO: Decide whether a piecewise function is differentiable at the break", "def": "1. Plug a into both pieces: are the values equal? If not, STOP: not differentiable.\n2. Differentiate both pieces and plug in a: are the slopes equal?\n3. Both yes ⇒ differentiable. Write the justification with both limits.", "note": "2.3 HW #3: h(x) = 7 ⇒ corner (slopes 0 and 3)."}, {"id": "seed-calc-u2-methods-13", "term": "HOW TO: Find constants a and b so a piecewise function is differentiable", "def": "1. Continuity equation: left piece(c) = right piece(c).\n2. Slope equation: left′(c) = right′(c).\n3. Solve the two equations together.", "note": "2.6 HW #4: b = 5 (continuity), then 5 − a = 3 ⇒ a = 2."}, {"id": "seed-calc-u2-methods-14", "term": "HOW TO: Find where f is NOT differentiable from a graph of f", "def": "Look for: corners, cusps, vertical tangents, jumps, holes, asymptotes.\nNOT on the list: smooth peaks/valleys (horizontal tangents).", "note": "2.3 HW #5: x = 2 (vertical tangent), 3 (corner), 5 (jump), 6 (hole)."}, {"id": "seed-calc-u2-methods-15", "term": "HOW TO: Find where f is NOT differentiable from a graph of f′", "def": "f is not differentiable where f′ does NOT EXIST: holes and vertical asymptotes on the f′ graph.\nA sharp point on the f′ graph is fine for f (f′ still has a value there).", "note": "2.3 HW #8: x = −2 (asymptote) and x = 1 (hole). Not x = 2."}, {"id": "seed-calc-u2-methods-16", "term": "HOW TO: Differentiate with radicals and fractions (power rule)", "def": "1. Rewrite: √x = x^(1/2), 6/x = 6x^(−1), 7/x² = 7x^(−2).\n2. Power rule on each term.\n3. Rewrite negative/fraction exponents back if asked.", "note": "7/x² + 11x⁴ ⇒ −14/x³ + 44x³."}, {"id": "seed-calc-u2-methods-17", "term": "HOW TO: Derivative using a graph of g (f = 4x³ + 2x + 6g(x))", "def": "1. f(3): plug in, reading g(3) from the graph.\n2. f′(x) = 12x² + 2 + 6g′(x).\n3. g′(3) = slope of the g graph at x = 3.\n4. Tangent line: y − f(3) = f′(3)(x − 3).", "note": "2.4 HW #3: y − 90 = 106(x − 3)."}, {"id": "seed-calc-u2-methods-18", "term": "HOW TO: Average velocity vs. instantaneous velocity", "def": "1. Average: (s(b) − s(a))/(b − a).\n2. Instantaneous: v(t) = s′(t).\n3. \"When are they equal?\" Set s′(t) = average and solve. Keep t inside the interval.", "note": "2.4 HW #4: 12√t − 4 = 20 ⇒ t = 4."}, {"id": "seed-calc-u2-methods-19", "term": "HOW TO: Two curves tangent to each other at a point", "def": "Tangent at (p, q) means BOTH:\n1. f(p) = q and g(p) = q (same point)\n2. f′(p) = g′(p) (same slope)\nSolve the equations one unknown at a time.", "note": "2.4 HW #6: a = 2, b = 0.5, c = 6."}, {"id": "seed-calc-u2-methods-20", "term": "HOW TO: Transformation of f from a table (g = 3f(x + 2) − 5)", "def": "1. g′(x) = 3f′(x + 2) (ignore the −5).\n2. To get g′(2), look up f′(4) in the table.\n3. Multiply by the stretch factor.", "note": "2.4 HW #7: g′(2) = 3·9 = 27."}, {"id": "seed-calc-u2-methods-21", "term": "HOW TO: Trig derivative with a \"horizontal tangent on [0, 2π]\" question", "def": "1. Find f′(x).\n2. Set f′(x) = 0 and isolate sin x or cos x.\n3. Use the unit circle to find EVERY angle in the interval.", "note": "2.5 HW #4c: cos x = ½ ⇒ π/3, 5π/3."}, {"id": "seed-calc-u2-methods-22", "term": "HOW TO: Parallel tangent lines of two trig functions", "def": "1. Set g′(x) = h′(x).\n2. Divide to get tan x = number.\n3. Find the angle(s) in the given interval.", "note": "2.5 HW #6b: tan x = −√3 ⇒ 2π/3 on [0, π]."}, {"id": "seed-calc-u2-methods-23", "term": "HOW TO: \"How many times steeper\" (ratio of slopes)", "def": "1. Find f′ at each point.\n2. Compare absolute values: |f′(B)| / |f′(A)|.", "note": "2.5 HW #9: slope at B is 2 times the slope at A."}, {"id": "seed-calc-u2-methods-24", "term": "HOW TO: A line through the origin (or a given point) tangent to a curve", "def": "1. Call the tangent point (x, f(x)).\n2. Slope #1 = f′(x).\n3. Slope #2 = (f(x) − 0)/(x − 0) (or use the given point).\n4. Set equal and solve for x, then find the slope.", "note": "2.6 HW #6: y = 8 ln x ⇒ x = e, m = 8/e. 2.5 HW #8 uses the same idea with (0, −3)."}, {"id": "seed-calc-u2-methods-25", "term": "HOW TO: Find the point where the tangent line has a given slope (or is a given line)", "def": "1. Solve the line for y to get its slope m.\n2. Solve f′(x) = m.\n3. Find the y-value with f(x).\n4. If k is unknown, plug the point into the line to find k.", "note": "2.6 HW #8: eˣ/2 − 1 = ½ ⇒ x = ln 3."}, {"id": "seed-calc-u2-methods-26", "term": "HOW TO: Product rule from a table", "def": "1. Write h′ = f′g + fg′.\n2. Look up all FOUR values at that x.\n3. Plug in and simplify.", "note": "2.7 HW #1: h′(2) = 3(2) + (−4)(−1) = 10."}, {"id": "seed-calc-u2-methods-27", "term": "HOW TO: Product rule with a graph (j(x) = g(x)/√x)", "def": "1. Rewrite as a product: g(x)·x^(−1/2).\n2. j′ = g′(x)x^(−1/2) + g(x)(−½)x^(−3/2).\n3. Read g(1) and g′(1) (slope) from the graph.", "note": "2.7 HW #3: j′(1) = ½."}, {"id": "seed-calc-u2-methods-28", "term": "HOW TO: Quotient rule from a table (h = f/g)", "def": "1. Write h′ = (f′g − fg′)/g².\n2. Look up f, f′, g, g′ at that x.\n3. Top first: f′·g, THEN subtract f·g′.\n4. Square g for the bottom.", "note": "f(2) = 5, f′(2) = 7, g(2) = 3, g′(2) = 1: h′(2) = (21 − 5)/9 = 16/9."}, {"id": "seed-calc-u2-methods-29", "term": "HOW TO: Tangent line to a quotient like y = 2x/(x − 1)", "def": "1. Point: plug x into y.\n2. Slope: quotient rule, then plug in x.\n3. y − y₁ = m(x − x₁).", "note": "At (−1, 1): y′ = −2/(x − 1)² = −1/2, so y − 1 = −½(x + 1)."}, {"id": "seed-calc-u2-methods-30", "term": "HOW TO: Horizontal tangent with a quotient like ln x / x", "def": "1. Quotient rule: (1 − ln x)/x².\n2. A fraction is 0 only when its TOP is 0.\n3. Solve top = 0 (and make sure the bottom isn't 0 there).", "note": "1 − ln x = 0 ⇒ x = e."}, {"id": "seed-calc-u2-methods-31", "term": "HOW TO: Horizontal tangent with a product like (4 − 3x)eˣ", "def": "1. Product rule.\n2. Factor out eˣ.\n3. eˣ is never 0, so set the other factor = 0.", "note": "2.7 HW #6: x = 1/3."}, {"id": "seed-calc-u2-methods-32", "term": "HOW TO: Sign of h′ = (fg)′ without numbers (even/odd, increasing)", "def": "1. Write h′(a) = f′(a)g(a) + f(a)g′(a).\n2. Decide the sign of each of the 4 values from the facts and the graph.\n3. Combine signs: (−)(−) = +, (+)(+) = +.", "note": "2.7 HW #8: h′(−1) > 0."}]}, {"id": "seed-mcq-calc-u2-mock1", "rev": 2, "kind": "mcq", "title": "AP Calc Unit 2 — Mock Test 1 (MCQ + FRQ)", "folder": "AP Calc", "description": "Half multiple choice, half free response (12 points each), like the AP exam. Lessons 2.1–2.8 only, including the quotient rule. Focus: limit definition, tables, differentiability of a piecewise function (2003 AP #6). Every question comes from the College Board (released AP exams, the Course and Exam Description, the 2008 Practice Exam) or OpenStax Calculus, and its source is shown under the question. For free response, write your work, reveal the solution, and score yourself with the rubric.", "cards": [], "questions": [{"id": "seed-mcq-calc-u2-mock1-m0", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6 · multiple choice</small><br><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">e<sup>(2 + h)</sup> − e²</span><span style=\"padding:0 3px\">h</span></span> =", "img": null, "choices": ["0", "1", "2e", "e²", "2e²"], "answer": 3, "why": "This is the limit definition of the derivative of f(x) = eˣ at a = 2: [f(2 + h) − f(2)]/h. Since (eˣ)′ = eˣ, the limit equals f′(2) = e². Plugging in h = 0 only gives 0/0, so recognize the pattern instead.", "source": "College Board, 2008 AP Calculus AB Practice Exam, Section I Part A (no calculator), question 14."}, {"id": "seed-mcq-calc-u2-mock1-m1", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · multiple choice</small><br>The limit <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">[3(2 + h)² + 2] − 14</span><span style=\"padding:0 3px\">h</span></span> represents f′(a) for some function f and number a. Which is correct?", "img": null, "choices": ["f(x) = 3x² + 2, a = 2, and the limit equals 14", "f(x) = 3x² + 2, a = 14, and the limit equals 12", "f(x) = 3x² + 2, a = 2, and the limit equals 12", "f(x) = 3x², a = 2, and the limit equals 6"], "answer": 2, "why": "Match [f(a + h) − f(a)]/h. The piece with (2 + h) is f(a + h), so f(x) = 3x² + 2 and a = 2. Check: f(2) = 3·4 + 2 = 14, the number being subtracted. Then f′(x) = 6x, so f′(2) = 12. (14 is f(2), not the slope.)", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.2, Exercise 69. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock1-m2", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · multiple choice</small><br>f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:3.2em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.6\"><span>2/x</span><span>for x < −1</span><span>x² − 3</span><span>for −1 ≤ x ≤ 2</span><span>4x − 3</span><span>for x > 2</span></span></span><br>Let f be the function defined above. At what values of x, if any, is f not differentiable?", "img": null, "choices": ["x = −1 only", "x = 2 only", "x = −1 and x = −2", "f is differentiable for all values of x."], "answer": 1, "why": "Check each break point for continuity AND matching slopes. At x = −1: 2/(−1) = −2 and (−1)² − 3 = −2, so f is continuous; slopes (2/x)′ = −2/x² = −2 and (x² − 3)′ = 2x = −2 match, so f IS differentiable there. At x = 2: x² − 3 = 1 but 4x − 3 = 5, so f jumps. Not continuous means not differentiable. Answer: x = 2 only. (Choice C is printed this way in the College Board original.)", "source": "College Board, AP Calculus AB and BC Course and Exam Description (2019), sample multiple-choice question 2."}, {"id": "seed-mcq-calc-u2-mock1-m3", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · multiple choice</small><br>Let f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>1</span><span>x < 1</span><span>x</span><span>x ≥ 1</span></span></span>. Using the limit definition at x = 1, why does f′(1) not exist?", "img": null, "choices": ["f is not continuous at x = 1", "f(1) is undefined", "The difference quotient → ∞, so the tangent line is vertical", "The left-hand difference quotient → 0 but the right-hand one → 1, so the one-sided limits disagree"], "answer": 3, "why": "f(1) = 1. From the left, f(1 + h) = 1, so [f(1 + h) − f(1)]/h = 0/h = 0. From the right, f(1 + h) = 1 + h, so the quotient is h/h = 1. The one-sided limits (0 and 1) are different, so there is a corner and f′(1) does not exist. f IS continuous at 1 (both sides approach 1), so B is the trap.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.1, Exercise 43. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock1-m4", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · multiple choice</small><br>Which is an equation of the line tangent to the graph of f(x) = 2x³ + 4x² − 5x − 3 at x = −1?", "img": null, "choices": ["y − 4 = −7(x − 1)", "y − 4 = 9(x + 1)", "y − 4 = −7(x + 1)", "y + 4 = −7(x − 1)"], "answer": 2, "why": "Point: f(−1) = −2 + 4 + 5 − 3 = 4, so (−1, 4). Slope: f′(x) = 6x² + 8x − 5, so f′(−1) = 6 − 8 − 5 = −7. Point-slope: y − 4 = −7(x − (−1)) = −7(x + 1). (Slope 9 comes from plugging in x = +1.)", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 137. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock1-m5", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7 · multiple choice</small><br>If f(x) = (x + 2)(2x² − 3), then f′(x) =", "img": null, "choices": ["6x² + 8x + 3", "4x", "6x² + 8x − 3", "4x(x + 2)"], "answer": 2, "why": "Product rule: (1)(2x² − 3) + (x + 2)(4x) = 2x² − 3 + 4x² + 8x = 6x² + 8x − 3. \"4x\" is (x + 2)′·(2x² − 3)′ = 1·4x, the classic mistake of multiplying the derivatives.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 112. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock1-m6", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5 · multiple choice</small><br>If y = x − x³ sin x, then dy/dx =", "img": null, "choices": ["1 − 3x² sin x + x³ cos x", "1 − 3x² sin x − x³ cos x", "−3x² sin x − x³ cos x", "1 − 3x² cos x"], "answer": 1, "why": "d/dx(x) = 1. For x³ sin x use the product rule: 3x² sin x + x³ cos x. The minus sign in front hits BOTH terms: 1 − 3x² sin x − x³ cos x.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.5, Exercise 178. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock1-m7", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6 · multiple choice</small><br>If f(x) = x²eˣ, then f′(x) =", "img": null, "choices": ["xeˣ(x + 2)", "2xeˣ", "x²eˣ", "eˣ(x² + 2)"], "answer": 0, "why": "Product rule: (x²)′eˣ + x²(eˣ)′ = 2xeˣ + x²eˣ. Factor out xeˣ: xeˣ(2 + x). 2xeˣ is the product of the derivatives, which is not the derivative of the product.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.9, Exercise 331. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock1-m8", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7 · multiple choice</small><br>f and g are differentiable functions with the values in the table.<table style=\"border-collapse:collapse;margin:8px 0\"><tr><th style=\"border:1px solid currentColor;padding:3px 10px\">x</th><th style=\"border:1px solid currentColor;padding:3px 10px\">1</th><th style=\"border:1px solid currentColor;padding:3px 10px\">2</th><th style=\"border:1px solid currentColor;padding:3px 10px\">3</th><th style=\"border:1px solid currentColor;padding:3px 10px\">4</th></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">f(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">5</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">0</td></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">g(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−4</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">6</td></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">f′(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−1</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">7</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">8</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−3</td></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">g′(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">4</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">1</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">9</td></tr></table>If h(x) = x·f(x) + 4g(x), find h′(1).", "img": null, "choices": ["19", "10", "15", "18"], "answer": 3, "why": "h′(x) = [1·f(x) + x·f′(x)] + 4g′(x). At x = 1: f(1) + 1·f′(1) + 4g′(1) = 3 + (−1) + 4(4) = 18. 15 forgets the f(1) term (x·f(x) needs the product rule), and 10 uses g(1) instead of g′(1).", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 126. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock1-m9", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8 · multiple choice</small><br>f and g are differentiable functions with the values in the table.<table style=\"border-collapse:collapse;margin:8px 0\"><tr><th style=\"border:1px solid currentColor;padding:3px 10px\">x</th><th style=\"border:1px solid currentColor;padding:3px 10px\">1</th><th style=\"border:1px solid currentColor;padding:3px 10px\">2</th><th style=\"border:1px solid currentColor;padding:3px 10px\">3</th><th style=\"border:1px solid currentColor;padding:3px 10px\">4</th></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">f(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">5</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">0</td></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">g(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−4</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">6</td></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">f′(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−1</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">7</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">8</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−3</td></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">g′(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">4</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">1</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">9</td></tr></table>If h(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(x)</span><span style=\"padding:0 3px\">g(x)</span></span>, find h′(2).", "img": null, "choices": ["7", "16/9", "−16/9", "26/9"], "answer": 1, "why": "Quotient rule: h′ = (f′g − fg′)/g². At x = 2: (7·3 − 5·1)/3² = (21 − 5)/9 = 16/9. 26/9 uses + instead of −, −16/9 subtracts in the wrong order, and 7 is f′/g′.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 127. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock1-m10", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8 · multiple choice</small><br>If f(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">4x³ − 2x + 1</span><span style=\"padding:0 3px\">x²</span></span>, then f′(x) =", "img": null, "choices": ["4 + 2/x² − 2/x³", "4 + 2/x² + 2/x³", "4 − 2/x² + 2/x³", "(12x² − 2)/(2x)"], "answer": 0, "why": "Fastest: split the fraction first. f(x) = 4x − 2x⁻¹ + x⁻², so f′(x) = 4 + 2x⁻² − 2x⁻³ = 4 + 2/x² − 2/x³. (The quotient rule gives the same answer.) (12x² − 2)/(2x) is top′/bottom′, which is never the rule.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 115. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock1-m11", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5 · multiple choice</small><br>A particle moves along a line so that its position at time t is s(t) = 3t + 2 cos t for 0 ≤ t ≤ 2π. At what times is the particle at rest (velocity 0)?", "img": null, "choices": ["t = π/6 and t = 5π/6", "Never: the velocity is never 0", "t = π/2 and t = 3π/2", "t = 0 and t = π"], "answer": 1, "why": "Velocity is the derivative: v(t) = s′(t) = 3 − 2 sin t. Setting 3 − 2 sin t = 0 needs sin t = 3/2, but sin t is never bigger than 1. So the particle is never at rest.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.5, Checkpoint 3.27. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock1-f0", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · free response</small><br>Two short parts taken word for word from recent AP Calculus AB exams. Use the tables, and give units.", "parts": [{"label": "(a)", "q": "Male birds of a certain species arrive at a nesting area over a thirty-day period. The rate at which the male birds arrive at time t days is modeled by a differentiable function M, where M(t) is measured in number of birds per day.<table style=\"border-collapse:collapse;margin:8px 0\"><tr><th style=\"border:1px solid currentColor;padding:3px 10px\">t (days)</th><th style=\"border:1px solid currentColor;padding:3px 10px\">0</th><th style=\"border:1px solid currentColor;padding:3px 10px\">5</th><th style=\"border:1px solid currentColor;padding:3px 10px\">10</th><th style=\"border:1px solid currentColor;padding:3px 10px\">15</th><th style=\"border:1px solid currentColor;padding:3px 10px\">20</th><th style=\"border:1px solid currentColor;padding:3px 10px\">25</th><th style=\"border:1px solid currentColor;padding:3px 10px\">30</th></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">M(t) (birds per day)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">7</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">16</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">6</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">5</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">0</td></tr></table>Approximate M′(7.5) using the average rate of change of M over the interval 5 ≤ t ≤ 10. Show the work that leads to your answer, and indicate units of measure.", "sol": "M′(7.5) ≈ <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">M(10) − M(5)</span><span style=\"padding:0 3px\">10 − 5</span></span> = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">16 − 7</span><span style=\"padding:0 3px\">5</span></span> = 9/5 = <b>1.8 birds per day per day</b>.<br><b>Official scoring (2 pts):</b> 1 pt for the answer with a difference AND a quotient from the table; 1 pt for the units \"birds per day per day\". Trap: you are not given M(7.5). Use the two table values around 7.5.", "pts": 2}, {"label": "(b)", "q": "The temperature of coffee in a cup at time t minutes is modeled by a decreasing differentiable function C, where C(t) is measured in degrees Celsius.<table style=\"border-collapse:collapse;margin:8px 0\"><tr><th style=\"border:1px solid currentColor;padding:3px 10px\">t (minutes)</th><th style=\"border:1px solid currentColor;padding:3px 10px\">0</th><th style=\"border:1px solid currentColor;padding:3px 10px\">3</th><th style=\"border:1px solid currentColor;padding:3px 10px\">7</th><th style=\"border:1px solid currentColor;padding:3px 10px\">12</th></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">C(t) (°C)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">100</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">85</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">69</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">55</td></tr></table>Approximate C′(5) using the average rate of change of C over the interval 3 ≤ t ≤ 7. Show the work that leads to your answer and include units of measure.", "sol": "C′(5) ≈ <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">C(7) − C(3)</span><span style=\"padding:0 3px\">7 − 3</span></span> = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">69 − 85</span><span style=\"padding:0 3px\">4</span></span> = <b>−4 degrees Celsius per minute</b>.<br><b>Scoring (2 pts):</b> 1 pt for the setup and answer, 1 pt for units. Negative makes sense because the coffee is cooling.", "pts": 2}], "source": "College Board, 2026 AP Calculus AB free-response question 1(a) and College Board, 2024 AP Calculus AB free-response question 1(a). Answers from the official scoring guideline and 2024 Chief Reader Report. Their other parts need integrals, so they are left out."}, {"id": "seed-mcq-calc-u2-mock1-f1", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · free response</small><br>Let f be the function defined by f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>√(x + 1)</span><span>for 0 ≤ x ≤ 3</span><span>5 − x</span><span>for 3 < x ≤ 5</span></span></span>.", "parts": [{"label": "(a)", "q": "Is f continuous at x = 3? Explain why or why not.", "sol": "Yes. lim<sub>x→3⁻</sub> f(x) = √(3 + 1) = 2, lim<sub>x→3⁺</sub> f(x) = 5 − 3 = 2, and f(3) = √4 = 2. The left limit, right limit, and f(3) are all equal, so f is continuous at x = 3.<br><b>Suggested scoring (2 pts):</b> 1 pt for both one-sided limits (and f(3)), 1 pt for \"yes\" with the limit reasoning. A bare \"yes\" earns nothing.", "pts": 2}, {"label": "(c)", "q": "Suppose the function g is defined by g(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>k√(x + 1)</span><span>for 0 ≤ x ≤ 3</span><span>mx + 2</span><span>for 3 < x ≤ 5</span></span></span>, where k and m are constants. If g is differentiable at x = 3, what are the values of k and m?", "sol": "Differentiable means g is continuous AND the slopes match at x = 3.<br><b>1. Continuity:</b> k√4 = 3m + 2, so 2k = 3m + 2.<br><b>2. Slopes:</b> (k√(x + 1))′ = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">k</span><span style=\"padding:0 3px\">2√(x + 1)</span></span> (the √x rule, shifted left 1), which is k/4 at x = 3. (mx + 2)′ = m. So k/4 = m.<br><b>3. Solve:</b> 2k = 3(k/4) + 2, so (5/4)k = 2, giving <b>k = 8/5</b> and <b>m = 2/5</b>.<br><b>Suggested scoring (3 pts):</b> 1 pt for the continuity equation, 1 pt for the slope equation, 1 pt for both values.", "pts": 3}], "source": "College Board, 2003 AP Calculus AB free-response question 6, parts (a) and (c), word for word. Part (b) asks for an average value (an integral), so it is left out."}, {"id": "seed-mcq-calc-u2-mock1-f2", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · free response</small><br>Let f(x) = x² + x.", "parts": [{"label": "(a)", "q": "Use the definition f′(a) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(a + h) − f(a)</span><span style=\"padding:0 3px\">h</span></span> to find the slope of the line tangent to f at x = 1.", "sol": "f(1) = 2. f(1 + h) = (1 + h)² + (1 + h) = 1 + 2h + h² + 1 + h = 2 + 3h + h².<br><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(1 + h) − f(1)</span><span style=\"padding:0 3px\">h</span></span> = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">3h + h²</span><span style=\"padding:0 3px\">h</span></span> = 3 + h → <b>3</b> as h → 0.<br><b>Suggested scoring (2 pts):</b> 1 pt for a correct difference quotient, 1 pt for the algebra and limit. Using the power rule when the definition is asked for earns 0.", "pts": 2}, {"label": "(b)", "q": "Find an equation of the tangent line to f at x = 1.", "sol": "Point (1, f(1)) = (1, 2), slope 3: <b>y − 2 = 3(x − 1)</b> (or y = 3x − 1). <b>1 pt.</b>", "pts": 1}], "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.1, Exercise 13."}]}, {"id": "seed-mcq-calc-u2-mock2", "rev": 2, "kind": "mcq", "title": "AP Calc Unit 2 — Mock Test 2 (MCQ + FRQ)", "folder": "AP Calc", "description": "Half multiple choice, half free response (12 points each), like the AP exam. Lessons 2.1–2.8 only, including the quotient rule. Focus: quotient rule with ln x (2008 AP #6), reading f′ from graphs (2026 AP #4, CED), and corners. Every question comes from the College Board (released AP exams, the Course and Exam Description, the 2008 Practice Exam) or OpenStax Calculus, and its source is shown under the question. For free response, write your work, reveal the solution, and score yourself with the rubric.", "cards": [], "questions": [{"id": "seed-mcq-calc-u2-mock2-m0", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7 · multiple choice</small><br><table style=\"border-collapse:collapse;margin:8px 0\"><tr><th style=\"border:1px solid currentColor;padding:3px 10px\">x</th><th style=\"border:1px solid currentColor;padding:3px 10px\">f(x)</th><th style=\"border:1px solid currentColor;padding:3px 10px\">f′(x)</th><th style=\"border:1px solid currentColor;padding:3px 10px\">g(x)</th><th style=\"border:1px solid currentColor;padding:3px 10px\">g′(x)</th></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">1</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−4</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−5</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3</td></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−3</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">1</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">8</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">4</td></tr></table>The table above gives values of the differentiable functions f and g and their derivatives at selected values of x. If h is the function defined by h(x) = f(x)g(x) + 2g(x), then h′(1) =", "img": null, "choices": ["32", "30", "−6", "−16"], "answer": 0, "why": "h′(x) = f′(x)g(x) + f(x)g′(x) + 2g′(x). At x = 1: (−4)(−5) + (2)(3) + 2(3) = 20 + 6 + 6 = 32.", "source": "College Board, AP Calculus AB and BC Course and Exam Description (2019), sample multiple-choice question 3."}, {"id": "seed-mcq-calc-u2-mock2-m1", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · multiple choice</small><br>The graph of the even function y = f(x) consists of 4 line segments, as shown above. Which of the following statements about f is false?", "img": "seed/img/calc-pe08-q23.png", "choices": ["lim x→0 (f(x) − f(0)) = 0", "lim x→0 (f(x) − f(0))/x = 0", "lim x→0 (f(x) − f(−x))/(2x) = 0", "lim x→2 (f(x) − f(2))/(x − 2) = 1", "lim x→3 (f(x) − f(3))/(x − 3) does not exist."], "answer": 1, "why": "B is the derivative at 0. f has a corner at 0 (slope −1 on the left, +1 on the right), so that limit does not exist, and B is FALSE. A is true because f is continuous. C is true because f is even, so f(x) − f(−x) = 0. D is true because the slope from (0, 0) to (3, 3) is 1. E is true because (3, 3) is a corner.", "source": "College Board, 2008 AP Calculus AB Practice Exam, Section I Part A (no calculator), question 23."}, {"id": "seed-mcq-calc-u2-mock2-m2", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5 · multiple choice</small><br><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">cos(π + h) + 1</span><span style=\"padding:0 3px\">h</span></span> =", "img": null, "choices": ["The limit does not exist", "1", "−1", "0"], "answer": 3, "why": "Since cos π = −1, the top is cos(π + h) − cos π. This is the definition of the derivative of cos x at a = π, which is −sin π = 0.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.2, Exercise 70. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock2-m3", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · multiple choice</small><br>Let f(x) = 1/x. Use f′(a) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">x→a</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(x) − f(a)</span><span style=\"padding:0 3px\">x − a</span></span> to find f′(2).", "img": null, "choices": ["−1/4", "1/2", "−1/2", "1/4"], "answer": 0, "why": "<span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">1/x − 1/2</span><span style=\"padding:0 3px\">x − 2</span></span> = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">(2 − x)/(2x)</span><span style=\"padding:0 3px\">x − 2</span></span> = −1/(2x), using 2 − x = −(x − 2). As x → 2 this is −1/4. (Power rule check: f′(x) = −1/x², so f′(2) = −1/4.)", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.1, Exercise 27. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock2-m4", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8 · multiple choice</small><br>Which is an equation of the line tangent to y = 2x/(x − 1) at the point (−1, 1)?", "img": null, "choices": ["y = −½x + ½", "y = −½x − ½", "y = x + 2", "y = ½x + 3/2"], "answer": 0, "why": "Quotient rule: y′ = [2(x − 1) − 2x(1)]/(x − 1)² = −2/(x − 1)². At x = −1: −2/4 = −½. Then y − 1 = −½(x + 1), so y = −½x + ½. (y = x + 2 forgets to square the bottom.)", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 120. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock2-m5", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · multiple choice</small><br>If f(x) = 1/x − x², what is f′(1)?", "img": null, "choices": ["3", "−3", "1", "−1"], "answer": 1, "why": "Rewrite 1/x as x⁻¹. f′(x) = −x⁻² − 2x = −1/x² − 2x. At x = 1: −1 − 2 = −3.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 134. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock2-m6", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5 · multiple choice</small><br>An equation of the line tangent to f(x) = −sin x at x = 0 is", "img": null, "choices": ["y = 0", "y = −1", "y = −x", "y = x"], "answer": 2, "why": "Point: f(0) = −sin 0 = 0. Slope: f′(x) = −cos x, so f′(0) = −1. Tangent: y − 0 = −1(x − 0), so y = −x.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.5, Exercise 185. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock2-m7", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6 · multiple choice</small><br>If f(x) = x^π · π^x (π is just a number), then f′(x) =", "img": null, "choices": ["πx^(π−1)·π^x·ln π", "πx^(π−1)·π^x + x^π·π^x·ln π", "πx^(π−1) · xπ^(x−1)", "πx^(π−1)·π^x + x^π·π^x"], "answer": 1, "why": "Product rule. x^π is a POWER (power rule: πx^(π−1)). π^x is an EXPONENTIAL aˣ (rule: aˣ ln a, so π^x ln π). f′ = πx^(π−1)·π^x + x^π·π^x ln π. Choice B wrongly uses the power rule on π^x.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.9, Exercise 339. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock2-m8", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8 · multiple choice</small><br>If f(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">x² + 4</span><span style=\"padding:0 3px\">x² − 4</span></span>, then f′(x) =", "img": null, "choices": ["4x³/(x² − 4)²", "1", "−16x/(x² − 4)²", "16x/(x² − 4)²"], "answer": 2, "why": "Quotient rule: [2x(x² − 4) − (x² + 4)(2x)]/(x² − 4)² = [2x³ − 8x − 2x³ − 8x]/(x² − 4)² = −16x/(x² − 4)². 4x³/(…) comes from adding instead of subtracting, and 1 is top′/bottom′.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 116. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock2-m9", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7 · multiple choice</small><br>f and g are differentiable functions with the values in the table.<table style=\"border-collapse:collapse;margin:8px 0\"><tr><th style=\"border:1px solid currentColor;padding:3px 10px\">x</th><th style=\"border:1px solid currentColor;padding:3px 10px\">1</th><th style=\"border:1px solid currentColor;padding:3px 10px\">2</th><th style=\"border:1px solid currentColor;padding:3px 10px\">3</th><th style=\"border:1px solid currentColor;padding:3px 10px\">4</th></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">f(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">5</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">0</td></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">g(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−4</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">6</td></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">f′(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−1</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">7</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">8</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−3</td></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">g′(x)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">4</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">1</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">9</td></tr></table>If h(x) = 2x + f(x)g(x), find h′(3).", "img": null, "choices": ["−26", "18", "−36", "−34"], "answer": 3, "why": "h′(x) = 2 + f′(x)g(x) + f(x)g′(x). At x = 3: 2 + (8)(−4) + (−2)(2) = 2 − 32 − 4 = −34. −36 forgets the 2, and 18 multiplies the derivatives (2 + 8·2).", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 128. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock2-m10", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · multiple choice</small><br>T(x) is the temperature, in °F, at a height of x feet above the ground. What does T′(1000) = −0.1 mean?", "img": null, "choices": ["At a height of 1000 ft, the temperature is −0.1 °F", "At a height of 1000 ft, the temperature is dropping about 0.1 °F for each additional foot of height", "The average temperature between 0 and 1000 ft is −0.1 °F", "The temperature drops 0.1 °F for every 1000 feet"], "answer": 1, "why": "A derivative is a RATE: output units per input unit (°F per foot), at that input. T′(1000) = −0.1 means that near x = 1000 ft, going up 1 foot changes the temperature by about −0.1 °F. B describes T(1000), not T′(1000).", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.2, Exercise 97. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock2-m11", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · multiple choice</small><br>Using the limit definition, why is f(x) = x^(1/3) (the cube root of x) not differentiable at x = 0?", "img": null, "choices": ["f(0) is undefined", "The left and right difference quotients approach different finite numbers (a corner)", "The difference quotient h^(1/3)/h = 1/h^(2/3) → ∞, so the tangent line is vertical", "f is not continuous at x = 0"], "answer": 2, "why": "[f(0 + h) − f(0)]/h = h^(1/3)/h = h^(−2/3) = 1/h^(2/3). The bottom → 0⁺ from both sides, so the quotient → +∞. An infinite slope means a VERTICAL tangent, so f is not differentiable at 0. f is continuous there, and there is no corner.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.1, Exercise 41. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock2-f0", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.8 · free response</small><br>Let f be the function given by f(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">ln x</span><span style=\"padding:0 3px\">x</span></span> for all x > 0. The derivative of f is given by f′(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">1 − ln x</span><span style=\"padding:0 3px\">x²</span></span>.", "parts": [{"label": "(a)", "q": "Use the quotient rule to show that f′(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">1 − ln x</span><span style=\"padding:0 3px\">x²</span></span>.", "sol": "Low·(d high) − high·(d low), over low²: f′(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">x·(1/x) − (ln x)·1</span><span style=\"padding:0 3px\">x²</span></span> = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">1 − ln x</span><span style=\"padding:0 3px\">x²</span></span>. ✓<br><b>Suggested scoring (2 pts):</b> 1 pt for the correct quotient-rule setup with (ln x)′ = 1/x, 1 pt for simplifying x·(1/x) = 1.", "pts": 2}, {"label": "(b)", "q": "Write an equation for the line tangent to the graph of f at x = e².", "sol": "Point: f(e²) = ln(e²)/e² = 2/e². Slope: f′(e²) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">1 − 2</span><span style=\"padding:0 3px\">e⁴</span></span> = −1/e⁴.<br><b>y − 2/e² = −(1/e⁴)(x − e²)</b>.<br><b>Scoring (2 pts):</b> 1 pt for f(e²) and f′(e²), 1 pt for the equation. Don't simplify: AP accepts point-slope form.", "pts": 2}, {"label": "(c)", "q": "Find the x-coordinate of the point where the graph of f has a horizontal tangent line.", "sol": "Horizontal tangent means f′(x) = 0. A fraction is 0 when its top is 0: 1 − ln x = 0, so ln x = 1 and <b>x = e</b>. (The bottom x² is not 0 there.) <b>1 pt.</b>", "pts": 1}], "source": "College Board, 2008 AP Calculus AB free-response question 6. Part (b) here is the official part (a), word for word. Parts (a) and (c) were added: (c) uses the same f′ = 0 equation as the official (b), which goes on to relative extrema (Unit 5). The official (c) and (d) are Unit 5 and limits, so they are left out."}, {"id": "seed-mcq-calc-u2-mock2-f1", "type": "frq", "img": "seed/img/calc-ap26-q4-fprime.png", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6 · free response</small><br>Let f be a twice-differentiable function on the closed interval [−4, 4] with f(2) = 3. The graph of f′, the derivative of f, is shown.", "parts": [{"label": "Part A", "q": "For x > 0, the function g is defined by g(x) = f(x) − ln x. Find g′(2). Show the work that leads to your answer.", "sol": "g′(x) = f′(x) − 1/x. From the graph, f′(2) = 1.5 (the labeled point (2, 1.5)).<br>g′(2) = 1.5 − ½ = <b>1</b>.<br><b>Official scoring (2 pts):</b> 1 pt for g′(x) = f′(x) − 1/x (or g′(2) = f′(2) − ½), 1 pt for the answer. Trap: f(2) = 3 is not needed. The graph shows f′, not f.", "pts": 2}], "source": "College Board, 2026 AP Calculus AB free-response question 4, Part A, word for word, with the official scoring guideline. Parts B–D (inflection points, concavity, extrema) are Unit 5, so they are left out."}, {"id": "seed-mcq-calc-u2-mock2-f2", "type": "frq", "img": "seed/img/calc-ced-frq2-fprime.png", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7 · free response</small><br>The figure above shows the graph of f′, the derivative of a twice-differentiable function f, on the closed interval [0, 4]. The graph of f′ crosses the x-axis at x = 1, x = 2, and x = 3. It is known that f(2) = 5.", "parts": [{"label": "(d)", "q": "The function g is defined by g(x) = x³f(x). Find g′(2). Show the work that leads to your answer.", "sol": "Product rule: g′(x) = 3x²·f(x) + x³·f′(x).<br>f(2) = 5 is given. f′(2) = 0 because the graph of f′ crosses the x-axis at x = 2.<br>g′(2) = 3(4)(5) + 8(0) = <b>60</b>.<br><b>Suggested scoring (2 pts):</b> 1 pt for the product rule, 1 pt for the answer.", "pts": 2}], "source": "College Board, AP Calculus AB and BC Course and Exam Description (2019), sample free-response question 2, part (d). The original also lists the areas between f′ and the x-axis, which only parts (a)–(c) use. Those parts need Units 5–6, so they are left out."}, {"id": "seed-mcq-calc-u2-mock2-f3", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · free response</small><br>Let f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>−x² + 2</span><span>x ≤ 1</span><span>x</span><span>x > 1</span></span></span>.", "parts": [{"label": "(a)", "q": "Is f continuous at x = 1? Justify your answer.", "sol": "Left: −(1)² + 2 = 1. Right: lim<sub>x→1⁺</sub> x = 1. And f(1) = 1. All equal, so <b>yes</b>, f is continuous at 1. <b>1 pt.</b>", "pts": 1}, {"label": "(b)", "q": "Use the definition of the derivative (one-sided difference quotients) to show that f is not differentiable at x = 1.", "sol": "Left (h → 0⁻): <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">[−(1 + h)² + 2] − 1</span><span style=\"padding:0 3px\">h</span></span> = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">−2h − h²</span><span style=\"padding:0 3px\">h</span></span> = −2 − h → <b>−2</b>.<br>Right (h → 0⁺): <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">(1 + h) − 1</span><span style=\"padding:0 3px\">h</span></span> = h/h → <b>1</b>.<br>−2 ≠ 1, so f′(1) does not exist (a corner). f is <b>not differentiable</b> at x = 1.<br><b>Suggested scoring (2 pts):</b> 1 pt for each one-sided limit with the conclusion.", "pts": 2}], "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.2, Exercise 76. The original part (a) asks for a sketch; here it asks about continuity instead."}]}, {"id": "seed-mcq-calc-u2-mock3", "rev": 2, "kind": "mcq", "title": "AP Calc Unit 2 — Mock Test 3 (MCQ + FRQ)", "folder": "AP Calc", "description": "Half multiple choice, half free response (12 points each), like the AP exam. Lessons 2.1–2.8 only, including the quotient rule. Focus: k√x − ln x (2007 AP #6), units and meaning of a derivative, and a quotient-rule model. Every question comes from the College Board (released AP exams, the Course and Exam Description, the 2008 Practice Exam) or OpenStax Calculus, and its source is shown under the question. For free response, write your work, reveal the solution, and score yourself with the rubric.", "cards": [], "questions": [{"id": "seed-mcq-calc-u2-mock3-m0", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · multiple choice</small><br>For the function f, f′(x) = 2x + 1 and f(1) = 4. What is the approximation for f(1.2) found by using the line tangent to the graph of f at x = 1?", "img": null, "choices": ["0.6", "3.4", "4.2", "4.6", "4.64"], "answer": 3, "why": "Tangent line at x = 1: point (1, 4), slope f′(1) = 2(1) + 1 = 3, so y = 4 + 3(x − 1). At x = 1.2: 4 + 3(0.2) = 4.6. (0.6 is just the change, and 4.2 forgets the slope.)", "source": "College Board, 2008 AP Calculus AB Practice Exam, Section I Part A (no calculator), question 18."}, {"id": "seed-mcq-calc-u2-mock3-m1", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6 · multiple choice</small><br><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">eʰ − 1</span><span style=\"padding:0 3px\">h</span></span> =", "img": null, "choices": ["1", "The limit does not exist", "e", "0"], "answer": 0, "why": "e⁰ = 1, so the top is e^(0 + h) − e⁰. This is the derivative of eˣ at a = 0, which is e⁰ = 1.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.2, Exercise 73. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock3-m2", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · multiple choice</small><br><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">(2 + h)⁴ − 16</span><span style=\"padding:0 3px\">h</span></span> =", "img": null, "choices": ["16", "32", "0", "8"], "answer": 1, "why": "2⁴ = 16, so this is [f(2 + h) − f(2)]/h for f(x) = x⁴ at a = 2. f′(x) = 4x³, so f′(2) = 4·8 = 32.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.2, Exercise 71. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock3-m3", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · multiple choice</small><br>Let f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>2x</span><span>0 ≤ x ≤ 1</span><span>3x − 1</span><span>x > 1</span></span></span>. Which is true at x = 1?", "img": null, "choices": ["f is differentiable but not continuous at x = 1", "f is continuous but not differentiable at x = 1", "f is differentiable at x = 1", "f is not continuous at x = 1"], "answer": 1, "why": "Continuity: 2(1) = 2 and 3(1) − 1 = 2, so f is continuous. Slopes: 2 on the left, 3 on the right, so they do not match and there is a corner. f is not differentiable. (D is impossible: differentiable always implies continuous.)", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.2, Exercise 74. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock3-m4", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8 · multiple choice</small><br>Find an equation of the line passing through P(3, 3) and tangent to the graph of f(x) = 6/(x − 1).", "img": null, "choices": ["y = −(3/2)x + 3", "y = (3/2)x − 3/2", "y = −3x + 12", "y = −(3/2)x + 15/2"], "answer": 3, "why": "P is on the graph: f(3) = 6/2 = 3. Quotient rule (top is a constant): f′(x) = [0·(x − 1) − 6·1]/(x − 1)² = −6/(x − 1)², so f′(3) = −6/4 = −3/2. Then y − 3 = −(3/2)(x − 3), so y = −(3/2)x + 15/2. (−3 forgets to square the bottom.)", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 141. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock3-m5", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · multiple choice</small><br>At which x-values does f(x) = x³ + x² − x − 1 have a horizontal tangent line?", "img": null, "choices": ["x = 0 and x = −2/3", "x = 1 and x = −1/3", "x = −1 and x = 1", "x = −1 and x = 1/3"], "answer": 3, "why": "Horizontal tangent means f′(x) = 0: 3x² + 2x − 1 = (3x − 1)(x + 1) = 0, so x = 1/3 or x = −1. (x = 0 and −2/3 are where the slope is −1, which is part (b) of the same OpenStax exercise.)", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 142(a). Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock3-m6", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7 · multiple choice</small><br>If y = (x + cos x)(1 − sin x), then dy/dx =", "img": null, "choices": ["(1 − sin x)² − cos x·(x + cos x)", "(1 − sin x)(−cos x)", "(1 − sin x)² + cos x·(x + cos x)", "(1 + sin x)(1 − sin x) − cos x·(x + cos x)"], "answer": 0, "why": "Product rule. (x + cos x)′ = 1 − sin x and (1 − sin x)′ = −cos x. So y′ = (1 − sin x)(1 − sin x) + (x + cos x)(−cos x) = (1 − sin x)² − cos x(x + cos x). Choice B multiplies the two derivatives.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.5, Exercise 181. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock3-m7", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5 · multiple choice</small><br>For 0 < x < 2π, where does the graph of f(x) = x − 2 cos x have a tangent line with slope 2?", "img": null, "choices": ["x = π/2 only", "x = 7π/6 and x = 11π/6", "x = π/6 and x = 5π/6", "x = π/3 and x = 5π/3"], "answer": 2, "why": "f′(x) = 1 − 2(−sin x) = 1 + 2 sin x. Set 1 + 2 sin x = 2, so sin x = ½, giving x = π/6 or 5π/6 (quadrants I and II). 7π/6 and 11π/6 come from the sign mistake (cos x)′ = +sin x.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.5, Exercise 198. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock3-m8", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8 · multiple choice</small><br>If g(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">cos x</span><span style=\"padding:0 3px\">4x²</span></span>, then g′(x) =", "img": null, "choices": ["(−x sin x − 2 cos x)/(4x³)", "(−x sin x + 2 cos x)/(4x³)", "(x sin x − 2 cos x)/(4x³)", "−sin x/(8x)"], "answer": 0, "why": "Quotient rule: [(−sin x)(4x²) − (cos x)(8x)]/(4x²)² = (−4x² sin x − 8x cos x)/(16x⁴). Divide top and bottom by 4x: (−x sin x − 2 cos x)/(4x³). −sin x/(8x) is top′/bottom′.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.5, worked example \"Finding the Derivative of a Function Containing cos x\". Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock3-m9", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6 · multiple choice</small><br>If f(x) = x² ln(9x), then f′(x) =", "img": null, "choices": ["2x · 1/(9x)", "2x ln(9x)", "2x ln(9x) + x", "2x ln(9x) + 9x"], "answer": 2, "why": "Log rule first: ln(9x) = ln 9 + ln x, so (ln 9x)′ = 0 + 1/x = 1/x. Product rule: 2x·ln(9x) + x²·(1/x) = 2x ln(9x) + x.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.9, Exercise 342. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock3-m10", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8 · multiple choice</small><br>A herring swimming along a straight line has traveled s(t) = t²/(t² + 2) feet in t seconds. What is its velocity at t = 3 seconds?", "img": null, "choices": ["9/11 ft/s", "1 ft/s", "−12/121 ft/s", "12/121 ft/s"], "answer": 3, "why": "Velocity = s′(t). Quotient rule: [2t(t² + 2) − t²(2t)]/(t² + 2)² = 4t/(t² + 2)². At t = 3: 12/11² = 12/121. 9/11 is s(3), the POSITION. 1 is top′/bottom′.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 145. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock3-m11", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5 · multiple choice</small><br>A pendulum's position is s(t) = a cos t + b sin t (cm, t in seconds), where a and b are constants. If the position is 0 cm and the velocity is 3 cm/s when t = 0, find a and b.", "img": null, "choices": ["a = 0, b = −3", "a = 0, b = 3", "a = 3, b = 0", "a = −3, b = 0"], "answer": 1, "why": "s(0) = a·1 + b·0 = a = 0. Velocity v(t) = s′(t) = −a sin t + b cos t, so v(0) = b = 3.", "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.5, Exercise 201. Answer choices were written for this test."}, {"id": "seed-mcq-calc-u2-mock3-f0", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.6 · free response</small><br>Let f be the function defined by f(x) = k√x − ln x for x > 0, where k is a positive constant.", "parts": [{"label": "(a)", "q": "Find f′(x).", "sol": "√x = x^(1/2), so (k√x)′ = k·½x^(−1/2) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">k</span><span style=\"padding:0 3px\">2√x</span></span>. (ln x)′ = 1/x.<br><b>f′(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">k</span><span style=\"padding:0 3px\">2√x</span></span> − <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">1</span><span style=\"padding:0 3px\">x</span></span></b>. <b>1 pt.</b>", "pts": 1}, {"label": "(b)", "q": "For what value of the constant k does the graph of f have a horizontal tangent line at x = 1?", "sol": "Horizontal tangent: f′(1) = 0. So k/(2·1) − 1/1 = 0, giving k/2 = 1 and <b>k = 2</b>.<br><b>Suggested scoring (2 pts):</b> 1 pt for setting f′(1) = 0, 1 pt for k = 2.", "pts": 2}, {"label": "(c)", "q": "Using the value of k from part (b), write an equation for the line tangent to the graph of f at x = 4.", "sol": "f(x) = 2√x − ln x. Point: f(4) = 2(2) − ln 4 = 4 − ln 4. Slope: f′(4) = 2/(2·2) − 1/4 = ½ − ¼ = ¼.<br><b>y − (4 − ln 4) = ¼(x − 4)</b>.<br><b>Suggested scoring (2 pts):</b> 1 pt for the point and slope, 1 pt for the equation.", "pts": 2}], "source": "College Board, 2007 AP Calculus AB free-response question 6, adapted. Part (a) is the official (a) without f″(x). Part (b) asks for a horizontal tangent instead of a critical point, which uses the same equation f′(1) = 0. Part (c) was added. The rest of the original (extrema, inflection) is Unit 5."}, {"id": "seed-mcq-calc-u2-mock3-f1", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · free response</small><br>Two official AP parts about estimating a derivative from a table. Include units.", "parts": [{"label": "(a)", "q": "A student starts reading a book at time t = 0 minutes and continues reading for the next 10 minutes. The rate at which the student reads is modeled by the differentiable function R, where R(t) is measured in words per minute.<table style=\"border-collapse:collapse;margin:8px 0\"><tr><th style=\"border:1px solid currentColor;padding:3px 10px\">t (minutes)</th><th style=\"border:1px solid currentColor;padding:3px 10px\">0</th><th style=\"border:1px solid currentColor;padding:3px 10px\">2</th><th style=\"border:1px solid currentColor;padding:3px 10px\">8</th><th style=\"border:1px solid currentColor;padding:3px 10px\">10</th></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">R(t) (words per minute)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">90</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">100</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">150</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">162</td></tr></table>Approximate R′(1) using the average rate of change of R over the interval 0 ≤ t ≤ 2. Show the work that leads to your answer. Indicate units of measure.", "sol": "R′(1) ≈ <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">R(2) − R(0)</span><span style=\"padding:0 3px\">2 − 0</span></span> = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">100 − 90</span><span style=\"padding:0 3px\">2</span></span> = <b>5 words per minute per minute</b>.<br><b>Official scoring (2 pts):</b> 1 pt for the answer with setup, 1 pt for units.", "pts": 2}, {"label": "(b)", "q": "On a certain weekday, the rate at which vehicles cross a bridge is modeled by the differentiable function R for 0 ≤ t ≤ 12, where R(t) is measured in vehicles per hour and t is the number of hours since 7:00 a.m. (t = 0).<table style=\"border-collapse:collapse;margin:8px 0\"><tr><th style=\"border:1px solid currentColor;padding:3px 10px\">t (hours)</th><th style=\"border:1px solid currentColor;padding:3px 10px\">0</th><th style=\"border:1px solid currentColor;padding:3px 10px\">2</th><th style=\"border:1px solid currentColor;padding:3px 10px\">4</th><th style=\"border:1px solid currentColor;padding:3px 10px\">6</th><th style=\"border:1px solid currentColor;padding:3px 10px\">8</th><th style=\"border:1px solid currentColor;padding:3px 10px\">10</th><th style=\"border:1px solid currentColor;padding:3px 10px\">12</th></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">R(t) (vehicles per hour)</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2935</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3653</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3442</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3010</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3604</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">1986</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">2201</td></tr></table>Use the data in the table to approximate R′(5). Show the computations that lead to your answer. Using correct units, explain the meaning of R′(5) in the context of the problem.", "sol": "R′(5) ≈ <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">R(6) − R(4)</span><span style=\"padding:0 3px\">6 − 4</span></span> = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">3010 − 3442</span><span style=\"padding:0 3px\">2</span></span> = <b>−216 vehicles per hour per hour</b>.<br><b>Meaning:</b> at 12:00 noon (t = 5), the rate at which vehicles cross the bridge is DEcreasing by about 216 vehicles per hour each hour.<br><b>Suggested scoring (2 pts):</b> 1 pt for the estimate, 1 pt for the meaning with units and the time.", "pts": 2}], "source": "College Board, 2025 AP Calculus AB free-response question 3(a) (official scoring guideline) and College Board, AP Calculus AB and BC Course and Exam Description (2019), sample free-response question 1(a), both word for word. The rest of each question needs integrals."}, {"id": "seed-mcq-calc-u2-mock3-f2", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.8 · free response</small><br>The population, in millions, of arctic flounder in the Atlantic Ocean is modeled by the function P(t) = (8t + 3)/(0.2t² + 1), where t is measured in years.", "parts": [{"label": "(a)", "q": "Determine the initial flounder population.", "sol": "Initial means t = 0: P(0) = (0 + 3)/(0 + 1) = <b>3 million</b> flounder. <b>1 pt.</b>", "pts": 1}, {"label": "(b)", "q": "Determine P′(10) and briefly interpret the result.", "sol": "Quotient rule: P′(t) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">8(0.2t² + 1) − (8t + 3)(0.4t)</span><span style=\"padding:0 3px\">(0.2t² + 1)²</span></span>.<br>At t = 10: 0.2(100) + 1 = 21, so P′(10) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">8(21) − (83)(4)</span><span style=\"padding:0 3px\">21²</span></span> = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">168 − 332</span><span style=\"padding:0 3px\">441</span></span> = −164/441 ≈ <b>−0.372 million per year</b>.<br><b>Meaning:</b> at year 10, the population is decreasing by about 372,000 flounder per year.<br><b>Suggested scoring (2 pts):</b> 1 pt for the quotient-rule derivative, 1 pt for the value with its meaning.", "pts": 2}], "source": "OpenStax Calculus Volume 1 (Strang & Herman, Rice University, CC BY-NC-SA 4.0), Section 3.3, Exercise 146."}]}, {"id": "seed-mcq-apes-u2-mock1", "rev": 1, "kind": "mcq", "title": "APES Unit 2 — Mock Test 1 (climate + biomes)", "folder": "APES", "description": "40 applied questions on air/ocean currents, ENSO, seasons, albedo, climate diagrams, biomes and aquatic zones. Diagrams appear after you answer.", "cards": [], "questions": [{"id": "seed-mcq-apes-u2-mock1-q0", "stem": "A city at 30° N in the middle of a continent gets less than 25 cm of rain a year. Which best explains this?", "img": null, "choices": ["The Coriolis effect blocks rain clouds from reaching it", "A cold ocean current flows past it", "Rising air at the ITCZ cools adiabatically", "Dry air of a Hadley cell sinks there and warms adiabatically"], "answer": 3, "why": "Air sinks at ~30°, gets compressed and warms (adiabatic heating): high pressure, clear skies, little rain.", "whyImg": "seed/img/apes-u2-hadley.svg"}, {"id": "seed-mcq-apes-u2-mock1-q1", "stem": "Air rising over the equator cools mainly because it", "img": null, "choices": ["mixes with cold air from the poles", "expands as the air pressure around it decreases", "loses heat to space by radiation", "releases latent heat as it rises"], "answer": 1, "why": "Adiabatic cooling: lower pressure at altitude lets the air expand, which lowers its temperature."}, {"id": "seed-mcq-apes-u2-mock1-q2", "stem": "When water vapor condenses into cloud droplets inside a rising air mass, the air mass will most likely", "img": null, "choices": ["stop moving", "become denser", "warm and rise even higher", "cool and sink"], "answer": 2, "why": "Condensation releases latent heat, which warms the air and pushes it higher (this powers thunderstorms and Hadley cells)."}, {"id": "seed-mcq-apes-u2-mock1-q3", "stem": "Air saturated with water at 30 °C (about 30 g/m³) cools to 10 °C (about 10 g/m³). About how much water falls as precipitation per cubic meter?", "img": null, "choices": ["40 g", "20 g", "10 g", "30 g"], "answer": 1, "why": "30 − 10 = 20 g/m³ can no longer stay as vapor."}, {"id": "seed-mcq-apes-u2-mock1-q4", "stem": "Seattle gets about 37 inches of rain a year; Moses Lake, east of the Cascades, gets about 8. The main reason is that", "img": null, "choices": ["Moses Lake is farther from the equator", "Moses Lake is at a higher elevation", "air sinking down the east side of the Cascades warms and dries", "the California Current only reaches Seattle"], "answer": 2, "why": "Rain shadow: moist air rains on the windward (west) side; dry air descends the leeward side and warms adiabatically.", "whyImg": "seed/img/apes-u2-rainshadow.svg"}, {"id": "seed-mcq-apes-u2-mock1-q5", "stem": "An island's prevailing winds come from the east off a warm ocean, and it has a tall mountain in the middle. Which side will have a rainforest?", "img": null, "choices": ["The west side", "The east side", "Both sides equally", "Neither; the mountain blocks all rain"], "answer": 1, "why": "The windward (east) side gets the rain as air is forced up the mountain; the west side is the rain shadow."}, {"id": "seed-mcq-apes-u2-mock1-q6", "stem": "During an El Niño event, which change occurs off the coast of Peru?", "img": null, "choices": ["Cold, nutrient-rich water rises to the surface", "Thermohaline circulation stops", "Warm surface water builds up and upwelling is suppressed", "Stronger trade winds increase upwelling"], "answer": 2, "why": "Trade winds weaken, warm water flows east to Peru and blocks upwelling, so nutrients and fish decline.", "whyImg": "seed/img/apes-u2-enso.svg"}, {"id": "seed-mcq-apes-u2-mock1-q7", "stem": "A Peruvian fishing crew notices anchovy catches collapsing in late December, with unusually warm water. The most likely cause is", "img": null, "choices": ["the ITCZ moving south of Peru", "weakened trade winds during an El Niño", "La Niña strengthening the trade winds", "an increase in upwelling"], "answer": 1, "why": "El Niño (often starting near Christmas) weakens trade winds; warm water stops upwelling, so anchovies starve."}, {"id": "seed-mcq-apes-u2-mock1-q8", "stem": "According to the class notes, a strong El Niño winter would most likely bring which conditions to Washington State?", "img": null, "choices": ["Hurricanes", "Cold and snowy", "Warm and dry", "Cool and wet"], "answer": 2, "why": "El Niño: warm, dry winters in the northwestern U.S.; cool, wet winters in the southwestern U.S."}, {"id": "seed-mcq-apes-u2-mock1-q9", "stem": "Which describes La Niña compared with a normal year?", "img": null, "choices": ["No change in the trade winds", "Weaker trade winds and warmer water off Peru", "Stronger trade winds, stronger upwelling and colder water off Peru", "Reversed trade winds and flooding in Peru"], "answer": 2, "why": "La Niña is the opposite of El Niño: stronger trades push more warm water west and boost upwelling off Peru.", "whyImg": "seed/img/apes-u2-enso.svg"}, {"id": "seed-mcq-apes-u2-mock1-q10", "stem": "London (51° N) has much milder winters than St. John's, Newfoundland (47° N). The best explanation is", "img": null, "choices": ["London is at a lower elevation", "the polar cell sinks over Newfoundland", "the Gulf Stream carries warm tropical water toward Britain", "London is in a rain shadow"], "answer": 2, "why": "Thermohaline circulation/Gulf Stream warms western Europe; Newfoundland gets the cold North Atlantic current.", "whyImg": "seed/img/apes-u2-thermohaline.svg"}, {"id": "seed-mcq-apes-u2-mock1-q11", "stem": "Scientists worry that rapid melting of Greenland's glaciers could make western Europe colder. Why?", "img": null, "choices": ["Fresher, less dense water would stop sinking, slowing thermohaline circulation", "Fresh water would strengthen the Gulf Stream", "Melting ice raises the albedo of the North Atlantic", "More evaporation would cause more clouds over Europe"], "answer": 0, "why": "Thermohaline circulation depends on cold, SALTY, dense water sinking. Fresh meltwater is less dense, so the conveyor (and the Gulf Stream's heat) weakens."}, {"id": "seed-mcq-apes-u2-mock1-q12", "stem": "San Francisco and Washington, D.C. are at similar latitudes, but San Francisco has much cooler summers. Which ocean feature best explains this?", "img": null, "choices": ["The Gulf Stream warms Washington, D.C. in winter only", "A warm current flows north along the West Coast", "Thermohaline circulation sinks off California", "A cold current flows south along the West Coast"], "answer": 3, "why": "Cold water from the poles runs down the west coasts of continents (California Current), cooling the coast.", "whyImg": "seed/img/apes-u2-gyres.svg"}, {"id": "seed-mcq-apes-u2-mock1-q13", "stem": "Some of the world's largest fisheries are off the west coasts of South America and Africa. This is mainly because", "img": null, "choices": ["upwelling brings nutrient-rich deep water to the surface", "gyres trap fish along those coasts", "warm water there holds more oxygen", "rivers dump fresh water there"], "answer": 0, "why": "Diverging currents on west coasts pull up deep, nutrient-rich water: phytoplankton boom, then fish.", "whyImg": "seed/img/apes-u2-gyres.svg"}, {"id": "seed-mcq-apes-u2-mock1-q14", "stem": "In which direction does the North Atlantic gyre circulate?", "img": null, "choices": ["It reverses every season", "Clockwise", "Counterclockwise", "Straight east to west"], "answer": 1, "why": "Gyres go clockwise in the Northern Hemisphere and counterclockwise in the Southern (opposite of hurricanes)."}, {"id": "seed-mcq-apes-u2-mock1-q15", "stem": "A hurricane forms in the Gulf of Mexico. Viewed from above, its winds will spin", "img": null, "choices": ["counterclockwise", "clockwise", "east to west only", "in no consistent direction"], "answer": 0, "why": "Low-pressure systems spin counterclockwise in the Northern Hemisphere (class notes)."}, {"id": "seed-mcq-apes-u2-mock1-q16", "stem": "On December 21, the sun's rays are directly overhead at", "img": null, "choices": ["the Arctic Circle", "the Tropic of Cancer (23.5° N)", "the Tropic of Capricorn (23.5° S)", "the equator"], "answer": 2, "why": "December solstice: the N. Hemisphere is tilted away; the sun is overhead at 23.5° S. Shortest day in the north.", "whyImg": "seed/img/apes-u2-seasons.svg"}, {"id": "seed-mcq-apes-u2-mock1-q17", "stem": "Which statement best explains why the Northern Hemisphere has summer in July?", "img": null, "choices": ["The sun gives off more energy in July", "Earth is closest to the sun in July", "The ITCZ moves to the North Pole", "The N. Hemisphere is tilted toward the sun, so rays are more direct and days are longer"], "answer": 3, "why": "Seasons come from the 23.5° tilt (angle of rays + day length), not distance. Earth is actually closest to the sun in January."}, {"id": "seed-mcq-apes-u2-mock1-q18", "stem": "As Arctic sea ice melts and exposes dark ocean water, the region warms even faster. This is an example of", "img": null, "choices": ["a positive feedback caused by lower albedo", "latent heat release", "adiabatic heating", "a negative feedback caused by higher albedo"], "answer": 0, "why": "Ice (50-90% albedo) is replaced by water (~10%): more absorption, more melting. A reinforcing (positive) feedback."}, {"id": "seed-mcq-apes-u2-mock1-q19", "stem": "On a sunny day, a dark asphalt parking lot gets much hotter than a nearby forest. Which is the best explanation?", "img": null, "choices": ["Forests have no albedo", "The parking lot gets more direct sunlight", "Asphalt has a lower albedo, so it absorbs more solar energy", "Asphalt has a higher albedo than forest"], "answer": 2, "why": "Asphalt reflects only 5-10% (forest 10-20%), so it absorbs more energy as heat."}, {"id": "seed-mcq-apes-u2-mock1-q20", "stem": "Which biome does this climate diagram most likely represent?", "img": "seed/img/apes-u2-clim-woodland.svg", "choices": ["Temperate seasonal forest", "Subtropical desert", "Tropical rainforest", "Woodland/shrubland"], "answer": 3, "why": "Mild all year with a WET winter and almost no summer rain: Mediterranean climate = woodland/shrubland (chaparral)."}, {"id": "seed-mcq-apes-u2-mock1-q21", "stem": "Which biome does this climate diagram most likely represent?", "img": "seed/img/apes-u2-clim-troprain.svg", "choices": ["Tropical seasonal forest/savanna", "Temperate rainforest", "Tropical rainforest", "Temperate grassland"], "answer": 2, "why": "Hot all year (~24-28 °C) and heavy rain every month = tropical rainforest."}, {"id": "seed-mcq-apes-u2-mock1-q22", "stem": "On a climate diagram, the precipitation line falls below the temperature line from June through September. During those months,", "img": null, "choices": ["plant growth is limited by temperature", "it is outside the growing season", "the soil is frozen", "plant growth is limited by precipitation"], "answer": 3, "why": "When precipitation is below temperature, water demand exceeds supply: growth is limited by water.", "whyImg": "seed/img/apes-u2-clim-howto.svg"}, {"id": "seed-mcq-apes-u2-mock1-q23", "stem": "A region averages 10 °C and 75 cm of precipitation per year. Which biome is it most likely?", "img": null, "choices": ["Temperate seasonal forest", "Tropical rainforest", "Temperate grassland", "Savanna"], "answer": 0, "why": "10 °C is temperate; 75 cm is enough for broadleaf deciduous forest but too dry for temperate rainforest and too wet for grassland/cold desert.", "whyImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-mcq-apes-u2-mock1-q24", "stem": "Tropical rainforests are highly productive, yet farmers who clear them often find the soil wears out in a few years. Why?", "img": null, "choices": ["Rainforest soils have too much organic matter", "Fire destroys the topsoil every year", "The soil is frozen most of the year", "Fast decomposition and uptake by plants leave few nutrients in the soil, and heavy rain leaches the rest"], "answer": 3, "why": "Nutrients are stored in the plants, not the soil. Once the forest is cut, the thin soil loses fertility quickly."}, {"id": "seed-mcq-apes-u2-mock1-q25", "stem": "Boreal forest soils have a thick layer of organic material but are low in nutrients. Which explains this?", "img": null, "choices": ["Heavy rainfall all year", "Frequent wildfires adding ash", "Rapid decomposition in warm summers", "Slow decomposition of waxy, acidic needles in cold temperatures"], "answer": 3, "why": "Cold slows decomposers and conifer needles resist decay, so litter piles up without releasing nutrients."}, {"id": "seed-mcq-apes-u2-mock1-q26", "stem": "A biome has a thin layer of soil that thaws in summer over a permanently frozen layer, and no trees. Which biome is it?", "img": null, "choices": ["Tundra", "Boreal forest", "Temperate grassland", "Cold desert"], "answer": 0, "why": "Permafrost blocks deep roots and drainage = tundra."}, {"id": "seed-mcq-apes-u2-mock1-q27", "stem": "A biome has hot, dry summers and mild, rainy winters. Its shrubs resprout after fires and some seeds only open after a fire. Where would you find it?", "img": null, "choices": ["Southern California", "Northern Russia", "Central Canada", "The Amazon basin"], "answer": 0, "why": "Woodland/shrubland: chaparral in southern California (also the Mediterranean, Chile, SW Australia, South Africa)."}, {"id": "seed-mcq-apes-u2-mock1-q28", "stem": "Cacti in Arizona and euphorbs in Namibia look very similar even though they are not closely related. This is because", "img": null, "choices": ["both evolved in the tropical rainforest", "similar dry climates selected for similar adaptations", "euphorbs were introduced from Arizona", "they share a recent common ancestor"], "answer": 1, "why": "Convergent evolution: the same selective pressures (heat, drought) produce similar growth forms. That's why biomes are defined by plant growth forms."}, {"id": "seed-mcq-apes-u2-mock1-q29", "stem": "Savannas have a long dry season even though they are in the tropics. What causes the dry season?", "img": null, "choices": ["The polar cell reaches the tropics in winter", "Rain shadows from tall mountains", "The ITCZ moves away from the region for part of the year", "Cold ocean currents block rain"], "answer": 2, "why": "The rainy ITCZ follows the most direct sunlight, so it passes over savannas only in their summer."}, {"id": "seed-mcq-apes-u2-mock1-q30", "stem": "A hiker climbs Mt. Rainier from a lowland temperate rainforest to the summit. The changes in vegetation she sees are most similar to", "img": null, "choices": ["traveling from the equator toward the poles", "traveling from east to west across the U.S.", "traveling from the poles to the equator", "going from summer to winter in a desert"], "answer": 0, "why": "Latitude-altitude analogy: going up is like going toward the poles (forest, then subalpine forest, then alpine tundra)."}, {"id": "seed-mcq-apes-u2-mock1-q31", "stem": "It is 70 °F at the base of a mountain (1,000 ft). In dry air, about what temperature would you expect at 9,000 ft?", "img": null, "choices": ["26 °F", "61 °F", "44 °F", "46 °F"], "answer": 0, "why": "Dry lapse rate 5.5 °F per 1,000 ft. Rise = 8,000 ft, so 5.5 × 8 = 44 °F colder: 70 − 44 = 26 °F."}, {"id": "seed-mcq-apes-u2-mock1-q32", "stem": "In a pond, cattails and other rooted plants growing near the shore are found in the", "img": null, "choices": ["littoral zone", "limnetic zone", "profundal zone", "benthic zone"], "answer": 0, "why": "Littoral = shallow, near shore, rooted/emergent plants, most photosynthesis.", "whyImg": "seed/img/apes-u2-lake.svg"}, {"id": "seed-mcq-apes-u2-mock1-q33", "stem": "In the open water of a lake, where sunlight reaches but no rooted plants grow, the only producers are", "img": null, "choices": ["mosses", "chemosynthetic bacteria", "cattails", "phytoplankton"], "answer": 3, "why": "That's the limnetic zone; phytoplankton are its only photosynthesizers."}, {"id": "seed-mcq-apes-u2-mock1-q34", "stem": "Every August, fish die in a lake surrounded by fertilized farm fields. Which sequence best explains this?", "img": null, "choices": ["Upwelling brings deep cold water to the surface", "Nutrient runoff causes algae blooms; decomposers break down dead algae and use up oxygen", "Phytoplankton release toxic oxygen", "Cold water holds too much oxygen"], "answer": 1, "why": "Eutrophication: nutrients → algae bloom → dead algae → high BOD → low dissolved oxygen → fish kill. Warm summer water also holds less O2."}, {"id": "seed-mcq-apes-u2-mock1-q35", "stem": "Trout are found in a cold, fast mountain stream but not in a warm, slow river downstream. The most likely reason is that the mountain stream", "img": null, "choices": ["has more rooted plants", "has more nutrients", "is more eutrophic", "has higher dissolved oxygen from cold water and turbulence"], "answer": 3, "why": "Cold water holds more O2 and rapids mix air into the water. Trout and salmon need high DO; catfish tolerate low DO."}, {"id": "seed-mcq-apes-u2-mock1-q36", "stem": "At a deep-sea hydrothermal vent, the base of the food web is", "img": null, "choices": ["phytoplankton that photosynthesize", "kelp anchored to rocks", "zooplankton that migrate from the surface", "chemosynthetic bacteria using hydrogen sulfide"], "answer": 3, "why": "No light in the aphotic zone: bacteria get energy from H2S or methane (chemosynthesis) and feed tube worms.", "whyImg": "seed/img/apes-u2-ocean.svg"}, {"id": "seed-mcq-apes-u2-mock1-q37", "stem": "Reef-building corals contain zooxanthellae algae that provide sugars from photosynthesis, while the coral provides CO2, nutrients and shelter. This relationship is", "img": null, "choices": ["parasitism", "mutualism", "competition", "commensalism"], "answer": 1, "why": "Both benefit (+/+): mutualism. It's also why corals must live in shallow, sunlit water."}, {"id": "seed-mcq-apes-u2-mock1-q38", "stem": "A marine biologist finds large areas of white, dying coral after an unusually hot summer. What most likely happened?", "img": null, "choices": ["Salinity dropped from El Niño rains", "Warm water caused the zooxanthellae to die or leave the coral", "Zooplankton overgrazed the coral", "The coral was buried by sediment from upwelling"], "answer": 1, "why": "Coral bleaching: high temperatures (and low pH) kill or expel the symbiotic algae; without them the coral starves."}, {"id": "seed-mcq-apes-u2-mock1-q39", "stem": "Which statement best explains why estuaries are such important nursery areas for fish and shellfish?", "img": null, "choices": ["They are shallow, warm and nutrient-rich, with sheltering vegetation", "They are deep, cold and dark, so predators can't see", "They have the highest salinity of any marine biome", "They have no tides"], "answer": 0, "why": "Rivers bring nutrients into shallow, warm, brackish water with salt marsh plants: very productive and sheltered. Two-thirds of marine fish and shellfish spend larval stages there."}]}, {"id": "seed-mcq-apes-u2-mock2", "rev": 1, "kind": "mcq", "title": "APES Unit 2 — Mock Test 2 (biodiversity + conservation)", "folder": "APES", "description": "42 applied questions on Ch 18: genetic diversity, ecosystem values, HIPPCO, laws (Lacey, CITES, MMPA, ESA), reserve design, DTM math and species interactions.", "cards": [], "questions": [{"id": "seed-mcq-apes-u2-mock2-q0", "stem": "A small, isolated population of Florida panthers began showing heart defects and kinked tails. What action did scientists take that most directly solved this problem?", "img": null, "choices": ["Banning the international trade of panther parts", "Removing invasive species from their habitat", "Releasing panthers from a Texas population to add genetic diversity", "Captive breeding of the remaining Florida panthers"], "answer": 2, "why": "The defects came from inbreeding depression. Adding 8 Texas panthers brought in new alleles: the population grew from ~20 to ~100."}, {"id": "seed-mcq-apes-u2-mock2-q1", "stem": "Cheetahs have very low genetic diversity today. This is best explained by", "img": null, "choices": ["hybridization with leopards", "overharvesting by humans in the 1900s", "a population bottleneck about 10,000 years ago", "habitat fragmentation by roads"], "answer": 2, "why": "A natural (nonhuman) bottleneck ~10,000 years ago."}, {"id": "seed-mcq-apes-u2-mock2-q2", "stem": "In the 1970s a fungus destroyed about half of the corn crop in the southern U.S. The main reason the damage was so widespread was that", "img": null, "choices": ["the fungus was an invasive insect", "most farmers planted the same high-yielding, susceptible variety", "farmers used too little fertilizer", "corn has no genetic diversity at all"], "answer": 1, "why": "Low crop genetic diversity (a near-monoculture). A preserved resistant variety supplied the gene that fixed it."}, {"id": "seed-mcq-apes-u2-mock2-q3", "stem": "The Svalbard Global Seed Vault was built mainly to", "img": null, "choices": ["store genetically engineered seeds for sale", "replace seed companies", "study climate change in the Arctic", "preserve the genetic diversity of crop plants against future disasters and diseases"], "answer": 3, "why": "It protects crop varieties (genetic diversity) from war, natural disasters, climate change and new diseases."}, {"id": "seed-mcq-apes-u2-mock2-q4", "stem": "Taxol, a cancer drug, was first found in the bark of the Pacific yew. This is an example of which instrumental value?", "img": null, "choices": ["Resilience", "Provisions", "Cultural services", "Regulating services"], "answer": 1, "why": "Goods used directly by people (drugs, lumber, food) are provisions."}, {"id": "seed-mcq-apes-u2-mock2-q5", "stem": "New York City pays to protect forests around its Catskill reservoirs instead of building a $6-8 billion filtration plant. The forests are providing which category of ecosystem service?", "img": null, "choices": ["Intrinsic value", "Cultural services", "Support systems", "Provisions"], "answer": 2, "why": "Water filtration (like pollination and pest control) is a support system."}, {"id": "seed-mcq-apes-u2-mock2-q6", "stem": "Tropical rainforests and oceans absorb about half of the carbon humans add to the atmosphere each year. This is an example of", "img": null, "choices": ["a provision", "a cultural service", "a regulating service", "resilience"], "answer": 2, "why": "Regulating services control environmental conditions (carbon, climate, nutrient and water cycles)."}, {"id": "seed-mcq-apes-u2-mock2-q7", "stem": "An Oregon prairie has many species of nitrogen-fixing wildflowers. When disease kills one of them, the soil still gets plenty of nitrogen. This illustrates", "img": null, "choices": ["edge effects", "resilience", "intrinsic value", "provisions"], "answer": 1, "why": "Species diversity = resilience: other species do the same job (Zumwalt Prairie)."}, {"id": "seed-mcq-apes-u2-mock2-q8", "stem": "A person argues that a tiny cave beetle should be protected even though it has no known use to humans. This argument is based on", "img": null, "choices": ["provisions", "cultural services", "instrumental value", "intrinsic value"], "answer": 3, "why": "Intrinsic value = valuable independent of any benefit to humans."}, {"id": "seed-mcq-apes-u2-mock2-q9", "stem": "Which is the leading cause of species decline and extinction worldwide?", "img": null, "choices": ["Invasive species", "Habitat loss", "Climate change", "Overharvesting"], "answer": 1, "why": "Habitat loss (development, agriculture, logging) is #1."}, {"id": "seed-mcq-apes-u2-mock2-q10", "stem": "As a large forest is broken into small patches by farms, songbird nests near the forest edges are increasingly taken over by brown-headed cowbirds. Which statement is correct?", "img": null, "choices": ["Cowbirds and songbirds have a mutualistic relationship", "Cowbirds are a native forest-interior species", "Fragmentation increased edge habitat, where cowbirds parasitize nests", "Smaller forests have less edge habitat"], "answer": 2, "why": "Cowbirds are nest (brood) parasites (+/−) that live at edges. More fragments = more edge = more parasitized nests."}, {"id": "seed-mcq-apes-u2-mock2-q11", "stem": "Kudzu spread across the southeastern U.S. after being planted for erosion control. Which factor best explains its success?", "img": null, "choices": ["It only grows in deserts", "It is native to the Southeast", "It cannot reproduce", "It has no herbivores or natural enemies there"], "answer": 3, "why": "Invasives often escape the natural enemies that controlled them at home."}, {"id": "seed-mcq-apes-u2-mock2-q12", "stem": "Zebra mussels most likely reached the Great Lakes by", "img": null, "choices": ["attaching to migrating birds", "being sold as pets", "riding in ships' ballast water", "being released to control algae"], "answer": 2, "why": "Ships took on ballast water in the Black/Caspian Seas and pumped it out in the Great Lakes."}, {"id": "seed-mcq-apes-u2-mock2-q13", "stem": "Which is a POSITIVE effect of zebra mussels in the Great Lakes?", "img": null, "choices": ["They eat algae that native species need", "They crowd out native mussels", "They filter algae and some contaminants, making water clearer", "They clog water intake pipes"], "answer": 2, "why": "They filter water and counteract cultural eutrophication, but the negatives outweigh this."}, {"id": "seed-mcq-apes-u2-mock2-q14", "stem": "Many ground-nesting birds in Hawaii went extinct soon after rats arrived on ships. The best explanation is that", "img": null, "choices": ["rats outcompeted the birds for seeds", "the island birds had never evolved defenses against ground predators", "rats carried avian malaria", "the birds were overharvested by sailors"], "answer": 1, "why": "With no ground predators on the islands, there was no selection against ground nesting, so eggs and chicks were easy prey."}, {"id": "seed-mcq-apes-u2-mock2-q15", "stem": "The dodo went extinct within about 80 years of humans reaching Mauritius. Which two causes were most responsible?", "img": null, "choices": ["Pollution and climate change", "Habitat loss and disease", "Invasive plants and drought", "Overharvesting and introduced rats"], "answer": 3, "why": "Sailors hunted the fearless flightless bird, and rats ate its eggs and chicks."}, {"id": "seed-mcq-apes-u2-mock2-q16", "stem": "Both the American bison and the passenger pigeon were heavily market-hunted in the 1800s. Why did the bison survive while the pigeon went extinct?", "img": null, "choices": ["Bison reproduce faster than pigeons", "Bison were never overharvested", "Pigeons were invasive", "Legal protections came in time for the bison; pigeons were also hit by forest clearing"], "answer": 3, "why": "Bison (down to <1,000) were protected and rebounded to 500,000+. Pigeons faced hunting AND habitat loss; the last died in 1914."}, {"id": "seed-mcq-apes-u2-mock2-q17", "stem": "A hunter illegally shoots a deer in Wisconsin and ships the meat to a buyer in Illinois. Which law has he violated?", "img": null, "choices": ["The Marine Mammal Protection Act", "The Lacey Act", "CITES", "The Convention on Biological Diversity"], "answer": 1, "why": "The Lacey Act forbids shipping illegally harvested plants or animals across state lines."}, {"id": "seed-mcq-apes-u2-mock2-q18", "stem": "A smuggler brings rhinoceros horn from Africa into the United States. This most directly violates", "img": null, "choices": ["the Clean Water Act", "the Marine Mammal Protection Act", "the Lacey Act", "CITES"], "answer": 3, "why": "CITES controls INTERNATIONAL trade in threatened species and their parts (enforced in the U.S. under the ESA)."}, {"id": "seed-mcq-apes-u2-mock2-q19", "stem": "A developer's plan to build homes is blocked because the site is critical habitat for a listed salamander. Which law is responsible?", "img": null, "choices": ["The Endangered Species Act", "CITES", "The Marine Mammal Protection Act", "The Lacey Act"], "answer": 0, "why": "The ESA protects listed species and their critical habitat, which can restrict land use."}, {"id": "seed-mcq-apes-u2-mock2-q20", "stem": "A fisherman kills a sea otter that was eating his catch. This is prohibited under", "img": null, "choices": ["CITES", "the Marine Mammal Protection Act", "the Lacey Act", "the Convention on Biological Diversity"], "answer": 1, "why": "The MMPA (1972) bans killing ALL marine mammals in the U.S."}, {"id": "seed-mcq-apes-u2-mock2-q21", "stem": "Which is an example of the ECOSYSTEM approach to conservation rather than the single-species approach?", "img": null, "choices": ["Creating a biosphere reserve around a national park", "Captive breeding of California condors", "Listing the gray wolf under the ESA", "Banning the trade of rhino horn"], "answer": 0, "why": "Protecting a whole region (biosphere reserve, national park, marine reserve) conserves many species and functions at once."}, {"id": "seed-mcq-apes-u2-mock2-q22", "stem": "According to the theory of island biogeography, which island would have the MOST species?", "img": null, "choices": ["Small island far from the mainland", "Large island far from the mainland", "Small island close to the mainland", "Large island close to the mainland"], "answer": 3, "why": "Larger = bigger populations and more habitats; closer = more species can disperse there.", "whyImg": "seed/img/apes-u2-islands.svg"}, {"id": "seed-mcq-apes-u2-mock2-q23", "stem": "A conservation group can afford to protect either one large forest or four small forests of the same total area. An ADVANTAGE of the four small forests is that", "img": null, "choices": ["they don't need corridors", "they contain less edge habitat", "a single disease or fire is less likely to wipe out all the populations", "each one supports larger populations"], "answer": 2, "why": "SLOSS: several small reserves spread risk (metapopulations), but have more edge and smaller populations.", "whyImg": "seed/img/apes-u2-islands.svg"}, {"id": "seed-mcq-apes-u2-mock2-q24", "stem": "Building a strip of forest connecting two isolated national parks would most likely", "img": null, "choices": ["increase edge habitat in the core of each park", "block migration", "let individuals disperse, so a population that crashes can be rescued", "increase inbreeding in both parks"], "answer": 2, "why": "Habitat corridors connect a metapopulation."}, {"id": "seed-mcq-apes-u2-mock2-q25", "stem": "In a biosphere reserve, where would an ecotourism lodge and a research station most appropriately be placed?", "img": null, "choices": ["In the core zone", "In the transition area only", "Outside the reserve entirely", "In the buffer zone"], "answer": 3, "why": "Core = minimal impact. Buffer = tourism, recreation, education, research. Transition = settlements, sustainable logging and farming.", "whyImg": "seed/img/apes-u2-reserve.svg"}, {"id": "seed-mcq-apes-u2-mock2-q26", "stem": "In the Galápagos, several islands are completely off-limits to tourists while others allow visitors on designated trails. This is best described as", "img": null, "choices": ["a biosphere reserve", "a habitat corridor", "multiple-use land", "a wildlife refuge"], "answer": 0, "why": "Zones with different allowed human impacts = biosphere reserve design."}, {"id": "seed-mcq-apes-u2-mock2-q27", "stem": "In a debt-for-nature swap, a developing country", "img": null, "choices": ["receives new loans to build national parks", "sells protected land to the U.S.", "pays part of its debt to local environmental organizations for conservation instead of to the U.S.", "is forgiven all of its debt"], "answer": 2, "why": "The debt isn't erased; payments are redirected into the country's own conservation (e.g., Guatemala, Peru, Costa Rica)."}, {"id": "seed-mcq-apes-u2-mock2-q28", "stem": "Shade-grown coffee farms support about 150 bird species versus 20-50 on sun-grown farms but produce only about one-third as much coffee per hectare. Which is the main trade-off?", "img": null, "choices": ["Producing the same amount of shade coffee requires about three times as much land", "Shade coffee destroys more rainforest per hectare", "Shade coffee needs more pesticide", "Shade coffee tastes worse"], "answer": 0, "why": "Yield is 1/3, so 3× the land for the same harvest, and growers need higher prices to stay profitable."}, {"id": "seed-mcq-apes-u2-mock2-q29", "stem": "Of 744 North American mammal species, 86 are endangered. About what percent is that?", "img": null, "choices": ["16.4%", "11.6%", "86%", "8.6%"], "answer": 1, "why": "86 ÷ 744 × 100 = 11.6%."}, {"id": "seed-mcq-apes-u2-mock2-q30", "stem": "Of about 11,000 bird species that have existed since 1500, 156 have gone extinct. About what percent is that?", "img": null, "choices": ["0.14%", "15.6%", "14%", "1.4%"], "answer": 3, "why": "156 ÷ 11,000 × 100 ≈ 1.4%."}, {"id": "seed-mcq-apes-u2-mock2-q31", "stem": "Based on IUCN data, which group has the highest PERCENT of species that are threatened or near-threatened among these animals?", "img": null, "choices": ["Mammals", "Birds", "Fish", "Amphibians"], "answer": 3, "why": "Amphibians ~49% (conifers ~50% among plants). Birds and fish are ~23%, mammals ~33%."}, {"id": "seed-mcq-apes-u2-mock2-q32", "stem": "After the Deepwater Horizon spill, BP sprayed chemical dispersants to break up the oil. Why did this ALSO harm wildlife?", "img": null, "choices": ["It caused upwelling", "The dispersant itself is toxic to many animals", "It made the oil sink and raised the water temperature", "It increased the albedo of the Gulf"], "answer": 1, "why": "The dispersant is toxic. The oil + dispersant killed tens of thousands of sea turtles plus many pelicans and gulls."}, {"id": "seed-mcq-apes-u2-mock2-q33", "stem": "Scientists predict up to 25% of Banksia plant species in southwestern Australia may go extinct as the region dries. The main reason they're so vulnerable is that", "img": null, "choices": ["they are overharvested for lumber", "there's no nearby suitable habitat to migrate to", "they are invasive", "they need cold winters"], "answer": 1, "why": "The shrubland is a small peninsula with ocean on one side and a desert that's already too dry inland."}, {"id": "seed-mcq-apes-u2-mock2-q34", "stem": "What makes the current 'sixth mass extinction' different from the previous five?", "img": null, "choices": ["It is the first to remove more than 75% of species", "It is happening very quickly and is caused by humans", "It only affects marine species", "It is caused by an asteroid"], "answer": 1, "why": "Rapid, and the first since humans have been on Earth (and caused by us)."}, {"id": "seed-mcq-apes-u2-mock2-q35", "stem": "A mass extinction is defined as the loss of at least what percent of species within about 2 million years?", "img": null, "choices": ["75%", "50%", "90%", "25%"], "answer": 0, "why": "At least 75% within ~2 million years."}, {"id": "seed-mcq-apes-u2-mock2-q36", "stem": "The background extinction rate is about 0.1 per 1,000 species per millennium. If humans have increased it about 1,000-fold, the current rate is about", "img": null, "choices": ["1 per 1,000 species per millennium", "1,000 per 1,000 species per millennium", "10 per 1,000 species per millennium", "100 per 1,000 species per millennium"], "answer": 3, "why": "0.1 × 1,000 = 100."}, {"id": "seed-mcq-apes-u2-mock2-q37", "stem": "Which species would be MOST vulnerable to extinction?", "img": null, "choices": ["A small rodent that has many litters a year and lives on several continents", "An insect that eats many different plants", "A large predatory bird that raises one chick every two years and nests only in old-growth trees", "A weedy plant that grows along roadsides"], "answer": 2, "why": "Low reproductive rate + high trophic level + specialized habitat = extinction-prone."}, {"id": "seed-mcq-apes-u2-mock2-q38", "stem": "Honeybees were brought to North America in the 1600s and are widespread today, yet they are not usually called invasive. Why?", "img": null, "choices": ["They never established populations", "They are exotic but don't spread harmfully or damage native species the way invasives do", "They are native to North America", "They are protected by the ESA"], "answer": 1, "why": "Exotic = outside its historical range. Invasive = exotic AND spreads rapidly causing harm. Most exotics are not invasive."}, {"id": "seed-mcq-apes-u2-mock2-q39", "stem": "Mosses and ferns grow on the trunks and branches of trees in the Olympic temperate rainforest, getting more light without harming the trees. This relationship is", "img": null, "choices": ["commensalism", "mutualism", "predation", "parasitism"], "answer": 0, "why": "One benefits, the other is unaffected (+/0). Same as epiphytes on tropical trees."}, {"id": "seed-mcq-apes-u2-mock2-q40", "stem": "Which is a trend reported by the Convention on Biological Diversity?", "img": null, "choices": ["Overharvesting of fish has ended", "Natural habitats are becoming smaller and more fragmented", "Crop genetic diversity is increasing", "Very few species are at risk of extinction"], "answer": 1, "why": "The 2010 goal wasn't met; habitats are shrinking and fragmenting."}, {"id": "seed-mcq-apes-u2-mock2-q41", "stem": "Which pair is correct about U.S. and IUCN categories?", "img": null, "choices": ["U.S. 'threatened' is similar to IUCN 'extinct'", "U.S. 'endangered' is similar to IUCN 'threatened'", "The two systems use identical definitions", "U.S. 'endangered' is similar to IUCN 'least concern'"], "answer": 1, "why": "U.S. endangered ≈ IUCN threatened; U.S. threatened ≈ IUCN near-threatened."}]}, {"id": "seed-mcq-apes-u2-mock3", "rev": 1, "kind": "mcq", "title": "APES Unit 2 — Mock Test 3 (mixed + climate diagrams)", "folder": "APES", "description": "20 mixed questions with climate diagrams to identify, wetlands, rivers and ocean zones.", "cards": [], "questions": [{"id": "seed-mcq-apes-u2-mock3-q0", "stem": "A student watches a toilet flush clockwise in Seattle and concludes the Coriolis effect is wrong. What's the best response?", "img": null, "choices": ["The Coriolis effect only works in the Southern Hemisphere", "The Coriolis effect only affects air, not water", "Toilets in the Northern Hemisphere always spin counterclockwise", "The Coriolis effect is too weak to control water in something as small as a toilet"], "answer": 3, "why": "It only matters over large distances (hurricanes, ocean currents). The bowl's shape and jets control the swirl."}, {"id": "seed-mcq-apes-u2-mock3-q1", "stem": "Most of the weather in the contiguous United States moves from west to east. This is mainly because the U.S. lies in the belt of", "img": null, "choices": ["trade winds", "polar easterlies", "the ITCZ", "westerlies"], "answer": 3, "why": "30-60° N: westerlies (winds from the southwest).", "whyImg": "seed/img/apes-u2-circulation.svg"}, {"id": "seed-mcq-apes-u2-mock3-q2", "stem": "Which latitudes typically have rising air, low pressure and abundant precipitation?", "img": null, "choices": ["0° and 30°", "0° and 60°", "60° and 90°", "30° and 90°"], "answer": 1, "why": "Air rises at 0° (ITCZ) and 60°; it sinks at 30° and 90° (dry).", "whyImg": "seed/img/apes-u2-circulation.svg"}, {"id": "seed-mcq-apes-u2-mock3-q3", "stem": "Which list puts the atmospheric layers in order from Earth's surface upward?", "img": null, "choices": ["Troposphere, stratosphere, mesosphere, thermosphere", "Stratosphere, troposphere, mesosphere, thermosphere", "Thermosphere, mesosphere, stratosphere, troposphere", "Troposphere, mesosphere, stratosphere, thermosphere"], "answer": 0, "why": "'The Silly Monkey Threw Eggs.'"}, {"id": "seed-mcq-apes-u2-mock3-q4", "stem": "Temperature INCREASES with altitude in the stratosphere because", "img": null, "choices": ["of latent heat release from clouds", "it is closer to the sun", "ozone absorbs ultraviolet radiation and releases heat", "greenhouse gases are concentrated there"], "answer": 2, "why": "UV is absorbed by ozone in the upper stratosphere and converted to heat."}, {"id": "seed-mcq-apes-u2-mock3-q5", "stem": "The northern lights (aurora borealis) occur in which layer?", "img": null, "choices": ["Stratosphere", "Mesosphere", "Troposphere", "Thermosphere"], "answer": 3, "why": "Charged gases in the thermosphere glow when hit by solar energy."}, {"id": "seed-mcq-apes-u2-mock3-q6", "stem": "Which pair of biomes has its plant growth limited mostly by TEMPERATURE?", "img": null, "choices": ["Tropical rainforest and savanna", "Temperate grassland and woodland/shrubland", "Tundra and boreal forest", "Subtropical desert and savanna"], "answer": 2, "why": "Cold biomes: plenty of water relative to the short, cold growing season."}, {"id": "seed-mcq-apes-u2-mock3-q7", "stem": "Which biome has the most fertile soil and has been the most heavily converted to agriculture in the U.S.?", "img": null, "choices": ["Temperate grassland (tallgrass prairie)", "Boreal forest", "Tundra", "Temperate rainforest"], "answer": 0, "why": "Deep-rooted grasses + fast decomposition = rich soil; >98% of tallgrass prairie is farmland."}, {"id": "seed-mcq-apes-u2-mock3-q8", "stem": "Which biome is identified by this climate diagram?", "img": "seed/img/apes-u2-clim-boreal.svg", "choices": ["Boreal forest", "Tundra", "Temperate seasonal forest", "Temperate rainforest"], "answer": 0, "why": "Very cold winters (−15 °C), a short warm summer (~18 °C) and moderate summer rain = boreal forest."}, {"id": "seed-mcq-apes-u2-mock3-q9", "stem": "Which biome is identified by this climate diagram?", "img": "seed/img/apes-u2-clim-savanna.svg", "choices": ["Subtropical desert", "Tropical rainforest", "Tropical seasonal forest/savanna", "Woodland/shrubland"], "answer": 2, "why": "Hot all year with a very wet season and several bone-dry months = tropical seasonal forest/savanna."}, {"id": "seed-mcq-apes-u2-mock3-q10", "stem": "Which biome is identified by this climate diagram?", "img": "seed/img/apes-u2-clim-temprain.svg", "choices": ["Boreal forest", "Temperate rainforest", "Temperate seasonal forest", "Woodland/shrubland"], "answer": 1, "why": "Mild (4-18 °C, above freezing all year) with very heavy winter rain and a drier summer = temperate rainforest."}, {"id": "seed-mcq-apes-u2-mock3-q11", "stem": "Which is the MAIN reason aquatic biomes are not classified by temperature and precipitation?", "img": null, "choices": ["Water temperature never changes", "Precipitation doesn't fall on water", "Aquatic organisms don't respond to temperature", "They are defined by salinity, depth and water flow instead"], "answer": 3, "why": "Aquatic biomes are categorized by physical traits: salinity, depth and flow."}, {"id": "seed-mcq-apes-u2-mock3-q12", "stem": "A wetland is dominated by bald cypress trees standing in water. It is a", "img": null, "choices": ["estuary", "swamp", "marsh", "bog"], "answer": 1, "why": "Swamp = trees. Marsh = grasses/reeds. Bog = sphagnum moss, acidic."}, {"id": "seed-mcq-apes-u2-mock3-q13", "stem": "A cold, acidic wetland in Ireland is covered in thick sphagnum moss and peat. It is a", "img": null, "choices": ["mangrove", "bog", "swamp", "marsh"], "answer": 1, "why": "Bogs: moss build-up, acidic (Ireland's peat bogs)."}, {"id": "seed-mcq-apes-u2-mock3-q14", "stem": "Which is NOT an ecosystem service provided by wetlands?", "img": null, "choices": ["Filtering pollutants", "Flood control", "Groundwater recharge", "Producing most of Earth's oxygen through deep-sea photosynthesis"], "answer": 3, "why": "Wetlands control floods, recharge groundwater, filter water and provide habitat."}, {"id": "seed-mcq-apes-u2-mock3-q15", "stem": "The land along a river's banks, whose plants reduce erosion and shade the water, is called the", "img": null, "choices": ["periphyton", "limnetic zone", "benthic zone", "riparian zone"], "answer": 3, "why": "Periphyton = algae/animals/fungi attached to rocks on the bottom; riparian = the bank."}, {"id": "seed-mcq-apes-u2-mock3-q16", "stem": "Building a high dam with a deep reservoir on a warm river would most likely", "img": null, "choices": ["make the river downstream colder", "increase dissolved oxygen in the reservoir's depths", "stop sediment from settling in the reservoir", "warm the river downstream"], "answer": 0, "why": "Water released from the cold bottom of a deep reservoir cools the river downstream; reservoirs also fill with sediment."}, {"id": "seed-mcq-apes-u2-mock3-q17", "stem": "Which ocean zone has organisms that must survive drying out, intense sun and pounding waves twice a day?", "img": null, "choices": ["Open ocean", "Benthic zone of the deep sea", "Aphotic zone", "Intertidal zone"], "answer": 3, "why": "The intertidal zone is exposed at every low tide.", "whyImg": "seed/img/apes-u2-ocean.svg"}, {"id": "seed-mcq-apes-u2-mock3-q18", "stem": "Productivity in the open ocean (pelagic zone) is highest where", "img": null, "choices": ["light reaches and nutrients are supplied by upwelling or river mouths", "there is no current", "the water is warmest", "the water is deepest"], "answer": 0, "why": "Light + nutrients (N, P) control pelagic productivity."}, {"id": "seed-mcq-apes-u2-mock3-q19", "stem": "Mangrove swamps protect tropical coastlines mainly by", "img": null, "choices": ["increasing salinity", "producing calcium carbonate reefs", "trapping sediment and reducing erosion and storm damage", "raising water temperature"], "answer": 2, "why": "Their roots trap sediment, extend the land and buffer storms; they're also fish nurseries."}]}, {"id": "seed-mcq-apes-u2-textbook", "rev": 1, "kind": "mcq", "title": "APES Unit 2 — Textbook AP Practice Questions (Ch 4 + 18)", "folder": "APES", "description": "Every module and chapter-exam multiple-choice question from Ch 4 and Ch 18, with the answer explained.", "cards": [], "questions": [{"id": "seed-mcq-apes-u2-textbook-q0", "stem": "[Mod 59] In a major extinction event, what is the minimum percentage of species that goes extinct?", "img": null, "choices": ["40 percent", "75 percent", "50 percent", "90 percent"], "answer": 1, "why": "At least 75% within 2 million years."}, {"id": "seed-mcq-apes-u2-textbook-q1", "stem": "[Mod 59] What factor has played the largest role in decreased diversity of domesticated species?", "img": null, "choices": ["a focus on increased yields", "the use of genetic engineering", "the adaptation to specific growing environments", "increased seed storage efforts"], "answer": 0, "why": "Farmers keep only the most productive breeds/varieties."}, {"id": "seed-mcq-apes-u2-textbook-q2", "stem": "[Mod 59] Which group of organisms has had the greatest number of extinctions since 1500?", "img": null, "choices": ["birds", "reptiles", "amphibians", "fish"], "answer": 0, "why": "Birds 156; fish 70; amphibians 35; reptiles 28."}, {"id": "seed-mcq-apes-u2-textbook-q3", "stem": "[Mod 59] The intrinsic value of an ecosystem", "img": null, "choices": ["is the total monetary worth of its features.", "is based on the goods the ecosystem produces.", "considers the potential benefits that could be discovered in the ecosystem.", "is the value it has independent of humans."], "answer": 3, "why": "Intrinsic = independent of any benefit to humans."}, {"id": "seed-mcq-apes-u2-textbook-q4", "stem": "[Mod 59] Which is NOT a category of instrumental value?", "img": null, "choices": ["regulating services", "resilience", "provisions", "diversity"], "answer": 3, "why": "The 5 categories: provisions, regulating, support, resilience, cultural."}, {"id": "seed-mcq-apes-u2-textbook-q5", "stem": "[Mod 60] The most significant cause of species decline and extinction throughout the world is", "img": null, "choices": ["habitat loss.", "climate change.", "overharvesting.", "invasive species."], "answer": 0, "why": "Habitat loss is #1."}, {"id": "seed-mcq-apes-u2-textbook-q6", "stem": "[Mod 60] Invasive species are", "img": null, "choices": ["usually not a threat to biodiversity.", "rare in island habitats.", "successful due to a lack of natural enemies.", "often unable to compete effectively in the new environment."], "answer": 2, "why": "No predators, herbivores or diseases to control them."}, {"id": "seed-mcq-apes-u2-textbook-q7", "stem": "[Mod 60] Passenger pigeons were driven extinct primarily by", "img": null, "choices": ["habitat loss.", "overharvesting.", "pollution.", "invasive species."], "answer": 1, "why": "Market hunting (plus forest clearing)."}, {"id": "seed-mcq-apes-u2-textbook-q8", "stem": "[Mod 60] The Lacey Act", "img": null, "choices": ["provides protected habitats for a number of threatened species.", "forbids the interstate shipping of illegally harvested plants and animals.", "provides harvesting quotas and prevents overharvesting.", "prevents the spread of invasive species to the United States."], "answer": 1, "why": "Interstate + illegally harvested."}, {"id": "seed-mcq-apes-u2-textbook-q9", "stem": "[Mod 60] The primary impact of climate change on species diversity is expected to be", "img": null, "choices": ["an increased variability in weather.", "decreased precipitation worldwide.", "changes in available habitat because of changing temperatures.", "the increased ability of species to disperse."], "answer": 2, "why": "Shifting temperature + precipitation changes where suitable habitat is."}, {"id": "seed-mcq-apes-u2-textbook-q10", "stem": "[Mod 61] The Marine Mammal Protection Act", "img": null, "choices": ["allows states to make exceptions regarding the killing of marine mammals.", "prohibits the killing of all marine mammals.", "allows the import of marine mammal body parts.", "protects sharks as well as marine mammals."], "answer": 1, "why": "Only USFWS and NMFS can grant exceptions; sharks are fish."}, {"id": "seed-mcq-apes-u2-textbook-q11", "stem": "[Mod 61] Which is NOT true of the Endangered Species Act?", "img": null, "choices": ["It is an example of the single-species approach to conservation.", "It prohibits the hunting or harvesting of some listed species.", "It includes the development of recovery plans for listed species.", "It uses a different definition for threatened than the IUCN."], "answer": 1, "why": "The ESA prohibits harming ALL listed species, not just some. The other three are true."}, {"id": "seed-mcq-apes-u2-textbook-q12", "stem": "[Mod 61] Problems with protecting many small habitats include: I. increased proportions of edge habitats  II. increased dispersal between populations  III. the need for corridors between some protected species", "img": null, "choices": ["I only", "I and III", "II only", "II and III"], "answer": 1, "why": "More edge (I) and needing corridors to connect them (III) are costs; dispersal (II) is a benefit."}, {"id": "seed-mcq-apes-u2-textbook-q13", "stem": "[Mod 61] Which is a trend identified by the Convention on Biological Diversity?", "img": null, "choices": ["Very few plant species are at risk of extinction.", "The genetic diversity of crops is increasing.", "Marine species are affected most by recent biodiversity losses.", "Natural habitats are becoming smaller and more fragmented."], "answer": 3, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q14", "stem": "[Mod 61] According to the theory of island biogeography", "img": null, "choices": ["when conservation areas are close to each other, more species will persist.", "species on islands far from the mainland are at the least risk of extinction.", "multiple small conservation areas will protect species better than one large area of the same size.", "edge habitat is important to protect for increased diversity."], "answer": 0, "why": "Closer = easier dispersal = more species."}, {"id": "seed-mcq-apes-u2-textbook-q15", "stem": "[Ch 18 exam] Which is a cause of declining global biodiversity? I. pollution  II. habitat loss  III. overharvesting", "img": null, "choices": ["I", "I and III", "II and III", "I, II, and III"], "answer": 3, "why": "All three (plus invasives and climate change)."}, {"id": "seed-mcq-apes-u2-textbook-q16", "stem": "[Ch 18 exam] Which statement about global biodiversity is TRUE?", "img": null, "choices": ["Species diversity is decreasing but genetic diversity is increasing.", "Species diversity is decreasing and genetic diversity is decreasing.", "Species diversity is increasing but genetic diversity is decreasing.", "Declines in genetic diversity are occurring in wild plants but not in crop plants."], "answer": 1, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q17", "stem": "[Ch 18 exam] Which group of animals is declining in species diversity around the world? I. fish and amphibians  II. birds and reptiles  III. mammals", "img": null, "choices": ["I only", "I and III", "II and III", "I, II, and III"], "answer": 3, "why": "Every assessed group has many threatened species."}, {"id": "seed-mcq-apes-u2-textbook-q18", "stem": "[Ch 18 exam] Which species was historically overharvested?", "img": null, "choices": ["brown-headed cowbird", "honeybee", "dodo bird", "zebra mussel"], "answer": 2, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q19", "stem": "[Ch 18 exam] Which statement is NOT correct regarding the genetic diversity of livestock?", "img": null, "choices": ["The use of only the most productive breeds improves genetic diversity.", "Livestock come from very few species.", "The genetic diversity of livestock has declined during the past century.", "Different breeds are adapted to different climatic conditions."], "answer": 0, "why": "Using only productive breeds REDUCES diversity."}, {"id": "seed-mcq-apes-u2-textbook-q20", "stem": "[Ch 18 exam] Which statement is NOT correct about invasive exotic species?", "img": null, "choices": ["They often have no major predators or herbivores.", "Most introduced species become established in new regions.", "A well-known invasive exotic plant is the kudzu vine.", "A well-known invasive exotic animal is the zebra mussel."], "answer": 1, "why": "Most introductions FAIL to establish."}, {"id": "seed-mcq-apes-u2-textbook-q21", "stem": "[Ch 18 exam] Which is an example of the single-species approach to conservation? I. the Endangered Species Act  II. the Marine Mammal Protection Act  III. the Biosphere Reserve", "img": null, "choices": ["I only", "I and II", "I and III", "I, II, and III"], "answer": 1, "why": "Biosphere reserves are the ecosystem approach."}, {"id": "seed-mcq-apes-u2-textbook-q22", "stem": "[Ch 18 exam] Which is NOT an example of how the Endangered Species Act can affect human activities?", "img": null, "choices": ["It has been used to prevent new construction.", "It has prevented logging in particular areas.", "It prevents the killing of listed species.", "It prevents human use of biosphere reserves."], "answer": 3, "why": "Biosphere reserves allow human use in the buffer/transition zones."}, {"id": "seed-mcq-apes-u2-textbook-q23", "stem": "[Ch 18 exam] Which does NOT illustrate the principles of island biogeography?", "img": null, "choices": ["A larger protected area should contain more species.", "Protected areas that are closer together should contain more species.", "National parks can be thought of as islands of biodiversity.", "A larger protected area will have fewer habitats."], "answer": 3, "why": "Larger areas have MORE habitats."}, {"id": "seed-mcq-apes-u2-textbook-q24", "stem": "[Ch 18 exam] In a biosphere reserve", "img": null, "choices": ["sustainable agriculture and tourism are permitted in different zones.", "human activities are allowed throughout the reserve.", "human activities are restricted to the central core of the reserve.", "sustainable agriculture is permitted, but tourism is not."], "answer": 0, "why": "Tourism in the buffer; agriculture in the transition area."}, {"id": "seed-mcq-apes-u2-textbook-q25", "stem": "[Ch 18 exam] The Svalbard Global Seed Vault was created to address the problem of", "img": null, "choices": ["climate change.", "emerging diseases.", "declining genetic diversity of crop plants.", "disease resistance."], "answer": 2, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q26", "stem": "[Ch 18 exam] The international agreement known as CITES was created to", "img": null, "choices": ["monitor populations of endangered species on the Red List.", "determine if a species is endangered or not.", "control the international trade of threatened plants and animals.", "reduce the spread of invasive species."], "answer": 2, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q27", "stem": "[Ch 18 exam] In the 'debt-for-nature' swap, the debt of a country is transferred from the ___ to the ___.", "img": null, "choices": ["UN; Nature Conservancy", "World Bank; local environmental organizations", "U.S. government; local environmental organizations", "IUCN; Nature Conservancy"], "answer": 2, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q28", "stem": "[Ch 18 exam] Which is NOT associated with smaller habitat sizes?", "img": null, "choices": ["a decrease in genetic diversity", "a decrease in edge habitat", "loss of habitat diversity", "faster extinction rates"], "answer": 1, "why": "Smaller habitats have proportionally MORE edge."}, {"id": "seed-mcq-apes-u2-textbook-q29", "stem": "[Ch 18 exam] Which agreement regulates the shipping of endangered or threatened species within the United States?", "img": null, "choices": ["the Convention on International Trade in Endangered Species", "the Lacey Act", "the Endangered Species Act", "National Environmental Policy Act"], "answer": 1, "why": "Within the U.S., across state lines = Lacey Act."}, {"id": "seed-mcq-apes-u2-textbook-q30", "stem": "[Ch 18 exam] Several Galápagos islands are off-limits to tourists, while others allow tourists on outer edges and designated trails. Which best describes the Galápagos Islands?", "img": null, "choices": ["a wildlife refuge", "a biosphere reserve", "multiple-use lands", "a managed resource protection area"], "answer": 1, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q31", "stem": "[Ch 18 exam] Which is true of invasive species?", "img": null, "choices": ["Invasive species are defined as species that come from other countries.", "By definition, all exotic species are invasive.", "All invasive species spread rapidly.", "Invasive species typically have few ecological interactions."], "answer": 2, "why": "Spreading rapidly and causing harm is the definition of invasive."}, {"id": "seed-mcq-apes-u2-textbook-q32", "stem": "[Mod 9] Which list is in the correct order of atmospheric layers starting from Earth's surface?", "img": null, "choices": ["exosphere, troposphere, mesosphere, stratosphere, thermosphere", "mesosphere, stratosphere, thermosphere, exosphere, troposphere", "thermosphere, troposphere, stratosphere, exosphere, mesosphere", "troposphere, stratosphere, mesosphere, thermosphere, exosphere"], "answer": 3, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q33", "stem": "[Mod 9] Which contributes to the unequal warming of Earth? I. variation in the angle of sunlight  II. variation in the surface area over which the Sun's rays are distributed  III. variation in sunlight reflected from clouds", "img": null, "choices": ["I only", "I and II", "II and III", "III only"], "answer": 1, "why": "Angle and surface area are the textbook's main geometric causes (I and II)."}, {"id": "seed-mcq-apes-u2-textbook-q34", "stem": "[Mod 9] Which has the highest albedo?", "img": null, "choices": ["soil", "snow", "water", "pavement"], "answer": 1, "why": "Fresh snow 80-95%."}, {"id": "seed-mcq-apes-u2-textbook-q35", "stem": "[Mod 9] Summer in the Northern Hemisphere is warmer primarily because of: I. increased atmospheric absorption  II. the tilt of Earth's axis  III. reduced albedo", "img": null, "choices": ["I only", "I and II", "II only", "II and III"], "answer": 2, "why": "The tilt."}, {"id": "seed-mcq-apes-u2-textbook-q36", "stem": "[Mod 9] Which atmospheric layer contains the protective ozone layer?", "img": null, "choices": ["exosphere", "stratosphere", "thermosphere", "troposphere"], "answer": 1, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q37", "stem": "[Mod 10] Temperature change in adiabatic heating occurs due to", "img": null, "choices": ["water vapor condensing.", "a pressure increase.", "absorption of sunlight.", "a pressure decrease."], "answer": 1, "why": "Sinking air is compressed by higher pressure."}, {"id": "seed-mcq-apes-u2-textbook-q38", "stem": "[Mod 10] Latent heat release", "img": null, "choices": ["increases air temperature.", "decreases air temperature.", "increases air pressure.", "decreases air pressure."], "answer": 0, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q39", "stem": "[Mod 10] Which does NOT contribute to atmospheric convection currents?", "img": null, "choices": ["Hadley cells", "gyres", "polar cells", "the intertropical convergence zone"], "answer": 1, "why": "Gyres are OCEAN currents."}, {"id": "seed-mcq-apes-u2-textbook-q40", "stem": "[Mod 10] The maximum amount of water vapor air can hold at a given temperature is called the", "img": null, "choices": ["saturation point.", "absolute humidity.", "dew point.", "vapor pressure."], "answer": 0, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q41", "stem": "[Mod 10] The Coriolis effect is responsible for", "img": null, "choices": ["the convergence of two ascending Hadley cells.", "the location of atmospheric currents caused by the unequal heating of Earth.", "the cooling effect of air as it rises and expands.", "the deflection of atmospheric currents."], "answer": 3, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q42", "stem": "[Mod 10] Which does NOT play a role in causing a rain shadow?", "img": null, "choices": ["cold polar air", "a mountain range", "adiabatic cooling", "humid ocean air"], "answer": 0, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q43", "stem": "[Mod 10] Which is the correct order of the convection cells, starting from the equator?", "img": null, "choices": ["Ferrel, Hadley, polar", "polar, Hadley, Ferrel", "Hadley, Ferrel, polar", "Hadley, polar, Ferrel"], "answer": 2, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q44", "stem": "[Mod 11] Which does NOT drive ocean currents?", "img": null, "choices": ["salinity", "prevailing winds", "temperature", "precipitation"], "answer": 3, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q45", "stem": "[Mod 11] High productivity and nutrient availability in the ocean occurs in areas with", "img": null, "choices": ["gyres.", "upwelling.", "warm waters.", "prevailing westerlies."], "answer": 1, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q46", "stem": "[Mod 11] Climate change could potentially disrupt which phenomenon?", "img": null, "choices": ["El Niño-Southern Oscillation (ENSO)", "thermohaline circulation", "upwelling off the coasts of Australia and New Zealand", "the polar current along Antarctica"], "answer": 1, "why": "Meltwater could stop the sinking of salty North Atlantic water."}, {"id": "seed-mcq-apes-u2-textbook-q47", "stem": "[Mod 11] Which is NOT true of an El Niño-Southern Oscillation (ENSO) event?", "img": null, "choices": ["It causes increased upwelling on the west coast of South America.", "It causes wetter conditions in the southern United States.", "It includes a reversal in tropical ocean currents.", "It often begins near Christmas."], "answer": 0, "why": "El Niño SUPPRESSES upwelling."}, {"id": "seed-mcq-apes-u2-textbook-q48", "stem": "[Mod 11] Gyres do all of the following EXCEPT", "img": null, "choices": ["redistribute heat in the ocean.", "result from the Coriolis effect.", "redistribute nutrients from the deep ocean.", "affect the temperatures of coastal areas."], "answer": 2, "why": "Deep-ocean nutrients come from upwelling and thermohaline mixing, not surface gyres."}, {"id": "seed-mcq-apes-u2-textbook-q49", "stem": "[Mod 12] In addition to temperature, a terrestrial biome is defined by: I. annual precipitation  II. distinctive animal species  III. distinctive plant species", "img": null, "choices": ["I only", "I and II", "I and III", "II and III"], "answer": 2, "why": "Plant growth forms, not animals."}, {"id": "seed-mcq-apes-u2-textbook-q50", "stem": "[Mod 12] The precipitation line below the temperature line in a climate diagram shows", "img": null, "choices": ["the primary growing season.", "the biome is a desert or tundra.", "when plant growth will be limited by precipitation.", "the seasons in which droughts are most likely to occur."], "answer": 2, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q51", "stem": "[Mod 12] Permafrost is an important factor in which biome? I. tundra  II. boreal forest  III. cold desert", "img": null, "choices": ["I only", "I and II", "II only", "I and III"], "answer": 0, "why": "The textbook ties permafrost to the tundra. (Some boreal forests have patches, so if your teacher says 'I and II', go with that.)"}, {"id": "seed-mcq-apes-u2-textbook-q52", "stem": "[Mod 12] In which biome is plant growth primarily constrained by precipitation?", "img": null, "choices": ["boreal forest", "temperate seasonal forest", "temperate grassland", "tropical rainforest"], "answer": 2, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q53", "stem": "[Mod 12] Which biome has the highest soil nutrient levels?", "img": null, "choices": ["tropical rainforest", "boreal forest", "woodland/shrubland", "temperate seasonal forest"], "answer": 3, "why": "Among these choices: fast-decomposing broadleaf litter."}, {"id": "seed-mcq-apes-u2-textbook-q54", "stem": "[Mod 13] Which ecosystem experiences harsh conditions due to conditions from tides?", "img": null, "choices": ["coral reef", "open ocean", "intertidal zone", "ponds and lakes"], "answer": 2, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q55", "stem": "[Mod 13] Most of the photosynthesis in lakes and ponds occurs in the", "img": null, "choices": ["benthic zone.", "littoral zone.", "limnetic zone.", "profundal zone."], "answer": 1, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q56", "stem": "[Mod 13] Which is NOT an important ecosystem service provided by wetlands?", "img": null, "choices": ["flood control", "breeding habitat for birds", "water filtration", "seed dispersal"], "answer": 3, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q57", "stem": "[Mod 13] Aquatic biomes are categorized by: I. dominant plant growth forms  II. depth  III. salinity", "img": null, "choices": ["I and II", "I and III", "II and III", "I, II, and III"], "answer": 2, "why": "Salinity, depth and flow."}, {"id": "seed-mcq-apes-u2-textbook-q58", "stem": "[Mod 13] Which biome contains the aphotic zone?", "img": null, "choices": ["coral reefs", "streams and rivers", "freshwater wetlands", "open ocean"], "answer": 3, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q59", "stem": "[Ch 4 exam] In which layer of Earth's atmosphere does most weather occur?", "img": null, "choices": ["troposphere", "stratosphere", "mesosphere", "thermosphere"], "answer": 0, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q60", "stem": "[Ch 4 exam] Which statement best explains why polar regions are colder than tropical regions?", "img": null, "choices": ["Polar regions have lower albedo values.", "Polar regions receive less solar energy per unit of surface area.", "Tropical regions receive less direct sunlight throughout the year.", "Sunlight travels through more atmosphere and loses more energy in tropical regions."], "answer": 1, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q61", "stem": "[Ch 4 exam] Which statement about patterns of air convection is NOT correct?", "img": null, "choices": ["The air in a Hadley cell rises where sunlight strikes Earth most directly.", "The greatest amount of precipitation occurs at the intertropical convergence zone.", "The air in a Hadley cell descends near 30° N and 30° S, causing the formation of deserts.", "Along Earth's surface, the air of a Hadley cell moves away from the equator."], "answer": 3, "why": "Along the surface, Hadley-cell air moves TOWARD the equator (trade winds)."}, {"id": "seed-mcq-apes-u2-textbook-q62", "stem": "[Ch 4 exam] An increase in evaporation near the equator would most likely cause", "img": null, "choices": ["increased precipitation at the ITCZ.", "decreased precipitation at the ITCZ.", "increased precipitation in Ferrel cells.", "decreased precipitation in Ferrel cells."], "answer": 0, "why": "More water vapor rising at the ITCZ = more rain there."}, {"id": "seed-mcq-apes-u2-textbook-q63", "stem": "[Ch 4 exam] The high heat capacity of water causes what effect when combined with ocean circulation?", "img": null, "choices": ["the high salinity of deep polar water in the thermohaline cycle", "warm temperatures in continental coastal areas", "the suppression of upwelling during an ENSO event", "the heat transfer between the ocean and atmosphere due to evaporation along the equator"], "answer": 1, "why": "Currents carry stored heat to coasts (Gulf Stream warming England)."}, {"id": "seed-mcq-apes-u2-textbook-q64", "stem": "[Ch 4 exam] Which process is NOT characteristic of oceanic circulation?", "img": null, "choices": ["counterclockwise gyres in the Northern Hemisphere", "slow thermohaline circulation of surface and deep ocean waters", "unequal heating of tropical versus polar ocean waters", "El Niño-Southern Oscillation"], "answer": 0, "why": "NH gyres are CLOCKWISE."}, {"id": "seed-mcq-apes-u2-textbook-q65", "stem": "[Ch 4 exam] Which statement about rain shadows is correct?", "img": null, "choices": ["They occur on the western sides of mountain ranges in the Northern Hemisphere.", "As air rises over a mountain range, water vapor condenses into precipitation.", "They occur on the eastern sides of mountain ranges in the Southern Hemisphere.", "The rain shadow side of a mountain range receives the most rain."], "answer": 1, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q66", "stem": "[Ch 4 exam] Why do scientists use dominant plant growth forms to categorize terrestrial biomes?", "img": null, "choices": ["Plants with similar growth forms are always closely related genetically.", "Different plant growth forms indicate climate differences, whereas different animal forms do not.", "Plants from similar climates evolve different adaptations.", "Similar plant growth forms are found in climates with similar temperatures and amounts of precipitation."], "answer": 3, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q67", "stem": "[Ch 4 exam] Which information is NOT found in climate diagrams?", "img": null, "choices": ["average annual temperature", "average annual humidity", "the months when plant growth is limited by precipitation", "the length of the growing season"], "answer": 1, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q68", "stem": "[Ch 4 exam] Which statement about tundras and boreal forests is correct?", "img": null, "choices": ["Both are characterized by slow plant growth, so there is little accumulation of organic matter.", "Tundras are warmer than boreal forests.", "Boreal forests have shorter growing seasons than tundras.", "Boreal forests have larger dominant plant growth forms than tundras."], "answer": 3, "why": "Trees vs. low shrubs/mosses. (Both actually ACCUMULATE organic matter because decomposition is slow.)"}, {"id": "seed-mcq-apes-u2-textbook-q69", "stem": "[Ch 4 exam] Which statement about temperate biomes is NOT correct?", "img": null, "choices": ["Temperate biomes have average annual temperatures above 20 °C.", "Temperate rainforests receive the most precipitation, whereas cold deserts receive the least precipitation.", "Temperate rainforests can be found in the northwestern United States.", "Temperate shrublands are adapted to frequent fires."], "answer": 0, "why": "Temperate = ~5-20 °C; above 20 °C is tropical."}, {"id": "seed-mcq-apes-u2-textbook-q70", "stem": "[Ch 4 exam] Which statement about tropical biomes is correct?", "img": null, "choices": ["Tropical rainforests have the highest precipitation due to the proximity of the ITCZ.", "Savannas are characterized by the densest forests.", "Tropical rainforests have the slowest rates of decomposition due to high rainfall.", "Subtropical deserts have the highest species diversity."], "answer": 0, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q71", "stem": "[Ch 4 exam] Which statement about aquatic biomes is correct?", "img": null, "choices": ["They are characterized by dominant plant growth forms.", "They can be categorized by temperature and precipitation.", "Lakes contain littoral zones and intertidal zones.", "Freshwater wetlands have emergent plants in their deepest areas, whereas ponds and lakes do not."], "answer": 3, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q72", "stem": "[Ch 4 exam] Heavy precipitation over the ITCZ and on the windward side of mountain ranges are both caused by", "img": null, "choices": ["the Coriolis effect.", "prevailing winds.", "adiabatic heating.", "reduced air pressure."], "answer": 3, "why": "Rising air meets reduced pressure, expands and cools adiabatically, then condenses."}, {"id": "seed-mcq-apes-u2-textbook-q73", "stem": "[Ch 4 exam] A climate diagram shows temperatures of 15-22 °C all year, with 0 mm of rain in December-January and a peak of rain in June-July. Which biome?", "img": null, "choices": ["boreal forest", "temperate rainforest", "temperate seasonal forest", "tropical seasonal forest"], "answer": 3, "why": "Warm all year with distinct wet and dry seasons."}, {"id": "seed-mcq-apes-u2-textbook-q74", "stem": "[Ch 4 exam] Which is NOT true regarding an ENSO event?", "img": null, "choices": ["An ENSO event relies on thermohaline circulation.", "An ENSO event brings warmer air temperatures to South America.", "An ENSO event typically starts around Christmas.", "ENSO events are driven by a reversal of trade winds."], "answer": 0, "why": "ENSO is a surface wind/current change, not thermohaline."}, {"id": "seed-mcq-apes-u2-textbook-q75", "stem": "[Ch 4 exam] The limnetic zone is defined as the area of a lake where", "img": null, "choices": ["algae and emergent plants grow.", "sunlight does not reach.", "the thermocline exists.", "phytoplankton are the only photosynthetic organisms."], "answer": 3, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q76", "stem": "[Ch 4 exam] Which statement about the stratosphere is FALSE?", "img": null, "choices": ["It is where UV radiation is converted to infrared radiation.", "It is where Earth's weather occurs.", "It is above the troposphere.", "It contains a layer of ozone."], "answer": 1, "why": "Weather = troposphere."}, {"id": "seed-mcq-apes-u2-textbook-q77", "stem": "[Ch 4 exam] Which biome provides ecosystem services that include reducing the severity of floods and filtering pollutants from the water?", "img": null, "choices": ["freshwater wetlands", "temperate grassland", "coral reef", "open ocean"], "answer": 0, "why": ""}, {"id": "seed-mcq-apes-u2-textbook-q78", "stem": "[Ch 4 exam] Which explains the large amount of precipitation over the tropics? I. the unequal warming of the tropics  II. adiabatic heating  III. adiabatic cooling", "img": null, "choices": ["I only", "III only", "I and II", "I and III"], "answer": 3, "why": "Intense heating makes air rise; rising air cools adiabatically and rains."}]}, {"id": "seed-mcq-calc-u2-hwdrill", "rev": 3, "kind": "mcq", "title": "AP Calc Unit 2 — Homework-Style MCQ Drill (2.1–2.8)", "folder": "AP Calc", "description": "106 multiple-choice questions modeled on the 2.1–2.8 homework. The last 12 are the quotient rule (2.8). Each explanation says which homework problem it matches.", "cards": [], "questions": [{"id": "seed-mcq-calc-u2-hwdrill-q0", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>Let f(x) = x² − 3x. Which expression equals f(x + h) − f(x)?", "img": null, "choices": ["h² − 3h", "x² + 2xh + h² − 3x − 3h", "2xh + h² − 3h", "2xh + h²"], "answer": 2, "why": "f(x + h) = (x + h)² − 3(x + h) = x² + 2xh + h² − 3x − 3h. Subtract f(x) = x² − 3x: the x² and −3x cancel, leaving 2xh + h² − 3h. Always plug (x + h) into EVERY x, then subtract the WHOLE f(x)."}, {"id": "seed-mcq-calc-u2-hwdrill-q1", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>Let f(x) = 2x² + 1. Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(1 + h) − f(1)</span><span style=\"padding:0 3px\">h</span></span>.", "img": null, "choices": ["2", "3", "4", "The limit does not exist."], "answer": 2, "why": "f(1 + h) = 2(1 + 2h + h²) + 1 = 3 + 4h + 2h², and f(1) = 3. The difference quotient is (4h + 2h²)/h = 4 + 2h. Let h → 0: 4. (Shortcut check: f′(x) = 4x, so f′(1) = 4.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q2", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>For the same function, what does the value of <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(1 + h) − f(1)</span><span style=\"padding:0 3px\">h</span></span> represent?", "img": null, "choices": ["The average rate of change of f on the interval [0, 1]", "The slope of the secant line between x = 1 and x = 1 + h", "The slope of the line tangent to the graph of f at x = 1 (the instantaneous rate of change at x = 1)", "The value of f at x = 1"], "answer": 2, "why": "Without the limit, the fraction is a secant slope (average rate of change). Taking h → 0 squeezes the two points together, so the limit is the tangent slope = instantaneous rate of change = f′(1)."}, {"id": "seed-mcq-calc-u2-hwdrill-q3", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>A student uses the limit definition to find the slope of the tangent line to f(x) = 5x − x² at x = 2. Which first step is written correctly? (Note f(2) = 6.)", "img": null, "choices": ["lim h→0 [ (5(2 + h) − (2 + h)²) − 6 ] / h", "lim h→0 [ (10 + h) − (2 + h)² − 6 ] / h", "lim h→0 [ (5(2 + h) − (2 + h)²) − 6 ] / (2 + h)", "lim h→0 [ 5(2 + h) − 2 + h² − 6 ] / h"], "answer": 0, "why": "Replace every x with (2 + h) and keep grouping symbols: 5(2 + h) − (2 + h)². Then subtract f(2) = 6 and divide by h (not by 2 + h). Choice \"(10 + h)\" forgot to distribute the 5, the same mistake Lina made in 2.1 HW #3."}, {"id": "seed-mcq-calc-u2-hwdrill-q4", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">√(9 + h) − 3</span><span style=\"padding:0 3px\">h</span></span>.", "img": null, "choices": ["3", "The limit does not exist.", "1/3", "1/6"], "answer": 3, "why": "It is a derivative in disguise: f(x) = √x and a = 9, because √9 = 3. f′(x) = 1/(2√x), so f′(9) = 1/(2·3) = 1/6."}, {"id": "seed-mcq-calc-u2-hwdrill-q5", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>The concentration of a medicine is C(t) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">12</span><span style=\"padding:0 3px\">2 + t</span></span> mg/L, where t is in hours. What is the average rate of change of C on [1, 4]?", "img": null, "choices": ["−2 mg/L per hour", "−2/3 mg/L per hour", "2/3 mg/L per hour", "−1/2 mg/L per hour"], "answer": 1, "why": "Average rate of change = (C(4) − C(1))/(4 − 1) = (12/6 − 12/3)/3 = (2 − 4)/3 = −2/3 mg/L per hour. Units are (output units) per (input units)."}, {"id": "seed-mcq-calc-u2-hwdrill-q6", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>The graph of the piecewise linear function f is shown. Which statement is FALSE?", "img": "seed/img/calc-t1-pw.svg", "choices": ["(f(−5) − f(1)) / (−5 − 1) = −1/2", "lim x→−3 (f(x) − f(−3)) = 1", "lim h→0 (f(−1 + h) − f(−1)) / h = −2", "lim x→2 (f(x) − f(2)) / (x − 2) = 2"], "answer": 1, "why": "f(−5) = 0 and f(1) = −3, so the secant slope is (0 − (−3))/(−6) = −1/2 ✓. At x = −1, f is on the segment from (−2, 3) to (1, −3), slope −2 ✓. At x = 2, f is on the segment from (1, −3) to (3, 1), slope 2 ✓. f is continuous at −3, so f(x) − f(−3) → 0, not 1. That one is false."}, {"id": "seed-mcq-calc-u2-hwdrill-q7", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>The function f passes through (3, −1) and f′(3) = −2. Which is an equation of the line tangent to f at x = 3?", "img": null, "choices": ["y − 1 = −2(x + 3)", "y + 1 = −2(x − 3)", "y + 1 = ½(x − 3)", "y + 1 = −2(x + 3)"], "answer": 1, "why": "Point-slope form: y − f(a) = f′(a)(x − a). Here y − (−1) = −2(x − 3). Signs flip inside the parentheses. Slope ½ would be the NORMAL line (opposite reciprocal)."}, {"id": "seed-mcq-calc-u2-hwdrill-q8", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>The line tangent to the graph of f at x = 2 is y = 4x − 7. What are f(2) and f′(2)?", "img": null, "choices": ["f(2) = 1 and f′(2) = 4", "f(2) = 4 and f′(2) = 1", "f(2) = −7 and f′(2) = 4", "f(2) = 1 and f′(2) = −7"], "answer": 0, "why": "The tangent line touches f at x = 2, so f(2) = the line at x = 2 = 4(2) − 7 = 1. The tangent line has the same slope as f there, so f′(2) = 4."}, {"id": "seed-mcq-calc-u2-hwdrill-q9", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>Let f(x) = 3x² + x. Using the limit definition, [f(x + h) − f(x)] / h simplifies (before taking the limit) to:", "img": null, "choices": ["6x + 3h + 1", "6x + 3h² + 1", "3h + 1", "6x + 1"], "answer": 0, "why": "f(x + h) − f(x) = 3(x² + 2xh + h²) + x + h − 3x² − x = 6xh + 3h² + h. Divide by h: 6x + 3h + 1. Then letting h → 0 gives f′(x) = 6x + 1."}, {"id": "seed-mcq-calc-u2-hwdrill-q10", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>The graph of f′, the derivative of f, is shown. If f(4) = 7, which is an equation of the line tangent to the graph of f at x = 4?", "img": "seed/img/calc-t1-fprime-line.svg", "choices": ["y − 7 = 1(x − 4)", "y − 4 = 1(x − 7)", "y − 1 = 7(x − 4)", "y − 7 = −1(x − 4)"], "answer": 0, "why": "The graph shows f′, so its y-values are SLOPES of f. Read f′(4) = 1 from the graph. The point comes from f(4) = 7. Tangent line: y − 7 = 1(x − 4)."}, {"id": "seed-mcq-calc-u2-hwdrill-q11", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>Which is an equation of the line NORMAL to y = x³ at x = 1?", "img": null, "choices": ["y − 1 = 3(x − 1)", "y − 1 = −3(x − 1)", "y − 1 = ⅓(x − 1)", "y − 1 = −⅓(x − 1)"], "answer": 3, "why": "Point (1, 1). Tangent slope y′ = 3x² = 3. The normal line is perpendicular, so its slope is the opposite reciprocal: −1/3."}, {"id": "seed-mcq-calc-u2-hwdrill-q12", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>The graph of the piecewise linear function f is shown. Which statement about f′ is true?", "img": "seed/img/calc-t1-trap.svg", "choices": ["f′(3) = 2", "f′(−1) does not exist", "f′(−2) = 0", "f′(0) = 4"], "answer": 1, "why": "f′ is the slope of each segment: 2 on (−4, −1), 0 on (−1, 2), −2 on (2, 4). f′(0) = 0 (not the height 4), f′(3) = −2, f′(−2) = 2. At x = −1 there is a corner, so f′(−1) does not exist."}, {"id": "seed-mcq-calc-u2-hwdrill-q13", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>Let f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>x² + 1</span><span>x ≤ 1</span><span>2x</span><span>x > 1</span></span></span>. Which is true at x = 1?", "img": null, "choices": ["f is continuous but not differentiable at x = 1", "f is not continuous at x = 1", "f is continuous and differentiable at x = 1", "f is differentiable but not continuous at x = 1"], "answer": 2, "why": "Step 1 (continuity): left value 1² + 1 = 2, right value 2(1) = 2 ✓. Step 2 (slopes): left 2x → 2, right 2 ✓. Both match, so f is differentiable. \"Differentiable but not continuous\" is never possible."}, {"id": "seed-mcq-calc-u2-hwdrill-q14", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>Let f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>x²</span><span>x ≤ 2</span><span>4x − 3</span><span>x > 2</span></span></span>. Is f differentiable at x = 2?", "img": null, "choices": ["Yes, because both pieces are polynomials", "No, because f is not continuous at x = 2", "Yes, because the left and right slopes are both 4", "No, because the slopes do not match"], "answer": 1, "why": "Trap! The slopes DO match (2x → 4 and 4). But check continuity first: left value 4, right value 4(2) − 3 = 5. There is a jump, so f is not continuous and therefore not differentiable."}, {"id": "seed-mcq-calc-u2-hwdrill-q15", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>ax² + 1</span><span>x ≤ 1</span><span>bx − 2</span><span>x > 1</span></span></span> is differentiable for all x. What are a and b?", "img": null, "choices": ["a = −3, b = −6", "a = 1, b = 2", "a = 3, b = 4", "a = 3, b = 6"], "answer": 3, "why": "Continuity at 1: a + 1 = b − 2. Matching slopes: 2a(1) = b. Substitute b = 2a: a + 1 = 2a − 2, so a = 3 and b = 6."}, {"id": "seed-mcq-calc-u2-hwdrill-q16", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>The graph of f is shown on the interval (−4, 4). At which x-values is f NOT differentiable?", "img": "seed/img/calc-t1-features.svg", "choices": ["x = −2, x = 1, and x = 2 only", "x = −2, x = 1, x = 2, and x = 3", "x = −2 and x = 2 only", "x = 1 and x = 3 only"], "answer": 0, "why": "x = −2 is a corner. x = 1 is a vertical tangent (the curve stands straight up), so the slope is infinite. x = 2 is a jump (discontinuity). x = 3 is a smooth minimum with a horizontal tangent: slope 0 exists, so f IS differentiable there."}, {"id": "seed-mcq-calc-u2-hwdrill-q17", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>If f is differentiable at x = 3, which of the following MUST be true?", "img": null, "choices": ["f′(3) > 0", "lim x→3⁻ f′(x) = lim x→3⁺ f′(x)", "f′(3) = 0", "lim x→3 f(x) = f(3)"], "answer": 3, "why": "Differentiable ⇒ continuous, so lim f(x) = f(3) is guaranteed. Knowing f′(3) exists says nothing about the behavior of f′ NEAR 3 (2.3 HW #10), and nothing about its sign."}, {"id": "seed-mcq-calc-u2-hwdrill-q18", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>If f(x) = 4x³ − 6√x + 2/x, then f′(x) =", "img": null, "choices": ["12x² − 3/√x + 2/x²", "12x² − 3/√x − 2/x²", "12x² − 3√x − 2/x²", "12x² − 12/√x − 2/x"], "answer": 1, "why": "Rewrite first: 4x³ − 6x^(1/2) + 2x^(−1). Power rule: 12x² − 6·½x^(−1/2) + 2(−1)x^(−2) = 12x² − 3/√x − 2/x²."}, {"id": "seed-mcq-calc-u2-hwdrill-q19", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>Let f(x) = x³ − 3x² − 9x + 4. At which x-values does f have a horizontal tangent?", "img": null, "choices": ["x = 0 and x = 2", "x = 3 only", "x = 1 and x = −3", "x = −1 and x = 3"], "answer": 3, "why": "Horizontal tangent means f′(x) = 0. f′(x) = 3x² − 6x − 9 = 3(x − 3)(x + 1) = 0, so x = 3 or x = −1."}, {"id": "seed-mcq-calc-u2-hwdrill-q20", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>A particle has position s(t) = t³ for 0 ≤ t ≤ 3. At what time does its instantaneous velocity equal its average velocity on [0, 3]?", "img": null, "choices": ["t = 3/2", "t = √3", "t = 1", "t = 3"], "answer": 1, "why": "Average velocity = (s(3) − s(0))/3 = 27/3 = 9. Instantaneous velocity is s′(t) = 3t². Set 3t² = 9, so t = √3 (t = −√3 is outside [0, 3])."}, {"id": "seed-mcq-calc-u2-hwdrill-q21", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>Evaluate lim x→2 (x⁴ − 16)/(x − 2).", "img": null, "choices": ["8", "The limit does not exist.", "32", "16"], "answer": 2, "why": "Derivative in disguise: (f(x) − f(a))/(x − a) with f(x) = x⁴ and a = 2 (2⁴ = 16). f′(x) = 4x³, so f′(2) = 32."}, {"id": "seed-mcq-calc-u2-hwdrill-q22", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>A differentiable function f has f(4) = 9 and f′(4) = 5. Let g(x) = 2f(x + 1) − 3. What is g′(3)?", "img": null, "choices": ["5", "10", "15", "7"], "answer": 1, "why": "Vertical stretch by 2 doubles slopes; the −3 shift does not change slopes; the (x + 1) shift means you read f′ at x + 1. g′(x) = 2f′(x + 1), so g′(3) = 2f′(4) = 10."}, {"id": "seed-mcq-calc-u2-hwdrill-q23", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5</small><br>d/dx (3 sin x − 2 cos x) =", "img": null, "choices": ["3 cos x + 2 cos x", "3 cos x − 2 sin x", "3 cos x + 2 sin x", "−3 cos x + 2 sin x"], "answer": 2, "why": "d/dx sin x = cos x and d/dx cos x = −sin x. So −2 cos x becomes −2(−sin x) = +2 sin x."}, {"id": "seed-mcq-calc-u2-hwdrill-q24", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5</small><br>Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">x→π/3</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">cos x − ½</span><span style=\"padding:0 3px\">x − π/3</span></span>.", "img": null, "choices": ["0", "√3/2", "−1/2", "−√3/2"], "answer": 3, "why": "Derivative in disguise: f(x) = cos x, a = π/3 (cos π/3 = ½). f′(x) = −sin x, so f′(π/3) = −sin(π/3) = −√3/2."}, {"id": "seed-mcq-calc-u2-hwdrill-q25", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5</small><br>Which is an equation of the line tangent to y = 2 sin x at x = π?", "img": null, "choices": ["y = −2(x − π)", "y − 2 = −2(x − π)", "y = −2x", "y = 2(x − π)"], "answer": 0, "why": "Point: y = 2 sin π = 0, so (π, 0). Slope: y′ = 2 cos x, and 2 cos π = −2. Line: y − 0 = −2(x − π)."}, {"id": "seed-mcq-calc-u2-hwdrill-q26", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5</small><br>Let f(x) = x + 2 cos x. On [0, 2π], where does f have a horizontal tangent?", "img": null, "choices": ["x = π/6 and x = 5π/6", "x = π/3 and x = 5π/3", "x = 7π/6 and x = 11π/6", "x = π/6 and x = 11π/6"], "answer": 0, "why": "f′(x) = 1 − 2 sin x = 0 ⇒ sin x = ½. Sine is ½ in Quadrants I and II: π/6 and 5π/6. (π/3 and 5π/3 are where COS x = ½.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q27", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6</small><br>d/dx (3eˣ + 4 ln x − 5ˣ) =", "img": null, "choices": ["3eˣ + 4 ln x − 5ˣ", "3xeˣ⁻¹ + 4/x − 5ˣ ln 5", "3eˣ + 4/x − x·5^(x−1)", "3eˣ + 4/x − 5ˣ ln 5"], "answer": 3, "why": "eˣ stays eˣ. ln x becomes 1/x. aˣ becomes aˣ·ln a. The power rule does NOT apply when x is in the exponent."}, {"id": "seed-mcq-calc-u2-hwdrill-q28", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6</small><br>The line tangent to y = eˣ + 2x at (0, 1) crosses the x-axis at x =", "img": null, "choices": ["−1/2", "1/3", "−1/3", "−3"], "answer": 2, "why": "Slope: y′ = eˣ + 2, so at x = 0 it is 1 + 2 = 3. Tangent line: y = 3x + 1. Set y = 0: x = −1/3."}, {"id": "seed-mcq-calc-u2-hwdrill-q29", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6</small><br>Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">ln(e + h) − 1</span><span style=\"padding:0 3px\">h</span></span>.", "img": null, "choices": ["1/e", "0", "e", "1"], "answer": 0, "why": "ln e = 1, so this is (f(e + h) − f(e))/h with f(x) = ln x and a = e. f′(x) = 1/x, so the answer is f′(e) = 1/e."}, {"id": "seed-mcq-calc-u2-hwdrill-q30", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7</small><br>The table gives values of f, g and their derivatives at x = 1. Let h(x) = f(x)·g(x). Find h′(1).<table style=\"border-collapse:collapse;margin:8px 0\"><tr><th style=\"border:1px solid currentColor;padding:3px 10px\">x</th><th style=\"border:1px solid currentColor;padding:3px 10px\">f(x)</th><th style=\"border:1px solid currentColor;padding:3px 10px\">f′(x)</th><th style=\"border:1px solid currentColor;padding:3px 10px\">g(x)</th><th style=\"border:1px solid currentColor;padding:3px 10px\">g′(x)</th></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">1</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−2</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">4</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">5</td></tr></table>", "img": null, "choices": ["−10", "12", "7", "23"], "answer": 2, "why": "Product rule: h′ = f′g + fg′ = (−2)(4) + (3)(5) = −8 + 15 = 7. −10 is f′·g′, the classic mistake: the derivative of a product is NOT the product of the derivatives."}, {"id": "seed-mcq-calc-u2-hwdrill-q31", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7</small><br>If y = x²eˣ, then dy/dx =", "img": null, "choices": ["xeˣ(x + 2)", "2xeˣ", "2x + eˣ", "x²eˣ"], "answer": 0, "why": "Product rule: (x²)′eˣ + x²(eˣ)′ = 2xeˣ + x²eˣ. Factor out xeˣ: xeˣ(2 + x)."}, {"id": "seed-mcq-calc-u2-hwdrill-q32", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>Let f(x) = −x² + 4x. Which expression equals f(x + h)?", "img": null, "choices": ["−x² − 2xh − h² + 4x + h", "−x² − 2xh − h² + 4x + 4h", "−x² − h² + 4x + 4h", "−x² + 2xh + h² + 4x + 4h"], "answer": 1, "why": "f(x + h) = −(x + h)² + 4(x + h) = −(x² + 2xh + h²) + 4x + 4h. The negative sign must hit ALL THREE terms of (x + h)²."}, {"id": "seed-mcq-calc-u2-hwdrill-q33", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>Let f(x) = 3x − ln x. Which expression gives the instantaneous rate of change of f at x = 2?", "img": null, "choices": ["lim h→0 [ (3 + h) − ln(2 + h) − (6 − ln 2) ] / h", "lim h→0 [ 3(2 + h) − ln(2 + h) − (6 − ln 2) ] / (2 + h)", "lim x→2 [ 3x − ln x − 6 − ln 2 ] / (x − 2)", "lim x→2 [ (3x − ln x) − (6 − ln 2) ] / (x − 2)"], "answer": 3, "why": "Definition 2: (f(x) − f(2))/(x − 2) with f(2) = 6 − ln 2 subtracted as a GROUP. Choice 2 forgot the parentheses (−ln 2 should be +ln 2). Choice 3 should be 3(2 + h). Choice 4 divides by the wrong thing."}, {"id": "seed-mcq-calc-u2-hwdrill-q34", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>Let f(x) = 7 − 2x. What is the value of <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">x→5</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(x) − f(5)</span><span style=\"padding:0 3px\">x − 5</span></span>?", "img": null, "choices": ["−2", "−3", "7", "0"], "answer": 0, "why": "f is linear with slope −2, so every secant slope and every tangent slope is −2. (−3 is f(5), not a slope.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q35", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>The graph of f(x) = x² − 4x is shown. Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(1 + h) − f(1)</span><span style=\"padding:0 3px\">h</span></span> for h = 2.", "img": "seed/img/calc-t2-parabola.svg", "choices": ["0", "−2", "2", "−3"], "answer": 0, "why": "With h = 2 this is (f(3) − f(1))/2 = (−3 − (−3))/2 = 0, the slope of the secant line from (1, −3) to (3, −3). (−2 is the tangent slope f′(1), which you would get as h → 0.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q36", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>V(t) is the volume of water in a tank, in liters, t minutes after it starts draining. What does V′(4) = −3 mean?", "img": null, "choices": ["After 4 minutes the tank holds −3 liters.", "At t = 4 minutes, the volume is decreasing at a rate of 3 liters per minute.", "On average, the volume drops 3 liters per minute from t = 0 to t = 4.", "The volume decreased by 3 liters during the first 4 minutes."], "answer": 1, "why": "A derivative is an INSTANTANEOUS rate at one moment, in (output units) per (input units): liters per minute at t = 4. The negative sign means decreasing."}, {"id": "seed-mcq-calc-u2-hwdrill-q37", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>Let f(x) = 1/x. Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">x→2</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(x) − f(2)</span><span style=\"padding:0 3px\">x − 2</span></span>.", "img": null, "choices": ["−1/4", "−1/2", "1/4", "The limit does not exist."], "answer": 0, "why": "Algebra: (1/x − 1/2)/(x − 2) = ((2 − x)/(2x))/(x − 2) = −1/(2x) → −1/4. Shortcut: f′(x) = −1/x², so f′(2) = −1/4."}, {"id": "seed-mcq-calc-u2-hwdrill-q38", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>The line tangent to the graph of f at (−1, 4) also passes through (2, −5). What is f′(−1)?", "img": null, "choices": ["−9", "3", "−3", "−1/3"], "answer": 2, "why": "f′(−1) is the slope of the tangent line: (−5 − 4)/(2 − (−1)) = −9/3 = −3."}, {"id": "seed-mcq-calc-u2-hwdrill-q39", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>The graph of f′, the derivative of f, is shown. What is the slope of the line normal to the graph of f at x = 4?", "img": "seed/img/calc-t2-fprime-sqrt.svg", "choices": ["−1/4", "−4", "4", "1/4"], "answer": 0, "why": "Read the graph of f′ at x = 4: f′(4) = 4 (point B). That is the tangent slope. The normal slope is the opposite reciprocal: −1/4."}, {"id": "seed-mcq-calc-u2-hwdrill-q40", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>Using the same graph of f′, what does point A tell you about f?", "img": "seed/img/calc-t2-fprime-sqrt.svg", "choices": ["f(1) = 2.", "f has a horizontal tangent at x = 1.", "The graph of f is decreasing at x = 1.", "At x = 1, the slope of the graph of f is 2."], "answer": 3, "why": "On a graph of f′, the y-coordinate is a slope of f. A = (1, 2), so f′(1) = 2: f has slope 2 (and is increasing) at x = 1. It says nothing about the height f(1)."}, {"id": "seed-mcq-calc-u2-hwdrill-q41", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>The line y = b(x + 3) is tangent to f at x = −2, and the line y = 3b(x + 1) − 2 is tangent to f at x = 0. The two tangent lines intersect at x = 1. What are f′(−2) and f′(0)?", "img": null, "choices": ["f′(−2) = −1 and f′(0) = −3", "f′(−2) = 3 and f′(0) = 1", "f′(−2) = 1 and f′(0) = 3", "f′(−2) = 2 and f′(0) = 6"], "answer": 2, "why": "At x = 1 the lines have the same y: b(4) = 3b(2) − 2 ⇒ 4b = 6b − 2 ⇒ b = 1. The slopes of the tangent lines are f′(−2) = b = 1 and f′(0) = 3b = 3. (Same idea as 2.2 HW #8.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q42", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>The graph of f is shown. Which is true?", "img": "seed/img/calc-t2-cubic.svg", "choices": ["f′(−1) < f′(2.5) < f′(1)", "f′(2.5) < f′(−1) < f′(1)", "f′(1) < f′(2.5) < f′(−1)", "f′(−1) < f′(1) < f′(2.5)"], "answer": 0, "why": "Compare steepness and direction. At x = −1 the graph is falling steeply (most negative slope). At x = 2.5 it is falling gently (small negative). At x = 1 it is rising (positive). Here f(x) = −x³/3 + x² + 1, so f′(−1) = −3, f′(2.5) = −1.25, f′(1) = 1."}, {"id": "seed-mcq-calc-u2-hwdrill-q43", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>The line y = L(x) is tangent to the graph of f at (2, −1), and L(6) = 7. Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">x→2</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(x) − f(2)</span><span style=\"padding:0 3px\">x − 2</span></span>.", "img": null, "choices": ["undefined", "1/2", "2", "8"], "answer": 2, "why": "The limit is f′(2) = the slope of the tangent line. The tangent line goes through (2, −1) and (6, 7): slope = (7 − (−1))/(6 − 2) = 2."}, {"id": "seed-mcq-calc-u2-hwdrill-q44", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>Let f(x) = |x − 3|. Which is true at x = 3?", "img": null, "choices": ["f is not continuous at x = 3", "f is differentiable at x = 3 and f′(3) = 1", "f is differentiable at x = 3 and f′(3) = 0", "f is continuous but not differentiable at x = 3"], "answer": 3, "why": "The V-shape has a corner at x = 3: left slope −1, right slope +1. No hole or jump, so it is continuous, but the slopes do not match, so it is not differentiable."}, {"id": "seed-mcq-calc-u2-hwdrill-q45", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>Let f(x) = ∛(x − 2). Why is f not differentiable at x = 2?", "img": null, "choices": ["The graph has a vertical tangent at x = 2", "f is not defined at x = 2", "The graph has a corner at x = 2", "f is not continuous at x = 2"], "answer": 0, "why": "f′(x) = 1/(3(x − 2)^(2/3)), which blows up at x = 2. The curve stands straight up there: a vertical tangent (infinite slope). f(2) = 0 and f is continuous."}, {"id": "seed-mcq-calc-u2-hwdrill-q46", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>ax² + bx</span><span>x ≤ 1</span><span>4x − 1</span><span>x > 1</span></span></span> is differentiable at x = 1. What are a and b?", "img": null, "choices": ["a = 1, b = 3", "a = 1, b = 2", "a = 2, b = 1", "a = 3, b = −2"], "answer": 1, "why": "Continuity: a + b = 4(1) − 1 = 3. Slopes: 2a(1) + b = 4. Subtract the equations: a = 1, then b = 2."}, {"id": "seed-mcq-calc-u2-hwdrill-q47", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>2 sin x</span><span>x ≤ π/6</span><span>ax + b</span><span>x > π/6</span></span></span> is differentiable. What are a and b?", "img": null, "choices": ["a = 2, b = 1 − π/3", "a = √3, b = 1 − √3π/6", "a = √3, b = 1", "a = 1, b = 1 − π/6"], "answer": 1, "why": "Slopes: 2 cos(π/6) = 2·(√3/2) = √3 = a. Continuity: 2 sin(π/6) = 1 must equal a(π/6) + b, so b = 1 − √3π/6. (Same setup as 2.5 HW #3 and 2.6 HW #4.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q48", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>Let f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>3 ln x</span><span>x ≤ 1</span><span>x² + x − 2</span><span>x > 1</span></span></span>. Which statements are true?<br>I. f is continuous at x = 1<br>II. lim x→1⁻ f′(x) = lim x→1⁺ f′(x)<br>III. f′(1) = 3", "img": null, "choices": ["I only", "II only", "II and III only", "I, II, and III"], "answer": 3, "why": "I: left value 3 ln 1 = 0, right value 1 + 1 − 2 = 0 ✓. II: left 3/x → 3, right 2x + 1 → 3 ✓. Since both hold, f is differentiable and f′(1) = 3 ✓. Compare 2.6 HW #10, where II was true but I failed because of a jump."}, {"id": "seed-mcq-calc-u2-hwdrill-q49", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>The graph of f′, the derivative of f, is shown. On (−4, 4), at which x-values is f NOT differentiable?", "img": "seed/img/calc-t2-fprime-asym.svg", "choices": ["x = −1 and x = 2 only", "x = 1 only", "x = 1 and x = 2 only", "x = −1, x = 1, and x = 2"], "answer": 0, "why": "f fails to be differentiable where f′ does not exist: the hole at x = −1 and the vertical asymptote at x = 2. The sharp point at x = 1 is on the graph of f′ itself (f′(1) = 2.5 exists), so f IS differentiable at x = 1. (Same trap as 2.3 HW #8.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q50", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>If g(x) = 8/x² − 3∛x, then g′(x) =", "img": null, "choices": ["−16/x − x^(−2/3)", "−16/x³ − 1/∛(x²)", "16/x³ − 1/∛(x²)", "−16/x³ − 3/∛(x²)"], "answer": 1, "why": "Rewrite: 8x^(−2) − 3x^(1/3). Power rule: −16x^(−3) − 3·⅓x^(−2/3) = −16/x³ − 1/x^(2/3)."}, {"id": "seed-mcq-calc-u2-hwdrill-q51", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>The graphs of f(x) = ax − x² and g(x) = x² + bx + c are tangent to each other at the point (1, 2). What are a, b, and c?", "img": null, "choices": ["a = 1, b = −1, c = 2", "a = 3, b = −1, c = 2", "a = 3, b = 1, c = 0", "a = 3, b = −3, c = 4"], "answer": 1, "why": "Tangent at (1, 2) means same point AND same slope. f(1) = a − 1 = 2 ⇒ a = 3. f′(x) = 3 − 2x, so f′(1) = 1. g′(x) = 2x + b ⇒ 2 + b = 1 ⇒ b = −1. g(1) = 1 − 1 + c = 2 ⇒ c = 2. (Like 2.4 HW #6.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q52", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>The graph of the line y = g(x) is shown. Let f(x) = x² + 3g(x). What is f′(2)?", "img": "seed/img/calc-t2-gline.svg", "choices": ["7/2", "11/2", "7", "5/2"], "answer": 3, "why": "g is a line through (0, 2) with slope −1/2, so g′(x) = −1/2 everywhere. f′(x) = 2x + 3g′(x), so f′(2) = 4 + 3(−1/2) = 5/2. (Like 2.4 HW #3.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q53", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>Let f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>x² − 2x</span><span>x < 3</span><span>4x − 9</span><span>x ≥ 3</span></span></span>. What is f′(3)?", "img": null, "choices": ["3", "4", "Nonexistent", "6"], "answer": 1, "why": "Continuity: 9 − 6 = 3 and 12 − 9 = 3 ✓. Slopes: 2x − 2 → 4 and 4 ✓. Both match, so f′(3) = 4. (Like 2.4 HW #10.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q54", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5</small><br>Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">sin(π/4 + h) − √2/2</span><span style=\"padding:0 3px\">h</span></span>.", "img": null, "choices": ["√2/2", "1", "−√2/2", "0"], "answer": 0, "why": "sin(π/4) = √2/2, so this is the definition of f′(π/4) for f(x) = sin x. f′(x) = cos x, and cos(π/4) = √2/2."}, {"id": "seed-mcq-calc-u2-hwdrill-q55", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5</small><br>On [0, π], where is the line tangent to g(x) = sin x parallel to the line tangent to h(x) = √3 cos x?", "img": null, "choices": ["x = π/6", "x = 5π/6", "x = 2π/3", "x = π/3"], "answer": 1, "why": "Parallel ⇒ equal slopes: cos x = −√3 sin x ⇒ tan x = −1/√3. On [0, π], tangent is negative in Quadrant II: x = 5π/6. (Like 2.5 HW #6b.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q56", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5</small><br>The graph of f(x) = cos x is shown. Point A is at x = π/2 and point B is at x = 7π/6. Which point has the steeper slope, and how many times steeper?", "img": "seed/img/calc-t2-cos.svg", "choices": ["Point B, twice as steep", "Point A, twice as steep", "They are equally steep", "Point A, three times as steep"], "answer": 1, "why": "Slope = f′(x) = −sin x. At A (x = π/2): −sin(π/2) = −1. At B (x = 7π/6): −sin(7π/6) = ½. |−1| is twice |½|, so A is twice as steep. (Like 2.5 HW #9.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q57", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6</small><br>Which expression does NOT equal 6?", "img": null, "choices": ["3 ln e²", "e^(ln 2 + ln 3)", "ln e² + ln e⁴", "(ln e³)²"], "answer": 3, "why": "(ln e³)² = 3² = 9. The others: e^(ln 6) = 6; 3·2 = 6; 2 + 4 = 6. Remember ln eⁿ = n and e^(ln n) = n."}, {"id": "seed-mcq-calc-u2-hwdrill-q58", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6</small><br>A line with slope m passes through the origin and is tangent to y = 4 ln x. What is m?", "img": null, "choices": ["e/4", "4/e", "4", "1/e"], "answer": 1, "why": "Let the tangent point be (x, 4 ln x). Slope from derivative: 4/x. Slope from origin: (4 ln x)/x. Set equal: ln x = 1, so x = e, and m = 4/e. (Like 2.6 HW #6.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q59", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6</small><br>At what point on the graph of f(x) = eˣ − 2x is the tangent line parallel to y = x + 5?", "img": null, "choices": ["(ln 2, 2 − 2 ln 2)", "(ln 3, 3)", "(ln 3, 3 − 2 ln 3)", "(3, e³ − 6)"], "answer": 2, "why": "Parallel ⇒ slope 1. f′(x) = eˣ − 2 = 1 ⇒ eˣ = 3 ⇒ x = ln 3. y = e^(ln 3) − 2 ln 3 = 3 − 2 ln 3."}, {"id": "seed-mcq-calc-u2-hwdrill-q60", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7</small><br>If y = x³ ln x, then dy/dx =", "img": null, "choices": ["x²(3 ln x + 1)", "3x² ln x", "3x²", "x²(3 + ln x)"], "answer": 0, "why": "Product rule: (x³)′ ln x + x³ (ln x)′ = 3x² ln x + x³·(1/x) = 3x² ln x + x² = x²(3 ln x + 1)."}, {"id": "seed-mcq-calc-u2-hwdrill-q61", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7</small><br>For what value of x is the line tangent to f(x) = (2x − 1)eˣ horizontal?", "img": null, "choices": ["x = −1/2", "There is no such x.", "x = 0", "x = 1/2"], "answer": 0, "why": "f′(x) = 2eˣ + (2x − 1)eˣ = eˣ(2x + 1). eˣ is never 0, so 2x + 1 = 0 ⇒ x = −1/2. (Like 2.7 HW #6.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q62", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7</small><br>Let f(x) = 2x³ and g(x) = x². If h(x) = f(x)·g(x), what is h′(x)?", "img": null, "choices": ["10x⁴", "12x³", "6x² + 2x", "2x⁵"], "answer": 0, "why": "h(x) = 2x⁵, so h′(x) = 10x⁴. Product rule check: 6x²·x² + 2x³·2x = 6x⁴ + 4x⁴ = 10x⁴. 12x³ is f′·g′, which is NOT the derivative of the product."}, {"id": "seed-mcq-calc-u2-hwdrill-q63", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>Let f(x) = x² + 5. Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(2 + h) − f(2)</span><span style=\"padding:0 3px\">h</span></span>.", "img": null, "choices": ["9", "4", "4 + h", "2"], "answer": 1, "why": "(f(2 + h) − f(2))/h = ((4 + 4h + h² + 5) − 9)/h = 4 + h. Then h → 0 gives 4. (4 + h is the step BEFORE taking the limit.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q64", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>You estimate f′(1) with (f(1 + h) − f(1))/h. Which value of h gives the best estimate?", "img": null, "choices": ["h = 4", "h = 2", "h = 0.5", "h = 0.1"], "answer": 3, "why": "The closer h is to 0, the closer the secant line is to the tangent line. (Like 2.1 HW #4d.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q65", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>Let f(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">4</span><span style=\"padding:0 3px\">x + 2</span></span>. What is the instantaneous rate of change of f at x = 2?", "img": null, "choices": ["1", "−1", "1/4", "−1/4"], "answer": 3, "why": "f(x) = 4(x + 2)^(−1). The instantaneous rate is f′(2). Using the limit definition (or the shortcut f′(x) = −4/(x + 2)²): f′(2) = −4/16 = −1/4."}, {"id": "seed-mcq-calc-u2-hwdrill-q66", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>The slope of the tangent line to f at x = c is <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">cos(π/2 + h)</span><span style=\"padding:0 3px\">h</span></span>. What is the value of this slope?", "img": null, "choices": ["The limit does not exist.", "0", "1", "−1"], "answer": 3, "why": "cos(π/2) = 0, so this is (f(c + h) − f(c))/h with f(x) = cos x and c = π/2. f′(x) = −sin x, so f′(π/2) = −1. (Like 2.1 HW #7.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q67", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1</small><br>f(1) = 4, f(3) = 10, and <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">x→3</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(x) − f(3)</span><span style=\"padding:0 3px\">x − 3</span></span> = −2. Which is NOT guaranteed?", "img": null, "choices": ["The tangent line to f at x = 3 has negative slope.", "The average rate of change of f on [1, 3] is 3.", "f is continuous at x = 3.", "f′(1) > 0"], "answer": 3, "why": "Average rate = (10 − 4)/2 = 3 ✓. f′(3) = −2 < 0 ✓. Differentiable at 3 ⇒ continuous at 3 ✓. Nothing tells you f′(1): a positive average rate does not mean the slope at x = 1 is positive. (Like 2.1 HW #10.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q68", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>Which is an equation of the line normal to y = √x at x = 4?", "img": null, "choices": ["y − 4 = −4(x − 2)", "y − 2 = 4(x − 4)", "y − 2 = ¼(x − 4)", "y − 2 = −4(x − 4)"], "answer": 3, "why": "Point: (4, √4) = (4, 2). Tangent slope: y′ = 1/(2√x) = 1/4. Normal slope: −4."}, {"id": "seed-mcq-calc-u2-hwdrill-q69", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>The graph of the piecewise linear function f is shown. Which describes f′?", "img": "seed/img/calc-t3-pw.svg", "choices": ["f′ = −2 on (−4, −2), 2 on (−2, 1), −4 on (1, 3)", "f′ = 2 on (−4, −2), 2 on (−2, 1), −3 on (1, 3)", "f′ = 2 on (−4, −2), 0 on (−2, 1), −3 on (1, 3); f′(−2) = 2 and f′(1) = 0", "f′ = 2 on (−4, −2), 0 on (−2, 1), −3 on (1, 3); f′ does not exist at x = −2 and x = 1"], "answer": 3, "why": "f′ is the slope of each segment (not its height): (−4, −2) → (−2, 2) has slope 2; the flat part has slope 0; (1, 2) → (3, −4) has slope −6/2 = −3. At corners f′ does not exist, so the graph of f′ has open circles there. (Like 2.2 HW #4.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q70", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2</small><br>The graph of f′ is shown and f(2) = 5. Which is an equation of the line tangent to f at x = 2?", "img": "seed/img/calc-t3-fprime-line.svg", "choices": ["y = 5", "y = 2x + 5", "y − 5 = 2(x − 2)", "x = 2"], "answer": 0, "why": "Read f′(2) = 0 from the graph (where f′ crosses the x-axis). A slope of 0 gives a horizontal tangent line through (2, 5): y = 5."}, {"id": "seed-mcq-calc-u2-hwdrill-q71", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>The graph of f is shown. Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">x→−2</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(x) − f(−2)</span><span style=\"padding:0 3px\">x + 2</span></span>.", "img": "seed/img/calc-t3-features.svg", "choices": ["3", "0", "The limit does not exist.", "−2"], "answer": 1, "why": "This limit is f′(−2). The graph has a smooth peak with a horizontal tangent at x = −2, so f′(−2) = 0. (Like 2.3 HW #5c.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q72", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>For the same graph of f, at which x-values on (−4, 4) is f NOT differentiable?", "img": "seed/img/calc-t3-features.svg", "choices": ["x = −2 and x = 0", "x = 2 only", "x = 0 and x = 2", "x = −2, x = 0, and x = 2"], "answer": 2, "why": "x = 0 is a corner (the curve has slope −2 coming in and the line has slope −1 going out). x = 2 has a hole with f(2) plotted somewhere else: a discontinuity. x = −2 is a smooth peak: slope 0 exists."}, {"id": "seed-mcq-calc-u2-hwdrill-q73", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>For the same graph of f, what is the slope of the line tangent to f at x = 3?", "img": "seed/img/calc-t3-features.svg", "choices": ["0", "−2", "−1", "1"], "answer": 2, "why": "Near x = 3 the graph is the straight line from (0, 1) to (4, −3), so the slope is (−3 − 1)/(4 − 0) = −1."}, {"id": "seed-mcq-calc-u2-hwdrill-q74", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>f(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>kx²</span><span>x ≤ 2</span><span>4x − 4</span><span>x > 2</span></span></span>. For what value of k is f differentiable at x = 2?", "img": null, "choices": ["There is no such k.", "k = 1/2", "k = 1", "k = 2"], "answer": 2, "why": "Continuity: 4k = 4(2) − 4 = 4 ⇒ k = 1. Check slopes with k = 1: 2kx = 4 at x = 2, and the right side has slope 4 ✓. So k = 1 works."}, {"id": "seed-mcq-calc-u2-hwdrill-q75", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3</small><br>A continuous function f has f(2) = 2 and f′(2) = 5. Let h(x) = <span style=\"display:inline-flex;align-items:center;vertical-align:middle\"><span style=\"font-size:2.3em;font-weight:200;line-height:1\">{</span><span style=\"display:inline-grid;grid-template-columns:auto auto;column-gap:16px;line-height:1.5\"><span>3x − 4</span><span>x ≤ 2</span><span>f(x)</span><span>x > 2</span></span></span>. Which is true at x = 2?", "img": null, "choices": ["h is differentiable and h′(2) = 3", "h is not continuous", "h is differentiable", "h is continuous but not differentiable"], "answer": 3, "why": "Continuity: 3(2) − 4 = 2 = f(2) ✓. Slopes: left 3, right f′(2) = 5. They do not match, so h is continuous but not differentiable. (Like 2.3 HW #6.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q76", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>If f(x) = 5x⁴ − 2/x³ + 7, then f′(x) =", "img": null, "choices": ["20x³ − 6/x²", "20x³ + 6/x⁴", "20x³ − 6/x⁴", "20x³ + 6/x² + 7"], "answer": 1, "why": "Rewrite −2/x³ = −2x^(−3). Its derivative is −2(−3)x^(−4) = +6/x⁴. The constant 7 becomes 0."}, {"id": "seed-mcq-calc-u2-hwdrill-q77", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>Let f(x) = 3x^(2/3) − x. Evaluate lim x→8 (f(x) − f(8))/(x − 8).", "img": null, "choices": ["0", "2", "−1", "1"], "answer": 0, "why": "The limit is f′(8). f′(x) = 2x^(−1/3) − 1, and 8^(−1/3) = 1/2, so f′(8) = 2(1/2) − 1 = 0. (Like 2.4 HW #5.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q78", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>At which x-values is the tangent line to f(x) = x³ − 3x parallel to y = 9x − 1?", "img": null, "choices": ["x = −√3 and x = √3", "x = −2 and x = 2", "x = 0 and x = 3", "x = 2 only"], "answer": 1, "why": "Parallel ⇒ same slope 9. f′(x) = 3x² − 3 = 9 ⇒ x² = 4 ⇒ x = ±2."}, {"id": "seed-mcq-calc-u2-hwdrill-q79", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>A particle has position s(t) = 2t³ − 6t. At what time t in [0, 2] does its instantaneous velocity equal its average velocity on [0, 2]?", "img": null, "choices": ["t = √2", "t = 4/3", "t = 2/√3", "t = 1"], "answer": 2, "why": "Average velocity = (s(2) − s(0))/2 = (4 − 0)/2 = 2. v(t) = s′(t) = 6t² − 6. Set 6t² − 6 = 2 ⇒ t² = 4/3 ⇒ t = 2/√3 ≈ 1.15."}, {"id": "seed-mcq-calc-u2-hwdrill-q80", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4</small><br>A differentiable function f has f′(3) = 6. Let g(x) = −2f(x − 1) + 4. What is g′(4)?", "img": null, "choices": ["−8", "−12", "−2", "12"], "answer": 1, "why": "g′(x) = −2f′(x − 1) (the +4 does not affect slopes). g′(4) = −2f′(3) = −12. (Like 2.4 HW #7.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q81", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5</small><br>Which is an equation of the line tangent to f(x) = 3x + cos x at x = π/2?", "img": null, "choices": ["y = 2(x − π/2)", "y − 3π/2 = 4(x − π/2)", "y − 3π/2 = 2(x − π/2)", "y − 3π/2 = 3(x − π/2)"], "answer": 2, "why": "Point: f(π/2) = 3π/2 + 0. Slope: f′(x) = 3 − sin x, so f′(π/2) = 3 − 1 = 2."}, {"id": "seed-mcq-calc-u2-hwdrill-q82", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5</small><br>Let g(x) = 5 cos x. On which interval is g′(x) > 0?", "img": null, "choices": ["(0, π)", "(−π/2, π/2)", "(π/2, 3π/2)", "(π, 2π)"], "answer": 3, "why": "g′(x) = −5 sin x > 0 when sin x < 0, which happens on (π, 2π)."}, {"id": "seed-mcq-calc-u2-hwdrill-q83", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5</small><br>Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">h→0</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">4 sin(π/6 + h) − 2</span><span style=\"padding:0 3px\">h</span></span>.", "img": null, "choices": ["−2√3", "√3/2", "2√3", "2"], "answer": 2, "why": "4 sin(π/6) = 2, so this is f′(π/6) for f(x) = 4 sin x. f′(x) = 4 cos x, so 4 cos(π/6) = 4(√3/2) = 2√3."}, {"id": "seed-mcq-calc-u2-hwdrill-q84", "stem": "<small style=\"color:var(--mut)\">Lesson 2.5</small><br>The line y = −3x + 3π/2 is tangent to the graph of f at x = a. Which correctly identifies f and a?", "img": null, "choices": ["f(x) = −3 sin x and a = 0", "f(x) = 3 sin x and a = π", "f(x) = −3 cos x and a = 3π/2", "f(x) = 3 cos x and a = π/2"], "answer": 3, "why": "Check point AND slope. f(π/2) = 3 cos(π/2) = 0, and the line at π/2 is −3π/2 + 3π/2 = 0 ✓. f′(x) = −3 sin x, so f′(π/2) = −3 ✓. The others have slope −3 but their tangent point is not on this line. (Like 2.5 HW #11.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q85", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6</small><br>If f(x) = 2eˣ − 3 ln x + 2ˣ, then f′(1) =", "img": null, "choices": ["2 − 3 + 2 ln 2", "2e − 3 + 2 ln 2", "2e + 3 + 2 ln 2", "2e − 3 + 2"], "answer": 1, "why": "f′(x) = 2eˣ − 3/x + 2ˣ ln 2. At x = 1: 2e − 3 + 2 ln 2."}, {"id": "seed-mcq-calc-u2-hwdrill-q86", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6</small><br>The line −2x + 6y = k is tangent to y = ln x. What is k?", "img": null, "choices": ["−2 + 6 ln 3", "6 ln 3", "−6 + 6 ln 3", "−6 + 6 ln 2"], "answer": 2, "why": "The line is y = x/3 + k/6, slope 1/3. Set 1/x = 1/3 ⇒ x = 3, point (3, ln 3). Plug in: k = −2(3) + 6 ln 3 = −6 + 6 ln 3. (Like 2.6 Notes #5.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q87", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6</small><br>Let f(x) = ln x and let h be a positive constant. Which is true?", "img": null, "choices": ["f(2 + h) > f(2) and f′(2) > f′(2 + h)", "f(2 + h) = f(2) + h", "f(2 + h) > f(2) and f′(2) < f′(2 + h)", "f(2 + h) < f(2) and f′(2) > f′(2 + h)"], "answer": 0, "why": "ln x is always increasing, so f(2 + h) > f(2). f′(x) = 1/x shrinks as x grows, so 1/2 > 1/(2 + h). The graph keeps rising but flattens. (Like 2.6 HW #9.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q88", "stem": "<small style=\"color:var(--mut)\">Lesson 2.6</small><br>Evaluate lim x→e² (ln x − 2)/(x − e²).", "img": null, "choices": ["1/2", "e²", "1/e²", "0"], "answer": 2, "why": "ln(e²) = 2, so this is f′(e²) for f(x) = ln x. f′(x) = 1/x, giving 1/e²."}, {"id": "seed-mcq-calc-u2-hwdrill-q89", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7</small><br>The table gives values of f. Let g(x) = −f(x)(x² + 1). What is g′(1)?<table style=\"border-collapse:collapse;margin:8px 0\"><tr><th style=\"border:1px solid currentColor;padding:3px 10px\">x</th><th style=\"border:1px solid currentColor;padding:3px 10px\">f(x)</th><th style=\"border:1px solid currentColor;padding:3px 10px\">f′(x)</th></tr><tr><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">1</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">3</td><td style=\"border:1px solid currentColor;padding:3px 10px;text-align:center\">−2</td></tr></table>", "img": null, "choices": ["2", "−10", "−2", "4"], "answer": 2, "why": "Product rule with the minus sign out front: g′(x) = −[f′(x)(x² + 1) + f(x)(2x)]. At x = 1: −[(−2)(2) + (3)(2)] = −[−4 + 6] = −2. (Like 2.7 HW #5.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q90", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7</small><br>What is the slope of the line tangent to y = √x(2x + 1) at x = 4?", "img": null, "choices": ["9/4", "4", "18", "25/4"], "answer": 3, "why": "Product rule: y′ = (1/(2√x))(2x + 1) + √x·2. At x = 4: (1/4)(9) + 2(2) = 9/4 + 4 = 25/4. (Like 2.7 HW #10.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q91", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7</small><br>f is an even, differentiable function that is positive and increasing for all x > 0. A function g has g(−2) = −3 and g′(−2) = 1. Let h(x) = f(x)g(x). Which is true?", "img": null, "choices": ["h′(−2) = 0", "h′(−2) < 0", "h′(−2) > 0", "There is not enough information."], "answer": 2, "why": "Even ⇒ the graph is a mirror image across the y-axis, so for x < 0, f is positive and DECREASING: f(−2) > 0 and f′(−2) < 0. h′(−2) = f′(−2)g(−2) + f(−2)g′(−2) = (−)(−) + (+)(+) > 0. (Like 2.7 HW #8.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q92", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7</small><br>f(x) = (3x² − ax)·g(x), where a is a constant, g(1) = 2, and g′(1) = −1. If f′(1) = 4, what is a?", "img": null, "choices": ["9", "3", "−5", "5"], "answer": 3, "why": "f′(x) = (6x − a)g(x) + (3x² − ax)g′(x). At x = 1: (6 − a)(2) + (3 − a)(−1) = 12 − 2a − 3 + a = 9 − a. Set 9 − a = 4 ⇒ a = 5. (Like 2.7 HW #7.)"}, {"id": "seed-mcq-calc-u2-hwdrill-q93", "stem": "<small style=\"color:var(--mut)\">Lesson 2.7</small><br>Let f(x) = eˣ sin x. For what x in [0, π] does the instantaneous rate of change of f equal the average rate of change of f on [0, π]?", "img": null, "choices": ["x = 3π/4", "x = π/4", "x = π/2", "x = π"], "answer": 0, "why": "Average rate = (f(π) − f(0))/π = (0 − 0)/π = 0. f′(x) = eˣ sin x + eˣ cos x = eˣ(sin x + cos x) = 0 ⇒ tan x = −1 ⇒ x = 3π/4. (Like 2.7 HW #4.)"}, {"id": "seed-mcq-calc-u2-hwdrill-28-q0", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>If f(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">eˣ</span><span style=\"padding:0 3px\">x² + 1</span></span>, then f′(x) =", "img": null, "choices": ["eˣ / (2x)", "eˣ(x − 1)² / (x² + 1)²", "[eˣ(x² + 1) + 2xeˣ] / (x² + 1)²", "eˣ(x² − 2x + 1) / (x² + 1)"], "answer": 1, "why": "Quotient rule: [eˣ(x² + 1) − eˣ(2x)] / (x² + 1)². Factor eˣ from the top: eˣ(x² − 2x + 1) = eˣ(x − 1)². Traps: f′/g′ = eˣ/(2x), a PLUS in the middle, or forgetting to square the bottom. (Like 2.8 HW #1.)"}, {"id": "seed-mcq-calc-u2-hwdrill-28-q1", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>Let f(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">x² + 4x</span><span style=\"padding:0 3px\">x²</span></span>. What is f′(x)?", "img": null, "choices": ["(2x + 4)/(2x)", "1 + 4/x", "4/x²", "−4/x²"], "answer": 3, "why": "The bottom is a single term, so split first: f(x) = x²/x² + 4x/x² = 1 + 4x⁻¹. Power rule: f′(x) = −4x⁻² = −4/x². (The quotient rule gives the same answer, just with more work.) (Like 2.8 HW #2.)"}, {"id": "seed-mcq-calc-u2-hwdrill-28-q2", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>If <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">d</span><span style=\"padding:0 3px\">dx</span></span>(<span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(x)</span><span style=\"padding:0 3px\">sin x</span></span>) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">3x² sin x − x³ cos x</span><span style=\"padding:0 3px\">sin² x</span></span>, then f(x) could be", "img": null, "choices": ["x³", "3x²", "−x³", "x³ cos x"], "answer": 0, "why": "Match the quotient rule pattern [f′·g − f·g′]/g² with g = sin x, g′ = cos x. The first term of the top is f′·sin x = 3x² sin x, so f′ = 3x². The second term is f·cos x = x³ cos x, so f = x³. Check: (x³)′ = 3x² ✓. (Like 2.8 HW #3.)"}, {"id": "seed-mcq-calc-u2-hwdrill-28-q3", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>Let g(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">2 ln x</span><span style=\"padding:0 3px\">f(x)</span></span>, where f(e) = 2 and f′(e) = 6. What is g′(e)?", "img": null, "choices": ["1/e + 3", "1/e − 3", "1/(3e)", "4/e − 12"], "answer": 1, "why": "Quotient rule: g′ = [(2/x)·f(x) − 2 ln x·f′(x)] / [f(x)]². At x = e: [(2/e)(2) − 2(1)(6)] / 2² = (4/e − 12)/4 = 1/e − 3. Remember ln e = 1, and divide the WHOLE top by 4. (Like 2.8 HW #4.)"}, {"id": "seed-mcq-calc-u2-hwdrill-28-q4", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>Let h(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">x</span><span style=\"padding:0 3px\">2 cos x</span></span>. Evaluate <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.1;margin-right:3px\">lim<small style=\"font-size:11px\">x→π</small></span><span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">h(x) − h(π)</span><span style=\"padding:0 3px\">x − π</span></span>.", "img": null, "choices": ["The limit does not exist.", "1/2", "−1/2", "0"], "answer": 2, "why": "This limit is h′(π) (Definition 2). Quotient rule: h′ = [1·2cos x − x·(−2 sin x)] / (2cos x)² = (2cos x + 2x sin x)/(4cos² x). At π: (2(−1) + 0)/(4·1) = −1/2. (Like 2.8 HW #5.)"}, {"id": "seed-mcq-calc-u2-hwdrill-28-q5", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>f is differentiable with f(3) = 2 and f′(3) = 0. Let h(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">f(x)</span><span style=\"padding:0 3px\">13 − 2x</span></span>. Which is true about h′(3)?", "img": null, "choices": ["It cannot be determined.", "h′(3) > 0", "h′(3) < 0", "h′(3) = 0"], "answer": 1, "why": "h′(3) = [f′(3)(13 − 6) − f(3)(−2)] / (13 − 6)² = [0·7 + 4] / 49 = 4/49 > 0. f′(3) = 0 does NOT make h′(3) = 0, because the bottom also changes. (Like 2.8 HW #6.)"}, {"id": "seed-mcq-calc-u2-hwdrill-28-q6", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>At what x-values does y = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">x²</span><span style=\"padding:0 3px\">eˣ</span></span> have a horizontal tangent line?", "img": null, "choices": ["x = 0 only", "x = 2 only", "x = −2 and x = 0", "x = 0 and x = 2"], "answer": 3, "why": "y′ = [2x·eˣ − x²·eˣ] / (eˣ)² = eˣ(2x − x²)/e²ˣ = (2x − x²)/eˣ = x(2 − x)/eˣ. A fraction is 0 when its TOP is 0, and eˣ is never 0: x = 0 or x = 2. (Like 2.8 HW #7.)"}, {"id": "seed-mcq-calc-u2-hwdrill-28-q7", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>Let f(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">x</span><span style=\"padding:0 3px\">x − 6</span></span>. For which values of c is the line 3x + 8y = c tangent to the graph of f?", "img": null, "choices": ["c = 2 and c = 50", "c = 2 only", "c = 10 and c = 2", "c = 50 only"], "answer": 0, "why": "Line: y = −(3/8)x + c/8, slope −3/8. f′(x) = [(x − 6) − x]/(x − 6)² = −6/(x − 6)². Set −6/(x − 6)² = −3/8 ⇒ (x − 6)² = 16 ⇒ x = 10 or x = 2. Points: (10, 5/2) and (2, −1/2). c = 3x + 8y: 30 + 20 = 50 and 6 − 4 = 2. (10 and 2 are the x-values, not c.) (Like 2.8 HW #8.)"}, {"id": "seed-mcq-calc-u2-hwdrill-28-q8", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>Let h(x) = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">g(x)</span><span style=\"padding:0 3px\">f(x)</span></span>. At x = −4: f(−4) = b, f′(−4) = 3, g(−4) = −2b, g′(−4) = 5, where b ≠ 0. What is h′(−4)?", "img": null, "choices": ["5/3", "−1/b", "11/b", "−11/b"], "answer": 2, "why": "The TOP of h is g, so start with g′: h′ = [g′f − g f′]/f² = [5·b − (−2b)(3)]/b² = (5b + 6b)/b² = 11b/b² = 11/b. Starting with f′ instead flips the sign (−11/b). (Like 2.8 HW #9.)"}, {"id": "seed-mcq-calc-u2-hwdrill-28-q9", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>Which is an equation of the line tangent to y = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">x − 4</span><span style=\"padding:0 3px\">x² + 2</span></span> at x = 1?", "img": null, "choices": ["y + 1 = 1(x − 1)", "y + 1 = −1(x − 1)", "y + 1 = (1/3)(x − 1)", "y − 1 = 1(x + 1)"], "answer": 0, "why": "Point: y(1) = (1 − 4)/(1 + 2) = −1, so (1, −1). Slope: y′ = [1·(x² + 2) − (x − 4)(2x)] / (x² + 2)². At 1: [3 − (−3)(2)]/9 = 9/9 = 1. Line: y + 1 = 1(x − 1). (Like 2.8 HW #10.)"}, {"id": "seed-mcq-calc-u2-hwdrill-28-q10", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>f(2) = 3, f′(2) = −1, g(2) = 2 and g′(2) = 4. If h(x) = f(x)/g(x), what is h′(2)?", "img": null, "choices": ["−7", "−1/4", "7/2", "−7/2"], "answer": 3, "why": "h′(2) = [f′g − fg′]/g² = [(−1)(2) − (3)(4)] / 2² = (−2 − 12)/4 = −7/2. Traps: f′/g′ = −1/4; reversing the top gives +7/2; forgetting to square the bottom gives −7."}, {"id": "seed-mcq-calc-u2-hwdrill-28-q11", "stem": "<small style=\"color:var(--mut)\">Lesson 2.8</small><br>If y = <span style=\"display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.25;margin:0 2px\"><span style=\"border-bottom:1.5px solid currentColor;padding:0 3px\">sin x</span><span style=\"padding:0 3px\">x</span></span>, then dy/dx =", "img": null, "choices": ["cos x", "(sin x − x cos x) / x²", "(x cos x − sin x) / x²", "(x cos x + sin x) / x²"], "answer": 2, "why": "Quotient rule with top sin x and bottom x: [cos x · x − sin x · 1] / x². Low d-high (x cos x) MINUS high d-low (sin x), over x²."}]}, {"id": "seed-mcq-java-u2-mock", "rev": 1, "kind": "mcq", "title": "AP CSA Unit 2 — Mock Test (60 questions)", "folder": "AP CSA", "description": "55 multiple-choice + 5 free-response questions covering Unit 2 Practices 1–4: parameters and returns, signatures and overloading, objects and references, and Strings. Lesson 2.1–2.4 = Practice 1–4, so you can drill one practice at a time. Every code question was compiled and run with Java to confirm the answer.", "cards": [], "questions": [{"id": "seed-mcq-java-u2-mock-q0", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · code tracing · medium</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    int a = 4;\n    int b = 9;\n    swap(a, b);\n    System.out.println(a + \" \" + b);\n}\n\npublic static void swap(int a, int b) {\n    int temp = a;\n    a = b;\n    b = temp;\n    System.out.println(a + \" \" + b);\n}</pre>", "img": null, "choices": ["9 4\n4 9", "4 9\n4 9", "9 4\n9 4", "4 9\n9 4"], "answer": 0, "why": "swap gets COPIES of a and b. It swaps its own copies and prints 9 4, but main's a and b never change, so main prints 4 9. Java is pass-by-value."}, {"id": "seed-mcq-java-u2-mock-q1", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · code tracing · hard</small><br>mystery both prints and returns. What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    int x = mystery(3);\n    int y = mystery(x) + mystery(1);\n    System.out.println(x + y);\n}\n\npublic static int mystery(int n) {\n    System.out.print(n + \" \");\n    return n * 2;\n}</pre>", "img": null, "choices": ["3 6 1 20", "3 6 1 14", "3 6 1 614", "6 12 2 20"], "answer": 0, "why": "mystery(3) prints \"3 \" and returns 6, so x = 6. mystery(6) prints \"6 \" and returns 12; mystery(1) prints \"1 \" and returns 2; y = 14. Last line prints x + y = 6 + 14 = 20 (both ints, so it is addition, not \"614\")."}, {"id": "seed-mcq-java-u2-mock-q2", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · code tracing · hard</small><br>Notice the parameter names. What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    int x = 2, y = 5, z = 8;\n    order(z, x, y);\n    order(y, z + x, x * y);\n}\n\npublic static void order(int y, int z, int x) {\n    System.out.println(x + \" \" + y + \" \" + z);\n}</pre>", "img": null, "choices": ["2 5 8\n5 10 10", "5 8 2\n10 10 5", "5 8 2\n10 5 10", "8 2 5\n5 10 10"], "answer": 2, "why": "Arguments are matched by POSITION, not by name. order(z, x, y) = order(8, 2, 5), so the parameter y = 8, z = 2, x = 5 and it prints x y z = 5 8 2. order(y, z + x, x * y) = order(5, 10, 10): y = 5, z = 10, x = 10, so it prints 10 5 10."}, {"id": "seed-mcq-java-u2-mock-q3", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · code tracing · very hard</small><br>Track every variable carefully. What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    int a = 3, b = 7;\n    b = calc(b, a);\n    a = calc(a, b);\n    System.out.println(a + \" \" + b);\n}\n\npublic static int calc(int b, int a) {\n    a = a + b;\n    b = a / 2;\n    System.out.print(b + \" \");\n    return a - b;\n}</pre>", "img": null, "choices": ["10 8 4 5", "5 4 3 7", "5 4 5 4", "5 4 4 5"], "answer": 3, "why": "calc(b, a) = calc(7, 3): the PARAMETER b = 7 and a = 3. a = 10, b = 5, prints \"5 \", returns 10 − 5 = 5, so main's b = 5. calc(a, b) = calc(3, 5): b = 3, a = 5, then a = 8, b = 4, prints \"4 \", returns 4, so main's a = 4. Finally prints a b = 4 5."}, {"id": "seed-mcq-java-u2-mock-q4", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · code tracing · hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">System.out.println(Math.max(Math.abs(-7), Math.min(3, -10)) + Math.pow(2, 3));</pre>", "img": null, "choices": ["-2.0", "15.0", "78.0", "15"], "answer": 1, "why": "Inside out: Math.abs(-7) = 7 and Math.min(3, -10) = -10, so Math.max(7, -10) = 7. Math.pow(2, 3) returns the DOUBLE 8.0. 7 + 8.0 = 15.0 (int + double is a double). No String is involved, so nothing is concatenated."}, {"id": "seed-mcq-java-u2-mock-q5", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · code tracing · very hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    System.out.println(avg(7, 4));\n    System.out.println(avg(7, 4) * 2);\n}\n\npublic static double avg(int a, int b) {\n    return (a + b) / 2;\n}</pre>", "img": null, "choices": ["5.0\n11.0", "5\n10", "5.0\n10.0", "5.5\n11.0"], "answer": 2, "why": "(a + b) / 2 is int / int = 11 / 2 = 5. Only THEN is 5 converted to the double return type, giving 5.0. So avg(7, 4) * 2 = 10.0. The return type does not make the division a decimal division; you would need / 2.0."}, {"id": "seed-mcq-java-u2-mock-q6", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · code tracing · hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    int n = 4;\n    triple(n);\n    System.out.println(\"out: \" + n);\n    n = triple(n + 1);\n    System.out.println(\"out: \" + n);\n}\n\npublic static int triple(int n) {\n    n = n * 3;\n    System.out.println(\"in: \" + n);\n    return n;\n}</pre>", "img": null, "choices": ["in: 12\nout: 12\nin: 39\nout: 39", "in: 12\nout: 4\nin: 13\nout: 13", "in: 12\nout: 4\nin: 15\nout: 15", "in: 12\nout: 4\nin: 15\nout: 4"], "answer": 2, "why": "The first call's return value (12) is thrown away, and changing the parameter n does not change main's n, so main still prints 4. The second call passes 5 and the result IS stored: n = 15."}, {"id": "seed-mcq-java-u2-mock-q7", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · code tracing · hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    System.out.println(f(2) + f(3) + \"=\" + f(2) + f(3));\n}\n\npublic static int f(int x) {\n    return x * x;\n}</pre>", "img": null, "choices": ["13=13", "13=49", "4913=49", "49=49"], "answer": 1, "why": "Left to right: f(2) + f(3) = 4 + 9 = 13 (still numbers). 13 + \"=\" = \"13=\". From now on + means join: \"13=\" + 4 = \"13=4\", then + 9 = \"13=49\"."}, {"id": "seed-mcq-java-u2-mock-q8", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · code tracing · very hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    System.out.println(b(a(1)));\n}\n\npublic static int a(int n) {\n    System.out.print(\"a\" + n + \" \");\n    return n + 1;\n}\n\npublic static int b(int n) {\n    System.out.print(\"b\" + n + \" \");\n    return a(n * 2) + a(n);\n}</pre>", "img": null, "choices": ["a1 b2 a4 a2 8", "a1 b2 a4 a2 7", "a1 b2 a2 a4 8", "b2 a1 a4 a2 8"], "answer": 0, "why": "The innermost call runs first: a(1) prints \"a1 \" and returns 2. b(2) prints \"b2 \", then evaluates a(4) + a(2) left to right: \"a4 \" (returns 5), \"a2 \" (returns 3). b returns 8, and println prints 8 last."}, {"id": "seed-mcq-java-u2-mock-q9", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · code tracing · medium</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">int d = Math.abs(3 - 10);\nint m = Math.min(d, 5) * 2;\nSystem.out.println(d + m);</pre>", "img": null, "choices": ["24", "710", "17", "12"], "answer": 2, "why": "d = Math.abs(3 - 10) = 7. Math.min(7, 5) = 5, times 2 = 10. d + m = 7 + 10 = 17 (int addition, not concatenation)."}, {"id": "seed-mcq-java-u2-mock-q10", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · code tracing · hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    int total = 0;\n    for (int k = 1; k &lt;= 3; k++) {\n        total += sumTo(k);\n    }\n    System.out.println(total + \" \" + sumTo(total / 4));\n}\n\npublic static int sumTo(int n) {\n    int sum = 0;\n    for (int i = 1; i &lt;= n; i++) {\n        sum += i;\n    }\n    return sum;\n}</pre>", "img": null, "choices": ["10 6", "6 3", "10 10", "10 3"], "answer": 3, "why": "sumTo(1) + sumTo(2) + sumTo(3) = 1 + 3 + 6, so total = 10. total / 4 = 10 / 4 = 2 (integer division), and sumTo(2) = 3."}, {"id": "seed-mcq-java-u2-mock-q11", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · code tracing · hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    stars(3, \"ab\");\n    stars(2 * 2 - 3, \"*\" + 1);\n    stars(1 + 1, \"-\");\n}\n\npublic static void stars(int n, String s) {\n    for (int i = 0; i &lt; n; i++) {\n        System.out.print(s);\n    }\n    System.out.println();\n}</pre>", "img": null, "choices": ["aaabbb\n*1\n--", "ababab\n**\n--", "ababab\n*1*1*1*1\n--", "ababab\n*1\n--"], "answer": 3, "why": "stars(3, \"ab\") prints \"ab\" 3 times. 2 * 2 - 3 = 1 and \"*\" + 1 = \"*1\", so the second line is \"*1\" printed once. 1 + 1 = 2, so the third line is \"--\"."}, {"id": "seed-mcq-java-u2-mock-q12", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · code tracing · medium</small><br>Using the Counter class shown below: What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">class Counter {\n    private int count;\n    public Counter() { count = 0; }\n    public Counter(int start) { count = start; }\n    public void add(int n) { count += n; }\n    public int getCount() { return count; }\n}\n\nCounter c1 = new Counter(5);\nCounter c2 = c1;\nc2.add(3);\nSystem.out.println(c1.getCount() + \" \" + c2.getCount());</pre>", "img": null, "choices": ["5 3", "8 3", "5 8", "8 8"], "answer": 3, "why": "c2 = c1 copies the REFERENCE, so both variables point to the same Counter. Adding 3 through c2 changes that one object, so both print 8."}, {"id": "seed-mcq-java-u2-mock-q13", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · code tracing · hard</small><br>Using the Counter class shown below: What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">class Counter {\n    private int count;\n    public Counter() { count = 0; }\n    public Counter(int start) { count = start; }\n    public void add(int n) { count += n; }\n    public int getCount() { return count; }\n}\n\nCounter a = new Counter(2);\nCounter b = a;\nb = new Counter(10);\nb.add(1);\na.add(4);\nSystem.out.println(a.getCount() + \" \" + b.getCount());</pre>", "img": null, "choices": ["6 15", "2 15", "17 17", "6 11"], "answer": 3, "why": "b = new Counter(10) REASSIGNS b to a brand-new object; a still points to the original Counter(2). So b.add(1) makes b 11, and a.add(4) makes a 6."}, {"id": "seed-mcq-java-u2-mock-q14", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · code tracing · very hard</small><br>Using the Counter class shown below: What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">class Counter {\n    private int count;\n    public Counter() { count = 0; }\n    public Counter(int start) { count = start; }\n    public void add(int n) { count += n; }\n    public int getCount() { return count; }\n}\n\npublic static void main(String[] args) {\n    Counter x = new Counter(7);\n    reset(x);\n    System.out.println(x.getCount());\n}\n\npublic static void reset(Counter c) {\n    c.add(1);\n    c = new Counter();\n    c.add(100);\n}</pre>", "img": null, "choices": ["108", "8", "7", "100"], "answer": 1, "why": "c starts as a copy of x's reference, so c.add(1) MUTATES x's object (now 8). Then c = new Counter() only changes the method's copy of the reference; add(100) affects the new object, which is discarded. x still shows 8."}, {"id": "seed-mcq-java-u2-mock-q15", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · code tracing · very hard</small><br>Using the Counter class shown below: How many Counter objects are created, and what does r.getCount() return after this code runs?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">class Counter {\n    private int count;\n    public Counter() { count = 0; }\n    public Counter(int start) { count = start; }\n    public void add(int n) { count += n; }\n    public int getCount() { return count; }\n}\n\nCounter p = new Counter();\nCounter q = new Counter(3);\nCounter r = q;\nq = p;\np = new Counter(q.getCount());\nCounter s;</pre>", "img": null, "choices": ["4 objects; r.getCount() returns 3", "5 objects; r.getCount() returns 0", "3 objects; r.getCount() returns 0", "3 objects; r.getCount() returns 3"], "answer": 3, "why": "Count the times \"new\" runs: new Counter(), new Counter(3), new Counter(q.getCount()) = 3. r = q and q = p only copy references, and \"Counter s;\" only declares a variable. r still points to the Counter(3) object."}, {"id": "seed-mcq-java-u2-mock-q16", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · code tracing · hard</small><br>Using the Counter class shown below: What happens when this code runs?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">class Counter {\n    private int count;\n    public Counter() { count = 0; }\n    public Counter(int start) { count = start; }\n    public void add(int n) { count += n; }\n    public int getCount() { return count; }\n}\n\nCounter a = new Counter(1);\nCounter b = a;\na = null;\nb.add(2);\nSystem.out.println(b.getCount());</pre>", "img": null, "choices": ["It prints 1", "It prints 3", "NullPointerException at b.add(2)", "It prints 2"], "answer": 1, "why": "a = null only changes the variable a. b still refers to the Counter object, so b.add(2) works and prints 3. A NullPointerException only happens when you call a method THROUGH a null reference (a.add(2) here would throw)."}, {"id": "seed-mcq-java-u2-mock-q17", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · code tracing · very hard</small><br>Using the Counter class shown below: What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">class Counter {\n    private int count;\n    public Counter() { count = 0; }\n    public Counter(int start) { count = start; }\n    public void add(int n) { count += n; }\n    public int getCount() { return count; }\n}\n\npublic static void main(String[] args) {\n    Counter a = new Counter(4);\n    Counter b = new Counter(6);\n    Counter c = combine(a, b);\n    c.add(1);\n    System.out.println(a.getCount() + \" \" + b.getCount() + \" \" + c.getCount());\n}\n\npublic static Counter combine(Counter x, Counter y) {\n    x.add(y.getCount());\n    return y;\n}</pre>", "img": null, "choices": ["10 6 7", "4 7 7", "11 6 11", "10 7 7"], "answer": 3, "why": "combine mutates x (a's object): 4 + 6 = 10. It returns y, which is a reference to b's object, so c and b are the same Counter. c.add(1) makes that object 7, seen through both b and c."}, {"id": "seed-mcq-java-u2-mock-q18", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · code tracing · hard</small><br>Using the Counter class shown below: What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">class Counter {\n    private int count;\n    public Counter() { count = 0; }\n    public Counter(int start) { count = start; }\n    public void add(int n) { count += n; }\n    public int getCount() { return count; }\n}\n\nCounter c = new Counter(1);\nfor (int i = 0; i &lt; 3; i++) {\n    c.add(c.getCount());\n}\nSystem.out.println(c.getCount());</pre>", "img": null, "choices": ["16", "7", "4", "8"], "answer": 3, "why": "Each pass adds the CURRENT count to itself (doubling): 1 → 2 → 4 → 8. getCount() is called fresh every time through the loop."}, {"id": "seed-mcq-java-u2-mock-q19", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · code tracing · very hard</small><br>Using the Counter class shown below: What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">class Counter {\n    private int count;\n    public Counter() { count = 0; }\n    public Counter(int start) { count = start; }\n    public void add(int n) { count += n; }\n    public int getCount() { return count; }\n}\n\npublic static void main(String[] args) {\n    Counter x = new Counter(1);\n    Counter y = new Counter(2);\n    swap(x, y);\n    System.out.println(x.getCount() + \" \" + y.getCount());\n}\n\npublic static void swap(Counter a, Counter b) {\n    Counter t = a;\n    a = b;\n    b = t;\n    a.add(10);\n}</pre>", "img": null, "choices": ["12 1", "11 2", "1 12", "2 11"], "answer": 2, "why": "Swapping the parameters only swaps the method's COPIES of the references; x and y in main are untouched. But after the swap, a refers to y's object, so a.add(10) mutates y's Counter: 2 + 10 = 12."}, {"id": "seed-mcq-java-u2-mock-q20", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · code tracing · hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">String s = \"computer\";\ns.substring(3);\nString t = s.substring(1, 4) + s.length();\nSystem.out.println(s + \" \" + t);</pre>", "img": null, "choices": ["computer ompu8", "computer comp8", "computer omp8", "puter ute5"], "answer": 2, "why": "s.substring(3); creates \"puter\" and throws it away, because Strings are immutable and the result was not assigned. s is still \"computer\". substring(1, 4) is indexes 1, 2, 3 = \"omp\" (end excluded), and length is 8."}, {"id": "seed-mcq-java-u2-mock-q21", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · code tracing · very hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    String w = \"java\";\n    String r = change(w);\n    System.out.println(w + \" \" + r + \" \" + change(r));\n}\n\npublic static String change(String s) {\n    s = s.substring(1) + s.substring(0, 1);\n    return s.substring(0, 2);\n}</pre>", "img": null, "choices": ["java avaj va", "java av va", "avaj av va", "java av av"], "answer": 1, "why": "change(\"java\"): s becomes \"ava\" + \"j\" = \"avaj\" (only the local copy), returns \"av\". w is still \"java\". change(\"av\"): s becomes \"v\" + \"a\" = \"va\", returns its first two characters, \"va\"."}, {"id": "seed-mcq-java-u2-mock-q22", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · code tracing · very hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">int a = 3, b = 4;\nString s = a + b + \"\" + a + b;\nSystem.out.println(s + (a + b) + s.length());</pre>", "img": null, "choices": ["73473", "343474", "734343", "73474"], "answer": 0, "why": "Line 2, left to right: a + b = 7, then 7 + \"\" = \"7\", + a = \"73\", + b = \"734\". Line 3: \"734\" + (a + b) adds the parentheses first, giving \"7347\", then + s.length() (3) gives \"73473\"."}, {"id": "seed-mcq-java-u2-mock-q23", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · code tracing · hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">String s = \"abcdefgh\";\ns = s.substring(2, 7);\ns = s.substring(s.length() / 2) + s.substring(0, 1);\nSystem.out.println(s + \" \" + s.length());</pre>", "img": null, "choices": ["efgc 4", "fgc 3", "efghc 5", "defgc 5"], "answer": 0, "why": "\"abcdefgh\".substring(2, 7) is indexes 2 to 6 = \"cdefg\" (length 5). 5 / 2 = 2, so substring(2) = \"efg\", plus substring(0, 1) = \"c\", giving \"efgc\", which has length 4."}, {"id": "seed-mcq-java-u2-mock-q24", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · code tracing · medium</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">String a = \"cat\";\nString b = a;\na = a + \"s\";\nb = b.substring(1);\nSystem.out.println(a + \" \" + b);</pre>", "img": null, "choices": ["cats at", "cats ats", "ats ats", "cat at"], "answer": 0, "why": "b = a makes both refer to \"cat\". a = a + \"s\" builds a NEW String \"cats\" for a only; b still refers to \"cat\". Then b becomes \"cat\".substring(1) = \"at\"."}, {"id": "seed-mcq-java-u2-mock-q25", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · overloading & signatures · medium</small><br>What is the method signature of this method?<br><code>public static double area(int w, double h)</code>", "img": null, "choices": ["area(int w, double h)", "area(int, double)", "double area(int w, double h)", "public static double area(int, double)"], "answer": 1, "why": "A signature is only the method NAME plus the parameter TYPES in order. The return type, the parameter names, and modifiers like public/static are not part of it."}, {"id": "seed-mcq-java-u2-mock-q26", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · overloading & signatures · hard</small><br>A class already has <code>public static int calc(int a, double b)</code>. Which method can be ADDED to the same class as a valid overload?", "img": null, "choices": ["public static double calc(int x, double y)", "public static int calc(double a, int b)", "public static int calc(int b, double a)", "private static int calc(int a, double b)"], "answer": 1, "why": "The parameter TYPES must differ in number, type, or order. (double, int) is a different order of types, so it is valid. Changing only the return type, only the parameter names, or only the access modifier leaves the signature calc(int, double) the same, which is a compile-time error."}, {"id": "seed-mcq-java-u2-mock-q27", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · overloading & signatures · hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    show(5 / 2);\n    show(5 / 2.0);\n    show(\"\" + 5);\n}\n\npublic static void show(int x) { System.out.println(\"int\"); }\npublic static void show(double x) { System.out.println(\"double\"); }\npublic static void show(String x) { System.out.println(\"String\"); }</pre>", "img": null, "choices": ["double\nint\nString", "int\ndouble\nint", "int\ndouble\nString", "double\ndouble\nString"], "answer": 2, "why": "Java picks the overload by the argument's type. 5 / 2 is int / int = an int (2). 5 / 2.0 is a double. \"\" + 5 is the String \"5\"."}, {"id": "seed-mcq-java-u2-mock-q28", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · overloading & signatures · very hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    f(1, 2);\n    f(1.0, 2);\n    f(1, 2.0);\n}\n\npublic static void f(double a, double b) { System.out.println(\"dd\"); }\npublic static void f(int a, double b) { System.out.println(\"id\"); }</pre>", "img": null, "choices": ["id\ndd\nid", "Compile-time error: f(1, 2) is ambiguous", "dd\ndd\nid", "id\nid\nid"], "answer": 0, "why": "f(1, 2): both overloads work (the ints can widen to double), but f(int, double) is MORE SPECIFIC because it needs less widening, so Java picks it. f(1.0, 2): a double can never narrow to int, so only f(double, double) works. f(1, 2.0) matches f(int, double) exactly."}, {"id": "seed-mcq-java-u2-mock-q29", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · overloading & signatures · very hard</small><br>What happens with the call g(3, 4)?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    g(3, 4);\n}\n\npublic static void g(int a, double b) { System.out.println(\"A\"); }\npublic static void g(double a, int b) { System.out.println(\"B\"); }</pre>", "img": null, "choices": ["It prints B", "It prints A", "It compiles, then throws a runtime exception", "Compile-time error: the call is ambiguous"], "answer": 3, "why": "g(int, double) needs the 4 widened; g(double, int) needs the 3 widened. Neither is more specific than the other, so the compiler cannot choose: \"reference to g is ambiguous\". This is a COMPILE-time error, not a runtime one."}, {"id": "seed-mcq-java-u2-mock-q30", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · overloading & signatures · hard</small><br>Given these two methods, which call causes a compile-time error?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static int sum(int a, int b) { return a + b; }\npublic static double sum(double a, double b, double c) { return a + b + c; }</pre>", "img": null, "choices": ["sum(1, 2.5, 3)", "sum(1, 2)", "sum(1.5, 2)", "sum(1, 2, 3)"], "answer": 2, "why": "sum(1.5, 2) has 2 arguments, so only sum(int, int) has the right number, but 1.5 is a double and cannot narrow to int. sum(1, 2, 3) is fine: the ints widen to double for the 3-parameter version."}, {"id": "seed-mcq-java-u2-mock-q31", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · overloading & signatures · hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    System.out.println(half(7) + half(7.0));\n}\n\npublic static int half(int n) { return n / 2; }\npublic static double half(double n) { return n / 2; }</pre>", "img": null, "choices": ["7.0", "6", "33.5", "6.5"], "answer": 3, "why": "half(7) calls the int version: 7 / 2 = 3. half(7.0) calls the double version: 3.5. 3 + 3.5 = 6.5 (addition, since there is no String)."}, {"id": "seed-mcq-java-u2-mock-q32", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · overloading & signatures · very hard</small><br>One overload calls the other. What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    System.out.println(area(3) + area(2, 5));\n}\n\npublic static int area(int s) {\n    return area(s, s);\n}\n\npublic static int area(int w, int h) {\n    System.out.print(\"[\" + w + \"x\" + h + \"] \");\n    return w * h;\n}</pre>", "img": null, "choices": ["[3x3] [2x5] 910", "[3x3] [2x5] 19", "19 [3x3] [2x5]", "[2x5] [3x3] 19"], "answer": 1, "why": "println must evaluate its argument BEFORE printing anything. area(3) calls area(3, 3), which prints \"[3x3] \" and returns 9. Then area(2, 5) prints \"[2x5] \" and returns 10. Only then does println print 9 + 10 = 19."}, {"id": "seed-mcq-java-u2-mock-q33", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · overloading & signatures · medium</small><br>Given these methods, which statement causes a compile-time error?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void printTwice(int n) { System.out.println(n * 2); }\npublic static int twice(int n) { return n * 2; }</pre>", "img": null, "choices": ["int y = printTwice(4);", "int x = twice(4);", "twice(4);", "printTwice(twice(4));"], "answer": 0, "why": "printTwice is void, so it produces no value to store in y. twice(4); on its own line is legal; the returned 8 is simply thrown away."}, {"id": "seed-mcq-java-u2-mock-q34", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · overloading & signatures · hard</small><br>Read this API documentation:<div style=\"border:1px solid var(--line);border-radius:8px;padding:8px 12px;margin:8px 0\"><code>public static int clamp(int value, int low, int high)</code><br>Returns <code>value</code> if it is between <code>low</code> and <code>high</code> (inclusive). Returns <code>low</code> if <code>value &lt; low</code>, and <code>high</code> if <code>value &gt; high</code>.<br><b>Precondition:</b> <code>low &lt;= high</code></div>What does this print?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">System.out.println(clamp(15, 0, 10) + \"\" + clamp(-8, -5, 5));</pre>", "img": null, "choices": ["15-8", "5", "10-8", "10-5"], "answer": 3, "why": "clamp(15, 0, 10): 15 is above high, so it returns 10. clamp(-8, -5, 5): -8 is below low, so it returns -5. 10 + \"\" = \"10\", then + (-5) joins to \"10-5\". Both calls meet the precondition low <= high."}, {"id": "seed-mcq-java-u2-mock-q35", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · error identification · medium</small><br>What is wrong with this method?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static int bigger(int a, int b) {\n    int m = Math.max(a, b);\n    System.out.println(m);\n}</pre>", "img": null, "choices": ["Compile-time error: missing return statement", "Nothing; it returns 0 by default", "Logic error: it prints the larger value but returns nothing", "Runtime exception when the method is called"], "answer": 0, "why": "The method promises to return an int, but no return statement exists, so the compiler rejects it (\"missing return statement\"). Printing m is not the same as returning it."}, {"id": "seed-mcq-java-u2-mock-q36", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · error identification · hard</small><br>average(1, 2, 2) should be about 1.67. Which best describes this code?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    System.out.println(average(1, 2, 2));\n}\n\npublic static double average(int a, int b, int c) {\n    return (a + b + c) / 3;\n}</pre>", "img": null, "choices": ["Logic error: it compiles and runs, but prints 1.0", "Runtime exception: the division produces a fraction", "Compile-time error: (a + b + c) / 3 is an int but the method returns double", "It prints 1.6666666666666667"], "answer": 0, "why": "All three operands are ints, so 5 / 3 = 1 (integer division). The int 1 is legally widened to the double 1.0 when returned. It compiles and runs, just with the wrong answer. Fix: divide by 3.0."}, {"id": "seed-mcq-java-u2-mock-q37", "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · error identification · hard</small><br>What happens?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">int total;\nfor (int i = 1; i &lt;= 3; i++) {\n    total += i;\n}\nSystem.out.println(total);</pre>", "img": null, "choices": ["It prints 0", "It prints 6, since total starts at 0", "Compile-time error: total might not have been initialized", "Runtime exception: NullPointerException"], "answer": 2, "why": "Local variables have NO default value. total is used (total += i) before it is ever given a value, so the compiler refuses: \"variable total might not have been initialized\". Fix: int total = 0;"}, {"id": "seed-mcq-java-u2-mock-q38", "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · error identification · very hard</small><br>A student writes both methods in the same class. What happens?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static int scale(int x, int factor) {\n    return x * factor;\n}\n\npublic static double scale(int factor, int x) {\n    return factor * x * 1.0;\n}</pre>", "img": null, "choices": ["Valid overload, because the parameters are in a different order", "It compiles, but calling scale(2, 3) causes a runtime exception", "Compile-time error: scale(int, int) is already defined", "Valid overload, because the return types differ"], "answer": 2, "why": "Both signatures are scale(int, int). Swapping parameter NAMES does not change the types, and the return type is not part of the signature. Duplicate signatures are a compile-time error."}, {"id": "seed-mcq-java-u2-mock-q39", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · error identification · very hard</small><br>What happens when this runs?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">String s = null;\nString t = s + \"!\";\nSystem.out.println(t.length() + \" \" + s.length());</pre>", "img": null, "choices": ["NullPointerException on line 2 (s + \"!\")", "NullPointerException at runtime, and nothing is printed", "It prints 5 0", "Compile-time error: you cannot concatenate null"], "answer": 1, "why": "Line 2 is fine: concatenating null gives the String \"null!\" (t.length() is 5). But s.length() calls a method THROUGH null, which throws NullPointerException. println evaluates its whole argument first, so the exception happens before anything prints."}, {"id": "seed-mcq-java-u2-mock-q40", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · error identification · hard</small><br>Using the Counter class shown below: What happens with the statement <code>Counter c = new Counter(2.5);</code>?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">class Counter {\n    private int count;\n    public Counter() { count = 0; }\n    public Counter(int start) { count = start; }\n    public void add(int n) { count += n; }\n    public int getCount() { return count; }\n}</pre>", "img": null, "choices": ["c's count is 2 (the decimal is dropped)", "Runtime exception when the constructor runs", "c's count is 3 (rounded)", "Compile-time error: no constructor accepts a double"], "answer": 3, "why": "Counter only has Counter() and Counter(int). A double never automatically narrows to int, so no constructor matches: compile-time error."}, {"id": "seed-mcq-java-u2-mock-q41", "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · error identification · hard</small><br>Using the Rect class shown below, what happens when the code runs?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">class Rect {\n    private int width;\n    private int height;\n    public Rect(int width, int height) {\n        this.width = width;\n        this.height = height;\n    }\n    public int getWidth() { return width; }\n    public int getHeight() { return height; }\n}\n\nint h = 3;\nint w = 8;\nRect r = new Rect(h, w);\nSystem.out.println(r.getWidth());</pre>", "img": null, "choices": ["It prints 8, because Java matches h to height", "Logic error: it compiles and prints 3", "Compile-time error: the arguments must be named width and height", "Runtime exception"], "answer": 1, "why": "Arguments are matched to parameters by POSITION, not by variable name. h (3) goes into width and w (8) into height. Both are ints, so the compiler cannot catch it. That is why argument order matters."}, {"id": "seed-mcq-java-u2-mock-q42", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · error identification · hard</small><br>What happens?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">String s = \"hello\";\nSystem.out.println(s.substring(5) + \"|\" + s.substring(2, 6));</pre>", "img": null, "choices": ["It prints o|llo", "Compile-time error", "StringIndexOutOfBoundsException at runtime", "It prints |llo"], "answer": 2, "why": "\"hello\" has length 5. substring(5) is legal and gives \"\" (start may equal length). But substring(2, 6) has end 6 > length 5, so it throws at runtime, before println prints anything."}, {"id": "seed-mcq-java-u2-mock-q43", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · error identification · very hard</small><br>Which describes this code?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">String a = \"hi\";\nString b = new String(\"hi\");\nSystem.out.println(a == b);\nSystem.out.println(a.equals(b));</pre>", "img": null, "choices": ["It prints true, then false", "Valid code; prints false, then true", "Compile-time error: Strings cannot be compared with ==", "It prints true, then true"], "answer": 1, "why": "new String(\"hi\") creates a separate object. == compares REFERENCES (is it the same object?), so it is false. .equals compares the characters, so it is true. Always use .equals for String content."}, {"id": "seed-mcq-java-u2-mock-q44", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · error identification · hard</small><br>Which describes this code?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">String w = \"code\";\nString r = w.substring(w.length());\nSystem.out.println(\"[\" + r + \"]\" + r.length());</pre>", "img": null, "choices": ["Compile-time error", "It prints [e]1", "Valid code; prints []0", "StringIndexOutOfBoundsException, because index 4 does not exist"], "answer": 2, "why": "substring(start) allows start == length() and returns the empty String \"\". Only a start greater than length() (or negative) throws an exception."}, {"id": "seed-mcq-java-u2-mock-q45", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · String manipulation · medium</small><br>What is <code>\"Hello, World!\".length()</code>?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">System.out.println(\"Hello, World!\".length());</pre>", "img": null, "choices": ["13", "10", "11", "12"], "answer": 0, "why": "Count EVERY character, including the comma, the space, and the \"!\": H-e-l-l-o-,-space-W-o-r-l-d-! = 13."}, {"id": "seed-mcq-java-u2-mock-q46", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · String manipulation · medium</small><br>What is <code>\"programming\".substring(3, 7)</code>?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">System.out.println(\"\\\"\" + \"programming\".substring(3, 7) + \"\\\"\");</pre>", "img": null, "choices": ["\"rogr\"", "\"gram\"", "\"ogra\"", "\"gramm\""], "answer": 1, "why": "Indexes 3, 4, 5, 6 (end 7 is excluded): p0 r1 o2 g3 r4 a5 m6, which spells \"gram\". The length is always end − start = 4."}, {"id": "seed-mcq-java-u2-mock-q47", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · String manipulation · hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">String s = \"APCSA rocks\";\nSystem.out.println(s.substring(s.length() - 5) + s.substring(0, 2));</pre>", "img": null, "choices": [" rocksAP", "ocksAP", "rocksAP", "rocksAPC"], "answer": 2, "why": "length is 11, so substring(11 − 5) = substring(6). Index 5 is the space, so index 6 starts \"rocks\". Then substring(0, 2) = \"AP\"."}, {"id": "seed-mcq-java-u2-mock-q48", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · String manipulation · hard</small><br>Which expression returns <code>word</code> with its first and last characters swapped? (For example, \"pizza\" becomes \"aizzp\". Assume the length is at least 2.)", "img": null, "choices": ["word.substring(word.length() - 1) + word.substring(1, word.length() - 1) + word.substring(0, 1)", "word.substring(word.length()) + word.substring(1, word.length() - 1) + word.substring(0, 1)", "word.substring(word.length() - 1) + word.substring(1, word.length()) + word.substring(0, 1)", "word.substring(word.length() - 1) + word.substring(0, word.length() - 1)"], "answer": 0, "why": "Last char: substring(length − 1). Middle: substring(1, length − 1). First: substring(0, 1). substring(length) is \"\" (loses the last char); substring(1, length) keeps the last char in the middle; the last choice just moves the last letter to the front (\"apizz\")."}, {"id": "seed-mcq-java-u2-mock-q49", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · String manipulation · very hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">String s = \"abcdefg\";\nString first = s.substring(0, s.length() / 2);\nString second = s.substring(s.length() / 2);\nSystem.out.println(first + \" \" + second);</pre>", "img": null, "choices": ["abcd efg", "abc defg", "abc efg", "abcd defg"], "answer": 1, "why": "length 7 / 2 = 3 (integer division). first = substring(0, 3) = \"abc\"; second = substring(3) = \"defg\". With an odd length, the extra character goes into the SECOND half."}, {"id": "seed-mcq-java-u2-mock-q50", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · String manipulation · hard</small><br>For an odd-length String <code>s</code>, which expression returns the middle character? (For example, \"abcde\" gives \"c\".)", "img": null, "choices": ["s.substring(s.length() / 2, s.length() / 2 + 1)", "s.substring((s.length() + 1) / 2, (s.length() + 1) / 2 + 1)", "s.substring(s.length() / 2 - 1, s.length() / 2)", "s.substring(s.length() / 2 + 1)"], "answer": 0, "why": "For length 5, length / 2 = 2, which is exactly the middle index. substring(2, 3) gives one character, \"c\". The others give \"b\", \"de\", and \"d\"."}, {"id": "seed-mcq-java-u2-mock-q51", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · String manipulation · very hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">System.out.println(1 + 2 + \"3\" + 4 * 5 + (6 + 7));</pre>", "img": null, "choices": ["1232013", "332013", "332067", "334513"], "answer": 1, "why": "Left to right: 1 + 2 = 3, then 3 + \"3\" = \"33\". * happens before +, so 4 * 5 = 20 and \"33\" + 20 = \"3320\". The parentheses go first: 6 + 7 = 13, so the result is \"332013\"."}, {"id": "seed-mcq-java-u2-mock-q52", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · String manipulation · hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static void main(String[] args) {\n    String msg = \"hey\";\n    shout(msg);\n    shout(msg.substring(1));\n    System.out.println(msg);\n}\n\npublic static void shout(String s) {\n    s = s + \"!!\";\n    System.out.print(s + \" \");\n}</pre>", "img": null, "choices": ["hey!! ey!! hey!!", "hey!! y!! hey", "hey!! ey!! hey", "hey!! ey hey"], "answer": 2, "why": "shout reassigns its own copy s; msg in main is never changed (Strings are immutable and Java is pass-by-value). msg.substring(1) is \"ey\", so the second call prints \"ey!! \"."}, {"id": "seed-mcq-java-u2-mock-q53", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · String manipulation · very hard</small><br>What is the exact output?<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">String s = \"mississippi\";\ns = s.substring(s.length() - 4) + s.substring(1, 4);\ns = s.substring(2) + s.length();\nSystem.out.println(s);</pre>", "img": null, "choices": ["piiss7", "ppiiss7", "iiss7", "piiss11"], "answer": 0, "why": "\"mississippi\" has length 11, so substring(7) = indexes 7 to 10 = \"ippi\". substring(1, 4) = \"iss\". s = \"ippiiss\" (length 7). Then substring(2) = \"piiss\" plus s.length() (7, measured BEFORE reassignment) = \"piiss7\"."}, {"id": "seed-mcq-java-u2-mock-q54", "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · String manipulation · hard</small><br>Let <code>String s = \"java\";</code> Which call throws a StringIndexOutOfBoundsException?", "img": null, "choices": ["s.substring(4)", "s.substring(1, 4)", "s.substring(0, 0)", "s.substring(2, 1)"], "answer": 3, "why": "Valid indexes satisfy 0 ≤ start ≤ end ≤ length() (here 4). substring(4) and substring(0, 0) are legal and give \"\". substring(1, 4) is \"ava\". substring(2, 1) has start > end, so it throws."}, {"id": "seed-mcq-java-u2-mock-f0", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.1 · Practice 1: Parameters & Returns · free response · hard</small><br>Write a complete Java method (not a full class or main method).", "parts": [{"label": "Method", "q": "Write a method <code>largestGap</code> that takes three <code>int</code> parameters and returns the largest difference between any two of them. Use <code>Math.max</code> and <code>Math.min</code>. For example, <code>largestGap(4, -2, 9)</code> returns 11 and <code>largestGap(5, 5, 5)</code> returns 0.", "pts": 4, "sol": "One correct solution:<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static int largestGap(int a, int b, int c) {\n    int biggest = Math.max(a, Math.max(b, c));\n    int smallest = Math.min(a, Math.min(b, c));\n    return biggest - smallest;\n}</pre><b>Rubric</b><ol style=\"margin:6px 0 0 18px\"><li>Correct header: public static int largestGap(int a, int b, int c) (1 pt)</li><li>Finds the largest of three with nested Math.max (1 pt)</li><li>Finds the smallest of three with nested Math.min (1 pt)</li><li>Returns (not prints) largest − smallest (1 pt)</li></ol>"}]}, {"id": "seed-mcq-java-u2-mock-f1", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.2 · Practice 2: Signatures, Overloading & APIs · free response · hard</small><br>Write a complete Java method (not a full class or main method).", "parts": [{"label": "Method", "q": "Write TWO overloaded methods named <code>average</code>. One takes two <code>int</code> parameters and the other takes three. Both return the exact average as a <code>double</code>. For example, <code>average(3, 4)</code> returns 3.5 and <code>average(1, 2, 2)</code> returns 1.6666666666666667.", "pts": 4, "sol": "One correct solution:<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static double average(int a, int b) {\n    return (a + b) / 2.0;\n}\n\npublic static double average(int a, int b, int c) {\n    return (a + b + c) / 3.0;\n}</pre><b>Rubric</b><ol style=\"margin:6px 0 0 18px\"><li>Both methods named average with return type double (1 pt)</li><li>Parameter lists differ in number: (int, int) and (int, int, int) (1 pt)</li><li>Avoids integer division (divides by 2.0 and 3.0, or casts) (1 pt)</li><li>Returns the value in both methods (1 pt)</li></ol>"}]}, {"id": "seed-mcq-java-u2-mock-f2", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.3 · Practice 3: Objects, References & Constructors · free response · very hard</small><br>Write a complete Java method (not a full class or main method).", "parts": [{"label": "Method", "q": "Use this class:<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">class Counter {\n    private int count;\n    public Counter() { count = 0; }\n    public Counter(int start) { count = start; }\n    public void add(int n) { count += n; }\n    public int getCount() { return count; }\n}</pre>Write a method <code>biggerCopy</code> that takes two <code>Counter</code> parameters and returns a NEW <code>Counter</code> whose count equals the larger of the two counts. It must not change either parameter, and it must not return one of the parameters themselves.", "pts": 4, "sol": "One correct solution:<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static Counter biggerCopy(Counter a, Counter b) {\n    int bigger = Math.max(a.getCount(), b.getCount());\n    return new Counter(bigger);\n}</pre><b>Rubric</b><ol style=\"margin:6px 0 0 18px\"><li>Header: public static Counter biggerCopy(Counter a, Counter b) (1 pt)</li><li>Uses getCount() on both objects (not the private field) (1 pt)</li><li>Creates a new Counter with new, passing the larger value (1 pt)</li><li>Does not call add on a or b and does not return a or b (1 pt)</li></ol>"}]}, {"id": "seed-mcq-java-u2-mock-f3", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · free response · medium</small><br>Write a complete Java method (not a full class or main method).", "parts": [{"label": "Method", "q": "Write a method <code>swapEnds</code> that takes a <code>String</code> and returns a new String with its first and last characters swapped. Precondition: <code>word.length() &gt;= 2</code>. For example, <code>swapEnds(\"pizza\")</code> returns \"aizzp\" and <code>swapEnds(\"ab\")</code> returns \"ba\". Use <code>substring</code>.", "pts": 4, "sol": "One correct solution:<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static String swapEnds(String word) {\n    int len = word.length();\n    String first = word.substring(0, 1);\n    String middle = word.substring(1, len - 1);\n    String last = word.substring(len - 1);\n    return last + middle + first;\n}</pre><b>Rubric</b><ol style=\"margin:6px 0 0 18px\"><li>Gets the first character with substring(0, 1) (1 pt)</li><li>Gets the last character with substring(length − 1) (1 pt)</li><li>Gets the middle with substring(1, length − 1) (works for length 2: it gives \"\") (1 pt)</li><li>Returns last + middle + first (1 pt)</li></ol>"}]}, {"id": "seed-mcq-java-u2-mock-f4", "type": "frq", "img": null, "stem": "<small style=\"color:var(--mut)\">Lesson 2.4 · Practice 4: Strings · free response · very hard</small><br>Write a complete Java method (not a full class or main method).", "parts": [{"label": "Method", "q": "Write a method <code>rotateHalf</code> that takes a <code>String</code> and returns its second half followed by its first half. The first half is the first <code>s.length() / 2</code> characters, so for an odd length the extra character belongs to the second half. For example, <code>rotateHalf(\"abcdefg\")</code> returns \"defgabc\", <code>rotateHalf(\"abcd\")</code> returns \"cdab\", and <code>rotateHalf(\"\")</code> returns \"\".", "pts": 4, "sol": "One correct solution:<pre style=\"background:var(--soft);padding:10px 12px;border-radius:8px;font-size:14px;line-height:1.45;overflow-x:auto;white-space:pre;margin:8px 0\">public static String rotateHalf(String s) {\n    int half = s.length() / 2;\n    return s.substring(half) + s.substring(0, half);\n}</pre><b>Rubric</b><ol style=\"margin:6px 0 0 18px\"><li>Computes the split point with s.length() / 2 (1 pt)</li><li>Second half: substring(half) (1 pt)</li><li>First half: substring(0, half) (1 pt)</li><li>Returns second + first and works for \"\" and odd lengths (1 pt)</li></ol>"}]}]}, {"id": "seed-java-u2-rules", "rev": 1, "title": "AP CSA Unit 2 — Rules, Errors & How-To", "folder": "AP CSA", "description": "Rules to memorize, common errors (compile-time vs. runtime vs. logic), and step-by-step methods for tracing, overloading, references, and substring problems.", "cards": [{"id": "seed-java-u2-rules-0", "term": "Parameter vs. argument", "def": "Parameter: the variable declared in the method header (n in square(int n)).\nArgument: the actual value passed in the call (5 in square(5)).", "note": "Memory trick: Parameters are in the Plan (header); Arguments are Actual values."}, {"id": "seed-java-u2-rules-1", "term": "What does \"Java is pass-by-value\" mean?", "def": "A method receives a COPY of each argument's value. Changing the parameter never changes the caller's variable.", "note": "void add1(int n) { n++; }  →  int x = 5; add1(x);  x is still 5."}, {"id": "seed-java-u2-rules-2", "term": "Object parameters: what CAN and CANNOT a method change?", "def": "The method gets a copy of the REFERENCE (the arrow).\nCAN: mutate the shared object (c.add(1) is seen by the caller).\nCANNOT: change the caller's variable by reassigning (c = new Counter() only changes the method's copy)."}, {"id": "seed-java-u2-rules-3", "term": "Local variable scope", "def": "A variable exists only inside the { } where it is declared. Parameters are local to their method. A variable named x in main and a parameter named x are two DIFFERENT variables."}, {"id": "seed-java-u2-rules-4", "term": "How does return work?", "def": "\"return value;\" immediately ends the method and sends the value back. The method call is then replaced by that value, like f(3) → 9."}, {"id": "seed-java-u2-rules-5", "term": "return vs. println", "def": "println shows text on the screen. return hands a value back to the code that called the method. A method can do both. If the return value is not stored or used, it is lost: \"square(5);\" alone shows nothing."}, {"id": "seed-java-u2-rules-6", "term": "void vs. value-returning methods", "def": "void: returns nothing, so it cannot be used in an expression (int x = printIt(); is a compile error).\nValue-returning: must return a value of its declared type on every path."}, {"id": "seed-java-u2-rules-7", "term": "Parts of a method header", "def": "public static int max3(int a, int b, int c)\naccess · static · return type · name · parameter list (type + name pairs, separated by commas)"}, {"id": "seed-java-u2-rules-8", "term": "How do you choose a return type?", "def": "Ask what kind of value comes back: whole number → int, decimal → double, text → String, true/false → boolean, nothing → void."}, {"id": "seed-java-u2-rules-9", "term": "Math.abs, Math.min, Math.max", "def": "Math.abs(-7) → 7 and Math.abs(-2.5) → 2.5.\nmin/max take exactly TWO arguments. For three, nest them: Math.max(a, Math.max(b, c)).\nThe result is a double if either argument is a double: Math.max(3, 4.0) → 4.0."}, {"id": "seed-java-u2-rules-10", "term": "Math.pow(base, exponent)", "def": "ALWAYS returns a double: Math.pow(2, 3) → 8.0.\nint x = Math.pow(2, 3); is a compile-time error (possible lossy conversion). Use (int) Math.pow(2, 3) if you need an int."}, {"id": "seed-java-u2-rules-11", "term": "Integer division inside a method that returns double", "def": "return (a + b) / 2; with int a and b divides FIRST (dropping the decimal), then widens. avg(7, 4) returns 5.0, not 5.5.\nFix: (a + b) / 2.0"}, {"id": "seed-java-u2-rules-12", "term": "Tracing a call whose argument names don't match the parameter names", "def": "Match by POSITION, never by name. For order(z, x, y) with header order(int y, int z, int x), the first parameter (y) gets main's z."}, {"id": "seed-java-u2-rules-13", "term": "Order of evaluation in nested calls", "def": "The innermost call runs first, and arguments are evaluated left to right BEFORE the method runs. In b(a(1)), a runs before b prints anything."}, {"id": "seed-java-u2-rules-14", "term": "Print-and-return methods inside println", "def": "In System.out.println(f(2) + f(3)), both calls print their text FIRST, and then println prints the final result, because the argument must be fully evaluated before printing."}, {"id": "seed-java-u2-rules-15", "term": "Method signature: what IS and is NOT included", "def": "IS: the method name + parameter TYPES in order, like area(int, double).\nIS NOT: return type, parameter names, public/private, static."}, {"id": "seed-java-u2-rules-16", "term": "Method overloading", "def": "Several methods with the same name but different parameter lists: a different number of parameters, different types, or a different ORDER of types.", "note": "Valid set: f(int), f(double), f(int, int), f(int, double), f(double, int)."}, {"id": "seed-java-u2-rules-17", "term": "Why is changing only the return type an invalid overload?", "def": "int f(int x) and double f(int x) have the same signature f(int). Java chooses a method by its arguments, so it could not tell them apart: compile-time error (\"already defined\")."}, {"id": "seed-java-u2-rules-18", "term": "Why is changing only the parameter names an invalid overload?", "def": "f(int a, int b) and f(int b, int a) are both f(int, int). Names are not part of the signature: compile-time error."}, {"id": "seed-java-u2-rules-19", "term": "How does Java choose between overloaded methods?", "def": "1. An exact type match wins.\n2. Otherwise it allows widening (int → double).\n3. If several work, it picks the MOST SPECIFIC one (the one needing the least widening).\nThis is decided at compile time."}, {"id": "seed-java-u2-rules-20", "term": "Automatic widening (int → double)", "def": "An int can automatically become a double (f(double) accepts f(5)). A double NEVER automatically becomes an int: f(int) rejects f(5.0) with a compile error unless you cast."}, {"id": "seed-java-u2-rules-21", "term": "Ambiguous overloaded call", "def": "Two overloads both fit and neither is more specific. g(int, double) and g(double, int) called as g(3, 4) → compile-time error: \"reference to g is ambiguous\"."}, {"id": "seed-java-u2-rules-22", "term": "One overload calling another", "def": "public static int area(int s) { return area(s, s); }\nThe 1-parameter version reuses the 2-parameter version, so the logic is written once."}, {"id": "seed-java-u2-rules-23", "term": "Writing overloaded methods", "def": "Same name, different parameter lists. Each can have its own return type. Example:\ndouble average(int a, int b) { return (a + b) / 2.0; }\ndouble average(int a, int b, int c) { return (a + b + c) / 3.0; }"}, {"id": "seed-java-u2-rules-24", "term": "Class vs. object vs. reference variable", "def": "Class: the blueprint (code).\nObject: one instance built from it, with its own data.\nReference variable: holds the ADDRESS of an object (an arrow), not the object itself."}, {"id": "seed-java-u2-rules-25", "term": "What does \"new\" do?", "def": "It creates ONE new object, runs a matching constructor to set it up, and returns a reference to it. Each executed \"new\" = exactly one object."}, {"id": "seed-java-u2-rules-26", "term": "Constructor vs. method", "def": "A constructor has the SAME name as the class and NO return type (not even void). It runs only with \"new\" and initializes the object. A method has a return type and is called on an object or a class."}, {"id": "seed-java-u2-rules-27", "term": "Constructor overloading and valid calls", "def": "A class can have several constructors with different parameter lists, like Counter() and Counter(int start). A call must match one by number, type, and order: new Counter(2.5) is a compile-time error if only those two exist."}, {"id": "seed-java-u2-rules-28", "term": "Why does argument order matter in constructor calls?", "def": "Arguments are matched by POSITION. If Rect(int width, int height) is called as new Rect(h, w), width gets h. Same types → silent logic error. Different types (like String, int swapped) → compile-time error."}, {"id": "seed-java-u2-rules-29", "term": "Does \"Counter c;\" create an object?", "def": "No. It only declares a reference variable. A local c has no value yet (using it is a compile-time error). \"Counter c = null;\" also creates no object."}, {"id": "seed-java-u2-rules-30", "term": "Aliasing: two variables, one object", "def": "Counter b = a; copies the arrow, so both refer to the SAME object. A change made through b (b.add(5)) is visible through a."}, {"id": "seed-java-u2-rules-31", "term": "Reassignment vs. mutation", "def": "Reassignment: b = new Counter(5); points b at a different object, and a is unaffected.\nMutation: b.add(5); changes the object itself, which every alias sees."}, {"id": "seed-java-u2-rules-32", "term": "What does null mean?", "def": "A reference that points to NO object. You can assign it, print it (\"null\"), and concatenate it, but you cannot call methods through it."}, {"id": "seed-java-u2-rules-33", "term": "NullPointerException", "def": "A RUNTIME exception thrown when you call a method through a null reference, like s.length() or c.add(1) when the variable is null."}, {"id": "seed-java-u2-rules-34", "term": "Setting one reference to null: does it affect the others?", "def": "No. a = null only changes the variable a. If b = a was done earlier, b still refers to the object, and b.add(2) works fine."}, {"id": "seed-java-u2-rules-35", "term": "Instance methods vs. class (static) methods", "def": "Instance: called on an object and uses that object's data, like c.getCount() or s.length().\nClass/static: called on the class name, like Math.abs(-3) or Math.max(a, b)."}, {"id": "seed-java-u2-rules-36", "term": "Reading an unfamiliar class API", "def": "Look for: (1) constructors: what you must pass and in what order; (2) each method's return type: void means you cannot store a result; (3) parameter types and order; (4) preconditions; (5) which methods change the object."}, {"id": "seed-java-u2-rules-37", "term": "String indexing", "def": "The first character is at index 0 and the last is at index length() − 1.\n\"java\": j=0, a=1, v=2, a=3."}, {"id": "seed-java-u2-rules-38", "term": "substring(start)", "def": "Returns from start to the end. \"hello\".substring(2) → \"llo\". start may equal length(), which gives \"\"."}, {"id": "seed-java-u2-rules-39", "term": "substring(start, end)", "def": "From start up to but NOT including end. The result's length = end − start.\n\"hello\".substring(1, 4) → \"ell\"."}, {"id": "seed-java-u2-rules-40", "term": "Valid substring indexes and empty substrings", "def": "Legal when 0 ≤ start ≤ end ≤ length(). s.substring(k, k) and s.substring(s.length()) both give \"\" (not errors). Anything else throws StringIndexOutOfBoundsException at runtime."}, {"id": "seed-java-u2-rules-41", "term": "length()", "def": "Counts EVERY character, including spaces and punctuation. \"Hi, you!\".length() → 8."}, {"id": "seed-java-u2-rules-42", "term": "String immutability", "def": "String methods never change the original String; they return a NEW one. \"s.substring(1);\" alone does nothing. You must write s = s.substring(1);"}, {"id": "seed-java-u2-rules-43", "term": "Concatenation vs. addition (left to right)", "def": "1 + 2 + \"a\" → \"3a\" (adds first). \"a\" + 1 + 2 → \"a12\" (once a String appears, + joins). * and / still happen before +: \"a\" + 2 * 3 → \"a6\". Parentheses go first: \"a\" + (1 + 2) → \"a3\"."}, {"id": "seed-java-u2-rules-44", "term": "String references", "def": "String b = a; makes both refer to the same String. a = a + \"s\"; builds a NEW String for a only; b is unchanged."}, {"id": "seed-java-u2-rules-45", "term": "String parameters", "def": "Reassigning a String parameter inside a method (s = s + \"!\") does NOT change the caller's variable (pass-by-value + immutability). Return the new String instead and store it."}, {"id": "seed-java-u2-rules-46", "term": "First and last characters", "def": "First: s.substring(0, 1)\nLast: s.substring(s.length() - 1)"}, {"id": "seed-java-u2-rules-47", "term": "Swap the first and last characters", "def": "s.substring(s.length() - 1) + s.substring(1, s.length() - 1) + s.substring(0, 1)\nPrecondition: length ≥ 2. For \"ab\" the middle is \"\"."}, {"id": "seed-java-u2-rules-48", "term": "First and second halves (odd lengths)", "def": "first = s.substring(0, s.length() / 2)\nsecond = s.substring(s.length() / 2)\nInteger division puts the extra character in the SECOND half: \"abcde\" → \"ab\" and \"cde\"."}, {"id": "seed-java-u2-rules-49", "term": "Middle character of an odd-length String", "def": "s.substring(s.length() / 2, s.length() / 2 + 1)\n\"abcde\": 5 / 2 = 2 → \"c\"."}, {"id": "seed-java-u2-rules-50", "term": "== vs. .equals for Strings", "def": "== compares REFERENCES (is it the same object?). .equals compares the CHARACTERS. a == new String(\"hi\") is false even when a is \"hi\". Always use .equals for content."}, {"id": "seed-java-u2-rules-51", "term": "Compile-time error", "def": "The code breaks Java's rules, so the program never runs. Examples: missing ;, type mismatch, undefined method, wrong arguments, missing return, ambiguous call, duplicate signature, uninitialized local variable."}, {"id": "seed-java-u2-rules-52", "term": "Runtime exception", "def": "The code compiles, then crashes while running when something illegal happens: NullPointerException, StringIndexOutOfBoundsException, ArithmeticException (int ÷ 0)."}, {"id": "seed-java-u2-rules-53", "term": "Logic error", "def": "The code compiles AND finishes without crashing, but gives the wrong result: integer division, swapped arguments, ignored return values, off-by-one loops."}, {"id": "seed-java-u2-rules-54", "term": "Missing return statement", "def": "Compile-time error. A non-void method can reach its closing } without returning a value. Printing the value does not count as returning it."}, {"id": "seed-java-u2-rules-55", "term": "Return-type mistakes", "def": "return x; inside a void method → compile-time error (\"unexpected return value\").\nreturn 2.5; in an int method → compile-time error (possible lossy conversion).\nreturn 5; in a double method is FINE (widened to 5.0)."}, {"id": "seed-java-u2-rules-56", "term": "Wrong arguments or a nonexistent constructor", "def": "Compile-time error. The wrong number, types, or order of arguments matches no method/constructor: \"cannot be applied to given types\" or \"no suitable constructor found\"."}, {"id": "seed-java-u2-rules-57", "term": "Duplicate method signatures", "def": "Compile-time error (\"already defined\"). Two methods have the same name and parameter types, even if their return types or parameter names differ."}, {"id": "seed-java-u2-rules-58", "term": "Using an uninitialized local variable", "def": "Compile-time error: \"variable might not have been initialized\". Local variables get NO default value. Example: int total; total += 5;"}, {"id": "seed-java-u2-rules-59", "term": "NullPointerException: when it does and does NOT happen", "def": "Happens: calling a method through null (s.length(), c.add(1)).\nDoes NOT happen: printing or concatenating null. null + \"!\" is the String \"null!\"."}, {"id": "seed-java-u2-rules-60", "term": "StringIndexOutOfBoundsException", "def": "Runtime exception: a substring index is negative, greater than length(), or start > end. Nothing in that statement prints, because the exception happens before println gets its value."}, {"id": "seed-java-u2-rules-61", "term": "Violating an API precondition", "def": "A precondition is what must be true BEFORE calling a method (like low ≤ high). The compiler does not check it. If you violate it, the result is not guaranteed: a wrong answer or an exception."}, {"id": "seed-java-u2-rules-62", "term": "Valid code with surprising output (not an error)", "def": "Compiles and runs fine, but may not do what you meant: s.substring(1); with no assignment, == on Strings giving false, an ignored return value, integer division. Ask: \"Does it compile and finish?\" If yes, it is not a compile-time or runtime error."}, {"id": "seed-java-u2-rules-63", "term": "HOW TO: Trace a method with parameters", "def": "1. Write the call with its argument VALUES.\n2. Copy each value into the parameter in the same POSITION.\n3. Trace the method with its own variables in a box.\n4. When it ends, cross out the box. Main's variables are unchanged unless a returned value is assigned."}, {"id": "seed-java-u2-rules-64", "term": "HOW TO: Trace methods that return values", "def": "1. Work out the arguments.\n2. Trace the method until return.\n3. Replace the call with the returned value.\n4. Check whether the value is stored (x = f(3)), used (f(3) + 1), or thrown away (f(3);)."}, {"id": "seed-java-u2-rules-65", "term": "HOW TO: Trace methods that print AND return", "def": "Keep two columns: OUTPUT (what prints, in order) and VALUE (what comes back). Remember println(f(1) + f(2)) prints f(1)'s text, then f(2)'s text, then the sum."}, {"id": "seed-java-u2-rules-66", "term": "HOW TO: Decide which overloaded method is called", "def": "1. Write the TYPE of each argument (5 / 2 is int; 5 / 2.0 is double; \"\" + 5 is String).\n2. Find overloads with the right number of parameters.\n3. Exact match wins; otherwise allow int → double widening.\n4. If several fit, pick the most specific."}, {"id": "seed-java-u2-rules-67", "term": "HOW TO: Spot an ambiguous overload", "def": "Two overloads both fit only after widening, and each needs widening in a DIFFERENT position (g(int, double) vs g(double, int) with g(3, 4)). Neither is more specific → compile-time error."}, {"id": "seed-java-u2-rules-68", "term": "HOW TO: Count objects created", "def": "Count each \"new\" that actually runs (inside a loop, multiply by the number of passes). Ignore declarations (Counter c;), assignments (b = a;), and null."}, {"id": "seed-java-u2-rules-69", "term": "HOW TO: Draw a reference diagram", "def": "Draw each variable as a box and each object as a separate circle. new → draw a circle and an arrow. b = a → copy a's arrow. b = null → erase b's arrow. A method call on b changes the circle b points to."}, {"id": "seed-java-u2-rules-70", "term": "HOW TO: Trace String assignments", "def": "1. Write the current value of each String variable.\n2. A method call alone (s.substring(1);) changes nothing.\n3. Only \"s = ...\" updates s.\n4. Compute the right side using the OLD value of s, then update."}, {"id": "seed-java-u2-rules-71", "term": "HOW TO: Solve a complicated substring expression", "def": "1. Write the String with index numbers under each character.\n2. Compute length() and any arithmetic (length / 2 uses integer division).\n3. Take indexes start to end − 1.\n4. Do each substring separately, then join them left to right."}, {"id": "seed-java-u2-rules-72", "term": "HOW TO: Tell compile-time from runtime errors", "def": "Ask: can the compiler see the problem from the code alone (types, names, arguments, syntax, missing return)? → compile-time.\nDoes it depend on a value while running (null, bad index, ÷ 0)? → runtime."}, {"id": "seed-java-u2-rules-73", "term": "HOW TO: Read an unfamiliar API", "def": "1. Constructors: what to pass, in what order.\n2. Each method: name, parameter types, return type.\n3. void → do not store the result; non-void → use or store it.\n4. Read the preconditions and what the method changes."}, {"id": "seed-java-u2-rules-74", "term": "HOW TO: Check preconditions", "def": "Before each call, plug in the actual argument values and confirm every precondition is true (like low ≤ high, or length ≥ 2). If one is false, the answer is \"not guaranteed\" or an error, not a normal value."}, {"id": "seed-java-u2-rules-75", "term": "HOW TO: Write an FRQ method from scratch", "def": "1. Header: public static, return type, name, parameter types EXACTLY as described.\n2. Work out one example by hand.\n3. Use the required tools (Math.max, substring...).\n4. RETURN the result (do not print unless asked).\n5. Trace your code with the given examples."}, {"id": "seed-java-u2-rules-76", "term": "HOW TO: Choose void or a return type", "def": "If the problem says \"returns\", use a return type and a return statement. If it says \"prints\" or \"displays\" and nothing comes back, use void."}, {"id": "seed-java-u2-rules-77", "term": "HOW TO: Check a method for syntax errors", "def": "Check: the header has a return type and parameter types; braces and parentheses match; each statement ends with ;; a non-void method returns on every path; types match (no double into int); method and variable names are spelled the same everywhere."}, {"id": "seed-java-u2-rules-78", "term": "HOW TO: Test edge cases", "def": "Try the smallest legal inputs (length 2, the empty String \"\"), odd and even lengths, negative numbers, equal values, and 0. Check substring indexes at 0 and length()."}]}, {"id": "seed-apes-u2-learn-atmosphere", "rev": 1, "title": "APES Unit 2 — LEARN 1: Atmosphere", "folder": "APES", "description": "Slides I: the 5 layers, composition, CO2, ozone, jet stream. One fact per card: question → short answer, with the why, a memory trick, or the common trap in the note.", "cards": [{"id": "seed-apes-u2-learn-atmosphere-0", "term": "Order the 5 layers of the atmosphere from the ground up.", "def": "Troposphere → Stratosphere → Mesosphere → Thermosphere → Exosphere", "note": "Trick: \"The Silly Monkey Threw Eggs.\"", "defImg": "seed/img/apes-u2-atmosphere.svg"}, {"id": "seed-apes-u2-learn-atmosphere-1", "term": "What separates the layers of the atmosphere?", "def": "Temperature, which changes based on how much solar radiation each layer absorbs.", "note": "Each boundary is where temperature flips from falling to rising, or rising to falling."}, {"id": "seed-apes-u2-learn-atmosphere-2", "term": "Temperature pattern going up through the layers?", "def": "Troposphere ↓ cooler, stratosphere ↑ warmer, mesosphere ↓ cooler, thermosphere ↑ warmer.", "note": "Trick: down-up-down-up. The two layers that get warmer are the ones absorbing radiation: ozone absorbs UV in the stratosphere, and ions absorb it in the thermosphere.", "defImg": "seed/img/apes-u2-atmosphere.svg"}, {"id": "seed-apes-u2-learn-atmosphere-3", "term": "How high is the troposphere?", "def": "5.5–10.5 miles (lowest layer).", "note": "It's thinner at the poles and thicker at the equator."}, {"id": "seed-apes-u2-learn-atmosphere-4", "term": "Which layer contains ALL weather (clouds, rain)?", "def": "The troposphere.", "note": "It's also the densest layer, where we live and breathe. Temperature drops as you go up."}, {"id": "seed-apes-u2-learn-atmosphere-5", "term": "Composition of the troposphere (3 main gases)?", "def": "N₂ 78%, O₂ 21%, Ar 1%", "note": "Common trap: the most abundant gas is NITROGEN, not oxygen."}, {"id": "seed-apes-u2-learn-atmosphere-6", "term": "CO₂ in 1959 vs May 2021?", "def": "310 ppm (1959) → 419 ppm (2021).", "note": "That's about a 35% increase: (419−310)/310."}, {"id": "seed-apes-u2-learn-atmosphere-7", "term": "How fast are we adding CO₂ right now?", "def": "3–4 ppm per year."}, {"id": "seed-apes-u2-learn-atmosphere-8", "term": "What CO₂ limit does the IPCC say we must stay under, and what does it match?", "def": "Under 550 ppm, which matches the trillion-ton (carbon) cap and a 1.5 °C temperature change.", "note": "IPCC = Intergovernmental Panel on Climate Change."}, {"id": "seed-apes-u2-learn-atmosphere-9", "term": "Water vapor: greenhouse gas? Does it increase?", "def": "It IS a greenhouse gas, but it stays constant.", "note": "That's why the slides focus on CO₂ (rising) rather than water vapor (steady)."}, {"id": "seed-apes-u2-learn-atmosphere-10", "term": "What is the tropopause?", "def": "The temperature dividing line between the troposphere and the stratosphere."}, {"id": "seed-apes-u2-learn-atmosphere-11", "term": "How high is the stratosphere?", "def": "Up to ~32 miles."}, {"id": "seed-apes-u2-learn-atmosphere-12", "term": "Why is the stratosphere WARMER than the troposphere?", "def": "Ozone (O₃) there absorbs UV radiation.", "note": "The ozone layer is Earth's sunscreen. Absorbing UV heats the layer, so temperature rises with height."}, {"id": "seed-apes-u2-learn-atmosphere-13", "term": "How much mixing is there between the troposphere and stratosphere?", "def": "Very little.", "note": "Pollutants that reach the stratosphere (like CFCs) stay there a long time."}, {"id": "seed-apes-u2-learn-atmosphere-14", "term": "Where is the jet stream (per the slides), and why does it matter?", "def": "The stratosphere. Upper-layer winds control ground-level weather.", "note": "Many sources put it right at the tropopause, but answer \"stratosphere\" for this class."}, {"id": "seed-apes-u2-learn-atmosphere-15", "term": "Mesosphere: height and temperature trend?", "def": "32–50 miles; temperature DECREASES with height.", "note": "Meteors burn up here."}, {"id": "seed-apes-u2-learn-atmosphere-16", "term": "Thermosphere: other name, height, temperature trend, and why?", "def": "Ionosphere; 51–310 miles; temperature INCREASES because ions absorb solar radiation.", "note": "The auroras (northern and southern lights) happen here."}, {"id": "seed-apes-u2-learn-atmosphere-17", "term": "What is the exosphere?", "def": "Space (the outermost layer).", "note": "Satellites orbit here."}, {"id": "seed-apes-u2-learn-atmosphere-18", "term": "Which layer? (a) meteors burn up (b) aurora (c) ozone layer (d) all weather (e) satellites", "def": "(a) mesosphere (b) thermosphere (c) stratosphere (d) troposphere (e) exosphere", "defImg": "seed/img/apes-u2-atmosphere.svg"}]}, {"id": "seed-apes-u2-learn-climate", "rev": 1, "title": "APES Unit 2 — LEARN 2: Climate & Weather", "folder": "APES", "description": "Slides II: weather vs climate, air circulation, Hadley cells, Coriolis, hurricanes, rain shadow, El Niño, ocean currents, seasons. One fact per card: question → short answer, with the why, a memory trick, or the common trap in the note.", "cards": [{"id": "seed-apes-u2-learn-climate-0", "term": "Weather vs. climate?", "def": "WEATHER = short-term conditions in a local area. CLIMATE = average daily weather over an extended period of time over a larger region.", "note": "Tests give an example and ask which one it is: \"It's 90 °F in Phoenix today\" is weather; \"Phoenix averages 8 in. of rain a year\" is climate."}, {"id": "seed-apes-u2-learn-climate-1", "term": "What drives weather?", "def": "Temperature differences caused by differential (uneven) heating of the Earth."}, {"id": "seed-apes-u2-learn-climate-2", "term": "Why is the Earth heated unevenly? (3 reasons)", "def": "1) The angle of the Sun's rays 2) the surface area the rays spread over 3) albedo (some surfaces reflect more).", "note": "Think of a flashlight: aimed straight down it makes a small, bright spot (the equator); tilted, it makes a big, dim spot (the poles)."}, {"id": "seed-apes-u2-learn-climate-3", "term": "What is albedo? High-albedo vs low-albedo examples?", "def": "The % of sunlight a surface reflects. HIGH: fresh snow, ice. LOW: asphalt, forest, open ocean.", "note": "Melting ice exposes dark water, which absorbs more heat and melts more ice. That's a positive feedback loop."}, {"id": "seed-apes-u2-learn-climate-4", "term": "What do temperature differences cause in the atmosphere?", "def": "Convection, which creates high and low pressure areas."}, {"id": "seed-apes-u2-learn-climate-5", "term": "Why do winds blow?", "def": "To correct imbalances in atmospheric pressure and redistribute the Sun's energy.", "note": "Wind flows from HIGH pressure to LOW pressure."}, {"id": "seed-apes-u2-learn-climate-6", "term": "Why does the weather change in an area from day to day?", "def": "High and low pressure cells (or ridges) move over the region, and air masses move through them."}, {"id": "seed-apes-u2-learn-climate-7", "term": "Rising air vs sinking air: pressure, clouds, rain?", "def": "RISING air = LOW pressure → cools → clouds + rain. SINKING air = HIGH pressure → warms → clear + dry.", "note": "This one rule explains rainforests, deserts, and most weather. Rising air means rain."}, {"id": "seed-apes-u2-learn-climate-8", "term": "Why does rising air make rain?", "def": "Rising air expands and cools (adiabatic cooling). Cool air holds less water (lower saturation point), so the vapor condenses into clouds and rain.", "note": "Warm air is a big sponge and cold air is a small sponge. Shrink the sponge and the water gets squeezed out."}, {"id": "seed-apes-u2-learn-climate-9", "term": "Why is sinking air dry?", "def": "Sinking air is compressed and warms (adiabatic heating), so it can hold MORE water and nothing condenses."}, {"id": "seed-apes-u2-learn-climate-10", "term": "What is the Coriolis effect?", "def": "The deflection of wind and water caused by the rotation of the Earth."}, {"id": "seed-apes-u2-learn-climate-11", "term": "Coriolis: which way do storms (low-pressure systems) spin in each hemisphere?", "def": "COUNTERCLOCKWISE in the Northern Hemisphere; CLOCKWISE in the Southern Hemisphere."}, {"id": "seed-apes-u2-learn-climate-12", "term": "Does the Coriolis effect make toilets swirl the other way in the Southern Hemisphere?", "def": "No. Coriolis only matters over huge distances; toilets and sinks are far too small.", "note": "From the video \"The Truth about Toilet Swirl.\""}, {"id": "seed-apes-u2-learn-climate-13", "term": "Name the 3 global air circulation cells and their latitudes.", "def": "Hadley cells 0–30°, Ferrel cells 30–60°, Polar cells 60–90° (in each hemisphere).", "defImg": "seed/img/apes-u2-circulation.svg"}, {"id": "seed-apes-u2-learn-climate-14", "term": "Where does air RISE and where does it SINK globally?", "def": "RISES at 0° (equator) and 60°, so those are wet. SINKS at 30° and the poles (90°), so those are dry.", "note": "Trick: 0 and 60 are wet; 30 and 90 are dry.", "defImg": "seed/img/apes-u2-circulation.svg"}, {"id": "seed-apes-u2-learn-climate-15", "term": "Name the surface winds in each latitude band.", "def": "Trade winds 0–30°, westerlies 30–60°, polar easterlies 60–90°.", "note": "The U.S. is in the westerlies, which is why weather here moves west to east.", "defImg": "seed/img/apes-u2-circulation.svg"}, {"id": "seed-apes-u2-learn-climate-16", "term": "What is the ITCZ?", "def": "The Intertropical Convergence Zone: the latitude getting the most direct sunlight, where the trade winds meet and air rises. It's a rainy belt.", "note": "It moves north and south with the seasons, which causes wet and dry seasons in the tropics."}, {"id": "seed-apes-u2-learn-climate-17", "term": "HADLEY CELL at the EQUATOR: the 6 \"describe\" answers (air, what happens, rain, pressure, clouds, temperature).", "def": "Air RISES → expands and cools → condenses → HEAVY rain → LOW pressure → CLOUDY → hot all year = TROPICAL RAINFOREST.", "note": "Slide 14 asks exactly these six questions, so memorize them as a checklist.", "defImg": "seed/img/apes-u2-hadley.svg"}, {"id": "seed-apes-u2-learn-climate-18", "term": "HADLEY CELL at 30° N and S: the 6 \"describe\" answers.", "def": "Air SINKS → compresses and warms → dry → LITTLE rain → HIGH pressure → CLEAR skies → hot days, cold nights = DESERTS.", "note": "That's why the Sahara, Arabian, Mojave, and Australian deserts all sit near 30°.", "defImg": "seed/img/apes-u2-hadley.svg"}, {"id": "seed-apes-u2-learn-climate-19", "term": "Why are there big forests (temperate and boreal) around 60° latitude?", "def": "Air rises again at ~60° (where Ferrel and Polar cells meet), giving low pressure and precipitation."}, {"id": "seed-apes-u2-learn-climate-20", "term": "What causes hurricanes?", "def": "Low pressure systems driven by heat from the ocean.", "note": "Warm ocean water is the fuel. As low-pressure systems, they spin counterclockwise in the Northern Hemisphere."}, {"id": "seed-apes-u2-learn-climate-21", "term": "How is climate change affecting hurricanes?", "def": "The number of Category 4 and 5 hurricanes is increasing as climate change warms the oceans."}, {"id": "seed-apes-u2-learn-climate-22", "term": "What is orographic precipitation?", "def": "As air masses travel over mountain ranges they are pushed up and cooled, causing precipitation.", "defImg": "seed/img/apes-u2-rainshadow.svg"}, {"id": "seed-apes-u2-learn-climate-23", "term": "What is a rain shadow, and which side of the mountain is it on?", "def": "The dry area on the DOWNWIND (leeward) side of a mountain range. The air already dropped its rain on the windward side and warms as it sinks.", "note": "Example: Seattle (windward, west of the Cascades) gets ~37 in./yr, while Moses Lake (leeward, east) gets ~8 in./yr.", "defImg": "seed/img/apes-u2-rainshadow.svg"}, {"id": "seed-apes-u2-learn-climate-24", "term": "Windward vs leeward side: which is wet?", "def": "WINDWARD (facing the wind, where air rises) = wet. LEEWARD (downwind, where air sinks) = dry rain shadow.", "defImg": "seed/img/apes-u2-rainshadow.svg"}, {"id": "seed-apes-u2-learn-climate-25", "term": "What is El Niño (ENSO)?", "def": "A periodic weakening of the trade winds, which results in warming of the Pacific Ocean off the coast of Peru.", "note": "ENSO = El Niño Southern Oscillation.", "defImg": "seed/img/apes-u2-enso.svg"}, {"id": "seed-apes-u2-learn-climate-26", "term": "NORMAL Pacific pattern (no El Niño)?", "def": "Strong trade winds push warm surface water WEST toward Australia and Indonesia (rain there). Off Peru, cold water upwells, bringing nutrients and lots of fish.", "defImg": "seed/img/apes-u2-enso.svg"}, {"id": "seed-apes-u2-learn-climate-27", "term": "What happens to upwelling and fish off Peru during El Niño?", "def": "Upwelling weakens or stops, so fewer nutrients reach the surface and fish populations drop.", "note": "Warm, nutrient-poor water sits on top, which hurts Peru's anchovy fishery."}, {"id": "seed-apes-u2-learn-climate-28", "term": "The 4 global effects of El Niño (from the slide)?", "def": "1) Warm, dry winters in the NORTHWESTERN U.S. 2) Cool, wet winters in the SOUTHWESTERN U.S. 3) Flooding in Peru 4) Drought in Australia and Indonesia.", "note": "Trick: everything flips. Normally wet places (Australia, Indonesia) dry out, normally dry places (Peru) flood, and the U.S. Northwest is dry while the Southwest is wet."}, {"id": "seed-apes-u2-learn-climate-29", "term": "La Niña?", "def": "The opposite of El Niño: trade winds are STRONGER than normal. Water off Peru is colder, there's more upwelling, Australia and Indonesia are wetter, and Peru is drier."}, {"id": "seed-apes-u2-learn-climate-30", "term": "What was the \"climatic shift of 1976–77\"?", "def": "An abrupt change in ENSO behavior that has persisted to the present: more frequent and persistent El Niños rather than the cooler La Niñas."}, {"id": "seed-apes-u2-learn-climate-31", "term": "Is the 1976–77 ENSO shift caused by climate change?", "def": "UNCLEAR. It's highly unusual for the last 130 years of instrument records, but its link to climate change is not proven."}, {"id": "seed-apes-u2-learn-climate-32", "term": "What are gyres, and which way do they rotate?", "def": "Large-scale circular patterns of surface ocean water. CLOCKWISE in the Northern Hemisphere, COUNTERCLOCKWISE in the Southern Hemisphere.", "note": "The slide points out this is the OPPOSITE of the storm (Coriolis) direction. Common trap: storms go counterclockwise in the north, gyres go clockwise.", "defImg": "seed/img/apes-u2-gyres.svg"}, {"id": "seed-apes-u2-learn-climate-33", "term": "Which coasts get COLD currents, and what's the effect?", "def": "WEST coasts of continents get cold water from the poles, which cools the land next to them.", "note": "Example: the California coast is chilly even in summer.", "defImg": "seed/img/apes-u2-gyres.svg"}, {"id": "seed-apes-u2-learn-climate-34", "term": "Which coasts get WARM currents, and what's the effect?", "def": "EAST coasts of continents get warm water from the equator, which warms the land next to them.", "note": "Example: the Gulf Stream along the U.S. East Coast.", "defImg": "seed/img/apes-u2-gyres.svg"}, {"id": "seed-apes-u2-learn-climate-35", "term": "Where do upwellings occur, and what do they cause?", "def": "Along WEST coasts of most continents, bringing increased nutrients and fish populations.", "note": "Deep, cold, nutrient-rich water rises to replace surface water pushed away. Peru and California are examples."}, {"id": "seed-apes-u2-learn-climate-36", "term": "What is thermohaline circulation?", "def": "Cold, salty water SINKS at high latitudes and warm water RISES near the equator, making a global loop (\"The Great Conveyor Belt\").", "note": "Thermo means heat and haline means salt. Cold, salty water is dense, so it sinks.", "defImg": "seed/img/apes-u2-thermohaline.svg"}, {"id": "seed-apes-u2-learn-climate-37", "term": "Thermohaline example from the slide?", "def": "The Gulf Stream warms England, while Newfoundland (at about the same latitude) is cooled by the North Atlantic current."}, {"id": "seed-apes-u2-learn-climate-38", "term": "How could climate change affect thermohaline circulation?", "def": "It could SHUT IT DOWN. Melting ice adds fresh water, which makes the North Atlantic less salty and less dense, so it doesn't sink.", "note": "If that happened, England and northern Europe would get much colder."}, {"id": "seed-apes-u2-learn-climate-39", "term": "What causes seasons?", "def": "Earth's axis is tilted 23.5°, so the angle of the Sun's rays and the day length change through the year.", "note": "Common trap: seasons are NOT caused by distance from the Sun.", "defImg": "seed/img/apes-u2-seasons.svg"}, {"id": "seed-apes-u2-learn-climate-40", "term": "The 4 key facts about why we have seasons and biomes (slide).", "def": "1) Earth orbits the Sun on a plane called the ECLIPTIC 2) the axis is tilted 23.5° 3) the axis stays parallel to itself throughout the orbit 4) heat received depends on the ANGLE of the rays and the LENGTH of the days.", "defImg": "seed/img/apes-u2-seasons.svg"}, {"id": "seed-apes-u2-learn-climate-41", "term": "Dates: summer solstice, autumnal equinox, winter solstice, vernal equinox?", "def": "Summer solstice June 21; autumnal equinox Sept 22; winter solstice Dec 21; vernal (spring) equinox March 20.", "note": "The solstices are the longest and shortest days. On the equinoxes, day and night are equal and the Sun is overhead at the equator."}, {"id": "seed-apes-u2-learn-climate-42", "term": "On June 21, what season is it in Australia, and why?", "def": "WINTER. The Southern Hemisphere is tilted AWAY from the Sun, so its rays are less direct and its days are shorter."}]}, {"id": "seed-apes-u2-learn-biomes", "rev": 1, "title": "APES Unit 2 — LEARN 3: Land Biomes", "folder": "APES", "description": "Slides III: biome basics, climatograms, altitude-latitude, Powell, and all 9 terrestrial biomes. One fact per card: question → short answer, with the why, a memory trick, or the common trap in the note.", "cards": [{"id": "seed-apes-u2-learn-biomes-0", "term": "What is a biome?", "def": "A climax community with a wide geographic distribution, identified by TEMPERATURE, RAINFALL, and DOMINANT PLANT TYPES.", "note": "Climax community means the stable end stage of succession."}, {"id": "seed-apes-u2-learn-biomes-1", "term": "What 2 climate factors mostly determine which biome forms?", "def": "Temperature and precipitation.", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-learn-biomes-2", "term": "How do you read a climatogram (climate diagram)?", "def": "The shaded area is the growing season (above 0 °C). If precipitation is ABOVE temperature, growth is limited by TEMPERATURE. If precipitation is BELOW temperature, growth is limited by PRECIPITATION.", "note": "The Identify-the-Biome deck drills this with real data.", "defImg": "seed/img/apes-u2-clim-howto.svg"}, {"id": "seed-apes-u2-learn-biomes-3", "term": "What is the altitude-latitude analogy?", "def": "Going UP in altitude is like going north or south in LATITUDE: it gets colder and the biomes change with temperature.", "note": "Climb a tall mountain and you pass through forest, then boreal-like forest, then alpine tundra, just like driving toward the pole."}, {"id": "seed-apes-u2-learn-biomes-4", "term": "Environmental lapse rate (dry vs wet air)?", "def": "Lose 5.5 °F per 1,000 ft for DRY air and 3.0 °F per 1,000 ft for WET air as you go up.", "note": "Math example: climbing 4,000 ft in dry air gives 4 × 5.5 = 22 °F colder."}, {"id": "seed-apes-u2-learn-biomes-5", "term": "Why does it get colder as you go up? (3 steps from the slide)", "def": "1) Gases are compressible, so more pressure makes them denser. 2) Less atmosphere above you means less pressure, so the air is less dense. 3) Fewer air molecules means fewer collisions, which means less heat transfer.", "note": "Short version: thinner air holds less heat."}, {"id": "seed-apes-u2-learn-biomes-6", "term": "Who was John Wesley Powell, and what did he warn?", "def": "An explorer (he lost an arm in the Civil War and rode the Colorado River strapped into a chair). In his 1878 Report on the Lands of the Arid Region he warned that settlers would have to learn to live with very little precipitation WEST OF THE 100TH MERIDIAN.", "note": "Which cities ignored his warning? Los Angeles and Phoenix."}, {"id": "seed-apes-u2-learn-biomes-7", "term": "Why is the 100th meridian important?", "def": "It roughly divides the humid eastern U.S. from the arid West, which makes it key to understanding America's ecology (farming, water, biomes)."}, {"id": "seed-apes-u2-learn-biomes-8", "term": "Which biomes store lots of carbon in the SOIL, and why?", "def": "Tundra and boreal forest. The cold slows decomposition, so dead material builds up.", "note": "Tropical rainforests store their carbon in living PLANTS instead, because decomposition there is fast. Thawing permafrost releases greenhouse gases."}, {"id": "seed-apes-u2-learn-biomes-9", "term": "TUNDRA: climate + key features?", "def": "Very cold, dry, treeless; PERMAFROST (permanently frozen subsoil); short ~4-month growing season. Plants: mosses, lichens, low shrubs.", "note": "Animals: muskoxen, arctic foxes. Alpine tundra forms on high mountains (the altitude analogy).", "defImg": "seed/img/apes-u2-clim-tundra.svg"}, {"id": "seed-apes-u2-learn-biomes-10", "term": "What is permafrost, and why does it matter?", "def": "A permanently frozen soil layer under the tundra. It stops water draining and roots growing, and warming melts it, releasing CO₂ and methane."}, {"id": "seed-apes-u2-learn-biomes-11", "term": "TAIGA / BOREAL FOREST: climate + key features?", "def": "Long, very cold winters and short summers; CONIFEROUS evergreens (pine, spruce, fir); ~50–60° N. The needles decompose slowly, so the soil is acidic and nutrient-poor.", "note": "Animals: moose, bears, wolverines. Heavily logged for paper and lumber.", "defImg": "seed/img/apes-u2-clim-boreal.svg"}, {"id": "seed-apes-u2-learn-biomes-12", "term": "TEMPERATE RAINFOREST: where is it found? (slide list)", "def": "Coastal northern California, Oregon, Washington, British Columbia, southern Alaska; Scotland, Australia, New Zealand, and the southwest coast of Chile."}, {"id": "seed-apes-u2-learn-biomes-13", "term": "Why is a temperate rainforest so rainy?", "def": "It's always coastal and/or mountainous. Moist ocean air is forced over the mountains, cools, and precipitation forms (orographic precipitation)."}, {"id": "seed-apes-u2-learn-biomes-14", "term": "Temperate rainforest: annual rainfall?", "def": "50–120 inches per year."}, {"id": "seed-apes-u2-learn-biomes-15", "term": "Why are there mosses, ferns, and nurse trees in the temperate rainforest?", "def": "The cool climate slows evaporation, so it stays moist. Nurse trees (fallen logs) are common, and mosses and ferns grow on the surface of trees.", "note": "Plants growing on trees are a classic COMMENSALISM example."}, {"id": "seed-apes-u2-learn-biomes-16", "term": "Which place on Earth has the greatest biomass?", "def": "The temperate rainforest: up to 500 tons of biomass per acre.", "note": "Common trap: tropical rainforests have the most BIODIVERSITY, but temperate rainforests have the most BIOMASS."}, {"id": "seed-apes-u2-learn-biomes-17", "term": "How old are trees in old-growth temperate rainforest?", "def": "800 years old."}, {"id": "seed-apes-u2-learn-biomes-18", "term": "Common temperate rainforest animals?", "def": "Slugs, elk, black-tailed deer, bears, beaver, owls, and salmon."}, {"id": "seed-apes-u2-learn-biomes-19", "term": "Temperate rainforest: 3 human impacts?", "def": "1) At least half has been logged 2) many remaining forests are scheduled to be logged 3) some patches are protected as homes of the endangered NORTHERN SPOTTED OWL and MARBLED MURRELET."}, {"id": "seed-apes-u2-learn-biomes-20", "term": "TEMPERATE SEASONAL (DECIDUOUS) FOREST: climate + key features?", "def": "Warm summers, cold winters, rain spread through the year (over 1 m). Broadleaf trees that drop their leaves (oak, maple, beech). The leaves decompose fast, so the soil is fertile.", "note": "Found in the eastern U.S. and Europe. Much of it was cleared for farms.", "defImg": "seed/img/apes-u2-clim-tempseas.svg"}, {"id": "seed-apes-u2-learn-biomes-21", "term": "WOODLAND / SHRUBLAND (chaparral, Mediterranean): climate + key features?", "def": "Hot, DRY SUMMERS and mild, RAINY WINTERS. Fire-adapted shrubs that resprout or have seeds that need fire.", "note": "Found in southern California, the Mediterranean, Chile, SW Australia, and South Africa. The giveaway is rain in WINTER.", "defImg": "seed/img/apes-u2-clim-woodland.svg"}, {"id": "seed-apes-u2-learn-biomes-22", "term": "TEMPERATE GRASSLAND / COLD DESERT: climate + key features?", "def": "Cold winters, hot dry summers, too dry for trees. Deep-rooted grasses; fires and grazing keep trees out. Very fertile soil, so most of it is now farmland.", "note": "The Great Plains prairie, pampas, and steppes. In the rain shadow it becomes cold desert (eastern Washington).", "defImg": "seed/img/apes-u2-clim-grassland.svg"}, {"id": "seed-apes-u2-learn-biomes-23", "term": "TROPICAL RAINFOREST: climate + key features?", "def": "Hot and wet ALL year, within ~20° of the equator. The MOST biodiversity. Nutrients are locked in the plants, so the soil is POOR, and cleared land loses fertility fast.", "note": "Layers: canopy, understory, epiphytes, vines. The main threat is deforestation.", "defImg": "seed/img/apes-u2-clim-troprain.svg"}, {"id": "seed-apes-u2-learn-biomes-24", "term": "TROPICAL SEASONAL FOREST / SAVANNA: climate + key features?", "def": "Hot all year with a distinct WET season and DRY season (caused by the ITCZ moving). Grasses with scattered trees; fire and grazing keep it open.", "note": "African savanna: zebras, lions, acacia and baobab trees.", "defImg": "seed/img/apes-u2-clim-savanna.svg"}, {"id": "seed-apes-u2-learn-biomes-25", "term": "SUBTROPICAL DESERT: climate + key features?", "def": "At ~30° N and S, where Hadley-cell air sinks. Hot and extremely dry. Cacti and succulents with spines, waxy coats, and water-storing stems.", "note": "Sahara, Mojave, Arabian deserts.", "defImg": "seed/img/apes-u2-clim-desert.svg"}, {"id": "seed-apes-u2-learn-biomes-26", "term": "Cold desert vs hot (subtropical) desert: how do you tell them apart?", "def": "COLD desert has freezing winters and comes from a rain shadow. HOT desert is warm all year and comes from Hadley-cell sinking air at 30°."}, {"id": "seed-apes-u2-learn-biomes-27", "term": "Which biome? Wet winters, dry summers, frequent fires.", "def": "Woodland/shrubland (chaparral)."}, {"id": "seed-apes-u2-learn-biomes-28", "term": "Which biome? Permafrost, no trees, mosses and lichens.", "def": "Tundra."}, {"id": "seed-apes-u2-learn-biomes-29", "term": "Which biome? Huge mossy trees, 50–120 in. of rain, coastal mountains.", "def": "Temperate rainforest."}, {"id": "seed-apes-u2-learn-biomes-30", "term": "Which biome? Hot all year, rainy season and long dry season, grass with scattered trees.", "def": "Tropical seasonal forest / savanna."}, {"id": "seed-apes-u2-learn-biomes-31", "term": "Which biome? Conifers, very cold winters, acidic nutrient-poor soil.", "def": "Taiga / boreal forest."}, {"id": "seed-apes-u2-learn-biomes-32", "term": "Which biome? Richest soil in the world, too dry for trees, now mostly farms.", "def": "Temperate grassland."}, {"id": "seed-apes-u2-learn-biomes-33", "term": "Which biome has the most biodiversity, and which has the most biomass?", "def": "Most BIODIVERSITY: tropical rainforest. Most BIOMASS: temperate rainforest (per the slides)."}]}, {"id": "seed-apes-u2-learn-aquatic", "rev": 1, "title": "APES Unit 2 — LEARN 4: Aquatic Biomes", "folder": "APES", "description": "Slides IV: ocean zones, deep sea, coral, mangroves, estuaries, lakes, DO, wetlands, rivers, human impacts. One fact per card: question → short answer, with the why, a memory trick, or the common trap in the note.", "cards": [{"id": "seed-apes-u2-learn-aquatic-0", "term": "What is the pelagic zone?", "def": "The open ocean ABOVE the sea floor (the water column).", "defImg": "seed/img/apes-u2-ocean.svg"}, {"id": "seed-apes-u2-learn-aquatic-1", "term": "What 2 factors determine productivity in the ocean?", "def": "1) LIGHT penetration 2) inorganic NUTRIENTS (nitrogen and phosphorus).", "note": "Algae need sunlight and fertilizer, just like land plants."}, {"id": "seed-apes-u2-learn-aquatic-2", "term": "What is the euphotic zone, and how deep can it go?", "def": "The sunlit layer where photosynthesis can happen. It may extend to 200 m in very clear water.", "note": "Below it is the aphotic zone, with no light.", "defImg": "seed/img/apes-u2-ocean.svg"}, {"id": "seed-apes-u2-learn-aquatic-3", "term": "Which ocean areas are most productive, and why?", "def": "Current UPWELLINGS and RIVER MOUTHS, because they supply the most nutrients (N and P).", "note": "The open ocean is like a desert: lots of light but few nutrients."}, {"id": "seed-apes-u2-learn-aquatic-4", "term": "What are pelagic organisms?", "def": "Organisms NOT anchored to the sea floor that drift in the water column."}, {"id": "seed-apes-u2-learn-aquatic-5", "term": "Phytoplankton vs zooplankton?", "def": "PHYTOPLANKTON = microscopic floating algae (autotrophs, few move on their own). ZOOPLANKTON = microscopic animals that eat phytoplankton (heterotrophs, most move).", "note": "Together they form the base of the ocean food chain. Phyto means plant; zoo means animal."}, {"id": "seed-apes-u2-learn-aquatic-6", "term": "What is the benthic zone?", "def": "The sea floor, either shallow or deep.", "defImg": "seed/img/apes-u2-ocean.svg"}, {"id": "seed-apes-u2-learn-aquatic-7", "term": "Benthic organisms: which are anchored and which aren't (slide examples)?", "def": "ANCHORED: kelp, urchins, anemones. NOT anchored: clams, crabs, flounder, halibut.", "note": "Flounder and halibut swim, but they live on the bottom, so they're still benthic."}, {"id": "seed-apes-u2-learn-aquatic-8", "term": "How does substrate affect benthic ecosystems? (sand, mud, rock)", "def": "SHIFTING SAND: large plants and algae can't get established. MUD: little oxygen, but good for some rooted plants. ROCK: a good substrate for many kinds of algae.", "note": "Substrate means the bottom material. Life needs something stable to hold onto."}, {"id": "seed-apes-u2-learn-aquatic-9", "term": "Deep sea (abyssal) zone: where does energy come from without light?", "def": "Autotrophs are CHEMOSYNTHESIZERS that get energy from methane (CH₄) and hydrogen sulfide (H₂S), for example at hydrothermal vents.", "note": "Chemosynthesis means making food from chemicals instead of sunlight."}, {"id": "seed-apes-u2-learn-aquatic-10", "term": "What do most deep-sea organisms depend on for food?", "def": "The constant rain of organic matter (dead stuff) sinking from the photic zone above."}, {"id": "seed-apes-u2-learn-aquatic-11", "term": "Deep-sea animals: typical traits?", "def": "Usually scavengers; many are small and generate light (bioluminescence) to find or attract food.", "note": "Example: the anglerfish in Finding Nemo."}, {"id": "seed-apes-u2-learn-aquatic-12", "term": "Deep sea: how much of Earth's surface does it cover?", "def": "About 60%, making it the LARGEST ecosystem on the planet."}, {"id": "seed-apes-u2-learn-aquatic-13", "term": "Deep sea: 3 ecosystem services?", "def": "Nutrient recycling, carbon burial, and controlling ocean chemistry."}, {"id": "seed-apes-u2-learn-aquatic-14", "term": "Deep sea: the 7 microhabitats (know at least 5)?", "def": "Rocky mid-ocean ridges; submarine canyons; trenches and seamounts; chemoautotrophic cold seeps; hydrothermal vents; whale-falls; sediment-dominated continental slopes and abyssal plains."}, {"id": "seed-apes-u2-learn-aquatic-15", "term": "Why is it hard to protect the deep sea?", "def": "Our knowledge of deep-sea diversity is rudimentary (basic), and that lack of knowledge hinders efforts to protect it from advancing human exploration."}, {"id": "seed-apes-u2-learn-aquatic-16", "term": "Where do coral reefs form?", "def": "Around islands and along coasts with WARM, CLEAR water (example: the Great Barrier Reef).", "note": "The water must be clear because the coral's algae need sunlight."}, {"id": "seed-apes-u2-learn-aquatic-17", "term": "What is a coral?", "def": "An ANIMAL with a body structure called a POLYP, closely related to sea anemones."}, {"id": "seed-apes-u2-learn-aquatic-18", "term": "Coral: nematocysts vs zooxanthellae?", "def": "NEMATOCYSTS = stinging cells in the tentacles that catch zooplankton. ZOOXANTHELLAE = single-celled algae living inside the coral that photosynthesize and give it food.", "note": "Coral + zooxanthellae is the textbook example of MUTUALISM: both benefit."}, {"id": "seed-apes-u2-learn-aquatic-19", "term": "How are reefs built?", "def": "Each polyp makes its own calcium carbonate (CaCO₃) cup. Over thousands of years these build up into reefs."}, {"id": "seed-apes-u2-learn-aquatic-20", "term": "What is coral bleaching?", "def": "Corals expel their zooxanthellae, usually because of warm water (also acidity or pollution). They turn white and can starve.", "note": "Climate change warms the water and ocean acidification dissolves CaCO₃, so reefs get hit twice."}, {"id": "seed-apes-u2-learn-aquatic-21", "term": "Where do mangrove swamps form?", "def": "Along TROPICAL coasts with warm, shallow water and not too much wave action (Florida, the Caribbean, Southeast Asia, Africa)."}, {"id": "seed-apes-u2-learn-aquatic-22", "term": "What do mangroves do for the land?", "def": "Their roots TRAP SEDIMENT and EXTEND LAND into shallow seas.", "note": "They also block storm surges and shelter young fish."}, {"id": "seed-apes-u2-learn-aquatic-23", "term": "What is an estuary?", "def": "A partially enclosed bay where a river meets the ocean, with BRACKISH water (a fresh and salt mix) and tidal conditions."}, {"id": "seed-apes-u2-learn-aquatic-24", "term": "How are estuary organisms adapted?", "def": "To VARYING salinity levels from tides and river flow."}, {"id": "seed-apes-u2-learn-aquatic-25", "term": "Why are estuaries so productive?", "def": "They're SHALLOW, WARM, and NUTRIENT-RICH (from rivers), and they often include salt marshes."}, {"id": "seed-apes-u2-learn-aquatic-26", "term": "What 2 other roles do estuaries play?", "def": "1) Important NURSERY sites for fish and crustaceans 2) great for AGRICULTURE because of their deltas."}, {"id": "seed-apes-u2-learn-aquatic-27", "term": "5 human impacts on marine ecosystems?", "def": "1) OVERFISHING destroyed traditional fishing industries 2) FISH FARMING adds nutrients and spreads disease to wild fish 3) CONTAMINATED ESTUARIES from fertilizers, animal waste, and pesticides 4) SHIPPING WASTE: oil, human waste, toxins, trash 5) OFFSHORE OIL DRILLING spills (Deepwater Horizon)."}, {"id": "seed-apes-u2-learn-aquatic-28", "term": "What is limnology?", "def": "The study of fresh water ecosystems."}, {"id": "seed-apes-u2-learn-aquatic-29", "term": "The 2 categories of freshwater ecosystems?", "def": "STATIONARY water: lakes, ponds, reservoirs, wetlands. RUNNING water: streams and rivers."}, {"id": "seed-apes-u2-learn-aquatic-30", "term": "Lake zones: littoral vs limnetic?", "def": "LITTORAL = shallow zone near shore WITH rooted plants. LIMNETIC = open water with NO rooted plants (only phytoplankton).", "note": "Trick: Littoral = Land edge.", "defImg": "seed/img/apes-u2-lake.svg"}, {"id": "seed-apes-u2-learn-aquatic-31", "term": "What is a reservoir?", "def": "An artificial lake behind a dam."}, {"id": "seed-apes-u2-learn-aquatic-32", "term": "3 effects of reservoirs?", "def": "1) They eventually FILL IN with sediment 2) high dams with deep reservoirs turn warm rivers COLD (water released from the bottom) 3) they dramatically change the ecology of their watersheds."}, {"id": "seed-apes-u2-learn-aquatic-33", "term": "4 factors that affect freshwater productivity (photosynthesis)?", "def": "1) DEPTH: shallow water promotes PS 2) CLARITY: clear water promotes PS 3) NUTRIENTS: some increase PS, too many cause eutrophication and BOD 4) TEMPERATURE: colder water means slower PS.", "note": "PS = photosynthesis. More light, some nutrients, and warmth mean more growth."}, {"id": "seed-apes-u2-learn-aquatic-34", "term": "What INCREASES dissolved oxygen (DO)?", "def": "Wave action (mixing air in), photosynthesis, and COLD water.", "note": "Cold water holds more gas, which is why trout need cold, fast streams."}, {"id": "seed-apes-u2-learn-aquatic-35", "term": "What DECREASES dissolved oxygen?", "def": "Warm water, plus nutrients: eutrophication and BOD (biochemical oxygen demand)."}, {"id": "seed-apes-u2-learn-aquatic-36", "term": "Eutrophication: put the steps in order.", "def": "Excess nutrients (N, P) → algae bloom → algae die → decomposers use up oxygen (high BOD) → low DO → fish die (dead zone).", "note": "BOD is how much oxygen the decomposers demand. High BOD means low DO."}, {"id": "seed-apes-u2-learn-aquatic-37", "term": "Colder water: more or less DO? Faster or slower photosynthesis?", "def": "MORE dissolved oxygen, but SLOWER photosynthesis.", "note": "Both are on the slides, and tests like to pair them."}, {"id": "seed-apes-u2-learn-aquatic-38", "term": "Swamp vs marsh vs bog?", "def": "SWAMP = wetland with TREES (bald cypress swamps, southern Texas). MARSH = GRASSES and reeds (Evans Creek Preserve). BOG = build-up of MOSS (Ireland's peat bogs).", "note": "Trick: Swamp = Sticks (trees), Marsh = Meadow (grass), Bog = Bryophytes (moss)."}, {"id": "seed-apes-u2-learn-aquatic-39", "term": "Benefits of wetlands?", "def": "They store water and reduce flooding, recharge groundwater, filter pollutants, provide habitat and nurseries (fish, birds, amphibians), prevent erosion, and store carbon.", "note": "The slide's list was blank in the PDF, so check your class notes. These are the textbook's benefits."}, {"id": "seed-apes-u2-learn-aquatic-40", "term": "Streams: why don't nutrients build up, and where does food come from?", "def": "The faster the water, the harder it is for nutrients to accumulate. Most debris (food) comes from TERRESTRIAL sources, like leaves falling in."}, {"id": "seed-apes-u2-learn-aquatic-41", "term": "What is periphyton?", "def": "The collection of algae, animals, and fungi attached to rocks and other objects on a stream bottom.", "note": "It's the slimy coating on river rocks."}, {"id": "seed-apes-u2-learn-aquatic-42", "term": "What is the riparian zone?", "def": "The land along a river's banks. Its plants PREVENT EROSION and PROVIDE SHADE (which keeps the water cool and high in DO)."}, {"id": "seed-apes-u2-learn-aquatic-43", "term": "4 human impacts on fresh water?", "def": "1) HABITAT DESTRUCTION: 50% of U.S. wetlands destroyed since the 1600s 2) SEWAGE: human sewage historically; now ANIMAL waste is the bigger threat 3) AIR POLLUTION through ACID RAIN 4) NUTRIENTS: urban and farm runoff cause eutrophication."}, {"id": "seed-apes-u2-learn-aquatic-44", "term": "What % of U.S. wetlands have been destroyed since the 1600s?", "def": "50%."}, {"id": "seed-apes-u2-learn-aquatic-45", "term": "Freshwater sewage pollution: what's the biggest threat now?", "def": "ANIMAL waste (historically it was human sewage)."}, {"id": "seed-apes-u2-learn-aquatic-46", "term": "What is Mai Po an example of?", "def": "A protected wetland (Hong Kong) with huge biodiversity: over 400 bird species, 250+ plant species, and many butterflies, crabs, and dragonflies.", "note": "It shows that wetlands are biodiversity hotspots."}]}, {"id": "seed-apes-u2-learn-biodiversity", "rev": 1, "title": "APES Unit 2 — LEARN 5: Preserving Biodiversity", "folder": "APES", "description": "Slides V: species counts, extinction rates, the 5 human causes, why save species, extinction-prone traits. One fact per card: question → short answer, with the why, a memory trick, or the common trap in the note.", "cards": [{"id": "seed-apes-u2-learn-biodiversity-0", "term": "How many eukaryotic species are there, and how many are identified?", "def": "~8.7 million species; only ~1.2 million identified.", "note": "Common trap: these are estimates from 2011 that were still current as of 2024."}, {"id": "seed-apes-u2-learn-biodiversity-1", "term": "What % of species are still undiscovered (land vs marine)?", "def": "86% of LAND species and 91% of MARINE species."}, {"id": "seed-apes-u2-learn-biodiversity-2", "term": "What is extinction?", "def": "The natural and human-caused process of organisms being driven out of existence."}, {"id": "seed-apes-u2-learn-biodiversity-3", "term": "What is the background extinction rate?", "def": "0.1 extinction per 1,000 species per millennium (natural causes)."}, {"id": "seed-apes-u2-learn-biodiversity-4", "term": "How fast are humans driving extinctions compared to background?", "def": "1,000 TIMES the background rate = 100 extinctions per 1,000 species per millennium.", "note": "Math: 0.1 × 1,000 = 100."}, {"id": "seed-apes-u2-learn-biodiversity-5", "term": "What counts as a MAJOR (mass) extinction event?", "def": "Losing 75% of species within a 2-million-year period.", "note": "We may be in the SIXTH great extinction, the first caused by humans (Peter Ward TED talk)."}, {"id": "seed-apes-u2-learn-biodiversity-6", "term": "The 5 human causes of extinction (MEA)?", "def": "1) HABITAT change 2) OVERexploitation 3) INVASIVE alien species 4) POLLUTION 5) CLIMATE change.", "note": "Trick: HIPPCO = Habitat, Invasives, Pollution, Population (human growth drives them all), Climate change, Overexploitation."}, {"id": "seed-apes-u2-learn-biodiversity-7", "term": "Habitat change: definition + examples?", "def": "Modification and destruction of land and water habitats. Examples: deforestation, agriculture, damming rivers.", "note": "This is the #1 cause of extinction."}, {"id": "seed-apes-u2-learn-biodiversity-8", "term": "Overexploitation (overharvesting)?", "def": "Taking resources from the Earth faster than they can be replenished.", "note": "Examples: overfishing, the passenger pigeon, bison, poaching rhinos."}, {"id": "seed-apes-u2-learn-biodiversity-9", "term": "Invasive alien species: definition + 4 slide examples?", "def": "Non-native species that outcompete the natives. Examples: dandelions, blackberries, kudzu, starlings.", "note": "They succeed because they have no natural predators or diseases in the new place."}, {"id": "seed-apes-u2-learn-biodiversity-10", "term": "Pollution as a cause of extinction?", "def": "Air, land, and water pollution degrades habitats and undermines the health of all organisms."}, {"id": "seed-apes-u2-learn-biodiversity-11", "term": "Climate change as a cause of extinction: which regions are hit hardest?", "def": "It impacts every ecosystem on Earth, but POLAR and EQUATORIAL regions most."}, {"id": "seed-apes-u2-learn-biodiversity-12", "term": "Which cause? Kudzu takes over southern forests.", "def": "Invasive alien species."}, {"id": "seed-apes-u2-learn-biodiversity-13", "term": "Which cause? A river is dammed and a fish loses its spawning grounds.", "def": "Habitat change."}, {"id": "seed-apes-u2-learn-biodiversity-14", "term": "Which cause? Cod are fished faster than they can reproduce.", "def": "Overexploitation (overharvesting)."}, {"id": "seed-apes-u2-learn-biodiversity-15", "term": "Which cause? Polar bears lose sea ice.", "def": "Climate change."}, {"id": "seed-apes-u2-learn-biodiversity-16", "term": "3 reasons to save species (slide)?", "def": "1) All organisms have an inherent RIGHT TO EXIST 2) extinctions DESTABILIZE and disrupt ecosystems 3) BENEFITS TO HUMANS (ecosystem services).", "note": "Reason 1 is INTRINSIC value. Reason 3 is INSTRUMENTAL value."}, {"id": "seed-apes-u2-learn-biodiversity-17", "term": "Traits that make a species extinction-prone?", "def": "Low reproductive rate, specialized niche or diet, narrow range, high trophic level (big predator), large territory, fixed migration, rare, commercially valuable.", "note": "Safest: fast-breeding generalists (rats, cockroaches). Riskiest: big, slow, picky, rare, valuable species (tigers, condors, pandas)."}]}, {"id": "seed-apes-u2-learn-ch18", "rev": 1, "title": "APES Unit 2 — LEARN 6: Ch 18 Textbook Extras", "folder": "APES", "description": "Textbook facts that show up on MCQs: genetic diversity, values, interactions, laws, island biogeography, reserves. One fact per card: question → short answer, with the why, a memory trick, or the common trap in the note.", "cards": [{"id": "seed-apes-u2-learn-ch18-0", "term": "3 levels of biodiversity?", "def": "Ecosystem diversity, species diversity, and genetic diversity."}, {"id": "seed-apes-u2-learn-ch18-1", "term": "Why is low genetic diversity dangerous?", "def": "Inbreeding depression (harmful genes show up) and less ability to adapt to disease or change.", "note": "Examples: cheetahs (a natural bottleneck) and Florida panthers (helped by bringing in Texas panthers)."}, {"id": "seed-apes-u2-learn-ch18-2", "term": "Intrinsic vs instrumental value?", "def": "INTRINSIC = worth existing for its own sake. INSTRUMENTAL = worth as a tool for humans (ecosystem services)."}, {"id": "seed-apes-u2-learn-ch18-3", "term": "5 categories of instrumental value?", "def": "Provisions (goods like food, lumber, medicine), regulating services (climate, carbon, water), support systems (pollination, water filtration), resilience, cultural services (recreation, beauty, science).", "note": "Example: New York City protecting the Catskills watershed instead of building a filtration plant is a SUPPORT SYSTEM."}, {"id": "seed-apes-u2-learn-ch18-4", "term": "Mutualism vs commensalism vs parasitism, with unit examples?", "def": "MUTUALISM (+/+): coral and zooxanthellae. COMMENSALISM (+/0): moss or epiphytes on trees. PARASITISM (+/−): brown-headed cowbird laying eggs in other birds' nests."}, {"id": "seed-apes-u2-learn-ch18-5", "term": "Endangered Species Act (1973)?", "def": "U.S. law: lists endangered and threatened species, bans harming them or trading their parts, and protects critical habitat.", "note": "Successes: bald eagle, gray wolf, California condor. Conflict: the northern spotted owl vs logging."}, {"id": "seed-apes-u2-learn-ch18-6", "term": "CITES vs Lacey Act vs Marine Mammal Protection Act?", "def": "CITES (1973) = INTERNATIONAL trade in endangered species. LACEY ACT (1900) = no shipping illegal wildlife BETWEEN STATES. MMPA (1972) = protects all marine mammals in U.S. waters."}, {"id": "seed-apes-u2-learn-ch18-7", "term": "Theory of island biogeography: which islands have the most species?", "def": "LARGE islands CLOSE to the mainland.", "note": "Parks work like islands, so build big reserves connected by habitat corridors.", "defImg": "seed/img/apes-u2-islands.svg"}, {"id": "seed-apes-u2-learn-ch18-8", "term": "Biosphere reserve zones?", "def": "CORE (protected) → BUFFER (research, tourism) → TRANSITION (people live and farm sustainably).", "defImg": "seed/img/apes-u2-reserve.svg"}, {"id": "seed-apes-u2-learn-ch18-9", "term": "What is habitat fragmentation, and what does it cause?", "def": "Breaking habitat into small pieces. It creates more EDGE habitat, which favors edge species like cowbirds and hurts interior species."}]}, {"id": "seed-apes-u2-biomeid", "rev": 1, "title": "APES Unit 2 — Identify the Biome (temperature + rainfall)", "folder": "APES", "description": "Learn to name the biome from monthly temperature/precipitation data or a climate diagram, like the graphing activity. Method cards first, then practice with real places.", "cards": [{"id": "seed-apes-u2-biomeid-0", "term": "STEP-BY-STEP: how to identify a biome from temperature + rainfall data", "def": "1) Find the AVERAGE TEMPERATURE: below ~5 °C = tundra or boreal; 5-20 °C = temperate; above 20 °C = tropical.\n2) Add up the TOTAL PRECIPITATION (mm ÷ 10 = cm) and use the biome chart.\n3) Look at the PATTERN: When is it wet? Is there a dry season? How cold is winter?\n4) Find the GROWING SEASON: the months above 0 °C.\n5) Find the LIMITING FACTOR: precipitation line above the temperature line = limited by temperature; below = limited by precipitation (rule: plants need 20 mm per 10 °C).\n6) Check the HEMISPHERE: warmest months in Dec-Feb means the Southern Hemisphere.", "note": "Same steps as the Nashville graphing activity and the Ch 4 FRQ: graph it, shade above 0 °C, compare the two lines, then name the biome.", "defImg": "seed/img/apes-u2-clim-howto.svg"}, {"id": "seed-apes-u2-biomeid-1", "term": "Average annual temperature groups (textbook)", "def": "Tundra and boreal: below 5 °C. Temperate: 5 to 20 °C. Tropical: above 20 °C.", "note": "Temperature picks the row; rainfall picks the biome inside the row.", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-biomeid-2", "term": "How do you graph a climate diagram yourself?", "def": "Months on the x-axis. Temperature (°C) on the left y-axis, precipitation (mm) on the right y-axis, scaled so 10 °C lines up with 20 mm (so 0 °C = 0 mm, 20 °C = 40 mm, 50 °C = 100 mm). Plot temperature as one line and precipitation as another. Shade months above 0 °C (the growing season).", "note": "Quick check without graphing: for each month, double the temperature. If precipitation (mm) is bigger than 2 × temp, that month is limited by temperature. If smaller, it is limited by precipitation."}, {"id": "seed-apes-u2-biomeid-3", "term": "Quick math check: is a month limited by temperature or by precipitation?", "def": "Multiply the temperature (°C) by 2. If precipitation (mm) > 2 × temp, there is enough water, so the month is limited by TEMPERATURE. If precipitation < 2 × temp, it is too dry, so it's limited by PRECIPITATION.", "note": "Example: July 25 °C and 30 mm. 2 × 25 = 50 and 30 < 50, so July is limited by precipitation."}, {"id": "seed-apes-u2-biomeid-4", "term": "Southern Hemisphere trick", "def": "If the warmest months are December, January and February, the place is in the Southern Hemisphere (seasons are reversed).", "note": "The Ch 4 FRQ biome (5-15 °C, warmest in January, 418-717 mm every month) is a temperate rainforest in the Southern Hemisphere, e.g. southern Chile or New Zealand."}, {"id": "seed-apes-u2-biomeid-5", "term": "Textbook Fig 12.2 ranges: TUNDRA", "def": "Average annual temperature −10 to −5 °C; 0-100 cm precipitation per year.", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-biomeid-6", "term": "Textbook Fig 12.2 ranges: BOREAL FOREST", "def": "Average annual temperature −3 to 5 °C; about 5-199 cm per year (usually 30-100 cm).", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-biomeid-7", "term": "Textbook Fig 12.2 ranges: TEMPERATE GRASSLAND / COLD DESERT", "def": "Average annual temperature −4 to 17 °C; 0-40 cm per year.", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-biomeid-8", "term": "Textbook Fig 12.2 ranges: WOODLAND / SHRUBLAND", "def": "Average annual temperature about −4 to 20 °C (mostly 10-20); 0-130 cm per year, falling mostly in WINTER.", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-biomeid-9", "term": "Textbook Fig 12.2 ranges: TEMPERATE SEASONAL FOREST", "def": "Average annual temperature 4 to 20 °C; up to ~210 cm per year (textbook: over 1 m).", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-biomeid-10", "term": "Textbook Fig 12.2 ranges: TEMPERATE RAINFOREST", "def": "Average annual temperature 7 to 20 °C; 160-330 cm per year (slides: 50-120 in.).", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-biomeid-11", "term": "Textbook Fig 12.2 ranges: SUBTROPICAL DESERT", "def": "Average annual temperature 17 to 31 °C; 0-90 cm per year (usually under 25 cm).", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-biomeid-12", "term": "Textbook Fig 12.2 ranges: TROPICAL SEASONAL FOREST / SAVANNA", "def": "Average annual temperature 20 to 30 °C; 50-260 cm per year with a distinct dry season.", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-biomeid-13", "term": "Textbook Fig 12.2 ranges: TROPICAL RAINFOREST", "def": "Average annual temperature 20 to 30 °C; 230-450 cm per year.", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-biomeid-14", "term": "Signature pattern of each biome (memorize)", "def": "Tundra: below 0 °C most months, ~3-4 month growing season, little rain. Boreal: very cold winter, ~5-month growing season, summer rain. Temperate rainforest: mild + huge winter rain. Temperate seasonal: cold winter, warm summer, steady rain. Woodland/shrubland: wet winter, dry summer. Grassland: cold winter, hot summer, moderate-low rain. Tropical rainforest: hot + wet every month. Savanna: hot, wet season + long dry season. Subtropical desert: hot + almost no rain.", "defImg": "seed/img/apes-u2-biome-chart.svg"}, {"id": "seed-apes-u2-biomeid-15", "term": "Woodland/shrubland vs. temperate grassland: what's the difference on a graph?", "def": "Woodland/shrubland is mild all year (winter well above 0 °C) and its rain falls in WINTER. Grassland has freezing winters and its rain falls in spring and summer.", "note": "Both are limited by precipitation in summer."}, {"id": "seed-apes-u2-biomeid-16", "term": "Savanna vs. tropical rainforest: what's the difference on a graph?", "def": "Both are hot every month. Rainforest has high rain EVERY month. Savanna has several months of nearly zero rain (a dry season) when the ITCZ is away."}, {"id": "seed-apes-u2-biomeid-17", "term": "Temperate rainforest vs. temperate seasonal forest: what's the difference on a graph?", "def": "Temperate rainforest is milder (winter rarely below freezing) and much wetter (160-330 cm, mostly winter). Seasonal forest has colder winters near 0 °C and ~100 cm of steady rain."}, {"id": "seed-apes-u2-biomeid-18", "term": "Tundra vs. boreal forest: what's the difference on a graph?", "def": "Both are cold. Tundra's summer barely gets above freezing (~5-8 °C) with a growing season of only ~3-4 months. Boreal has a real summer (~15-18 °C) and ~5 months above 0 °C, enough for trees."}, {"id": "seed-apes-u2-biomeid-19", "term": "Cold desert vs. subtropical desert", "def": "Both are very dry (under ~25 cm). Cold desert has freezing winters (Moses Lake, Great Basin). Subtropical desert is warm to hot all year (Phoenix, Sahara) and has cacti and euphorbs."}, {"id": "seed-apes-u2-biomeid-20", "term": "Annual data: average 26 °C, 350 cm of rain, wet every month", "def": "Tropical rainforest.", "note": "Tropical (above 20 °C) plus the highest rainfall (230-450 cm)."}, {"id": "seed-apes-u2-biomeid-21", "term": "Annual data: average −8 °C, 20 cm of precipitation", "def": "Tundra.", "note": "Below −5 °C and very little precipitation."}, {"id": "seed-apes-u2-biomeid-22", "term": "Annual data: average 1 °C, 50 cm of precipitation, summer rain", "def": "Boreal forest (taiga).", "note": "Between −3 and 5 °C with moderate precipitation, enough for coniferous trees."}, {"id": "seed-apes-u2-biomeid-23", "term": "Annual data: average 9 °C, 30 cm, cold winters and hot summers", "def": "Temperate grassland / cold desert.", "note": "Temperate temperature but only 0-40 cm of rain."}, {"id": "seed-apes-u2-biomeid-24", "term": "Annual data: average 12 °C, 110 cm, rain spread evenly through the year", "def": "Temperate seasonal forest.", "note": "Temperate, over 1 m of rain, and no dry season."}, {"id": "seed-apes-u2-biomeid-25", "term": "Annual data: average 11 °C, 250 cm, mostly in winter, coastal", "def": "Temperate rainforest.", "note": "Temperate with 160-330 cm."}, {"id": "seed-apes-u2-biomeid-26", "term": "Annual data: average 16 °C, 50 cm, nearly all in winter (dry summer)", "def": "Woodland / shrubland.", "note": "Wet winter and dry summer is the Mediterranean signature."}, {"id": "seed-apes-u2-biomeid-27", "term": "Annual data: average 25 °C, 120 cm, with a 5-month dry season", "def": "Tropical seasonal forest / savanna.", "note": "Tropical, in the 50-260 cm range, with a dry season."}, {"id": "seed-apes-u2-biomeid-28", "term": "Annual data: average 24 °C, 10 cm", "def": "Subtropical desert.", "note": "Tropical temperature but almost no rain."}, {"id": "seed-apes-u2-biomeid-29", "term": "Textbook climograph: Egedesminde, Greenland (−15 to 8 °C, ~30-60 mm/month, growing season Jun-Sep)", "def": "Tundra.", "note": "Only ~4 months above 0 °C and a summer high of just 8 °C."}, {"id": "seed-apes-u2-biomeid-30", "term": "Textbook climograph: Thunder Bay, Ontario (−13 to 18 °C, 20-90 mm/month, growing season Apr-Oct)", "def": "Boreal forest.", "note": "Very cold winter, short warm summer, moderate summer rain."}, {"id": "seed-apes-u2-biomeid-31", "term": "Textbook climograph: Nanaimo, B.C. (4 to 18 °C, 150-180 mm in winter down to 20 mm in summer)", "def": "Temperate rainforest.", "note": "Mild all year, with rain heavy in winter and low in summer."}, {"id": "seed-apes-u2-biomeid-32", "term": "Textbook climograph: Stuttgart, Germany (2 to 19 °C, 40-100 mm every month)", "def": "Temperate seasonal forest.", "note": "Cold winter, warm summer, steady rain."}, {"id": "seed-apes-u2-biomeid-33", "term": "Textbook climograph: San Luis Obispo, CA (11 to 19 °C, 120 mm in winter, 0 mm May-Aug)", "def": "Woodland / shrubland (chaparral).", "note": "Mild with a wet winter and a dry summer."}, {"id": "seed-apes-u2-biomeid-34", "term": "Textbook climograph: Stillwater, Oklahoma (2 to 26 °C, 20-120 mm, peak in May-June)", "def": "Temperate grassland.", "note": "Cold winter, hot summer, spring and summer rain peak."}, {"id": "seed-apes-u2-biomeid-35", "term": "Textbook climograph: Basco, Philippines (21 to 29 °C, 80-400 mm)", "def": "Tropical rainforest.", "note": "Hot all year with very high rain."}, {"id": "seed-apes-u2-biomeid-36", "term": "Textbook climograph: Kabwe, Zambia (15 to 23 °C, 0 mm in the dry months, peaks ~240 mm)", "def": "Tropical seasonal forest / savanna.", "note": "Warm all year, with distinct wet and dry seasons."}, {"id": "seed-apes-u2-biomeid-37", "term": "Textbook climograph: Arica, Chile (16 to 22 °C, 0 mm every month)", "def": "Subtropical desert.", "note": "Warm with zero rain."}, {"id": "seed-apes-u2-biomeid-38", "term": "Which biome? Monthly data:\nMonth: J F M A M J J A S O N D\nTemp (°C): -25, -27, -26, -18, -7, 1, 4, 3, -1, -9, -18, -23\nPrecip (mm): 4, 4, 3, 3, 3, 8, 25, 25, 15, 10, 5, 4", "def": "Tundra.\n\nAverage temperature -12.2 °C, total precipitation 109 mm (11 cm). Growing season (months above 0 °C): Jun, Jul, Aug. Plant growth: limited by TEMPERATURE all year (precipitation is always above 2 × temp). Average far below 0 °C, only ~2-4 months above freezing, and little precipitation. (Real place: Utqiaġvik (Barrow), Alaska.)", "defImg": "seed/img/apes-u2-cp-barrow.svg"}, {"id": "seed-apes-u2-biomeid-39", "term": "Which biome is this climate diagram?", "def": "Tundra. (Real place: Utqiaġvik (Barrow), Alaska.)", "termImg": "seed/img/apes-u2-cp-barrow.svg", "note": "Average far below 0 °C, only ~2-4 months above freezing, and little precipitation."}, {"id": "seed-apes-u2-biomeid-40", "term": "Which biome? Monthly data:\nMonth: J F M A M J J A S O N D\nTemp (°C): -23, -19, -11, 0, 9, 15, 17, 14, 8, -3, -16, -21\nPrecip (mm): 14, 11, 9, 6, 15, 35, 55, 45, 28, 22, 17, 15", "def": "Boreal forest (taiga).\n\nAverage temperature -2.5 °C, total precipitation 272 mm (27 cm). Growing season (months above 0 °C): May, Jun, Jul, Aug, Sep. Plant growth: limited by PRECIPITATION in May; limited by TEMPERATURE the rest of the year. Very cold winters (−15 to −25 °C) but a real summer (~15-18 °C) with ~5 months above 0 °C. Moderate rain, mostly in summer. (Real place: Fairbanks, Alaska.)", "defImg": "seed/img/apes-u2-cp-fairbanks.svg"}, {"id": "seed-apes-u2-biomeid-41", "term": "Which biome is this climate diagram?", "def": "Boreal forest (taiga). (Real place: Fairbanks, Alaska.)", "termImg": "seed/img/apes-u2-cp-fairbanks.svg", "note": "Very cold winters (−15 to −25 °C) but a real summer (~15-18 °C) with ~5 months above 0 °C. Moderate rain, mostly in summer."}, {"id": "seed-apes-u2-biomeid-42", "term": "Which biome? Monthly data:\nMonth: J F M A M J J A S O N D\nTemp (°C): 5, 6, 7, 8, 11, 13, 15, 16, 14, 10, 7, 5\nPrecip (mm): 380, 300, 280, 180, 110, 70, 40, 50, 100, 280, 420, 400", "def": "Temperate rainforest.\n\nAverage temperature 9.8 °C, total precipitation 2610 mm (261 cm). Growing season (months above 0 °C): all 12 months. Plant growth: limited by TEMPERATURE all year (precipitation is always above 2 × temp). Mild (never far below 0 °C) with a HUGE amount of rain, mostly in winter. Coastal. (Real place: Forks, Washington (Olympic rainforest).)", "defImg": "seed/img/apes-u2-cp-forks.svg"}, {"id": "seed-apes-u2-biomeid-43", "term": "Which biome is this climate diagram?", "def": "Temperate rainforest. (Real place: Forks, Washington (Olympic rainforest).)", "termImg": "seed/img/apes-u2-cp-forks.svg", "note": "Mild (never far below 0 °C) with a HUGE amount of rain, mostly in winter. Coastal."}, {"id": "seed-apes-u2-biomeid-44", "term": "Which biome? Monthly data:\nMonth: J F M A M J J A S O N D\nTemp (°C): 1, 2, 7, 13, 18, 24, 26, 25, 21, 15, 9, 3\nPrecip (mm): 80, 70, 95, 90, 95, 95, 110, 90, 95, 80, 75, 90", "def": "Temperate seasonal forest.\n\nAverage temperature 13.7 °C, total precipitation 1065 mm (106 cm). Growing season (months above 0 °C): all 12 months. Plant growth: limited by TEMPERATURE all year (precipitation is always above 2 × temp). Cold winter near 0 °C, warm summer, and steady rain every month (total over 1 m). (Real place: Washington, D.C..)", "defImg": "seed/img/apes-u2-cp-dc.svg"}, {"id": "seed-apes-u2-biomeid-45", "term": "Which biome is this climate diagram?", "def": "Temperate seasonal forest. (Real place: Washington, D.C..)", "termImg": "seed/img/apes-u2-cp-dc.svg", "note": "Cold winter near 0 °C, warm summer, and steady rain every month (total over 1 m)."}, {"id": "seed-apes-u2-biomeid-46", "term": "Which biome? Monthly data:\nMonth: J F M A M J J A S O N D\nTemp (°C): 14, 15, 15, 17, 18, 20, 22, 23, 22, 20, 17, 14\nPrecip (mm): 80, 90, 60, 20, 5, 1, 0, 1, 5, 15, 25, 60", "def": "Woodland / shrubland (chaparral).\n\nAverage temperature 18.1 °C, total precipitation 362 mm (36 cm). Growing season (months above 0 °C): all 12 months. Plant growth: limited by PRECIPITATION in Apr, May, Jun, Jul, Aug, Sep, Oct, Nov; limited by TEMPERATURE the rest of the year. Mild all year, with a wet WINTER and a bone-dry SUMMER. (Real place: Los Angeles, California.)", "defImg": "seed/img/apes-u2-cp-la.svg"}, {"id": "seed-apes-u2-biomeid-47", "term": "Which biome is this climate diagram?", "def": "Woodland / shrubland (chaparral). (Real place: Los Angeles, California.)", "termImg": "seed/img/apes-u2-cp-la.svg", "note": "Mild all year, with a wet WINTER and a bone-dry SUMMER."}, {"id": "seed-apes-u2-biomeid-48", "term": "Which biome? Monthly data:\nMonth: J F M A M J J A S O N D\nTemp (°C): -2, -1, 3, 7, 12, 18, 21, 20, 15, 9, 3, -2\nPrecip (mm): 10, 12, 25, 45, 65, 50, 50, 38, 28, 20, 15, 12", "def": "Temperate grassland.\n\nAverage temperature 8.6 °C, total precipitation 370 mm (37 cm). Growing season (months above 0 °C): Mar, Apr, May, Jun, Jul, Aug, Sep, Oct, Nov. Plant growth: limited by PRECIPITATION in Aug, Sep; limited by TEMPERATURE the rest of the year. Big swing from below-freezing winters to hot summers, and only ~25-50 cm of rain, peaking in late spring and summer. (Real place: Cheyenne, Wyoming (Great Plains).)", "defImg": "seed/img/apes-u2-cp-cheyenne.svg"}, {"id": "seed-apes-u2-biomeid-49", "term": "Which biome is this climate diagram?", "def": "Temperate grassland. (Real place: Cheyenne, Wyoming (Great Plains).)", "termImg": "seed/img/apes-u2-cp-cheyenne.svg", "note": "Big swing from below-freezing winters to hot summers, and only ~25-50 cm of rain, peaking in late spring and summer."}, {"id": "seed-apes-u2-biomeid-50", "term": "Which biome? Monthly data:\nMonth: J F M A M J J A S O N D\nTemp (°C): -3, 0, 5, 10, 15, 19, 23, 22, 17, 10, 3, -2\nPrecip (mm): 25, 18, 15, 13, 15, 18, 8, 8, 8, 13, 25, 28", "def": "Temperate grassland / cold desert.\n\nAverage temperature 9.9 °C, total precipitation 194 mm (19 cm). Growing season (months above 0 °C): Mar, Apr, May, Jun, Jul, Aug, Sep, Oct, Nov. Plant growth: limited by PRECIPITATION in Apr, May, Jun, Jul, Aug, Sep, Oct; limited by TEMPERATURE the rest of the year. Cold winters and hot summers, and under ~25 cm of rain a year (rain shadow). (Real place: Moses Lake, Washington.)", "defImg": "seed/img/apes-u2-cp-moseslake.svg"}, {"id": "seed-apes-u2-biomeid-51", "term": "Which biome is this climate diagram?", "def": "Temperate grassland / cold desert. (Real place: Moses Lake, Washington.)", "termImg": "seed/img/apes-u2-cp-moseslake.svg", "note": "Cold winters and hot summers, and under ~25 cm of rain a year (rain shadow)."}, {"id": "seed-apes-u2-biomeid-52", "term": "Which biome? Monthly data:\nMonth: J F M A M J J A S O N D\nTemp (°C): 26, 26, 26, 26, 26, 27, 27, 28, 28, 28, 27, 27\nPrecip (mm): 260, 290, 310, 290, 230, 110, 90, 60, 80, 110, 170, 220", "def": "Tropical rainforest.\n\nAverage temperature 26.8 °C, total precipitation 2220 mm (222 cm). Growing season (months above 0 °C): all 12 months. Plant growth: limited by TEMPERATURE all year (precipitation is always above 2 × temp). Hot every month (~25-28 °C) with high rain every month (well over 2 m a year). Warmest months are Dec-Feb, so this is the Southern Hemisphere. (Real place: Manaus, Brazil (Amazon).)", "defImg": "seed/img/apes-u2-cp-manaus.svg"}, {"id": "seed-apes-u2-biomeid-53", "term": "Which biome is this climate diagram?", "def": "Tropical rainforest. (Real place: Manaus, Brazil (Amazon).)", "termImg": "seed/img/apes-u2-cp-manaus.svg", "note": "Hot every month (~25-28 °C) with high rain every month (well over 2 m a year)."}, {"id": "seed-apes-u2-biomeid-54", "term": "Which biome? Monthly data:\nMonth: J F M A M J J A S O N D\nTemp (°C): 29, 28, 28, 28, 27, 25, 25, 26, 28, 29, 29, 29\nPrecip (mm): 420, 370, 320, 100, 20, 2, 1, 5, 15, 70, 140, 250", "def": "Tropical seasonal forest / savanna.\n\nAverage temperature 27.6 °C, total precipitation 1713 mm (171 cm). Growing season (months above 0 °C): all 12 months. Plant growth: limited by PRECIPITATION in May, Jun, Jul, Aug, Sep; limited by TEMPERATURE the rest of the year. Hot every month, with a very wet season and several months with almost zero rain. Warmest months are Dec-Feb, so this is the Southern Hemisphere. (Real place: Darwin, Australia.)", "defImg": "seed/img/apes-u2-cp-darwin.svg"}, {"id": "seed-apes-u2-biomeid-55", "term": "Which biome is this climate diagram?", "def": "Tropical seasonal forest / savanna. (Real place: Darwin, Australia.)", "termImg": "seed/img/apes-u2-cp-darwin.svg", "note": "Hot every month, with a very wet season and several months with almost zero rain."}, {"id": "seed-apes-u2-biomeid-56", "term": "Which biome? Monthly data:\nMonth: J F M A M J J A S O N D\nTemp (°C): 12, 14, 17, 21, 26, 31, 34, 33, 30, 23, 16, 12\nPrecip (mm): 20, 20, 25, 6, 3, 1, 25, 25, 16, 15, 15, 22", "def": "Subtropical desert.\n\nAverage temperature 22.4 °C, total precipitation 193 mm (19 cm). Growing season (months above 0 °C): all 12 months. Plant growth: limited by PRECIPITATION in all 12 months; limited by TEMPERATURE the rest of the year. Warm to very hot and almost no rain all year. (Real place: Phoenix, Arizona.)", "defImg": "seed/img/apes-u2-cp-phoenix.svg"}, {"id": "seed-apes-u2-biomeid-57", "term": "Which biome is this climate diagram?", "def": "Subtropical desert. (Real place: Phoenix, Arizona.)", "termImg": "seed/img/apes-u2-cp-phoenix.svg", "note": "Warm to very hot and almost no rain all year."}, {"id": "seed-apes-u2-biomeid-58", "term": "Which biome? Monthly data:\nMonth: J F M A M J J A S O N D\nTemp (°C): 24, 24, 23, 19, 16, 14, 13, 13, 15, 17, 20, 22\nPrecip (mm): 10, 15, 20, 40, 120, 170, 160, 120, 80, 50, 25, 12", "def": "Woodland / shrubland (mallee).\n\nAverage temperature 18.3 °C, total precipitation 822 mm (82 cm). Growing season (months above 0 °C): all 12 months. Plant growth: limited by PRECIPITATION in Jan, Feb, Mar, Nov, Dec; limited by TEMPERATURE the rest of the year. Mild all year, with a wet WINTER and a bone-dry SUMMER. Here winter is June-August, so this is the Southern Hemisphere. Warmest months are Dec-Feb, so this is the Southern Hemisphere. (Real place: Perth, Australia.)", "defImg": "seed/img/apes-u2-cp-perth.svg"}, {"id": "seed-apes-u2-biomeid-59", "term": "Which biome is this climate diagram?", "def": "Woodland / shrubland (mallee). (Real place: Perth, Australia.)", "termImg": "seed/img/apes-u2-cp-perth.svg", "note": "Mild all year, with a wet WINTER and a bone-dry SUMMER. Here winter is June-August, so this is the Southern Hemisphere."}, {"id": "seed-apes-u2-biomeid-60", "term": "Which biome is this climate diagram?", "def": "Tundra.", "termImg": "seed/img/apes-u2-clim-tundra.svg", "note": "Average far below 0 °C, only ~2-4 months above freezing, and little precipitation."}, {"id": "seed-apes-u2-biomeid-61", "term": "Which biome is this climate diagram?", "def": "Boreal forest (taiga).", "termImg": "seed/img/apes-u2-clim-boreal.svg", "note": "Very cold winters (−15 to −25 °C) but a real summer (~15-18 °C) with ~5 months above 0 °C. Moderate rain, mostly in summer."}, {"id": "seed-apes-u2-biomeid-62", "term": "Which biome is this climate diagram?", "def": "Temperate rainforest.", "termImg": "seed/img/apes-u2-clim-temprain.svg", "note": "Mild (never far below 0 °C) with a HUGE amount of rain, mostly in winter. Coastal."}, {"id": "seed-apes-u2-biomeid-63", "term": "Which biome is this climate diagram?", "def": "Temperate seasonal forest.", "termImg": "seed/img/apes-u2-clim-tempseas.svg", "note": "Cold winter near 0 °C, warm summer, and steady rain every month (total over 1 m)."}, {"id": "seed-apes-u2-biomeid-64", "term": "Which biome is this climate diagram?", "def": "Woodland / shrubland (chaparral).", "termImg": "seed/img/apes-u2-clim-woodland.svg", "note": "Mild all year, with a wet WINTER and a bone-dry SUMMER."}, {"id": "seed-apes-u2-biomeid-65", "term": "Which biome is this climate diagram?", "def": "Temperate grassland.", "termImg": "seed/img/apes-u2-clim-grassland.svg", "note": "Big swing from below-freezing winters to hot summers, and only ~25-50 cm of rain, peaking in late spring and summer."}, {"id": "seed-apes-u2-biomeid-66", "term": "Which biome is this climate diagram?", "def": "Tropical rainforest.", "termImg": "seed/img/apes-u2-clim-troprain.svg", "note": "Hot every month (~25-28 °C) with high rain every month (well over 2 m a year)."}, {"id": "seed-apes-u2-biomeid-67", "term": "Which biome is this climate diagram?", "def": "Tropical seasonal forest / savanna.", "termImg": "seed/img/apes-u2-clim-savanna.svg", "note": "Hot every month, with a very wet season and several months with almost zero rain."}, {"id": "seed-apes-u2-biomeid-68", "term": "Which biome is this climate diagram?", "def": "Subtropical desert.", "termImg": "seed/img/apes-u2-clim-desert.svg", "note": "Warm to very hot and almost no rain all year."}]}, {"id": "seed-apes-u2-frq", "rev": 2, "title": "APES Unit 2 — FRQ (3 confirmed + likely picks)", "folder": "APES", "description": "★ = the 3 FRQs Mr. Boyd confirmed (global weather patterns + Hadley cells, seasons, why it gets colder). ◆ = my picks for the other 3. ○ = other long review answers as backup. Slide wording verbatim; each list has a full card plus one card per line.", "cards": [{"id": "seed-apes-u2-frq-r2-0", "term": "★ CONFIRMED 1 · DRAW: Global weather patterns (slide 11). What goes on the drawing?", "def": "Earth with lines at 60° N, 30° N, 0°, 30° S, 60° S.\n• Cells on the side, in each hemisphere: HADLEY cell (0–30°), MID-LATITUDE cell (30–60°), POLAR cell (60–90°), with loop arrows showing the air circling.\n• Red line at 0° = INTERTROPICAL CONVERGENCE ZONE (ITCZ).\n• HIGH at 30° N and HIGH at 30° S.\n• Surface wind arrows: NORTHEASTERLY TRADES (0–30° N) and SOUTHEASTERLY TRADES (0–30° S), both curving toward the equator; WESTERLIES (30–60° N and S), curving toward the poles.", "note": "Draw it from memory 3 times, checking against the picture each time. 6 latitude labels, 6 cells, ITCZ, 2 HIGHs, 4 wind labels.", "defImg": "seed/img/apes-u2-slide11.png"}, {"id": "seed-apes-u2-frq-r2-1", "term": "★ CONFIRMED 1 · HOW IT WORKS: Global weather patterns (explain the drawing).", "def": "Weather is driven by temperature differences caused by differential heating of the Earth. Temperature differences cause convection, which creates high and low pressure areas.\n• 0° (ITCZ): the Sun heats the air most, so air RISES → LOW pressure → clouds and heavy rain (rainforests).\n• 30° N and S: the air SINKS → HIGH pressure → clear and dry (deserts).\n• 60° N and S: air RISES again → low pressure → rain (temperate and boreal forests).\n• Poles: air SINKS → high pressure → cold and dry.\n• Winds blow at the surface from HIGH to LOW pressure: the trade winds blow from 30° back to the equator, and the westerlies blow from 30° toward 60°. The Coriolis effect curves them, so the trades come from the NE and SE and the westerlies from the west.", "note": "Rule for the whole drawing: rising air = low pressure = rain; sinking air = high pressure = dry. Rising at 0° and 60°, sinking at 30° and 90°.", "defImg": "seed/img/apes-u2-circulation.svg"}, {"id": "seed-apes-u2-frq-r2-2", "term": "★ CONFIRMED 1 · What 3 cells are in each hemisphere, and what latitudes?", "def": "Hadley cell 0–30°, Mid-latitude (Ferrel) cell 30–60°, Polar cell 60–90°."}, {"id": "seed-apes-u2-frq-r2-3", "term": "★ CONFIRMED 1 · Which way does the air move in each cell?", "def": "HADLEY: rises at 0°, flows toward the pole up high, sinks at 30°, returns to the equator along the surface (trade winds).\nMID-LATITUDE: sinks at 30°, flows toward the pole along the surface (westerlies), rises at 60°.\nPOLAR: rises at 60°, flows to the pole up high, sinks at the pole, returns to 60° along the surface.", "note": "Neighboring cells turn like meshing gears: where two cells meet, they both go up (0°, 60°) or both go down (30°, poles).", "defImg": "seed/img/apes-u2-circulation.svg"}, {"id": "seed-apes-u2-frq-r2-4", "term": "★ CONFIRMED 1 · Name the surface winds in each band (slides 11 and 13).", "def": "0–30° N: Northeasterly Trades. 0–30° S: Southeasterly Trades. 30–60° N and S: Westerlies. 60–90°: Polar easterlies.", "note": "Slide 13 also labels: Equatorial low / Doldrums (0°), Horse latitudes / Subtropical high (30°), Polar front / Subpolar low (60°), Polar high (90°)."}, {"id": "seed-apes-u2-frq-r2-5", "term": "★ CONFIRMED 1 · SLIDE 14 VERBATIM: Hadley cells up close, steps 1–5.", "def": "(1) At the ITCZ, the Sun heats the moist tropical air, causing it to rise.\n(2) The rising air experiences adiabatic cooling, which causes water vapor to condense into rain and fall back to Earth.\n(3) The condensation of water vapor produces latent heat release. This causes the air to expand and rise farther up into the atmosphere.\n(4) The warm, rising air displaces the cooler, drier air above it to the north and south.\n(5) The cool, dry air sinks and experiences adiabatic heating. It reaches Earth's surface as warm, dry air, and then flows back toward the equator.", "note": "Hook: HEAT → COOL → RELEASE → PUSH → SINK. Diagram labels: Hot, moist tropics (equator); Hot, dry desert (30° N and 30° S); Dry, cold air (top); Moisture arrows flowing in at the bottom.", "defImg": "seed/img/apes-u2-hadley.svg"}, {"id": "seed-apes-u2-frq-r2-6", "term": "★ CONFIRMED 1 · Hadley step 1?", "def": "At the ITCZ, the Sun heats the moist tropical air, causing it to rise."}, {"id": "seed-apes-u2-frq-r2-7", "term": "★ CONFIRMED 1 · Hadley step 2?", "def": "The rising air experiences adiabatic cooling, which causes water vapor to condense into rain and fall back to Earth."}, {"id": "seed-apes-u2-frq-r2-8", "term": "★ CONFIRMED 1 · Hadley step 3?", "def": "The condensation of water vapor produces latent heat release. This causes the air to expand and rise farther up into the atmosphere."}, {"id": "seed-apes-u2-frq-r2-9", "term": "★ CONFIRMED 1 · Hadley step 4?", "def": "The warm, rising air displaces the cooler, drier air above it to the north and south."}, {"id": "seed-apes-u2-frq-r2-10", "term": "★ CONFIRMED 1 · Hadley step 5?", "def": "The cool, dry air sinks and experiences adiabatic heating. It reaches Earth's surface as warm, dry air, and then flows back toward the equator."}, {"id": "seed-apes-u2-frq-r2-11", "term": "★ CONFIRMED 1 · SLIDE 14: \"Explaining rainforests and deserts\" — the 6 describe prompts.", "def": "• Describe what is the air doing here.\n• Describe what happens to the air as it rises or falls.\n• Describe precipitation patterns.\n• Describe the kind of pressure that results from this air movement.\n• Describe what kind of cloud cover results from this kind of pressure.\n• Describe temperature patterns.", "note": "Hook: AIR, CHANGE, RAIN, PRESSURE, CLOUDS, TEMP. Answer all 6 for the equator AND for 30°."}, {"id": "seed-apes-u2-frq-r2-12", "term": "★ CONFIRMED 1 · Answer the 6 prompts for the EQUATOR (rainforests).", "def": "Air: rising. Rises: it experiences adiabatic cooling, so water vapor condenses. Precipitation: heavy rain. Pressure: LOW pressure. Cloud cover: cloudy. Temperature: hot all year (hot, moist tropics). → Rainforests."}, {"id": "seed-apes-u2-frq-r2-13", "term": "★ CONFIRMED 1 · Answer the 6 prompts for 30° N and S (deserts).", "def": "Air: sinking. Falls: it experiences adiabatic heating, so it becomes warm and dry. Precipitation: very little. Pressure: HIGH pressure. Cloud cover: clear skies. Temperature: hot (hot, dry desert). → Deserts."}, {"id": "seed-apes-u2-frq-r2-14", "term": "★ CONFIRMED 2 · Why we have seasons and biomes: the key ideas (verbatim).", "def": "1. Earth orbits the sun on a plane called the ecliptic\n2. Earth's axis is inclined 23.5° to a perpendicular of the ecliptic\n3. The Earth's axis stays parallel to itself throughout its orbit\n4. The heat received by the Earth is a function of the angle of the rays and the length of the days", "note": "The slide and Review Part 1 both have FOUR, so learn all four even if the FRQ only asks for three. Hook: PLANE, TILT, PARALLEL, ANGLE + DAY LENGTH.", "defImg": "seed/img/apes-u2-seasons.svg"}, {"id": "seed-apes-u2-frq-r2-15", "term": "★ CONFIRMED 2 · Seasons idea 1?", "def": "Earth orbits the sun on a plane called the ecliptic."}, {"id": "seed-apes-u2-frq-r2-16", "term": "★ CONFIRMED 2 · Seasons idea 2?", "def": "Earth's axis is inclined 23.5° to a perpendicular of the ecliptic."}, {"id": "seed-apes-u2-frq-r2-17", "term": "★ CONFIRMED 2 · Seasons idea 3?", "def": "The Earth's axis stays parallel to itself throughout its orbit."}, {"id": "seed-apes-u2-frq-r2-18", "term": "★ CONFIRMED 2 · Seasons idea 4?", "def": "The heat received by the Earth is a function of the angle of the rays and the length of the days."}, {"id": "seed-apes-u2-frq-r2-19", "term": "★ CONFIRMED 2 · DRAW: the seasons diagram. What goes on it?", "def": "The Sun in the middle and Earth at 4 points on its orbit (the ecliptic), with the axis tilted 23.5° and pointing the SAME direction every time (parallel).\nLabel: Summer Solstice June 21st (north pole tilted toward the Sun); Autumnal Sept 22nd; Winter Solstice Dec 21st (tilted away); Vernal Equinox March 20th.", "note": "Your drawing has to show all 4 ideas: the orbit plane, the 23.5° tilt, the axis staying parallel, and direct vs angled rays.", "defImg": "seed/img/apes-u2-seasons.svg"}, {"id": "seed-apes-u2-frq-r2-20", "term": "★ CONFIRMED 3 · Why it gets colder as you go up: the 3 key ideas (verbatim).", "def": "1) Gases are compressible; the more pressure you put on a gas, the denser it gets.\n2) The more atmosphere there is above you, the denser the gas around you.\n3) The amount of thermal energy in a m3 is a function of how many air molecules (N2, O2, etc.) there are – fewer particles, fewer collisions, less heat transfer!", "note": "Hook: SQUEEZE → STACK → COUNT. Gas gets squeezed, more air stacked above squeezes it more, and more molecules per m³ means more heat.", "defImg": "seed/img/apes-u2-colder.svg"}, {"id": "seed-apes-u2-frq-r2-21", "term": "★ CONFIRMED 3 · Colder idea 1?", "def": "Gases are compressible; the more pressure you put on a gas, the denser it gets."}, {"id": "seed-apes-u2-frq-r2-22", "term": "★ CONFIRMED 3 · Colder idea 2?", "def": "The more atmosphere there is above you, the denser the gas around you."}, {"id": "seed-apes-u2-frq-r2-23", "term": "★ CONFIRMED 3 · Colder idea 3?", "def": "The amount of thermal energy in a m3 is a function of how many air molecules (N2, O2, etc.) there are – fewer particles, fewer collisions, less heat transfer!"}, {"id": "seed-apes-u2-frq-r2-24", "term": "★ CONFIRMED 3 · DRAW: the \"why it gets colder\" diagrams.", "def": "Boxes of 1 m³ of air at different heights. Sea level: crowded with molecules (whole atmosphere pressing down) = warm. Higher up: fewer and fewer molecules = colder.", "note": "Same slide: Altitude-latitude analogy → going up in altitude is like going north or south in latitude; lapse rate 5.5 °F/1000 ft dry air, 3.0 °F/1000 ft wet air.", "defImg": "seed/img/apes-u2-colder.svg"}, {"id": "seed-apes-u2-frq-r2-25", "term": "◆ LIKELY · Human caused extinction (MEA): the 5 ways (verbatim).", "def": "a. Habitat change → modification and destruction of land and water habitats (Ex: deforestation, agriculture, damming rivers)\nb. Overexploitation/overharvesting → taking resources from the Earth faster than they can be replenished\nc. Invasive alien species → non-native species outcompete the natives (Ex: dandelions, blackberries, kudzu, starling)\nd. Pollution → air, land, and water pollution degrades habitats and undermines the health of all organisms\ne. Climate change → impacts every ecosystem of the Earth, polar and equatorial regions most", "note": "TOP PICK. Review Part 2 asks for exactly these five, and it's a lettered \"human impacts\" list just like 2 of the Unit 1 FRQs. Hook: HOIPC = Habitat, Over-harvest, Invasive, Pollution, Climate."}, {"id": "seed-apes-u2-frq-r2-26", "term": "◆ LIKELY · Extinction a. Habitat change?", "def": "Modification and destruction of land and water habitats (Ex: deforestation, agriculture, damming rivers)."}, {"id": "seed-apes-u2-frq-r2-27", "term": "◆ LIKELY · Extinction b. Overexploitation/overharvesting?", "def": "Taking resources from the Earth faster than they can be replenished."}, {"id": "seed-apes-u2-frq-r2-28", "term": "◆ LIKELY · Extinction c. Invasive alien species?", "def": "Non-native species outcompete the natives (Ex: dandelions, blackberries, kudzu, starling)."}, {"id": "seed-apes-u2-frq-r2-29", "term": "◆ LIKELY · Extinction d. Pollution?", "def": "Air, land, and water pollution degrades habitats and undermines the health of all organisms."}, {"id": "seed-apes-u2-frq-r2-30", "term": "◆ LIKELY · Extinction e. Climate change?", "def": "Impacts every ecosystem of the Earth, polar and equatorial regions most."}, {"id": "seed-apes-u2-frq-r2-31", "term": "◆ LIKELY · Human impacts on MARINE ecosystems: the 5 (verbatim).", "def": "a. Overfishing → has destroyed many of the traditional fishing industries of the world\nb. Fish farming → results in addition of nutrients to the ocean and spreads disease to wild fish\nc. Contamination of estuaries → affected by fertilizers, animal wastes, and pesticides from farmland\nd. Shipping waste → results in oil, human waste, toxins, and trash going into oceans\ne. Off-shore oil drilling → results in spills like Deep Water Horizon", "note": "Review Part 2: \"Describe the five primary ways that humans impact marine ecosystems.\" Hook: FISH, FARM, FERTILIZER, FREIGHT, FUEL (overfishing, fish farming, estuary contamination, shipping, oil drilling)."}, {"id": "seed-apes-u2-frq-r2-32", "term": "◆ LIKELY · Marine a. Overfishing?", "def": "Has destroyed many of the traditional fishing industries of the world."}, {"id": "seed-apes-u2-frq-r2-33", "term": "◆ LIKELY · Marine b. Fish farming?", "def": "Results in addition of nutrients to the ocean and spreads disease to wild fish."}, {"id": "seed-apes-u2-frq-r2-34", "term": "◆ LIKELY · Marine c. Contamination of estuaries?", "def": "Affected by fertilizers, animal wastes, and pesticides from farmland."}, {"id": "seed-apes-u2-frq-r2-35", "term": "◆ LIKELY · Marine d. Shipping waste?", "def": "Results in oil, human waste, toxins, and trash going into oceans."}, {"id": "seed-apes-u2-frq-r2-36", "term": "◆ LIKELY · Marine e. Off-shore oil drilling?", "def": "Results in spills like Deep Water Horizon."}, {"id": "seed-apes-u2-frq-r2-37", "term": "◆ LIKELY · Human impacts on FRESH WATER: the 4 (verbatim).", "def": "a. Habitat destruction → 50% of wetlands in U.S. destroyed since 1600's\nb. Sewage → historically in U.S., human sewage has been a major pollutant, now animal waste is a bigger threat\nc. Air pollution → major impact through acid rain\nd. Nutrients → urban and agricultural run-off cause eutrophication", "note": "Review Part 2: \"Describe four significant human impacts on fresh water ecosystems.\" Hook: HABITAT, SEWAGE, ACID RAIN, NUTRIENTS (\"Hungry Sharks Ate Nemo\")."}, {"id": "seed-apes-u2-frq-r2-38", "term": "◆ LIKELY · Fresh water a. Habitat destruction?", "def": "50% of wetlands in U.S. destroyed since 1600's."}, {"id": "seed-apes-u2-frq-r2-39", "term": "◆ LIKELY · Fresh water b. Sewage?", "def": "Historically in U.S., human sewage has been a major pollutant, now animal waste is a bigger threat."}, {"id": "seed-apes-u2-frq-r2-40", "term": "◆ LIKELY · Fresh water c. Air pollution?", "def": "Major impact through acid rain."}, {"id": "seed-apes-u2-frq-r2-41", "term": "◆ LIKELY · Fresh water d. Nutrients?", "def": "Urban and agricultural run-off cause eutrophication."}, {"id": "seed-apes-u2-frq-r2-42", "term": "◆ LIKELY · SLIDE-ONLY PICK: Global climate key ideas 1–5 (slide 8, verbatim).", "def": "1. Weather is driven by temperature differences caused by differential heating of the Earth\n2. Temperature differences cause convection which creates high and low pressure areas in the atmosphere\n3. Winds blow to correct imbalances in atmospheric pressure and redistribute the sun's energy\n4. High and low pressure cells or ridges move over geographic regions and cause changes in weather as air masses move through the cells\n5. Coriolis effect → deflection of wind and water by the rotation of the Earth\n   a. Counterclockwise in the n. hemisphere\n   b. Clockwise in the s. hemisphere", "note": "My pick for the one FRQ that isn't on the review. It's a numbered \"Key Ideas\" list like the seasons, colder, and natural-selection FRQs, and no review question asks for it. Hook: HEAT → CONVECTION → WIND → CELLS MOVE → CORIOLIS."}, {"id": "seed-apes-u2-frq-r2-43", "term": "◆ LIKELY · Climate key idea 1?", "def": "Weather is driven by temperature differences caused by differential heating of the Earth."}, {"id": "seed-apes-u2-frq-r2-44", "term": "◆ LIKELY · Climate key idea 2?", "def": "Temperature differences cause convection which creates high and low pressure areas in the atmosphere."}, {"id": "seed-apes-u2-frq-r2-45", "term": "◆ LIKELY · Climate key idea 3?", "def": "Winds blow to correct imbalances in atmospheric pressure and redistribute the sun's energy."}, {"id": "seed-apes-u2-frq-r2-46", "term": "◆ LIKELY · Climate key idea 4?", "def": "High and low pressure cells or ridges move over geographic regions and cause changes in weather as air masses move through the cells."}, {"id": "seed-apes-u2-frq-r2-47", "term": "◆ LIKELY · Climate key idea 5?", "def": "Coriolis effect → deflection of wind and water by the rotation of the Earth. a. Counterclockwise in the n. hemisphere. b. Clockwise in the s. hemisphere."}, {"id": "seed-apes-u2-frq-r2-48", "term": "○ BACKUP · Normal, El Niño, and La Niña patterns (trade winds, surface water, upwelling, convection).", "def": "NORMAL: Strong trade winds and strong equatorial currents push warm surface water west, so there is warm water and low pressure by Australia/Indonesia (rising air, convection, rain). Off Peru there is cool water and high pressure with a strong Peruvian current; upwelling brings increased nutrients and fish populations.\nEL NIÑO: A periodic weakening of the Trade Winds → results in a warming of the Pacific Ocean off the coast of Peru. Weak trade winds; warm water moves east to Peru; upwelling (nutrients and fish) decreases. Pressure increases over Australia (drier) and decreases off South America, so convection and rain shift east.\nLA NIÑA: Trade winds are stronger than normal, pushing even more warm water west. Upwelling off Peru is stronger, so the water there is colder. Convection and rain are stronger over Indonesia and Australia, while Peru is drier.", "note": "Long Part 1 question, and also a likely pick. Track 4 things in each: trade winds, warm water, upwelling, where the rain is.", "defImg": "seed/img/apes-u2-enso.svg"}, {"id": "seed-apes-u2-frq-r2-49", "term": "○ BACKUP · Four El Niño effects (verbatim).", "def": "a. Warm, dry winters in the northwestern U.S.\nb. Cool, wet winters in the southwestern U.S.\nc. Flooding in Peru\nd. Drought in Australia and Indonesia"}, {"id": "seed-apes-u2-frq-r2-50", "term": "○ BACKUP · How each type of ocean current behaves (verbatim, 4).", "def": "1. Gyres → large-scale patterns of surface water circulation, clockwise in the n. hemisphere and counterclockwise in the s. hemisphere (opposite of Coriolis effect!)\n2. Cold water from the poles moves along the west coasts of continents → cools adjacent land mass\n3. Warm water from the equator moves along the east coasts of continents → warms adjacent land mass\n4. Upwellings occur along west coasts of most continents → result in increased nutrients and fish populations", "defImg": "seed/img/apes-u2-gyres.svg"}, {"id": "seed-apes-u2-frq-r2-51", "term": "○ BACKUP · Thermohaline circulation, and what if it shuts down?", "def": "Thermohaline circulation → results from cold salty water sinking at high latitudes and warm water rising near the equator (aka: The Great Conveyor Belt). Ex: Gulf Stream warms England, while Newfoundland is cooled by North Atlantic current. Global climate change could shut down the circulation: melting ice adds fresh water, so the water is less salty and does not sink, and places like England would get much colder.", "defImg": "seed/img/apes-u2-thermohaline.svg"}, {"id": "seed-apes-u2-frq-r2-52", "term": "○ BACKUP · Why western Washington (Seattle, 37.41 in.) gets so much more rain than eastern Washington (Moses Lake, 7.69 in.).", "def": "Orographic precipitation → as air masses travel over mountain ranges they are pushed up and cooled, causing precipitation (rain shadow on downwind side). Moist ocean air is pushed up over the Cascades and rains on the western side (Seattle). Moses Lake is on the downwind side, in the rain shadow.", "defImg": "seed/img/apes-u2-rainshadow.svg"}, {"id": "seed-apes-u2-frq-r2-53", "term": "○ BACKUP · Four factors that influence productivity in fresh water (verbatim).", "def": "1) Depth → shallow water promotes PS\n2) Clarity → clear water promotes PS\n3) Nutrients → inputs can increase PS, but too much can result in eutrophication and BOD (biochemical oxygen demand)\n4) Temperature → the colder the water, the slower the rate of PS"}, {"id": "seed-apes-u2-frq-r2-54", "term": "○ BACKUP · Three factors that influence dissolved oxygen (verbatim).", "def": "1) Wave action and photosynthesis → increase DO\n2) Temperature → the colder the water the higher the DO\n3) Nutrients → eutrophication and biochemical oxygen demand (BOD) reduce DO"}, {"id": "seed-apes-u2-frq-r2-55", "term": "○ BACKUP · Describe the deep sea (abyssal) ecosystem + 3 services + 7 microhabitats.", "def": "a. Occurs at great depths in the ocean. b. No light to support photosynthesis → autotrophs are chemosynthesizers; release energy from methane (CH4) and hydrogen sulfide (H2S). c. Organisms depend on constant rain of organic matter from photic zone. d. Animals are usually scavengers, many are small and generate light for finding or attracting food.\nSERVICES: Nutrient recycling; Carbon burial; Controls ocean chemistry.\nMICROHABITATS: Rocky mid-ocean ridges; Submarine canyons; Trenches and seamounts; Chemoautotrophic cold seeps; Hydrothermal vents; Whale-falls; Sediment-dominated continental slopes and abyssal plains."}, {"id": "seed-apes-u2-frq-r2-56", "term": "○ BACKUP · Why estuaries are valuable AND vulnerable.", "def": "VALUABLE: Estuaries → partially enclosed bays where rivers meet the ocean; have brackish water and tidal conditions. Extremely productive ecosystems because they are shallow, warm, and nutrient-rich → often include salt marshes. Important nursery sites for fish and crustaceans. Great places for agriculture because of their deltas.\nVULNERABLE: Contamination of estuaries → affected by fertilizers, animal wastes, and pesticides from farmland (everything upstream drains into them)."}, {"id": "seed-apes-u2-frq-r2-57", "term": "○ BACKUP · Coral reefs vs mangrove swamps + 2 contributions each.", "def": "CORAL REEFS → form around islands and along coasts where warm, clear waters are found (Ex: Great Barrier Reef). Corals are animals (polyps) with zooxanthellae, algae that photosynthesize for food; each polyp builds a calcium carbonate cup that becomes reef. Contributions: habitat for huge marine biodiversity; protect coasts from waves.\nMANGROVE SWAMPS → form along tropical coasts where there is warm shallow water without too much wave action. Contributions: trap sediments and extend land into shallow seas; nursery habitat for young fish and protection from storms.\nBOTH: warm, shallow, tropical coasts."}, {"id": "seed-apes-u2-frq-r2-58", "term": "○ BACKUP · Two factors that influence productivity in the pelagic zone (verbatim).", "def": "a. Light penetration → the euphotic zone, may extend to 200 m in very clear water\nb. Inorganic nutrients (nitrogen and phosphorous) → current upwellings and river mouths are most productive"}, {"id": "seed-apes-u2-frq-r2-59", "term": "○ BACKUP · Why should we save other species? (verbatim, 3)", "def": "1. All organisms have an inherent right to exist\n2. Extinctions destabilize and disrupt ecosystems\n3. Benefits to humans → ecosystem services"}, {"id": "seed-apes-u2-frq-r2-60", "term": "○ BACKUP · SLIDE-ONLY BACKUP: Temperate rainforest (slide 35).", "def": "a. Coastal northern California, Oregon, Washington, British Columbia, and southern Alaska; Scotland, Australia, New Zealand, and the southwest coast of Chile\nb. Always coastal and/or mountainous → moist air forced over the mountains, cools, and precipitation forms\nc. 50-120 in. average annual rainfall\nd. Cool climate slows evaporation → nurse trees common and mosses, ferns, and other plants grow on the surface of trees\ne. Biomass greater than any other place on Earth → up to 500 tons of biomass per acre\nf. Old growth stands have 800-year-old trees\ng. Slugs, elk, black tail deer, bears, beaver, owls, and salmon are common\nh. Human impacts: 1) At least half of original temperate rainforest has been logged 2) Many remaining forests are scheduled to be logged 3) Some patches protected because they are home to endangered northern spotted owls and the marbled murrelet", "note": "The only biome with a full text slide, and it's local to you, so it's my second slide-only pick."}]}], "retire": ["seed-apes-u2-biomes", "seed-apes-u2-ch18", "seed-apes-u2-climate", "seed-apes-u2-examples", "seed-apes-u2-learn", "seed-apes-u2-math", "seed-apes-u2-review"]};
